function normalizeFailureCodexEntry(entry = null) {
  if (!entry) return null;
  return {
    id: entry.id || `failure_${entry.type || "note"}_${entry.day || state?.day || 1}`,
    type: entry.type || "note",
    day: Number(entry.day || state?.day || 1),
    title: entry.title || "失败见闻",
    headline: entry.headline || entry.title || "这次没有白走",
    problem: entry.problem || "",
    insight: entry.insight || "",
    nextAction: entry.nextAction || "",
    support: entry.support || "",
    rewardText: entry.rewardText || entry.support || "",
    sourceId: entry.sourceId || "",
    tone: entry.tone || "learn",
    icon: entry.icon || "记",
  };
}

function normalizeFailureCodexState(failureCodexState = {}) {
  const defaults = createInitialFailureCodexState();
  const entries = Array.isArray(failureCodexState.entries)
    ? failureCodexState.entries.map(normalizeFailureCodexEntry).filter(Boolean).slice(0, 12)
    : [];
  return {
    ...defaults,
    ...failureCodexState,
    total: Number(failureCodexState.total || entries.length || 0),
    byType: { ...(failureCodexState.byType || {}) },
    last: normalizeFailureCodexEntry(failureCodexState.last) || entries[0] || null,
    entries,
  };
}

function syncFailureCodexState() {
  state.failureCodexState = normalizeFailureCodexState(state.failureCodexState);
  return state.failureCodexState;
}

function failureCodexTypeLabel(type = "") {
  const labels = {
    order: "订单",
    shop: "旧铺",
    risk: "节气风险",
    dungeon: "秘境",
    trade: "商队/远征",
  };
  return labels[type] || "见闻";
}

function recordFailureCodexEntry(entry = {}) {
  const codex = syncFailureCodexState();
  const safe = normalizeFailureCodexEntry({
    ...entry,
    day: entry.day || state.day,
    id: entry.id || `failure_${entry.type || "note"}_${entry.sourceId || state.day}_${codex.total + 1}`,
  });
  const existingIndex = codex.entries.findIndex((candidate) => candidate.id === safe.id);
  if (existingIndex >= 0) codex.entries.splice(existingIndex, 1);
  codex.entries.unshift(safe);
  codex.entries = codex.entries.slice(0, 12);
  codex.last = safe;
  codex.total = Number(codex.total || 0) + (existingIndex >= 0 ? 0 : 1);
  codex.byType[safe.type] = Number(codex.byType[safe.type] || 0) + (existingIndex >= 0 ? 0 : 1);
  return safe;
}

function failureCodexRows(limit = 4) {
  const codex = syncFailureCodexState();
  const rows = [...codex.entries];
  const recoveryOrder = visibleOrders()
    .filter((order) => !canDeliverOrder(order))
    .map((order) => ({ order, recovery: orderRecoverySpec(order) }))
    .find(({ recovery }) => recovery && !recovery.ready);
  if (recoveryOrder && !rows.some((entry) => entry.type === "order" && entry.sourceId === recoveryOrder.order.order_id)) {
    const { order, recovery } = recoveryOrder;
    rows.unshift(normalizeFailureCodexEntry({
      id: `failure_order_preview_${order.order_id}_${state.day}`,
      type: "order",
      day: state.day,
      title: "订单补救小票",
      headline: `${orderTitle(order)} 的缺口已经圈出`,
      problem: recovery.missingText || "订单还差一项关键货物",
      insight: recovery.action || "先查看生产路线，补齐第一项缺口。",
      nextAction: recovery.support?.routeAction === "recipe"
        ? "先点“看配方”，再回到订单板。"
        : recovery.support?.routeAction === "seed"
          ? "先补种对应作物，把订单链接回田地。"
          : "领取托底后按订单板路线补齐。",
      support: recovery.supportText || "补救路线已写入订单板",
      rewardText: recovery.supportText || "补救路线已写入订单板",
      sourceId: order.order_id,
      tone: "support",
      icon: "单",
    }));
  }
  if (state.shopOpeningState?.failureRecovery && !rows.some((entry) => entry.type === "shop" && entry.day === state.day)) {
    const recovery = state.shopOpeningState.failureRecovery;
    rows.unshift(normalizeFailureCodexEntry({
      id: `failure_shop_preview_${state.day}`,
      type: "shop",
      day: state.day,
      title: recovery.title || "旧铺补救小票",
      headline: "旧铺把流失原因圈出来了",
      problem: recovery.problem || "",
      insight: recovery.learningLine || recovery.detail || "这不是白亏，账页已经记住了顾客为什么没买。",
      nextAction: recovery.tomorrowAction || recovery.action || "明天按补救小票先修正一处短板。",
      support: recovery.support || "补救路线已写入账页",
      rewardText: recovery.support || "补救路线已写入账页",
      tone: "shop",
      icon: "铺",
    }));
  }
  return rows.slice(0, limit);
}

