    day: state.day,
    npcId: npcSpec.npcId,
    npcName: npcName(npcSpec.npcId),
    itemId,
    itemName: itemLabel,
    count: 1,
    title: npcSpec.title,
    summary: npcSpec.summary,
    detail: npcSpec.detail,
    line: npcSpec.line,
    area: npcSpec.area,
    rewardText: `${npcName(npcSpec.npcId)}好感 +1`,
    memoryTitle: "旧铺第一笔账",
    sceneTag: npcSpec.sceneTag,
    followup: npcSpec.followup,
    favorAfter: Number(state.npcFavor[npcSpec.npcId] || 0),
