function maybeCompleteLingchiWaterFreshMenuLine(openingFeedback = {}, report = []) {
  if (!state.completed.has("qingbo_water_fresh_signature_line")) return null;
  if (state.completed.has("lingchi_water_fresh_menu_line")) return null;
  const sale = (report || []).find((entry) => entry.reason === "buy" && entry.itemId === "item_food_lingchi_sanxian_geng");
  if (!sale) return null;
  const price = Number((String(sale.text || "").match(/成交 (\d+)/) || [0, 0])[1] || data.itemsById.get("item_food_lingchi_sanxian_geng")?.sell_price_base || 196);
  addNpcFavor("npc_qinghe", 1, "灵池水鲜小菜单");
  state.fame += 1;
  const feedback = triggerQinghePondProgressFeedback("menu", {
    sale,
    price,
    customerName: sale.name || customerDisplayName(sale.customerArchetype || "") || "水鲜熟客",
  });
  complete("lingchi_water_fresh_menu_line");
  state.shopReport.push({
    name: "灵池水鲜小菜单成型",
    text: `${sale.name || "顾客"}点走灵池三鲜羹，旧铺的水鲜招牌从一盘口味扩成了小菜单。`,
    reason: "qinghe_pond",
    detail: `清波鱼脍 -> 灵池三鲜羹 -> 双水鲜陈列 · 声望 +1 · 青禾好感 +1 · 成交 ${price} 灵石`,
  });
  addLog(
    "灵池水鲜小菜单",
    `${itemName("item_food_lingchi_sanxian_geng")}首卖后，旧铺已经能用两道灵池水鲜留住清口熟客。下一步可以围绕水航订单、季节鲜货和固定客群继续扩线。`,
  );
  return feedback;
}

function createLingchiWaterFreshRegularPledge(menuFeedback = null, report = []) {
  if (!menuFeedback || !state.completed.has("lingchi_water_fresh_menu_line")) return null;
  const opening = syncShopOpeningState();
  const current = normalizeShopVisitPledge(opening.visitPledge);
  if (
    current
    && current.status === "active"
    && state.day <= Number(current.dueDay || 0)
    && (String(current.id || "").startsWith("water_fresh_regular_pledge_") || Number(current.createdDay || 0) < state.day)
  ) {
    return { pledge: current, created: false };
  }
  const sale = (report || []).find((entry) => entry.reason === "buy" && entry.itemId === "item_food_lingchi_sanxian_geng") || {};
  const customerArchetype = sale.customerArchetype || "healer";
  const customerLabel = sale.name || customerDisplayName(customerArchetype) || "水鲜熟客";
  const reward = shopVisitPledgeRewardSpec(customerArchetype);
  const createdDay = Number(state.day || 1);
  const targetItemId = "item_food_lingchi_sanxian_geng";
  const targetItemName = itemName(targetItemId);
  const pledge = normalizeShopVisitPledge({
    id: `water_fresh_regular_pledge_${createdDay}_${customerArchetype}`,
    status: "active",
    createdDay,
    activeDay: createdDay + 1,
    dueDay: createdDay + 2,
    customerArchetype,
    customerLabel,
    sourceLabel: "灵池水鲜小菜单",
    hotTag: "water_food",
    hotTagLabel: "灵池水鲜",
    targetItemId,
    targetItemName,
    rewardGold: Number(reward.gold || 0) + 12,
    rewardFame: Number(reward.fame || 0) + 1,
    headline: `${customerLabel}留下水鲜熟客帖`,
    detail: `${customerLabel}点过${targetItemName}后专门留话：明后两天若还能吃到这口灵池鲜汤，就愿意替旧铺多带一句口碑。`,
    cta: `补齐 ${targetItemName}，最好和${itemName("item_food_qingbo_yukuai")}同日摆出，让水鲜小菜单真的不断档。`,
    note: `水鲜熟客留单：灵石 +${Number(reward.gold || 0) + 12} · 声望 +${Number(reward.fame || 0) + 1}`,
    tone: "good",
  });
  opening.visitPledge = pledge;
  if (opening.lastSession?.day === state.day) opening.lastSession.visitPledge = pledge;
  if (opening.history[0]?.day === state.day) opening.history[0].visitPledge = pledge;
  return { pledge, created: true };
}

function maybeCompleteLingchiWaterFreshRegulars(visitPledgeResult = null) {
  if (!visitPledgeResult || visitPledgeResult.status !== "done") return null;
  if (!String(visitPledgeResult.id || "").startsWith("water_fresh_regular_pledge_")) return null;
  if (state.completed.has("lingchi_water_fresh_regulars")) return null;
  complete("lingchi_water_fresh_regulars");
  addNpcFavor("npc_qinghe", 1, "水鲜熟客留单兑现");
  state.shopReport.push({
    name: "水鲜固定客群成型",
    text: `${visitPledgeResult.customerLabel}按帖回门，灵池三鲜羹不再只是尝鲜货，而是旧铺能被熟客专门记住的一口。`,
    reason: "water_fresh_regulars",
    detail: `水鲜熟客留单兑现 · 青禾好感 +1 · 固定水鲜客群常驻 · ${visitPledgeResult.resultText || visitPledgeResult.detail}`,
  });
  addLog(
    "水鲜固定客群",
    `${visitPledgeResult.customerLabel}兑现了水鲜熟客留单，旧铺的灵池水鲜已经从小菜单长成固定客群。后续维持清波鱼脍和灵池三鲜羹不断档，会持续拉住清口熟客。`,
  );
  return {
    active: true,
    customerLabel: visitPledgeResult.customerLabel,
    targetItemName: visitPledgeResult.targetItemName,
  };
}

function cancelShopRestockTarget() {
  const opening = syncShopOpeningState();
  const target = opening.restockTarget;
  if (!target) return;
  opening.restockHistory.unshift(normalizeShopRestockTarget({
    ...target,
    status: "canceled",
    canceledDay: state.day,
  }));
  opening.restockHistory = opening.restockHistory.slice(0, 8);
  opening.restockTarget = null;
  shopRestockFocus = null;
  addLog("旧铺补货", `${target.itemName} 的补货追踪已取消。`);
  render();
}

function createInitialSpiritInteractionState() {
  return {
    unlocked: false,
    firstDay: 0,
    last: null,
    floatingText: "",
    moodRepairEvent: null,
    moodRepairHistory: [],
    history: [],
  };
}

function createInitialCanalRestorationState() {
  return {
    restored: false,
    day: 0,
    expandedPlots: 0,
    unlockedSeedId: "",
    unlockedSeedName: "",
    seedGiftCount: 0,
    waterCropUnlocked: false,
    last: null,
    history: [],
  };
}

function normalizeCanalRestorationState(canalRestorationState = {}) {
  const defaults = createInitialCanalRestorationState();
  return {
    ...defaults,
    ...canalRestorationState,
    last: canalRestorationState.last ? { ...canalRestorationState.last } : null,
    history: Array.isArray(canalRestorationState.history) ? canalRestorationState.history.map((entry) => ({ ...entry })).slice(0, 8) : [],
  };
}

function syncCanalRestorationState() {
  state.canalRestorationState = normalizeCanalRestorationState(state.canalRestorationState);
  return state.canalRestorationState;
}

function createInitialPondState() {
  return {
    unlocked: false,
    builtDay: 0,
    waterLevel: 1,
    waterControlUnlocked: false,
    waterControlMastery: false,
    sereneDays: 0,
    nightWaterCropCareDays: 0,
    restRespiteNights: 0,
    lastRestRespiteDay: 0,
    lastRestRespiteSpiritCount: 0,
    lotusStage: "none",
    lastBlessingDay: 0,
    lastEcologyEvent: null,
    ecologyHistory: [],
    firstCatchDone: false,
    lastCatchDay: 0,
    lastCatch: null,
    history: [],
  };
}

function normalizePondState(pondState = {}) {
  const defaults = createInitialPondState();
  return {
    ...defaults,
    ...pondState,
    waterLevel: Math.max(0, Math.min(2, Number(pondState.waterLevel ?? defaults.waterLevel))),
    waterControlUnlocked: Boolean(pondState.waterControlUnlocked),
    waterControlMastery: Boolean(pondState.waterControlMastery),
    sereneDays: Math.max(0, Number(pondState.sereneDays || 0)),
    nightWaterCropCareDays: Math.max(0, Number(pondState.nightWaterCropCareDays || 0)),
    restRespiteNights: Math.max(0, Number(pondState.restRespiteNights || 0)),
    lastRestRespiteDay: Math.max(0, Number(pondState.lastRestRespiteDay || 0)),
    lastRestRespiteSpiritCount: Math.max(0, Number(pondState.lastRestRespiteSpiritCount || 0)),
    lotusStage: ["none", "bud", "bloom"].includes(pondState.lotusStage) ? pondState.lotusStage : defaults.lotusStage,
    lastBlessingDay: Math.max(0, Number(pondState.lastBlessingDay || 0)),
    lastEcologyEvent: pondState.lastEcologyEvent ? { ...pondState.lastEcologyEvent } : null,
    ecologyHistory: Array.isArray(pondState.ecologyHistory) ? pondState.ecologyHistory.map((entry) => ({ ...entry })).slice(0, 8) : [],
    lastCatch: pondState.lastCatch ? { ...pondState.lastCatch } : null,
    history: Array.isArray(pondState.history) ? pondState.history.map((entry) => ({ ...entry })).slice(0, 8) : [],
  };
}

function syncPondState() {
  state.pondState = normalizePondState(state.pondState);
  return state.pondState;
}

function createInitialDengyingLanternState() {
  return {
    lastRevealDay: 0,
    revealUsedDay: 0,
    revealedRotationId: "",
    revealedAreaId: "",
    revealedThemeTag: "",
    revealedRewardFocus: "",
    revealedEntryModifier: "",
    history: [],
  };
}

function normalizeDengyingLanternState(lanternState = {}) {
  const defaults = createInitialDengyingLanternState();
  return {
    ...defaults,
    ...lanternState,
    lastRevealDay: Math.max(0, Number(lanternState.lastRevealDay || 0)),
    revealUsedDay: Math.max(0, Number(lanternState.revealUsedDay || 0)),
    revealedRotationId: String(lanternState.revealedRotationId || ""),
    revealedAreaId: String(lanternState.revealedAreaId || ""),
    revealedThemeTag: String(lanternState.revealedThemeTag || ""),
    revealedRewardFocus: String(lanternState.revealedRewardFocus || ""),
    revealedEntryModifier: String(lanternState.revealedEntryModifier || ""),
    history: Array.isArray(lanternState.history) ? lanternState.history.map((entry) => ({ ...entry })).slice(0, 8) : [],
  };
}

function syncDengyingLanternState() {
  state.dengyingLanternState = normalizeDengyingLanternState(state.dengyingLanternState);
  return state.dengyingLanternState;
}

function pondWaterLevelSpec(level = syncPondState().waterLevel) {
  const map = {
    0: {
      level: 0,
      label: "浅水",
      shortLabel: "偏浅",
      cropDelta: -1,
      fishDelta: 0,
      autoWater: false,
      summary: "池边露出泥沿，适合歇水，但水生菜会吃亏。",
    },
    1: {
      level: 1,
      label: "平水",
      shortLabel: "正稳",
      cropDelta: 1,
      fishDelta: 0,
      autoWater: true,
      summary: "水线刚好压过田沟，最适合养露珠芹这类嫩水菜。",
    },
    2: {
      level: 2,
      label: "丰水",
      shortLabel: "偏满",
      cropDelta: 0,
      fishDelta: 1,
      autoWater: true,
      summary: "池水更深，灵鱼回得快，但嫩菜容易长得散。",
    },
  };
  return map[Math.max(0, Math.min(2, Number(level || 0)))] || map[1];
}

function pondWaterLevelText(level = syncPondState().waterLevel) {
  const spec = pondWaterLevelSpec(level);
  return `${spec.label} · ${spec.summary}`;
}

function pondLotusStageText(stage = syncPondState().lotusStage) {
  const map = {
    none: "水面还在养静气",
    bud: "月白莲苞刚冒头",
    bloom: "月白莲已经开稳",
  };
  return map[stage] || map.none;
}

function pondWaterCropPlotCount() {
  return state.plots.filter((plot) => {
    if (!plot?.cropId || !plot.waterSoil) return false;
    const crop = data.cropsById.get(plot.cropId);
    return crop?.element_type === "water";
  }).length;
}

function pondWaterControlUnlocked() {
  syncPondState();
  return state.pondState.waterControlUnlocked || state.claimedQuestRewards.has("quest_side_0205_qinghe_pond");
}

function pondWaterMasteryUnlocked() {
  syncPondState();
  return state.pondState.waterControlMastery;
}

function pondWaterCropBonus() {
  const spec = pondWaterLevelSpec(syncPondState().waterLevel);
  if (spec.level === 1 && pondWaterMasteryUnlocked()) return spec.cropDelta + 1;
  if (spec.level === 2 && pondWaterMasteryUnlocked()) return 1;
  return spec.cropDelta;
}

function pondCatchExtraCount() {
  const spec = pondWaterLevelSpec(syncPondState().waterLevel);
  return pondWaterControlUnlocked() ? spec.fishDelta : 0;
}

function recordPondEcologyEvent(type, title, detail, extra = {}) {
  syncPondState();
  const entry = {
    type,
    title,
    detail,
    day: state.day,
    ...extra,
  };
  state.pondState.lastEcologyEvent = { ...entry };
  state.pondState.ecologyHistory.unshift(entry);
  state.pondState.ecologyHistory = state.pondState.ecologyHistory.slice(0, 8);
  return entry;
}

function settlePondEcology() {
  syncPondState();
  if (!state.builtBuildings.has("build_fishpond_lv1") || !pondWaterControlUnlocked()) return null;
  const carePlots = pondWaterCropPlotCount();
  const steadyCareNight = pondWaterLevelSpec(state.pondState.waterLevel).level === 1 && carePlots > 0;
  const previousStage = state.pondState.lotusStage || "none";
  if (steadyCareNight) {
    state.pondState.sereneDays += 1;
    state.pondState.nightWaterCropCareDays += 1;
  } else {
    state.pondState.sereneDays = 0;
  }
  const nextStage = state.pondState.sereneDays >= 3 ? "bloom" : state.pondState.sereneDays >= 2 ? "bud" : "none";
  state.pondState.lotusStage = nextStage;
  if (previousStage !== nextStage) {
    if (nextStage === "bud") {
      recordPondEcologyEvent(
        "lotus_bud",
        "月白莲苞",
        `你把灵池连着稳了 ${state.pondState.sereneDays} 夜，水生田边终于浮出一枚发光的莲苞。`,
        { carePlots, sereneDays: state.pondState.sereneDays, lotusStage: nextStage },
      );
      complete("pond_moonlotus_preview");
      addLog("静池生光", "露珠芹一带被你照看得很稳，月白莲苞从池边冒了头。再稳几夜，也许会有新的精怪认路回来。");
    } else if (nextStage === "bloom") {
      recordPondEcologyEvent(
        "lotus_bloom",
        "月莲静池",
        `灵池已经稳住了 ${state.pondState.sereneDays} 夜，月白莲在水面悄悄开了一层。`,
        { carePlots, sereneDays: state.pondState.sereneDays, lotusStage: nextStage },
      );
      complete("pond_moonlotus_bloom");
      addLog("静池开莲", "灵池平稳了几夜以后，月白莲终于在夜里开稳，池边的风声都轻了一点。");
    }
  }
  maybeGrantWaterLotusSeeds("pond_bloom");
  if (nextStage === "bloom" && state.pondState.lastBlessingDay !== state.day && state.pondState.sereneDays % 3 === 0 && state.spirits.length > 0) {
    const moodGain = 6;
    const staminaGain = 4;
    for (const spirit of state.spirits) {
      spirit.mood = Math.min(100, Number(spirit.mood || 0) + moodGain);
      spirit.stamina = Math.min(100, Number(spirit.stamina || 0) + staminaGain);
    }
    state.pondState.lastBlessingDay = state.day;
    recordPondEcologyEvent(
      "moon_blessing",
      "静池夜色",
      `月白莲在后半夜开了一阵，${state.spirits.length} 只精怪都跟着松快了些。`,
      { carePlots, sereneDays: state.pondState.sereneDays, lotusStage: nextStage, moodGain, staminaGain, spiritCount: state.spirits.length },
    );
    addLog("静池夜色", `月白莲开了一回，${state.spirits.length} 只精怪心情 +${moodGain}、体力 +${staminaGain}。`);
  }
  return state.pondState.lastEcologyEvent;
}

function maybeGrantWaterLotusSeeds(source = "pond_bloom") {
  syncPondState();
  const seedId = "seed_shuihang_lianshi";
  if (state.completed.has("year2_water_lotus_seed_unlocked")) return false;
  if (!year2Unlocked() || state.pondState.lotusStage !== "bloom") return false;
  addItem(seedId, 3);
  state.completed.add("year2_water_lotus_seed_unlocked");
  state.selectedSeedId = seedId;
  upsertWorldChange({
    key: "year2_water_lotus_seed_unlocked",
    title: "静池养出水航莲实",
    detail: "青禾把月白莲影压进了池边的新种，说以后不只养鱼，也能养出真正适合水航和远行客的莲实。",
    rewardHint: `${itemName(seedId)} x3 · ${itemName("crop_water_lotus_seed")} 可播种`,
    visualType: "moon_pool",
  });
  addLog(
    "水航莲实入池",
    `${source === "starter_kit" ? "蟠桃宴后，" : ""}静池已经养稳，青禾分给你 ${itemName(seedId)} x3。把它种在水润田里，下一批 ${itemName("crop_water_lotus_seed")} 就能接上第二年的水航和灵池订单。`,
  );
  return true;
}

function setPondWaterLevel(nextLevel, source = "manual") {
  syncPondState();
  const clamped = Math.max(0, Math.min(2, Number(nextLevel || 0)));
  if (state.pondState.waterLevel === clamped) return false;
  const before = pondWaterLevelSpec(state.pondState.waterLevel);
  state.pondState.waterLevel = clamped;
  const after = pondWaterLevelSpec(clamped);
  if (source !== "silent") {
    const prefix = source === "weather" ? "池水受天时牵动" : "灵池调水";
    addLog(prefix, `${before.label} 调成了 ${after.label}。${after.summary}`);
  }
  return true;
}

function updatePondWaterLevelByWeather(weather = currentWeatherConfig()) {
  if (!state.builtBuildings.has("build_fishpond_lv1")) return false;
  const weatherId = String(weather?.weather_id || "");
  const visualId = String(weather?.visual_fx_id || "");
  const waterBonus = Number(weather?.water_bonus || 0);
  if (waterBonus >= 0.25 || weatherId.includes("rain") || visualId.includes("rain")) return setPondWaterLevel(syncPondState().waterLevel + 1, "weather");
  if (waterBonus <= -0.15 || weatherId.includes("dry") || visualId.includes("dry") || weatherId.includes("hot")) return setPondWaterLevel(syncPondState().waterLevel - 1, "weather");
  return false;
}

