function workshopOutputOrderMatchSpec(outputItemId = "", outputCount = 1) {
  const matches = visibleOrders()
    .map((order) => {
      const needs = orderNeeds(order);
      const need = needs.find((entry) => entry.itemId === outputItemId);
      if (!need) return null;
      const missing = needs
        .map(({ itemId, count }) => ({
          itemId,
          count,
          have: Number(state.inventory[itemId] || 0),
        }))
        .filter((entry) => entry.have < entry.count);
      const ready = missing.length === 0;
      const haveOutput = Number(state.inventory[outputItemId] || 0);
      return {
        orderId: order.order_id,
        orderTitle: orderTitle(order),
        orderNpc: npcName(order.issuer_id || order.reward_favor_npc),
        outputItemId,
        outputItemName: itemName(outputItemId),
        outputCount: Number(outputCount || 1),
        neededCount: Number(need.count || 1),
        haveOutput,
        ready,
        missingText: missing.map((entry) => `${itemName(entry.itemId)} ${entry.have}/${entry.count}`).join("、"),
        rewardGold: Number(order.reward_gold || 0),
        rewardFame: Number(order.reward_fame || 0),
      };
    })
    .filter(Boolean)
    .sort((a, b) => Number(b.ready) - Number(a.ready) || b.rewardGold - a.rewardGold || a.orderTitle.localeCompare(b.orderTitle, "zh-Hans-CN"));
  return matches[0] || null;
}

function workshopOrderMatchSafe(match = null) {
  return match
    ? {
      orderId: match.orderId,
      orderTitle: match.orderTitle,
      orderNpc: match.orderNpc,
      outputItemId: match.outputItemId,
      outputItemName: match.outputItemName,
      outputCount: Number(match.outputCount || 1),
      neededCount: Number(match.neededCount || 1),
      haveOutput: Number(match.haveOutput || 0),
      ready: Boolean(match.ready),
      missingText: match.missingText || "",
      rewardGold: Number(match.rewardGold || 0),
      rewardFame: Number(match.rewardFame || 0),
    }
    : null;
}

function workshopLineFeedbackSpec(kind = "queued", options = {}) {
  const recipe = options.recipe || data.recipes.find((entry) => entry.recipe_id === options.recipeId) || null;
  const orderMatch = workshopOrderMatchSafe(options.orderMatch || null);
  const outputItemId = options.outputItemId || recipe?.output_item_id || orderMatch?.outputItemId || "";
  const outputName = options.outputItemName || (outputItemId ? itemName(outputItemId) : "工坊产物");
  const recipeLabel = options.recipeName || (recipe ? recipeName(recipe) : outputName);
  const count = Number(options.outputCount || recipe?.output_count || orderMatch?.outputCount || 1);
  const helperCount = Number(options.helperCount ?? state.spirits.filter((spirit) => spirit.job === "workshop").length);
  const speedText = options.speedText || multiplierText(Number(options.speed || 1));
  const profiles = {
    queued: {
      title: "工坊上灶",
      verb: "排产入线",
      accent: "#be4f37",
      detail: `${recipeLabel} 已进后厂，锅火会在入夜推进。`,
    },
    completed: {
      title: "后厂出锅",
      verb: "香气走线",
      accent: "#b47d2f",
      detail: `${outputName} x${count} 已沿产线送到前场。`,
    },
    order_ready: {
      title: "订单板亮了",
      verb: "这锅可交",
      accent: "#286f58",
      detail: `${orderMatch?.orderTitle || "订单"} 已备齐，可以去订单板交付。`,
    },
    order_pending: {
      title: "订单接上线",
      verb: "还差余料",
      accent: "#8f5f3f",
      detail: `${orderMatch?.orderTitle || "订单"} 接上这锅，还差 ${orderMatch?.missingText || "余料"}。`,
    },
  };
  const profile = profiles[kind] || profiles.queued;
  return {
    kind,
    title: profile.title,
    verb: profile.verb,
    accent: profile.accent,
    detail: options.detail || profile.detail,
    recipeId: recipe?.recipe_id || options.recipeId || "",
    recipeName: recipeLabel,
    outputItemId,
    outputItemName: outputName,
    outputCount: count,
    orderMatch,
    helperCount,
    speedText,
    etaNights: Number(options.etaNights || 0),
    createdAt: performance.now(),
    day: state.day,
  };
}

function triggerWorkshopLineFeedback(kind = "queued", options = {}) {
  state.workshopLineFeedback = workshopLineFeedbackSpec(kind, options);
  return state.workshopLineFeedback;
}

function workshopCraftFeedbackSpec(recipe, outputItemId, outputCount, firstAroma = false, orderMatch = workshopOutputOrderMatchSpec(outputItemId, outputCount)) {
  const outputName = itemName(outputItemId);
  const safeOrderMatch = workshopOrderMatchSafe(orderMatch);
  const orderLine = safeOrderMatch
    ? safeOrderMatch.ready
      ? `${safeOrderMatch.orderTitle} 已备齐，可以直接交单。`
      : `${safeOrderMatch.orderTitle} 接上这锅，还差 ${safeOrderMatch.missingText || "余料"}。`
    : "";
  return {
    recipeId: recipe.recipe_id,
    recipeName: recipeName(recipe),
    outputItemId,
    outputItemName: outputName,
    outputCount: Number(outputCount || 1),
    firstAroma: Boolean(firstAroma),
    orderId: safeOrderMatch?.orderId || "",
    orderTitle: safeOrderMatch?.orderTitle || "",
    orderNpc: safeOrderMatch?.orderNpc || "",
    orderReady: Boolean(safeOrderMatch?.ready),
    orderMissingText: safeOrderMatch?.missingText || "",
    orderMatch: safeOrderMatch,
    headline: firstAroma ? "第一锅香气引来了订单" : safeOrderMatch?.ready ? `${outputName} 可交单` : `${outputName} 出锅`,
    detail: firstAroma ? `${outputName} 的香气已经把第一张订单贴上旧铺订单板。${orderLine ? ` ${orderLine}` : ""}` : orderLine || `${recipeName(recipe)} 已完成，后厂这一锅已经可以直接备货。`,
    cta: safeOrderMatch?.ready ? "去订单板交付这单" : safeOrderMatch ? `继续补齐：${safeOrderMatch.missingText || "订单余料"}` : firstAroma ? "去订单板看看要交什么" : "趁热摆上货架，或者继续排产",
    createdAt: performance.now(),
    day: state.day,
  };
}

function triggerWorkshopCraftFeedback(recipe, outputItemId, outputCount, firstAroma = false, orderMatch = workshopOutputOrderMatchSpec(outputItemId, outputCount)) {
  state.workshopCraftFeedback = workshopCraftFeedbackSpec(recipe, outputItemId, outputCount, firstAroma, orderMatch);
  return state.workshopCraftFeedback;
}

function workshopOutputStorageRouteSafetyText() {
  return "只定位订单板、旧铺货签、配方栏或背包，不会自动交单、开铺、上架、售卖、继续加工、排产、扣库存、发奖励、入夜或消耗资源";
}

function workshopOutputStorageRouteFeedbackSpec(feedback = state.workshopCraftFeedback, recipe = null) {
  if (!feedback?.outputItemId) return null;
  const safeMatch = workshopOrderMatchSafe(feedback.orderMatch || workshopOutputOrderMatchSpec(feedback.outputItemId, feedback.outputCount));
  const outputItemId = feedback.outputItemId;
  const routeTags = shopTagsForItem(outputItemId, ecologyCourtyardSummary());
  const shopTag = prioritizeShopTag(routeTags, new Map(routeTags.map((tag) => [tag, 1])), "food");
  return {
    key: `${state.day}:${feedback.recipeId || recipe?.recipe_id || "recipe"}:${outputItemId}:${Number(feedback.outputCount || 1)}:${safeMatch?.orderId || shopTag}:${Math.round(performance.now())}`,
    day: state.day,
    recipeId: feedback.recipeId || recipe?.recipe_id || "",
    recipeName: feedback.recipeName || (recipe ? recipeName(recipe) : "当前配方"),
    outputItemId,
    outputItemName: feedback.outputItemName || itemName(outputItemId),
    outputCount: Number(feedback.outputCount || 1),
    firstAroma: Boolean(feedback.firstAroma),
    orderId: safeMatch?.orderId || "",
    orderTitle: safeMatch?.orderTitle || "",
    orderReady: Boolean(safeMatch?.ready),
    orderMissingText: safeMatch?.missingText || "",
    shopTag,
    shopTagText: shopTagLabel(shopTag),
    currentStock: Number(state.inventory[outputItemId] || 0),
    safety: workshopOutputStorageRouteSafetyText(),
    createdAt: performance.now(),
  };
}

function recordWorkshopOutputStorageRouteFeedback(feedback = state.workshopCraftFeedback, recipe = null) {
  const spec = workshopOutputStorageRouteFeedbackSpec(feedback, recipe);
  if (!spec) return null;
  state.workshopOutputStorageRouteFeedback = spec;
  return spec;
}

function recordWorkshopAroma(recipe, outputItemId, outputCount, orderMatchOverride = null, source = "manual") {
  syncWorkshopAromaState();
  const outputName = itemName(outputItemId);
  const firstAroma = !state.workshopAromaState.orderUnlocked;
  const orderMatch = workshopOrderMatchSafe(orderMatchOverride || workshopOutputOrderMatchSpec(outputItemId, outputCount));
  state.workshopAromaState.recipeId = recipe.recipe_id;
  state.workshopAromaState.itemId = outputItemId;
  state.workshopAromaState.itemName = outputName;
  state.workshopAromaState.day = state.day;
  state.workshopAromaState.orderUnlocked = true;
  state.workshopAromaState.liveFocus = {
    status: "completed",
    headline: orderMatch?.ready ? `${outputName} 可交单` : `${outputName} 出锅`,
    detail: orderMatch
      ? `${recipeName(recipe)} 已完成，${orderMatch.ready ? `${orderMatch.orderTitle} 已经能交付。` : `${orderMatch.orderTitle} 接上这锅，还差 ${orderMatch.missingText || "余料"}。`}`
      : `${recipeName(recipe)} 已完成，香气正在往旧铺门口飘。`,
    recipeName: recipeName(recipe),
    outputItemId,
    outputItemName: outputName,
    outputCount,
    progress: 100,
    etaNights: 0,
    helperCount: state.spirits.filter((spirit) => spirit.job === "workshop").length,
    speedText: multiplierText(workshopMultiplier() * workshopSpiritBonus()),
    orderMatch,
    advice: orderMatch?.ready
      ? `订单板已亮：${orderMatch.orderTitle} 可以直接交付。`
      : orderMatch
        ? `这锅已接上 ${orderMatch.orderTitle}，继续补 ${orderMatch.missingText || "余料"}。`
        : "趁热摆上货架，或者接订单把这锅香气换成声望。",
  };
  state.workshopAromaState.history.unshift({
    day: state.day,
    recipeId: recipe.recipe_id,
    itemId: outputItemId,
    itemName: outputName,
    outputCount,
    firstAroma,
    orderMatch,
  });
  state.workshopAromaState.history = state.workshopAromaState.history.slice(0, 8);
  complete("first_workshop_aroma");
  const feedback = triggerWorkshopCraftFeedback(recipe, outputItemId, outputCount, firstAroma, orderMatch);
  feedback.source = source === "queued" ? "queued" : "manual";
  recordWorkshopOutputStorageRouteFeedback(feedback, recipe);
  return firstAroma;
}

