function preloadImages() {
  return Promise.all(
    Object.entries(ASSET_SOURCES).map(([key, src]) => {
      return new Promise((resolve) => {
        const img = new Image();
        img.onload = () => {
          images[key] = img;
          resolve();
        };
        img.onerror = () => resolve();
        img.src = assetSrc(src);
      });
    }),
  );
}

function parseCsv(text) {
  const rows = [];
  let row = [];
  let cell = "";
  let quoted = false;

  for (let i = 0; i < text.length; i += 1) {
    const char = text[i];
    const next = text[i + 1];

    if (char === '"' && quoted && next === '"') {
      cell += '"';
      i += 1;
    } else if (char === '"') {
      quoted = !quoted;
    } else if (char === "," && !quoted) {
      row.push(cell);
      cell = "";
    } else if ((char === "\n" || char === "\r") && !quoted) {
      if (char === "\r" && next === "\n") i += 1;
      row.push(cell);
      if (row.some((value) => value.length > 0)) rows.push(row);
      row = [];
      cell = "";
    } else {
      cell += char;
    }
  }

  if (cell.length > 0 || row.length > 0) {
    row.push(cell);
    rows.push(row);
  }

  const [headers, ...body] = rows;
  return body.map((values) =>
    Object.fromEntries(headers.map((header, index) => [header, values[index] ?? ""])),
  );
}

async function loadCsv(path) {
  const embedded = embeddedCsvText(path);
  if (embedded !== null) return parseCsv(embedded);

  const response = await fetch(path);
  if (!response.ok) throw new Error(`无法加载 ${path}`);
  return parseCsv(await response.text());
}

async function loadData() {
  const entries = await Promise.all(
    Object.entries(DATA_FILES).map(async ([key, path]) => [
      key,
      runtimeDataLoader
        ? await runtimeDataLoader.loadTable(key, path, () => loadCsv(path))
        : await loadCsv(path),
    ]),
  );

  for (const [key, value] of entries) data[key] = value;

  for (const text of data.localization) data.names.set(text.text_key, text.zh_cn);
  for (const group of data.conditionGroups) data.conditionGroupsById.set(group.condition_group_id, group);
  for (const item of data.items) data.itemsById.set(item.item_id, item);
  for (const crop of data.crops) {
    data.cropsBySeed.set(crop.seed_item_id, crop);
    data.cropsById.set(crop.crop_id, crop);
  }
  for (const recipe of data.recipes) {
    if (!data.recipesByOutput.has(recipe.output_item_id)) data.recipesByOutput.set(recipe.output_item_id, recipe);
  }
  for (const building of data.buildings) data.buildingsById.set(building.building_id, building);
  for (const machine of data.machines) {
    data.machinesById.set(machine.machine_id, machine);
    data.machinesByBuilding.set(machine.building_unlock_id, machine);
  }
  for (const param of data.spiritMoodParams) data.moodParamsByScope.set(`${param.scope_type}:${param.scope_target}`, param);
  for (const event of data.spiritEvents) {
    const list = data.spiritEventsByLine.get(event.spirit_line_id) || [];
    list.push(event);
    data.spiritEventsByLine.set(event.spirit_line_id, list);
  }
  for (const memory of data.spiritMemoryFlags) {
    const eventId = memory.set_condition.replace("_complete", "");
    data.spiritMemoryByEvent.set(eventId, memory);
  }
  for (const profile of data.customerProfiles) data.customerProfilesBy.set(profile.archetype_id, profile);
  for (const behavior of data.customerBehavior) data.customerBehaviorBy.set(`${behavior.customer_archetype}:${behavior.state_name}`, behavior);
  for (const flow of data.customerStateFlow) {
    const list = data.customerFlowBy.get(flow.customer_archetype) || [];
    list.push(flow);
    data.customerFlowBy.set(flow.customer_archetype, list);
  }
  for (const step of data.questSteps) {
    const list = data.questStepsByQuest.get(step.quest_id) || [];
    list.push(step);
    data.questStepsByQuest.set(step.quest_id, list);
  }
  for (const step of data.sideQuestSteps) {
    const list = data.sideQuestStepsByQuest.get(step.quest_id) || [];
    list.push(step);
    data.sideQuestStepsByQuest.set(step.quest_id, list);
  }
  for (const trigger of data.sideQuestTriggers) {
    const list = data.sideQuestTriggersByQuest.get(trigger.quest_id) || [];
    list.push(trigger);
    data.sideQuestTriggersByQuest.set(trigger.quest_id, list);
  }
  for (const schedule of data.npcSchedules) {
    const list = data.schedulesByNpc.get(schedule.npc_id) || [];
    list.push(schedule);
    data.schedulesByNpc.set(schedule.npc_id, list);
  }
  for (const epilogue of data.cohabEpilogues) {
    data.cohabById.set(epilogue.epilogue_id, epilogue);
    data.cohabByNpc.set(epilogue.npc_id, epilogue);
  }
  for (const event of data.cohabWeeklyEvents) {
    const list = data.cohabWeeklyByEpilogue.get(event.epilogue_id) || [];
    list.push(event);
    data.cohabWeeklyByEpilogue.set(event.epilogue_id, list);
  }
  for (const event of data.cohabFestivalEvents) {
    const list = data.cohabFestivalByEpilogue.get(event.epilogue_id) || [];
    list.push(event);
    data.cohabFestivalByEpilogue.set(event.epilogue_id, list);
  }
  for (const map of data.cohabDialogueMaps) {
    const list = data.cohabDialogueByEpilogue.get(map.epilogue_id) || [];
    list.push(map);
    data.cohabDialogueByEpilogue.set(map.epilogue_id, list);
  }
  for (const map of data.sideQuestDialogueMaps) {
    const list = data.sideDialogueByQuest.get(map.quest_id) || [];
    list.push(map);
    data.sideDialogueByQuest.set(map.quest_id, list);
  }
  for (const shot of data.cutsceneTimeline) {
    const list = data.cutsceneShotsById.get(shot.cutscene_id) || [];
    list.push(shot);
    data.cutsceneShotsById.set(shot.cutscene_id, list);
  }
  for (const asset of data.cutsceneAssets) {
    const list = data.cutsceneAssetsById.get(asset.cutscene_id) || [];
    list.push(asset);
    data.cutsceneAssetsById.set(asset.cutscene_id, list);
  }
  for (const beat of data.sideQuestCutsceneBeats) {
    const list = data.sideCutsceneBeatsByMap.get(beat.map_id) || [];
    list.push(beat);
    data.sideCutsceneBeatsByMap.set(beat.map_id, list);
  }
  for (const audio of data.audioAssets) data.audioAssetsById.set(audio.audio_id, audio);
  for (const bus of data.audioMixBuses) {
    data.audioMixBusesById.set(bus.bus_id, bus);
    if (settings.audioBusVolumes[bus.bus_id] === undefined) {
      settings.audioBusVolumes[bus.bus_id] = Math.round(Number(bus.default_volume || 1) * 100);
    }
  }
  for (const bundle of data.finalSupportBundles) data.finalSupportBundlesById.set(bundle.bundle_id, bundle);
  for (const stage of data.finalSupportStages) {
    const list = data.finalSupportStagesByBundle.get(stage.bundle_id) || [];
    list.push(stage);
    data.finalSupportStagesByBundle.set(stage.bundle_id, list);
  }
  for (const rule of data.shopPriceRules) data.priceRulesByArchetype.set(rule.customer_archetype, rule);
  for (const theme of data.shopShelfThemes) data.shelfThemesByTag.set(theme.theme_tag, theme);
  for (const npc of data.npcs) data.npcsById.set(npc.npc_id, npc);
  for (const dungeon of data.dungeons) data.dungeonsById.set(dungeon.area_id, dungeon);
  for (const enemy of data.enemies) data.enemiesById.set(enemy.enemy_id, enemy);
  for (const boss of data.bosses) data.bossesById.set(boss.boss_id, boss);
  for (const skill of data.bossSkills) {
    const list = data.bossSkillsByBoss.get(skill.boss_id) || [];
    list.push(skill);
    data.bossSkillsByBoss.set(skill.boss_id, list);
  }
  for (const skill of data.spiritSkills) {
    const list = data.spiritSkillsBySpirit.get(skill.spirit_id) || [];
    list.push(skill);
    data.spiritSkillsBySpirit.set(skill.spirit_id, list);
  }
  for (const loot of data.lootPools) {
    const list = data.lootByPool.get(loot.pool_id) || [];
    list.push(loot);
    data.lootByPool.set(loot.pool_id, list);
  }
  for (const route of data.tradeRoutes) data.tradeRoutesById.set(route.route_id, route);
  for (const event of data.tradeRouteEvents) {
    const list = data.tradeEventsByRoute.get(event.route_id) || [];
    list.push(event);
    data.tradeEventsByRoute.set(event.route_id, list);
  }
  for (const risk of data.tradeRouteRiskSupplies) {
    const list = data.tradeRisksByRoute.get(risk.route_id) || [];
    list.push(risk);
    data.tradeRisksByRoute.set(risk.route_id, list);
  }
  for (const rotation of data.hiddenDungeonRotations) {
    const list = data.hiddenRotationsByArea.get(rotation.area_id) || [];
    list.push(rotation);
    data.hiddenRotationsByArea.set(rotation.area_id, list);
  }
  for (const term of data.solarTerms) data.solarTermsById.set(term.term_id, term);
  for (const weather of data.weather) data.weatherById.set(weather.weather_id, weather);
  for (const achievement of data.achievements) data.achievementsById.set(achievement.achievement_id, achievement);
  for (const trial of data.year2SolarTrials) data.solarTrialsById.set(trial.trial_id, trial);
  for (const plan of data.year2ContentPlan) data.year2ContentPlanById.set(plan.content_id, plan);
  for (const guide of data.guideScripts) {
    const key = `${guide.trigger_type}:${guide.trigger_param}`;
    const list = data.guideScriptsByTrigger.get(key) || [];
    list.push(guide);
    data.guideScriptsByTrigger.set(key, list);
  }
  for (const line of data.dialogues) {
    const group = data.dialoguesByGroup.get(line.dialogue_group_id) || [];
    group.push(line);
    data.dialoguesByGroup.set(line.dialogue_group_id, group);
  }

  state.dataReady = true;
  state.weatherId = pickWeatherForTerm(currentTermConfig()).weather_id;
  hydratePlatformState();
  hydrateAchievements();
  checkAchievements();
  scanConfiguredEvents("load_data");
}

function localize(key, fallback = key) {
  return data.names.get(key) || fallback;
}

function patternMatchesKey(pattern = "", key = "") {
  return pattern.split("|").some((part) => {
    const normalized = part.trim();
    if (!normalized) return false;
    const regex = new RegExp(`^${normalized.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\\\*/g, ".*")}$`);
    return regex.test(key);
  });
}

function collectLocalizationKeysForPlan(plan) {
  const keys = new Set();
  const pushKey = (value) => {
    if (typeof value === "string" && value && patternMatchesKey(plan.key_pattern, value)) keys.add(value);
  };
  const scanRows = (rows) => {
    for (const row of rows || []) {
      for (const [field, value] of Object.entries(row)) {
        if (field.endsWith("_key") || field.includes("subtitle") || field.includes("toast")) pushKey(value);
      }
    }
  };

  for (const tableName of String(plan.source_table || "").split("|")) {
    const rows = data[tableName.trim()];
    if (rows) scanRows(rows);
  }
  for (const text of data.localization) pushKey(text.text_key);
  return [...keys];
}

function localizationCoverageFor(plan) {
  const keys = collectLocalizationKeysForPlan(plan);
  const present = keys.filter((key) => data.names.has(key));
  const target = Number(plan.coverage_target || 100);
  const coverage = keys.length ? Math.round((present.length / keys.length) * 100) : 0;
  const missing = keys.filter((key) => !data.names.has(key)).slice(0, 5);
  const plannedOnly = keys.length === 0 && plan.content_area === "marketing";
  return {
    keys,
    present,
    target,
    coverage: plannedOnly ? target : coverage,
    missing,
    pass: plannedOnly ? plan.priority !== "P0" || data.steamAssets.length > 0 : coverage >= target,
    plannedOnly,
  };
}

function localizationSummary(priority = "P0") {
  const plans = data.localizationCoverage.filter((plan) => plan.priority === priority);
  const results = plans.map((plan) => localizationCoverageFor(plan));
  return {
    total: plans.length,
    passed: results.filter((result) => result.pass).length,
    avg: results.length ? Math.round(results.reduce((sum, result) => sum + result.coverage, 0) / results.length) : 0,
  };
}

function communityAssetReady(entry) {
  const asset = String(entry.primary_asset || "");
  const relatedSteamAsset = data.steamAssets.find((plan) =>
    plan.asset_plan_id.includes(asset)
      || plan.asset_type === entry.format
      || plan.asset_name.includes(entry.content_theme)
      || plan.required_capture.includes(entry.content_theme),
  );
  const systemReady = {
    term_system_gif: data.solarTerms.length > 0 && data.weather.length > 0,
    spirit_birth_clip: state.completed.has("spirit") || data.spirits.length > 0,
    shop_workshop_clip: state.completed.has("shop") || data.shopPriceRules.length > 0,
    customer_tag_infographic: data.customerSegments.length > 0 && data.customerProfiles.length > 0,
    demo_route_card: data.demoQa.length > 0 && data.verticalSlice.length > 0,
    year2_trial_clip: data.year2SolarTrials.length > 0,
    feature_trailer_v1: data.steamAssets.some((plan) => plan.asset_type === "trailer"),
    year2_freeplay_graph: data.freeplayGoals.length > 0 && data.year2GoalBook.length > 0,
  }[asset];
  return {
    ready: Boolean(relatedSteamAsset || systemReady),
    asset: relatedSteamAsset,
    reason: relatedSteamAsset ? `${relatedSteamAsset.asset_name} · ${relatedSteamAsset.acceptance_criteria}` : systemReady ? "对应系统已接入，可录制临时素材。" : "缺少可直接对应的素材计划或实机系统。",
  };
}

function communityCalendarSummary() {
  const entries = data.communityContentCalendar;
  const ready = entries.filter((entry) => communityAssetReady(entry).ready).length;
  const steamBeats = entries.filter((entry) => entry.target_channel.includes("steam")).length;
  const demoBeats = entries.filter((entry) => entry.cta === "download_demo").length;
  return { total: entries.length, ready, steamBeats, demoBeats };
}

