function upgradeSpiritToConfig(spirit, config, options = {}) {
  if (!spirit || !config) return null;
  const previousId = spirit.id;
  spirit.id = config.spirit_id;
  spirit.lineId = config.spirit_line_id;
  spirit.name = localize(config.spirit_name_key, spirit.name);
  spirit.mood = Number(config.mood_max || spirit.mood || 100);
  spirit.hunger = Number(config.hunger_max || spirit.hunger || 100);
  spirit.stamina = Number(config.stamina_max || spirit.stamina || 100);
  spirit.workRangeX = Number(config.work_range_x || spirit.workRangeX || 0);
  spirit.workRangeY = Number(config.work_range_y || spirit.workRangeY || 0);
  if (options.carryRareGiftDays && previousId !== spirit.id && state.rareSpiritLifeState?.claimedGiftDays?.[previousId]) {
    state.rareSpiritLifeState.claimedGiftDays[spirit.id] = state.rareSpiritLifeState.claimedGiftDays[previousId];
    delete state.rareSpiritLifeState.claimedGiftDays[previousId];
  }
  ensureSpiritJobs(spirit);
  return spirit;
}

function spiritEventReady(event) {
  if (state.completedSpiritEvents.has(event.spirit_event_id)) return false;
  const condition = event.trigger_condition || "";
  if (condition === "first_spirit_birth") return state.spirits.some((spirit) => spirit.lineId === event.spirit_line_id);
  if (condition === "first_auto_water_complete") return state.completed.has("assist");
  if (condition === "first_fire_machine_assign") return state.completed.has("machine") || state.builtBuildings.has("build_furnace_001");
  if (condition === "first_auto_storage_complete") return state.builtBuildings.has("build_storage_001");
  if (condition === "first_cloth_recipe_complete") return state.completed.has("craft") && state.shopShelfTheme.includes("gift");
  if (condition === "storage_box_count_2") return state.builtBuildings.size >= 3;
  if (condition === "has_dungeon_runs_5") return state.dungeonClears.size > 0 || state.completed.has("dungeon_explore");
  if (condition === "has_faction_order_active") return state.tradeRuns.some((run) => run.status === "traveling") || state.completed.has("trade_route_start");
  if (condition.startsWith("current_term_")) return currentTermId() === `term_${condition.replace("current_term_", "")}`;
  if (condition.includes("chapter_3_complete")) {
    return state.completed.has("chapter_3_complete")
      || state.completed.has("fire_core_restored")
      || state.defeatedBosses.has("boss_chiyan_xiehou")
      || state.claimedQuestRewards.has("quest_main_0302_shanghui_laike");
  }
  if (condition.includes("quest_main_0402")) return state.completed.has("repair") || state.dungeonClears.size > 0;
  if (condition.includes("quest_main_0403")) return state.completed.has("solar_trial_complete") || state.completedSolarTrials.size > 0;
  return conditionMet(condition);
}

function spiritEventRewardText(event) {
  if (event.reward_type === "item") return itemName(event.reward_param);
  if (event.reward_type === "scene") return `演出 ${event.reward_param}`;
  if (event.reward_type === "buff") return `记忆效果 ${event.reward_param}`;
  return `${event.reward_type} ${event.reward_param}`;
}

function applySpiritEventReward(event) {
  if (event.reward_type === "item") {
    addItem(event.reward_param, 1);
    return `${itemName(event.reward_param)} x1`;
  }
  if (event.reward_type === "scene") {
    state.playedCutscenes.add(event.reward_param);
    state.completed.add(`scene_${event.reward_param}`);
    return `解锁演出 ${event.reward_param}`;
  }
  if (event.reward_type === "buff") {
    state.completed.add(event.reward_param);
    return `激活 ${event.reward_param}`;
  }
  return spiritEventRewardText(event);
}

function completeSpiritEvent(eventId) {
  const event = data.spiritEvents.find((entry) => entry.spirit_event_id === eventId);
  if (!event) return addLog("精怪事件未配置", "CSV 中没有找到该精怪事件。");
  if (!spiritEventReady(event)) return addLog("精怪事件未触发", `${localize(event.dialogue_key, event.note)} 的条件尚未满足。`);
  const ownedSpirit = spiritEventOwnedSpirit(event);
  const beforeUpgrade = ownedSpirit ? spiritUpgradeSnapshot(ownedSpirit) : null;
  const targetConfig = spiritEventUpgradeConfig(event);
  const shouldUpgrade = ownedSpirit && targetConfig && ["evolve", "final"].includes(event.event_stage) && ownedSpirit.id !== targetConfig.spirit_id;
  const upgradedSpirit = shouldUpgrade ? upgradeSpiritToConfig(ownedSpirit, targetConfig) : ownedSpirit;
  const reward = applySpiritEventReward(event);
  state.completedSpiritEvents.add(event.spirit_event_id);
  const memory = data.spiritMemoryByEvent.get(event.spirit_event_id);
  if (memory) state.spiritMemoryFlags.add(memory.memory_flag_id);
  if (upgradedSpirit && beforeUpgrade && shouldUpgrade) {
    triggerSpiritEvolutionFeedback(upgradedSpirit, beforeUpgrade, {
      entry_id: event.spirit_event_id,
      event_stage: event.event_stage,
      exclusive_action: `${spiritEventStageLabel(event.event_stage)}完成 · ${areaName(event.area_id)}`,
    }, event.reward_type === "item" ? event.reward_param : "");
  }
  if (upgradedSpirit && event.event_stage === "final") triggerSpiritFinaleFeedback(upgradedSpirit, event, reward);
  const focusSpirit = upgradedSpirit || ownedSpirit || state.spirits.find((spirit) => (spirit.lineId || spiritLine(spirit.id)) === event.spirit_line_id) || null;
  const stageLabel = spiritEventStageLabel(event.event_stage);
  const dialogueText = localize(event.dialogue_key, event.note);
  state.activeDialogue = [
    ...state.activeDialogue.slice(-2),
    { speaker: "古戒", text: `${stageLabel}已记下：${dialogueText}` },
    ...(focusSpirit ? [{ speaker: focusSpirit.name, text: spiritVoice(focusSpirit.id, event.event_stage === "intro" ? "idle" : "happy") }] : []),
  ];
  complete("spirit_event_complete");
  playCue(shouldUpgrade ? "成就解锁" : "对话翻页");
  addLog("精怪记忆", `${focusSpirit ? `${focusSpirit.name} · ` : ""}${stageLabel}：${dialogueText} 奖励：${reward}${memory ? `；记忆 ${memory.memory_flag_id}` : ""}${shouldUpgrade && beforeUpgrade ? `；工作范围 ${beforeUpgrade.workRangeX}x${beforeUpgrade.workRangeY} -> ${focusSpirit.workRangeX}x${focusSpirit.workRangeY}` : ""}。`);
  render();
}

function spiritEventTriggerHint(event) {
  const condition = String(event?.trigger_condition || "");
  if (!condition) return "继续推进洞天日常";
  if (condition === "first_spirit_birth") return "收获第一只作物精怪后会自动接上";
  if (condition === "first_auto_water_complete") return "先让精怪完成一次自动浇水";
  if (condition === "first_fire_machine_assign") return "先给工坊点起第一台火位";
  if (condition === "first_auto_storage_complete") return "先把仓房和自动入库接上";
  if (condition === "first_cloth_recipe_complete") return "先做出第一张布料配方并接上礼品主题";
  if (condition === "storage_box_count_2") return "继续扩仓，让仓位真正忙起来";
  if (condition === "has_dungeon_runs_5") return "再去几趟秘境，让护卫经验成型";
  if (condition === "has_faction_order_active") return "先让商路和势力订单真正跑起来";
  if (condition.startsWith("current_term_")) {
    const termId = `term_${condition.replace("current_term_", "")}`;
    const term = data.solarTermsById.get(termId);
    return `等到 ${localize(term?.term_name_key, termId)} 时节再来`;
  }
  if (condition.includes("chapter_3_complete")) return "推进第三章主线，等火位与终章前置接上";
  if (condition.includes("quest_main_0402")) return "推进第四章前段，让灵渠与水线接上";
  if (condition.includes("quest_main_0403")) return "推进终阵前的试炼与宴席准备";
  return conditionLabel(condition);
}

function spiritEventSceneReady(event) {
  return Boolean(event?.reward_type === "scene" && cutsceneShots(event.reward_param).length > 0);
}

function playSpiritEventScene(eventId = "") {
  const event = data.spiritEvents.find((entry) => entry.spirit_event_id === eventId);
  if (!event) return addLog("精怪演出缺失", `未找到事件 ${eventId}。`);
  if (event.reward_type !== "scene") return addLog("暂无回看演出", `${localize(event.dialogue_key, event.note)} 当前是记忆/奖励事件，不是镜头演出。`);
  if (!state.completedSpiritEvents.has(event.spirit_event_id)) return addLog("演出尚未解锁", `${localize(event.dialogue_key, event.note)} 还没完成，先把这段伙伴事件触发掉。`);
  if (cutsceneShots(event.reward_param).length > 0) return startCutscene(event.reward_param);
  return addLog("演出待接入", `${event.reward_param} 还没有镜头数据，先继续推进其他伙伴线。`);
}

function spiritEventGoalRows(limit = 6) {
  const lineIds = [...new Set((data.spiritEvents || []).map((event) => event.spirit_line_id))];
  return lineIds.map((lineId) => {
    const events = (data.spiritEventsByLine.get(lineId) || [])
      .slice()
      .sort((a, b) => Number(["intro", "evolve", "final"].indexOf(a.event_stage)) - Number(["intro", "evolve", "final"].indexOf(b.event_stage)));
    const ownedSpirit = state.spirits.find((spirit) => (spirit.lineId || spiritLine(spirit.id)) === lineId) || null;
    const baseConfig = data.spirits.find((entry) => entry.spirit_line_id === lineId && Number(entry.stage || 1) === 1)
      || data.spirits.find((entry) => entry.spirit_line_id === lineId)
      || null;
    const completedEvents = events.filter((event) => state.completedSpiritEvents.has(event.spirit_event_id));
    const readyEvent = events.find(spiritEventReady) || null;
    const nextEvent = events.find((event) => !state.completedSpiritEvents.has(event.spirit_event_id)) || null;
    const replayEvent = events.find((event) => state.completedSpiritEvents.has(event.spirit_event_id) && spiritEventSceneReady(event)) || null;
    const stateClass = completedEvents.length >= events.length
      ? "done"
      : readyEvent
        ? "ready"
        : ownedSpirit
          ? "pending"
          : "locked";
    const headline = readyEvent
      ? `${spiritEventStageLabel(readyEvent.event_stage)}可触发`
      : nextEvent
        ? `下一步：${spiritEventStageLabel(nextEvent.event_stage)}`
        : "伙伴线已收录完成";
    const detail = readyEvent
      ? `${localize(readyEvent.dialogue_key, readyEvent.note)} · ${spiritEventSceneReady(readyEvent) ? "完成后会收进一段进化镜头。" : "完成后会写进伙伴记忆。"}`
      : nextEvent
        ? spiritEventTriggerHint(nextEvent)
        : replayEvent
          ? "这段进化镜头已经收进年鉴，随时可以回看。"
          : "这一条伙伴线已经从初见走到终章陪伴。";
    return {
      lineId,
      spiritName: ownedSpirit?.name || localize(baseConfig?.spirit_name_key, lineId.replace("spirit_line_", "")),
      ownedSpirit,
      events,
      completedEvents,
      readyEvent,
      nextEvent,
      replayEvent,
      stateClass,
      headline,
      detail,
    };
  })
    .sort((a, b) => {
      const score = (row) => (row.readyEvent ? 30 : 0) + (row.ownedSpirit ? 10 : 0) + row.completedEvents.length;
      return score(b) - score(a);
    })
    .slice(0, limit);
}

function spiritFinalEventForLine(lineId = "") {
  return (data.spiritEventsByLine.get(lineId) || []).find((event) => event.event_stage === "final") || null;
}

