function spiritFinaleEffectPanelRows(effects = spiritFinaleEffectSummary(), panel = "") {
  return spiritFinaleEffectRows(effects).filter((row) => row.active && (!panel || row.panel === panel));
}

function spiritFinaleEffectCompactText(effects = spiritFinaleEffectSummary(), limit = 3) {
  const rows = Array.isArray(effects?.rows)
    ? effects.rows.filter((row) => row.active !== false && Number(row.value || 0) > 0)
    : spiritFinaleEffectRows(effects).filter((row) => row.active);
  if (rows.length === 0) return "";
  const shown = rows.slice(0, limit).map((row) => `${row.shortTitle}：${row.valueText}`);
  const more = rows.length > limit ? `；另有 ${rows.length - limit} 条常驻线` : "";
  return `${shown.join("；")}${more}`;
}

function spiritFinaleEffectPanelText(effects = spiritFinaleEffectSummary(), panel = "", limit = 2) {
  const rows = Array.isArray(effects?.rows)
    ? effects.rows.filter((row) => row.active !== false && Number(row.value || 0) > 0 && (!panel || row.panel === panel))
    : spiritFinaleEffectPanelRows(effects, panel);
  if (rows.length === 0) return "";
  const shown = rows.slice(0, limit).map((row) => `${row.shortTitle}：${row.valueText}`);
  const more = rows.length > limit ? `；另有 ${rows.length - limit} 条` : "";
  return `${shown.join("；")}${more}`;
}

function spiritFinaleEffectSnapshot(effects = spiritFinaleEffectSummary()) {
  if (!effects) return null;
  const rows = Array.isArray(effects.rows)
    ? effects.rows.filter((row) => row.active !== false && Number(row.value || 0) > 0).map((row) => ({ ...row, active: true }))
    : spiritFinaleEffectRows(effects).filter((row) => row.active);
  if (rows.length === 0) return null;
  const totalLoopBonus = Number(effects.totalLoopBonus || rows.reduce((sum, row) => sum + Number(row.value || 0), 0));
  return {
    count: Number(effects.count || rows.length),
    labels: Array.isArray(effects.labels) && effects.labels.length ? [...effects.labels] : rows.map((row) => row.label),
    text: effects.text || rows.map((row) => `${row.anchorLabel}：${row.detail}`).join("；"),
    rows,
    farmGrowthBonus: Number(effects.farmGrowthBonus || 0),
    waterCareBonus: Number(effects.waterCareBonus || 0),
    workshopSpeedBonus: Number(effects.workshopSpeedBonus || 0),
    patrolGuardBonus: Number(effects.patrolGuardBonus || 0),
    shopBudgetBonus: Number(effects.shopBudgetBonus || 0),
    festivalThemeBonus: Number(effects.festivalThemeBonus || 0),
    totalLoopBonus,
    headline: `终章伙伴常驻 ${rows.length}/6`,
    detail: spiritFinaleEffectCompactText({ rows }, 4),
  };
}

function spiritMemoryBonus(scope) {
  return [...state.spiritMemoryFlags].reduce((sum, flagId) => {
    const memory = data.spiritMemoryFlags.find((entry) => entry.memory_flag_id === flagId);
    return memory?.effect_scope === scope ? sum + 1 : sum;
  }, 0);
}

function addBondExp(spirit, value, reason) {
  spirit.bondExp = (spirit.bondExp || 0) + value;
  const nextLevel = bondLevelFor(spirit, spirit.bondExp);
  if (nextLevel > (spirit.bondLevel || 1)) {
    spirit.bondLevel = nextLevel;
    const dialogue = data.spiritBondLevels.find((entry) => entry.spirit_line_id === spirit.lineId && Number(entry.bond_level) === nextLevel);
    addLog("羁绊提升", `${spirit.name} 羁绊达到 ${nextLevel} 级。${dialogue ? localize(dialogue.dialogue_key, "") : ""}`);
  } else {
    addLog("羁绊增加", `${spirit.name} ${reason}，羁绊 +${value}。`);
  }
}

function spiritInteractionActionText(type, spirit) {
  const moment = rareSpiritMomentForSpirit(spirit);
  if (type === "theater" && moment) return `${spirit.name} 在${moment.focus}${moment.action}`;
  if (type === "theater") return `${spirit.name} 拉着你看了一小段洞天日常`;
  if (type === "feed") return `${spirit.name} 抱着食物转了一圈，叶尖亮起一点暖光`;
  return `${spirit.name} 往你掌心蹭了蹭，头顶冒出小小灵花`;
}

function spiritInteractionFeedbackSpec(entry = null) {
  if (!entry) return null;
  const spirit = spiritById(entry.spiritId) || {
    id: entry.spiritId,
    name: entry.spiritName,
    lineId: spiritLine(entry.spiritId),
    job: "farm",
  };
  const profile = spiritVisualProfile(spirit);
  const isFeed = entry.type === "feed";
  const isRepair = entry.type === "mood_repair";
  const isTheater = entry.type === "theater";
  return {
    spiritId: entry.spiritId,
    spiritName: entry.spiritName,
    lineId: spirit.lineId || spiritLine(entry.spiritId),
    type: entry.type,
    firstInteraction: Boolean(entry.firstInteraction),
    label: isRepair ? "安抚小事" : isTheater ? "今日小剧场" : isFeed ? "喂食回应" : "摸摸回应",
    headline: entry.firstInteraction ? "第一次伙伴回应" : isRepair ? "心情被认真接住了" : isFeed ? "它满足地晃了晃" : "它蹭了蹭你的掌心",
    actionText: entry.actionText || spiritInteractionActionText(entry.type, spirit),
    quote: entry.quote || "",
    bondText: entry.floatingText || `羁绊 +${entry.bondGain || 0}`,
    bondGain: Number(entry.bondGain || 0),
    bondLevel: Number(entry.bondLevel || 1),
    mood: Number(entry.mood || 0),
    hunger: Number(entry.hunger || 0),
    extraText: entry.extraText || "",
    responseMotion: isRepair ? "心情修复" : isFeed ? "抱着食物转圈" : isTheater ? "拉你看小剧场" : "蹭掌心",
    cta: entry.firstInteraction ? "伙伴回应已写入精怪面板" : isFeed ? "继续留意饱腹和心情" : "睡前再陪它一会儿",
    profileLabel: profile.label,
    accent: profile.accent,
    glow: profile.glow,
    createdAt: performance.now(),
    day: state.day,
  };
}

function triggerSpiritInteractionFeedback(entry = null) {
  const feedback = spiritInteractionFeedbackSpec(entry);
  if (!feedback) return null;
  state.spiritInteractionFeedback = feedback;
  return feedback;
}

function recordSpiritInteraction(spirit, type, bondGain, quote, extraText = "") {
  syncSpiritInteractionState();
  const firstInteraction = !state.spiritInteractionState.unlocked;
  const actionText = spiritInteractionActionText(type, spirit);
  const entry = {
    day: state.day,
    spiritId: spirit.id,
    spiritName: spirit.name,
    type,
    actionText,
    quote,
    bondGain,
    bondExp: spirit.bondExp || 0,
    bondLevel: spirit.bondLevel || 1,
    mood: Math.round(spirit.mood || 0),
    hunger: Math.round(spirit.hunger || 0),
    extraText,
    firstInteraction,
  };

  state.spiritInteractionState.unlocked = true;
  if (!state.spiritInteractionState.firstDay) state.spiritInteractionState.firstDay = state.day;
  state.spiritInteractionState.last = entry;
  state.spiritInteractionState.floatingText = `羁绊 +${bondGain}`;
  state.spiritInteractionState.history.unshift(entry);
  state.spiritInteractionState.history = state.spiritInteractionState.history.slice(0, 10);
  complete("bond");
  if (firstInteraction) complete("first_spirit_interaction");
  triggerSpiritInteractionFeedback(entry);
  return { entry, firstInteraction };
}

