function createSpiritMoodRepairEvent(spirit, source = "day_end") {
  if (!spirit) return null;
  const profile = spiritMoodRepairProfile(spirit);
  return {
    id: `mood_repair_${spirit.id}_${state.day}`,
    spiritId: spirit.id,
    spiritName: spirit.name,
    job: spirit.job || "farm",
    day: state.day,
    source,
    title: profile.title,
    cause: profile.cause,
    action: profile.action,
    advice: profile.advice,
    glyph: profile.glyph,
    moodBefore: Math.round(Number(spirit.mood || 0)),
    repaired: false,
  };
}

function maybeTriggerSpiritMoodRepair(source = "day_end") {
  const interaction = syncSpiritInteractionState();
  if (interaction.moodRepairEvent && !interaction.moodRepairEvent.repaired) return interaction.moodRepairEvent;
  const lowSpirit = state.spirits
    .filter((spirit) => Number(spirit.mood || 0) <= 38 || (Number(spirit.mood || 0) <= 48 && Number(spirit.stamina || 0) < 45))
    .sort((a, b) => Number(a.mood || 0) - Number(b.mood || 0) || Number(a.stamina || 0) - Number(b.stamina || 0))[0];
  if (!lowSpirit) return null;
  const event = createSpiritMoodRepairEvent(lowSpirit, source);
  interaction.moodRepairEvent = event;
  interaction.moodRepairHistory.unshift({ ...event });
  interaction.moodRepairHistory = interaction.moodRepairHistory.slice(0, 8);
  addLog("精怪低落", `${event.spiritName} ${event.title}：${event.cause} ${event.advice}`);
  return event;
}

function completeSpiritMoodRepair(spiritId = "") {
  const interaction = syncSpiritInteractionState();
  const event = interaction.moodRepairEvent;
  if (!event || event.repaired) return addLog("暂无低落小事", "当前没有待修复的精怪低落事件。");
  const spirit = spiritById(spiritId || event.spiritId);
  if (!spirit || spirit.id !== event.spiritId) return addLog("精怪不在身边", "这段低落小事对应的精怪暂时不在当前队列。");
  const moodGain = Math.max(12, Math.min(22, 58 - Number(spirit.mood || 0)));
  const staminaGain = 8;
  const bondGain = 5;
  spirit.mood = Math.min(100, Number(spirit.mood || 0) + moodGain);
  spirit.stamina = Math.min(100, Number(spirit.stamina || 0) + staminaGain);
  addBondExp(spirit, bondGain, "被认真安抚了一回");
  addGoalBookProgress("daily", "spiritCareCount", 1);
  event.repaired = true;
  event.repairedDay = state.day;
  event.moodGain = moodGain;
  event.staminaGain = staminaGain;
  event.bondGain = bondGain;
  const quote = spiritVoice(spirit.id, "happy");
  const entry = {
    day: state.day,
    spiritId: spirit.id,
    spiritName: spirit.name,
    type: "mood_repair",
    actionText: `${spirit.name} 被你从低落里哄了回来`,
    quote,
    bondGain,
    bondExp: spirit.bondExp || 0,
    bondLevel: spirit.bondLevel || 1,
    mood: Math.round(spirit.mood || 0),
    hunger: Math.round(spirit.hunger || 0),
    extraText: `${event.action} · 心情 +${moodGain} · 体力 +${staminaGain}`,
    floatingText: "心情修复",
    firstInteraction: !interaction.unlocked,
  };
  interaction.unlocked = true;
  if (!interaction.firstDay) interaction.firstDay = state.day;
  interaction.last = entry;
  interaction.floatingText = "心情修复";
  interaction.history.unshift(entry);
  interaction.history = interaction.history.slice(0, 10);
  interaction.moodRepairHistory[0] = { ...event };
  triggerSpiritInteractionFeedback(entry);
  complete("spirit_mood_repair");
  playCue("成就解锁");
  addLog("精怪安抚", `${event.spiritName}：${event.action} 心情 +${moodGain}，体力 +${staminaGain}，羁绊 +${bondGain}。`);
  render();
}

function jobName(job) {
  const names = {
    farm: "农田岗",
    workshop: "工坊岗",
    shop: "店铺岗",
    patrol: "巡逻岗",
    expedition: "远征岗",
    garden: "庭院岗",
  };
  return names[job] || job;
}

function ensureSpiritJobs(spirit) {
  if (!spirit.job) spirit.job = "farm";
  if (!spirit.jobExp) spirit.jobExp = {};
  if (!spirit.jobLevels) spirit.jobLevels = {};
  for (const job of ["farm", "workshop", "shop", "patrol", "expedition", "garden"]) {
    if (!spirit.jobExp[job]) spirit.jobExp[job] = 0;
    if (!spirit.jobLevels[job]) spirit.jobLevels[job] = 0;
  }
}

function jobLevelFor(job, exp) {
  const levels = data.spiritJobMastery
    .filter((entry) => entry.job_type === job)
    .sort((a, b) => Number(a.level) - Number(b.level));
  let level = 0;
  for (const entry of levels) {
    if (exp >= Number(entry.exp_required || 0)) level = Number(entry.level || 0);
  }
  return level;
}

function spiritConfigFor(spirit) {
  return data.spirits.find((entry) => entry.spirit_id === spirit?.id);
}

function spiritMainJob(spirit) {
  const config = spiritConfigFor(spirit);
  const roleMap = {
    farm: "farm",
    workshop: "workshop",
    shop: "shop",
    expedition: "expedition",
    patrol: "patrol",
    garden: "garden",
    combat: "expedition",
    utility: "patrol",
  };
  return roleMap[config?.main_role] || "farm";
}

function spiritLineJobAffinity(spirit, job = spirit.job || "farm") {
  const lineId = spirit.lineId || spiritLine(spirit.id);
  const affinityMap = {
    spirit_line_luobo: { farm: 0.08 },
    spirit_line_lajiao: { workshop: 0.1 },
    spirit_line_shui: { farm: 0.1, garden: 0.04 },
    spirit_line_yunshu: { patrol: 0.08, expedition: 0.04 },
    spirit_line_bucao: { workshop: 0.08, farm: 0.04 },
    spirit_line_caikuang: { expedition: 0.1, patrol: 0.04 },
    spirit_line_jieqi: { patrol: 0.08, garden: 0.06 },
    spirit_line_meishi: { workshop: 0.08, shop: 0.04 },
    spirit_line_yaoyuan: { farm: 0.08, workshop: 0.04 },
    spirit_line_hualing: { shop: 0.12, garden: 0.04 },
    spirit_line_leizhu: { expedition: 0.12, patrol: 0.04 },
    spirit_line_yuelian: { garden: 0.12, farm: 0.04 },
    spirit_line_dengying: { patrol: 0.12, expedition: 0.04 },
    spirit_line_shuqi: { shop: 0.1, patrol: 0.04 },
    spirit_line_fengmi: { farm: 0.1, shop: 0.04 },
  };
  return Number(affinityMap[lineId]?.[job] || 0);
}

function spiritJobSpecialtyBonus(spirit, job = spirit.job || "farm") {
  const mainBonus = spiritMainJob(spirit) === job ? 0.16 : 0;
  const lineBonus = spiritLineJobAffinity(spirit, job);
  const stageBonus = Math.max(0, Number((spirit.id.match(/_(\d+)$/) || [0, 1])[1]) - 1) * 0.03;
  return mainBonus + lineBonus + stageBonus;
}

function spiritJobSpecialtyLabel(spirit, job = spirit.job || "farm") {
  const mainJob = spiritMainJob(spirit);
  const bonus = spiritJobSpecialtyBonus(spirit, job);
  const lineBonus = spiritLineJobAffinity(spirit, job);
  if (mainJob === job && lineBonus > 0) return `天赋契合 ${jobName(job)} +${Math.round(bonus * 100)}%`;
  if (mainJob === job) return `主职${jobName(job)} +${Math.round(bonus * 100)}%`;
  if (lineBonus > 0) return `副专长${jobName(job)} +${Math.round(bonus * 100)}%`;
  return `主职偏向${jobName(mainJob)}，当前无专长加成`;
}

function spiritStageNumber(spirit) {
  const config = spiritConfigFor(spirit);
  const suffixStage = Number((String(spirit?.id || "").match(/_(\d+)$/) || [0, 1])[1] || 1);
  return Math.max(1, Number(config?.stage || suffixStage || 1));
}

function spiritStageLabel(stage = 1) {
  if (Number(stage) >= 3) return "三阶究极";
  if (Number(stage) >= 2) return "二阶进化";
  return "一阶初生";
}

function spiritWorkRangeSpec(spirit, job = spirit?.job || "farm") {
  const config = spiritConfigFor(spirit);
  const lineId = config?.spirit_line_id || spirit?.lineId || spiritLine(spirit?.id);
  const stage = spiritStageNumber(spirit);
  const rangeX = Math.max(1, Number(spirit?.workRangeX || config?.work_range_x || 1));
  const rangeY = Math.max(1, Number(spirit?.workRangeY || config?.work_range_y || 1));
  const previousConfig = data.spirits.find((entry) => entry.spirit_line_id === lineId && Number(entry.stage || 1) === stage - 1);
  const nextConfig = data.spirits.find((entry) => entry.spirit_line_id === lineId && Number(entry.stage || 1) === stage + 1);
  const previousRangeX = Math.max(1, Number(previousConfig?.work_range_x || rangeX));
  const previousRangeY = Math.max(1, Number(previousConfig?.work_range_y || rangeY));
  const nextRangeX = Math.max(1, Number(nextConfig?.work_range_x || rangeX));
  const nextRangeY = Math.max(1, Number(nextConfig?.work_range_y || rangeY));
  const area = rangeX * rangeY;
  const previousArea = previousRangeX * previousRangeY;
  const deltaCells = Math.max(0, area - previousArea);
  const workPower = Number(config?.work_power_base || 1);
  const previousPower = Number(previousConfig?.work_power_base || workPower);
  const powerGain = Math.max(0, workPower - previousPower);
  const jobHintMap = {
    farm: "田间自动照看范围",
    workshop: "后厂投料与看火范围",
    shop: "货架补货与迎客范围",
    patrol: "夜巡灯线覆盖范围",
    expedition: "商路探旗响应范围",
    garden: "庭院安抚灵息范围",
  };
  const deltaText = stage >= 2 && deltaCells > 0
    ? `比上一阶多 ${deltaCells} 格，基础工力 +${Math.round(powerGain * 100)}%`
    : nextConfig
      ? `下一阶可扩到 ${nextRangeX}x${nextRangeY}`
      : "范围已稳定成型";
  const nextText = nextConfig
    ? `下一阶预览：${nextRangeX}x${nextRangeY} · 工力 ${Number(nextConfig.work_power_base || workPower).toFixed(2)}`
    : "已到当前配置最高阶，范围表现会持续留在场景中";
  return {
    stage,
    stageName: spiritStageLabel(stage),
    rangeX,
    rangeY,
    area,
    previousRangeX,
    previousRangeY,
    deltaCells,
    workPower,
    powerGain,
    rangeLabel: `${rangeX}x${rangeY} 覆盖`,
    jobHint: jobHintMap[job] || "岗位覆盖范围",
    deltaText,
    nextText,
    evolved: stage >= 2,
  };
}

function spiritJobPersonaSpec(spirit, job = spirit.job || "farm") {
  const helperName = spirit?.name || "精怪";
  const planted = state.plots.filter((plot) => plot.cropId);
  const mature = planted.filter((plot) => plot.mature);
  const unwatered = planted.filter((plot) => !plot.watered && !plot.mature);
  const workshopFocus = state.workshopAromaState?.liveFocus || workshopQueueFocusSpec();
  const shopFocus = normalizeShopOpeningState(state.shopOpeningState).liveFocus;
  const riskCount = unresolvedRisks().length;
  const traveling = (state.tradeRuns || []).filter((run) => run.status === "traveling").length;
  const gardenMoods = state.spirits.filter((entry) => entry.id !== spirit?.id).map((entry) => Number(entry.mood || 0));
  const lowestMood = gardenMoods.length ? Math.min(...gardenMoods) : Number(spirit?.mood || 0);
  const specs = {
    farm: {
      glyph: "水",
      tone: "water",
      action: unwatered.length > 0 ? `巡田补水 ${unwatered.length} 格` : mature.length > 0 ? `守着 ${mature.length} 块成熟田` : planted.length > 0 ? "压稳田垄夜露" : "等你播下新种",
      focus: unwatered.length > 0 ? "缺水灵田" : mature.length > 0 ? "成熟作物" : "灵田土脉",
      advice: unwatered.length > 0 ? "入夜前或交给精怪补水，明早成长更稳。" : mature.length > 0 ? "先收成熟作物，把库存转成工坊原料。" : "继续播种，农田岗才有发挥空间。",
    },
    workshop: {
      glyph: "火",
      tone: "ember",
      action: state.workshopQueue.length > 0 ? `灶边稳火 ${workshopFocus.progress}%` : "擦亮锅铲等排产",
      focus: workshopFocus.outputItemName || "工坊火候",
      advice: state.workshopQueue.length > 0 ? workshopFocus.advice : "安排当前配方入夜生产，工坊岗会缩短等待。",
    },
    shop: {
      glyph: "铃",
      tone: "gold",
      action: shopFocus ? `复盘 ${shopFocus.buyers} 单成交` : state.shopReport.length > 0 ? "整理旧铺反馈" : "练习招客话术",
      focus: shopFocus?.topItemName || shopFocus?.hotTagLabel || "旧铺门口",
      advice: shopFocus?.shelfAdvice || "开铺后会记录顾客为什么买、为什么离开。",
    },
    patrol: {
      glyph: "灯",
      tone: "jade",
      action: riskCount > 0 ? `巡夜盯防 ${riskCount} 条风险` : "沿篱笆巡灯",
      focus: riskCount > 0 ? "节气风险" : "洞天边界",
      advice: riskCount > 0 ? "先处理风险，巡逻岗能帮你减轻入夜损失。" : "保持巡逻岗，可以在节气风险出现时更快响应。",
    },
    expedition: {
      glyph: "旗",
      tone: "sky",
      action: traveling > 0 ? `校点 ${traveling} 支商队` : "测风看路",
      focus: traveling > 0 ? "在途商路" : "可派遣路线",
      advice: traveling > 0 ? "等商队返航后查看收益，再决定下一条路线。" : "派遣精怪短途商路，可以把库存和探索转成额外收益。",
    },
    garden: {
      glyph: "花",
      tone: "flower",
      action: lowestMood < 60 ? "安抚低落伙伴" : "收拢庭院花息",
      focus: lowestMood < 60 ? "伙伴心情" : "庭院共鸣",
      advice: lowestMood < 60 ? "庭院岗能托住心情和体力，适合长线养成。" : "保持庭院岗，有助于稳定每日状态和同住事件。",
    },
  };
  const spec = specs[job] || specs.farm;
  return {
    ...spec,
    label: jobName(job),
    helperName,
    efficiency: multiplierText(jobEfficiency(spirit, job)),
    specialty: spiritJobSpecialtyLabel(spirit, job),
    shortLine: `${spec.glyph} · ${spec.action}`,
  };
}

