function jobEfficiency(spirit, job = spirit.job || "farm") {
  ensureSpiritJobs(spirit);
  const level = spirit.jobLevels[job] || 0;
  const config = data.spiritJobMastery
    .filter((entry) => entry.job_type === job && Number(entry.level) <= Math.max(1, level))
    .sort((a, b) => Number(b.level) - Number(a.level))[0];
  const memoryBonus = job === "farm" ? spiritMemoryBonus("farm") * 0.02 : job === "workshop" ? spiritMemoryBonus("machine") * 0.02 : job === "shop" ? spiritMemoryBonus("shop") * 0.02 : 0;
  const finale = spiritFinaleEffectSummary();
  const finaleBonus = job === "farm"
    ? finale.farmGrowthBonus + finale.waterCareBonus * 0.35
    : job === "workshop"
      ? finale.workshopSpeedBonus
      : job === "shop"
        ? finale.shopBudgetBonus + finale.festivalThemeBonus * 0.45
        : job === "patrol"
          ? finale.patrolGuardBonus
          : job === "garden"
            ? finale.festivalThemeBonus * 0.25
            : 0;
  return 1 + Number(config?.efficiency_bonus || 0) + Math.max(0, level - 1) * 0.02 + memoryBonus + finaleBonus + spiritJobSpecialtyBonus(spirit, job);
}

function spiritJobWorkPower(spirit, job = spirit.job || "farm") {
  const staminaFactor = Math.max(0.42, Math.min(1.2, Number(spirit.stamina || 0) / 86));
  const moodFactor = Math.max(0.5, Math.min(1.18, Number(spirit.mood || 0) / 82));
  const hungerFactor = Math.max(0.38, Math.min(1.08, Number(spirit.hunger || 0) / 76));
  return jobEfficiency(spirit, job) * staminaFactor * moodFactor * hungerFactor;
}

function spendSpiritJobNeeds(spirit, job) {
  const cost = {
    farm: [9, 4, 5],
    workshop: [10, 5, 6],
    shop: [8, 3, 5],
    patrol: [8, 2, 4],
    expedition: [12, 5, 7],
    garden: [6, -3, 3],
  }[job] || [8, 3, 4];
  spirit.stamina = Math.max(0, Number(spirit.stamina || 0) - cost[0]);
  spirit.mood = Math.max(0, Math.min(100, Number(spirit.mood || 0) - cost[1]));
  spirit.hunger = Math.max(0, Number(spirit.hunger || 0) - cost[2]);
  spirit.assignments = (spirit.assignments || 0) + 1;
}

function addJobExp(spirit, job, value, reason) {
  ensureSpiritJobs(spirit);
  spirit.jobExp[job] = (spirit.jobExp[job] || 0) + value;
  const nextLevel = jobLevelFor(job, spirit.jobExp[job]);
  if (nextLevel > (spirit.jobLevels[job] || 0)) {
    spirit.jobLevels[job] = nextLevel;
    addLog("岗位熟练提升", `${spirit.name} 的${jobName(job)}达到 Lv.${nextLevel}：${reason}。`);
  }
}

function spiritById(spiritId) {
  if (!spiritId) return state.spirits[0];
  return state.spirits.find((spirit) => spirit.id === spiritId) || state.spirits[0];
}

function assignSpiritJob(job, spiritId = "") {
  const spirit = spiritById(spiritId);
  if (!spirit) return addLog("还没有精怪", "先让第一只作物成精。");
  ensureSpiritJobs(spirit);
  spirit.job = job;
  spirit.mood = Math.max(0, (spirit.mood || 0) - 2);
  addJobExp(spirit, job, 1, "完成岗位切换");
  complete("spirit_job");
  const persona = spiritJobPersonaSpec(spirit, job);
  triggerSpiritJobShiftFeedback(spirit, job, persona);
  addLog("岗位切换", `${spirit.name} 改到${persona.label}：${persona.action}。效率 ${persona.efficiency}，${persona.specialty}。${persona.advice}`);
  render();
}

function spiritJobShiftFeedbackSpec(spirit, job = spirit?.job || "farm", persona = spiritJobPersonaSpec(spirit, job)) {
  if (!spirit) return null;
  const index = Math.max(0, state.spirits.findIndex((entry) => entry.id === spirit.id));
  const sameJobIndex = state.spirits.slice(0, index).filter((entry) => (entry.job || "farm") === job).length;
  const station = spiritJobStation({ ...spirit, job }, sameJobIndex, index);
  const profile = spiritVisualProfile(spirit);
  return {
    spiritId: spirit.id,
    spiritName: spirit.name,
    job,
    jobName: persona.label || jobName(job),
    action: persona.action,
    focus: persona.focus,
    efficiency: persona.efficiency,
    specialty: persona.specialty,
    advice: persona.advice,
    glyph: persona.glyph || profile.glyph,
    accent: profile.accent,
    glow: profile.glow,
    station,
    createdAt: performance.now(),
    day: state.day,
  };
}

function triggerSpiritJobShiftFeedback(spirit, job = spirit?.job || "farm", persona = spiritJobPersonaSpec(spirit, job)) {
  state.spiritJobShiftFeedback = spiritJobShiftFeedbackSpec(spirit, job, persona);
  return state.spiritJobShiftFeedback;
}

function expeditionName(expedition) {
  const names = {
    expedition_name_short_market_001: "短途集市补给",
    expedition_name_trade_cloudbridge_001: "云桥商路",
    expedition_name_hidden_canal_001: "隐渠巡查",
  };
  return names[expedition?.expedition_name_key] || localize(expedition?.expedition_name_key, expedition?.expedition_id || "未知派遣");
}

function rewardPoolEntries(poolId) {
  return data.rewardPools?.filter((entry) => entry.reward_pool_id === poolId) || [];
}

function applyRewardEntryPreview(entry) {
  if (entry.reward_type === "item") return entry.reward_param === "item_gold_generic" ? `灵石 ${entry.reward_count}` : `${itemName(entry.reward_param)} x${entry.reward_count}`;
  if (entry.reward_type === "building") return `建筑 ${buildingName(data.buildingsById.get(entry.reward_param) || entry.reward_param)}`;
  if (entry.reward_type === "recipe") {
    const recipe = data.recipes.find((record) => record.recipe_id === entry.reward_param);
    return `配方 ${recipe ? recipeName(recipe) : entry.reward_param}`;
  }
  if (entry.reward_type === "favor") return `${npcName(entry.reward_param)} 好感 +${Number(entry.reward_count || 1) * 10}`;
  if (entry.reward_type === "reputation") return `声望 +${Math.max(1, Math.round(Number(entry.reward_count || 1) / 10))}`;
  if (entry.reward_type === "bond_exp") return `羁绊 +${entry.reward_count}`;
  if (entry.reward_type === "title" || entry.reward_type === "cosmetic" || entry.reward_type === "scene") return `${entry.reward_type} ${entry.reward_param}`;
  return `${entry.reward_type} ${entry.reward_param || entry.reward_count || ""}`.trim();
}

function favorRewardSummary(reward) {
  if (!reward) return "已领取当前全部奖励";
  if (reward.reward_type === "scene") return `对白 ${localize(`${reward.reward_param}_001`, reward.reward_param)}`;
  if (reward.reward_type === "item") return `${itemName(reward.reward_param)} x${Number(reward.reward_count || 1)}`;
  if (reward.reward_type === "recipe") return `配方 ${reward.reward_param}`;
  if (reward.reward_type === "quest") return `任务 ${reward.reward_param}`;
  if (reward.reward_type === "building") return `建筑许可 ${buildingName(data.buildingsById.get(reward.reward_param) || reward.reward_param)}`;
  if (reward.reward_type === "discount") return `折扣 ${reward.reward_param}`;
  return `${reward.reward_type} ${reward.reward_param || ""}`.trim();
}

function questRewardReady(quest, side = false) {
  const runtime = questRuntime();
  if (runtime) return runtime.questRewardReady(quest, side);

  if (!quest?.complete_reward_group || state.claimedQuestRewards.has(quest.quest_id)) return false;
  if (side && !sideQuestVisible(quest)) return false;
  const progress = questProgress(quest, side);
  return progress.total > 0 && progress.done >= progress.total;
}

function finishClaimedQuestReward(quest, side = false, result = null) {
  const rewards = Array.isArray(result?.rewards) ? result.rewards : [];
  if (side && quest.quest_id === "quest_side_0205_qinghe_pond") {
    syncPondState();
    state.pondState.waterControlUnlocked = true;
    if (state.pondState.waterLevel === 0) state.pondState.waterLevel = 1;
    complete("pond_water_control");
    state.selectedRecipeId = "recipe_water_crop_intro";
    triggerQinghePondProgressFeedback("recipe", { rewardText: rewards.join(" 路 ") });
  }
  if (side) {
    const steps = questStepsFor(quest, true);
    const finalStep = result?.finalStep || steps[steps.length - 1];
    triggerSideQuestPresentation(quest.quest_id, "after_finish", finalStep?.step_id);
    triggerSideQuestPresentation(quest.quest_id, "after_complete", finalStep?.step_id);
    state.sideQuestFeedback = sideQuestFeedbackSpec(quest.quest_id, "finish", "after_complete", finalStep?.step_id, 1);
  }
  addLog("Quest complete", `${questTitle(quest)} rewards: ${rewards.join(", ") || "none"}.`);
  return true;
}

function claimQuestReward(quest, side = false) {
  const runtime = questRuntime();
  if (runtime) {
    const result = runtime.claimQuestReward(quest, side);
    if (!result.claimed) return false;
    return finishClaimedQuestReward(quest, side, result);
  }

  if (!questRewardReady(quest, side)) return false;
  const rewards = rewardPoolEntries(quest.complete_reward_group)
    .filter((entry) => conditionMet(entry.condition_group || "always_true"))
    .map((entry) => applyRewardEntry(entry));
  state.claimedQuestRewards.add(quest.quest_id);
  if (side) state.activeSideQuests.add(quest.quest_id);
  else state.missionDone.add(quest.quest_id);
  if (side && quest.quest_id === "quest_side_0205_qinghe_pond") {
    syncPondState();
    state.pondState.waterControlUnlocked = true;
    if (state.pondState.waterLevel === 0) state.pondState.waterLevel = 1;
    complete("pond_water_control");
    state.selectedRecipeId = "recipe_water_crop_intro";
    triggerQinghePondProgressFeedback("recipe", { rewardText: rewards.join(" · ") });
  }
  if (side) {
    const steps = questStepsFor(quest, true);
    const finalStep = steps[steps.length - 1];
    triggerSideQuestPresentation(quest.quest_id, "after_finish", finalStep?.step_id);
    triggerSideQuestPresentation(quest.quest_id, "after_complete", finalStep?.step_id);
    state.sideQuestFeedback = sideQuestFeedbackSpec(quest.quest_id, "finish", "after_complete", finalStep?.step_id, 1);
  }
  addLog("任务完成", `${questTitle(quest)} 奖励：${rewards.join("、") || "无额外奖励"}。`);
  return true;
}

function checkQuestRewards() {
  const runtime = questRuntime();
  if (runtime) {
    const results = runtime.checkQuestRewards();
    for (const result of results) {
      const quest = (result.side ? data.sideQuests : data.quests).find((entry) => entry.quest_id === result.questId);
      if (quest) finishClaimedQuestReward(quest, result.side, result);
    }
    return results.length;
  }

  let claimed = 0;
  for (const quest of data.quests) {
    if (claimQuestReward(quest)) claimed += 1;
  }
  for (const quest of data.sideQuests) {
    if (claimQuestReward(quest, true)) claimed += 1;
  }
  return claimed;
}

function applyRewardEntry(entry, power = 1) {
  const count = Math.max(1, Math.round(Number(entry.reward_count || 1) * power));
  if (entry.reward_type === "item") {
    const itemId = entry.reward_param === "item_gold_generic" ? null : entry.reward_param;
    if (itemId) addItem(itemId, count);
    else state.gold += count;
    return itemId ? `${itemName(itemId)} x${count}` : `灵石 ${count}`;
  }
  if (entry.reward_type === "building") {
    state.builtBuildings.add(entry.reward_param);
    const machine = data.machinesByBuilding.get(entry.reward_param);
    if (machine) state.unlockedMachines.add(machine.machine_id);
    return `建筑解锁 ${buildingName(data.buildingsById.get(entry.reward_param) || entry.reward_param)}`;
  }
  if (entry.reward_type === "recipe") {
    state.completed.add(`recipe_${entry.reward_param}`);
    return `配方解锁 ${entry.reward_param}`;
  }
  if (entry.reward_type === "favor") {
    addNpcFavor(entry.reward_param, count * 10, "任务奖励");
    return `${npcName(entry.reward_param)} 好感 +${count * 10}`;
  }
  if (entry.reward_type === "reputation") {
    const fame = Math.max(1, Math.round(count / 10));
    state.fame += fame;
    return `声望 +${fame}`;
  }
  if (entry.reward_type === "bond_exp" && state.spirits[0]) {
    addBondExp(state.spirits[0], count, "派遣见闻");
    return `羁绊 +${count}`;
  }
  if (entry.reward_type === "title" || entry.reward_type === "cosmetic" || entry.reward_type === "scene") {
    state.completed.add(`${entry.reward_type}_${entry.reward_param}`);
    return `${entry.reward_type} ${entry.reward_param}`;
  }
  if (entry.reward_type === "buff" || entry.reward_type === "discount" || entry.reward_type === "ui" || entry.reward_type === "exp") {
    state.completed.add(`${entry.reward_type}_${entry.reward_param}`);
    return `${entry.reward_type} ${entry.reward_param} x${count}`;
  }
  return `${entry.reward_type} +${count}`;
}

function startSpiritExpedition(expeditionId = data.spiritExpeditions[0]?.expedition_id, spiritId = "") {
  const spirit = spiritById(spiritId);
  if (!spirit) return addLog("还没有精怪", "先让第一只作物成精。");
  ensureSpiritJobs(spirit);
  const expedition = data.spiritExpeditions.find((entry) => entry.expedition_id === expeditionId);
  if (!expedition) return addLog("派遣未配置", "CSV 中没有找到该派遣。");
  if ((spirit.stamina || 0) < 18) return addLog("精怪太累", "入夜休息后再派遣。");

  const efficiency = jobEfficiency(spirit, "expedition");
  spirit.stamina = Math.max(0, (spirit.stamina || 0) - 18);
  spirit.mood = Math.max(0, (spirit.mood || 0) - 4);
  addJobExp(spirit, "expedition", 3, expeditionName(expedition));
  addBondExp(spirit, 4, "完成派遣");
  addGoalBookProgress("daily", "expeditionsSent", 1);
  addGoalBookProgress("weekly", "expeditionComplete", 1);
  addGoalBookProgress("lifetime", "expeditionComplete", 1);
  const rewards = rewardPoolEntries(expedition.reward_pool_id).slice(0, 2).map((entry) => applyRewardEntry(entry, efficiency));
  complete("spirit_expedition");
  addLog("精怪派遣", `${spirit.name} 完成${expeditionName(expedition)}：${rewards.join("、") || "带回镇外见闻"}。`);
  render();
}

function ecologyComboName(combo) {
  const names = {
    combo_name_rain_herb_garden: "雨草药圃",
    combo_name_cloud_warehouse: "云仓联运",
    combo_name_moon_pond: "月池静养",
  };
  return names[combo?.combo_name_key] || localize(combo?.combo_name_key, combo?.combo_id || "生态组合");
}

function ecologyComboActive(combo) {
  if (!combo) return false;
  const ownedLines = new Set(state.spirits.map((spirit) => spirit.lineId || spiritLine(spirit.id)));
  if (combo.combo_id === "eco_moon_pond") {
    return ownedLines.has("spirit_line_yuelian")
      && state.builtBuildings.has("build_fishpond_lv1")
      && state.completedRareSpiritEvents.has("rsea_006");
  }
  if (combo.combo_id === "eco_night_lamp_path") {
    return ownedLines.has("spirit_line_dengying")
      && state.completedRareSpiritEvents.has("rsea_008")
      && (state.completed.has("dungeon_explore") || state.resolvedRisks.size > 0);
  }
  const requiredLines = splitTags(combo.required_spirit_lines);
  const lineMatched = requiredLines.some((line) => ownedLines.has(line)) || ownedLines.has("spirit_line_luobo");
  const requiredTags = splitTags(combo.required_building_tags);
  const buildingMatched = data.buildings
    .filter((building) => state.builtBuildings.has(building.building_id))
    .some((building) => requiredTags.some((tag) => (building.function_tags || "").includes(tag) || building.category.includes(tag)));
  return lineMatched && buildingMatched;
}

function activeEcologyCombos() {
  return data.spiritEcologyCombos.filter(ecologyComboActive);
}

function ecologyEffectValue(effectType = "") {
  return activeEcologyCombos().reduce((sum, combo) => {
    return sum + (String(combo.effect_type || "") === String(effectType || "") ? Number(combo.effect_param_1 || 0) : 0);
  }, 0);
}

function moonPondComboActive() {
  return Boolean(data.spiritEcologyCombos.find((combo) => combo.combo_id === "eco_moon_pond" && ecologyComboActive(combo)));
}

function nightLampComboActive() {
  return Boolean(data.spiritEcologyCombos.find((combo) => combo.combo_id === "eco_night_lamp_path" && ecologyComboActive(combo)));
}

function yuelianRestRespiteSkill() {
  const spirit = state.spirits.find((entry) => (entry.lineId || spiritLine(entry.id)) === "spirit_line_yuelian");
  if (!spirit) return null;
  return data.spiritSkills.find((skill) =>
    String(skill.spirit_id || "").startsWith("spirit_yuelian_")
    && skill.effect_type === "hunger_reduce"
    && skill.target_rule === "garden_spirits",
  ) || null;
}

function yuelianRestRespiteActive() {
  return state.completedRareSpiritEvents.has("rsea_017") && Boolean(yuelianRestRespiteSkill());
}

function yuelianFatiguedSpirits() {
  return state.spirits.filter((spirit) =>
    Number(spirit.stamina || 0) <= 26
    || Number(spirit.mood || 0) <= 52
    || Number(spirit.hunger || 0) <= 36,
  );
}

function recordYuelianRestRespite() {
  syncPondState();
  if (!state.completedRareSpiritEvents.has("rsea_005") || state.completedRareSpiritEvents.has("rsea_017")) return null;
  if (!state.builtBuildings.has("build_fishpond_lv1")) return null;
  const fatigued = yuelianFatiguedSpirits();
  if (fatigued.length === 0 || state.pondState.lastRestRespiteDay === state.day) return null;
  state.pondState.restRespiteNights += 1;
  state.pondState.lastRestRespiteDay = state.day;
  state.pondState.lastRestRespiteSpiritCount = fatigued.length;
  const names = fatigued.slice(0, 3).map((spirit) => spirit.name).join("、");
  const entry = recordPondEcologyEvent(
    "yuelian_rest_respite",
    "留白静养",
    `${names || "疲惫的精怪"}被你留在夜色里歇了一晚，月莲把池边莲叶铺成一小片安静。`,
    {
      spiritIds: fatigued.map((spirit) => spirit.id),
      spiritCount: fatigued.length,
      restRespiteNights: state.pondState.restRespiteNights,
      lineId: "spirit_line_yuelian",
    },
  );
  complete("yuelian_rest_respite");
  addLog(
    "留白静养",
    `你没有催疲惫的精怪继续硬撑，静池记下第 ${state.pondState.restRespiteNights}/2 夜留白。${state.pondState.restRespiteNights >= 2 ? "月莲好像终于懂了你的分寸，可以去目标册接上二阶段事件。" : "再有一次这样的夜晚，月莲会更愿意把静养的方法交给你。"}`,
  );
  return entry;
}

function yuelianRestRespiteReady() {
  syncPondState();
  return state.completedRareSpiritEvents.has("rsea_005")
    && !state.completedRareSpiritEvents.has("rsea_017")
    && state.builtBuildings.has("build_fishpond_lv1")
    && Number(state.pondState.restRespiteNights || 0) >= 2
    && Boolean(yuelianRestRespiteSkill());
}

function dengyingFestivalCustomerSkill() {
  const spirit = state.spirits.find((entry) => (entry.lineId || spiritLine(entry.id)) === "spirit_line_dengying");
  if (!spirit) return null;
  return data.spiritSkills.find((skill) =>
    String(skill.spirit_id || "").startsWith("spirit_dengying_")
    && skill.effect_type === "festival_customer_up"
    && skill.target_rule === "winter_shop",
  ) || null;
}

function dengyingFestivalWarmthActive() {
  return state.completedRareSpiritEvents.has("rsea_008") && Boolean(dengyingFestivalCustomerSkill());
}

function dengyingHiddenRevealSkill() {
  const spirit = state.spirits.find((entry) => (entry.lineId || spiritLine(entry.id)) === "spirit_line_dengying");
  if (!spirit) return null;
  return data.spiritSkills.find((skill) =>
    String(skill.spirit_id || "").startsWith("spirit_dengying_")
    && skill.effect_type === "hidden_reveal"
    && skill.target_rule === "night_hidden_entry",
  ) || null;
}

function dengyingWinterLanternReady() {
  syncGoalBookState();
  if (!state.completedRareSpiritEvents.has("rsea_008") || state.completedRareSpiritEvents.has("rsea_018")) return false;
  const spirit = state.spirits.find((entry) => (entry.lineId || spiritLine(entry.id)) === "spirit_line_dengying");
  const bondLevel = spirit ? Math.max(Number(spirit.bondLevel || 0), bondLevelFor(spirit, spirit.bondExp)) : 0;
  const winterWindow = currentTermId() === "term_dongzhi" || currentShopSeason()?.season_id === "season_shop_005";
  return Boolean(spirit)
    && bondLevel >= 10
    && winterWindow
    && Number(state.goalBookState?.seasonal?.lanternDungeonClears || 0) >= 1
    && Boolean(dengyingHiddenRevealSkill());
}

function dengyingRevealCandidates() {
  const termId = currentTermId();
  return data.hiddenDungeonRotations.filter((rotation) => {
    if (!rotation) return false;
    if (rotation.season_window && rotation.season_window !== termId) return false;
    if (!conditionMet(rotation.unlock_condition_group)) return false;
    const dungeon = data.dungeonsById.get(rotation.area_id);
    if (!dungeon) return false;
    return !dungeon.unlock_condition_group || conditionMet(dungeon.unlock_condition_group);
  });
}

function dengyingRevealRotation() {
  const candidates = dengyingRevealCandidates();
  if (candidates.length === 0) return null;
  const index = (state.day + state.dungeonClears.size + state.completedRareSpiritEvents.size) % candidates.length;
  return candidates[index] || candidates[0];
}

function dengyingHiddenRevealReady() {
  const lanternState = syncDengyingLanternState();
  return state.completedRareSpiritEvents.has("rsea_018")
    && Boolean(dengyingHiddenRevealSkill())
    && lanternState.lastRevealDay !== state.day
    && Boolean(dengyingRevealRotation());
}

function dengyingRevealedRotation() {
  const lanternState = syncDengyingLanternState();
  if (lanternState.lastRevealDay !== state.day || !lanternState.revealedRotationId || !lanternState.revealedAreaId) return null;
  const rotation = data.hiddenDungeonRotations.find((entry) => entry.rotation_id === lanternState.revealedRotationId);
  return {
    ...(rotation || {}),
    rotation_id: lanternState.revealedRotationId,
    area_id: lanternState.revealedAreaId,
    theme_tag: lanternState.revealedThemeTag || rotation?.theme_tag || "",
    reward_focus: lanternState.revealedRewardFocus || rotation?.reward_focus || "",
    entry_modifier: lanternState.revealedEntryModifier || rotation?.entry_modifier || "",
  };
}

function revealDengyingHiddenEntry() {
  if (!state.completedRareSpiritEvents.has("rsea_018")) return addLog("长灯路未成", "先接上灯影精的满羁绊事件，它才会替你把今夜的隐藏入口照出来。");
  if (!dengyingHiddenRevealSkill()) return addLog("灯影未到", "灯影精还没有把“先照见入口”的本事真正稳住。");
  const lanternState = syncDengyingLanternState();
  const revealed = dengyingRevealedRotation();
  if (lanternState.lastRevealDay === state.day && revealed) {
    const dungeon = data.dungeonsById.get(revealed.area_id || "");
    const dungeonLabel = dungeon ? dungeonName(dungeon) : "今夜秘境";
    return addLog("今夜灯路已亮", `${dungeonLabel} 的隐藏入口今晚已经被照了出来，先去秘境面板顺着这段灯路走一趟。`);
  }
  const rotation = dengyingRevealRotation();
  if (!rotation) return addLog("今夜无路可照", "当前还没有满足主线与轮换条件的隐藏入口。继续推进冬至线、主线或镇民关系后再试。");
  const dungeon = data.dungeonsById.get(rotation.area_id);
  const dungeonLabel = dungeon ? dungeonName(dungeon) : "今夜秘境";
  const skill = dengyingHiddenRevealSkill();
  lanternState.lastRevealDay = state.day;
  lanternState.revealUsedDay = 0;
  lanternState.revealedRotationId = rotation.rotation_id || "";
  lanternState.revealedAreaId = rotation.area_id || "";
  lanternState.revealedThemeTag = rotation.theme_tag || "";
  lanternState.revealedRewardFocus = rotation.reward_focus || "";
  lanternState.revealedEntryModifier = rotation.entry_modifier || "";
  lanternState.history.unshift({
    day: state.day,
    rotationId: rotation.rotation_id || "",
    areaId: rotation.area_id || "",
    themeTag: rotation.theme_tag || "",
    rewardFocus: rotation.reward_focus || "",
    entryModifier: rotation.entry_modifier || "",
    revealPower: Number(skill?.effect_param_1 || 1),
  });
  lanternState.history = lanternState.history.slice(0, 8);
  complete("dengying_hidden_reveal");
  playCue("成就解锁");
  addLog("冬至长灯路", `灯影精把通往${dungeonLabel}的长灯一盏盏接亮，今夜隐藏入口已经先显形了。等你踏进去时，前一段路会更容易看清。`);
  render();
}

function hualingThemeShowcaseReady() {
  syncGoalBookState();
  state.shopStats = normalizeShopStats(state.shopStats);
  const flowerThemeCount = Number(state.goalBookState?.seasonal?.flowerThemeCount || 0);
  const themeUsage = Number(state.shopStats.themeUsage?.fresh_market || 0) + Number(state.shopStats.themeUsage?.gift_banquet || 0);
  return (flowerThemeCount > 0 || themeUsage > 0) && Number(state.shopStats.soldCount || 0) > 0 && shopReputationScore() >= 100;
}

function hualingGuestCharmActive() {
  const themeTag = currentShelfTheme()?.theme_tag || state.shopShelfTheme;
  return state.completedRareSpiritEvents.has("rsea_002") && ["fresh_market", "gift_banquet"].includes(themeTag);
}

function hualingSilentMarketReady() {
  syncGoalBookState();
  state.shopStats = normalizeShopStats(state.shopStats);
  const spirit = state.spirits.find((entry) => (entry.lineId || spiritLine(entry.id)) === "spirit_line_hualing");
  const bondLevel = spirit ? Math.max(Number(spirit.bondLevel || 0), bondLevelFor(spirit, spirit.bondExp)) : 0;
  if (!spirit || bondLevel < 10 || !state.completedRareSpiritEvents.has("rsea_002")) return false;

  const seasonStats = currentShopSeasonStats();
  const currentSeason = currentShopSeason();
  const currentSeasonRank = currentSeason
    ? String(shopSeasonRank(shopSeasonScore(currentSeason, seasonStats).score, currentSeason).rank_tier || "c").toLowerCase()
    : "c";
  const liveSpringRankReady = currentSeason?.season_id === "season_shop_001" && ["s", "a", "b"].includes(currentSeasonRank);
  const settlementEntries = [state.shopStats.pendingSettlement, ...(state.shopStats.history || [])]
    .filter(Boolean)
    .filter((entry, index, list) => list.findIndex((other) => other.seasonId === entry.seasonId && other.cycleIndex === entry.cycleIndex) === index);
  const springRankReady = liveSpringRankReady || settlementEntries.some((entry) => entry.seasonId === "season_shop_001" && ["s", "a", "b"].includes(String(entry.rankTier || "").toLowerCase()));
  const flowerThemeCount = Number(state.goalBookState?.seasonal?.flowerThemeCount || 0);
  const giftThemeUsage = Number(state.shopStats.themeUsage?.gift_banquet || 0);
  const freshThemeUsage = Number(state.shopStats.themeUsage?.fresh_market || 0);
  const showcaseReady = flowerThemeCount >= 3 || giftThemeUsage >= 3 || giftThemeUsage + freshThemeUsage >= 6;
  const liveMainCustomer = shopSeasonLeadKey(seasonStats.customerVisits);
  const liveTopTheme = shopSeasonLeadKey(seasonStats.themeUsage);
  const crowdBuys = Number(seasonStats.customerBuys?.guest || 0)
    + Number(seasonStats.customerBuys?.faction || 0)
    + Number(seasonStats.customerBuys?.villager || 0);
  const crowdReady = crowdBuys >= 6
    || (["guest", "faction", "villager"].includes(liveMainCustomer) && ["gift_banquet", "fresh_market"].includes(liveTopTheme))
    || settlementEntries.some((entry) => ["guest", "faction", "villager"].includes(entry.mainCustomer) && ["gift_banquet", "fresh_market"].includes(entry.topThemeId));
  return springRankReady && showcaseReady && crowdReady;
}

function hualingSilentMarketActive() {
  const themeTag = currentShelfTheme()?.theme_tag || state.shopShelfTheme;
  return state.completedRareSpiritEvents.has("rsea_012") && ["fresh_market", "gift_banquet"].includes(themeTag);
}

