  const finalDone = state.completedRareSpiritEvents.has("rsea_004");
  const firstEvent = data.rareSpiritEvents.find((event) => event.entry_id === "rsea_003");
  const evolveEvent = data.rareSpiritEvents.find((event) => event.entry_id === "rsea_011");
