  const readyEvolve = evolveEvent && rareSpiritEventReady(evolveEvent) && !rareSpiritEventDone(evolveEvent);
  const readyFinal = finalEvent && rareSpiritEventReady(finalEvent) && !rareSpiritEventDone(finalEvent);
  const thunderRun = tradeRunFor("route_thunder_old_06");
