  const routeId = thunderRun?.routeId || travelingRun?.routeId || "route_thunder_old_06";
  const route = data.tradeRoutesById.get(routeId) || data.tradeRoutesById.get("route_thunder_old_06") || null;
  const thunderRoute = data.tradeRoutesById.get("route_thunder_old_06") || null;
