function loadSettings() {
  try {
    const raw = localStorage.getItem(SETTINGS_KEY);
    if (raw) settings = { ...settings, ...JSON.parse(raw) };
    settings.audioBusVolumes = settings.audioBusVolumes || {};
    if (!PANEL_GROUPS.some((group) => group.id === settings.panelGroup)) settings.panelGroup = "core";
  } catch (error) {
    recordError("settings_load", error);
  }
}

function saveSettings() {
  localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
}

function recordError(scope, error) {
  const entry = {
    scope,
    message: error?.message || String(error),
    time: new Date().toISOString(),
  };
  state.errors.unshift(entry);
  state.errors = state.errors.slice(0, 8);
  recordStabilityError();
  localStorage.setItem(ERROR_LOG_KEY, JSON.stringify(state.errors));
}

function achievementTitle(achievement) {
  return achievement ? achievement.title || achievement.achievement_id : "";
}

function hydrateAchievements() {
  try {
    const raw = localStorage.getItem(ACHIEVEMENT_KEY);
    if (!raw) return;
    const payload = JSON.parse(raw);
    state.unlockedAchievements = new Set(payload.unlockedAchievements || payload.ids || []);
  } catch (error) {
    recordError("achievements_load", error);
  }
}

function saveAchievementProfile() {
  const payload = {
    appId: BUILD_INFO.steamAppId,
    updatedAt: new Date().toISOString(),
    unlockedAchievements: [...state.unlockedAchievements],
    steamApiNames: [...state.unlockedAchievements]
      .map((id) => data.achievementsById.get(id)?.steam_api_name)
      .filter(Boolean),
  };
  localStorage.setItem(ACHIEVEMENT_KEY, JSON.stringify(payload));
}

function steamworksAdapter() {
  const candidate = globalThis[STEAMWORKS_BRIDGE.expectedGlobal] || globalThis.Steamworks || null;
  if (candidate && typeof candidate === "object") {
    const sdkReady = candidate.sdkReady === true;
    const bridgeReady = candidate.bridgeReady === true || sdkReady;
    return {
      id: candidate.adapterId || STEAMWORKS_BRIDGE.adapterId,
      mode: sdkReady ? "steamworks-sdk" : candidate.mode || "desktop-shell-stub",
      ready: bridgeReady,
      sdkReady,
      bridgeReady,
      evidenceMode: candidate.evidenceMode || null,
      setAchievement: candidate.setAchievement?.bind(candidate),
      storeStats: candidate.storeStats?.bind(candidate),
      writeCloud: candidate.writeCloud?.bind(candidate),
      activateOverlay: candidate.activateOverlay?.bind(candidate),
    };
  }
  return {
    id: "local-profile-awaiting-steamworks-sdk",
    mode: "local-mock",
    ready: false,
    sdkReady: false,
    bridgeReady: false,
    evidenceMode: null,
    setAchievement: null,
    storeStats: null,
    writeCloud: null,
    activateOverlay: null,
  };
}

function persistPlatformState() {
  try {
    if (saveRuntime) {
      saveRuntime.writeBrowserSlot(PLATFORM_STATE_KEY, state.platformState);
    } else {
      localStorage.setItem(PLATFORM_STATE_KEY, JSON.stringify(state.platformState));
    }
  } catch (error) {
    recordError("platform_state_save", error);
  }
}

function updatePlatformState(patch) {
  const adapter = steamworksAdapter();
  state.platformState = {
    ...state.platformState,
    adapter: adapter.mode,
    adapterId: adapter.id,
    sdkReady: adapter.sdkReady,
    bridgeReady: adapter.bridgeReady,
    evidenceMode: adapter.evidenceMode,
    appId: BUILD_INFO.steamAppId,
    bridge: STEAMWORKS_BRIDGE.adapterId,
    ...patch,
    pending: adapter.sdkReady ? [] : ["Steamworks SDK", "AppID", "Remote Storage", "Overlay"],
    updatedAt: new Date().toISOString(),
  };
  persistPlatformState();
  return state.platformState;
}

function hydratePlatformState() {
  try {
    const raw = saveRuntime ? saveRuntime.readBrowserSlot(PLATFORM_STATE_KEY) : localStorage.getItem(PLATFORM_STATE_KEY);
    if (raw) state.platformState = { ...state.platformState, ...JSON.parse(raw) };
  } catch (error) {
    recordError("platform_state_load", error);
  }
  updatePlatformState({});
}

async function writeDesktopSaveProfile(payload) {
  if (!saveRuntime?.bridgeAvailable?.()) return null;
  const result = await saveRuntime.writeDesktopProfile(SAVE_PROFILE_ID, payload);
  updatePlatformState({
    lastLocalJsonSave: {
      profileId: SAVE_PROFILE_ID,
      path: result.path || SAVE_PROFILE_ID,
      status: result.ok ? "written_to_user_save_dir" : "desktop_json_save_failed",
      adapter: result.adapter || saveRuntime.adapterLabel(),
      bytes: result.bytes || 0,
      at: result.updatedAt || new Date().toISOString(),
      error: result.error || "",
    },
  });
  return result;
}

async function readDesktopSaveProfile() {
  if (!saveRuntime?.bridgeAvailable?.()) return null;
  const result = await saveRuntime.readDesktopProfile(SAVE_PROFILE_ID);
  updatePlatformState({
    lastLocalJsonLoad: {
      profileId: SAVE_PROFILE_ID,
      path: result.path || SAVE_PROFILE_ID,
      status: result.ok ? "loaded_from_user_save_dir" : result.missing ? "desktop_json_save_missing" : "desktop_json_load_failed",
      adapter: result.adapter || saveRuntime.adapterLabel(),
      bytes: result.bytes || 0,
      at: result.updatedAt || new Date().toISOString(),
      error: result.error || "",
    },
  });
  return result;
}

function syncSteamAchievement(achievement) {
  const adapter = steamworksAdapter();
  const apiName = achievement?.steam_api_name || "";
  let status = "queued_local_profile";
  if (adapter.bridgeReady && apiName && adapter.setAchievement) {
    try {
      adapter.setAchievement(apiName);
      adapter.storeStats?.();
      status = adapter.sdkReady ? "synced_to_steamworks" : "desktop_shell_achievement_evidence_queued";
    } catch (error) {
      status = adapter.sdkReady ? "steamworks_sync_failed" : "desktop_shell_achievement_evidence_failed";
      recordError("steam_achievement_sync", error);
    }
  }
  updatePlatformState({
    lastAchievementSync: {
      achievementId: achievement?.achievement_id || "",
      apiName,
      status,
      at: new Date().toISOString(),
    },
  });
  return {
    ready: Boolean(achievement?.steam_api_name),
    apiName,
    adapter: adapter.id,
    status,
  };
}

function unlockAchievement(achievementId) {
  const achievement = data.achievementsById.get(achievementId);
  if (!achievement || state.unlockedAchievements.has(achievementId)) return false;
  state.unlockedAchievements.add(achievementId);
  saveAchievementProfile();
  const steam = syncSteamAchievement(achievement);
  addLog("成就解锁", `${achievementTitle(achievement)} · ${steam.apiName}`);
  playCue("成就解锁");
  return true;
}

function achievementUnlocked(achievement) {
  if (achievement.trigger_type === "completed") return state.completed.has(achievement.trigger_value);
  if (achievement.trigger_type === "saved") return Boolean(state[achievement.trigger_value]);
  if (achievement.trigger_type === "dungeon_clear") return state.dungeonClears.has(achievement.trigger_value);
  if (achievement.trigger_type === "all_completed") {
    return achievement.trigger_value.split("|").every((id) => state.completed.has(id));
  }
  return false;
}

function checkAchievements() {
  if (!state.dataReady) return;
  for (const achievement of data.achievements) {
    if (achievementUnlocked(achievement)) unlockAchievement(achievement.achievement_id);
  }
}

function writeCloudMirror() {
  const generatedAt = new Date().toISOString();
  state.cloudMirrorAt = generatedAt;
  const save = serializeState();
  const schemaReport = validateSaveSchema(save);
  const payload = {
    appId: BUILD_INFO.steamAppId,
    schemaVersion: SAVE_SCHEMA_VERSION,
    generatedAt,
    suggestedSteamCloudPath: "steam_cloud/xiannong_dongtian_profile.json",
    save,
    schemaReport,
    achievements: [...state.unlockedAchievements],
  };
  if (saveRuntime) {
    saveRuntime.writeBrowserSlot(CLOUD_SAVE_KEY, payload);
  } else {
    localStorage.setItem(CLOUD_SAVE_KEY, JSON.stringify(payload));
  }
  const adapter = steamworksAdapter();
  let status = "mirrored_to_local_storage";
  if (adapter.bridgeReady && adapter.writeCloud) {
    try {
      adapter.writeCloud(STEAMWORKS_BRIDGE.cloudPath, JSON.stringify(payload));
      status = adapter.sdkReady ? "synced_to_steam_remote_storage" : "desktop_shell_cloud_evidence_queued";
    } catch (error) {
      status = adapter.sdkReady ? "steam_remote_storage_failed" : "desktop_shell_cloud_evidence_failed";
      recordError("steam_cloud_sync", error);
    }
  }
  updatePlatformState({
    lastCloudSync: {
      path: payload.suggestedSteamCloudPath,
      schemaVersion: payload.schemaVersion,
      status,
      at: generatedAt,
    },
  });
  return payload;
}

function requestSteamOverlay(target = STEAMWORKS_BRIDGE.overlayTarget) {
  const adapter = steamworksAdapter();
  let status = "overlay_unavailable_in_local_mock";
  if (adapter.bridgeReady && adapter.activateOverlay) {
    try {
      adapter.activateOverlay(target);
      status = adapter.sdkReady ? "overlay_requested" : "desktop_shell_overlay_evidence_queued";
    } catch (error) {
      status = adapter.sdkReady ? "overlay_request_failed" : "desktop_shell_overlay_evidence_failed";
      recordError("steam_overlay", error);
    }
  }
  updatePlatformState({
    lastOverlayRequest: {
      target,
      status,
      at: new Date().toISOString(),
    },
  });
  addLog("Steamworks Overlay", adapter.ready ? `已请求打开 ${target}。` : "当前为 local-mock，真实 Overlay 待 Steamworks SDK 接入。");
  render();
}

function hasCoreLoop() {
  return ["plant", "harvest", "spirit", "assist", "craft", "shop", "repair"].every((id) => state.completed.has(id));
}

function year2Unlocked() {
  return state.completed.has("main_story_complete")
    || state.completed.has("final_banquet_complete")
    || state.completed.has("chapter_4_complete")
    || state.completed.has("final_pantao_harvested")
    || state.completed.has("quest_main_0403_pantao_dayan")
    || state.missionDone.has("quest_main_0403_pantao_dayan")
    || state.claimedQuestRewards.has("quest_main_0403_pantao_dayan")
    || state.triggeredEvents.has("event_main_0407");
}

function schemaDefaultFor(field) {
  if (field.default_value === "empty") {
    if (field.data_type.includes("array")) return [];
    if (field.data_type === "map") return {};
    return "";
  }
  if (field.default_value === "default_audio_bus") {
    return Object.fromEntries(data.audioMixBuses.map((bus) => [bus.bus_id, audioBusVolume(bus.bus_id)]));
  }
  if (field.data_type === "int") return Number(field.default_value || 0);
  return field.default_value || "";
}

function saveFieldValue(field, payload = serializeState()) {
  const fieldId = field.field_id;
  const values = {
    save_meta_version: payload.saveVersion || SAVE_SCHEMA_VERSION,
    save_world_year: Math.max(1, Math.ceil((payload.day || 1) / 72)),
    save_world_term: currentTermId(),
    save_player_gold: payload.gold,
    save_inventory_bag: payload.inventory,
    save_farm_tiles: payload.plots,
    save_spirit_owned: payload.spirits,
    save_spirit_bond: Object.fromEntries((payload.spirits || []).map((spirit) => [spirit.id, spirit.bondLevel || 0])),
    save_spirit_mastery: Object.fromEntries((payload.spirits || []).map((spirit) => [spirit.id, spirit.jobLevels || {}])),
    save_ecology_combo: { builtBuildings: payload.builtBuildings || [], finalSupportEffects: payload.finalSupportEffects || {} },
    save_expedition_state: payload.tradeRuns || [],
    save_freeplay_goal: { completed: payload.completed || [], completedSolarTrials: payload.completedSolarTrials || [] },
    save_shop_season: payload.shopStats || {},
    save_localization_seen: payload.playedCutscenes || [],
    save_audio_settings: Object.fromEntries(data.audioMixBuses.map((bus) => [bus.bus_id, audioBusVolume(bus.bus_id)])),
  };
  return values[fieldId];
}

function saveSchemaCoverage(payload = serializeState()) {
  const required = data.saveSchemaRegistry.filter((field) => field.persist_required === "true");
  const p0 = data.saveSchemaRegistry.filter((field) => field.qa_priority === "P0");
  const missing = required.filter((field) => saveFieldValue(field, payload) === undefined);
  const migrationRequired = data.saveSchemaRegistry.filter((field) => field.migration_required === "true");
  return {
    version: payload.saveVersion || SAVE_SCHEMA_VERSION,
    required: required.length,
    p0: p0.length,
    covered: required.length - missing.length,
    missing: missing.map((field) => field.field_id),
    migrationRequired: migrationRequired.length,
    migrations: data.saveMigrationPlan.length,
  };
}

function validateSaveSchema(payload = serializeState()) {
  const report = saveSchemaCoverage(payload);
  state.saveSchemaReport = {
    ...report,
    checkedAt: new Date().toISOString(),
  };
  return report;
}

function migrateSavePayload(payload) {
  const migrated = { ...payload };
  const fromVersion = Number(migrated.saveVersion || 0);
  const applied = [];
  for (const migration of data.saveMigrationPlan) {
    const migrationFrom = Number(migration.from_version || 0);
    const migrationTo = Number(migration.to_version || 0);
    if (migrationFrom < fromVersion || migrationTo > SAVE_SCHEMA_VERSION) continue;
    applied.push({
      id: migration.migration_id,
      from: migrationFrom,
      to: migrationTo,
      module: migration.affected_module,
      operation: migration.operation,
      rollback: migration.rollback_policy,
    });
  }
  for (const field of data.saveSchemaRegistry) {
    if (Number(field.added_version || 0) > SAVE_SCHEMA_VERSION) continue;
    const currentValue = saveFieldValue(field, migrated);
    if (currentValue === undefined) migrated[field.field_id] = schemaDefaultFor(field);
  }
  migrated.saveVersion = SAVE_SCHEMA_VERSION;
  migrated.saveMigratedFrom = fromVersion < SAVE_SCHEMA_VERSION ? fromVersion : migrated.saveMigratedFrom || null;
  migrated.saveMigrationHistory = [...(migrated.saveMigrationHistory || []), ...applied];
  return { payload: migrated, applied, fromVersion };
}

function earlyRewardDone(pace) {
  const unlock = pace.system_unlock;
  const completedId = earlyRewardCompletedId(pace, unlock);
  if (completedId === "clear") return state.completed.has("clear") || state.completed.has("plant") || Number(state.clearedDebris || 0) > 0;
  if (completedId === "spirit_sprout_preview") {
    return state.completed.has("spirit_sprout_preview")
      || state.completed.has("spirit_sprout_peek")
      || state.completed.has("spirit_sprout_birth")
      || state.completed.has("spirit")
      || state.spirits.length > 0;
  }
  if (completedId === "first_shop_opening") return state.completed.has("first_shop_opening") || state.completed.has("shop") || normalizeShopOpeningState(state.shopOpeningState).opened;
  if (completedId === "first_shop_sale_summary") return state.completed.has("first_shop_sale_summary") || state.completed.has("shop") || normalizeShopOpeningState(state.shopOpeningState).summaryUnlocked;
  if (completedId) return state.completed.has(completedId);
  if (pace.pace_id === "erp_003") return state.completed.has("spirit_sprout_preview") || state.completed.has("spirit") || state.spirits.length > 0;
  return false;
}

function earlyRewardCompletedId(pace, unlock = pace?.system_unlock || "") {
  const map = {
    erp_001: "clear",
    erp_002: "plant",
    erp_003: "spirit_sprout_preview",
    erp_004: "spirit",
    erp_005: "craft",
    erp_006: "first_shop_opening",
    erp_007: "first_shop_sale_summary",
    erp_008: "bond",
    erp_009: "repair",
    erp_010: "day_summary",
    spirit_panel: "spirit",
    processing: "craft",
    shop_open: "first_shop_opening",
    shop_summary: "first_shop_sale_summary",
    bond: "bond",
    repair: "repair",
    day_summary: "day_summary",
    spirit_preview: "spirit_sprout_preview",
  };
  return map[unlock] || map[pace?.pace_id] || "";
}

function firstOrderDeliveryDone() {
  return state.completed.has("first_order_delivery")
    || state.completedOrders.size > 0
    || Boolean(state.orderDeliveryFeedback?.firstOrder);
}

function earlyRewardFeedbackSpec(pace) {
  if (!pace) return null;
  return {
    paceId: pace.pace_id,
    phase: pace.phase,
    action: pace.player_action,
    instant: pace.instant_feedback,
    delayed: pace.delayed_feedback || pace.success_metric || "",
    unlock: pace.system_unlock || "",
    note: pace.note || "",
    timeMin: Number(pace.time_min || 0),
    createdAt: performance.now(),
    day: state.day,
  };
}

function triggerEarlyRewardFeedback(completedId = "") {
  const pace = data.earlyRewardPacing.find((entry) => earlyRewardCompletedId(entry) === completedId);
  if (!pace || state.completed.has(`early_reward_seen_${pace.pace_id}`)) return false;
  state.completed.add(`early_reward_seen_${pace.pace_id}`);
  const feedback = earlyRewardFeedbackSpec(pace);
  state.earlyRewardFeedback = feedback;
  state.earlyRewardKeepsake = feedback ? { ...feedback, completedId } : null;
  playCue("成就解锁");
  addLog("正反馈达成", `${pace.phase}：${pace.instant_feedback}。${pace.delayed_feedback || pace.success_metric}`);
  return true;
}

