function year2GoalPriorityScore(goal) {
  const progress = year2GoalProgress(goal);
  const target = Math.max(1, conditionTarget(goal.complete_condition));
  const priorityBonus = goal.priority === "P0" ? 40 : goal.priority === "P1" ? 20 : 0;
  let score = Number(goal.recommend_weight || 0) + priorityBonus + Math.min(45, Math.round((progress / target) * 45));
  if (goal.goal_id === "ygb_001" && state.spirits.some((spirit) => Number(spirit.mood || 0) < 72)) score += 28;
  if (goal.goal_id === "ygb_002" && visibleOrders().some((order) => canDeliverOrder(order))) score += 34;
  if (goal.goal_id === "ygb_003" && state.spirits.some((spirit) => (spirit.stamina || 0) >= 18)) score += 18;
  if (goal.goal_id === "ygb_005" && currentShopGoalScore() >= 900) score += 26;
  if (goal.goal_type === "seasonal" && year2GoalUnlocked(goal)) score += 36;
  return score;
}

function recommendedYear2Goals(goalType = "daily", limit = 3) {
  return data.year2GoalBook
    .filter((goal) => goal.goal_type === goalType)
    .filter((goal) => year2GoalUnlocked(goal))
    .filter((goal) => !year2GoalClaimed(goal))
    .sort((a, b) => year2GoalPriorityScore(b) - year2GoalPriorityScore(a))
    .slice(0, limit);
}

function year2TodayRecommendationRows(limit = 5) {
  if (!year2Unlocked()) return [];
  const rows = [];
  const seen = new Set();
  const pushGoal = (goal, source = "") => {
    if (!goal || seen.has(goal.goal_id) || year2GoalClaimed(goal) || !year2GoalUnlocked(goal)) return;
    const progress = year2GoalProgress(goal);
    const target = Math.max(1, conditionTarget(goal.complete_condition));
    const ready = year2GoalReady(goal);
    const score = year2GoalPriorityScore(goal);
    rows.push({
      goal,
      source,
      goalId: goal.goal_id,
      type: goal.goal_type,
      title: year2GoalTitle(goal),
      scope: year2GoalWorldBoardScopeLabel(goal),
      progress,
      target,
      percent: Math.max(0, Math.min(100, Math.round((progress / target) * 100))),
      ready,
      score,
      minutes: Number(goal.estimated_minutes || 0),
      rewardText: year2GoalRewardText(goal),
      note: goal.note || "第二年目标已写进洞天年鉴。",
      stateClass: ready ? "ready" : progress > 0 ? "active" : "pending",
    });
    seen.add(goal.goal_id);
  };
  recommendedYear2Goals("daily", 3).forEach((goal) => pushGoal(goal, "今日短目标"));
  recommendedYear2Goals("weekly", 1).forEach((goal) => pushGoal(goal, "本周推进"));
  recommendedYear2Goals("seasonal", 1).forEach((goal) => pushGoal(goal, "节气主题"));
  data.year2GoalBook
    .filter((goal) => ["collection", "relationship", "challenge"].includes(goal.goal_type))
    .filter((goal) => year2GoalUnlocked(goal) && !year2GoalClaimed(goal))
    .sort((a, b) => year2GoalPriorityScore(b) - year2GoalPriorityScore(a))
    .slice(0, 2)
    .forEach((goal) => pushGoal(goal, "长期追求"));
  if (rows.length < 3) {
    data.year2GoalBook
      .filter((goal) => year2GoalUnlocked(goal) && !year2GoalClaimed(goal))
      .sort((a, b) => year2GoalPriorityScore(b) - year2GoalPriorityScore(a))
      .forEach((goal) => pushGoal(goal, "补充推荐"));
  }
  return rows
    .sort((a, b) => Number(b.ready) - Number(a.ready) || b.score - a.score || a.minutes - b.minutes)
    .slice(0, limit);
}

function year2TodayRecommendationSpec(rows = year2TodayRecommendationRows(5)) {
  if (!year2Unlocked() || !rows.length) return null;
  const readyCount = rows.filter((row) => row.ready).length;
  const shortCount = rows.filter((row) => row.type === "daily").length;
  const lead = rows[0];
  return {
    active: true,
    title: "第二年今日推荐",
    headline: `推荐 ${rows.length}/5 · 今日短目标 ${shortCount} · 可收录 ${readyCount}`,
    detail: lead
      ? `${lead.scope} · ${lead.title}：${lead.note}`
      : "第二年目标册会把今日、本周、节气和长期目标排成可执行顺序。",
    rows,
    lead,
    safety: "只定位目标卡，不会自动领取奖励、推进时间、交付订单、派遣精怪、开铺、进入秘境或消耗资源。",
  };
}

