function year2GoalWorldBoardScopeLabel(goal) {
  return {
    daily: "今日",
    weekly: "本周",
    seasonal: "本月",
    collection: "收藏",
    relationship: "羁绊",
    challenge: "试炼",
  }[goal?.goal_type] || "长期";
}

function year2GoalWorldBoardSpec(width = refs.world?.width || 960, height = refs.world?.height || 640) {
  if (!year2Unlocked() || state.dungeon) return null;
  syncGoalBookState();
  const unlockedGoals = data.year2GoalBook
    .filter((goal) => year2GoalUnlocked(goal))
    .filter((goal) => !year2GoalClaimed(goal));
  if (!unlockedGoals.length) return null;
  const readyGoals = unlockedGoals
    .filter(year2GoalReady)
    .sort((a, b) => year2GoalPriorityScore(b) - year2GoalPriorityScore(a));
  const picked = [];
  const pushGoal = (goal) => {
    if (!goal || picked.some((entry) => entry.goal_id === goal.goal_id)) return;
    picked.push(goal);
  };
  readyGoals.slice(0, 2).forEach(pushGoal);
  recommendedYear2Goals("daily", 3).forEach(pushGoal);
  recommendedYear2Goals("weekly", 1).forEach(pushGoal);
  recommendedYear2Goals("seasonal", 1).forEach(pushGoal);
  unlockedGoals
    .filter((goal) => ["collection", "relationship", "challenge"].includes(goal.goal_type))
    .sort((a, b) => year2GoalPriorityScore(b) - year2GoalPriorityScore(a))
    .slice(0, 1)
    .forEach(pushGoal);
  if (!picked.length) return null;
  const focusGoal = readyGoals[0] || picked[0];
  const progress = year2GoalProgress(focusGoal);
  const target = Math.max(1, conditionTarget(focusGoal.complete_condition));
  const progressPercent = Math.max(0, Math.min(1, progress / target));
  const rows = picked.slice(0, 3).map((goal) => {
    const rowProgress = year2GoalProgress(goal);
    const rowTarget = Math.max(1, conditionTarget(goal.complete_condition));
    return {
      goal,
      title: year2GoalTitle(goal),
      scope: year2GoalWorldBoardScopeLabel(goal),
      ready: year2GoalReady(goal),
      progressText: `${Math.min(rowProgress, rowTarget)}/${rowTarget}`,
    };
  });
  const dailyCount = recommendedYear2Goals("daily", 5).length;
  const weeklyCount = recommendedYear2Goals("weekly", 3).length;
  const seasonalCount = recommendedYear2Goals("seasonal", 2).length;
  const readyCount = readyGoals.length;
  const cardWidth = 318;
  const cardHeight = rows.length >= 3 ? 144 : 126;
  const x = Math.max(238, Math.min(width - cardWidth - 32, 326));
  const y = Math.max(70, Math.min(height - cardHeight - 38, 96));
  return {
    active: true,
    key: `${state.day}:${focusGoal.goal_id}:${Math.min(progress, target)}:${target}:${readyCount}:${picked.map((goal) => goal.goal_id).join("|")}`,
    day: state.day,
    title: "主世界第二年目标年鉴",
    headline: readyCount > 0 ? "年鉴有新页可收录" : "第二年今日路线",
    cta: "年鉴目标 · 可点",
    goalId: focusGoal.goal_id,
    goalTitle: year2GoalTitle(focusGoal),
    goalScope: year2GoalWorldBoardScopeLabel(focusGoal),
    goalNote: focusGoal.note || "顺着这页推进第二年的长期日常。",
    rewardText: year2GoalRewardText(focusGoal),
    estimatedMinutes: Number(focusGoal.estimated_minutes || 0),
    ready: year2GoalReady(focusGoal),
    readyCount,
    dailyCount,
    weeklyCount,
    seasonalCount,
    progress,
    target,
    progressPercent,
    rows,
    selector: `[data-year2-goal="${selectorDataValue(focusGoal.goal_id)}"]`,
    fallbackSelector: "#goalBookPanel",
    rect: { x, y, width: cardWidth, height: cardHeight },
    anchor: { x: 530, y: 502 },
  };
}

function year2GoalWorldBoardAtCanvasPoint(px, py) {
  const spec = year2GoalWorldBoardSpec(refs.world?.width || 960, refs.world?.height || 640);
  if (!spec?.rect) return null;
  const { rect } = spec;
  return (
    px >= rect.x
    && px <= rect.x + rect.width
    && py >= rect.y
    && py <= rect.y + rect.height
  ) ? spec : null;
}

function focusYear2GoalWorldBoardFromCanvas(spec = year2GoalWorldBoardSpec()) {
  if (!spec?.goalId) return false;
  year2GoalWorldBoardFocus = {
    key: spec.key,
    day: state.day,
    goalId: spec.goalId,
  };
  queueStoryCompassFocusTarget({
    selector: spec.selector,
    fallbackSelector: spec.fallbackSelector || "#goalBookPanel",
    label: "点选第二年目标年鉴",
    log: `${spec.goalScope}目标「${spec.goalTitle}」已在目标册高亮。进度 ${Math.min(spec.progress, spec.target)}/${spec.target}，奖励 ${spec.rewardText}。这里只定位年鉴页，确认后再手动收录，不会自动领取。`,
    panelGroup: "core",
    missingTitle: "点选第二年目标年鉴",
    missingLog: "第二年目标年鉴已经指向目标册，但对应目标卡暂时没有找到。先查看目标册与留存钩子面板。",
  });
  return true;
}

