function focusFinalBanquetAfterwordBridge(nodeKey = "", spec = finalBanquetAfterwordBridgeSpec()) {
  if (!spec?.active) return false;
  const row = spec.rows.find((entry) => entry.key === nodeKey) || spec.focusNode || spec.rows.find((entry) => entry.stateClass === "ready") || spec.rows[0];
  if (!row) return false;
  finalBanquetAfterwordBridgeWorldFocus = { key: spec.key, day: state.day, nodeKey: row.key };
  queueStoryCompassFocusTarget({
    selector: row.selector,
    fallbackSelector: row.fallbackSelector || "#goalBookPanel",
    panelGroup: row.panelGroup || "core",
    label: `点选蟠桃宴后开卷桥：${row.label}`,
    log: `${row.title} 已定位：${row.detail}。${spec.safety}。`,
    missingTitle: "点选蟠桃宴后开卷桥",
    missingLog: `${row.title} 对应入口暂时没有找到，先回到目标册查看蟠桃宴后开卷桥。${spec.safety}。`,
  });
  return true;
}

function drawFinalBanquetAfterwordBridgeWorld(ctx, spec = finalBanquetAfterwordBridgeWorldSpec(), motion = performance.now() / 1000) {
  if (!spec?.rect) return false;
  const { rect } = spec;
  const active = finalBanquetAfterwordBridgeWorldFocus?.day === state.day
    && finalBanquetAfterwordBridgeWorldFocus?.key === spec.key;
  const bob = settings.reducedMotion ? 0 : Math.sin(motion * 2.1) * 2.5;
  const cardY = rect.y + bob;
  ctx.save();
  ctx.strokeStyle = active ? "rgba(224, 182, 109, 0.82)" : "rgba(224, 182, 109, 0.42)";
  ctx.lineWidth = active ? 3 : 2;
  ctx.setLineDash([8, 10]);
  ctx.lineDashOffset = settings.reducedMotion ? 0 : -motion * 14;
  ctx.beginPath();
  ctx.moveTo(spec.anchor.x, spec.anchor.y);
  ctx.bezierCurveTo(spec.anchor.x + 104, spec.anchor.y - 82, rect.x - 34, cardY + rect.height * 0.8, rect.x + 12, cardY + rect.height * 0.6);
  ctx.stroke();
  ctx.setLineDash([]);

  drawCanvasCard(ctx, rect.x, cardY, rect.width, rect.height, "rgba(255, 248, 232, 0.92)");
  ctx.strokeStyle = active ? "rgba(180, 125, 47, 0.78)" : "rgba(180, 125, 47, 0.34)";
  ctx.lineWidth = active ? 2.5 : 1.5;
  ctx.beginPath();
  ctx.roundRect(rect.x + 1, cardY + 1, rect.width - 2, rect.height - 2, 18);
  ctx.stroke();

  ctx.fillStyle = "#b47d2f";
  ctx.beginPath();
  ctx.roundRect(rect.x + 16, cardY + 15, 46, 38, 14);
  ctx.fill();
  ctx.fillStyle = "#fffdf5";
  ctx.font = "900 17px Microsoft YaHei";
  ctx.fillText("卷", rect.x + 29, cardY + 40);

  ctx.fillStyle = "#17231d";
  ctx.font = "900 14px Microsoft YaHei";
  ctx.fillText(spec.title, rect.x + 76, cardY + 28);
  ctx.fillStyle = "#8f5f3f";
  ctx.font = "800 11px Microsoft YaHei";
  ctx.fillText(spec.headline.slice(0, 22), rect.x + 76, cardY + 47);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "11px Microsoft YaHei";
  ctx.fillText(spec.detail.slice(0, 31), rect.x + 16, cardY + 70);

  spec.rows.slice(0, 4).forEach((row, index) => {
    const chipX = rect.x + 16 + index * 72;
    const chipY = cardY + 84;
    ctx.fillStyle = row.stateClass === "ready" ? "rgba(224, 182, 109, 0.22)" : row.stateClass === "done" ? "rgba(40, 111, 88, 0.16)" : "rgba(255, 253, 245, 0.76)";
    ctx.beginPath();
    ctx.roundRect(chipX, chipY, 64, 18, 9);
    ctx.fill();
    ctx.fillStyle = row.stateClass === "ready" ? "#b47d2f" : row.stateClass === "done" ? "#286f58" : "#8f5f3f";
    ctx.font = "800 10px Microsoft YaHei";
    ctx.fillText(row.label.slice(0, 4), chipX + 10, chipY + 13);
  });

  ctx.fillStyle = "#8f5f3f";
  ctx.font = "700 9px Microsoft YaHei";
  ctx.fillText(spec.safety.slice(0, 30), rect.x + 16, cardY + rect.height - 9);
  ctx.restore();
  return true;
}

function freeplayGoalEstimatedMinutes(goal) {
  const explicit = Number(goal.estimated_minutes || 0);
  if (explicit > 0) return explicit;
  const byId = {
    goal_daily_spirit_care: 12,
    goal_weekly_expedition: 90,
    goal_monthly_shop_rank: 180,
    goal_ecology_a_rank: 240,
    goal_trial_all_b: 360,
    goal_rare_spirit_collect: 300,
    goal_bond_10_first: 180,
    goal_bond_10_all_core: 480,
  };
  if (byId[goal.goal_id]) return byId[goal.goal_id];
  const byIntent = {
    short_session: 12,
    weekly_return: 90,
    monthly_mastery: 180,
    build_expression: 240,
    long_challenge: 360,
    collection_drive: 300,
    emotional_retention: 180,
    completionist: 480,
  };
  if (byIntent[goal.retention_intent]) return byIntent[goal.retention_intent];
  const byType = {
    daily: 12,
    weekly: 90,
    monthly: 180,
    collection: 240,
    challenge: 300,
    relationship: 180,
  };
  return byType[goal.goal_type] || 60;
}

function postMainlineTenHourGoalEvidenceSpec() {
  const year2Goals = data.year2GoalBook || [];
  const freeplayGoals = data.freeplayGoals || [];
  const rareSpiritLines = new Set((data.rareSpiritEvents || []).map((event) => event.spirit_id).filter(Boolean));
  const targetMinutes = 600;
  const year2Minutes = year2Goals.reduce((sum, goal) => sum + Number(goal.estimated_minutes || 0), 0);
  const freeplayMinutes = freeplayGoals.reduce((sum, goal) => sum + freeplayGoalEstimatedMinutes(goal), 0);
  const rareSpiritEventMinutes = Math.min(240, rareSpiritLines.size * 40);
  const totalMinutes = year2Minutes + freeplayMinutes + rareSpiritEventMinutes;
  const year2Types = new Set(year2Goals.map((goal) => goal.goal_type));
  const freeplayTypes = new Set(freeplayGoals.map((goal) => goal.goal_type));
  const freeplayIntents = new Set(freeplayGoals.map((goal) => goal.retention_intent));
  const coverage = [
    {
      key: "short_session",
      label: "短会话",
      pass: year2Types.has("daily") && freeplayIntents.has("short_session"),
      hint: "每天 5-20 分钟能照料精怪、补一单店铺或顺手推进。",
    },
    {
      key: "weekly_return",
      label: "周回访",
      pass: year2Types.has("weekly") && freeplayIntents.has("weekly_return"),
      hint: "每周用远征、岗位熟练和阶段订单把玩家拉回来。",
    },
    {
      key: "monthly_management",
      label: "月度经营",
      pass: year2Types.has("seasonal") && freeplayIntents.has("monthly_mastery"),
      hint: "名铺赛季、节气主题和水路订单形成月度经营目标。",
    },
    {
      key: "collection_drive",
      label: "收藏造景",
      pass: year2Types.has("collection") && freeplayTypes.has("collection") && rareSpiritLines.size >= 4,
      hint: "稀有精怪、秘境印记和生态庭院给通关后留下画面追求。",
    },
    {
      key: "long_challenge",
      label: "挑战复玩",
      pass: year2Types.has("challenge") && freeplayTypes.has("challenge"),
      hint: "第二年节气试炼和秘境熟悉度支撑高分挑战。",
    },
    {
      key: "emotional_retention",
      label: "情感留存",
      pass: year2Types.has("relationship") && freeplayTypes.has("relationship"),
      hint: "满羁绊、后日谈、小剧场和共同生活让玩家愿意留下。",
    },
  ];
  const minutesFor = (goalTypes, freeplayPredicate, extraMinutes = 0) => {
    const year2Part = year2Goals
      .filter((goal) => goalTypes.includes(goal.goal_type))
      .reduce((sum, goal) => sum + Number(goal.estimated_minutes || 0), 0);
    const freeplayPart = freeplayGoals
      .filter(freeplayPredicate)
      .reduce((sum, goal) => sum + freeplayGoalEstimatedMinutes(goal), 0);
    return year2Part + freeplayPart + extraMinutes;
  };
  const routeRows = [
    {
      key: "short_session",
      title: "宴后短会话",
      minutes: minutesFor(["daily"], (goal) => goal.cycle_type === "daily" || goal.retention_intent === "short_session"),
      detail: "照料精怪、补店铺单、派短途远征，解决通关后第一天不知道做什么的问题。",
    },
    {
      key: "weekly_return",
      title: "第一周回访",
      minutes: minutesFor(["weekly"], (goal) => goal.cycle_type === "weekly" || goal.retention_intent === "weekly_return"),
      detail: "岗位熟练、远征回报和首周礼宴订单，把每日经营接成周节奏。",
    },
    {
      key: "monthly_management",
      title: "名铺月度经营",
      minutes: minutesFor(["seasonal"], (goal) => goal.cycle_type === "monthly" || goal.retention_intent === "monthly_mastery"),
      detail: "节气主题、名铺评分和高级订单让第二年仍有经营目标。",
    },
    {
      key: "collection_drive",
      title: "收藏与生态造景",
      minutes: minutesFor(["collection"], (goal) => goal.goal_type === "collection", rareSpiritEventMinutes),
      detail: "稀有精怪线、庭院共鸣、秘境图鉴和长期画面反馈构成收藏路线。",
    },
    {
      key: "long_challenge",
      title: "节气试炼挑战",
      minutes: minutesFor(["challenge"], (goal) => goal.goal_type === "challenge"),
      detail: "反复挑战试炼评级、秘境读招和 Boss 熟悉度，支撑复玩。",
    },
    {
      key: "emotional_retention",
      title: "羁绊与后日谈",
      minutes: minutesFor(["relationship"], (goal) => goal.goal_type === "relationship"),
      detail: "满羁绊、小剧场、同住事件和终章伙伴常驻，形成情感留存。",
    },
  ];
  const contentPass = totalMinutes >= targetMinutes
    && coverage.every((entry) => entry.pass)
    && year2Goals.length >= 8
    && freeplayGoals.length >= 6
    && rareSpiritLines.size >= 4;
  const mainlineReady = mainStoryFullClearPass();
  return {
    releaseGate: "rrg_009",
    title: "主线后十小时路线",
    targetMinutes,
    totalMinutes,
    totalHours: Math.round((totalMinutes / 60) * 10) / 10,
    year2Minutes,
    freeplayMinutes,
    rareSpiritEventMinutes,
    year2GoalCount: year2Goals.length,
    freeplayGoalCount: freeplayGoals.length,
    rareSpiritLineCount: rareSpiritLines.size,
    coverage,
    routeRows,
    contentPass,
    mainlineReady,
    pass: contentPass && mainlineReady,
  };
}

function postMainlineTenHourGoalPass() {
  return postMainlineTenHourGoalEvidenceSpec().pass;
}

function postMainlineTenHourWorldRouteSpec(width = refs.world?.width || 960, height = refs.world?.height || 640) {
  if (!year2Unlocked() || state.dungeon) return null;
  const evidence = postMainlineTenHourGoalEvidenceSpec();
  const routeRows = evidence.routeRows.filter((row) => row.minutes > 0);
  if (!routeRows.length) return null;
  const focusIndex = Math.max(0, (state.day - 1) % routeRows.length);
  const focusRow = routeRows[focusIndex] || routeRows[0];
  const coverageDone = evidence.coverage.filter((entry) => entry.pass).length;
  const cardWidth = 296;
  const cardHeight = 138;
  const x = Math.max(34, Math.min(width - cardWidth - 34, 34));
  const y = Math.max(70, Math.min(height - cardHeight - 46, 78));
  return {
    key: `${state.day}:${evidence.totalMinutes}:${coverageDone}:${focusRow.key}`,
    title: "主线后十小时年路",
    label: "十小时年路灯牌",
    headline: evidence.pass ? "宴后仍有路可走" : "宴后目标待补强",
    detail: focusRow.detail,
    focusRow,
    coverageDone,
    coverageTotal: evidence.coverage.length,
    totalMinutes: evidence.totalMinutes,
    targetMinutes: evidence.targetMinutes,
    totalHours: evidence.totalHours,
    pass: evidence.pass,
    contentPass: evidence.contentPass,
    routeRows,
    rect: { x, y, width: cardWidth, height: cardHeight },
    anchor: { x: width - 118, y: Math.max(210, height - 158) },
  };
}

function postMainlineRouteStationSpecs(width = refs.world?.width || 960, height = refs.world?.height || 640) {
  const route = postMainlineTenHourWorldRouteSpec(width, height);
  if (!route) return [];
  const stationMeta = {
    short_session: { label: "晨课铃", icon: "晨", x: 324, y: Math.max(384, height - 214), accent: "#286f58", panel: "精怪照料 / 今日短目标" },
    weekly_return: { label: "远征风旗", icon: "远", x: 624, y: Math.max(392, height - 206), accent: "#4d91a6", panel: "本周远征 / 岗位回访" },
    monthly_management: { label: "名铺月榜", icon: "铺", x: Math.max(658, width - 286), y: 74, accent: "#b47d2f", panel: "名铺赛季 / 月度经营" },
    collection_drive: { label: "庭院图钉", icon: "景", x: 284, y: 176, accent: "#5d6f65", panel: "生态庭院 / 稀有收集" },
    long_challenge: { label: "试炼石盘", icon: "试", x: Math.max(612, width - 316), y: 242, accent: "#be4f37", panel: "年轮试炼 / 秘境挑战" },
    emotional_retention: { label: "羁绊茶盏", icon: "心", x: 92, y: Math.max(410, height - 176), accent: "#a55666", panel: "羁绊后日谈 / 小剧场" },
  };
  return route.routeRows.slice(0, 6).map((row, index) => {
    const meta = stationMeta[row.key] || { label: row.title, icon: "路", x: 120 + index * 92, y: height - 168, accent: "#8f5f3f", panel: "目标册" };
    const x = Math.max(24, Math.min(width - 112, meta.x));
    const y = Math.max(56, Math.min(height - 88, meta.y));
    return {
      ...row,
      ...meta,
      routeKey: row.key,
      order: index + 1,
      rect: { x, y, width: 100, height: 72 },
    };
  });
}

function postMainlineRouteStationTargets() {
  return postMainlineRouteStationTargetsWorld({
    stationSpecs: postMainlineRouteStationSpecs(),
  });
}

function postMainlineRouteStationFocusSpec(station) {
  if (!station) return {
    selector: "#goalBookPanel",
    fallbackSelector: "#goalBookPanel",
    panelGroup: "core",
    targetLabel: "主线后目标册",
    advice: "先看目标册顶部的主线后十小时路线，再挑一条今天想走的路。",
  };
  if (station.routeKey === "short_session") {
    const goal = recommendedYear2Goals("daily", 1)[0] || data.year2GoalBook.find((entry) => entry.goal_type === "daily");
    return {
      selector: goal ? `[data-year2-goal="${selectorDataValue(goal.goal_id)}"]` : "#goalBookPanel",
      fallbackSelector: "#goalBookPanel",
      panelGroup: "core",
      targetLabel: goal ? year2GoalTitle(goal) : "今日短目标",
      advice: "适合 5 到 20 分钟的回游：照料精怪、补一单、顺手把今天的洞天气口接上。",
    };
  }
  if (station.routeKey === "weekly_return") {
    const freeGoal = data.freeplayGoals.find((goal) => goal.goal_id === "goal_weekly_expedition")
      || data.freeplayGoals.find((goal) => goal.cycle_type === "weekly");
    const weeklyGoal = recommendedYear2Goals("weekly", 1)[0];
    return {
      selector: freeGoal ? `[data-freeplay-goal="${selectorDataValue(freeGoal.goal_id)}"]` : weeklyGoal ? `[data-year2-goal="${selectorDataValue(weeklyGoal.goal_id)}"]` : "#goalBookPanel",
      fallbackSelector: "#goalBookPanel",
      panelGroup: "core",
      targetLabel: freeGoal ? localize(freeGoal.goal_name_key, freeGoal.goal_id) : weeklyGoal ? year2GoalTitle(weeklyGoal) : "本周回访目标",
      advice: "适合隔几天回来继续：派远征、看岗位熟练、收回商路或秘境线索。",
    };
  }
  if (station.routeKey === "monthly_management") {
    const seasonalGoal = recommendedYear2Goals("seasonal", 1)[0] || data.year2GoalBook.find((goal) => goal.goal_type === "seasonal");
    return {
      selector: seasonalGoal ? `[data-year2-goal="${selectorDataValue(seasonalGoal.goal_id)}"]` : '[data-shop-season-board="rank"]',
      fallbackSelector: "#shopReport",
      panelGroup: "core",
      targetLabel: seasonalGoal ? year2GoalTitle(seasonalGoal) : "名铺赛季榜",
      advice: "适合月度经营：看评分短板、货架主题、节气订单和下一档奖励。",
    };
  }
  if (station.routeKey === "collection_drive") {
    const ecologyGoal = ecologyCourtyardGoalRows().find((row) => !row.claimed && (row.ready || row.active)) || ecologyCourtyardGoalRows().find((row) => !row.claimed);
    return {
      selector: ecologyGoal ? `[data-ecology-goal="${selectorDataValue(ecologyGoal.comboId)}"]` : ".rare-clue-tracker",
      fallbackSelector: "#goalBookPanel",
      panelGroup: "core",
      targetLabel: ecologyGoal ? ecologyGoal.name : "稀有精怪线索追踪",
      advice: "适合收藏和造景：补生态庭院、稀有精怪、秘境图鉴，让洞天越来越像自己的家。",
    };
  }
  if (station.routeKey === "long_challenge") {
    const trial = recommendedSolarTrial();
    const challengeGoal = data.freeplayGoals.find((goal) => goal.goal_id === "goal_trial_all_b");
    return {
      selector: trial ? `[data-solar-trial="${selectorDataValue(trial.trial_id)}"]` : challengeGoal ? `[data-freeplay-goal="${selectorDataValue(challengeGoal.goal_id)}"]` : "#solarTrialPanel",
      fallbackSelector: trial ? "#solarTrialPanel" : "#goalBookPanel",
      panelGroup: "systems",
      targetLabel: trial ? solarTrialName(trial) : challengeGoal ? localize(challengeGoal.goal_name_key, challengeGoal.goal_id) : "年轮试炼",
      advice: "适合复玩挑战：试炼评级、秘境读招、Boss 熟悉度和高分经营会在这里汇合。",
    };
  }
  if (station.routeKey === "emotional_retention") {
    const bondGoal = data.freeplayGoals.find((goal) => goal.goal_id === "goal_bond_10_first")
      || data.freeplayGoals.find((goal) => goal.goal_type === "relationship");
    const lifeRow = rareSpiritLifeCodexRows().find((row) => row.readyEvents.length > 0 || row.owned) || null;
    return {
      selector: lifeRow ? `[data-life-codex-line="${selectorDataValue(lifeRow.lineId)}"]` : bondGoal ? `[data-freeplay-goal="${selectorDataValue(bondGoal.goal_id)}"]` : "#relationshipPanel",
      fallbackSelector: bondGoal ? "#goalBookPanel" : "#relationshipPanel",
      panelGroup: lifeRow ? "core" : "story",
      targetLabel: lifeRow ? `${lifeRow.spiritName}生活图鉴` : bondGoal ? localize(bondGoal.goal_name_key, bondGoal.goal_id) : "后日谈关系线",
      advice: "适合慢慢陪伴：满羁绊、小剧场、同住后日谈和终章伙伴常驻都从这里接回生活感。",
    };
  }
  return {
    selector: "#goalBookPanel",
    fallbackSelector: "#goalBookPanel",
    panelGroup: "core",
    targetLabel: station.title,
    advice: station.detail,
  };
}

function postMainlineTodayRouteRowNode(row = null) {
  if (!row) return null;
  const station = postMainlineRouteStationSpecs()
    .find((entry) => entry.routeKey === row.key) || {
      routeKey: row.key,
      label: row.title || "今日路线",
      title: row.title || "主线后今日路线",
      detail: row.detail || "先接起一条今天就能推进的路线。",
      icon: "今",
      panel: "目标册",
      accent: "#b47d2f",
    };
  const focus = postMainlineTodayRouteFocusSpec(row);
  return {
    row,
    routeKey: row.key || station.routeKey || "",
    title: row.title || station.title || "主线后今日路线",
    stationLabel: station.label || row.title || "今日路线",
    panelLabel: station.panel || "目标册",
    icon: station.icon || "今",
    minutes: Number(row.minutes || 0),
    detail: row.detail || focus.advice || "先定位一条今天就能推进的路线。",
    selector: focus.selector,
    fallbackSelector: focus.fallbackSelector,
    panelGroup: focus.panelGroup || "core",
    targetLabel: focus.targetLabel || row.title || "主线后目标册",
    advice: focus.advice || row.detail || "先从最顺手的一条开始。",
    accent: station.accent || "#b47d2f",
  };
}

function postMainlineTodayRouteFocusSpec(row = null) {
  const station = row
    ? postMainlineRouteStationSpecs().find((entry) => entry.routeKey === row.key) || {
      ...row,
      routeKey: row.key,
      label: row.title || "今日路线",
    }
    : null;
  const base = postMainlineRouteStationFocusSpec(station);
  return {
    routeKey: row?.key || station?.routeKey || "",
    routeTitle: row?.title || station?.title || "主线后今日路线",
    selector: base.selector || "#goalBookPanel",
    fallbackSelector: base.fallbackSelector || "#goalBookPanel",
    panelGroup: base.panelGroup || "core",
    targetLabel: base.targetLabel || row?.title || "主线后目标册",
    advice: base.advice || row?.detail || "先定位一条今天就能推进的路线。",
    safety: "点击只定位年鉴页、自由目标卡或对应系统入口，不会自动领取奖励、推进时间、交单、开铺、开启试炼、发商队或消耗资源。",
  };
}

function postMainlineTodayRouteWorldSpec(width = refs.world?.width || 960, height = refs.world?.height || 640) {
  const route = postMainlineTenHourWorldRouteSpec(width, height);
  if (!route?.focusRow) return null;
  const focus = postMainlineTodayRouteFocusSpec(route.focusRow);
  const rowNode = postMainlineTodayRouteRowNode(route.focusRow);
  if (!rowNode) return null;
  const rows = route.routeRows
    .slice(0, 3)
    .map((row) => {
      const node = postMainlineTodayRouteRowNode(row);
      return node
        ? {
          ...node,
          active: row.key === route.focusRow.key,
        }
        : null;
    })
    .filter(Boolean);
  const cardWidth = 248;
  const cardHeight = 118;
  const x = Math.max(34, Math.min(width - cardWidth - 34, route.rect.x + 10));
  const y = Math.max(168, Math.min(height - cardHeight - 42, route.rect.y + route.rect.height + 18));
  return {
    key: `${state.day}:${route.focusRow.key}:${route.totalMinutes}:${route.coverageDone}`,
    title: "主线后今日路线",
    headline: "今天就有可落袋的事",
    routeKey: route.focusRow.key,
    focusRow: route.focusRow,
    rowNode,
    rows,
    selector: focus.selector,
    fallbackSelector: focus.fallbackSelector,
    panelGroup: focus.panelGroup,
    targetLabel: focus.targetLabel,
    advice: focus.advice,
    safety: focus.safety,
    minutes: rowNode.minutes,
    coverageDone: route.coverageDone,
    coverageTotal: route.coverageTotal,
    totalMinutes: route.totalMinutes,
    targetMinutes: route.targetMinutes,
    rect: { x, y, width: cardWidth, height: cardHeight },
    anchor: {
      x: route.rect.x + route.rect.width - 34,
      y: route.rect.y + route.rect.height + 10,
    },
  };
}

function postMainlineTodayRouteWorldAtCanvasPoint(px, py) {
  const spec = postMainlineTodayRouteWorldSpec(refs.world?.width || 960, refs.world?.height || 640);
  if (!spec?.rect) return null;
  const { rect } = spec;
  return px >= rect.x && px <= rect.x + rect.width && py >= rect.y && py <= rect.y + rect.height
    ? {
      id: "post_mainline_today_route",
      type: "post_mainline_today_route",
      label: spec.title,
      selector: spec.selector,
      fallbackSelector: spec.fallbackSelector,
      routeKey: spec.routeKey,
      postMainlineTodayRoute: spec,
      rect,
    }
    : null;
}

function focusPostMainlineTodayRouteWorldFromCanvas(target = postMainlineTodayRouteWorldSpec()) {
  const spec = target?.postMainlineTodayRoute || target;
  if (!spec?.rowNode) return false;
  const focus = spec.focus || postMainlineTodayRouteFocusSpec(spec.focusRow || spec.rowNode.row);
  const routeSpec = postMainlineTenHourWorldRouteSpec();
  postMainlineTodayRouteWorldFocus = {
    key: spec.key,
    day: state.day,
    routeKey: spec.routeKey || spec.rowNode.routeKey || "",
  };
  if (routeSpec?.key) {
    postMainlineTenHourWorldFocus = {
      key: routeSpec.key,
      day: state.day,
      routeKey: spec.routeKey || spec.rowNode.routeKey || "",
    };
  }
  queueStoryCompassFocusTarget(postMainlineTodayRouteFocusTargetWorld({ spec, focus }));
  const logEntry = postMainlineTodayRouteLogSpecWorld({ spec, focus });
  addLog(logEntry.title, logEntry.log);
  render();
  return true;
}

function postMainlineTenHourGoalMarkup(spec = postMainlineTenHourGoalEvidenceSpec()) {
  const stateClass = spec.pass ? "pass" : spec.contentPass ? "ready" : "warn";
  const statusText = spec.pass ? "已满足 rrg_009" : spec.contentPass ? "内容已备好，等待主线通关状态" : "目标厚度不足";
  return `
    <div class="post-mainline-goal-route ${stateClass}">
      <div class="post-mainline-goal-head">
        <strong>${spec.title}</strong>
        <em>${statusText}</em>
      </div>
      <span>通关后至少10小时有明确目标：当前估算 ${spec.totalMinutes}/${spec.targetMinutes} 分钟（约 ${spec.totalHours} 小时），第二年目标 ${spec.year2GoalCount} 条、自由目标 ${spec.freeplayGoalCount} 条、稀有精怪线 ${spec.rareSpiritLineCount} 条。</span>
      <div class="post-mainline-goal-meters">
        ${spec.routeRows.map((row) => `
          <span>
            <b>${row.title}</b>
            <i>${row.minutes} 分钟</i>
            <small>${row.detail}</small>
          </span>
        `).join("")}
      </div>
      <div class="post-mainline-goal-coverage">
        ${spec.coverage.map((entry) => `<small class="${entry.pass ? "pass" : "warn"}"><b>${entry.label}</b>${entry.hint}</small>`).join("")}
      </div>
      <button type="button" data-post-mainline-goal-route="focus">定位下一条可追目标</button>
      <small>点击只定位目标册里的下一步，不会自动跳关、不会自动领取奖励，也不会消耗资源。</small>
    </div>
  `;
}

function focusPostMainlineTenHourGoalEvidence() {
  const spec = postMainlineTenHourGoalEvidenceSpec();
  const worldSpec = postMainlineTenHourWorldRouteSpec();
  if (worldSpec?.key) {
    postMainlineTenHourWorldFocus = {
      key: worldSpec.key,
      day: state.day,
    };
  }
  const focusYear2Goal = data.year2GoalBook.find((goal) => year2GoalReady(goal))
    || recommendedYear2Goals("daily", 1)[0]
    || recommendedYear2Goals("weekly", 1)[0]
    || data.year2GoalBook.find((goal) => year2GoalUnlocked(goal))
    || data.year2GoalBook[0];
  const focusFreeplayGoal = data.freeplayGoals.find((goal) => freeplayGoalReady(goal))
    || data.freeplayGoals.find((goal) => freeplayGoalUnlocked(goal))
    || data.freeplayGoals[0];
  const selector = focusYear2Goal
    ? `[data-year2-goal="${selectorDataValue(focusYear2Goal.goal_id)}"]`
    : focusFreeplayGoal
      ? `[data-freeplay-goal="${selectorDataValue(focusFreeplayGoal.goal_id)}"]`
      : "#goalBookPanel";
  const goalLabel = focusYear2Goal
    ? year2GoalTitle(focusYear2Goal)
    : focusFreeplayGoal
      ? localize(focusFreeplayGoal.goal_name_key, focusFreeplayGoal.goal_id)
      : "目标册";
  queueStoryCompassFocusTarget({
    selector,
    fallbackSelector: "#goalBookPanel",
    label: "主线后十小时路线",
    log: `${spec.title} 已定位到「${goalLabel}」。当前证据 ${spec.totalMinutes}/${spec.targetMinutes} 分钟，覆盖 ${spec.coverage.filter((entry) => entry.pass).length}/${spec.coverage.length} 类留存意图；这里只定位下一步，不会自动跳关、不会自动领取奖励，也不会消耗资源。`,
    panelGroup: "core",
    missingTitle: "主线后十小时路线",
    missingLog: "十小时路线证据已经写入目标册，但当前目标按钮暂时没有找到。先查看目标册与留存钩子面板顶部的主线后路线卡。",
  });
  return true;
}

function spiritJobGoalRows() {
  return data.spiritJobMastery
    .filter((entry) => [1, 3, 5].includes(Number(entry.level || 0)))
    .sort((a, b) => {
      const jobCompare = String(a.job_type).localeCompare(String(b.job_type));
      return jobCompare || Number(a.level || 0) - Number(b.level || 0);
    });
}

function spiritJobProgress(job) {
  const spirits = state.spirits.filter((spirit) => {
    ensureSpiritJobs(spirit);
    return (spirit.jobLevels?.[job] || 0) > 0 || (spirit.jobExp?.[job] || 0) > 0 || spiritMainJob(spirit) === job;
  });
  const best = spirits
    .slice()
    .sort((a, b) => (b.jobLevels?.[job] || 0) - (a.jobLevels?.[job] || 0) || (b.jobExp?.[job] || 0) - (a.jobExp?.[job] || 0))[0];
  return {
    spirit: best,
    level: best?.jobLevels?.[job] || 0,
    exp: best?.jobExp?.[job] || 0,
  };
}

function spiritJobGoalReady(goal) {
  return spiritJobProgress(goal.job_type).level >= Number(goal.level || 0);
}

function spiritJobGoalClaimed(goal) {
  return state.claimedSpiritJobGoals.has(goal.mastery_id);
}

function spiritJobGoalRewardText(goal) {
  const level = Number(goal.level || 0);
  if (level >= 5) return `${itemName("item_stone_spirit_shard")} x3 · 声望 +2 · 称号`;
  if (level >= 3) return `${itemName("item_stone_spirit_shard")} x2 · 声望 +1`;
  return `${itemName("item_material_clean_water")} x2 · 灵石 12`;
}

function spiritJobMilestoneScene(goal, progress) {
  const scenes = {
    farm: ["田垄夜露", "精怪把水纹压进田埂，第二天泥土会自己发亮。"],
    workshop: ["灶火定律", "工坊火候被记成一圈灵纹，锅铲落下时有星屑跳动。"],
    shop: ["迎客铃响", "旧铺门口多了一枚小铃，熟客路过会下意识停步。"],
    patrol: ["巡夜灯痕", "灯影沿着篱笆巡了一圈，虫鸣忽然低了半拍。"],
    expedition: ["远路风标", "雷纹竹签插在镇口，远路上的风会先送来消息。"],
    garden: ["静池花息", "庭院一角泛起月白水光，精怪们围着那里打盹。"],
  }[goal.job_type] || ["岗位记忆", "精怪把今天的手艺记进洞天的灵纹里。"];
  return {
    title: scenes[0],
    detail: scenes[1],
    line: `${progress.spirit?.name || "精怪"}在${jobName(goal.job_type)} Lv.${goal.level} 留下了新的岗位记忆。`,
  };
}

function spiritJobMilestoneType(job) {
  return {
    farm: "field_totem",
    workshop: "forge_sigils",
    shop: "welcome_bell",
    patrol: "night_lamps",
    expedition: "route_banner",
    garden: "garden_pool",
  }[job] || "spirit_mark";
}

function applySpiritJobMilestone(goal) {
  const level = Number(goal.level || 0);
  if (level < 3) return null;
  const progress = spiritJobProgress(goal.job_type);
  const scene = spiritJobMilestoneScene(goal, progress);
  let milestone = (state.spiritJobMilestones || []).find((entry) => entry.masteryId === goal.mastery_id);
  if (!milestone) {
    milestone = {
      masteryId: goal.mastery_id,
      job: goal.job_type,
      level,
      title: scene.title,
      detail: scene.detail,
      spiritName: progress.spirit?.name || "精怪",
      visualType: spiritJobMilestoneType(goal.job_type),
      unlockedDay: state.day,
    };
    state.spiritJobMilestones.push(milestone);
  }
  state.spiritMemoryFlags.add(`memory_job_${goal.job_type}_${level}`);
  state.activeDialogue = [
    ...state.activeDialogue.slice(-3),
    { speaker: progress.spirit?.name || "精怪", text: scene.detail },
    { speaker: "古戒", text: scene.line },
  ];
  complete(`spirit_job_milestone_${goal.job_type}_${level}`);
  return milestone;
}

function spiritJobTaskText(milestone) {
  const texts = {
    farm: ["替田垄夜露试一次灵田", "保持至少 1 块作物成熟或种植中，让夜露有地方落脚。"],
    workshop: ["替灶火定律试一次火候", "准备工坊队列或保留净水，让灶火灵纹能继续转动。"],
    shop: ["替迎客铃响接一位熟客", "完成一次旧铺营业或保留店铺反馈，让铃声有回应。"],
    patrol: ["跟着巡夜灯痕走一圈", "处理或记录一次节气风险，让巡夜灯确认路线。"],
    expedition: ["沿远路风标探一次路", "拥有一次秘境/商路痕迹，让风标记住远方方向。"],
    garden: ["在静池花息旁安抚精怪", "让至少两只精怪或高心情精怪停在洞天里，共鸣静池。"],
  }[milestone.job] || ["整理岗位记忆", "让精怪完成一次对应岗位行动。"];
  return { title: texts[0], hint: texts[1] };
}

function spiritJobTaskReady(milestone) {
  if (!milestone) return false;
  if (milestone.job === "farm") return state.plots.some((plot) => plot.cropId);
  if (milestone.job === "workshop") return (state.workshopQueue || []).length > 0 || hasItem("item_material_clean_water", 1);
  if (milestone.job === "shop") return state.completed.has("shop") || (state.shopReport || []).length > 0;
  if (milestone.job === "patrol") return state.resolvedRisks.size > 0 || state.activeRisks.length > 0;
  if (milestone.job === "expedition") return state.dungeonClears.size > 0 || (state.tradeRuns || []).length > 0 || state.completed.has("spirit_expedition");
  if (milestone.job === "garden") return state.spirits.length >= 2 || state.spirits.some((spirit) => Number(spirit.mood || 0) >= 90);
  return true;
}

function spiritJobTaskRewardText(milestone) {
  if (!milestone) return "";
  if (milestone.level >= 5) return `${itemName("item_yearwheel_memory_shard")} x1 · 声望 +1`;
  return `${itemName("item_stone_spirit_shard")} x1 · 灵石 18`;
}

function spiritJobTaskEffectLevel(job) {
  return (state.spiritJobMilestones || [])
    .filter((milestone) => milestone.job === job && state.completedSpiritJobTasks.has(milestone.masteryId))
    .reduce((best, milestone) => Math.max(best, Number(milestone.level || 0)), 0);
}

function spiritJobTaskPersistentEffectText(job) {
  const level = spiritJobTaskEffectLevel(job);
  if (job === "farm") return level >= 5 ? "持续影响：农田收获额外 +2" : level >= 3 ? "持续影响：农田收获额外 +1" : "";
  if (job === "workshop") return level >= 5 ? "持续影响：工坊效率 +12%" : level >= 3 ? "持续影响：工坊效率 +6%" : "";
  if (job === "shop") return level >= 5 ? "持续影响：顾客预算 +15%，来客 +2" : level >= 3 ? "持续影响：顾客预算 +8%，来客 +1" : "";
  if (job === "patrol") return level >= 5 ? "持续影响：首个入夜风险直接化解" : level >= 3 ? "持续影响：首个入夜风险被削弱" : "";
  if (job === "expedition") return level >= 5 ? "持续影响：商路利润 +10%，稀有奖励 +1" : level >= 3 ? "持续影响：商路利润 +5%" : "";
  if (job === "garden") return level >= 5 ? "持续影响：睡前全体心情 +8，体力 +6" : level >= 3 ? "持续影响：睡前全体心情 +4，体力 +3" : "";
  return "";
}

function completeSpiritJobTask(masteryId) {
  const milestone = (state.spiritJobMilestones || []).find((entry) => entry.masteryId === masteryId);
  if (!milestone) return addLog("岗位小事未解锁", "先领取对应 Lv3/Lv5 岗位修行奖励。");
  if (state.completedSpiritJobTasks.has(masteryId)) return addLog("岗位小事已完成", `${milestone.title} 的后续小事已经完成。`);
  if (!spiritJobTaskReady(milestone)) return addLog("岗位小事未就绪", spiritJobTaskText(milestone).hint);

  if (milestone.level >= 5) {
    addItem("item_yearwheel_memory_shard", 1);
    state.fame += 1;
  } else {
    addItem("item_stone_spirit_shard", 1);
    state.gold += 18;
  }
  state.completedSpiritJobTasks.add(masteryId);
  state.spiritMemoryFlags.add(`memory_job_task_${milestone.job}_${milestone.level}`);
  const taskRewardText = spiritJobTaskRewardText(milestone);
  const taskEffectText = spiritJobTaskPersistentEffectText(milestone.job);
  state.activeDialogue = [
    ...state.activeDialogue.slice(-3),
    { speaker: milestone.spiritName || "精怪", text: `${milestone.title}终于有了回应。` },
    { speaker: "古戒", text: `${jobName(milestone.job)}的小事被记下，洞天的岗位灵纹更稳了。` },
  ];
  complete(`spirit_job_task_${milestone.job}_${milestone.level}`);
  triggerGoalClaimFeedback("job_task", {
    headline: spiritJobTaskText(milestone).title,
    detail: `${jobName(milestone.job)}的小事被记进岗位页。${taskEffectText || ""}`,
    rewardText: taskRewardText,
  });
  playCue("对话翻页");
  addLog("岗位小事完成", `${spiritJobTaskText(milestone).title}：获得 ${taskRewardText}。${taskEffectText}`);
  render();
}

function claimSpiritJobGoal(masteryId) {
  const goal = data.spiritJobMastery.find((entry) => entry.mastery_id === masteryId);
  if (!goal) return addLog("岗位目标不存在", masteryId);
  if (spiritJobGoalClaimed(goal)) return addLog("岗位目标已领取", `${jobName(goal.job_type)} Lv.${goal.level} 奖励已经领过。`);
  if (!spiritJobGoalReady(goal)) return addLog("岗位目标未达成", `${jobName(goal.job_type)} 还没有精怪达到 Lv.${goal.level}。`);

  const level = Number(goal.level || 0);
  if (level >= 5) {
    addItem("item_stone_spirit_shard", 3);
    state.fame += 2;
    state.completed.add(goal.unlock_effect || `title_job_${goal.job_type}_master`);
  } else if (level >= 3) {
    addItem("item_stone_spirit_shard", 2);
    state.fame += 1;
    state.completed.add(goal.unlock_effect || `anim_job_${goal.job_type}_special`);
  } else {
    addItem("item_material_clean_water", 2);
    state.gold += 12;
    state.completed.add(goal.unlock_effect || `buff_job_${goal.job_type}_01`);
  }
  state.claimedSpiritJobGoals.add(goal.mastery_id);
  const milestone = applySpiritJobMilestone(goal);
  const rewardText = spiritJobGoalRewardText(goal);
  complete("spirit_job_goal_claim");
  triggerGoalClaimFeedback("job_goal", {
    headline: `${jobName(goal.job_type)}修行 Lv.${goal.level}`,
    detail: milestone ? `${milestone.title} 已留在洞天。` : `${jobName(goal.job_type)}岗位修行已结印。`,
    rewardText,
  });
  playCue("成就解锁");
  addLog("岗位目标达成", `${jobName(goal.job_type)} Lv.${goal.level}：领取 ${rewardText}。${milestone ? ` ${milestone.title} 已留在洞天。` : ""}`);
  render();
}

function rareSpiritLineId(event) {
  const suffix = String(event?.spirit_id || "").replace(/^spirit_/, "");
  const config = data.spirits.find((spirit) =>
    spirit.spirit_id.startsWith(`${event?.spirit_id}_`) || spirit.spirit_line_id === `spirit_line_${suffix}`,
  );
  return config?.spirit_line_id || `spirit_line_${suffix}`;
}

function rareSpiritConfigForEvent(event) {
  if (!event) return null;
  const lineId = rareSpiritLineId(event);
  const stageSuffix = {
    first_meet: "_01",
    evolution: "_02",
    bond_final: "_03",
  }[event.event_stage] || "_01";
  return data.spirits.find((spirit) => spirit.spirit_line_id === lineId && spirit.spirit_id.endsWith(stageSuffix))
    || data.spirits.find((spirit) => spirit.spirit_line_id === lineId)
    || data.spirits.find((spirit) => spirit.spirit_id.startsWith(`${event.spirit_id}_`));
}

function rareSpiritOwned(event) {
  const lineId = rareSpiritLineId(event);
  return state.spirits.some((spirit) => (spirit.lineId || spiritLine(spirit.id)) === lineId);
}

function rareSpiritOwnedSpirit(event) {
  const lineId = rareSpiritLineId(event);
  return state.spirits.find((spirit) => (spirit.lineId || spiritLine(spirit.id)) === lineId) || null;
}

function upgradeRareSpiritToConfig(spirit, config) {
  return upgradeSpiritToConfig(spirit, config, { carryRareGiftDays: true });
}

function rareSpiritGiftItemId(event) {
  const giftMap = {
    花铃香囊: "item_gift_hualing_sachet",
    花铃迎客架: "item_furniture_hualing_welcome_shelf",
    无声花市幡: "item_furniture_hualing_silent_market_banner",
    雷纹竹签: "item_gift_leizhu_bamboo_tag",
    护货竹绳: "item_gift_leizhu_cargo_rope",
    雷竹路标: "item_furniture_leizhu_route_marker",
    月露: "item_gift_yuelu",
    凝露莲席: "item_gift_yuelian_respite_mat",
    月莲静池: "item_landscape_yuelian_pool",
    影灯芯: "item_gift_shadow_lamp_core",
    灯影长明盏: "item_furniture_dengying_lantern",
    账页书签: "item_gift_shuqi_bookmark",
    账房缺货签: "item_gift_shuqi_stock_slip",
    洞天旧账新编: "item_gift_shuqi_legacy_ledger",
    百花蜜滴: "item_gift_fengmi_honeydrop",
    花蜜调匙: "item_gift_fengmi_honeyspoon",
    百花蜜罐: "item_gift_fengmi_honeyjar",
  };
  return giftMap[event?.gift_reward] || `item_gift_${event?.entry_id || "rare_spirit"}`;
}

function rareSpiritEventDone(event) {
  return Boolean(event && state.completedRareSpiritEvents?.has(event.entry_id));
}

function rareSpiritDialogueGroupId(event) {
  const dialogueMap = {
    rsea_002: "dialogue_hualing_evolution",
    rsea_012: "dialogue_hualing_bond_final",
    rsea_009: "dialogue_shuqi_first_meet",
    rsea_013: "dialogue_shuqi_evolution",
    rsea_014: "dialogue_shuqi_bond_final",
    rsea_015: "dialogue_fengmi_evolution",
    rsea_016: "dialogue_fengmi_bond_final",
    rsea_011: "dialogue_leizhu_evolution",
    rsea_004: "dialogue_leizhu_bond_final",
    rsea_005: "dialogue_yuelian_first_meet",
    rsea_017: "dialogue_yuelian_evolution",
    rsea_006: "dialogue_yuelian_bond_final",
    rsea_008: "dialogue_dengying_evolution",
    rsea_018: "dialogue_dengying_bond_final",
  };
  return dialogueMap[event?.entry_id] || "";
}

function rareSpiritEventRewardText(event) {
  const giftText = itemName(rareSpiritGiftItemId(event));
  const config = rareSpiritConfigForEvent(event);
  if (event.event_stage === "first_meet" && !rareSpiritOwned(event) && config) {
    return `${localize(config.spirit_name_key, event.spirit_name)}入队 · ${giftText}`;
  }
  if (event.event_stage === "first_meet") return `${event.spirit_name}已结缘 · ${giftText}`;
  return `${event.exclusive_action || "专属动作"} · ${giftText}`;
}

function rareSpiritEventReady(event) {
  if (!event || rareSpiritEventDone(event)) return false;
  const isFirstMeet = event.event_stage === "first_meet";
  const clue = rareSpiritClueForEvent(event);
  const clueUnlocks = clue && !clue.soft && (clue.entryId === event.entry_id || isFirstMeet);
  if (!isFirstMeet && !rareSpiritOwned(event)) return false;
  if (clueUnlocks) return true;
  const condition = event.trigger_condition || "";
  if (condition.includes("flower_goods_display_days")) return state.completed.has("shop") && state.shopShelfTheme === "fresh_market";
  if (condition.includes("flower_shop_score")) return event.entry_id === "rsea_002" ? hualingThemeShowcaseReady() : state.fame * 200 + state.gold >= 1200;
  if (condition.includes("hualing_silent_market_ready")) return hualingSilentMarketReady();
  if (condition.includes("storm_day")) return currentWeatherConfig().disaster_tag.includes("storm") || state.completed.has("spirit_expedition");
  if (condition.includes("protected_midrisk_trade")) return protectedMidRiskTradeComplete();
  if (condition.includes("shuqi_stock_review_ready")) return shuqiStockReviewReady();
  if (condition.includes("shuqi_legacy_ledger_ready")) return shuqiLegacyLedgerReady();
  if (condition.includes("fengmi_dessert_chain_ready")) return fengmiDessertChainReady();
  if (condition.includes("fengmi_honey_feast_ready")) return fengmiHoneyFeastReady();
  if (condition.includes("yuelian_rest_respite_ready")) return yuelianRestRespiteReady();
  if (condition.includes("dengying_winter_lantern_ready")) return dengyingWinterLanternReady();
  if (condition.includes("completed_order_count")) {
    const target = Number((condition.match(/completed_order_count>=\s*(\d+)/)?.[1]) || 1);
    return state.completedOrders.size >= target;
  }
  const bondMatch = condition.match(/([a-z_]+)_bond>=\s*(\d+)/);
  if (bondMatch) {
    const spirit = rareSpiritOwnedSpirit(event);
    const target = Number(bondMatch[2] || 0);
    const bondReady = Boolean(spirit && Number(spirit.bondLevel || 0) >= target);
    if (condition.includes("hidden_thunder_route_clear")) return bondReady && thunderOldRouteReady();
    if (event.entry_id === "rsea_006") {
      syncPondState();
      return bondReady && state.builtBuildings.has("build_fishpond_lv1") && state.pondState.lotusStage === "bloom";
    }
    return bondReady;
  }
  if (condition.includes("night_water_crop_care")) {
    syncPondState();
    return state.builtBuildings.has("build_fishpond_lv1")
      && pondWaterControlUnlocked()
      && Number(state.pondState.nightWaterCropCareDays || 0) >= 3
      && state.pondState.lotusStage !== "none";
  }
  if (condition.includes("winter_night")) return currentTermId() === "term_dongzhi" || state.day >= 18;
  if (condition.includes("hidden_light_puzzle")) return state.completed.has("dungeon_explore");
  if (condition.includes("flower_field_built")) return state.builtBuildings.has("build_lingjing_001");
  return false;
}

function rareSpiritConditionHint(event) {
  const condition = String(event?.trigger_condition || "");
  const hints = [];
  const add = (text) => {
    if (text && !hints.includes(text)) hints.push(text);
  };
  if (condition.includes("flower_goods_display_days")) add("在花朝或春日把货架调成鲜花/礼赠主题，连续陈列花香商品。");
  if (condition.includes("flower_shop_score")) add("把花铃相关店铺评分推到 1200，推荐鲜花市集或礼宴主题。");
  if (condition.includes("hualing_silent_market_ready")) add("让花铃精二阶后，把熟客、回头客和名铺评分一起养稳。");
  if (condition.includes("storm_day")) add("等暴雨/雷雨天，或先完成一次精怪远征、商路供给。");
  if (condition.includes("trade_supply_done")) add("完成至少一次商路供给，让雷竹听见货车绳结声。");
  if (condition.includes("protected_midrisk_trade")) add("派队护送一次中风险商路，优先带雷竹或巡逻岗精怪。");
  if (condition.includes("hidden_thunder_route_clear")) add("打开并走通雷竹旧雷道隐藏路线。");
  if (condition.includes("night_water_crop_care")) add("建好灵池后，夜里照顾水生田 3 次，让水面留下月莲痕迹。");
  if (condition.includes("yuelian_rest_respite_ready")) add("在精怪疲劳时主动留白静养 2 夜，别把每个夜晚都排满工作。");
  if (condition.includes("yuelian_bond")) add("把月莲精羁绊养到 10 级，并让静池莲花真正开放。");
  if (condition.includes("winter_night")) add("等冬至或深冬夜晚，点亮旧仓/镇口灯火。");
  if (condition.includes("old_warehouse_lit_lamp")) add("先点亮 3 盏旧仓灯，让灯影有地方落脚。");
  if (condition.includes("hidden_light_puzzle")) add("在秘境中完成至少一次灯路/隐藏光谜。");
  if (condition.includes("dengying_winter_lantern_ready")) add("灯影精二阶后，在冬至窗口把羁绊养到 10，并完成长灯路目标。");
  if (condition.includes("completed_order_count")) {
    const target = Number((condition.match(/completed_order_count>=\s*(\d+)/)?.[1]) || 5);
    add(`完成 ${target} 单订单，让旧账本开始自己翻页。`);
  }
  if (condition.includes("shuqi_stock_review_ready")) add("结缘书契精后，用账页诊断重排一次货架并修复缺货问题。");
  if (condition.includes("shuqi_legacy_ledger_ready")) add("书契二阶后，把名铺赛季或店铺评分做出 A/S 级回忆。");
  if (condition.includes("flower_field_built")) add("建起灵景花田或花蜜相关庭院，让蜂蜜精闻到花期。");
  if (condition.includes("beehive_not_empty_days")) add("让蜂巢连续 2 天不是空的。");
  if (condition.includes("fengmi_dessert_chain_ready")) add("完成蜂蜜甜品订单、制作甜品并布置甜香主题。");
  if (condition.includes("fengmi_honey_feast_ready")) add("蜂蜜精二阶后，凑齐多只精怪、稳定店铺评分并办起百花茶会。");
  const bondMatch = condition.match(/([a-z_]+)_bond>=\s*(\d+)/);
  if (bondMatch && !condition.includes("yuelian_bond")) add(`把对应精怪羁绊养到 ${Number(bondMatch[2] || 10)} 级。`);
  return hints.join(" · ") || (condition ? `达成条件：${condition}` : "继续推进节气、店铺、秘境或精怪互动。");
}

function rareSpiritClueSourceText(clue = null, event = null) {
  if (!clue) return "尚未发现线索";
  const dungeon = data.dungeonsById.get(clue.sourceDungeonId || "");
  const dungeonText = dungeon
    ? dungeonName(dungeon)
    : clue.sourceDungeonId === "goal_book" ? "目标册奖励"
      : clue.sourceDungeonId === "canal_restoration" ? "灵渠复流"
        : clue.sourceDungeonId || "未知来源";
  const mechanic = data.dungeonSolarMechanics.find((entry) => entry.dungeon_id === clue.sourceMechanicId);
  const mechanicText = mechanic
    ? `${mechanic.solar_term}·${mechanic.puzzle_core}`
    : clue.sourceMechanicId === "goal_book" ? "自由目标"
      : clue.sourceMechanicId === "night_water_crop_care" ? "夜间水田照料"
        : "";
  return `${dungeonText}${mechanicText ? ` · ${mechanicText}` : ""}${clue.unlockedDay ? ` · 第 ${clue.unlockedDay} 天` : ""}`;
}

function rareSpiritStageLabel(stage = "") {
  const labels = {
    first_meet: "初见",
    evolution: "进化",
    bond_final: "满羁绊",
  };
  return labels[stage] || stage || "事件";
}

function rareSpiritClueTrackerRows(limit = 6) {
  const rows = data.rareSpiritEvents.map((event) => {
    const clue = rareSpiritClueForEvent(event);
    const done = rareSpiritEventDone(event);
    const ready = rareSpiritEventReady(event);
    const owned = rareSpiritOwned(event);
    const lineId = rareSpiritLineId(event);
    const priority = done ? 3 : ready ? 0 : clue ? 1 : event.event_stage === "first_meet" ? 2 : 4;
    const stateClass = done ? "done" : ready ? "ready" : clue ? "clued" : "locked";
    const statusText = done ? "已收录" : ready ? "现在可触发" : clue ? "线索已发现" : "还未发现";
    return {
      event,
      clue,
      done,
      ready,
      owned,
      lineId,
      priority,
      stateClass,
      statusText,
      stageLabel: rareSpiritStageLabel(event.event_stage),
      sourceText: rareSpiritClueSourceText(clue, event),
      nextAction: done
        ? "已经写进精怪生活图鉴，可去回看小剧场或继续养生态庭院。"
        : ready
          ? `去目标册点击“${event.event_stage === "first_meet" ? "触发初见" : "领取回礼"}”，把这段记忆落地。`
          : clue
            ? rareSpiritConditionHint(event)
            : rareSpiritConditionHint(event),
      rewardText: rareSpiritEventRewardText(event),
    };
  });
  return rows
    .sort((a, b) => a.priority - b.priority || Number(a.done) - Number(b.done) || String(a.event.entry_id).localeCompare(String(b.event.entry_id)))
    .slice(0, limit);
}

