function questStepsFor(quest, side = false) {
  const runtime = questRuntime();
  if (runtime) return runtime.questStepsFor(quest, side);
  const map = side ? data.sideQuestStepsByQuest : data.questStepsByQuest;
  return [...(map.get(quest.quest_id) || [])].sort((a, b) => Number(a.step_index) - Number(b.step_index));
}

function questTitle(quest) {
  return localize(quest.quest_name_key, quest.quest_id);
}

function targetName(targetId, objectiveType) {
  if (!targetId) return "目标";
  if (targetId === CHAPTER_4_DROUGHT_FLAG) return "九曜大旱世界状态";
  if (targetId.startsWith("npc_") || targetId.startsWith("spirit_")) return npcName(targetId);
  if (targetId.startsWith("boss_")) return bossName(targetId);
  if (targetId.startsWith("item_") || targetId.startsWith("seed_") || targetId.startsWith("crop_")) return itemName(targetId);
  if (targetId.startsWith("build_")) return buildingName(data.buildingsById.get(targetId)) || targetId;
  if (targetId.startsWith("area_")) return areaName(targetId);
  if (targetId.startsWith("event_")) return objectiveType === "defeat" ? "灾害/敌群" : targetId;
  if (targetId === "day_sleep") return "入夜结算";
  return targetId;
}

function stepProgress(step) {
  const runtime = questRuntime();
  if (runtime) return runtime.stepProgress(step);

  const target = step.target_id;
  const count = Number(step.target_count || 1);
  if (step.objective_type === "collect") {
    if (target === "item_gold_generic") return Math.min(count, state.gold || 0);
    const inventoryCount = Number(state.inventory[target] || 0);
    const cumulativeCount = Number(state.harvestCounts[`collect_${target}`] || 0);
    return Math.min(count, Math.max(inventoryCount, cumulativeCount));
  }
  if (step.objective_type === "harvest") {
    const harvested = Number(state.harvestCounts[target] || 0);
    const inventoryFallback = Number(state.inventory[target] || 0);
    return Math.min(count, Math.max(harvested, inventoryFallback));
  }
  if (step.objective_type === "plant") {
    if (target === CHAPTER_4_PANTAO_SEED_ID) {
      const crop = data.cropsBySeed.get(target);
      const planted = Number(state.harvestCounts[`plant_${target}`] || 0);
      const livePlots = state.plots.filter((plot) => plot.seedItemId === target || plot.cropId === crop?.crop_id).length;
      return Math.min(count, Math.max(planted, livePlots, state.completed.has(CHAPTER_4_PANTAO_PLANTED_FLAG) ? count : 0));
    }
    const planted = Number(state.harvestCounts[`plant_${target}`] || 0);
    const crop = data.cropsBySeed.get(target);
    const livePlots = target ? state.plots.filter((plot) => plot.seedItemId === target || plot.cropId === crop?.crop_id).length : 0;
    return Math.min(count, Math.max(planted, livePlots, state.completed.has("plant") ? count : 0));
  }
  if (step.objective_type === "sleep") return state.day > 1 ? count : 0;
  if (step.objective_type === "favor") return Math.min(count, favorLevel(state.npcFavor[target] || 0));
  if (step.objective_type === "talk") {
    if (state.activeDialogue.some((line) => line.speaker === npcName(target))) return count;
    return state.missionDone.size > 0 || state.npcFavor[target] > 0 ? count : 0;
  }
  if (step.objective_type === "enter_area") {
    if (target === CHAPTER_4_DROUGHT_FLAG) return chapter4DroughtActive() ? count : 0;
    if (target === "area_town_main") return state.missionDone.size > 0 || state.completed.has("shop") ? count : 0;
    if (state.completed.has(target)) return count;
    if (target.includes("dungeon") || target.includes("mine")) return state.completed.has("dungeon_enter") ? count : 0;
    return 0;
  }
  if (step.objective_type === "build") return state.builtBuildings.has(target) ? count : 0;
  if (step.objective_type === "craft") {
    if (state.inventory[target]) return Math.min(count, state.inventory[target]);
    return state.completed.has("craft") ? count : 0;
  }
  if (step.objective_type === "sell") {
    if (target.startsWith("order_")) return state.completedOrders.has(target) ? count : 0;
    if (target === "item_shop_category_3") return Math.min(count, Number(state.shopStats?.soldCount || 0));
    if (target === "item_shop_sales_total") return Math.min(count, Number(state.shopStats?.sales || 0));
    if (target.startsWith("item_shop_sales_total_")) return Math.min(count, Number(state.shopStats?.sales || 0));
    return Math.min(count, Number(state.shopStats?.itemSales?.[target] || 0));
  }
  if (step.objective_type === "defeat") {
    if (target.startsWith("boss_")) return state.defeatedBosses.has(target) ? count : 0;
    if (target === "event_pest_basic" && (state.completed.has("risk_pest") || state.resolvedRisks.has(target))) return count;
    return Math.min(count, state.resolvedRisks.size + state.dungeonClears.size);
  }
  return 0;
}

function stepLabel(step) {
  const verbs = {
    collect: "收集",
    harvest: "收获",
    plant: "播种",
    sleep: "入夜",
    favor: "好感",
    talk: "交谈",
    enter_area: "前往",
    build: "建造",
    craft: "制作",
    sell: "售卖",
    defeat: "处理",
  };
  const count = Number(step.target_count || 1);
  const current = stepProgress(step);
  if (step.objective_type === "favor") {
    return `${verbs[step.objective_type]} ${targetName(step.target_id, step.objective_type)} Lv.${Math.min(current, count)}/${count}`;
  }
  return `${verbs[step.objective_type] || step.objective_type} ${targetName(step.target_id, step.objective_type)} ${Math.min(current, count)}/${count}`;
}

function questProgress(quest, side = false) {
  const runtime = questRuntime();
  if (runtime) return runtime.questProgress(quest, side);

  const steps = questStepsFor(quest, side);
  const done = steps.filter((step) => stepProgress(step) >= Number(step.target_count || 1)).length;
  return { steps, done, total: steps.length };
}

function mainStoryQuestDone(quest) {
  const runtime = questRuntime();
  if (runtime) return runtime.mainStoryQuestDone(quest);

  if (!quest) return false;
  const progress = questProgress(quest);
  const allStepsDone = progress.total > 0 && progress.done >= progress.total;
  const demoMissionDone = DEMO_MISSIONS.some((mission) => mission.id === quest.quest_id) && state.missionDone.has(quest.quest_id);
  const specialDone = quest.quest_id === BAIZHI_QUEST_ID
    ? baizhiChapterFinished()
    : quest.quest_id === SPIRIT_MANOR_QUEST_ID
      ? state.builtBuildings.has(SPIRIT_MANOR_BUILDING_ID) || state.completed.has("spirit_manor_built")
      : quest.quest_id === FACTION_ORDER_QUEST_ID
        ? state.completed.has("chapter_3_complete") || state.defeatedBosses.has(FIRE_RUIN_BOSS_ID)
        : quest.quest_id === CHAPTER_4_DROUGHT_QUEST_ID
          ? chapter4DroughtReliefDelivered()
          : quest.quest_id === CHAPTER_4_LU_TRUTH_QUEST_ID
            ? state.completed.has(CHAPTER_4_FINAL_NEST_UNLOCK_FLAG) || hasItem(CHAPTER_4_DINGHAI_ITEM_ID, 1)
            : quest.quest_id === CHAPTER_4_PANTAO_QUEST_ID
              ? year2Unlocked() || state.completed.has("main_story_complete") || state.completed.has("final_banquet_complete")
              : false;
  return Boolean(
    state.claimedQuestRewards.has(quest.quest_id)
      || state.completed.has(quest.quest_id)
      || allStepsDone
      || demoMissionDone
      || specialDone,
  );
}

function mainStoryQuestStarted(quest) {
  const runtime = questRuntime();
  if (runtime) return runtime.mainStoryQuestStarted(quest);

  if (!quest) return false;
  const progress = questProgress(quest);
  return mainStoryQuestDone(quest)
    || progress.done > 0
    || state.missionDone.has(quest.quest_id)
    || state.completed.has(`quest_unlock_${quest.quest_id}`)
    || state.triggeredEvents.has(String(quest.quest_id || "").replace("quest_", "event_"));
}

