    second_dungeon: { selector: "#dungeonPanel", fallbackSelector: ".mission-story-compass", panelGroup: "systems", targetLabel: "第二秘境", routeHint: "看雾隐药谷或后续秘境解锁，确认机制、奖励和随行精怪。" },
