function scanConfiguredEvents(source = "runtime") {
  if (scanningConfiguredEvents) return 0;
  scanningConfiguredEvents = true;
  let triggered = 0;
  const runtime = questRuntime();
  if (runtime) {
    for (const candidate of runtime.configuredEventReadyQueue()) {
      if (executeConfiguredEvent(candidate.event, source)) triggered += 1;
    }
    scanningConfiguredEvents = false;
    return triggered;
  }
  const events = [...data.eventTriggers, ...data.sideQuestTriggers]
    .slice()
    .sort((a, b) => Number(b.priority || 0) - Number(a.priority || 0));
  for (const event of events) {
    if (event.repeatable !== "true" && state.triggeredEvents.has(event.event_id)) continue;
    if (event.quest_id && state.activeSideQuests.has(event.quest_id)) continue;
    const status = configuredTriggerReady(event);
    if (!status.ready) continue;
    if (executeConfiguredEvent(event, source)) triggered += 1;
  }
  scanningConfiguredEvents = false;
  return triggered;
}

function sideQuestVisible(quest) {
  const runtime = questRuntime();
  if (runtime) return runtime.sideQuestVisible(quest);
  const triggers = data.sideQuestTriggersByQuest.get(quest.quest_id) || [];
  if (state.activeSideQuests.has(quest.quest_id)) return true;
  if (quest.auto_accept === "true") return true;
  if (Number(quest.chapter || 0) <= 1 && state.fame >= 1) return true;
  return triggers.some((trigger) => configuredTriggerReady(trigger).ready);
}

function sideQuestClueForNpc(npcId = "", questId = "") {
  const runtime = questRuntime();
  if (runtime) return runtime.sideQuestClueForNpc(npcId, questId);
  const candidates = data.sideQuests
    .filter((quest) => (!questId || quest.quest_id === questId) && quest.issuer_id === npcId && !state.claimedQuestRewards.has(quest.quest_id))
    .map((quest) => {
      const triggers = data.sideQuestTriggersByQuest.get(quest.quest_id) || [];
      const trigger = triggers.find((entry) => entry.trigger_param === npcId) || triggers[0] || null;
      const triggerStatus = trigger ? configuredTriggerReady(trigger) : { param: true, condition: true, ready: true };
      const active = state.activeSideQuests.has(quest.quest_id) || quest.auto_accept === "true";
      const visible = active || sideQuestVisible(quest);
      const progress = questProgress(quest, true);
      const currentStep = progress.steps.find((step) => stepProgress(step) < Number(step.target_count || 1)) || progress.steps[progress.steps.length - 1] || null;
      const ready = Boolean(triggerStatus.ready || active || quest.auto_accept === "true");
      const rewardReady = questRewardReady(quest, true);
      const status = rewardReady
        ? "reward"
        : active
          ? "active"
          : ready
            ? "ready"
            : visible
              ? "visible"
              : "locked";
      return {
        quest,
        trigger,
        triggerStatus,
        active,
        visible,
        ready,
        rewardReady,
        status,
        progress,
        currentStep,
      };
    })
    .filter((entry) => entry.visible || entry.ready || entry.active)
    .sort((a, b) => {
      const stateScore = { reward: 60, active: 50, ready: 40, visible: 20, locked: 0 };
      return (stateScore[b.status] || 0) - (stateScore[a.status] || 0) || Number(b.quest.priority || 0) - Number(a.quest.priority || 0);
    });
  return candidates[0] || null;
}

function sideQuestClueStatusText(clue) {
  if (!clue) return "";
  if (clue.rewardReady) return "奖励可领";
  if (clue.active) return `已承接 · ${clue.progress.done}/${clue.progress.total || 0} 步`;
  if (clue.ready) return "可承接";
  if (clue.trigger) return `线索未满 · ${conditionLabel(clue.trigger.condition_group)}`;
  return "等待线索";
}

function formatSideQuestActionLabel(actionState = {}) {
  if (actionState.kind === "missing") return "推进支线";
  if (actionState.kind === "reward") return "领取奖励";
  if (actionState.kind === "accept") return "承接支线";
  if (actionState.kind === "done") return "查看收束";
  const labels = {
    talk: "去交谈",
    collect: String(actionState.targetId || "").startsWith("item_") ? "收集/调查" : "推进收集",
    build: "去建造",
    craft: "安排制作",
    sell: "去经营",
    defeat: "处理险情",
    harvest: "去收获",
    plant: "去播种",
    enter_area: "前往地点",
  };
  return labels[actionState.objectiveType] || "推进支线";
}

function formatSideQuestRouteActionLabel(actionState = {}) {
  if (actionState.kind === "missing") return "定位玩法入口";
  if (actionState.kind === "claimed") return "已完成";
  if (actionState.kind === "reward") return "定位领奖";
  if (actionState.kind === "accept") return "定位承接人";
  if (actionState.kind === "done") return "定位任务卡";
  const labels = {
    talk: "定位交谈",
    collect: "定位来源",
    build: "定位建造",
    craft: "定位配方",
    sell: "定位经营",
    defeat: "定位险情",
    harvest: "定位收获",
    plant: "定位播种",
    enter_area: "定位地点",
  };
  return labels[actionState.objectiveType] || "定位玩法入口";
}

function formatSideQuestRewardPreview(quest = null, rewardPoolId = "", rewards = []) {
  if (!quest?.complete_reward_group) return "回报：关系、声望或线索待配置";
  return rewards.length ? `回报：${rewards.join(" / ")}` : `回报池：${rewardPoolId}`;
}

function currentSideQuestStep(quest) {
  const runtime = questRuntime();
  if (runtime) return runtime.currentSideQuestStep(quest);
  if (!quest) return null;
  const progress = questProgress(quest, true);
  return progress.steps.find((step) => stepProgress(step) < Number(step.target_count || 1)) || null;
}

function acceptTownLifeSideQuest(npcId = "", questId = "") {
  const clue = sideQuestClueForNpc(npcId, questId);
  const acceptPlan = questRuntime()?.sideQuestAcceptPlan(npcId, questId) || (() => {
    if (!clue) return null;
    const fallbackTrigger = clue.trigger || null;
    const triggerReady = fallbackTrigger && !state.triggeredEvents.has(fallbackTrigger.event_id) && configuredTriggerReady(fallbackTrigger).ready;
    return {
      kind: clue.rewardReady || clue.active ? "track" : !clue.ready ? "locked" : triggerReady ? "start_from_trigger" : "start_direct",
      questId: clue.quest?.quest_id || "",
      npcId,
      trigger: fallbackTrigger,
      quest: clue.quest || null,
      currentStep: clue.currentStep || null,
      rewardReady: Boolean(clue.rewardReady),
      active: Boolean(clue.active),
      ready: Boolean(clue.ready),
      feedbackPhase: clue.rewardReady ? "finish" : clue.active ? "progress" : "accept",
      feedbackTiming: clue.rewardReady ? "after_complete" : clue.active ? "" : "after_accept",
      panelGroup: "core",
      shouldRender: true,
      shouldSaveSettings: clue.rewardReady || clue.active || clue.ready,
      shouldPlayCue: clue.ready && !clue.rewardReady && !clue.active,
      cue: "任务完成",
    };
  })();
  if (!clue || !acceptPlan || acceptPlan.kind === "missing") {
    addLog("支线线索", `${npcName(npcId)}这里暂时没有可承接的新旁事。`);
    render();
    return;
  }
  const { quest, trigger, currentStep } = acceptPlan;
  if (acceptPlan.kind === "track") {
    state.sideQuestFeedback = sideQuestFeedbackSpec(acceptPlan.questId, acceptPlan.feedbackPhase, acceptPlan.feedbackTiming, currentStep?.step_id || "", 0);
    settings.panelGroup = acceptPlan.panelGroup || "core";
    if (acceptPlan.shouldSaveSettings) saveSettings();
    addLog(acceptPlan.rewardReady ? "支线待领奖" : "支线追踪", `${questTitle(quest)} 已在任务面板高亮：${currentStep ? stepLabel(currentStep) : "等待下一步"}。`);
    render();
    return;
  }
  if (acceptPlan.kind === "locked") {
    const missing = trigger
      ? `${triggerReadable(trigger)}；条件 ${conditionLabel(trigger.condition_group)}`
      : "还没有匹配的支线触发器。";
    addLog("支线线索未满", `${questTitle(quest)} 暂时接不上：${missing}`);
    render();
    return;
  }
  let started = false;
  if (acceptPlan.kind === "start_from_trigger" && trigger) {
    started = executeConfiguredEvent(trigger, `town-life:${npcId}`);
  }
  if (!started) {
    state.activeSideQuests.add(acceptPlan.questId);
    const presented = triggerSideQuestPresentation(acceptPlan.questId, acceptPlan.feedbackTiming || "after_accept");
    state.sideQuestFeedback = sideQuestFeedbackSpec(acceptPlan.questId, acceptPlan.feedbackPhase || "accept", acceptPlan.feedbackTiming || "after_accept", "", presented);
    addLog("支线开启", `${npcName(npcId)}把「${questTitle(quest)}」托到了你手上。`);
  }
  settings.panelGroup = acceptPlan.panelGroup || "core";
  if (acceptPlan.shouldSaveSettings) saveSettings();
  if (acceptPlan.shouldPlayCue) playCue(acceptPlan.cue || "任务完成");
  render();
}

function sideQuestActionLabel(quest) {
  const runtime = questRuntime();
  if (runtime) return runtime.sideQuestActionLabel(quest);
  if (!quest) return "推进支线";
  if (questRewardReady(quest, true)) return "领取奖励";
  if (!state.activeSideQuests.has(quest.quest_id) && quest.auto_accept !== "true") return "承接支线";
  const step = currentSideQuestStep(quest);
  if (!step) return "查看收束";
  const labels = {
    talk: "去交谈",
    collect: step.target_id.startsWith("item_") ? "收集/调查" : "推进收集",
    build: "去建造",
    craft: "安排制作",
    sell: "去经营",
    defeat: "处理险情",
    harvest: "去收获",
    plant: "去播种",
    enter_area: "前往地点",
  };
  return labels[step.objective_type] || "推进支线";
}

function sideQuestRouteActionLabel(quest) {
  const runtime = questRuntime();
  if (runtime) return runtime.sideQuestRouteActionLabel(quest);
  if (!quest) return "定位玩法入口";
  if (state.claimedQuestRewards.has(quest.quest_id)) return "已完成";
  if (questRewardReady(quest, true)) return "定位领奖";
  if (!state.activeSideQuests.has(quest.quest_id) && quest.auto_accept !== "true") return "定位承接人";
  const step = currentSideQuestStep(quest);
  if (!step) return "定位任务卡";
  const labels = {
    talk: "定位交谈",
    collect: "定位来源",
    build: "定位建造",
    craft: "定位配方",
    sell: "定位经营",
    defeat: "定位险情",
    harvest: "定位收获",
    plant: "定位播种",
    enter_area: "定位地点",
  };
  return labels[step.objective_type] || "定位玩法入口";
}

function missionCropCodexRows() {
  const qingheQuest = data.sideQuests.find((entry) => entry.quest_id === "quest_side_0205_qinghe_pond") || null;
  const crop = data.cropsById.get("crop_luzhu_qin") || data.cropsBySeed.get("seed_luzhu_qin") || null;
  const seedOwned = Number(state.inventory.seed_luzhu_qin || 0);
  const cropOwned = Number(state.inventory.crop_luzhu_qin || 0);
  const plantedCount = state.plots.filter((plot) => plot.cropId === "crop_luzhu_qin").length;
  const waterPlots = state.plots.filter((plot) => !plot.debris && (plot.waterSoil || plot.newlyExpanded)).length;
  const farmSpiritCount = state.spirits.filter((spirit) => (spirit.job || "farm") === "farm").length;
  const pondControl = pondWaterControlUnlocked();
  const pondSpec = pondWaterLevelSpec(state.pondState.waterLevel);
  const progress = qingheQuest ? questProgress(qingheQuest, true) : { done: 0, total: 0 };
  const accepted = Boolean(qingheQuest && (state.activeSideQuests.has(qingheQuest.quest_id) || qingheQuest.auto_accept === "true"));
  const questDone = Boolean(qingheQuest && (state.claimedQuestRewards.has(qingheQuest.quest_id) || questRewardReady(qingheQuest, true) || progress.done >= progress.total && progress.total > 0));
  const ready = state.canalRepaired || seedOwned > 0 || cropOwned > 0 || plantedCount > 0 || accepted || questDone || waterPlots > 0;
  const done = questDone && (seedOwned > 0 || cropOwned > 0 || plantedCount > 0 || state.completed.has("recipe_recipe_water_crop_intro"));
  return [
    {
      key: "quest_crop_qinghe_luzhu_qin",
      questId: qingheQuest?.quest_id || "quest_side_0205_qinghe_pond",
      cropId: crop?.crop_id || "crop_luzhu_qin",
      seedId: crop?.seed_item_id || "seed_luzhu_qin",
      npcId: "npc_qinghe",
      cropName: cropName("crop_luzhu_qin"),
      questName: qingheQuest ? questTitle(qingheQuest) : "青禾池塘线",
      headline: qingheQuest
        ? `${questTitle(qingheQuest)} · ${progress.done}/${progress.total} 步`
        : "青禾的水生菜入口还在整理中",
      sourceText: state.canalRepaired
        ? "灵渠复流后会先放出露珠芹种子，灵池支线奖励再把水生菜入口讲清。"
        : "先把断桥与灵渠修起来，露珠芹和水润田才会真正露面。",
      termText: crop
        ? `春季主种 · 节气偏好 ${String(crop.solar_term_bonus_tags || "qingming|bailu").split("|").join(" / ")}`
        : "春季主种 · 清明 / 白露更合拍",
      soilText: waterPlots > 0
        ? `优先种在水润田或新水田，目前可用 ${waterPlots} 格。`
        : "先用修渠和灵池把水润田打开，再种这口带水气的嫩菜。",
      careText: pondControl
        ? `${pondSpec.label}最适合看这口菜。${pondSpec.level === 1 ? "平水最稳露珠芹收成，今夜也会替水生田续水。" : pondSpec.summary}`
        : `${farmSpiritCount > 0 ? `已有 ${farmSpiritCount} 位农田伙伴可接手照料。` : "先让一位精怪接上农田岗位。"}完成青禾池塘线后还能学会调水。`,
      taskText: qingheQuest
        ? `${questTitle(qingheQuest)} 当前 ${progress.done}/${progress.total} 步。${accepted ? "支线已承接，可顺着灵池与露珠芹继续走。" : "先和青禾谈话，把池塘支线接起来。"}`
        : "先看青禾关系卡和池塘线，再把露珠芹接到旧铺水鲜链上。",
      guideText: "把任务页需要的作物，拆成“来源 / 节气 / 土层 / 照看线索 / 实际入口”一页看懂，补上主线、支线与图鉴页的跳转闭环。",
      taskSafety: "只定位任务卡、图鉴条目、种子栏或精怪栏，不会自动播种、派工、推进时间或消耗资源。",
      npcSafety: "只定位支线卡、图鉴条目、种子栏或青禾关系卡，不会自动承接支线、播种、交付、推进时间或消耗资源。",
      stateClass: done ? "done" : ready ? "ready" : "pending",
    },
  ];
}

