function cutsceneFocusPoint(target = cutsceneFocusTarget(), width = 960, height = 640) {
  if (target.includes("festival") || target.includes("banquet")) return { x: width * 0.34, y: height * 0.78, tone: "gold" };
  if (target.includes("pantao")) return { x: width * 0.32, y: height * 0.72, tone: "gold" };
  if (target.includes("core_npc") || target.includes("npc_group")) return { x: width * 0.46, y: height * 0.64, tone: "earth" };
  if (target.includes("player_and_spirits")) return { x: width * 0.58, y: height * 0.66, tone: "jade" };
  if (target.includes("river") || target.includes("spring")) return { x: width * 0.78, y: height * 0.42, tone: "water" };
  if (target.includes("ending_panel") || target.includes("ui_ending")) return { x: width * 0.68, y: height * 0.5, tone: "gold" };
  if (target.includes("boss") || target.includes("nest") || target.includes("egg")) return { x: width * 0.62, y: height * 0.42, tone: "danger" };
  if (target.includes("array") || target.includes("solar")) return { x: width * 0.54, y: height * 0.3, tone: "gold" };
  if (target.includes("zhang") || target.includes("metal")) return { x: width * 0.64, y: height * 0.52, tone: "ember" };
  if (target.includes("qinghe") || target.includes("water") || target.includes("canal") || target.includes("pond")) return { x: width * 0.38, y: height * 0.48, tone: "water" };
  if (target.includes("baizhi") || target.includes("medicine") || target.includes("herb")) return { x: width * 0.66, y: height * 0.48, tone: "jade" };
  if (target.includes("xubo") || target.includes("bridge")) return { x: width * 0.28, y: height * 0.5, tone: "earth" };
  if (target.includes("hu_sihai") || target.includes("shelf") || target.includes("shop")) return { x: width * 0.25, y: height * 0.58, tone: "gold" };
   if (target.includes("farm") || target.includes("field")) return { x: width * 0.36, y: height * 0.58, tone: "earth" };
   if (target.includes("workshop") || target.includes("fire")) return { x: width * 0.66, y: height * 0.56, tone: "ember" };
   if (target.includes("training") || target.includes("guard") || target.includes("slope")) return { x: width * 0.62, y: height * 0.48, tone: "danger" };
   if (target.includes("storage") || target.includes("warehouse") || target.includes("crate")) return { x: width * 0.72, y: height * 0.54, tone: "earth" };
  if (target.includes("spirit")) return { x: width * 0.55, y: height * 0.64, tone: "jade" };
  if (target === "player") return { x: width * 0.5, y: height * 0.55, tone: "gold" };
  return { x: width * 0.5, y: height * 0.48, tone: "jade" };
}

function cutsceneCanvasSpec(width = 960, height = 640) {
  const active = state.activeCutscene;
  const shot = activeCutsceneShot();
  if (!active || !shot) return null;
  const target = cutsceneFocusTarget(shot);
  const point = cutsceneFocusPoint(target, width, height);
  const shotIndex = Number(active.kind === "side" ? shot.beat_index : shot.shot_index) || active.index + 1;
  const duration = Number(active.kind === "side" ? shot.duration_sec : shot.shot_duration_sec) || 0;
  const subtitle = localize(shot.subtitle_key, shot.subtitle_key || "");
  const title = active.kind === "side" ? `支线演出 ${active.id}` : cutsceneTitle(active.id);
  return {
    id: active.id,
    kind: active.kind,
    title,
    shot,
    shotIndex,
    duration,
    camera: shot.camera_type || "wide",
    target,
    focusLabel: targetName(target, target.startsWith("area_") ? "enter_area" : "talk"),
    actionLabel: cutsceneActionLabel(shot.action_key),
    subtitle: subtitle === shot.subtitle_key ? "" : subtitle,
    hook: shot.gameplay_hook || "",
    audioKey: shot.audio_key || "",
    point,
  };
}

function cutsceneWorldSlateCandidate() {
  if (state.activeCutscene || state.activeDialogue.length > 0 || state.dungeon && !state.dungeon.finished) return null;
  const mainCandidates = [...data.cutsceneShotsById.entries()]
    .map(([cutsceneId, shots], index) => {
      const sortedShots = shots.slice().sort((a, b) => Number(a.shot_index || 0) - Number(b.shot_index || 0));
      const shot = sortedShots[0];
      if (!shot) return null;
      const played = state.playedCutscenes.has(cutsceneId);
      const assets = data.cutsceneAssetsById.get(cutsceneId) || [];
      const score = (played ? 10 : 100)
        + (cutsceneId.includes("spirit") ? 24 : 0)
        + (cutsceneId.includes("final") ? 18 : 0)
        + (cutsceneId.includes("boss") ? 14 : 0)
        + Math.min(18, assets.length * 3)
        - index;
      return {
        id: cutsceneId,
        kind: "main",
        title: cutsceneTitle(cutsceneId),
        shot,
        shotCount: sortedShots.length,
        assetCount: assets.length,
        played,
        score,
      };
    })
    .filter(Boolean);
  const sideCandidates = [...data.sideCutsceneBeatsByMap.entries()]
    .map(([mapId, beats], index) => {
      const sortedBeats = beats.slice().sort((a, b) => Number(a.beat_index || 0) - Number(b.beat_index || 0));
      const beat = sortedBeats[0];
      if (!beat) return null;
      const played = state.playedCutscenes.has(mapId);
      const recentSide = state.sideQuestFeedback?.hasCutscene ? 34 : 0;
      const score = (played ? 8 : 92) + recentSide + Math.min(18, sortedBeats.length * 5) - index * 0.5;
      return {
        id: mapId,
        kind: "side",
        title: `支线演出 ${mapId}`,
        shot: beat,
        shotCount: sortedBeats.length,
        assetCount: 0,
        played,
        score,
      };
    })
    .filter(Boolean);
  return [...sideCandidates, ...mainCandidates].sort((a, b) => b.score - a.score)[0] || null;
}

function cutsceneWorldSlateRect(width = 960, height = 640) {
  const rectWidth = 354;
  const rectHeight = 132;
  const blockers = [
    { x: 44, y: 42, width: 326, height: 96 },
    rareSpiritWorldInvitationSpec()?.rect,
    rareSpiritClueRoadsignWorldSpec(width, height)?.rect,
    rareSpiritDailyStageWorldSpec(width, height)?.rect,
    dungeonMechanicWorldPreviewSpec()?.rect,
    dungeonMechanicWorldRouteSpec()?.rect,
    dungeonEntranceSilhouetteSpec(width, height)?.rect,
    dungeonSolarAtlasWorldSpec(width, height)?.rect,
  ].filter(Boolean);
  const overlap = (a, b) => a.x < b.x + b.width && a.x + a.width > b.x && a.y < b.y + b.height && a.y + a.height > b.y;
  const slots = [
    { x: width - rectWidth - 30, y: 52, width: rectWidth, height: rectHeight },
    { x: 38, y: height - rectHeight - 38, width: rectWidth, height: rectHeight },
    { x: width - rectWidth - 42, y: height - rectHeight - 54, width: rectWidth, height: rectHeight },
    { x: 388, y: 124, width: rectWidth, height: rectHeight },
  ];
  return slots.find((slot) => !blockers.some((blocker) => overlap(slot, blocker))) || slots[0];
}

function cutsceneWorldSlatePalette(tone = "jade", kind = "main") {
  const palettes = {
    gold: { accent: "#b47d2f", soft: "rgba(255, 248, 232, 0.93)", glow: "rgba(246, 240, 182, 0.26)", text: "#8f5f3f" },
    earth: { accent: "#8f5f3f", soft: "rgba(255, 248, 232, 0.93)", glow: "rgba(143, 95, 63, 0.18)", text: "#6b4a36" },
    water: { accent: "#4d91a6", soft: "rgba(232, 247, 250, 0.93)", glow: "rgba(77, 145, 166, 0.22)", text: "#2b6775" },
    jade: { accent: "#286f58", soft: "rgba(236, 248, 243, 0.93)", glow: "rgba(202, 235, 210, 0.24)", text: "#286f58" },
    ember: { accent: "#be4f37", soft: "rgba(255, 240, 232, 0.93)", glow: "rgba(190, 79, 55, 0.2)", text: "#8f3d2f" },
    danger: { accent: "#7f5570", soft: "rgba(248, 238, 248, 0.93)", glow: "rgba(126, 93, 150, 0.22)", text: "#5f3658" },
  };
  const base = palettes[tone] || palettes.jade;
  return kind === "side" ? { ...base, badge: "支" } : { ...base, badge: "镜" };
}

function cutsceneWorldSlateSpec(width = refs.world?.width || 960, height = refs.world?.height || 640) {
  const candidate = cutsceneWorldSlateCandidate();
  if (!candidate) return null;
  const target = cutsceneFocusTarget(candidate.shot);
  const point = cutsceneFocusPoint(target, width, height);
  const focusLabel = targetName(target, target.startsWith("area_") ? "enter_area" : "talk");
  const actionLabel = cutsceneActionLabel(candidate.shot.action_key);
  const audioKey = candidate.shot.audio_key || "";
  const audio = data.audioAssetsById.get(audioKey);
  const subtitle = localize(candidate.shot.subtitle_key, candidate.shot.subtitle_key || "");
  const rect = cutsceneWorldSlateRect(width, height);
  const palette = cutsceneWorldSlatePalette(point.tone, candidate.kind);
  const sourceLabel = candidate.kind === "side" ? "支线场记" : "主线场记";
  const statusLabel = candidate.played ? "可回看" : "未播放";
  const nodeWidth = 94;
  const nodeGap = 12;
  const nodeY = rect.y + 72;
  const nodeStartX = rect.x + 24;
  const nodes = [
    {
      key: "shot_focus",
      label: "镜头焦点",
      glyph: "镜",
      title: `${candidate.shot.camera_type || "wide"} · ${focusLabel}`,
      text: actionLabel,
      detail: `首镜头会看向 ${focusLabel}，动作是「${actionLabel}」。`,
      accent: palette.accent,
    },
    {
      key: "audio_emotion",
      label: "情绪音频",
      glyph: "声",
      title: audio ? `${audio.audio_type}/${audio.bus_id}` : audioCueFor(audioKey),
      text: candidate.shot.emotion_key || audioKey || "场景氛围",
      detail: audioKey ? `音频 key：${audioKey}，会走 ${audio?.bus_id || "默认"} 总线。` : "这段演出暂未绑定音频 key。",
      accent: candidate.kind === "side" ? "#4d91a6" : "#b47d2f",
    },
    {
      key: "gameplay_hook",
      label: "玩法钩子",
      glyph: "钩",
      title: candidate.shot.gameplay_hook || candidate.shot.skip_group || "回看入口",
      text: candidate.played ? "已收录" : `${candidate.shotCount} 镜头`,
      detail: candidate.shot.gameplay_hook || `共 ${candidate.shotCount} 段，可在剧情演出面板手动播放或跳过。`,
      accent: "#286f58",
    },
  ].map((node, index) => ({
    ...node,
    rect: {
      x: nodeStartX + index * (nodeWidth + nodeGap),
      y: nodeY,
      width: nodeWidth,
      height: 42,
    },
  }));
  return {
    id: "cutscene_world_slate",
    key: `${state.day}:${candidate.kind}:${candidate.id}:${statusLabel}:${state.playedCutscenes.size}`,
    title: "剧情场记牌 · 可点",
    subtitle: `${sourceLabel} · ${candidate.title} · ${statusLabel}`,
    note: "只定位演出面板，不自动播放",
    cutsceneId: candidate.id,
    kind: candidate.kind,
    statusLabel,
    shotCount: candidate.shotCount,
    assetCount: candidate.assetCount,
    firstSubtitle: subtitle === candidate.shot.subtitle_key ? "" : subtitle,
    selector: candidate.kind === "side"
      ? `[data-side-cutscene="${selectorDataValue(candidate.id)}"]`
      : `[data-cutscene-id="${selectorDataValue(candidate.id)}"]`,
    rect,
    point,
    palette,
    nodes,
  };
}

function cutsceneWorldSlateAtCanvasPoint(px, py) {
  const spec = cutsceneWorldSlateSpec();
  if (!spec?.rect) return null;
  const { rect } = spec;
  if (px < rect.x || px > rect.x + rect.width || py < rect.y || py > rect.y + rect.height) return null;
  const targetNode = spec.nodes.find((node) =>
    px >= node.rect.x && px <= node.rect.x + node.rect.width
    && py >= node.rect.y && py <= node.rect.y + node.rect.height,
  ) || spec.nodes[0];
  return { ...spec, targetNode };
}

function focusCutsceneWorldSlateFromCanvas(spec = cutsceneWorldSlateSpec()) {
  const node = spec?.targetNode || spec?.nodes?.[0] || null;
  if (!spec || !node) return false;
  cutsceneWorldSlateFocus = {
    day: state.day,
    key: spec.key,
    nodeKey: node.key,
    cutsceneId: spec.cutsceneId,
  };
  queueStoryCompassFocusTarget({
    selector: spec.selector,
    fallbackSelector: "#cutscenePanel",
    label: `点选剧情场记牌：${node.label}`,
    log: `${spec.subtitle} 已定位到剧情演出面板。「${node.label}」：${node.title}，${node.detail}。这里只定位和解释，不会自动播放演出、推进镜头、跳过演出、触发支线或消耗资源。`,
    panelGroup: "systems",
    missingTitle: "点选剧情场记牌",
    missingLog: "剧情场记牌已经点到，但演出卡暂时不可见。先打开系统深挖里的剧情演出面板查看镜头焦点、情绪音频和玩法钩子；不会自动播放演出、推进镜头、跳过演出、触发支线或消耗资源。",
  });
  return true;
}

function startCutscene(id, kind = "main") {
  const shots = kind === "side" ? (data.sideCutsceneBeatsByMap.get(id) || []) : cutsceneShots(id);
  if (shots.length === 0) return addLog("演出未配置", `${id} 没有镜头数据。`);
  state.activeDungeonMemoryPage = null;
  state.activeTownLifeMemoryPage = null;
  state.activeTownLifeShopMomentPage = null;
  state.activeCutscene = { id, kind, index: 0, startedDay: state.day };
  complete("cutscene_play");
  const first = kind === "side"
    ? shots.slice().sort((a, b) => Number(a.beat_index) - Number(b.beat_index))[0]
    : shots.slice().sort((a, b) => Number(a.shot_index) - Number(b.shot_index))[0];
  playCue(audioCueFor(first.audio_key), first.audio_key);
  addLog("演出开始", `${kind === "side" ? "支线演出" : cutsceneTitle(id)} 开始播放。`);
  render();
}

function advanceCutscene() {
  const current = state.activeCutscene;
  if (!current) return;
  const shot = activeCutsceneShot();
  const max = current.kind === "side" ? (data.sideCutsceneBeatsByMap.get(current.id) || []).length : cutsceneShots(current.id).length;
  if (!shot || current.index >= max - 1) {
    state.playedCutscenes.add(current.id);
    state.activeCutscene = null;
    complete("cutscene_complete");
    flushQueuedDialogueGroup();
    addLog("演出完成", `${current.kind === "side" ? current.id : cutsceneTitle(current.id)} 已播放完毕。`);
    render();
    return;
  }
  current.index += 1;
  const next = activeCutsceneShot();
  playCue(audioCueFor(next?.audio_key), next?.audio_key);
  render();
}

function skipActiveCutscene() {
  if (!state.activeCutscene) return skipCutscene();
  const id = state.activeCutscene.id;
  state.skippedCutscenes += 1;
  state.playedCutscenes.add(id);
  state.activeCutscene = null;
  complete("cutscene_skipped");
  flushQueuedDialogueGroup();
  addLog("跳过演出", `${cutsceneTitle(id)} 已跳过，相关任务旗标保留。`);
  render();
}

function updateMissions() {
  for (const mission of DEMO_MISSIONS) {
    if (state.missionDone.has(mission.id)) continue;
    const done = mission.required.every((id) => state.completed.has(id));
    if (!done) continue;

    state.missionDone.add(mission.id);
    showDialogue(mission.dialogueGroup);
    addLog("主线推进", `${localize(mission.nameKey, mission.id)} 已完成。`);
  }
}

function currentTermConfig() {
  const index = Math.floor((state.day - 1) / 3) % Math.max(data.solarTerms.length, 1);
  return data.solarTerms[index] || data.solarTermsById.get("term_lichun");
}

function weatherById(id, fallback = "weather_clear") {
  return data.weatherById.get(id) || data.weatherById.get(fallback) || data.weather[0] || {};
}

function pickWeatherForTerm(term) {
  if (chapter4DroughtActive()) return weatherById("weather_dry_heat");
  const group = term?.weather_weight_group || "";
  const dayMod = state.day % 3;
  if (group.includes("rain")) return weatherById(dayMod === 0 ? "weather_heavy_rain" : "weather_light_rain");
  if (group.includes("mist")) return weatherById("weather_mist");
  if (group.includes("dry")) return weatherById("weather_dry_heat");
  if (group.includes("hot")) return weatherById(dayMod === 0 ? "weather_dry_heat" : "weather_hot_wind");
  if (group.includes("dew")) return weatherById("weather_dew");
  if (group.includes("frost")) return weatherById("weather_frost");
  if (group.includes("snow")) return weatherById(group.includes("light") ? "weather_light_snow" : "weather_heavy_snow");
  if (group.includes("cold") || group.includes("extreme")) return weatherById(group.includes("extreme") ? "weather_extreme_cold" : "weather_cold_wind");
  if (group.includes("cloud")) return weatherById("weather_cloudy");
  return weatherById("weather_clear");
}

function currentWeatherConfig() {
  return weatherById(state.weatherId);
}

function currentTermId() {
  return currentTermConfig()?.term_id || "term_lichun";
}

function signedPercent(value) {
  const number = Number(value || 0);
  return `${number >= 0 ? "+" : ""}${Math.round(number * 100)}%`;
}

function multiplierText(value) {
  return `x${Number(value || 1).toFixed(2)}`;
}

function applyWeatherForDay(term = currentTermConfig()) {
  const weather = pickWeatherForTerm(term);
  state.weatherId = weather.weather_id;
  addLog("今日天气", `${localize(weather.weather_name_key, weather.weather_id)}：水分 ${signedPercent(weather.water_bonus)}，成长倍率 ${multiplierText(weather.crop_growth_modifier)}。`);
  return weather;
}

function riskKindFromEvent(event) {
  const text = `${event.event_id} ${event.event_name_key} ${event.execute_group}`.toLowerCase();
  if (text.includes("pest")) return "pest";
  if (text.includes("frost")) return "frost";
  if (text.includes("drought")) return "drought";
  return "term";
}

function riskTitle(kind) {
  const titles = {
    pest: "惊蛰虫害",
    frost: "霜降寒害",
    drought: "大暑干旱",
    term: "节气异动",
  };
  return titles[kind] || titles.term;
}

function riskActionLabel(kind) {
  const labels = {
    pest: "巡田驱虫",
    frost: "点火防霜",
    drought: "开渠保水",
    term: "稳定灵气",
  };
  return labels[kind] || labels.term;
}

function riskResolvedText(kind) {
  const texts = {
    pest: "虫害被压住，幼苗保住了。",
    frost: "火盆与灵水护住了田垄。",
    drought: "灵渠暂时蓄住了水气。",
    term: "节气异动已被安抚。",
  };
  return texts[kind] || texts.term;
}

function guideTextForTerm(termId, fallback) {
  const guide = (data.guideScriptsByTrigger.get(`on_term_change:${termId}`) || [])
    .sort((a, b) => Number(a.step_index) - Number(b.step_index))[0];
  return guide ? localize(guide.content_key, fallback) : fallback;
}

function patrolRiskGuardSpec(risk = unresolvedRisks()[0]) {
  const patrolLevel = spiritJobTaskEffectLevel("patrol");
  const patrolSpirits = state.spirits.filter((spirit) => spirit.job === "patrol");
  const cohabGuardBonus = cohabSharedBonusValue("night_guard") + cohabBuffValue("buff_night_guard_up");
  const ecologyGuardBonus = ecologyEffectValue("night_risk_reduce");
  const finale = spiritFinaleEffectSummary();
  const guardBonus = cohabGuardBonus + ecologyGuardBonus + finale.patrolGuardBonus;
  if (!risk) {
    return {
      state: "clear",
      label: "暂无险情",
      detail: patrolSpirits.length > 0 ? `${patrolSpirits[0].name} 正沿篱笆巡灯，等节气异动露头。` : "安排精怪到巡逻岗后，节气风险会更早被发现。",
    };
  }
  if (patrolLevel >= 5 || guardBonus >= 0.24) {
    return {
      state: "guarded",
      label: "巡夜可压下",
      detail: `巡逻灵纹足够强，入夜会直接化解${risk.title}${finale.patrolGuardBonus > 0 ? "，夜巡剑弧正在院门外压阵" : ""}。`,
    };
  }
  if (patrolLevel >= 3 || guardBonus >= 0.12 || patrolSpirits.length > 0) {
    return {
      state: "weaken",
      label: "巡夜可削弱",
      detail: `${patrolSpirits[0]?.name || "巡逻岗"}会先留下灯痕${finale.patrolGuardBonus > 0 ? "，夜巡剑弧也会补一层护线" : ""}，入夜损失会减轻。`,
    };
  }
  return {
    state: "manual",
    label: "建议手动处理",
    detail: `${risk.title} 入夜会伤田，当前巡逻岗还压不住。`,
  };
}

function spawnConfiguredRiskFromEvent(event, options = {}) {
  if (!event) return { risk: null, created: false };
  const termId = options.termId || event.trigger_param || currentTermId();
  const kind = options.kind || riskKindFromEvent(event);
  const existingRisk = state.activeRisks.find((risk) => !risk.resolved && (
    risk.eventId === event.event_id
      || (options.dedupeByKind && risk.kind === kind && risk.termId === termId)
  ));
  if (existingRisk) return { risk: existingRisk, created: false };

  const title = riskTitle(kind);
  const risk = {
    id: `${event.event_id}_${state.day}`,
    eventId: event.event_id,
    termId,
    kind,
    title,
    actionLabel: riskActionLabel(kind),
    severity: Number(options.severity || (kind === "pest" ? 3 : 2)),
    spawnedDay: state.day,
    expiresDay: state.day + Number(options.expiresInDays || 1),
    resolved: false,
    guide: options.guide || guideTextForTerm(termId, `${title} 已出现，请在入夜前处理。`),
  };

  state.activeRisks.unshift(risk);
  state.activeRisks = state.activeRisks.slice(0, 6);
  state.triggeredEvents.add(event.event_id);
  addLog("节气风险", `${risk.title}：${risk.guide}`);
  return { risk, created: true };
}

function spawnTermRisks(term) {
  if (!term) return;
  const events = data.eventTriggers
    .filter((event) => event.trigger_type === "on_term_change")
    .filter((event) => event.trigger_param === term.term_id)
    .filter((event) => conditionMet(event.condition_group))
    .filter((event) => (event.execute_group || "").includes("warn") || (event.execute_group || "").includes("disaster"));

  for (const event of events) {
    if (event.repeatable !== "true" && state.triggeredEvents.has(event.event_id)) continue;
    const result = spawnConfiguredRiskFromEvent(event, {
      termId: term.term_id,
      dedupeByKind: riskKindFromEvent(event) === "pest",
    });
    if (!result.created) continue;
    executeConfiguredEvent(event, "term-risk");
  }
}

function unresolvedRisks() {
  return state.activeRisks.filter((risk) => !risk.resolved);
}

function recordResolvedRisk(risk) {
  if (!risk) return;
  state.resolvedRisks.add(risk.eventId);
  if (risk.kind === "pest") {
    state.resolvedRisks.add("event_pest_basic");
    complete("risk_pest");
    return;
  }
  complete("risk_term");
}

function resolveRisk(riskId) {
  const risk = state.activeRisks.find((entry) => entry.id === riskId);
  if (!risk) return addLog("风险已散", "这条节气风险已经不在当前田里。");
  if (risk.resolved) return addLog("风险已处理", riskResolvedText(risk.kind));
  if (!spendStamina(8 + risk.severity * 2)) return;

  risk.resolved = true;
  risk.resolvedDay = state.day;
  recordResolvedRisk(risk);
  state.fame += risk.kind === "pest" ? 1 : 0;
  recordDailyIntentProgress("field", `处理 ${risk.title}`, {
    amount: 2 + Number(risk.severity || 1),
    rewardText: risk.kind === "pest" ? "稳住田垄 · 声望 +1" : "稳住田垄 · 避免入夜惩罚",
    target: `risk:${risk.id}`,
  });
  pulseAtSelected("risk");
  playCue(risk.kind === "pest" ? "精怪工作" : "浇水");
  addLog("风险处理", riskResolvedText(risk.kind));
  render();
}

function applyRiskPenalty(risk) {
  const planted = state.plots.filter((plot) => plot.cropId);
  const weakened = !!risk.weakened;
  if (planted.length === 0) {
    addLog("风险掠过", `${risk.title} 没有找到可伤的作物，但镇上记住了这次天时。`);
    return;
  }

  if (risk.kind === "pest") {
    const damaged = planted.slice(0, Math.min(Math.max(1, Number(risk.severity || 1) - (weakened ? 1 : 0)), planted.length));
    for (const plot of damaged) plot.watered = false;
    state.fame = Math.max(0, state.fame - 1);
    addLog(weakened ? "虫害受控" : "虫害蔓延", weakened ? `${damaged.length} 块灵田仍被虫气惊扰，但巡夜灯痕替你拦下了一部分，声望 -1。` : `${damaged.length} 块灵田受扰，水气散了，声望 -1。`);
  } else if (risk.kind === "frost") {
    const damaged = planted.slice(0, Math.min(weakened ? 1 : 2, planted.length));
    for (const plot of damaged) plot.plantedDay = Math.max(1, plot.plantedDay + 1);
    addLog(weakened ? "霜气已缓" : "霜寒压苗", weakened ? `${damaged.length} 块作物仍被霜气擦过，但成长只被拖慢了 1 天。` : `${damaged.length} 块作物成长被拖慢 1 天。`);
  } else if (risk.kind === "drought") {
    const damaged = weakened ? planted.slice(0, Math.ceil(planted.length / 2)) : planted;
    for (const plot of damaged) plot.watered = false;
    state.stamina = Math.max(weakened ? 50 : 45, state.stamina - (weakened ? 6 : 12));
    addLog(weakened ? "旱气被截" : "旱气逼田", weakened ? `${damaged.length} 块灵田的水气仍被抽走，但巡夜灯替你拦下一半旱意。` : "所有灵田水分被抽干，明日体力恢复受损。");
  } else {
    state.stamina = Math.max(weakened ? 55 : 50, state.stamina - (weakened ? 4 : 8));
    addLog(weakened ? "紊乱已缓" : "节气紊乱", weakened ? "未处理的灵气扰动仍在，但巡夜灯痕替你压住了一半波动。" : "未处理的灵气扰动让你多耗了一些体力。");
  }
}

function riskFailureCompensationSpec(risk = {}) {
  const severity = Math.max(1, Number(risk.severity || 1));
  const weakened = !!risk.weakened;
  const profiles = {
    pest: {
      title: "虫路见闻",
      insight: "虫害退去后，田埂边留下了一串虫路。下次惊蛰前先巡田驱虫，能更早压住虫气。",
      nextHint: "下次处理：安排巡逻岗或入夜前巡田驱虫。",
      rewardItemId: "item_material_clean_water",
      rewardCount: weakened ? 1 : Math.min(2, severity),
      spirit: 1,
      accent: "#be4f37",
      glyph: "虫",
    },
    frost: {
      title: "霜纹见闻",
      insight: "霜寒在叶背结成细纹，火盆位置也被记下来了。下次霜降前点火防霜更省体力。",
      nextHint: "下次处理：提前点火防霜，巡夜灯痕可减轻冻苗。",
      rewardItemId: "item_stone_spirit_shard",
      rewardCount: 1,
      spirit: weakened ? 1 : 2,
      accent: "#4d91a6",
      glyph: "霜",
    },
    drought: {
      title: "水脉见闻",
      insight: "旱气抽干水分时露出了一道旧水脉。下次大暑前开渠保水，可以少丢一夜水气。",
      nextHint: "下次处理：提前开渠保水，净水和巡逻岗都能托底。",
      rewardItemId: "item_material_clean_water",
      rewardCount: weakened ? 1 : 2,
      spirit: 1,
      accent: "#b47d2f",
      glyph: "水",
    },
    term: {
      title: "天时见闻",
      insight: "紊乱灵气散开后，洞天记住了这次节气脉冲。下次节气更替时，先稳定灵气会少耗体力。",
      nextHint: "下次处理：节气更替当天优先稳定灵气。",
      rewardItemId: "",
      rewardCount: 0,
      spirit: weakened ? 1 : 2,
      accent: "#286f58",
      glyph: "时",
    },
  };
  const profile = profiles[risk.kind] || profiles.term;
  const rewardText = [
    profile.rewardItemId && profile.rewardCount > 0 ? `${itemName(profile.rewardItemId)} x${profile.rewardCount}` : "",
    profile.spirit > 0 ? `洞天灵息 +${profile.spirit}` : "",
    weakened ? "巡夜削弱已生效" : "失败见闻已记录",
  ].filter(Boolean).join(" · ");
  return {
    title: profile.title,
    insight: profile.insight,
    nextHint: profile.nextHint,
    rewardItemId: profile.rewardItemId,
    rewardCount: profile.rewardCount,
    spirit: profile.spirit,
    rewardText,
    accent: profile.accent,
    glyph: profile.glyph,
    weakened,
  };
}

function triggerRiskCompensationFeedback(summary = {}) {
  state.riskCompensationFeedback = {
    ...summary,
    createdAt: performance.now(),
    duration: Number(summary.duration || 6200),
  };
}

function applyRiskFailureCompensation(risk = {}) {
  const compensation = riskFailureCompensationSpec(risk);
  if (compensation.rewardItemId && compensation.rewardCount > 0) addItem(compensation.rewardItemId, compensation.rewardCount);
  if (compensation.spirit > 0) state.grottoSpirit = Number(state.grottoSpirit || 0) + compensation.spirit;
  risk.compensation = {
    title: compensation.title,
    insight: compensation.insight,
    nextHint: compensation.nextHint,
    rewardText: compensation.rewardText,
    rewardItemId: compensation.rewardItemId,
    rewardCount: compensation.rewardCount,
    spirit: compensation.spirit,
    weakened: compensation.weakened,
  };
  triggerRiskCompensationFeedback({
    riskTitle: risk.title,
    title: compensation.title,
    insight: compensation.insight,
    nextHint: compensation.nextHint,
    rewardText: compensation.rewardText,
    accent: compensation.accent,
    glyph: compensation.glyph,
    weakened: compensation.weakened,
  });
  recordFailureCodexEntry({
    id: `failure_risk_${risk.id || risk.type || state.day}`,
    type: "risk",
    sourceId: risk.id || risk.type || "",
    title: compensation.title,
    headline: `${risk.title || "节气风险"}留下了处理线索`,
    problem: risk.title || "入夜风险未能完全处理",
    insight: compensation.insight,
    nextAction: compensation.nextHint,
    support: compensation.rewardText,
    rewardText: compensation.rewardText,
    tone: compensation.weakened ? "soft" : "learn",
    icon: compensation.glyph || "险",
  });
  addLog("失败见闻", `${risk.title} 已结算，但洞天留下${compensation.title}：${compensation.rewardText}。${compensation.nextHint}`);
  return compensation;
}

function settleUnresolvedRisks() {
  const patrolLevel = spiritJobTaskEffectLevel("patrol");
  const cohabGuardBonus = cohabSharedBonusValue("night_guard") + cohabBuffValue("buff_night_guard_up");
  const ecologyGuardBonus = ecologyEffectValue("night_risk_reduce");
  const finale = spiritFinaleEffectSummary();
  const guardBonus = cohabGuardBonus + ecologyGuardBonus + finale.patrolGuardBonus;
  const guardedRisk = unresolvedRisks()[0];
  if (guardedRisk && (patrolLevel >= 5 || guardBonus >= 0.24)) {
    guardedRisk.resolved = true;
    guardedRisk.resolvedDay = state.day;
    guardedRisk.guardedByPatrol = true;
    state.resolvedRisks.add(guardedRisk.eventId);
    addLog("巡夜灯守成", `${guardedRisk.title} 被岗位灵纹提前压下，今夜没有再扩散。${cohabGuardBonus > 0 ? "同住护院也替你盯住了院门。" : ""}${ecologyGuardBonus > 0 ? "灯影长明盏把夜路照亮，险情更早被看见了。" : ""}${finale.patrolGuardBonus > 0 ? "夜巡剑弧把院门外最后一段风声也截住了。" : ""}`);
  } else if (guardedRisk && (patrolLevel >= 3 || guardBonus >= 0.12)) {
    guardedRisk.weakened = true;
    guardedRisk.weakenedByPatrol = true;
    addLog("巡夜灯留痕", `${guardedRisk.title} 被岗位灵纹削弱，今夜损失会减轻。${cohabGuardBonus > 0 ? "沈孤灯的护场提醒也起了作用。" : ""}${ecologyGuardBonus > 0 ? "灯影留下的长灯也帮你提早看见了风吹草动。" : ""}${finale.patrolGuardBonus > 0 ? "夜巡剑弧也补上了一圈护线。" : ""}`);
  }
  for (const risk of unresolvedRisks()) {
    if (risk.expiresDay >= state.day) {
      applyRiskPenalty(risk);
      applyRiskFailureCompensation(risk);
    }
    risk.resolved = true;
    risk.failed = true;
  }
  state.activeRisks = state.activeRisks.slice(0, 6);
}

function applySolarTerm() {
  const term = currentTermConfig();
  if (!term) return;
  const termName = localize(term.term_name_key, state.term);
  const changed = state.term !== termName;
  state.term = termName;
  applyWeatherForDay(term);
  if (changed) {
    addLog("节气更替", `${termName}：${term.crop_bonus_tags || "灵气流转"}，市闻偏向 ${term.market_bonus_tags || "基础商品"}。`);
    spawnTermRisks(term);
    playCue("节气钟声");
  }
}

function skipCutscene() {
  if (state.activeCutscene) {
    const id = state.activeCutscene.id;
    state.skippedCutscenes += 1;
    state.playedCutscenes.add(id);
    state.activeCutscene = null;
    complete("cutscene_skipped");
    flushQueuedDialogueGroup();
    addLog("跳过演出", `${cutsceneTitle(id)} 已跳过，任务旗标和奖励状态保留。`);
    render();
    return;
  }
  state.skippedCutscenes += 1;
  state.activeDialogue = [];
  if (flushQueuedDialogueGroup()) {
    addLog("对白继续", "当前对话已关闭，下一段待播对白已经接上。");
  } else {
    addLog("跳过演出", "当前对话已跳过，任务旗标和奖励状态保留。");
  }
  render();
}

function applyCaptureScene(sceneId) {
  const scene = CAPTURE_SCENES[sceneId] || CAPTURE_SCENES.start;
  state.currentCaptureScene = sceneId;

  if (sceneId === "spirit" && state.spirits.length === 0) unlockSpirit();
  if (sceneId === "shop") {
    addItem("item_food_bailuobo_tang", 2);
    state.shopReport = [{ name: "村民", text: "买走白萝卜汤，成交 30 灵石。" }];
    complete("shop");
  }
  if (sceneId === "term") {
    state.day = 7;
    applySolarTerm();
  }

  addLog(scene.label, scene.log);
  render();
}

function exportCurrentPng() {
  const scene = CAPTURE_SCENES[state.currentCaptureScene] || CAPTURE_SCENES.start;
  try {
    const link = document.createElement("a");
    link.download = `xiannong-${state.currentCaptureScene}-day-${state.day}.png`;
    link.href = refs.world.toDataURL("image/png");
    link.click();
    addLog("截图导出", `${scene.label} 已导出为 PNG。`);
  } catch (error) {
    recordError("export_png", error);
    addLog("截图导出失败", error.message);
  }
  render();
}

function storeAssetEvidenceSpec() {
  const screenshotPlans = data.steamAssets
    .filter((asset) => asset.asset_type === "screenshot" && asset.priority === "P0")
    .slice(0, 8);
  const videoPlans = data.steamAssets
    .filter((asset) => ["trailer", "short_video"].includes(asset.asset_type))
    .slice(0, 3);
  const captureByLabel = new Map(Object.values(CAPTURE_SCENES).map((scene) => [scene.label, scene]));
  const steamReadyScreenshots = STEAM_READY_ASSETS.filter((asset) => asset.type === "screenshot");
  const rows = screenshotPlans.map((plan, index) => {
    const capture = captureByLabel.get(plan.asset_name) || Object.values(CAPTURE_SCENES)[index] || null;
    const readyAsset = steamReadyScreenshots.find((asset) => asset.label === plan.asset_name) || null;
    return {
      id: plan.asset_plan_id,
      label: plan.asset_name,
      capture: plan.required_capture,
      sellingPoint: plan.acceptance_criteria,
      source: plan.content_source,
      asset: capture?.asset || readyAsset?.path || "",
      readyPath: readyAsset?.path || "",
      ready: Boolean(capture && readyAsset),
    };
  });
  const sellingPointCount = new Set(rows.map((row) => row.sellingPoint).filter(Boolean)).size;
  const readyCount = rows.filter((row) => row.ready).length;
  const videoRows = videoPlans.map((plan, index) => ({
    id: plan.asset_plan_id,
    label: plan.asset_name,
    capture: plan.required_capture,
    duration: plan.acceptance_criteria,
    step: index + 1,
  }));
  return {
    title: "vsa_010 素材清单证据牌",
    subtitle: "核心循环截图和短视频 · 素材清单",
    acceptanceText: "至少6张截图能表达卖点",
    pass: readyCount >= 6 && sellingPointCount >= 6,
    readyCount,
    totalCount: rows.length,
    sellingPointCount,
    rows,
    videoRows,
    runbook: "短视频节奏：从荒田开局 -> 作物成精 -> 精怪代劳 -> 加工订单 -> 旧铺成交 -> 洞天修复/秘境/终章目标。",
    safeNote: "当前素材为项目自有程序化 SVG/PNG 占位，只用于 Demo 素材评审；正式上架前必须由最终可执行文件捕获真实实机截图、正式 key art 和 PV 替换。",
  };
}

function storeAssetEvidenceMarkup(spec = storeAssetEvidenceSpec()) {
  const rows = spec.rows.map((row) => `
    <figure class="asset-evidence-shot ${row.ready ? "ready" : "warn"}">
      ${row.asset ? `<img src="${assetSrc(row.asset)}" alt="${row.label}" loading="lazy" />` : ""}
      <figcaption>
        <strong>${row.label}</strong>
        <span>${row.sellingPoint}</span>
        <small>${row.capture}</small>
      </figcaption>
    </figure>
  `).join("");
  const videos = spec.videoRows.map((row) => `
    <div class="asset-evidence-video">
      <em>${row.step}</em>
      <span><b>${row.label}</b><small>${row.capture} · ${row.duration}</small></span>
    </div>
  `).join("");
  return `
    <section class="asset-evidence-card ${spec.pass ? "pass" : "warn"}">
      <div class="asset-evidence-head">
        <span>
          <strong>${spec.title}</strong>
          <small>${spec.subtitle}</small>
        </span>
        <em>${spec.acceptanceText}</em>
      </div>
      <div class="asset-evidence-score">
        <b>${spec.readyCount}/${spec.totalCount}</b>
        <span>截图可用 · 卖点覆盖 ${spec.sellingPointCount} 类</span>
      </div>
      <div class="asset-evidence-grid">${rows}</div>
      <div class="asset-evidence-video-strip">
        <strong>短视频/PV 剪辑线</strong>
        ${videos}
      </div>
      <small class="asset-evidence-safe">${spec.runbook} ${spec.safeNote}</small>
    </section>
  `;
}

function addItem(itemId, count) {
  state.inventory[itemId] = (state.inventory[itemId] || 0) + count;
  if (Number(count) > 0) {
    state.harvestCounts[`collect_${itemId}`] = Number(state.harvestCounts[`collect_${itemId}`] || 0) + Number(count || 0);
    recordShopRestockItemProgress(itemId, count);
  }
  if (state.inventory[itemId] <= 0) delete state.inventory[itemId];
}

function hasItem(itemId, count) {
  return (state.inventory[itemId] || 0) >= count;
}

function splitTags(value = "") {
  return value.split("|").map((tag) => tag.trim()).filter(Boolean);
}

function percentText(value) {
  return `${Math.round(Number(value || 0) * 100)}%`;
}

function conditionGroupFor(id = "") {
  return data.conditionGroupsById.get(id);
}

function conditionExpressionFor(id = "") {
  return conditionGroupFor(id)?.expression || "";
}

function splitConditionArgs(value = "") {
  const args = [];
  let depth = 0;
  let token = "";
  for (const char of value) {
    if (char === "," && depth === 0) {
      args.push(token.trim());
      token = "";
      continue;
    }
    if (char === "(") depth += 1;
    if (char === ")") depth = Math.max(0, depth - 1);
    token += char;
  }
  if (token.trim()) args.push(token.trim());
  return args;
}

function questStateMatches(questId, expected) {
  const runtime = questRuntime();
  if (runtime) return runtime.questStateMatches(questId, expected);

  const progressForQuest = (quest, side = false) => {
    if (!quest) return null;
    const progress = questProgress(quest, side);
    const done = progress.total > 0 && progress.done >= progress.total;
    const started = progress.done > 0
      || state.missionDone.has(questId)
      || state.completed.has(questId)
      || state.completed.has(`quest_unlock_${questId}`)
      || (side && state.activeSideQuests.has(questId));
    return { done, started, progress };
  };
  const main = progressForQuest(data.quests.find((quest) => quest.quest_id === questId));
  const side = progressForQuest(data.sideQuests.find((quest) => quest.quest_id === questId), true);
  const live = main || side;
  const completed = state.claimedQuestRewards.has(questId) || state.completed.has(questId) || state.missionDone.has(questId) || Boolean(live?.done);
  if (expected === "complete") return completed;
  if (expected === "ready_submit") return completed || Boolean(live && live.progress.done >= Math.max(1, live.progress.total - 1));
  if (expected === "active") return completed || Boolean(live?.started) || hasCoreLoop();
  return false;
}

function questStepDone(stepId) {
  const runtime = questRuntime();
  if (runtime) return runtime.questStepDone(stepId);

  const step = [...data.questSteps, ...data.sideQuestSteps].find((entry) => entry.step_id === stepId);
  return Boolean(step && stepProgress(step) >= Number(step.target_count || 1));
}

function questStepStateMatches(stepId, expected) {
  const done = questStepDone(stepId);
  if (expected === "complete" || expected === "done") return done;
  if (expected === "active") return done || state.day > 0;
  return false;
}

function hasSpiritLine(lineId) {
  return state.spirits.some((spirit) => (spirit.lineId || spiritLine(spirit.id)) === lineId)
    || (lineId === "spirit_line_luobo" && state.spirits.length > 0);
}

function ecologyComboRankCount(rank) {
  const targetRank = String(rank || "").toLowerCase();
  return data.spiritEcologyCombos.filter((combo) =>
    ecologyComboActive(combo) && String(combo.combo_rank || "").toLowerCase() === targetRank,
  ).length;
}

function selectedSpiritBondAverage() {
  if (!state.spirits.length) return 0;
  const total = state.spirits.reduce((sum, spirit) => sum + Number(spirit.bondLevel || 1), 0);
  return total / state.spirits.length;
}

function firstHarvested(cropId) {
  if (cropId === "crop_lingqi_bailuobo") return state.completed.has("harvest") || hasItem("item_crop_lingqi_bailuobo", 1);
  const crop = data.crops.find((entry) => entry.crop_id === cropId);
  return crop ? Object.keys(state.inventory).some((itemId) => itemId.includes(crop.crop_id.replace("crop_", ""))) : false;
}

function evaluateConditionExpression(expression = "", seen = new Set()) {
  const expr = String(expression || "").trim();
  if (!expr) return { pass: false, supported: false, reason: "empty expression" };
  if (expr === "true") return { pass: true, supported: true, reason: "always true" };
  if (expr === "false") return { pass: false, supported: true, reason: "always false" };

  const allOf = expr.match(/^all_of\((.*)\)$/);
  if (allOf) {
    const args = splitConditionArgs(allOf[1]);
    if (args.length === 0) return { pass: false, supported: false, reason: "all_of has no arguments" };
    const results = args.map((arg) =>
      data.conditionGroupsById.has(arg) ? conditionGroupStatus(arg, seen) : evaluateConditionExpression(arg, seen),
    );
    const unsupported = results.find((result) => !result.supported);
    if (unsupported) return { pass: false, supported: false, reason: `all_of unsupported: ${unsupported.reason}` };
    return {
      pass: results.every((result) => result.pass),
      supported: true,
      reason: results.map((result) => result.reason).join(" + "),
    };
  }

  const countMatch = expr.match(/^count\(([^)]+)\)>=(\d+)$/);
  if (countMatch) {
    const itemId = countMatch[1].trim();
    const target = Number(countMatch[2] || 0);
    return { pass: hasItem(itemId, target), supported: true, reason: `${itemName(itemId)} ${state.inventory[itemId] || 0}/${target}` };
  }

  const itemMatch = expr.match(/^has_item\(([^,()]+),(\d+)\)$/);
  if (itemMatch) {
    const itemId = itemMatch[1].trim();
    const target = Number(itemMatch[2] || 0);
    return { pass: hasItem(itemId, target), supported: true, reason: `${itemName(itemId)} ${state.inventory[itemId] || 0}/${target}` };
  }

  const firstHarvestMatch = expr.match(/^first_harvest\(([^)]+)\)$/);
  if (firstHarvestMatch) {
    const cropId = firstHarvestMatch[1].trim();
    return { pass: firstHarvested(cropId), supported: true, reason: `${cropId} first harvest` };
  }

  const dayMatch = expr.match(/^player_day>=(\d+)$/);
  if (dayMatch) {
    const target = Number(dayMatch[1] || 0);
    return { pass: state.day >= target, supported: true, reason: `day ${state.day}/${target}` };
  }

  const chapterMatch = expr.match(/^chapter_reached>=(\d+)$/);
  if (chapterMatch) {
    const target = Number(chapterMatch[1] || 0);
    return { pass: state.missionDone.size >= target || state.completed.has("dungeon"), supported: true, reason: `chapter proxy ${state.missionDone.size}/${target}` };
  }

  const reputationMatch = expr.match(/^shop_reputation>=(\d+)$/);
  if (reputationMatch) {
    const target = Number(reputationMatch[1] || 0);
    const score = shopReputationScore();
    return { pass: score >= target, supported: true, reason: `shop reputation ${score}/${target}` };
  }

  const currentTermMatch = expr.match(/^current_term==([a-z0-9_]+)$/i);
  if (currentTermMatch) {
    const termId = currentTermMatch[1].trim();
    return { pass: currentTermId() === termId, supported: true, reason: `${currentTermId()} == ${termId}` };
  }

  const dungeonClearMatch = expr.match(/^dungeon_clear\(([^)]+)\)$/);
  if (dungeonClearMatch) {
    const areaId = dungeonClearMatch[1].trim();
    const dungeon = data.dungeonsById.get(areaId);
    return { pass: state.dungeonClears.has(areaId), supported: true, reason: `${dungeonName(dungeon) || areaId} cleared` };
  }

  const favorMatch = expr.match(/^npc_favor_level\(([^)]+)\)>=(\d+)$/);
  if (favorMatch) {
    const npcId = favorMatch[1].trim();
    const target = Number(favorMatch[2] || 0);
    const liveLevel = favorLevel(state.npcFavor[npcId] || 0);
    const demoProxy = target <= 3 && (state.completed.has("spirit_expedition") || state.completed.has("repair"));
    return { pass: liveLevel >= target || demoProxy, supported: true, reason: `${npcName(npcId)} Lv.${liveLevel}/${target}` };
  }

  const questStateMatch = expr.match(/^quest_state\(([^)]+)\)==([a-z_]+)$/i);
  if (questStateMatch) {
    const questId = questStateMatch[1].trim();
    const expected = questStateMatch[2].trim();
    if (questId === "quest_main_0403_pantao_dayan" && expected === "complete") {
      return { pass: year2Unlocked(), supported: true, reason: `${questTitle(data.quests.find((quest) => quest.quest_id === questId) || { quest_id: questId })} complete` };
    }
    return { pass: questStateMatches(questId, expected), supported: true, reason: `${questTitle(data.quests.find((quest) => quest.quest_id === questId) || data.sideQuests.find((quest) => quest.quest_id === questId) || { quest_id: questId })} ${expected}` };
  }

  const questStepDoneMatch = expr.match(/^quest_step_done\(([^)]+)\)$/);
  if (questStepDoneMatch) {
    const stepId = questStepDoneMatch[1].trim();
    return { pass: questStepDone(stepId), supported: true, reason: `${stepId} done` };
  }

  const questStepStateMatch = expr.match(/^quest_step_state\(([^)]+)\)==([a-z_]+)$/i);
  if (questStepStateMatch) {
    const stepId = questStepStateMatch[1].trim();
    const expected = questStepStateMatch[2].trim();
    return { pass: questStepStateMatches(stepId, expected), supported: true, reason: `${stepId} ${expected}` };
  }

  const bossMatch = expr.match(/^boss_defeated\(([^)]+)\)$/);
  if (bossMatch) {
    const bossId = bossMatch[1].trim();
    return { pass: state.defeatedBosses.has(bossId), supported: true, reason: `${bossName(bossId)} defeated` };
  }

  const flagMatch = expr.match(/^flag\(([^)]+)\)==true$/);
  if (flagMatch) {
    const flag = flagMatch[1].trim();
    return { pass: state.completed.has(flag) || state.triggeredEvents.has(flag) || state.spiritMemoryFlags.has(flag), supported: true, reason: `${flag} flag` };
  }

  const spiritLineMatch = expr.match(/^has_spirit_line\(([^)]+)\)$/);
  if (spiritLineMatch) {
    const lineId = spiritLineMatch[1].trim();
    return { pass: hasSpiritLine(lineId), supported: true, reason: `${lineId} owned` };
  }

  const avgBondMatch = expr.match(/^avg_selected_spirit_bond_level>=(\d+)$/);
  if (avgBondMatch) {
    const target = Number(avgBondMatch[1] || 0);
    const avg = selectedSpiritBondAverage();
    return { pass: avg >= target, supported: true, reason: `avg bond ${avg.toFixed(1)}/${target}` };
  }

  const ecologyRankMatch = expr.match(/^ecology_combo_rank_count\(([^)]+)\)>=(\d+)$/);
  if (ecologyRankMatch) {
    const rank = ecologyRankMatch[1].trim();
    const target = Number(ecologyRankMatch[2] || 0);
    const count = ecologyComboRankCount(rank);
    return { pass: count >= target, supported: true, reason: `ecology rank ${rank} ${count}/${target}` };
  }

  if (data.conditionGroupsById.has(expr)) return conditionGroupStatus(expr, seen);

  return { pass: false, supported: false, reason: `unsupported expression: ${expr}` };
}

function conditionGroupStatus(id = "", seen = new Set()) {
  if (!id) return { id, known: true, expression: "true", pass: true, supported: true, reason: "default open" };
  if (seen.has(id)) return { id, known: true, expression: id, pass: false, supported: false, reason: "recursive condition group" };
  const group = conditionGroupFor(id);
  if (!group) {
    return {
      id,
      known: false,
      expression: id,
      pass: fallbackConditionMet(id),
      supported: true,
      reason: "legacy fallback condition",
    };
  }
  const nextSeen = new Set(seen);
  nextSeen.add(id);
  const result = evaluateConditionExpression(group.expression, nextSeen);
  return { id, known: true, expression: group.expression, ...result };
}

function conditionQaSummary() {
  const statuses = data.conditionGroups.map((group) => conditionGroupStatus(group.condition_group_id));
  const supported = statuses.filter((status) => status.supported).length;
  const passed = statuses.filter((status) => status.supported && status.pass).length;
  return { total: statuses.length, supported, passed, statuses };
}

function conditionLabel(condition = "") {
  if (!condition) return "默认开放";
  const group = conditionGroupFor(condition);
  if (group) return `${condition} · ${group.expression}`;
  const favorMatch = condition.match(/^npc_(.+)_favor_(\d+)$/);
  if (favorMatch) return `${npcName(`npc_${favorMatch[1]}`)}好感 Lv.${favorMatch[2]}`;
  const chapterMatch = condition.match(/^chapter_(\d+)_complete$/);
  if (chapterMatch) return `主线第 ${chapterMatch[1]} 章完成`;
  const activeQuestMatch = condition.match(/^quest_(.+)_active$/);
  if (activeQuestMatch) return `任务 ${condition.replace("_active", "")} 进行中`;
  const questMatch = condition.match(/^quest_(.+)_complete$/);
  if (questMatch) return `任务 ${condition.replace("_complete", "")} 完成`;
  return condition;
}

function fallbackConditionMet(condition = "") {
  if (!condition) return true;
  if (condition === "year2_start_unlocked" || condition === "quest_main_0403_complete") return year2Unlocked();
  if (condition === "unlock_herb_valley" || condition === "event_main_0205") return herbValleyUnlocked();
  const favorMatch = condition.match(/^npc_(.+)_favor_(\d+)$/);
  if (favorMatch) {
    const npcId = `npc_${favorMatch[1]}`;
    const level = Number(favorMatch[2] || 0);
    const liveLevel = favorLevel(state.npcFavor[npcId] || 0);
    const demoProxy = level <= 3 && (state.completed.has("spirit_expedition") || state.completed.has("repair"));
    return liveLevel >= level || demoProxy;
  }
  const chapterMatch = condition.match(/^chapter_(\d+)_complete$/);
  if (chapterMatch) return state.missionDone.size >= Number(chapterMatch[1]) || state.completed.has("dungeon");
  if (condition === "quest_main_0403_active") {
    return state.missionDone.has("quest_main_0403_pantao_dayan")
      || state.completed.has("solar_trial_complete")
      || hasCoreLoop();
  }
  if (condition.endsWith("_active")) {
    const id = condition.replace("_active", "");
    return state.missionDone.has(id) || state.completed.has(id) || state.completed.has(`quest_unlock_${id}`);
  }
  if (condition.endsWith("_complete")) {
    const id = condition.replace("_complete", "");
    return state.completed.has(id) || state.missionDone.has(id);
  }
  return state.completed.has(condition) || state.missionDone.has(condition);
}

function conditionMet(condition = "") {
  if (!condition) return true;
  if (data.conditionGroupsById.has(condition)) {
    const status = conditionGroupStatus(condition);
    if (status.supported) return status.pass;
  }
  return fallbackConditionMet(condition);
}

function finalSupportStages(bundleId) {
  return (data.finalSupportStagesByBundle.get(bundleId) || [])
    .slice()
    .sort((a, b) => {
      const order = { prep: 0, battle: 1, ending: 2 };
      return (order[a.stage_phase] ?? 9) - (order[b.stage_phase] ?? 9);
    });
}

function finalSupportReady(bundle) {
  if (!bundle) return false;
  if (bundle.bundle_id === "support_bundle_full_resonance") {
    if (conditionMet(bundle.require_condition_group) && hasCoreLoop()) return true;
    const readyCore = data.finalSupportBundles
      .filter((entry) => entry.npc_id !== "npc_system")
      .filter((entry) => state.unlockedFinalSupports.has(entry.bundle_id) || conditionMet(entry.require_condition_group));
    return conditionMet(bundle.require_condition_group) && readyCore.length >= 4;
  }
  return conditionMet(bundle.require_condition_group);
}

function townLifeUnlockedMemoryEntries(npcId = "") {
  const memories = TOWN_LIFE_MEMORY_BOOK[npcId] || [];
  const remembered = townLifeRememberedIds(npcId);
  return memories
    .map((memory) => remembered[memory.id])
    .filter(Boolean)
    .sort((a, b) => Number(a.level || 0) - Number(b.level || 0) || Number(a.interactions || 0) - Number(b.interactions || 0));
}

function finalSupportForeshadow(bundle) {
  if (!bundle) return { count: 0, total: 0, percent: 0, label: "暂无支援伏笔", detail: "等待关系记忆写入", tone: "empty" };
  if (bundle.npc_id === "npc_system") {
    const coreBundles = data.finalSupportBundles.filter((entry) => entry.npc_id !== "npc_system");
    const stats = coreBundles.map((entry) => finalSupportForeshadow(entry));
    const count = stats.reduce((sum, entry) => sum + entry.count, 0);
    const total = stats.reduce((sum, entry) => sum + entry.total, 0);
    const seeded = stats.filter((entry) => entry.count >= 3).length;
    return {
      count,
      total,
      percent: total ? Math.round((count / total) * 100) : 0,
      label: `全队关系伏笔 ${count}/${total}`,
      detail: `${seeded}/${coreBundles.length} 位核心 NPC 已形成可用于终章群像的日常铺垫`,
      tone: seeded >= 4 ? "ready" : count > 0 ? "warming" : "empty",
    };
  }
  const memories = TOWN_LIFE_MEMORY_BOOK[bundle.npc_id] || [];
  const unlocked = townLifeUnlockedMemoryEntries(bundle.npc_id);
  const latest = unlocked[unlocked.length - 1] || null;
  const next = memories.find((memory) => !townLifeRememberedIds(bundle.npc_id)[memory.id]) || null;
  const total = memories.length;
  const count = unlocked.length;
  return {
    count,
    total,
    percent: total ? Math.round((count / total) * 100) : 0,
    latest,
    next,
    label: `${npcName(bundle.npc_id)} 支援伏笔 ${count}/${total}`,
    detail: latest
      ? `最近记忆「${latest.title}」已能解释其终章支援：${bundle.note}`
      : `还缺少 ${npcName(bundle.npc_id)} 的日常记忆，终章支援会显得偏突然`,
    nextText: next ? `下一伏笔「${next.title}」` : "关系册当前篇章已完整",
    tone: count >= total && total > 0 ? "ready" : count >= 3 ? "warming" : count > 0 ? "seeded" : "empty",
  };
}

function finalSupportPrepClaimId(bundleId = "", tier = "") {
  return `${bundleId}:${tier}`;
}

function finalSupportPrepTiers(bundle) {
  if (!bundle || bundle.npc_id === "npc_system") return [];
  const foreshadow = finalSupportForeshadow(bundle);
  return [
    {
      tier: "intent",
      required: 3,
      label: "意向支援",
      effectRatio: 0.25,
      ready: foreshadow.count >= 3,
      claimed: state.finalSupportPrepClaims.has(finalSupportPrepClaimId(bundle.bundle_id, "intent")),
    },
    {
      tier: "pledge",
      required: 5,
      label: "成形支援",
      effectRatio: 0.5,
      ready: foreshadow.count >= 5,
      claimed: state.finalSupportPrepClaims.has(finalSupportPrepClaimId(bundle.bundle_id, "pledge")),
    },
  ].map((tier) => ({
    ...tier,
    bundleId: bundle.bundle_id,
    effectTarget: bundle.effect_target,
    effectValue: Number((Number(bundle.effect_value || 0) * tier.effectRatio).toFixed(3)),
  }));
}

function claimFinalSupportPrep(bundleId = "", tierId = "") {
  const bundle = data.finalSupportBundlesById.get(bundleId);
  if (!bundle || bundle.npc_id === "npc_system") return addLog("预备支援未配置", "这条支援暂时没有个人伏笔奖励。");
  const tier = finalSupportPrepTiers(bundle).find((entry) => entry.tier === tierId);
  if (!tier) return addLog("预备支援未配置", "没有找到这档支援伏笔奖励。");
  const claimId = finalSupportPrepClaimId(bundleId, tierId);
  if (state.finalSupportPrepClaims.has(claimId)) return addLog("预备支援已领取", `${npcName(bundle.npc_id)} 的${tier.label}已经写入终阵准备。`);
  if (!tier.ready) return addLog("支援伏笔不足", `${npcName(bundle.npc_id)} 还需要 ${tier.required} 段关系记忆才能给出${tier.label}。`);
  state.finalSupportPrepClaims.add(claimId);
  applyFinalSupportEffect(tier.effectTarget, tier.effectValue);
  complete(`final_support_prep_${tier.tier}`);
  triggerFinalSupportPrepFeedback(bundle, tier);
  playCue("成就解锁");
  addLog("预备支援到位", `${npcName(bundle.npc_id)} · ${tier.label}：${finalSupportEffectText(tier.effectTarget, tier.effectValue)}。`);
  render();
}

function finalSupportEffectText(target, value) {
  const names = {
    town_worker_capacity: "镇民施工力",
    final_array_stability: "终阵稳定",
    team_revive_window: "复苏窗口",
    array_qte_slowdown: "校时容错",
    final_order_stock_bonus: "终章库存",
    work_area_capacity: "阵台工位",
    irrigation_chain_efficiency: "引水效率",
    escort_damage_reduction: "护送减伤",
    all_final_support_bonus: "总共鸣",
    town_reputation: "凡仙镇口碑",
    final_array_damage_reduce: "阵基减伤",
    emergency_heal_count: "紧急治疗",
    fire_hazard_reduce: "火场压制",
    enemy_spawn_delay: "敌群延迟",
    trade_route_discount: "商路折扣",
    build_decorate_discount: "建造折扣",
  };
  const numeric = Number(value || 0);
  const isRatio = Math.abs(numeric) > 0 && Math.abs(numeric) < 1;
  return `${names[target] || target} +${isRatio ? percentText(numeric) : numeric}`;
}

function triggerFinalSupportPrepFeedback(bundle = null, tier = null) {
  if (!bundle || !tier) return null;
  const foreshadow = finalSupportForeshadow(bundle);
  const effectText = finalSupportEffectText(tier.effectTarget, tier.effectValue);
  const feedback = {
    bundleId: bundle.bundle_id,
    npcId: bundle.npc_id,
    npcName: npcName(bundle.npc_id),
    tierId: tier.tier,
    tierLabel: tier.label,
    supportType: bundle.support_type || "终章支援",
    effectText,
    count: foreshadow.count,
    required: tier.required,
    note: bundle.note || "这份关系伏笔已经写进终阵准备。",
    latestTitle: foreshadow.latest?.title || "",
    headline: `${npcName(bundle.npc_id)} · ${tier.label}入阵`,
    detail: `关系伏笔 ${foreshadow.count}/${tier.required} 已化成 ${effectText}`,
    createdAt: performance.now(),
    duration: 6200,
  };
  state.finalSupportPrepFeedback = feedback;
  return feedback;
}

function triggerFinalSupportUnlockFeedback(bundle = null) {
  if (!bundle) return null;
  const effectText = finalSupportEffectText(bundle.effect_target, bundle.effect_value);
  const stages = finalSupportStages(bundle.bundle_id);
  const firstStage = stages[0] || null;
  const feedback = {
    bundleId: bundle.bundle_id,
    npcId: bundle.npc_id,
    npcName: npcName(bundle.npc_id),
    supportType: bundle.support_type || "终章支援",
    effectText,
    conditionText: conditionLabel(bundle.require_condition_group),
    nextStageText: firstStage
      ? `${firstStage.stage_phase} · ${finalSupportEffectText(firstStage.effect_target, firstStage.effect_value)}`
      : "等待终章阶段配置",
    note: bundle.note || "这路支援已经正式进入最终战准备。",
    headline: `${npcName(bundle.npc_id)} · 终章支援到位`,
    detail: `${effectText} 已写入终阵准备`,
    createdAt: performance.now(),
    duration: 6600,
  };
  state.finalSupportUnlockFeedback = feedback;
  return feedback;
}

function finalSupportPower() {
  return Object.values(state.finalSupportEffects || {}).reduce((sum, value) => sum + Number(value || 0), 0);
}

function applyFinalSupportEffect(target, value) {
  if (!target) return;
  state.finalSupportEffects[target] = Number((Number(state.finalSupportEffects[target] || 0) + Number(value || 0)).toFixed(3));
}

function unlockFinalSupport(bundleId) {
  const bundle = data.finalSupportBundlesById.get(bundleId);
  if (!bundle) return addLog("终章支援未配置", "CSV 中没有找到该支援束。");
  if (state.unlockedFinalSupports.has(bundleId)) return addLog("支援已到位", `${npcName(bundle.npc_id)} 的终章支援已经进入最终战准备。`);
  if (!finalSupportReady(bundle)) return addLog("支援未解锁", `${npcName(bundle.npc_id)} 还需要 ${conditionLabel(bundle.require_condition_group)}。`);

  state.unlockedFinalSupports.add(bundleId);
  state.completed.add(bundle.unlock_flag);
  applyFinalSupportEffect(bundle.effect_target, bundle.effect_value);
  triggerFinalSupportUnlockFeedback(bundle);
  showDialogue(bundle.dialogue_group_id);
  complete("final_support_unlock");
  playCue("成就解锁");
  addLog("终章支援到位", `${npcName(bundle.npc_id)}：${bundle.note}。${finalSupportEffectText(bundle.effect_target, bundle.effect_value)}。`);
  render();
}

function applyFinalSupportStage(stageId) {
  const stage = data.finalSupportStages.find((entry) => entry.stage_id === stageId);
  if (!stage) return addLog("支援阶段未配置", "CSV 中没有找到该终章支援阶段。");
  const bundle = data.finalSupportBundlesById.get(stage.bundle_id);
  const bundleReady = state.unlockedFinalSupports.has(stage.bundle_id) || finalSupportReady(bundle);
  if (!bundleReady || !conditionMet(stage.trigger_condition_group)) {
    return addLog("阶段尚未就绪", `${bundle ? npcName(bundle.npc_id) : stage.bundle_id} 需要 ${conditionLabel(stage.trigger_condition_group)}。`);
  }
  if (state.appliedFinalSupportStages.has(stageId)) return addLog("阶段已应用", `${stage.stage_phase} 阶段支援已经写入最终战准备。`);

  if (!state.unlockedFinalSupports.has(stage.bundle_id)) state.unlockedFinalSupports.add(stage.bundle_id);
  state.appliedFinalSupportStages.add(stageId);
  applyFinalSupportEffect(stage.effect_target, stage.effect_value);
  finalSupportStageAfterglowWorldFocus = {
    key: `${stage.bundle_id}:${stage.stage_id}:final_support_stage_afterglow:${state.day}`,
    day: state.day,
    bundleId: stage.bundle_id,
    stageId: stage.stage_id,
    nodeKey: "written",
    source: "applied",
  };
  complete(`final_support_stage_${stage.stage_phase}`);
  if (stage.cutscene_id) startCutscene(stage.cutscene_id);
  addLog("终章阶段支援", `${npcName(bundle?.npc_id)} ${stage.stage_phase}：${finalSupportEffectText(stage.effect_target, stage.effect_value)}，QA ${stage.qa_check_key}。`);
  render();
}

function supplyTagLabel(tag) {
  const names = {
    portable_food: "便携干粮",
    water: "清水",
    medicine: "药品",
    cooling_drink: "清凉饮",
    trade_pack: "成套贸易包",
    refined_gift: "精致礼品",
  };
  return names[tag] || tag;
}

function itemMatchesSupplyTag(item, tag) {
  const tags = splitTags(item?.tags || "");
  if (tags.includes(tag)) return true;
  const aliasTags = {
    portable_food: ["food", "staple", "recover_sp"],
    water: ["water"],
    medicine: ["medicine", "heal_hp", "heal_sp"],
    cooling_drink: ["drink", "summer", "tea"],
    trade_pack: ["trade", "premium", "gift", "material"],
    refined_gift: ["gift", "premium", "festival", "tea", "book"],
  };
  return (aliasTags[tag] || []).some((alias) => tags.includes(alias) || item?.item_type === alias);
}

function inventoryCountBySupplyTag(tag) {
  return Object.entries(state.inventory).reduce((sum, [itemId, count]) => {
    const item = data.itemsById.get(itemId);
    return itemMatchesSupplyTag(item, tag) ? sum + count : sum;
  }, 0);
}

function routeSupplyStatus(route) {
  const required = splitTags(route.required_supply_tag);
  const risks = data.tradeRisksByRoute.get(route.route_id) || [];
  const tags = [...new Set([...required, ...risks.map((risk) => risk.required_supply_tag).filter(Boolean)])];
  return tags.map((tag) => {
    const risk = risks.find((entry) => entry.required_supply_tag === tag);
    const needed = Math.max(1, Number(risk?.min_supply_count || (tag === route.required_supply_tag ? 3 : 1)));
    const owned = inventoryCountBySupplyTag(tag);
    return { tag, owned, needed, ready: owned >= needed, risk };
  });
}

function tradeCargoCandidates(route) {
  const preferred = splitTags(route.preferred_goods_tags);
  return Object.entries(state.inventory)
    .map(([itemId, count]) => ({ itemId, count, item: data.itemsById.get(itemId) }))
    .filter(({ count, item }) => count > 0 && item && item.sell_price_base !== "0" && item.item_type !== "seed")
    .map((entry) => {
      const tags = splitTags(entry.item.tags);
      const match = tags.filter((tag) => preferred.includes(tag)).length;
      const value = Number(entry.item.sell_price_base || 0);
      return { ...entry, match, value };
    })
    .filter((entry) => entry.match > 0 || entry.value >= 20)
    .sort((a, b) => (b.match - a.match) || (b.value - a.value));
}

function tradeRunFor(routeId) {
  return (state.tradeRuns || []).find((run) => run.routeId === routeId && run.status === "traveling");
}

function tradeEventForRoute(routeId = "") {
  return (data.tradeEventsByRoute.get(routeId) || [])[0] || null;
}

function tradeEventChoiceSpec(event, choice = "b") {
  if (!event) return { choice: "none", label: "常规押运", riskDelta: 0, profitBonus: 0, rareBonus: 0, summary: "按常规路线押运" };
  const rawRisk = Number(event.risk_delta || 0);
  if (choice === "a") {
    return {
      choice: "a",
      label: event.choice_a || "冒险近路",
      riskDelta: rawRisk,
      profitBonus: Math.max(0.04, Math.abs(rawRisk) * 0.9),
      rareBonus: event.event_type === "story_event" ? 1 : 0,
      summary: `${event.event_name} · ${event.choice_a || "冒险近路"}`,
    };
  }
  return {
    choice: "b",
    label: event.choice_b || "稳妥旧路",
    riskDelta: -Math.max(0.02, Math.abs(rawRisk) * 0.55),
    profitBonus: 0,
    rareBonus: event.event_type === "inspection_event" ? 1 : 0,
    summary: `${event.event_name} · ${event.choice_b || "稳妥旧路"}`,
  };
}

function tradeCargoPlan(route) {
  const candidates = tradeCargoCandidates(route).slice(0, 3);
  const goods = [];
  let value = 0;
  for (const candidate of candidates) {
    const count = Math.min(candidate.count, candidate.match > 0 ? 2 : 1);
    if (count <= 0) continue;
    goods.push({ itemId: candidate.itemId, count, unitValue: candidate.value });
    value += candidate.value * count;
  }
  return { goods, value };
}

function spendTradeSupplies(supply) {
  const spent = [];
  for (const entry of supply.filter((item) => item.ready)) {
    let remaining = Math.max(0, Math.min(entry.needed, Math.ceil(entry.needed / 2)));
    for (const [itemId, count] of Object.entries(state.inventory)) {
      if (remaining <= 0) break;
      const item = data.itemsById.get(itemId);
      if (!itemMatchesSupplyTag(item, entry.tag)) continue;
      const used = Math.min(count, remaining);
      addItem(itemId, -used);
      remaining -= used;
      spent.push(`${itemName(itemId)} x${used}`);
    }
  }
  return spent;
}

function startTradeRoute(routeId, eventChoice = "b") {
  const route = data.tradeRoutesById.get(routeId);
  const spirit = state.spirits[0];
  if (!route) return addLog("商路未配置", "CSV 中没有找到这条跨界商路。");
  if (!spirit) return addLog("缺少领路精怪", "先让作物成精，再由远征岗押队。");
  ensureSpiritJobs(spirit);
  const preview = routePreview(route);
  if (!preview.unlocked) return addLog("商路未解锁", `${route.route_name} 需要 ${conditionLabel(route.unlock_condition_group)}。`);
  if (tradeRunFor(route.route_id)) return addLog("商队在途", `${route.route_name} 已经有一支商队在路上。`);
  if ((spirit.stamina || 0) < 22) return addLog("精怪太累", "正式发商队至少需要 22 点体力。");
  const hiddenTradeGuard = state.completed.has("buff_trade_risk_down_next");

  const cargo = tradeCargoPlan(route);
  if (cargo.goods.length === 0 || cargo.value <= 0) return addLog("无可装货物", `${route.route_name} 偏好 ${splitTags(route.preferred_goods_tags).join(" / ")}，请先准备可售货品。`);

  for (const goods of cargo.goods) addItem(goods.itemId, -goods.count);
  const spentSupply = spendTradeSupplies(preview.supply);
  spirit.stamina = Math.max(0, (spirit.stamina || 0) - 22);
  spirit.mood = Math.max(0, (spirit.mood || 0) - 5);
  addJobExp(spirit, "expedition", 4, `${route.route_name} 押运`);
  const event = preview.event || tradeEventForRoute(route.route_id);
  const choiceSpec = tradeEventChoiceSpec(event, eventChoice);

  const run = {
    id: `${route.route_id}_${state.day}_${state.tradeRuns.length + 1}`,
    routeId: route.route_id,
    startDay: state.day,
    returnDay: state.day + Number(route.travel_days || 1),
    cargo: cargo.goods,
    cargoValue: cargo.value,
    risk: Math.max(0.04, Math.min(0.95, preview.risk + choiceSpec.riskDelta)),
    readySupply: preview.ready,
    eventId: event?.trade_event_id || "",
    eventChoice: choiceSpec.choice,
    eventChoiceLabel: choiceSpec.label,
    eventRiskDelta: choiceSpec.riskDelta,
    eventProfitBonus: choiceSpec.profitBonus,
    eventRareBonus: choiceSpec.rareBonus,
    rotationId: preview.rotation?.rotation_id || "",
    status: "traveling",
  };
  state.tradeRuns.push(run);
  if (hiddenTradeGuard) state.completed.delete("buff_trade_risk_down_next");
  complete("trade_route_start");
  complete(choiceSpec.choice === "a" ? "trade_route_choice_risky" : "trade_route_choice_safe");
  addLog("商队出发", `${route.route_name} 装载 ${cargo.goods.map((goods) => `${itemName(goods.itemId)} x${goods.count}`).join("、")}，预计第 ${run.returnDay} 天返回。${event ? `事件选择：${choiceSpec.label}，风险 ${signedPercent(choiceSpec.riskDelta)}${choiceSpec.profitBonus > 0 ? `，利润预期 +${percentText(choiceSpec.profitBonus)}` : ""}。` : ""}${spentSupply.length ? `补给消耗：${spentSupply.join("、")}。` : "未消耗额外补给。"}${hiddenTradeGuard ? "雷痕旧路的见闻还在，这一趟商路风险会再低一截。" : ""}`);
  render();
}

function triggerQingheLotusBasinTradeReturnFeedback(run = null, route = null, rewards = []) {
  if (!run || run.routeId !== "route_lotus_basin_03" || !route) return null;
  const firstReturn = !state.completed.has("qinghe_lotus_basin_trade_return");
  if (firstReturn) complete("qinghe_lotus_basin_trade_return");
  const rewardText = rewards.length ? rewards.join("、") : "水航返货";
  const change = upsertWorldChange({
    key: "qinghe_lotus_basin_trade_return",
    title: "莲泽水航返货",
    detail: `${route.route_name}返航后，青禾把涨潮、借港和返货的水路记成熟线。旧铺的灵池水鲜已经能顺着莲泽水航带回更稳定的水系货。`,
    rewardHint: `${Number(run.profit || 0)} 灵石 · ${rewardText}`,
    visualType: "lotus_basin_trade_return",
  });
  addLog("莲泽水航返货", `${route.route_name}带回 ${Number(run.profit || 0)} 灵石和${rewardText}，青禾的水航熟路已经记入洞天水面。`);
  if (firstReturn && !state.completed.has("qinghe_lotus_basin_return_dialogue")) {
    addNpcFavor("npc_qinghe", 3, "莲泽水航返货");
    complete("qinghe_lotus_basin_return_dialogue");
    queueDialogueGroup("dialogue_qinghe_lotus_basin_return");
  }
  return change;
}

function settleTradeRun(run) {
  const route = data.tradeRoutesById.get(run.routeId);
  if (!route || run.status !== "traveling" || run.returnDay > state.day) return;
  const taskLevel = spiritJobTaskEffectLevel("expedition");
  const cohabTradeBonus = cohabSharedBonusValue("trade_margin") + cohabBuffValue("buff_trade_margin_up");
  const eventProfitBonus = Number(run.eventProfitBonus || 0);
  const familiarRoute = lotusBasinFamiliarRouteBonus(route);
  const profitBonusRate = (taskLevel >= 5 ? 0.1 : taskLevel >= 3 ? 0.05 : 0) + cohabTradeBonus + eventProfitBonus + familiarRoute.profitBonus;
  const rareRewardBonus = (taskLevel >= 5 ? 1 : 0) + Number(run.eventRareBonus || 0) + (run.readySupply ? familiarRoute.rareRewardBonus : 0);
  const riskPenalty = run.readySupply ? run.risk * 0.35 : run.risk * 0.75;
  const profitRate = Math.max(0.35, Number(route.profit_rate || 1) - riskPenalty);
  const gross = Math.max(1, Math.round(run.cargoValue * profitRate));
  const baseProfit = Math.max(1, gross - Math.round(run.cargoValue * 0.45));
  const profit = Math.max(1, Math.round(baseProfit * (1 + profitBonusRate)));
  state.gold += profit;
  state.fame += run.readySupply ? 2 : 1;
  const rewards = rewardPoolEntries(route.rare_reward_pool)
    .slice(0, (run.readySupply ? 2 : 1) + rareRewardBonus)
    .map((entry) => applyRewardEntry(entry, run.readySupply ? 1 : 0.65));
  run.status = "returned";
  run.returnedDay = state.day;
  run.profit = profit;
  run.rewards = rewards;
  const securedMidRisk = run.readySupply && Number(route.base_risk || 0) >= 0.16;
  if (securedMidRisk) complete("protected_midrisk_trade");
  complete("trade_route_complete");
  triggerQingheLotusBasinTradeReturnFeedback(run, route, rewards);
  triggerCohabWeeklyEvents("on_trade_return", { routeId: run.routeId, day: state.day });
  const escortNote = securedMidRisk
    ? stormEscortActive()
      ? "雷竹沿路校过绳结和落雷点，这趟货比从前稳了许多。"
      : "这趟中风险商路你先保住了货，整支队伍才能全须全尾地回来。"
    : "";
  const familiarNote = familiarRoute.active ? `莲泽熟路加成：风险更低，回款 +${percentText(familiarRoute.profitBonus)}${run.readySupply ? "，额外返货 +1。" : "。"}` : "";
  const eventNote = run.eventChoiceLabel ? `路上选择「${run.eventChoiceLabel}」已结算。` : "";
  const tradeLearningNeeded = !run.readySupply || run.risk >= 0.45 || riskPenalty >= 0.22;
  if (tradeLearningNeeded) {
    const rewardText = `${profit} 灵石${rewards.length ? ` · ${rewards.join("、")}` : ""}`;
    recordFailureCodexEntry({
      id: `failure_trade_${run.id}`,
      type: "trade",
      sourceId: `${run.routeId}:${run.id}`,
      title: run.readySupply ? "商队险路见闻" : "商队补给缺口",
      headline: `${route.route_name} 把风险折损写进路簿`,
      problem: run.readySupply
        ? `风险折损 ${percentText(riskPenalty)}，利润被压低。`
        : `补给不足，风险折损 ${percentText(riskPenalty)}。`,
      insight: run.readySupply
        ? "路线能走通，但高风险路线需要雷竹、补给或更稳的事件选择。"
        : "不是白跑，商队带回了缺口标签：下次先备足路线补给。",
      nextAction: "下次发商队前先查看路线补给、风险和随行精怪，再决定保守或高收益选择。",
      support: rewardText,
      rewardText,
      tone: run.readySupply ? "learn" : "support",
      icon: "路",
    });
  }
  addLog("商队返程", `${route.route_name} 带回 ${profit} 灵石${profitBonusRate > 0 ? `（综合加成 ${percentText(profitBonusRate)}）` : ""}、声望 +${run.readySupply ? 2 : 1}${rewards.length ? `、${rewards.join("、")}` : ""}。风险折损 ${percentText(riskPenalty)}。${eventNote}${familiarNote}${escortNote}`);
}

function settleTradeRoutes() {
  for (const run of state.tradeRuns || []) settleTradeRun(run);
  state.tradeRuns = (state.tradeRuns || []).slice(-8);
}

