function expandShopSemanticTags(tags = []) {
  const runtime = shopRuntime();
  if (runtime) return runtime.expandShopSemanticTags(tags);
  const groups = [
    ["festival", "festival_food", "festival_gift"],
    ["gift", "festival_gift", "flower_food"],
    ["premium", "premium_luxury", "luxury", "rare_goods"],
    ["portable_food", "portable_supply"],
    ["route_rare", "rare_goods"],
    ["drink", "cooling_drink"],
    ["cooling", "cooling_drink", "refreshing"],
    ["cheap", "low_price", "cheap_crop"],
    ["crop", "common_crop", "cheap_crop"],
    ["batch", "batch_standard"],
    ["water_food", "water"],
    ["recover_sp", "heal_sp"],
    ["recover_hp", "heal_hp"],
    ["dessert", "sweet_food", "festival_food", "flower_food", "fruit_food"],
    ["material", "workshop_supply"],
    ["medicine", "relief"],
    ["staple", "portable_supply"],
  ];
  const expanded = new Set(tags.filter(Boolean));
  let changed = true;
  while (changed) {
    changed = false;
    for (const group of groups) {
      if (!group.some((tag) => expanded.has(tag))) continue;
      for (const tag of group) {
        if (expanded.has(tag)) continue;
        expanded.add(tag);
        changed = true;
      }
    }
  }
  return [...expanded];
}

function shopTagsOverlap(leftTags = [], rightTags = []) {
  const runtime = shopRuntime();
  if (runtime) return runtime.shopTagsOverlap(leftTags, rightTags);
  if (!leftTags.length || !rightTags.length) return false;
  const right = new Set(expandShopSemanticTags(rightTags));
  return expandShopSemanticTags(leftTags).some((tag) => right.has(tag));
}

