function rareSpiritGiftItemIds() {
  return new Set((state.rareSpiritGifts || []).map((gift) => gift.itemId).filter(Boolean));
}

function ecologyTagMatchesCombo(tags = [], comboId = "", itemId = "") {
  const profile = ecologyCommodityProfile(comboId);
  return profile.tags.some((tag) => shopTagsOverlap(tags, [tag]))
    || profile.itemFragments.some((fragment) => itemId.includes(fragment));
}

function ecologySemanticTagsForItem(itemOrId, ecologyGarden = null) {
  const item = typeof itemOrId === "string" ? data.itemsById.get(itemOrId) : (itemOrId?.item || itemOrId);
  const itemId = typeof itemOrId === "string" ? itemOrId : itemOrId?.itemId || itemOrId?.item_id || item?.item_id || "";
  const baseTags = splitTags(item?.tags || item?.item_tags || "");
  if (!itemId && baseTags.length === 0) return [];
  const garden = ecologyGarden || ecologyCourtyardSummary();
  const activeCombos = [...(garden.claimedCombos || []), ...(garden.activeCombos || [])];
  const activeComboIds = new Set(activeCombos.map((combo) => combo.comboId).filter(Boolean));
  const inferred = new Set();
  const ecologyMatch = activeCombos.some((combo) => ecologyTagMatchesCombo(baseTags, combo.comboId, itemId));

  if (ecologyMatch) inferred.add("ecology_product");
  if (
    rareSpiritGiftItemIds().has(itemId)
    || (ecologyMatch && baseTags.some((tag) => ["gift", "premium", "dessert", "tea", "drink", "festival", "medicine", "archive"].includes(tag)))
  ) {
    inferred.add("spirit_crafted");
  }
  if (
    itemId === "item_route_rare_material"
    || baseTags.some((tag) => ["trade", "rare", "cloud", "archive"].includes(tag))
    || /(^|_)(trade|route|archive|cloud)(_|$)/.test(itemId)
    || (activeComboIds.has("eco_cloud_warehouse") && baseTags.some((tag) => ["portable_food", "premium", "gift"].includes(tag)))
  ) {
    inferred.add("route_rare");
  }

  return [...inferred];
}

function shopTagsForItem(itemOrId, ecologyGarden = null) {
  const item = typeof itemOrId === "string" ? data.itemsById.get(itemOrId) : (itemOrId?.item || itemOrId);
  const baseTags = splitTags(item?.tags || item?.item_tags || "");
  return [...new Set([...baseTags, ...ecologySemanticTagsForItem(itemOrId, ecologyGarden)])];
}

