function shopHotTag(goods, theme, ecologyGarden = null) {
  const runtime = shopRuntime();
  if (runtime) {
    const taggedGoods = (Array.isArray(goods) ? goods : []).map((good) => ({
      ...good,
      tags: shopTagsForItem(good?.item || good?.itemId, ecologyGarden),
    }));
    return runtime.shopHotTag(taggedGoods, theme);
  }
  const required = splitTags(theme?.required_item_tags || "");
  const counts = new Map();
  for (const { item, count } of goods) {
    for (const tag of shopTagsForItem(item, ecologyGarden)) {
      counts.set(tag, Number(count || 1) + Number(counts.get(tag) || 0));
    }
  }
  const available = [...counts.keys()];
  const featured = available.filter((tag) => required.includes(tag) || isExpressiveShopTag(tag) || ["ecology_product", "spirit_crafted", "route_rare"].includes(tag));
  return prioritizeShopTag(featured.length ? featured : available, counts, required[0] || "food");
}

function shopDisplayDiagnosisSpec(goods = sellableInventoryGoods(), theme = currentShelfTheme(), customers = data.customers, ecologyGarden = ecologyCourtyardSummary()) {
  const safeGoods = goods.filter(({ item, count }) => item && Number(count || 0) > 0);
  const themeTags = splitTags(theme?.required_item_tags || "");
  const goodsTags = new Set(safeGoods.flatMap(({ item, itemId }) => shopTagsForItem(item || itemId, ecologyGarden)));
  const themeScore = Math.round(themeMatchScore(safeGoods, theme) * 100);
  const minThemeScore = Math.round(Number(theme?.min_theme_ratio || 0.5) * 100);
  const hotTag = shopHotTag(safeGoods, theme, ecologyGarden);
  const activeSegments = activeCustomerSegments();
  const visibleCustomers = (customers || [])
    .filter((customer) => Number(customer.fame_requirement || 0) <= state.fame)
    .filter((customer) => {
      const unlockCondition = customerProfile(customer).unlock_condition_group || "";
      return !unlockCondition || conditionMet(unlockCondition);
    })
    .map((customer) => {
      const segment = activeSegments.find((entry) => entry.customer_archetype === customer.archetype);
      const view = customerViewFor(customer, segment);
      const preferred = splitTags(view.preferred_tags);
      const disliked = splitTags(view.disliked_tags);
      const matchingPreferred = preferred.filter((tag) => shopTagsOverlap([...goodsTags], [tag]));
      const themeCustomerBonus = customer.archetype === theme?.customer_archetype ? 3 : 0;
      const segmentBonus = Number(segment?.visit_rate || 1);
      return {
        customer,
        view,
        preferred,
        disliked,
        matchingPreferred,
        score: matchingPreferred.length * 2 + themeCustomerBonus + segmentBonus,
      };
    })
    .filter((entry) => entry.preferred.length > 0)
    .sort((a, b) => Number(b.score || 0) - Number(a.score || 0));
  const customerTargets = visibleCustomers.slice(0, 3).map((entry) => {
    const focusTags = (entry.matchingPreferred.length ? entry.matchingPreferred : entry.preferred).slice(0, 3);
    return {
      name: customerDisplayName(entry.customer.archetype),
      archetype: entry.customer.archetype,
      tags: focusTags,
      tagText: focusTags.map(shopTagLabel).join(" / ") || "随便看看",
    };
  });
  const featuredGoods = safeGoods
    .map(({ item, itemId, count }) => {
      const tags = shopTagsForItem(item || itemId, ecologyGarden);
      const themeMatches = themeTags.filter((tag) => shopTagsOverlap(tags, [tag]));
      const customerMatches = visibleCustomers
        .filter((entry) => shopTagsOverlap(tags, entry.preferred) && !shopTagsOverlap(tags, entry.disliked))
        .slice(0, 3);
      const ecologyTags = tags.filter((tag) => ["ecology_product", "spirit_crafted", "route_rare"].includes(tag));
      const expressiveTags = tags.filter((tag) => isExpressiveShopTag(tag));
      const score = themeMatches.length * 5
        + customerMatches.length * 3
        + ecologyTags.length * 3
        + expressiveTags.length * 2
        + Math.min(4, Number(count || 0));
      const labelTags = [...new Set([...themeMatches, ...ecologyTags, ...expressiveTags, ...tags])].slice(0, 3);
      return {
        itemId,
        itemName: itemName(itemId),
        count: Number(count || 0),
        score,
        tagText: labelTags.map(shopTagLabel).join(" / ") || shopTagLabel(hotTag),
        customerText: customerMatches.map((entry) => customerDisplayName(entry.customer.archetype)).join(" / ") || "路过客",
      };
    })
    .sort((a, b) => Number(b.score || 0) - Number(a.score || 0))
    .slice(0, 4);
  const missingTags = themeTags
    .filter((tag) => !safeGoods.some(({ item, itemId }) => shopTagsOverlap(shopTagsForItem(item || itemId, ecologyGarden), [tag])))
    .slice(0, 4);
  const themeOptions = data.shopShelfThemes
    .map((candidate) => ({
      theme: candidate,
      score: Math.round(themeMatchScore(safeGoods, candidate) * 100),
      tags: splitTags(candidate.required_item_tags),
    }))
    .sort((a, b) => Number(b.score || 0) - Number(a.score || 0));
  const bestTheme = themeOptions.find((entry) => entry.theme?.theme_tag !== theme?.theme_tag && entry.score > themeScore + 10)
    || (themeScore < minThemeScore ? themeOptions.find((entry) => entry.theme?.theme_tag !== theme?.theme_tag) : null);
  const nextTheme = bestTheme
    ? {
      themeTag: bestTheme.theme.theme_tag,
      themeName: bestTheme.theme.note || bestTheme.theme.theme_tag,
      score: bestTheme.score,
      tagText: bestTheme.tags.slice(0, 3).map(shopTagLabel).join(" / "),
    }
    : null;
  const tone = safeGoods.length === 0 || themeScore < minThemeScore ? "warn" : themeScore >= Math.max(70, minThemeScore) ? "good" : "focus";
  const featuredName = featuredGoods[0]?.itemName || "可卖货";
  const headline = safeGoods.length === 0
    ? "货架还没有能讲清楚的第一件商品。"
    : themeScore >= minThemeScore
      ? `${featuredName}可以放头排，先让“${shopTagLabel(hotTag)}”成为今日招牌。`
      : `${theme?.note || "当前主题"}还缺${missingTags.slice(0, 2).map(shopTagLabel).join(" / ") || "关键标签"}支撑。`;
  const advice = safeGoods.length === 0
    ? "先放上一件可卖作物或加工品，再看客群偏好。"
    : nextTheme
      ? `换陈列建议：${nextTheme.themeName} 当前可达 ${nextTheme.score}%，比硬撑旧主题更清楚。`
      : missingTags.length > 0
        ? `补一件${missingTags.slice(0, 2).map(shopTagLabel).join(" / ")}，主题匹配会更稳。`
        : `主推货架围绕 ${featuredName} 展开，旁边补同标签小货即可。`;
  return {
    active: safeGoods.length > 0,
    title: "货架陈列诊断",
    themeName: theme?.note || state.shopShelfTheme || "旧铺主题",
    themeScore,
    minThemeScore,
    hotTag,
    hotTagLabel: shopTagLabel(hotTag),
    featuredGoods,
    customerTargets,
    missingTags,
    missingTagText: missingTags.map(shopTagLabel).join(" / "),
    requiredTagText: themeTags.slice(0, 4).map(shopTagLabel).join(" / "),
    nextTheme,
    tone,
    headline,
    advice,
  };
}

function shopDisplayDiagnosisMarkup(spec = shopDisplayDiagnosisSpec()) {
  if (!spec?.active) return "";
  const goodsText = spec.featuredGoods.length
    ? spec.featuredGoods.map((good, index) => `
      <div class="shop-display-good ${index === 0 ? "feature" : ""}">
        <b>${index === 0 ? "主推货" : "备选货"} · ${good.itemName} x${good.count}</b>
        <span>${good.tagText}</span>
        <small>更容易打动：${good.customerText}</small>
      </div>
    `).join("")
    : "<small>还没有可主推商品，先补一件可卖加工品。</small>";
  const customerText = spec.customerTargets.length
    ? spec.customerTargets.map((target) => `<b>${target.name}<small>${target.tagText}</small></b>`).join("")
    : "<b>客群未定<small>先用应季货测试第一批顾客</small></b>";
  const missingText = spec.missingTags.length
    ? spec.missingTags.map((tag) => `<em class="shop-display-tag missing">${shopTagLabel(tag)}</em>`).join("")
    : `<em class="shop-display-tag">主题标签齐备</em>`;
  return `
    <div class="shop-display-diagnosis ${spec.tone}" data-shop-board="display-diagnosis">
      <strong>${spec.title} · ${spec.themeName}</strong>
      <span>${spec.headline}</span>
      <div class="shop-display-diagnosis-grid">
        <b>主题匹配 ${spec.themeScore}%<small>门槛 ${spec.minThemeScore}%</small></b>
        <b>热卖标签 ${spec.hotTagLabel}<small>${spec.requiredTagText || "应季货"}</small></b>
        <b>客群偏好<small>${spec.customerTargets.map((target) => target.name).join(" / ") || "待观察"}</small></b>
      </div>
      <div class="shop-display-goods">${goodsText}</div>
      <div class="shop-display-customer-targets">${customerText}</div>
      <div class="shop-display-tags">${missingText}</div>
      <small>换陈列建议：${spec.nextTheme ? `${spec.nextTheme.themeName} · 预计 ${spec.nextTheme.score}% · ${spec.nextTheme.tagText}` : "暂不需要换主题，先补厚当前主推货。"}</small>
      <small>掌柜建议：${spec.advice}</small>
    </div>
  `;
}

