function shopCompendiumDisplaySpec(entry = null, theme = currentShelfTheme(), hotTag = "") {
  if (!entry || (!entry.unlocked && !entry.cleared)) return null;
  const blueprint = shopCompendiumDisplayBlueprint(entry.mechanicId);
  const themeTags = splitTags(theme?.required_item_tags || "");
  const matchingTags = blueprint.tags.filter((tag) => tag === hotTag || themeTags.includes(tag));
  const termMatch = entry.termId === currentTermId();
  const palette = dungeonMechanicTheme(dungeonMechanicTone({ dungeon_id: entry.mechanicId }));
  const customerText = [...new Set(blueprint.archetypes)].slice(0, 3).map(customerDisplayName).join(" / ");
  const tagText = [...new Set(blueprint.tags)].slice(0, 3).map(shopTagLabel).join(" / ");
  const score = (entry.cleared ? 6 : 4) + (termMatch ? 2 : 0) + matchingTags.length * 2 + Math.min(2, Number(entry.clearCount || 0));
  const themeBonus = (entry.cleared ? 0.03 : 0.015) + (termMatch ? 0.01 : 0) + (matchingTags.length > 0 ? 0.01 : 0);
  const budgetBonus = (entry.cleared ? 0.05 : 0.03) + (matchingTags.length > 0 ? 0.01 : 0);
  return {
    key: entry.key,
    entry,
    shortTitle: entry.stampLabel,
    title: `${entry.stampLabel} 陈设`,
    palette,
    motif: blueprint.motif,
    tags: blueprint.tags,
    archetypes: blueprint.archetypes,
    customerText,
    tagText,
    termMatch,
    matchingTags,
    score,
    themeBonus,
    budgetBonus,
    marketText: `${entry.stampLabel} 会让 ${customerText} 更愿意停在 ${tagText} 的货架前。`,
    detail: matchingTags.length > 0
      ? `${entry.termLabel} 的印记正在映照 ${matchingTags.map(shopTagLabel).join(" / ")} 陈列。`
      : blueprint.caption,
  };
}

function activeShopCompendiumDisplays(goods = sellableInventoryGoods(), theme = currentShelfTheme(), limit = 2, hotTag = shopHotTag(goods, theme)) {
  return dungeonCompendiumEntries()
    .map((entry) => shopCompendiumDisplaySpec(entry, theme, hotTag))
    .filter(Boolean)
    .sort((a, b) => b.score - a.score || Number(b.entry.lastUpdateDay || 0) - Number(a.entry.lastUpdateDay || 0))
    .slice(0, limit);
}

function shopCompendiumDisplayEffect(displays = [], theme = currentShelfTheme(), hotTag = "") {
  if (!displays.length) {
    return {
      themeBonus: 0,
      visitorBonus: 0,
      summary: "",
      detail: "",
      customerText: "",
      tagText: hotTag ? shopTagLabel(hotTag) : "",
    };
  }
  const themeBonus = Math.min(0.14, displays.reduce((sum, display) => sum + Number(display.themeBonus || 0), 0));
  const visitorBonus = displays.some((display) => display.termMatch || display.matchingTags.length > 0)
    ? 1
    : displays.some((display) => display.entry.cleared)
      ? 1
      : 0;
  const customerText = [...new Set(displays.flatMap((display) => display.archetypes))].slice(0, 4).map(customerDisplayName).join(" / ");
  const tagText = [...new Set(displays.flatMap((display) => display.tags))].slice(0, 4).map(shopTagLabel).join(" / ");
  const summary = `${displays.map((display) => display.shortTitle).join(" / ")} 正在镇店`;
  const detail = `${customerText} 会更容易被 ${tagText || shopTagLabel(hotTag)} 的陈列留住。主题映照 +${Math.round(themeBonus * 100)}%${visitorBonus > 0 ? ` · 来客 +${visitorBonus}` : ""}。`;
  return {
    themeBonus,
    visitorBonus,
    summary,
    detail,
    customerText,
    tagText,
  };
}

function shopCompendiumCustomerSupport(displays = [], customerView = {}, choice = null, hotTag = "", ecologyGarden = null) {
  const runtime = shopRuntime();
  if (runtime) {
    const preferred = splitTags(customerView.preferred_tags || "");
    const itemTags = shopTagsForItem(choice?.item || choice?.itemId || "", ecologyGarden);
    const plan = runtime.shopCompendiumCustomerSupport({
      displays,
      customerArchetype: customerView.archetype,
      preferredTags: preferred,
      itemTags,
      hotTag,
    });
    const top = plan.matched[0];
    return {
      budgetBonus: plan.budgetBonus,
      matched: plan.matched,
      note: top ? shopCompendiumCustomerRemark(top, customerView, choice, hotTag, ecologyGarden) : "",
    };
  }
  if (!displays.length) return { budgetBonus: 0, matched: [], note: "" };
  const preferred = splitTags(customerView.preferred_tags || "");
  const itemTags = shopTagsForItem(choice?.item || choice?.itemId || "", ecologyGarden);
  const matched = displays.filter((display) => display.archetypes.includes(customerView.archetype)
    || display.tags.some((tag) => shopTagsOverlap([tag], preferred) || shopTagsOverlap([tag], itemTags) || tag === hotTag));
  const budgetBonus = Math.min(0.16, matched.reduce((sum, display) => sum + Number(display.budgetBonus || 0), 0));
  const top = matched[0];
  return {
    budgetBonus,
    matched,
    note: top ? shopCompendiumCustomerRemark(top, customerView, choice, hotTag, ecologyGarden) : "",
  };
}

function shopCompendiumCustomerRemark(display = null, customerView = {}, choice = null, hotTag = "", ecologyGarden = null) {
  if (!display) return "";
  const archetype = customerView.archetype || "villager";
  const name = customerDisplayName(archetype);
  const preferred = splitTags(customerView.preferred_tags || "");
  const itemTags = shopTagsForItem(choice?.item || choice?.itemId || "", ecologyGarden);
  const matchedTag = display.tags.find((tag) => shopTagsOverlap([tag], itemTags) || shopTagsOverlap([tag], preferred) || tag === hotTag)
    || display.matchingTags?.[0]
    || display.tags[0]
    || hotTag
    || "food";
  const tagText = shopTagLabel(matchedTag);
  const itemText = choice?.itemId ? itemName(choice.itemId) : tagText;
  const lines = {
    villager: `${name}在${display.shortTitle}前停下，说这排${tagText}有股刚从洞天带回来的稳当气。`,
    child: `${name}踮脚看${display.shortTitle}，指着${tagText}说想把这点节气光带回家。`,
    rogue_cultivator: `${name}扫过${display.shortTitle}后点头，觉得${itemText}够压住路上的风露。`,
    healer: `${name}闻见${display.shortTitle}里的清气，先把${tagText}记进了药囊清单。`,
    crafter: `${name}摸了摸${display.shortTitle}下的木牌，说${itemText}的火候和材料气都更明白了。`,
    trader: `${name}看着${display.shortTitle}算脚程，觉得这批${tagText}适合顺路带去下一站。`,
    guest: `${name}被${display.shortTitle}映出的纹路留住，愿意多看一眼${tagText}。`,
    faction: `${name}对着${display.shortTitle}记了一笔，说这批${itemText}有资格进门派采买单。`,
  };
  return lines[archetype] || `${display.shortTitle}让${name}多停了一会儿，目光落在${tagText}上。`;
}

