function activeNpcCompendiumRemark(npcId = "") {
  const goods = sellableInventoryGoods();
  const theme = currentShelfTheme();
  const hotTag = shopHotTag(goods, theme);
  return shopCompendiumNpcRemark(npcId, activeShopCompendiumDisplays(goods, theme, 2, hotTag));
}

function activeCustomerSegments() {
  const termId = currentTermId();
  const weatherId = currentWeatherConfig().weather_id;
  const reputation = shopReputationScore();
  return data.customerSegments.filter((segment) => {
    if (Number(segment.reputation_min || 0) > reputation) return false;
    if (Number(segment.fame_min || 0) > state.fame) return false;
    if (segment.term_tag && segment.term_tag !== termId) return false;
    if (segment.weather_tag && segment.weather_tag !== weatherId) return false;
    return true;
  });
}

function segmentForCustomer(customer) {
  return activeCustomerSegments().find((segment) => segment.customer_archetype === customer.archetype);
}

function behaviorFor(customer, stateName) {
  return data.customerBehaviorBy.get(`${customer.archetype}:${stateName}`)
    || data.customerBehaviorBy.get(`${customer.archetype}:enter_shop`)
    || {};
}

function flowFor(customer) {
  return [...(data.customerFlowBy.get(customer.archetype) || [])]
    .sort((a, b) => Number(a.state_order) - Number(b.state_order))
    .slice(0, 4);
}

function barkFor(archetype, context) {
  const bark = data.npcBarks.find((entry) => entry.speaker_group === archetype && entry.context_type === context)
    || data.npcBarks.find((entry) => entry.speaker_group === archetype);
  return bark ? localize(bark.text_key, "") : "";
}

function customerJourney(customer, bought, reason) {
  const flow = flowFor(customer);
  const steps = flow.map((step) => localize(step.ui_hint_key, step.state_name));
  const bark = bought ? barkFor(customer.archetype, "shop_buy") : "";
  const terminal = reason || "没有找到合适商品";
  return [...steps, bark, terminal].filter(Boolean).join(" → ");
}

function customerNeedBubble(customer, segment, hotTag = "", compendiumDisplays = [], returningCustomer = null, introducedCustomer = null) {
  const displayName = customerDisplayName(customer.archetype);
  const view = customerViewFor(customer, segment);
  const preferred = splitTags(view.preferred_tags);
  const useHotTag = isExpressiveShopTag(hotTag) && preferred.some((tag) => tag === hotTag || ["food", "fresh_food", "clean_food", "water_food", "food_cold", "cooling", "drink", "staple", "medicine"].includes(tag));
  const tag = useHotTag ? hotTag : prioritizeShopTag(preferred, new Map(), hotTag || "food");
  const directHint = shopFeedbackForSegment("need_hint", displayName, tag);
  const detailTags = [...new Set([tag, ...preferred])].slice(0, 3);
  const displaySupport = shopCompendiumCustomerSupport(compendiumDisplays, view, null, hotTag);
  const displayRemark = displaySupport.note || "";
  const needText = introducedCustomer?.needText || returningCustomer?.needText || displayRemark || directHint?.bubble_text || `想找${shopTagLabel(tag)}`;
  const detail = introducedCustomer
    ? `${introducedCustomer.arrivalText || introducedCustomer.headline || "熟客带了新脚步"} · ${introducedCustomer.broughtByText || `${introducedCustomer.hostLabel || "熟客"}把人领进门`} · 偏好：${detailTags.map(shopTagLabel).join(" / ") || "随便看看"}`
    : returningCustomer
    ? `${returningCustomer.arrivalText || returningCustomer.headline || "熟脸回门"} · 偏好：${detailTags.map(shopTagLabel).join(" / ") || "随便看看"}`
    : displayRemark
      ? `被${displaySupport.matched[0]?.shortTitle || "节气印记"}吸引 · 偏好：${detailTags.map(shopTagLabel).join(" / ") || "随便看看"}`
      : `偏好：${detailTags.map(shopTagLabel).join(" / ") || "随便看看"}`;
  return {
    name: displayName,
    customerArchetype: customer.archetype,
    tag,
    text: needText,
    detail,
    compendiumRemark: displayRemark,
    compendiumDisplay: displaySupport.matched[0]?.shortTitle || "",
    returningCustomer: Boolean(returningCustomer),
    returnVisitChance: Number(returningCustomer?.chance || 0),
    returnVisitHeadline: returningCustomer?.headline || "",
    returnVisitText: returningCustomer?.arrivalText || "",
    introducedCustomer: Boolean(introducedCustomer),
    introducedByLabel: introducedCustomer?.hostLabel || "",
    introducedVisitHeadline: introducedCustomer?.headline || "",
    introducedVisitText: introducedCustomer?.arrivalText || "",
  };
}

function shopPurchaseReason(choice, customer, soldIndex = 0) {
  const tags = shopTagsForItem(choice.item);
  const displayName = customerDisplayName(customer.archetype);
  if ((choice.itemId === "item_drink_helu_tangshui" || choice.item?.item_id === "item_drink_helu_tangshui") && state.completed.has("qinghe_lotus_basin_followup_order_done")) {
    if (customer.archetype === "waterway_broker") return "这杯荷露糖水带着莲泽熟路的回单味，水航客一尝就知道能带回去认门。";
    if (["trader", "guest", "faction"].includes(customer.archetype)) return "这杯荷露糖水有莲泽熟路的回单味，带出去比普通甜饮更像能认门的招牌。";
    if (["healer", "rogue_cultivator", "crafter"].includes(customer.archetype)) return "清甜不腻，还带着水航莲实的凉气，正适合赶路或收工后压燥。";
    return "荷露糖水一摆出来，就知道这家水鲜不是临时一船，而是能反复回来的熟路。";
  }
  if (choice.itemId === "item_food_qingbo_yukuai" || choice.item?.item_id === "item_food_qingbo_yukuai") {
    if (["healer", "rogue_cultivator"].includes(customer.archetype)) return "鱼鲜清凉不压药气，路上吃也不会拖着身子沉。";
    if (["trader", "guest"].includes(customer.archetype)) return "灵池鱼鲜有记忆点，端出去比普通凉菜更像招牌。";
    return "这口带着灵池活水和露珠芹清气，正好尝尝旧铺的新水鲜。";
  }
  const orderedTags = tags.filter((tag) => tag !== "food").sort((a, b) => shopTagPriority(b) - shopTagPriority(a));
  const direct = orderedTags.map((tag) => shopFeedbackForSegment("purchase_reason", displayName, tag)).find((entry) => entry?.result_text);
  if (direct?.result_text) return direct.result_text;
  const focusTag = orderedTags[0] || tags[0] || "food";
  if (focusTag === "refreshing") return "清口凉润，正好拿来压一压今天的燥气。";
  if (focusTag === "water_food") return "这口带着新渠水气，入口就知道是刚开水田出的。";
  if (focusTag === "food_cold") return "凉润不腻，热天忙完之后正想来这一口。";
  if (focusTag === "clean_food") return "清净爽口，不会压药气，带回去配诊也稳妥。";
  if (focusTag === "cooling") return "火气大的活计做完，就想来点凉口补给。";
  if (focusTag === "ecology_product") return "院里的生态气息在这货上是活的，带回去也像把洞天的一角带走。";
  if (focusTag === "spirit_crafted") return "一看就是精怪认真照看过的手作，细气和火候都不一样。";
  if (focusTag === "route_rare") return "这种货外路难撞见，碰上了就该先收。";
  return shopFeedbackBy("purchase_reason", soldIndex)?.result_text || `匹配 ${tags.slice(0, 2).map(shopTagLabel).join(" / ")} 标签。`;
}

function shopFeaturedMoment(goods = [], sale = null, hotTag = "") {
  const hasQingboFishDish = goods.some(({ itemId }) => itemId === "item_food_qingbo_yukuai") || sale?.itemId === "item_food_qingbo_yukuai";
  if (hasQingboFishDish) {
    if (sale?.itemId === "item_food_qingbo_yukuai") {
      return "清波鱼脍已经从灵池端上旧铺账页，水鲜招牌第一次真正卖出了声响。";
    }
    if (["refreshing", "water_food", "fish", "cooling", "fresh_food"].includes(hotTag)) {
      return `清波鱼脍已经摆上头排，来客开始顺着“${shopTagLabel(hotTag)}”认这股灵池鲜味。`;
    }
    return "清波鱼脍已经摆上头排，等第一位顾客把这股灵池鲜味带走。";
  }
  const hasCanalDish = goods.some(({ itemId }) => itemId === "item_food_liangban_lingqin");
  if (!hasCanalDish) return "";
  if (sale?.itemId === "item_food_liangban_lingqin") {
    return "新渠头一盘口味已经卖出去，旧铺第一次把水田的清润做成了招牌。";
  }
  if (["refreshing", "water_food", "food_cold", "clean_food", "cooling"].includes(hotTag)) {
    return `凉拌灵芹已经摆上头排，来客开始顺着“${shopTagLabel(hotTag)}”找这股新渠水气。`;
  }
  return "凉拌灵芹已经摆上头排，等第一位顾客把这股新渠水气带走。";
}

function shopCustomerShortReview(sale = null, hotTag = "", liveFocus = null) {
  if (!sale) return "";
  const tag = prioritizeShopTag(shopTagsForItem(sale.itemId || "", ecologyCourtyardSummary()), new Map(), hotTag || "food");
  const customerType = sale.customerArchetype || "";
  const tagLabel = shopTagLabel(tag || "food");
  const topItemName = liveFocus?.topItemName || itemName(sale.itemId || "");
  if (sale.itemId === "item_food_qingbo_yukuai") {
    if (customerType === "healer") return "鱼鲜处理得清，露珠芹压住腥气，拿去配诊也不扰药性。";
    if (customerType === "rogue_cultivator") return "这口轻，走远路也不坠胃，灵池水气倒挺醒神。";
    if (customerType === "trader") return "有鱼鲜、有水路故事，这样的货路上最好讲价也最好讲来历。";
    if (customerType === "guest") return "小铺能端出这种水鲜，门面一下就不一样了。";
    return "灵池这口鲜比凉菜更有记忆点，下回路过还想看有没有。";
  }
  if (customerType === "villager") {
    if (["staple", "food", "fresh_food"].includes(tag)) return "这一口踏实，拿回去就像今天没白忙。";
    if (["dessert", "drink"].includes(tag)) return "不贵还顺口，回去路上正好慢慢吃。";
    return `${topItemName}够稳当，带回去一家人都能吃得明白。`;
  }
  if (customerType === "rogue_cultivator") {
    if (["medicine", "clean_food", "herb"].includes(tag)) return "药气不冲，带在路上也让人安心。";
    if (["portable_food", "food_cold", "cooling"].includes(tag)) return "行路人就认这种不拖累脚程的东西。";
    return `这份${tagLabel}货收着不亏，路上总用得上。`;
  }
  if (customerType === "healer") {
    if (["medicine", "herb", "clean_food"].includes(tag)) return "火候和药气都干净，拿去配诊也稳。";
    return `${topItemName}处理得细，不像是随手摆上来的。`;
  }
  if (customerType === "crafter") {
    if (["material", "portable_food", "staple"].includes(tag)) return "做工的人认这种实在货，省事又顶用。";
    return `这份${topItemName}收得值，像是给忙人备的。`;
  }
  if (customerType === "trader") {
    if (["portable_food", "route_rare", "drink"].includes(tag)) return "这货拿得出手，也经得住路上来回看。";
    return `${topItemName}有记忆点，下回路过还想看看。`;
  }
  if (customerType === "guest") {
    if (["premium", "gift", "festival", "dessert"].includes(tag)) return "体面、顺眼，还真让人记住了这家小铺。";
    return `${topItemName}摆得像样，送人也不失礼。`;
  }
  if (customerType === "faction") {
    if (["premium", "ritual", "medicine", "batch"].includes(tag)) return "货色稳，分量也稳，往后这类单子还能再谈。";
    return `${topItemName}有规矩，掌柜是懂长线买卖的。`;
  }
  if (customerType === "child") {
    if (["dessert", "fresh_food", "low_price"].includes(tag)) return "这个闻着就开心，下次路过还想来找。";
    return `${topItemName}看着就想带走，回去要分给别人尝尝。`;
  }
  if (customerType === "pilgrim") {
    if (["ritual", "ecology_product", "spirit_crafted"].includes(tag)) return "这货不只是好看，拿在手里像真带了点洞天气。";
    return `${topItemName}是有心气的货，路上遇见就该收。`;
  }
  if (customerType === "collector") {
    if (["route_rare", "spirit_crafted", "ecology_product"].includes(tag)) return "这种货不是天天有，先收下再慢慢看它的来路。";
    return `${topItemName}有辨识度，算得上值得记一笔。`;
  }
  if (tag === "premium") return "看得出不是随便摆摆，掌柜是认真想过门面的。";
  if (["dessert", "drink"].includes(tag)) return `这份${tagLabel}货一入口，旧铺就像真有了招牌味。`;
  return `${topItemName}这股${tagLabel}气已经让人记住了。`;
}

function isQingboWaterFreshLead(leadItemName = "", itemId = "") {
  const label = String(leadItemName || "");
  return itemId === "item_food_qingbo_yukuai"
    || itemId === "item_food_lingchi_sanxian_geng"
    || itemId === "item_drink_helu_tangshui"
    || label.includes("清波鱼脍")
    || label.includes("灵池水鲜")
    || label.includes("莲泽熟路")
    || label.includes("水航");
}

function shopReturnVisitPreviewSpec(sale = null, openingFeedback = {}, options = {}) {
  if (!sale) return null;
  const customer = data.customers.find((entry) => entry.archetype === sale.customerArchetype) || null;
  const itemTag = prioritizeShopTag(
    shopTagsForItem(sale.itemId || "", ecologyCourtyardSummary()),
    new Map(),
    openingFeedback.hotTag || options.hotTag || "food",
  );
  const itemTagLabel = shopTagLabel(itemTag || "food");
  const customerLabel = sale.name || customerDisplayName(sale.customerArchetype || "") || "这类顾客";
  const revisitBase = Number(customer?.revisit_base || 0.3);
  const themeScoreRatio = Math.max(0, Math.min(1, Number(options.themeScore || openingFeedback.liveFocus?.themeScore || 0) / 100));
  const qingboWaterFresh = sale.itemId === "item_food_qingbo_yukuai";
  const matchedTagBonus = openingFeedback.hotTag && itemTag && openingFeedback.hotTag === itemTag ? 0.1 : 0.04;
  const firstSaleBonus = openingFeedback.firstSale ? 0.08 : 0.04;
  const waterFreshBonus = qingboWaterFresh ? 0.08 : 0;
  const revisitChance = Math.round(Math.min(0.95, revisitBase + themeScoreRatio * 0.22 + matchedTagBonus + firstSaleBonus + waterFreshBonus) * 100);
  const topItemName = openingFeedback.liveFocus?.topItemName || itemName(sale.itemId || "") || "这件货";
  const itemLine = sale.itemId ? itemName(sale.itemId) : topItemName || "这件货";
  const headline = qingboWaterFresh
    ? revisitChance >= 60 ? "水鲜回头客已经闻着路回来" : revisitChance >= 45 ? "灵池水鲜开始长出熟客线" : "再稳一轮就能立住水鲜招牌"
    : revisitChance >= 60 ? "回头客已经记住这味" : revisitChance >= 45 ? "回头客苗头已经出现" : "再稳一轮就会有回头客";
  const detail = qingboWaterFresh
    ? `${customerLabel}已经把清波鱼脍和旧铺连在一起，只要明早头排不断鱼鲜，这条灵池水鲜线就会从首卖长成回头客。`
    : revisitChance >= 60
      ? `${customerLabel}一类顾客已经记住 ${topItemName} 这股${itemTagLabel}气，只要货架别断，明天很容易再回来。`
      : revisitChance >= 45
        ? `${customerLabel}一类顾客已经开始认这口${itemTagLabel}味，明天继续摆在头排，就能把回头路接住。`
        : `${customerLabel}已经给出了第一条购买线索，再用一轮${itemTagLabel}货把这条线压实，回头客才会真正出现。`;
  const cta = qingboWaterFresh
    ? `先补 ${itemLine} x2，明早摆头排，把鱼、露珠芹和净水这条水鲜招牌线接住。`
    : revisitChance >= 60
      ? `继续备 ${itemLine} 或同类${itemTagLabel}货，别让头排断档。`
      : `把 ${itemLine} 和同类${itemTagLabel}货摆在更显眼的位置，再开一轮旧铺。`;
  return {
    customerLabel,
    itemTag,
    itemTagLabel,
    chance: revisitChance,
    headline,
    detail,
    cta,
    summary: qingboWaterFresh ? `${customerLabel}水鲜回头苗头 ${revisitChance}%` : `${customerLabel}一类顾客回头苗头 ${revisitChance}%`,
    tone: revisitChance >= 60 ? "good" : revisitChance >= 45 ? "mid" : "note",
  };
}

