function shopReturningCustomerTargets(opening = syncShopOpeningState()) {
  const safeOpening = normalizeShopOpeningState(opening);
  const sourceDay = Number(safeOpening.lastSession?.day || 0);
  if (!sourceDay || sourceDay >= state.day) return [];
  const board = safeOpening.regularBoard || safeOpening.lastSession?.regularBoard || safeOpening.history?.[0]?.regularBoard || null;
  if (!board?.rows?.length) return [];
  const qingboRestockTarget = safeOpening.restockTarget?.status === "active" && safeOpening.restockTarget.itemId === "item_food_qingbo_yukuai"
    ? safeOpening.restockTarget
    : null;
  const hotTagLabel = qingboRestockTarget ? "灵池水鲜" : board.hotTagLabel || safeOpening.hotTagLabel || safeOpening.lastSession?.hotTagLabel || "应季货";
  const leadItemName = qingboRestockTarget?.itemName || safeOpening.lastSession?.liveFocus?.topItemName || safeOpening.firstSale?.itemName || `${hotTagLabel}货`;
  return board.rows
    .filter((row) => Number(row.chance || 0) >= 45)
    .slice(0, 2)
    .map((row) => {
      const copy = shopReturningCustomerVisitCopy(row.customerArchetype, hotTagLabel, leadItemName, Number(row.chance || 0));
      return {
        customerArchetype: row.customerArchetype || "",
        customerLabel: row.customerLabel || customerDisplayName(row.customerArchetype || "") || "来客",
        chance: Number(row.chance || 0),
        headline: row.headline || `${row.customerLabel || "这类顾客"}又回门了`,
        quote: row.quote || "",
        hotTagLabel,
        leadItemName,
        ...copy,
      };
    });
}

