function shopWordOfMouthBulletinSpec(openingFeedback = {}) {
  const introducedRows = Array.isArray(openingFeedback.introducedCustomers) ? openingFeedback.introducedCustomers : [];
  const returningRows = Array.isArray(openingFeedback.returningCustomers) ? openingFeedback.returningCustomers : [];
  const introducedBought = introducedRows.filter((row) => row.bought);
  const returningBought = returningRows.filter((row) => row.bought);
  if (!introducedRows.length && !returningBought.length) return null;
  const sourceType = introducedRows.length > 0 ? "introduced" : "returning";
  const sourceLabels = [...new Set([
    ...introducedRows.map((row) => row.hostLabel || row.customerLabel || ""),
    ...returningRows.map((row) => row.customerLabel || ""),
  ].filter(Boolean))].slice(0, 3);
  const preferredArchetypes = [...new Set([
    ...introducedRows.map((row) => row.customerArchetype || ""),
    ...introducedRows.map((row) => row.hostArchetype || ""),
    ...returningBought.map((row) => row.customerArchetype || ""),
  ].filter(Boolean))].slice(0, 4);
  const preferredLabels = preferredArchetypes.map((archetype) => customerDisplayName(archetype)).filter(Boolean).slice(0, 4);
  const leadRow = introducedRows[0] || returningBought[0] || returningRows[0] || null;
  const hotTag = openingFeedback.hotTag || openingFeedback.liveFocus?.hotTag || "";
  const hotTagLabel = openingFeedback.hotTagLabel || openingFeedback.liveFocus?.hotTagLabel || shopTagLabel(hotTag || "food");
  const waterFreshRow = [...introducedBought, ...returningBought, ...introducedRows, ...returningRows]
    .find((row) => isQingboWaterFreshLead(row.itemName || "", row.itemId || ""));
  const leadItemName = waterFreshRow
    ? itemName("item_food_qingbo_yukuai")
    : openingFeedback.liveFocus?.topItemName
    || leadRow?.itemName
    || normalizeShopOpeningState(state.shopOpeningState).firstSale?.itemName
    || `${hotTagLabel || "应季"}货`;
  const qingboWaterFresh = Boolean(waterFreshRow) || isQingboWaterFreshLead(leadItemName, openingFeedback.liveFocus?.topItemId || "");
  const strongWord = introducedBought.length > 0 || introducedRows.length >= 2 || returningBought.length >= 2 || qingboWaterFresh;
  const baseVisitorBonus = sourceType === "introduced"
    ? Math.min(2, 1 + (introducedBought.length > 0 || introducedRows.length >= 2 ? 1 : 0))
    : Math.min(1, Math.max(0, returningBought.length));
  const visitorBonus = Math.min(qingboWaterFresh ? 3 : 2, baseVisitorBonus + (qingboWaterFresh ? 1 : 0));
  const budgetBonus = (sourceType === "introduced"
    ? strongWord ? 0.08 : 0.05
    : 0.04) + (qingboWaterFresh ? 0.03 : 0);
  const visitBias = (sourceType === "introduced"
    ? strongWord ? 0.18 : 0.12
    : 0.08) + (qingboWaterFresh ? 0.05 : 0);
  const tagVisitBias = hotTag ? (strongWord ? 0.12 : 0.08) + (qingboWaterFresh ? 0.03 : 0) : 0;
  const tagBudgetBonus = hotTag ? (sourceType === "introduced" ? 0.06 : 0.04) + (qingboWaterFresh ? 0.03 : 0) : 0;
  const createdDay = Number(state.day || 1);
  const headline = qingboWaterFresh
    ? sourceType === "introduced"
      ? `${sourceLabels[0] || "熟客"}把灵池水鲜顺嘴带给了新脚步`
      : `${sourceLabels[0] || "熟客"}把清波鱼脍这口水鲜传开了`
    : sourceType === "introduced"
      ? `${sourceLabels[0] || "熟客"}已经开始替旧铺带新脚步了`
      : `${sourceLabels[0] || "熟客"}把这家旧铺的回门劲继续传了下去`;
  const summary = qingboWaterFresh
    ? `${sourceLabels.join(" / ") || "熟客"}把清波鱼脍讲成了旧铺的灵池水鲜招牌，${preferredLabels.slice(0, 2).join(" / ") || "更多来客"}明日会顺着这口清凉来认门。`
    : sourceType === "introduced"
      ? `${sourceLabels.join(" / ") || "熟客"}把${leadItemName}和${hotTagLabel || "这排货"}顺嘴提给了${preferredLabels.slice(0, 2).join(" / ") || "更多来客"}。`
      : `${sourceLabels.join(" / ") || "熟客"}回门买单后，门口已经有人开始把${leadItemName}当成这家店的记号。`;
  const detail = qingboWaterFresh
    ? "明日这股话头会先把认鲜、认清口、认灵池来路的人往门前引一引，清波鱼脍不断档，水鲜招牌才会真的立住。"
    : sourceType === "introduced"
      ? `明日这股话头会先把${preferredLabels.slice(0, 3).join(" / ") || "对口来客"}往门前引一引，尤其是还记得${hotTagLabel || "这排货"}的人。`
      : `明日回门余温会继续托住${hotTagLabel || "这排货"}，让认这口味的人更愿意停下来看看。`;
  const nextAction = qingboWaterFresh
    ? "明天先把清波鱼脍留在显眼处，备鱼、露珠芹和净水，别让刚传开的灵池水鲜断档。"
    : `明天先把${leadItemName}留在显眼处${hotTagLabel ? `，把“${hotTagLabel}”这股味继续接住` : ""}，别让刚传出去的话头断掉。`;
  return normalizeShopWordOfMouth({
    id: `shop_word_${createdDay}_${sourceType}_${hotTag || (qingboWaterFresh ? "water_fresh" : preferredArchetypes[0]) || "note"}`,
    sourceType,
    createdDay,
    activeDay: createdDay + 1,
    expiresDay: createdDay + 2,
    hotTag,
    hotTagLabel,
    leadItemName,
    sourceLabels,
    preferredArchetypes,
    preferredLabels,
    introducedCount: introducedRows.length,
    returningCount: returningRows.length,
    soldCount: introducedBought.length + returningBought.length,
    visitorBonus,
    budgetBonus,
    visitBias,
    tagVisitBias,
    tagBudgetBonus,
    headline,
    summary,
    detail,
    nextAction,
    tone: strongWord ? "good" : "mid",
  });
}

function recordShopWordOfMouthBulletin(openingFeedback = {}) {
  state.shopStats = normalizeShopStats(state.shopStats);
  const bulletin = shopWordOfMouthBulletinSpec(openingFeedback);
  if (!bulletin) return null;
  state.shopStats.wordOfMouth = bulletin;
  const existingIndex = state.shopStats.wordOfMouthHistory.findIndex((entry) => entry.id === bulletin.id);
  if (existingIndex >= 0) state.shopStats.wordOfMouthHistory.splice(existingIndex, 1);
  state.shopStats.wordOfMouthHistory.unshift(bulletin);
  state.shopStats.wordOfMouthHistory = state.shopStats.wordOfMouthHistory.slice(0, 8);
  return bulletin;
}

function createWaterwayStandingTownWordOfMouth(spec = waterwayStandingOrderSupplySpec(), moment = null) {
  if (!spec?.active) return null;
  const createdDay = Number(state.day || 1);
  const focusItemName = spec.focusRow?.itemName || moment?.itemName || "莲泽熟路货";
  const stockedKinds = Number(spec.stockedKinds || 0);
  const totalStock = Number(spec.totalStock || 0);
  const sourceLabel = moment?.npcName || npcName("npc_qinghe");
  return normalizeShopWordOfMouth({
    id: `shop_word_${createdDay}_waterway_standing_${spec.focusRow?.itemId || "lianze"}`,
    sourceType: "waterway_standing",
    createdDay,
    activeDay: createdDay + 1,
    expiresDay: createdDay + 3,
    hotTag: "water_food",
    hotTagLabel: "莲泽熟路水鲜",
    leadItemName: focusItemName,
    sourceLabels: [sourceLabel, "莲泽水航客"],
    preferredArchetypes: ["waterway_broker", "trader", "guest"],
    preferredLabels: ["水航客", "行商", "贵客"],
    returningCount: Math.max(1, stockedKinds),
    soldCount: Math.max(1, totalStock),
    visitorBonus: spec.ready ? 2 : 1,
    budgetBonus: spec.ready ? 0.12 : 0.06,
    visitBias: spec.ready ? 0.22 : 0.12,
    tagVisitBias: spec.ready ? 0.16 : 0.08,
    tagBudgetBonus: spec.ready ? 0.08 : 0.04,
    headline: spec.ready ? "青禾把莲泽常单传成了旧铺认门路" : "青禾把莲泽常单话头先递出去了",
    summary: spec.ready
      ? `${sourceLabel}把旧铺 ${stockedKinds} 类 / ${totalStock} 件熟路货写进水路小簿，水航客明日会顺着“不断档”来认门。`
      : `${sourceLabel}把莲泽常单的话头递了出去，但旧铺还要先补厚水鲜、饮品或路线稀货。`,
    detail: spec.ready
      ? "明日铺前市闻会优先引来水航客与顺路行商；只要头排还有水鲜、饮品或路线稀货，就能把青禾后话兑现成可见来客。"
      : "这条市闻会先挂在门口，但若货架偏薄，水航客只会认路不认货。先补常单，再开铺接住。",
    nextAction: `明天开铺前把${focusItemName}或任意水鲜/饮品摆回头排，让“莲泽熟路不断档”从小簿变成成交。`,
    tone: spec.ready ? "good" : "mid",
  });
}

function recordWaterwayStandingTownWordOfMouth(spec = waterwayStandingOrderSupplySpec(), moment = null) {
  const bulletin = createWaterwayStandingTownWordOfMouth(spec, moment);
  if (!bulletin) return null;
  state.shopStats = normalizeShopStats(state.shopStats);
  state.shopStats.wordOfMouth = bulletin;
  const existingIndex = state.shopStats.wordOfMouthHistory.findIndex((entry) => entry.id === bulletin.id);
  if (existingIndex >= 0) state.shopStats.wordOfMouthHistory.splice(existingIndex, 1);
  state.shopStats.wordOfMouthHistory.unshift(bulletin);
  state.shopStats.wordOfMouthHistory = state.shopStats.wordOfMouthHistory.slice(0, 8);
  addLog("莲泽常单铺前市闻", `${bulletin.headline}：${bulletin.summary}`);
  return bulletin;
}

function activeShopWordOfMouthSpec(day = state.day, stats = normalizeShopStats(state.shopStats)) {
  const bulletin = normalizeShopWordOfMouth(stats.wordOfMouth);
  if (!bulletin) return null;
  const safeDay = Number(day || state.day || 1);
  if (safeDay < Number(bulletin.activeDay || 0) || safeDay > Number(bulletin.expiresDay || 0)) return null;
  const freshness = safeDay === Number(bulletin.activeDay || 0) ? 1 : 0.58;
  const baseVisitorBonus = Number(bulletin.visitorBonus || 0);
  return {
    ...bulletin,
    active: true,
    preview: false,
    freshness,
    visitorBonus: baseVisitorBonus > 0 ? Math.max(1, Math.round(baseVisitorBonus * freshness)) : 0,
    budgetBonus: Number(bulletin.budgetBonus || 0) * freshness,
    visitBias: Number(bulletin.visitBias || 0) * freshness,
    tagVisitBias: Number(bulletin.tagVisitBias || 0) * freshness,
    tagBudgetBonus: Number(bulletin.tagBudgetBonus || 0) * freshness,
    statusLabel: safeDay === Number(bulletin.activeDay || 0) ? "今日在传" : "余温还在",
  };
}

function shopWordOfMouthDisplaySpec(day = state.day, stats = normalizeShopStats(state.shopStats)) {
  const active = activeShopWordOfMouthSpec(day, stats);
  if (active) return active;
  const bulletin = normalizeShopWordOfMouth(stats.wordOfMouth);
  if (!bulletin) return null;
  const safeDay = Number(day || state.day || 1);
  if (safeDay === Number(bulletin.createdDay || 0) && Number(bulletin.activeDay || 0) === safeDay + 1) {
    return {
      ...bulletin,
      active: false,
      preview: true,
      freshness: 1,
      statusLabel: "明日会传开",
    };
  }
  return null;
}

function shopWordOfMouthVisitBias(customer, segment = null, spec = activeShopWordOfMouthSpec()) {
  const runtime = shopRuntime();
  if (runtime) return runtime.shopWordOfMouthVisitBias(customer, segment, spec);
  if (!customer || !spec) return 0;
  let bonus = 0;
  if ((spec.preferredArchetypes || []).includes(customer.archetype)) bonus += Number(spec.visitBias || 0);
  if (spec.hotTag) {
    const view = customerViewFor(customer, segment);
    const tags = expandShopSemanticTags(splitTags(view.preferred_tags || ""));
    if (shopTagsOverlap(tags, [spec.hotTag])) bonus += Number(spec.tagVisitBias || 0);
  }
  return bonus;
}

function shopWordOfMouthBudgetBonus(customer, choice = null, spec = activeShopWordOfMouthSpec()) {
  const runtime = shopRuntime();
  if (runtime) {
    const tags = choice ? shopTagsForItem(choice.itemId || choice.item || "", ecologyCourtyardSummary()) : [];
    return runtime.shopWordOfMouthBudgetBonus(customer, tags, spec);
  }
  if (!customer || !choice || !spec) return 0;
  let bonus = 0;
  if ((spec.preferredArchetypes || []).includes(customer.archetype)) bonus += Number(spec.budgetBonus || 0);
  if (spec.hotTag) {
    const tags = shopTagsForItem(choice.itemId || choice.item || "", ecologyCourtyardSummary());
    if (shopTagsOverlap(tags, [spec.hotTag])) bonus += Number(spec.tagBudgetBonus || 0);
  }
  return bonus;
}

function shopWordOfMouthCustomerNote(customer, spec = activeShopWordOfMouthSpec()) {
  if (!customer || !spec) return "";
  const leadSource = spec.sourceLabels?.[0] || "门口熟客";
  if ((spec.preferredArchetypes || []).includes(customer.archetype)) {
    return `${leadSource}把${spec.leadItemName || spec.hotTagLabel || "这排货"}顺嘴提给了${customerDisplayName(customer.archetype)}。`;
  }
  if (spec.hotTag) {
    return `门口正在传${spec.hotTagLabel || shopTagLabel(spec.hotTag)}这股味，${customerDisplayName(customer.archetype)}也多看了一眼。`;
  }
  return "";
}

function shopWordOfMouthMarkup(spec = shopWordOfMouthDisplaySpec()) {
  if (!spec) return "";
  const effectText = `${spec.preview ? "明日" : "今日"}来客 +${Math.max(0, Number(spec.visitorBonus || 0))}${Number(spec.budgetBonus || 0) > 0 ? ` · 对口成交预算 +${Math.round(Number(spec.budgetBonus || 0) * 100)}%` : ""}`;
  return `
    <div class="shop-word-of-mouth ${spec.tone} ${spec.preview ? "preview" : "active"}">
      <strong>铺前市闻 · ${spec.statusLabel}</strong>
      <span>${spec.headline}</span>
      <small>${spec.summary}</small>
      <small>${effectText}</small>
      <small>${spec.detail}</small>
      <small>掌柜建议：${spec.nextAction}</small>
    </div>
  `;
}

function shopWordOfMouthSummaryText(spec = activeShopWordOfMouthSpec()) {
  if (!spec) return "";
  return `${spec.headline}；来客 +${Math.max(0, Number(spec.visitorBonus || 0))}${Number(spec.budgetBonus || 0) > 0 ? `，对口预算 +${Math.round(Number(spec.budgetBonus || 0) * 100)}%` : ""}；${spec.nextAction}`;
}

function shopWordOfMouthVisitLeadSpec(spec = shopWordOfMouthDisplaySpec()) {
  if (!spec) return null;
  const targetArchetype = spec.preferredArchetypes?.[0] || "";
  const customerLabel = customerDisplayName(targetArchetype) || "来客";
  const hotTagLabel = spec.hotTagLabel || shopTagLabel(spec.hotTag || "food");
  const leadItemName = spec.leadItemName || `${hotTagLabel || "应季"}货`;
  const leadSource = spec.sourceLabels?.[0] || "门口熟客";
  const itemPrompt = leadItemName || `${hotTagLabel || "这排货"}`;
  const previewHeadline = `${customerLabel}明天很可能顺着这股市闻找来`;
  const activeHeadline = `${customerLabel}已经顺着这股市闻找上门`;
  const previewDetail = `${leadSource}把${itemPrompt}的口碑顺嘴提了出去，${customerLabel}明天会来认一认这排货。`;
  const activeDetail = `${leadSource}昨天传出去的话头已经落地，${customerLabel}今天会先盯着${itemPrompt}看。`;
  const cta = `先把${itemPrompt}留在头排${spec.hotTag ? `，再稳住“${hotTagLabel}”这股味` : ""}。`;
  return {
    sourceId: spec.id || "",
    customerArchetype: targetArchetype,
    customerLabel,
    sourceLabel: leadSource,
    hotTag: spec.hotTag || "",
    hotTagLabel,
    leadItemName,
    preview: Boolean(spec.preview),
    title: "铺前来帖",
    headline: spec.preview ? previewHeadline : activeHeadline,
    detail: spec.preview ? previewDetail : activeDetail,
    needText: `${customerLabel}多半是冲着${itemPrompt}来的。`,
    cta,
    tone: spec.tone || "mid",
  };
}

function shopWordOfMouthVisitSnapshot(leadSpec = null, report = [], openingFeedback = {}) {
  if (!leadSpec?.customerArchetype) return null;
  const reportEntry = (report || []).find((entry) => entry.customerArchetype === leadSpec.customerArchetype);
  return {
    ...leadSpec,
    preview: false,
    appeared: Boolean(reportEntry),
    bought: reportEntry?.reason === "buy",
    resultText: reportEntry
      ? `${reportEntry.text}${reportEntry.reason === "buy" ? ` ${leadSpec.customerLabel}真的顺着这张来帖进门买了。`
        : ` ${leadSpec.customerLabel}已经认了门，只是还在挑。`}`
      : `${leadSpec.customerLabel}今天还没现身，但这股市闻还会再挂一天。`,
  };
}

function shopWordOfMouthVisitMarkup(spec = null) {
  if (!spec) return "";
  return `
    <div class="shop-word-of-mouth-visit ${spec.tone || "mid"} ${spec.preview ? "preview" : spec.bought ? "good" : "active"}">
      <strong>${spec.title}</strong>
      <span>${spec.headline}</span>
      <small>${spec.appeared ? spec.resultText || spec.detail : spec.detail}</small>
      <small>${spec.needText}</small>
      <small>掌柜建议：${spec.cta}</small>
    </div>
  `;
}

function shopWordOfMouthVisitSummaryText(spec = null) {
  if (!spec) return "";
  if (spec.appeared) {
    return `${spec.customerLabel}${spec.bought ? " 已顺着市闻进门成交" : " 已顺着市闻来认门"}；${spec.cta}`;
  }
  return `${spec.customerLabel}明天会顺着市闻来认${spec.leadItemName || spec.hotTagLabel || "这排货"}；${spec.cta}`;
}

function shopWordOfMouthWorldNoteSpec(day = state.day) {
  const wordSpec = shopWordOfMouthDisplaySpec(day);
  const opening = normalizeShopOpeningState(state.shopOpeningState);
  const liveVisit = opening.lastSession?.day === state.day
    ? opening.lastSession.shopWordOfMouthVisit || null
    : null;
  const leadSpec = liveVisit || shopWordOfMouthVisitLeadSpec(wordSpec);
  if (!wordSpec && !leadSpec) return null;
  const visitActive = Boolean(leadSpec && !leadSpec.preview);
  const appeared = Boolean(leadSpec?.appeared);
  const bought = Boolean(leadSpec?.bought);
  const sourceLabel = leadSpec?.sourceLabel || wordSpec?.sourceLabels?.[0] || "门口熟客";
  const customerLabel = leadSpec?.customerLabel || customerDisplayName(wordSpec?.preferredArchetypes?.[0]) || "来客";
  const leadItemName = leadSpec?.leadItemName || wordSpec?.leadItemName || wordSpec?.hotTagLabel || "头排货";
  const title = bought
    ? "铺前来帖兑现 · 可点"
    : appeared || visitActive
      ? "铺前来帖认门 · 可点"
      : "铺前市闻来帖 · 可点";
  const detail = appeared
    ? leadSpec.resultText || leadSpec.detail || wordSpec?.detail || "这张来帖已经有客人认门。"
    : leadSpec?.detail || wordSpec?.detail || "这股铺前市闻正在往旧铺门口聚。";
  return {
    id: "shop_word_of_mouth_note",
    title,
    headline: leadSpec?.headline || wordSpec?.headline || `${customerLabel}会顺着市闻来认门`,
    detail,
    sourceLabel,
    customerLabel,
    leadItemName,
    statusLabel: bought ? "已成交" : appeared ? "已认门" : visitActive ? "今日来认门" : wordSpec?.statusLabel || "明日会传开",
    routeText: "谁传话 -> 谁来认门 -> 头排接货",
    safeNote: "只定位旧铺市闻和来帖，不会自动开铺、接客、成交、改价、补货或消耗材料",
    visitActive,
    appeared,
    bought,
    preview: Boolean(leadSpec?.preview || wordSpec?.preview),
    tone: leadSpec?.tone || wordSpec?.tone || "mid",
    selector: visitActive ? ".shop-word-of-mouth-visit" : ".shop-word-of-mouth",
    rect: { x: 38, y: 246, width: 332, height: 104 },
    anchor: { x: 146, y: 176 },
  };
}

function shopVisitPledgeRewardSpec(customerArchetype = "") {
  if (["guest", "faction", "collector"].includes(customerArchetype)) return { gold: 32, fame: 2 };
  if (["trader", "healer", "pilgrim", "crafter"].includes(customerArchetype)) return { gold: 24, fame: 1 };
  if (["rogue_cultivator"].includes(customerArchetype)) return { gold: 20, fame: 1 };
  return { gold: 16, fame: 1 };
}

function shopVisitPledgeSpec(leadSpec = null, openingFeedback = {}) {
  if (!leadSpec?.customerArchetype) return null;
  const reward = shopVisitPledgeRewardSpec(leadSpec.customerArchetype);
  const targetItemId = openingFeedback.liveFocus?.topItemId
    || normalizeShopOpeningState(state.shopOpeningState).firstSale?.itemId
    || "";
  const targetItemName = targetItemId ? itemName(targetItemId) : leadSpec.leadItemName || `${leadSpec.hotTagLabel || "应季"}货`;
  const createdDay = Number(state.day || 1);
  return normalizeShopVisitPledge({
    id: `shop_visit_pledge_${createdDay}_${leadSpec.customerArchetype || "guest"}`,
    status: "active",
    createdDay,
    activeDay: createdDay + 1,
    dueDay: createdDay + 2,
    customerArchetype: leadSpec.customerArchetype,
    customerLabel: leadSpec.customerLabel,
    sourceLabel: leadSpec.sourceLabel || "",
    hotTag: leadSpec.hotTag || "",
    hotTagLabel: leadSpec.hotTagLabel || "",
    targetItemId,
    targetItemName,
    rewardGold: reward.gold,
    rewardFame: reward.fame,
    headline: `${leadSpec.customerLabel}留下一张来帖`,
    detail: `${leadSpec.customerLabel}明后两天会来认${targetItemName || leadSpec.hotTagLabel || "这排货"}，若真接住，这笔顺口小赏也会留下。`,
    cta: `先把${targetItemName || leadSpec.hotTagLabel || "对口货"}摆在头排，接住这位${leadSpec.customerLabel}的来帖。`,
    note: `小赏：灵石 +${reward.gold} · 声望 +${reward.fame}`,
    tone: leadSpec.tone || "mid",
  });
}

function recordShopVisitPledge(openingFeedback = {}, leadSpec = null) {
  const opening = syncShopOpeningState();
  const current = normalizeShopVisitPledge(opening.visitPledge);
  if (current && current.status === "active" && state.day <= Number(current.dueDay || 0)) return current;
  const pledge = shopVisitPledgeSpec(leadSpec, openingFeedback);
  if (!pledge) return null;
  opening.visitPledge = pledge;
  return pledge;
}

function shopVisitPledgeDisplaySpec(opening = syncShopOpeningState()) {
  const pledge = normalizeShopVisitPledge(opening.visitPledge);
  if (!pledge) return null;
  const safeDay = Number(state.day || 1);
  if (pledge.status === "done" && pledge.fulfilledDay === safeDay) {
    return {
      ...pledge,
      preview: false,
      active: false,
      completed: true,
      failed: false,
      statusLabel: "今日已兑现",
    };
  }
  if (pledge.status === "expired" && pledge.expiredDay === safeDay) {
    return {
      ...pledge,
      preview: false,
      active: false,
      completed: false,
      failed: true,
      statusLabel: "今日落空",
    };
  }
  if (pledge.status !== "active") return null;
  if (safeDay < pledge.activeDay) {
    return {
      ...pledge,
      preview: true,
      active: false,
      completed: false,
      failed: false,
      statusLabel: "明日待接",
    };
  }
  if (safeDay <= pledge.dueDay) {
    return {
      ...pledge,
      preview: false,
      active: true,
      completed: false,
      failed: false,
      statusLabel: safeDay === pledge.activeDay ? "今日待接" : "最后一日",
    };
  }
  return null;
}

function shopVisitPledgeRouteCandidates(pledge = shopVisitPledgeDisplaySpec()) {
  if (!pledge) return [];
  if (pledge.targetItemId) {
    return shopRestockRouteCandidates({
      day: state.day,
      itemId: pledge.targetItemId,
      itemName: pledge.targetItemName,
      note: pledge.detail,
    });
  }
  if (pledge.hotTag) {
    return [{
      type: "shop",
      label: "看旧铺货签",
      title: pledge.hotTagLabel || "对口货",
      detail: `先围着${pledge.hotTagLabel || "这排货"}检查可卖库存和货签。`,
      action: "shop",
      shopTag: pledge.hotTag,
      score: 100,
    }];
  }
  return [];
}

function shopVisitPledgeMarkup(spec = shopVisitPledgeDisplaySpec()) {
  if (!spec) return "";
  const routes = shopVisitPledgeRouteCandidates(spec);
  return `
    <div class="shop-visit-pledge ${spec.completed ? "good" : spec.failed ? "warn" : spec.preview ? "preview" : "active"}">
      <strong>铺前来帖小约 · ${spec.statusLabel}</strong>
      <span>${spec.headline}</span>
      <small>${spec.resultText || spec.detail}</small>
      <small>${spec.note}</small>
      ${routes.length > 0 ? `
        <div class="shop-restock-routes">
          <strong>接帖路线</strong>
          ${routes.slice(0, 2).map((route) => `
            <div class="shop-restock-route ${route.type}">
              <b>${route.label} · ${route.title}</b>
              <small>${route.detail}</small>
              <button type="button" data-shop-restock-route="${route.action}" data-shop-restock-recipe="${route.recipeId || ""}" data-shop-restock-seed="${route.seedId || ""}" data-shop-restock-tag="${route.shopTag || ""}" data-shop-restock-item="${route.itemId || spec.targetItemId || ""}">${route.action === "recipe" ? "看配方" : route.action === "seed" ? "看种子" : "看旧铺货签"}</button>
            </div>
          `).join("")}
        </div>
      ` : ""}
      <small>掌柜建议：${spec.cta}</small>
    </div>
  `;
}

function shopVisitPledgeSummaryText(spec = null) {
  if (!spec) return "";
  if (spec.completed) return `${spec.customerLabel}的来帖已经兑现，额外获得灵石 +${spec.rewardGold} / 声望 +${spec.rewardFame}；${spec.cta}`;
  if (spec.failed) return `${spec.customerLabel}的来帖今天落空了；${spec.cta}`;
  return `${spec.customerLabel}的来帖还在等你接住；${spec.note}；${spec.cta}`;
}

function resolveShopVisitPledge(customers = [], report = [], opening = syncShopOpeningState()) {
  const pledge = normalizeShopVisitPledge(opening.visitPledge);
  if (!pledge || pledge.status !== "active") return null;
  if (state.day < pledge.activeDay || state.day > pledge.dueDay) return null;
  const appeared = (customers || []).some((customer) => customer.archetype === pledge.customerArchetype);
  const matchedEntry = (report || []).find((entry) => (
    entry.customerArchetype === pledge.customerArchetype
    && entry.reason === "buy"
    && (
      (pledge.targetItemId && entry.itemId === pledge.targetItemId)
      || (!pledge.targetItemId && pledge.hotTag && shopTagsOverlap(shopTagsForItem(entry.itemId || "", ecologyCourtyardSummary()), [pledge.hotTag]))
      || (!pledge.targetItemId && !pledge.hotTag)
    )
  )) || null;
  if (matchedEntry) {
    state.gold += pledge.rewardGold;
    state.fame += pledge.rewardFame;
    opening.visitPledge = normalizeShopVisitPledge({
      ...pledge,
      status: "done",
      fulfilledDay: state.day,
      resultText: `${pledge.customerLabel}按帖买走 ${matchedEntry.itemId ? itemName(matchedEntry.itemId) : pledge.targetItemName || "对口货"}，额外留下灵石 +${pledge.rewardGold} / 声望 +${pledge.rewardFame} 的顺口小赏。`,
    });
    return opening.visitPledge;
  }
  if (appeared || state.day >= pledge.dueDay) {
    opening.visitPledge = normalizeShopVisitPledge({
      ...pledge,
      status: "expired",
      expiredDay: state.day,
      resultText: appeared
        ? `${pledge.customerLabel}今天确实来了，但没被${pledge.targetItemName || pledge.hotTagLabel || "这排货"}留住。`
        : `${pledge.customerLabel}这张来帖挂了两天，门口的话头慢慢散掉了。`,
    });
    return opening.visitPledge;
  }
  return null;
}

function shopTownErrandRoleSpec(itemId = "", hotTag = "", customerLabel = "") {
  const tags = new Set(shopTagsForItem(itemId, ecologyCourtyardSummary()));
  const matching = (...keys) => keys.some((key) => tags.has(key) || hotTag === key);
  if (matching("medicine", "herb", "clean_food", "recover_sp", "recover_hp", "heal_hp", "heal_sp")) {
    return {
      npcId: "npc_baizhi",
      areaLabel: "医馆门口",
      title: "医馆顺带留药",
      tone: "good",
      requestText: `${customerLabel || "门口那位来客"}提过你家的${itemName(itemId)}，白芷便托人留话，想顺带留一份备在药柜边。`,
    };
  }
  if (matching("drink", "tea", "story", "dessert", "sweet_food", "honey", "festival")) {
    return {
      npcId: "npc_lu_sanxiao",
      areaLabel: "茶寮灯下",
      title: "茶寮添一口顺味",
      tone: "good",
      requestText: `${customerLabel || "来茶寮听书的人"}把你家的${itemName(itemId)}夸到了陆三笑耳边，他想顺手留一份让今晚的话头更顺。`,
    };
  }
  if (matching("ore", "metal", "copper", "iron", "tool")) {
    return {
      npcId: "npc_zhang_tieshan",
      areaLabel: "铁匠铺门前",
      title: "铁匠铺捎来一句",
      tone: "mid",
      requestText: `${customerLabel || "懂货的人"}提起你家的${itemName(itemId)}，张铁山想留一份压在案边，看看旧铺这手货稳不稳。`,
    };
  }
  if (matching("wood", "build", "material")) {
    return {
      npcId: "npc_atan",
      areaLabel: "木作棚边",
      title: "木作棚顺手留料",
      tone: "mid",
      requestText: `${customerLabel || "镇上的熟脸"}把${itemName(itemId)}的口碑带到了阿檀那里，她想顺手留一份搭今日草样。`,
    };
  }
  if (matching("refreshing", "water_food", "food_cold", "cooling", "fish", "pond")) {
    return {
      npcId: "npc_qinghe",
      areaLabel: "河岸浅桥",
      title: "河岸尝一口新鲜",
      tone: "good",
      requestText: `${customerLabel || "沿河走的人"}说你家的${itemName(itemId)}带着一股清水气，青禾想顺手留一份试试旧渠这阵水味。`,
    };
  }
  if (matching("gift", "premium", "trade", "route_rare", "portable_food")) {
    return {
      npcId: "npc_hu_sihai",
      areaLabel: "行脚摊旁",
      title: "行商留话试货",
      tone: "mid",
      requestText: `${customerLabel || "外来客"}把${itemName(itemId)}夸到了胡四海那边，他想顺手留一份，看看这手货能不能接上行脚路。`,
    };
  }
  return {
    npcId: "npc_xubo",
    areaLabel: "镇公所廊下",
    title: "镇上顺手留一份",
    tone: "mid",
    requestText: `${customerLabel || "门口熟脸"}把${itemName(itemId)}的口碑顺嘴带到了许伯耳边，他想顺手留一份，给值夜的人添口像样的热乎货。`,
  };
}

function shopTownErrandRewardSpec(itemId = "", npcId = "") {
  const tags = new Set(shopTagsForItem(itemId, ecologyCourtyardSummary()));
  const bulky = ["food", "staple", "fresh_food", "vegetable", "water_food"].some((tag) => tags.has(tag));
  const premium = ["gift", "premium", "route_rare", "medicine", "dessert", "trade"].some((tag) => tags.has(tag));
  const count = bulky && !premium ? 2 : 1;
  const gold = premium ? 40 : bulky ? 28 : 32;
  const fame = premium || npcId === "npc_hu_sihai" ? 1 : 0;
  const favor = npcId === "npc_xubo" ? 2 : premium ? 3 : 2;
  return { count, gold, fame, favor };
}

function shopTownErrandSpec(visitPledgeResult = null, openingFeedback = {}) {
  if (!visitPledgeResult || visitPledgeResult.status !== "done") return null;
  const requestItemId = visitPledgeResult.targetItemId
    || openingFeedback.liveFocus?.topItemId
    || normalizeShopOpeningState(state.shopOpeningState).firstSale?.itemId
    || "";
  if (!requestItemId) return null;
  const role = shopTownErrandRoleSpec(requestItemId, visitPledgeResult.hotTag || openingFeedback.hotTag || "", visitPledgeResult.customerLabel || "");
  const reward = shopTownErrandRewardSpec(requestItemId, role.npcId);
  const npcLabel = npcName(role.npcId);
  const requestItemName = itemName(requestItemId);
  const createdDay = Number(state.day || 1);
  return normalizeShopTownErrand({
    id: `shop_town_errand_${createdDay}_${role.npcId || "town"}`,
    status: "active",
    createdDay,
    activeDay: createdDay + 1,
    dueDay: createdDay + 2,
    npcId: role.npcId,
    npcLabel,
    areaLabel: role.areaLabel,
    sourceLabel: visitPledgeResult.customerLabel || visitPledgeResult.sourceLabel || "旧铺门前",
    customerLabel: visitPledgeResult.customerLabel || "",
    hotTag: visitPledgeResult.hotTag || openingFeedback.hotTag || "",
    hotTagLabel: visitPledgeResult.hotTagLabel || openingFeedback.hotTagLabel || "",
    requestItemId,
    requestItemName,
    count: reward.count,
    rewardGold: reward.gold,
    rewardFame: reward.fame,
    rewardFavor: reward.favor,
    headline: `${npcLabel}从${role.areaLabel}捎来一句话`,
    detail: `${role.requestText} 明后两天若顺手送去，${npcLabel}也会把这份旧铺口碑记在心上。`,
    requestText: role.requestText,
    cta: `先备好 ${requestItemName} x${reward.count}，再去关系面板看 ${npcLabel} 今天在哪里。`,
    note: `回礼：灵石 +${reward.gold}${reward.fame ? ` · 声望 +${reward.fame}` : ""} · 好感 +${reward.favor}`,
    tone: role.tone,
  });
}

function resolveShopTownErrandLifecycle(opening = syncShopOpeningState()) {
  const errand = normalizeShopTownErrand(opening.townErrand);
  if (!errand || errand.status !== "active") return errand;
  if (state.day <= Number(errand.dueDay || 0)) return errand;
  opening.townErrand = normalizeShopTownErrand({
    ...errand,
    status: "expired",
    expiredDay: state.day,
    resultText: `${errand.npcLabel}等了两天，这句关于${errand.requestItemName || "旧铺货"}的捎话先慢慢散掉了。`,
  });
  if (opening.lastSession?.day === state.day) opening.lastSession.townErrand = opening.townErrand;
  if (opening.history[0]?.day === state.day) opening.history[0].townErrand = opening.townErrand;
  return opening.townErrand;
}

function recordShopTownErrand(openingFeedback = {}, visitPledgeResult = null) {
  const opening = syncShopOpeningState();
  const current = resolveShopTownErrandLifecycle(opening);
  if (current && current.status === "active" && state.day <= Number(current.dueDay || 0)) return current;
  if (current && current.status === "done" && Number(current.fulfilledDay || 0) === state.day) return current;
  const errand = shopTownErrandSpec(visitPledgeResult, openingFeedback);
  if (!errand) return null;
  opening.townErrand = errand;
  if (opening.lastSession?.day === state.day) opening.lastSession.townErrand = errand;
  if (opening.history[0]?.day === state.day) opening.history[0].townErrand = errand;
  return errand;
}

function shopTownErrandDisplaySpec(opening = syncShopOpeningState()) {
  const current = resolveShopTownErrandLifecycle(opening);
  const errand = normalizeShopTownErrand(current);
  if (!errand) return null;
  const safeDay = Number(state.day || 1);
  const have = errand.requestItemId ? Number(state.inventory[errand.requestItemId] || 0) : 0;
  const ready = have >= Number(errand.count || 1);
  if (errand.status === "done" && errand.fulfilledDay === safeDay) {
    return {
      ...errand,
      have,
      ready,
      preview: false,
      active: false,
      completed: true,
      failed: false,
      statusLabel: "今日已送到",
    };
  }
  if (errand.status === "expired" && errand.expiredDay === safeDay) {
    return {
      ...errand,
      have,
      ready,
      preview: false,
      active: false,
      completed: false,
      failed: true,
      statusLabel: "今日落空",
    };
  }
  if (errand.status !== "active") return null;
  if (safeDay < errand.activeDay) {
    return {
      ...errand,
      have,
      ready,
      preview: true,
      active: false,
      completed: false,
      failed: false,
      statusLabel: "明日可送",
    };
  }
  if (safeDay <= errand.dueDay) {
    return {
      ...errand,
      have,
      ready,
      preview: false,
      active: true,
      completed: false,
      failed: false,
      statusLabel: safeDay === errand.activeDay ? "今日待送" : "最后一日",
    };
  }
  return null;
}

function shopTownErrandRouteCandidates(errand = shopTownErrandDisplaySpec()) {
  if (!errand || !errand.requestItemId) return [];
  return shopRestockRouteCandidates({
    day: state.day,
    itemId: errand.requestItemId,
    itemName: errand.requestItemName,
    note: errand.detail,
  });
}

function shopTownErrandPrimaryActionSpec(errand = shopTownErrandDisplaySpec()) {
  if (!errand || errand.completed || errand.failed) return null;
  if (errand.active && errand.ready) {
    return { mode: "deliver", label: "交付捎话" };
  }
  const route = shopTownErrandRouteCandidates(errand)[0] || null;
  if (route) {
    return {
      mode: "route",
      label: route.action === "recipe" ? "看配方" : route.action === "seed" ? "看种子" : "看旧铺货签",
      route,
    };
  }
  return {
    mode: "focus",
    label: "看镇上动线",
  };
}

function shopTownErrandButtonsMarkup(spec = shopTownErrandDisplaySpec(), { includeFocus = false } = {}) {
  if (!spec || spec.completed || spec.failed) return "";
  const primary = shopTownErrandPrimaryActionSpec(spec);
  const buttons = [];
  if (primary) {
    buttons.push(`
      <button type="button" data-shop-town-errand-action="${primary.mode}" data-shop-town-errand-route="${primary.route?.action || ""}" data-shop-town-errand-recipe="${primary.route?.recipeId || ""}" data-shop-town-errand-seed="${primary.route?.seedId || ""}" data-shop-town-errand-tag="${primary.route?.shopTag || ""}" data-shop-town-errand-item="${primary.route?.itemId || spec.requestItemId || ""}">${primary.label}</button>
    `);
  }
  if (includeFocus && (!primary || primary.mode !== "focus")) {
    buttons.push('<button type="button" data-shop-town-errand-action="focus">看镇上动线</button>');
  }
  return buttons.length ? `<div class="shop-town-errand-actions">${buttons.join("")}</div>` : "";
}

function shopTownErrandMarkup(spec = shopTownErrandDisplaySpec(), options = {}) {
  if (!spec) return "";
  const routes = shopTownErrandRouteCandidates(spec);
  return `
    <div class="shop-town-errand ${spec.completed ? "good" : spec.failed ? "warn" : spec.preview ? "preview" : spec.ready ? "good" : "active"}">
      <strong>镇上捎话 · ${spec.statusLabel}</strong>
      <span>${spec.headline}</span>
      <small>${spec.resultText || spec.detail}</small>
      <small>备货：${spec.requestItemName} ${spec.have}/${spec.count} · ${spec.note}</small>
      ${routes.length > 0 ? `
        <div class="shop-restock-routes">
          <strong>顺手备货</strong>
          ${routes.slice(0, 2).map((route) => `
            <div class="shop-restock-route ${route.type}">
              <b>${route.label} · ${route.title}</b>
              <small>${route.detail}</small>
            </div>
          `).join("")}
        </div>
      ` : ""}
      ${shopTownErrandButtonsMarkup(spec, options)}
      <small>掌柜建议：${spec.cta}</small>
    </div>
  `;
}

function shopTownErrandSummaryText(spec = null) {
  if (!spec) return "";
  if (spec.completed) return `${spec.npcLabel}的捎话已经送到，回礼 ${spec.rewardGold} 灵石${spec.rewardFame ? ` / 声望 +${spec.rewardFame}` : ""} / 好感 +${spec.rewardFavor}。`;
  if (spec.failed) return `${spec.npcLabel}那句关于${spec.requestItemName || "旧铺货"}的捎话今天落空了。`;
  return `${spec.npcLabel}还在等 ${spec.requestItemName} ${spec.have || 0}/${spec.count}；${spec.note}。`;
}

function shopReputationStageSpec(opening = syncShopOpeningState(), stats = normalizeShopStats(state.shopStats), townState = syncTownLifeInteractionState()) {
  const safeOpening = normalizeShopOpeningState(opening);
  const safeStats = normalizeShopStats(stats);
  const safeTown = townState || syncTownLifeInteractionState();
  const session = safeOpening.lastSession || null;
  const history = Array.isArray(safeOpening.history) ? safeOpening.history : [];
  const historyMatch = (field, predicate = (value) => Boolean(value)) => history.find((entry) => predicate(entry?.[field]))?.[field] || null;
  const regularBoard = normalizeShopRegularBoard(safeOpening.regularBoard || session?.regularBoard || historyMatch("regularBoard"));
  const returningRows = [
    ...(safeOpening.returningCustomers || []),
    ...(session?.returningCustomers || []),
    ...history.flatMap((entry) => Array.isArray(entry.returningCustomers) ? entry.returningCustomers : []),
  ].map((entry) => normalizeShopReturningCustomerVisit(entry)).filter(Boolean);
  const introducedRows = [
    ...(safeOpening.introducedCustomers || []),
    ...(session?.introducedCustomers || []),
    ...history.flatMap((entry) => Array.isArray(entry.introducedCustomers) ? entry.introducedCustomers : []),
  ].map((entry) => normalizeShopIntroducedCustomerVisit(entry)).filter(Boolean);
  const visitPledge = normalizeShopVisitPledge(safeOpening.visitPledge || session?.visitPledge || historyMatch("visitPledge"));
  const townErrand = normalizeShopTownErrand(safeOpening.townErrand || session?.townErrand || historyMatch("townErrand"));
  const wordHistory = Array.isArray(safeStats.wordOfMouthHistory) ? safeStats.wordOfMouthHistory.map((entry) => normalizeShopWordOfMouth(entry)).filter(Boolean) : [];
  const wordOfMouth = normalizeShopWordOfMouth(safeStats.wordOfMouth) || wordHistory[0] || null;
  const shopMoment = safeTown?.lastShopMoment || (Array.isArray(safeTown?.shopMomentHistory) ? safeTown.shopMomentHistory[0] : null);
  const firstSale = safeOpening.firstSale || session?.firstSale || null;
  const hotTagLabel = safeOpening.hotTagLabel || session?.hotTagLabel || regularBoard?.hotTagLabel || wordOfMouth?.hotTagLabel || "应季货";
  const leadItemName = firstSale?.itemName || wordOfMouth?.leadItemName || visitPledge?.targetItemName || townErrand?.requestItemName || `${hotTagLabel}货`;
  const evidence = [
    {
      key: "first_sale",
      label: "首单",
      active: Boolean(safeOpening.summaryUnlocked || firstSale),
      proof: firstSale ? `${firstSale.name || "第一位顾客"}买走${firstSale.itemName || leadItemName}` : "第一笔成交已经写进账页",
      next: "先完成一次开铺成交，让旧铺有第一句可被记住的话。",
    },
    {
      key: "regular_board",
      label: "留言墙",
      active: Boolean(regularBoard?.rows?.length),
      proof: regularBoard?.rows?.[0] ? `${regularBoard.rows[0].customerLabel}回头苗头 ${regularBoard.rows[0].chance}%` : "熟客苗头已经能被看见",
      next: `继续围着${hotTagLabel}补货，把顾客记住的理由写到熟客留言墙。`,
    },
    {
      key: "returning",
      label: "熟脸",
      active: returningRows.length > 0,
      proof: returningRows[0] ? `${returningRows[0].customerLabel}${returningRows[0].bought ? `又买走${returningRows[0].itemName || "一件货"}` : "回门看货"}` : "有熟脸愿意再进门",
      next: `别让${leadItemName}断档，先接住昨天记得这口味的人。`,
    },
    {
      key: "introduced",
      label: "新客",
      active: introducedRows.length > 0,
      proof: introducedRows[0] ? `${introducedRows[0].hostLabel || "熟客"}带来${introducedRows[0].customerLabel}` : "熟客开始带新脚步",
      next: "把熟客夸过的货摆到头排，让新客一进门就看见理由。",
    },
    {
      key: "word_of_mouth",
      label: "市闻",
      active: Boolean(wordOfMouth),
      proof: wordOfMouth?.headline || "铺前已经有人顺嘴传话",
      next: `接住${hotTagLabel}这股话头，明天先稳住对口客群。`,
    },
    {
      key: "visit_pledge",
      label: "来帖",
      active: Boolean(visitPledge),
      proof: visitPledge ? `${visitPledge.customerLabel}留下${visitPledge.targetItemName || visitPledge.hotTagLabel || "对口货"}小约` : "来帖开始变成可追踪的小目标",
      next: "等铺前来帖出现后，按小约备货并在期限内接住。",
    },
    {
      key: "town_errand",
      label: "捎话",
      active: Boolean(townErrand),
      proof: townErrand ? `${townErrand.npcLabel}托了${townErrand.requestItemName || "一件旧铺货"}` : "镇上还没把旧铺当成可托付的地方",
      next: "完成来帖后，把顺手货送进镇上人的日常里。",
    },
    {
      key: "shop_afterword",
      label: "后话",
      active: Boolean(shopMoment),
      proof: shopMoment ? `${shopMoment.npcName || shopMoment.npcLabel || "镇民"}：${shopMoment.sceneTag || shopMoment.title || "旧铺后话"}` : "旧铺影响还没落成镇上生活后话",
      next: "把镇上捎话办妥，让关系册写下一页旧铺后话。",
    },
  ];
  const completedEvidence = evidence.filter((entry) => entry.active);
  const progressCount = completedEvidence.length;
  const stageTable = [
    {
      min: 8,
      stageKey: "town_line",
      stageName: "旧铺真成了一条线",
      headline: "旧铺不只在卖货，已经把熟客、新客和镇上托付串成了凡仙镇的一段日常。",
      detail: `从${leadItemName}到${hotTagLabel}，有人进门、有人传话，也有人在夜里记得这份照应。`,
      tone: "complete",
    },
    {
      min: 7,
      stageKey: "town_trust",
      stageName: "镇上有人肯托付",
      headline: "旧铺的货已经走出柜台，开始被镇上的人拿去解决真实小事。",
      detail: `这一步让经营从“卖给顾客”变成“被镇上用得上”，名声开始有了生活重量。`,
      tone: "trust",
    },
    {
      min: 5,
      stageKey: "word_spreads",
      stageName: "话头能传出去",
      headline: "门口的话已经能传到第二天，旧铺开始有了不用自己吆喝的客流。",
      detail: `接下来要把${hotTagLabel}这股味接稳，让来帖和小约变成更具体的备货目标。`,
      tone: "spread",
    },
    {
      min: 3,
      stageKey: "regulars_return",
      stageName: "熟脸开始回头",
      headline: "有人不只是买过一次，而是开始带着记忆重新走到门前。",
      detail: `把${leadItemName}留在显眼处，熟脸回门和熟客带新客会让旧铺更像真的开起来了。`,
      tone: "return",
    },
    {
      min: 1,
      stageKey: "known_door",
      stageName: "开门有人认",
      headline: "第一笔成交已经让旧铺有了名字，顾客开始把货和这扇门连在一起。",
      detail: `现在要把首单从一次收入，养成一批愿意回头的熟脸。`,
      tone: "start",
    },
    {
      min: 0,
      stageKey: "quiet_sign",
      stageName: "旧铺还在擦招牌",
      headline: "柜台已经摆好，但旧铺名声还没有真正落到顾客记忆里。",
      detail: "先准备一件标签清楚的作物或菜品，开铺完成第一笔成交。",
      tone: "quiet",
    },
  ];
  const stage = stageTable.find((entry) => progressCount >= entry.min) || stageTable[stageTable.length - 1];
  const nextEvidence = evidence.find((entry) => !entry.active) || null;
  const recentProofs = completedEvidence.slice(-3).map((entry) => entry.proof).filter(Boolean);
  return {
    ...stage,
    progressCount,
    progressTotal: evidence.length,
    progressPercent: Math.round((progressCount / Math.max(1, evidence.length)) * 100),
    hotTagLabel,
    leadItemName,
    nextGoal: nextEvidence ? `${nextEvidence.label}：${nextEvidence.next}` : "继续经营、送货和回看后话，把这条旧铺来往养成第二年名铺赛季的底气。",
    chips: evidence.map((entry) => ({
      key: entry.key,
      label: entry.label,
      active: entry.active,
      proof: entry.proof,
    })),
    recentProofs,
    metricsText: `${progressCount}/${evidence.length} 条名声证据`,
  };
}

function shopReputationStageMarkup(spec = shopReputationStageSpec()) {
  if (!spec) return "";
  return `
    <div class="shop-reputation-stage ${spec.tone}" data-shop-reputation-stage="${spec.stageKey}">
      <div class="shop-reputation-stage-head">
        <strong>旧铺名声 · ${spec.stageName}</strong>
        <b>${spec.metricsText}</b>
      </div>
      <span>${spec.headline}</span>
      <small>${spec.detail}</small>
      <div class="shop-reputation-stage-meter"><i style="width:${spec.progressPercent}%"></i></div>
      <div class="shop-reputation-stage-chips">
        ${spec.chips.map((chip) => `<b class="${chip.active ? "done" : "todo"}">${chip.label}</b>`).join("")}
      </div>
      ${spec.recentProofs.length > 0 ? `<small>最近证据：${spec.recentProofs.join("；")}</small>` : ""}
      <small>下一步：${spec.nextGoal}</small>
    </div>
  `;
}

function shopReputationStageSummaryText(spec = shopReputationStageSpec()) {
  if (!spec || spec.progressCount <= 0) return "";
  return `${spec.stageName}（${spec.metricsText}）：${spec.headline}；下一步：${spec.nextGoal}`;
}

function shopReputationTownBarkSpec(row = null, spec = shopReputationStageSpec()) {
  if (!row || !spec || spec.progressCount <= 0 || row.status?.key === "away") return null;
  const npcId = row.npc?.npc_id || "";
  const name = npcName(npcId);
  const hotTag = spec.hotTagLabel || "应季货";
  const leadItem = spec.leadItemName || `${hotTag}货`;
  const afterword = latestTownLifeShopMoment(npcId);
  const stageLines = {
    known_door: {
      label: "认得旧铺",
      line: `${name}从铺前经过，念叨刚有人提起那件${leadItem}。`,
      detail: `旧铺名声刚起，${name}已经把“这扇门”和${leadItem}连在一起。`,
      bubble: `听说${leadItem}`,
      tone: "start",
    },
    regulars_return: {
      label: "熟脸回门",
      line: `${name}看了眼旧铺招牌，说${hotTag}的熟脸今天可能还会回头。`,
      detail: `熟客开始回门，镇民会更常顺口提醒你稳住${hotTag}备货。`,
      bubble: "熟脸会回",
      tone: "return",
    },
    word_spreads: {
      label: "话头传开",
      line: `${name}把街口听来的话捎给你：旧铺这阵子的${hotTag}有人在问。`,
      detail: `旧铺的话头已经传出去，镇上动线会出现更多顺路打听。`,
      bubble: `${hotTag}有人问`,
      tone: "spread",
    },
    town_trust: {
      label: "镇上肯托",
      line: `${name}说镇里有人愿意把小事托给旧铺，别让${leadItem}断了线。`,
      detail: `旧铺的货开始被镇上用来办真实小事，托付感会压到日常动线里。`,
      bubble: "旧铺能托",
      tone: "trust",
    },
    town_line: {
      label: "旧铺成线",
      line: `${name}路过时笑了笑：如今提起${hotTag}，大家会先想起这间旧铺。`,
      detail: `熟客、新客和镇上托付已经串成一条生活线，旧铺名声有了稳定回声。`,
      bubble: "旧铺成线",
      tone: "complete",
    },
  };
  const picked = afterword
    ? {
      label: "旧铺后话",
      line: `${name}还记着旧铺那页后话：${afterword.sceneTag || afterword.title || "顺手照应"}。`,
      detail: `${afterword.summary || "这页后话让旧铺和镇上人的生活更接近了一点。"}${afterword.rewardText ? ` · ${afterword.rewardText}` : ""}`,
      bubble: afterword.sceneTag || "旧铺后话",
      tone: "afterword",
    }
    : stageLines[spec.stageKey] || null;
  if (!picked) return null;
  return {
    ...picked,
    stageName: spec.stageName,
    metricsText: spec.metricsText,
    npcId,
  };
}

