function shopTownErrandDialogueLine(errand = null, feedback = null) {
  if (!errand) return "这份顺手货我先收下了。";
  const base = feedback?.dialogueBase || shopTownErrandNarrativeSpec(errand, feedback).dialogueBase;
  if (feedback?.memoryTitle) return `${base} 还有，${feedback.memoryTitle}这件事，我也记下了。`;
  if (feedback?.favorLeveled) return `${base} 往后这类顺手事，你也可以先来找我。`;
  return base;
}

function shopTownErrandFeedbackSpec(errand = null, { favorBefore = 0, favorAfter = 0, unlockedMemories = [] } = {}) {
  if (!errand) return null;
  const favorBeforeLevel = favorLevel(favorBefore);
  const favorAfterLevel = favorLevel(favorAfter);
  const memory = unlockedMemories[0] || null;
  const narrative = shopTownErrandNarrativeSpec(errand, { memoryTitle: memory?.title || "" });
  return {
    id: errand.id || `shop_town_feedback_${errand.npcId || "npc"}_${state.day}`,
    npcId: errand.npcId,
    npcLabel: errand.npcLabel,
    title: narrative.feedbackTitle,
    itemName: errand.requestItemName,
    count: errand.count,
    areaLabel: errand.areaLabel,
    rewardGold: errand.rewardGold,
    rewardFame: errand.rewardFame,
    rewardFavor: errand.rewardFavor,
    favorBefore,
    favorAfter,
    favorLeveled: favorAfterLevel > favorBeforeLevel,
    memoryTitle: memory?.title || "",
    memorySummary: memory?.summary || "",
    sceneTag: narrative.sceneTag,
    followup: narrative.followup,
    dialogueBase: narrative.dialogueBase,
    momentTitle: narrative.momentTitle,
    momentSummary: narrative.momentSummary,
    response: favorAfterLevel > favorBeforeLevel
      ? `${narrative.responseBase} 关系升到 Lv.${favorAfterLevel}。`
      : `${narrative.responseBase} 好感 +${errand.rewardFavor}。`,
    detail: narrative.detail,
    line: "",
    nextAdvice: memory
      ? `关系册已经写下「${memory.title}」，${narrative.nextAdvice}`
      : narrative.nextAdvice,
    day: state.day,
    createdAt: performance.now(),
  };
}

function townLifeErrandFeedbackSpec(errand = null, weatherEcho = null, { favorBefore = 0, favorAfter = 0, unlockedMemories = [] } = {}) {
  if (!errand) return null;
  const favorBeforeLevel = favorLevel(favorBefore);
  const favorAfterLevel = favorLevel(favorAfter);
  const memory = unlockedMemories[0] || null;
  const npcLabel = errand.npcName || npcName(errand.npcId);
  const itemLabel = errand.itemName || itemName(errand.itemId);
  const weatherLabel = weatherEcho?.label || errand.weatherLabel || "";
  const weatherSummary = weatherEcho?.summary || (weatherLabel
    ? `${weatherLabel}这件小事在镇上留下了一点回响。`
    : `${npcLabel}把这份顺手照应记进了今日来往。`);
  const favorLeveled = favorAfterLevel > favorBeforeLevel;
  return {
    id: `${errand.key || errand.npcId || "npc"}:${state.day}:town_life_errand_feedback`,
    npcId: errand.npcId,
    npcName: npcLabel,
    title: "小托付回礼",
    headline: "托付办妥",
    itemName: itemLabel,
    count: Number(errand.count || 1),
    areaLabel: errand.area || "凡仙镇",
    actionLabel: errand.action || "日常",
    rewardGold: Number(errand.rewardGold || 0),
    rewardFame: Number(errand.rewardFame || 0),
    rewardFavor: Number(errand.rewardFavor || 0),
    favorBefore,
    favorAfter,
    favorLeveled,
    favorLevel: favorAfterLevel,
    memoryTitle: memory?.title || "",
    memorySummary: memory?.summary || "",
    weatherLabel,
    weatherTone: weatherEcho?.tone || errand.weatherTone || "gold",
    weatherSummary,
    weatherHint: weatherEcho?.weatherHint || errand.weatherHint || "",
    response: memory
      ? `关系册写下「${memory.title}」。`
      : favorLeveled
        ? `好感升到 Lv.${favorAfterLevel}。`
        : `好感 ${favorAfter}/100。`,
    detail: errand.request || weatherSummary,
    day: state.day,
    createdAt: performance.now(),
  };
}

function shopTownErrandMomentSpec(errand = null, feedback = null) {
  if (!errand || !feedback) return null;
  return normalizeTownLifeShopMoment({
    day: state.day,
    npcId: errand.npcId,
    npcName: errand.npcLabel,
    itemId: errand.requestItemId,
    itemName: errand.requestItemName,
    count: errand.count,
    title: feedback.momentTitle || `${errand.npcLabel}把旧铺这口货记住了`,
    summary: feedback.momentSummary || (feedback.memoryTitle
      ? `${errand.npcLabel}收下 ${errand.requestItemName} 后，顺手把「${feedback.memoryTitle}」这件事也写进了关系册。`
      : `${errand.npcLabel}收下 ${errand.requestItemName}，旧铺和镇上的来往因此更像一条会回声的路。`),
    detail: feedback.line || feedback.detail || `${errand.npcLabel}在${errand.areaLabel}接住了这份顺手货。`,
    line: feedback.line || "",
    area: errand.areaLabel,
    rewardText: `${errand.rewardGold} 灵石${errand.rewardFame ? ` · 声望 +${errand.rewardFame}` : ""} · 好感 +${errand.rewardFavor}`,
    memoryTitle: feedback.memoryTitle || "",
    sceneTag: feedback.sceneTag || "",
    followup: feedback.followup || "",
    favorAfter: feedback.favorAfter || 0,
    fresh: true,
  });
}

function queueShopTownErrandDialogue(feedback = state.shopTownErrandFeedback) {
  if (!feedback) return;
  const errand = normalizeShopTownErrand(syncShopOpeningState().townErrand) || null;
  const line = shopTownErrandDialogueLine(errand, feedback);
  feedback.line = line;
  state.shopTownErrandFeedback = feedback;
  state.activeDialogue = [
    ...state.activeDialogue.slice(-3),
    {
      speakerId: feedback.npcId,
      speaker: feedback.npcLabel,
      text: line,
      groupId: `shop_town_errand_${feedback.id}`,
      lineOrder: 0,
    },
  ];
  playCue("对话翻页");
}

function focusShopTownErrandNpc(npcId = "") {
  const row = townLifeRows(12).find((entry) => entry.npc.npc_id === npcId);
  if (row) return focusTownLifeNpcFromCanvas(row);
  if (settings.panelGroup !== "systems") {
    settings.panelGroup = "systems";
    saveSettings();
  }
  addLog("镇上捎话", `${npcName(npcId)}今天的动线已经展开到关系面板里了。`);
  render();
  return true;
}

function completeShopTownErrand() {
  const opening = syncShopOpeningState();
  const errand = shopTownErrandDisplaySpec(opening);
  if (!errand) {
    addLog("镇上捎话", "这会儿没有正在等你接的镇上捎话。");
    render();
    return;
  }
  if (errand.preview) {
    addLog("镇上捎话", `${errand.npcLabel}的这句捎话要到明天才正式算数，今晚先把${errand.requestItemName}备出来。`);
    render();
    return;
  }
  if (errand.completed) {
    addLog("镇上捎话", `${errand.npcLabel}的这句捎话今天已经送到了。`);
    render();
    return;
  }
  if (errand.failed) {
    addLog("镇上捎话", `${errand.npcLabel}的这句捎话已经散掉了，等下一阵旧铺口碑再接回来。`);
    render();
    return;
  }
  if (!hasItem(errand.requestItemId, errand.count)) {
    addLog("镇上捎话", `${errand.npcLabel}还在等 ${errand.requestItemName} ${errand.have}/${errand.count}。先按备货路线补一补。`);
    render();
    return;
  }
  addItem(errand.requestItemId, -Number(errand.count || 1));
  const favorBefore = Number(state.npcFavor[errand.npcId] || 0);
  const memoryBeforeId = latestTownLifeMemory(errand.npcId)?.memoryId || "";
  state.gold += Number(errand.rewardGold || 0);
  state.fame += Number(errand.rewardFame || 0);
  addNpcFavor(errand.npcId, Number(errand.rewardFavor || 0), `镇上捎话 · ${errand.requestItemName}`);
  opening.townErrand = normalizeShopTownErrand({
    ...errand,
    status: "done",
    fulfilledDay: state.day,
    resultText: `${errand.npcLabel}在${errand.areaLabel}收下 ${errand.requestItemName} x${errand.count}，说旧铺这阵口碑果然没有白起。`,
  });
  if (opening.lastSession?.day === state.day) opening.lastSession.townErrand = opening.townErrand;
  if (opening.history[0]?.day === state.day) opening.history[0].townErrand = opening.townErrand;
  const townState = syncTownLifeInteractionState();
  townState.errandHistory.unshift({
    npcId: errand.npcId,
    npcName: errand.npcLabel,
    area: errand.areaLabel,
    title: `旧铺捎话 · ${errand.requestItemName}`,
    itemId: errand.requestItemId,
    itemName: errand.requestItemName,
    count: errand.count,
    rewardGold: errand.rewardGold,
    rewardFame: errand.rewardFame,
    rewardFavor: errand.rewardFavor,
    completed: true,
    completedDay: state.day,
    shopGenerated: true,
  });
  townState.errandHistory = townState.errandHistory.slice(0, 12);
  const unlockedMemories = recordTownLifeInteraction(errand.npcId, "errand");
  const latestMemory = latestTownLifeMemory(errand.npcId);
  const freshMemory = latestMemory && latestMemory.day === state.day && latestMemory.memoryId !== memoryBeforeId
    ? [latestMemory]
    : [];
  state.shopTownErrandFeedback = shopTownErrandFeedbackSpec(opening.townErrand, {
    favorBefore,
    favorAfter: Number(state.npcFavor[errand.npcId] || 0),
    unlockedMemories: unlockedMemories.length > 0 ? unlockedMemories : freshMemory,
  });
  queueShopTownErrandDialogue(state.shopTownErrandFeedback);
  recordTownLifeShopMoment(shopTownErrandMomentSpec(opening.townErrand, state.shopTownErrandFeedback));
  recordDailyIntentProgress("relationship", `${errand.npcLabel} 的旧铺捎话送到了`, {
    amount: 4,
    rewardText: `灵石 +${errand.rewardGold}${errand.rewardFame ? ` · 声望 +${errand.rewardFame}` : ""} · 好感 +${errand.rewardFavor}`,
    target: `npc:${errand.npcId}`,
  });
  addLog("镇上捎话办妥", `${errand.npcLabel}收下 ${errand.requestItemName} x${errand.count}，回礼 ${errand.rewardGold} 灵石${errand.rewardFame ? `、声望 +${errand.rewardFame}` : ""}、好感 +${errand.rewardFavor}。${state.shopTownErrandFeedback?.memoryTitle ? ` 关系册写下「${state.shopTownErrandFeedback.memoryTitle}」。` : ""}`);
  playCue("任务完成");
  render();
}

function focusShopTownErrandAction(action = "focus", options = {}) {
  const errand = shopTownErrandDisplaySpec();
  if (!errand) {
    addLog("镇上捎话", "当前没有可追的镇上捎话。");
    renderLogs();
    return;
  }
  if (action === "deliver") return completeShopTownErrand();
  if (action === "route") {
    return focusShopRestockRoute(options.routeAction, {
      recipeId: options.recipeId,
      seedId: options.seedId,
      shopTag: options.shopTag,
      itemId: options.itemId || errand.requestItemId,
    });
  }
  focusShopTownErrandNpc(errand.npcId);
}

function shopDoorstepSceneCrowdBoost(row = {}) {
  const chance = Number(row.chance || 0);
  if (row.hostArchetype || row.hostLabel) {
    if (row.bought && ["guest", "faction", "trader"].includes(row.hostArchetype || "")) return chance >= 60 ? 2 : 1;
    if (row.bought) return 1;
    return chance >= 58 ? 1 : 0;
  }
  if (row.bought && ["guest", "faction", "trader"].includes(row.customerArchetype || "")) return chance >= 60 ? 2 : 1;
  if (row.bought) return chance >= 60 ? 1 : 0;
  return chance >= 58 ? 1 : 0;
}

function shopDoorstepSceneSpec(opening = syncShopOpeningState()) {
  const safeOpening = normalizeShopOpeningState(opening);
  const sessionDay = Number(safeOpening.lastSession?.day || 0);
  if (sessionDay !== state.day) return null;
  const returningRows = Array.isArray(safeOpening.returningCustomers) && safeOpening.returningCustomers.length
    ? safeOpening.returningCustomers
    : Array.isArray(safeOpening.lastSession?.returningCustomers)
      ? safeOpening.lastSession.returningCustomers
      : [];
  const introducedRows = Array.isArray(safeOpening.introducedCustomers) && safeOpening.introducedCustomers.length
    ? safeOpening.introducedCustomers
    : Array.isArray(safeOpening.lastSession?.introducedCustomers)
      ? safeOpening.lastSession.introducedCustomers
      : [];
  if (!returningRows.length && !introducedRows.length) return null;
  const boughtRows = returningRows.filter((row) => row.bought);
  const introducedBoughtRows = introducedRows.filter((row) => row.bought);
  const crowdBoost = [...returningRows, ...introducedRows].reduce((sum, row) => sum + shopDoorstepSceneCrowdBoost(row), 0);
  const leadRow = returningRows[0] || introducedRows[0];
  const returningNames = returningRows.slice(0, 3).map((row) => row.customerLabel).join(" / ");
  const introducedNames = introducedRows.slice(0, 3).map((row) => row.customerLabel).join(" / ");
  const displayRows = [
    ...returningRows.map((row) => ({ ...row, sceneType: "returning" })),
    ...introducedRows.map((row) => ({ ...row, sceneType: "introduced" })),
  ].slice(0, 4);
  const title = introducedRows.length > 0
    ? crowdBoost >= 3
      ? "熟脸带新脚步，门口更热了"
      : "熟脸把新客领进门"
    : crowdBoost >= 2
      ? "门口熟脸又带热了"
      : boughtRows.length > 0
        ? "熟脸回门，小铺有续声"
        : "熟脸先回来探路";
  const headline = introducedRows.length > 0
    ? `${returningNames || leadRow?.hostLabel || "熟客"}回门后，又把${introducedNames || "新的脚步"}领到了旧铺门前。`
    : crowdBoost >= 2
      ? `${returningNames} 这批昨天记住旧铺的人回来后，门口又跟着多了几双脚步。`
      : boughtRows.length > 0
        ? `${returningNames} 又回门认货，小铺开始有了“隔天还会再来”的声音。`
        : `${returningNames} 先回来探路，门口已经不是只有生客匆匆路过。`;
  const sceneLine = introducedRows.length > 0
    ? `回门 ${returningRows.length} 位 · 新脚步 ${introducedRows.length} 位${introducedBoughtRows.length > 0 ? ` · 新客成交 ${introducedBoughtRows.length} 单` : " · 先把门认住了"}`
    : crowdBoost >= 2
      ? `回门 ${returningRows.length} 位 · 跟热闹的脚步 +${crowdBoost}`
      : `回门 ${returningRows.length} 位${boughtRows.length > 0 ? ` · 再成交 ${boughtRows.length} 单` : " · 先把旧印象接住了"}`;
  const detail = introducedRows[0]?.detail || leadRow?.detail || "把昨天被记住的那件货继续留在头排，门口熟脸会越来越自然地回来。";
  return {
    active: true,
    title,
    headline,
    sceneLine,
    detail,
    rows: displayRows,
    returningCount: returningRows.length,
    introducedCount: introducedRows.length,
    boughtCount: boughtRows.length,
    crowdBoost,
    tone: crowdBoost >= 2 || boughtRows.length > 0 || introducedBoughtRows.length > 0 ? "good" : "mid",
  };
}

function shopDoorstepSceneMarkup(spec = shopDoorstepSceneSpec()) {
  if (!spec?.active) return "";
  return `
    <div class="shop-doorstep-scene ${spec.tone}">
      <strong>${spec.title}</strong>
      <span>${spec.headline}</span>
      <small>${spec.sceneLine}</small>
      ${spec.rows.slice(0, 3).map((row) => `
        <div class="shop-doorstep-row ${row.bought ? "good" : "mid"}">
          <b>${row.sceneType === "introduced" ? `${row.customerLabel} · ${row.hostLabel || "熟客"}带来的新脚步` : `${row.customerLabel}${row.bought ? " · 回门后又买了" : " · 回门看看"}`}</b>
          <span>${row.resultText || row.arrivalText || row.needText || row.headline}</span>
        </div>
      `).join("")}
      <small>门前小景：${spec.detail}</small>
    </div>
  `;
}

function shopDoorstepSceneSummaryText(opening = syncShopOpeningState()) {
  const spec = shopDoorstepSceneSpec(opening);
  if (!spec?.active) return "";
  return `${spec.rows.map((row) => row.sceneType === "introduced" ? `${row.hostLabel || "熟客"}带来${row.customerLabel}${row.bought ? " 并成交" : " 来认门"}` : `${row.customerLabel}${row.bought ? " 回门又买了" : " 回门看货"}`).join(" / ")}；${spec.sceneLine}；${spec.detail}`;
}

function shopWaterwayBrokerSceneSpec(opening = syncShopOpeningState(), report = state.shopReport) {
  if (!state.completed.has("qinghe_lotus_basin_followup_order_done")) return null;
  const safeOpening = normalizeShopOpeningState(opening);
  const sessionDay = Number(safeOpening.lastSession?.day || 0);
  if (sessionDay !== state.day) return null;
  const rows = (Array.isArray(report) ? report : [])
    .filter((entry) => entry.customerArchetype === "waterway_broker" && entry.reason !== "diagnosis")
    .slice(0, 4);
  if (!rows.length) return null;
  const boughtRows = rows.filter((entry) => entry.reason === "buy");
  const boughtNames = boughtRows.map((entry) => itemName(entry.itemId)).filter(Boolean);
  const waterwayGoods = rows
    .filter((entry) => {
      const item = data.itemsById.get(entry.itemId);
      const tags = item ? shopTagsForItem(item) : [];
      return shopTagsOverlap(tags, ["water_food", "drink", "route_rare", "cooling"]);
    })
    .map((entry) => itemName(entry.itemId))
    .filter(Boolean);
  const leadItem = boughtNames[0] || waterwayGoods[0] || "水鲜货";
  const boughtCount = boughtRows.length;
  const title = boughtCount > 0 ? "莲泽客船认门成交" : "莲泽客船到店看货";
  const headline = boughtCount > 0
    ? `水航客把${leadItem}认作熟路货，旧铺门前第一次有了“能带回莲泽”的回声。`
    : "水航客顺着青禾跑熟的水路停在旧铺门前，先看水鲜、饮品和能回订的货。";
  const sceneLine = `水航客 ${rows.length} 位 · 成交 ${boughtCount} 单 · ${waterwayGoods.length ? `熟路货 ${waterwayGoods.slice(0, 2).join(" / ")}` : "正在确认水路来头"}`;
  const detail = boughtCount > 0
    ? "这不是普通来客成交，而是商路内容反哺店铺：水航客会把水鲜口碑、回订预期和莲泽熟路一起带回去。"
    : "如果清波鱼脍、灵池三鲜羹或荷露糖水断档，水航客会先记住“路熟但货薄”。";
  const nextAction = boughtCount > 0
    ? "继续保持水鲜和饮品不断档，让水航客从尝鲜变成长单。"
    : "明天优先补一件水鲜或饮品，把熟路客船真正留成成交。";
  return {
    active: true,
    title,
    headline,
    sceneLine,
    detail,
    nextAction,
    rows,
    boughtCount,
    visitorCount: rows.length,
    leadItem,
    waterwayGoods,
    tone: boughtCount > 0 ? "good" : "mid",
    accent: "#4d91a6",
  };
}

function shopWaterwayBrokerSceneMarkup(spec = shopWaterwayBrokerSceneSpec()) {
  if (!spec?.active) return "";
  return `
    <div class="shop-waterway-broker-scene ${spec.tone}" data-shop-board="waterway-broker">
      <strong>${spec.title}</strong>
      <span>${spec.headline}</span>
      <small>${spec.sceneLine}</small>
      <div class="shop-waterway-broker-chips">
        <b>莲泽熟路</b>
        <b>${spec.boughtCount > 0 ? `成交 ${spec.boughtCount}` : "先看货"}</b>
        <b>${spec.leadItem}</b>
      </div>
      ${spec.rows.slice(0, 3).map((row) => `
        <div class="shop-waterway-broker-row ${row.reason === "buy" ? "good" : "mid"}">
          <b>${row.name || "水航客"} · ${row.reason === "buy" ? "认门成交" : "泊船看货"}</b>
          <span>${row.text || row.detail || "正在看旧铺水路来头"}</span>
        </div>
      `).join("")}
      <small>掌柜建议：${spec.nextAction}</small>
      <small>画面反馈：水航客船会停在旧铺旁，表示青禾水路内容已经反哺店铺经营。</small>
    </div>
  `;
}

function shopWaterwayBrokerSceneSummaryText(spec = shopWaterwayBrokerSceneSpec()) {
  if (!spec?.active) return "";
  return `${spec.title}：${spec.sceneLine}；${spec.detail} 下一步：${spec.nextAction}`;
}

const WATERWAY_SHELF_TAGS = ["water_food", "drink", "route_rare", "cooling", "clean_food", "fresh_food"];
const WATERWAY_SIGNATURE_ITEM_IDS = [
  "item_food_qingbo_yukuai",
  "item_food_lingchi_sanxian_geng",
  "item_drink_helu_tangshui",
  "crop_water_lotus_seed",
];

function shopWaterwayShelfSpotlightSpec(
  goods = sellableInventoryGoods(),
  theme = currentShelfTheme(),
  waterwayScene = shopWaterwayBrokerSceneSpec(),
) {
  if (!state.completed.has("qinghe_lotus_basin_followup_order_done")) return null;
  const safeGoods = (goods || []).filter(({ item, count }) => item && Number(count || 0) > 0);
  const themeTags = splitTags(theme?.required_item_tags || "");
  const waterwayGoods = safeGoods
    .map(({ item, itemId, count }) => {
      const tags = shopTagsForItem(item || itemId, ecologyCourtyardSummary());
      const matchedTags = WATERWAY_SHELF_TAGS.filter((tag) => shopTagsOverlap(tags, [tag]));
      const signature = WATERWAY_SIGNATURE_ITEM_IDS.includes(itemId);
      const themeMatch = themeTags.some((tag) => shopTagsOverlap(tags, [tag]));
      const score = matchedTags.length * 4 + (signature ? 5 : 0) + (themeMatch ? 2 : 0) + Math.min(3, Number(count || 0));
      return {
        itemId,
        itemName: itemName(itemId),
        count: Number(count || 0),
        tags,
        matchedTags,
        signature,
        themeMatch,
        score,
        tagText: [...new Set([...matchedTags, ...tags])].slice(0, 3).map(shopTagLabel).join(" / "),
      };
    })
    .filter((entry) => entry.matchedTags.length > 0 || entry.signature)
    .sort((a, b) => Number(b.score || 0) - Number(a.score || 0))
    .slice(0, 4);
  const topGood = waterwayGoods[0] || null;
  const missingTags = WATERWAY_SHELF_TAGS
    .filter((tag) => !waterwayGoods.some((good) => shopTagsOverlap(good.tags, [tag])))
    .slice(0, 3);
  const active = Boolean(waterwayScene?.active || waterwayGoods.length > 0);
  if (!active) return null;
  const ready = waterwayGoods.length >= 2 || (topGood && topGood.count >= 2);
  const title = ready ? "水航水鲜货架已亮" : "水航水鲜货架待补";
  const headline = topGood
    ? `${topGood.itemName}适合摆到水航客视线第一格，先让莲泽熟路货有一个明确锚点。`
    : "莲泽熟路已经跑通，但旧铺货架还缺一件能让水航客立刻认门的水鲜或饮品。";
  const detail = waterwayScene?.active
    ? `${waterwayScene.sceneLine}。${topGood ? `他们正在看${topGood.itemName}这类熟路货。` : "他们已经到门口，但货架还没接住水路需求。"}`
    : topGood
      ? `当前水航货 ${waterwayGoods.length} 件，适合等下一批水航客进店时把${topGood.itemName}放头排。`
      : "先从清波鱼脍、灵池三鲜羹、荷露糖水或莲实类货里补一件。";
  const nextAction = ready
    ? "保持水鲜和饮品不断档，水航客会更容易把回订口碑带回莲泽。"
    : missingTags.length > 0
      ? `优先补${missingTags.map(shopTagLabel).join(" / ")}，让熟路货架不只是一件孤品。`
      : "把现有水航货补到 2 件以上，避免水航客刚认门就遇到断档。";
  return {
    active: true,
    ready,
    title,
    headline,
    detail,
    nextAction,
    topGood,
    goods: waterwayGoods,
    missingTags,
    missingTagText: missingTags.map(shopTagLabel).join(" / "),
    tone: ready ? "good" : "mid",
    waterwaySceneActive: Boolean(waterwayScene?.active),
    accent: "#4d91a6",
  };
}

function shopWaterwayShelfSpotlightMarkup(spec = shopWaterwayShelfSpotlightSpec()) {
  if (!spec?.active) return "";
  const goodsMarkup = spec.goods.length
    ? spec.goods.slice(0, 3).map((good, index) => `
      <div class="shop-waterway-shelf-good ${index === 0 ? "feature" : ""}">
        <b>${index === 0 ? "头排水航货" : "续补水航货"} · ${good.itemName} x${good.count}</b>
        <span>${good.tagText || "水航货"}</span>
      </div>
    `).join("")
    : "<small>货架暂无水航货，先补一件水鲜或饮品。</small>";
  return `
    <div class="shop-waterway-shelf-spotlight ${spec.tone}" data-shop-board="waterway-shelf">
      <strong>${spec.title}</strong>
      <span>${spec.headline}</span>
      <small>${spec.detail}</small>
      <div class="shop-waterway-shelf-chips">
        <b>${spec.ready ? "可接熟路客" : "货架偏薄"}</b>
        <b>${spec.topGood?.itemName || "待补水鲜"}</b>
        <b>${spec.waterwaySceneActive ? "客船已到" : "预备来客"}</b>
      </div>
      <div class="shop-waterway-shelf-goods">${goodsMarkup}</div>
      ${spec.missingTagText ? `<small>缺口标签：${spec.missingTagText}</small>` : ""}
      <small>掌柜建议：${spec.nextAction}</small>
    </div>
  `;
}

function shopWaterwayShelfSpotlightSummaryText(spec = shopWaterwayShelfSpotlightSpec()) {
  if (!spec?.active) return "";
  return `${spec.title}：${spec.headline} ${spec.nextAction}`;
}

function shopWaterwayCustomerBrowseSpec(
  opening = syncShopOpeningState(),
  report = state.shopReport,
  shelf = shopWaterwayShelfSpotlightSpec(),
) {
  if (!state.completed.has("qinghe_lotus_basin_followup_order_done")) return null;
  const safeOpening = normalizeShopOpeningState(opening);
  if (Number(safeOpening.lastSession?.day || 0) !== state.day) return null;
  const rows = (Array.isArray(report) ? report : [])
    .map((entry, reportIndex) => ({ ...entry, reportIndex }))
    .filter((entry) => entry.customerArchetype === "waterway_broker" && entry.reason !== "diagnosis")
    .slice(0, 3);
  if (!rows.length) return null;
  const lead = rows.find((entry) => entry.reason === "buy") || rows[0];
  const targetGood = shelf?.topGood || (lead?.itemId ? {
    itemId: lead.itemId,
    itemName: itemName(lead.itemId),
    tagText: shopTagsForItem(lead.itemId).slice(0, 3).map(shopTagLabel).join(" / "),
  } : null);
  const bought = rows.some((entry) => entry.reason === "buy");
  const warned = rows.some((entry) => ["price", "stock", "tag"].includes(entry.reason));
  const flowHint = localize("customer_flow_hint_waterway_check", "水航客正在看水鲜、饮品和能带回莲泽的熟路货。");
  const routeHint = localize("customer_flow_hint_waterway_route", "水航客会为稳定熟路和可回订口碑接受更高价格。");
  const bubble = bought
    ? "这件带回莲泽有人认。"
    : warned
      ? "路是熟的，货还要稳。"
      : "先看水鲜和回订口碑。";
  const title = bought ? "水航客挑中熟路货" : warned ? "水航客挑货后犹豫" : "水航客正在挑货";
  const headline = targetGood
    ? `水航客停在${targetGood.itemName}前，正在判断这件货能不能带回莲泽认门。`
    : "水航客停在水航货架前，先确认旧铺是不是有稳定水鲜和饮品。";
  const detail = bought
    ? `${routeHint} 今天这条线已经从“看路”变成“认货”。`
    : warned
      ? `${flowHint} 今天的短板会直接影响水航客是否愿意回订。`
      : `${flowHint} 如果头排货够清楚，他们会更愿意把口碑带回莲泽。`;
  const nextAction = shelf?.nextAction || (bought
    ? "保持水鲜不断档，让这批熟路客变成长单。"
    : "先补厚水鲜和饮品，再开铺接下一批水航客。");
  return {
    active: true,
    title,
    headline,
    detail,
    nextAction,
    bubble,
    rows,
    lead,
    targetGood,
    bought,
    warned,
    tone: bought ? "good" : warned ? "warn" : "mid",
    reportIndex: Number(lead?.reportIndex ?? -1),
    customerLabel: lead?.name || "水航客",
    actionLabel: bought ? "认门成交" : warned ? "挑货犹豫" : "驻足挑货",
    accent: "#4d91a6",
  };
}

