function recordShopOpeningFeedback({ customers, report, goods, theme, themeScore, sessionSales, compendiumDisplays = [], compendiumDisplayEffect = null, ecologyShopAura = null, qingboSignatureAura = null, restockFulfillment = null, spiritFinaleEffects = null, returningCustomers = [], introducedCustomers = [], shopWordOfMouthVisit = null }) {
  syncShopOpeningState();
  const opening = state.shopOpeningState;
  const firstOpen = !opening.opened;
  const sale = report.find((entry) => entry.reason === "buy");
  const firstSale = sale && !opening.firstSale;
  const saleReasonText = sale
    ? String(sale.detail || "")
      .split("→")
      .map((part) => part.trim())
      .filter(Boolean)
      .slice(-1)[0] || "顾客觉得商品和价格都合适。"
    : "";
  const hotTag = shopHotTag(goods, theme);
  const featuredMomentText = shopFeaturedMoment(goods, sale, hotTag);
  const returningTargetMap = new Map((returningCustomers || []).map((entry) => [entry.customerArchetype, entry]));
  const introducedTargetMap = new Map((introducedCustomers || []).map((entry) => [entry.customerArchetype, entry]));
  const needBubbles = customers
    .slice(0, 3)
    .map((customer) => customerNeedBubble(
      customer,
      segmentForCustomer(customer),
      hotTag,
      compendiumDisplays,
      returningTargetMap.get(customer.archetype) || null,
      introducedTargetMap.get(customer.archetype) || null,
    ));
  const displaySummary = compendiumDisplayEffect?.summary || "";
  const displayDetail = compendiumDisplayEffect?.detail || "";
  const liveFocus = shopLiveFocusSpec(report, goods, theme, themeScore, hotTag);
  const failureRecovery = shopFailureRecoverySpec(report, goods, theme, themeScore, hotTag);
  const customerDecisionLedger = shopCustomerDecisionLedgerSpec({
    customers,
    report,
    goods,
    theme,
    themeScore,
    hotTag,
    sessionSales,
    needBubbles,
    liveFocus,
    failureRecovery,
  });
  const reviewQuote = sale ? shopCustomerShortReview(sale, hotTag, liveFocus) : "";
  const returnPreview = sale
    ? shopReturnVisitPreviewSpec(sale, {
      firstSale: Boolean(firstSale),
      hotTag,
      hotTagLabel: shopTagLabel(hotTag),
      liveFocus,
    }, {
      themeScore: Math.round(themeScore * 100),
      hotTag,
    })
    : null;
  const safeSpiritFinaleEffects = spiritFinaleEffects ? spiritFinaleEffectSnapshot(spiritFinaleEffects) : null;
  const safeDisplays = compendiumDisplays.map((display) => ({
    key: display.key,
    title: display.title,
    shortTitle: display.shortTitle,
    customerText: display.customerText,
    tagText: display.tagText,
  }));
  const safeEcologyShopAura = ecologyShopAura
    ? {
      comboId: ecologyShopAura.comboId,
      comboName: ecologyShopAura.comboName,
      title: ecologyShopAura.title,
      focusText: ecologyShopAura.focusText,
      auraText: ecologyShopAura.auraText,
      visitorBonus: ecologyShopAura.visitorBonus,
      budgetBonus: ecologyShopAura.budgetBonus,
      matchedGoodsText: ecologyShopAura.matchedGoodsText,
      inspectionCareActive: ecologyShopAura.inspectionCareActive,
      summary: ecologyShopAura.summary,
    }
    : null;
  const safeQingboSignatureAura = qingboWaterFreshSignatureAuraSnapshot(qingboSignatureAura);

  opening.opened = true;
  if (!opening.firstOpenDay) opening.firstOpenDay = state.day;
  opening.hotTag = hotTag;
  opening.hotTagLabel = shopTagLabel(hotTag);
  opening.needBubbles = needBubbles;
  opening.returningCustomers = returningCustomers.map((entry) => normalizeShopReturningCustomerVisit(entry)).filter(Boolean).slice(0, 4);
  opening.introducedCustomers = introducedCustomers.map((entry) => normalizeShopIntroducedCustomerVisit(entry)).filter(Boolean).slice(0, 4);
  opening.lastSession = {
    day: state.day,
    visitors: customers.length,
    buyers: report.filter((entry) => entry.reason === "buy").length,
    sales: sessionSales,
    themeTag: theme?.theme_tag || state.shopShelfTheme,
    themeName: theme?.note || state.shopShelfTheme,
    themeScore: Math.round(themeScore * 100),
    hotTag,
    hotTagLabel: shopTagLabel(hotTag),
    featuredMomentText,
    reviewQuote,
    returnPreview,
    returningCustomers: opening.returningCustomers,
    introducedCustomers: opening.introducedCustomers,
    visitPledge: opening.visitPledge ? normalizeShopVisitPledge(opening.visitPledge) : null,
    townErrand: opening.townErrand ? normalizeShopTownErrand(opening.townErrand) : null,
    shopWordOfMouthVisit: shopWordOfMouthVisit ? { ...shopWordOfMouthVisit } : null,
    liveFocus,
    failureRecovery,
    customerDecisionLedger,
    ecologyShopAura: safeEcologyShopAura,
    qingboSignatureAura: safeQingboSignatureAura,
    compendiumDisplaySummary: displaySummary,
    compendiumDisplayDetail: displayDetail,
    compendiumDisplays: safeDisplays,
    spiritFinaleEffects: safeSpiritFinaleEffects,
    restockFulfillment: restockFulfillment?.active
      ? {
        itemId: restockFulfillment.itemId,
        itemName: restockFulfillment.itemName,
        count: restockFulfillment.count,
        desiredCount: restockFulfillment.desiredCount,
        tagLabel: restockFulfillment.tagLabel,
        waterFresh: Boolean(restockFulfillment.waterFresh),
        summary: restockFulfillment.summary,
        detail: restockFulfillment.detail,
        themeBonus: restockFulfillment.themeBonus,
        budgetBonus: restockFulfillment.budgetBonus,
        visitorBonus: restockFulfillment.visitorBonus,
      }
      : null,
  };
  opening.liveFocus = liveFocus;
  opening.failureRecovery = failureRecovery;
  opening.customerDecisionLedger = customerDecisionLedger;

  if (sale) {
    const price = Number((sale.text.match(/成交 (\d+)/) || [0, 0])[1]);
    if (!opening.firstSaleDay) opening.firstSaleDay = state.day;
    opening.summaryUnlocked = true;
    if (!opening.firstSale) {
      opening.firstSale = {
        day: state.day,
        name: sale.name,
        customerArchetype: sale.customerArchetype || "",
        itemId: sale.itemId,
        itemName: itemName(sale.itemId),
        price,
        reasonText: saleReasonText,
        reviewQuote,
        returnPreview,
      };
    }
  }

  const regularBoard = shopRegularBoardSpec(opening);
  opening.regularBoard = regularBoard;
  if (opening.lastSession) opening.lastSession.regularBoard = regularBoard;

  opening.history.unshift({
    day: state.day,
    visitors: opening.lastSession.visitors,
    buyers: opening.lastSession.buyers,
    sales: sessionSales,
    hotTag,
    hotTagLabel: opening.hotTagLabel,
    firstOpen,
    firstSale: Boolean(firstSale),
    liveFocus,
    failureRecovery,
    customerDecisionLedger,
    regularBoard,
    returningCustomers: opening.returningCustomers,
    introducedCustomers: opening.introducedCustomers,
    visitPledge: opening.visitPledge ? normalizeShopVisitPledge(opening.visitPledge) : null,
    townErrand: opening.townErrand ? normalizeShopTownErrand(opening.townErrand) : null,
    shopWordOfMouthVisit: shopWordOfMouthVisit ? { ...shopWordOfMouthVisit } : null,
    ecologyShopAura: safeEcologyShopAura,
    qingboSignatureAura: safeQingboSignatureAura,
    compendiumDisplaySummary: displaySummary,
    compendiumDisplays: safeDisplays,
    spiritFinaleEffects: safeSpiritFinaleEffects,
  });
  opening.history = opening.history.slice(0, 8);

  if (firstOpen) complete("first_shop_opening");
  if (sale) complete("first_shop_sale_summary");
  return {
    firstOpen,
    firstSale: Boolean(firstSale),
    hotTagLabel: opening.hotTagLabel,
    hotTag,
    featuredMomentText,
    reviewQuote,
    returnPreview,
    returningCustomers: opening.returningCustomers,
    introducedCustomers: opening.introducedCustomers,
    visitPledge: opening.visitPledge ? normalizeShopVisitPledge(opening.visitPledge) : null,
    townErrand: opening.townErrand ? normalizeShopTownErrand(opening.townErrand) : null,
    shopWordOfMouthVisit: shopWordOfMouthVisit ? { ...shopWordOfMouthVisit } : null,
    liveFocus,
    failureRecovery,
    customerDecisionLedger,
    regularBoard,
    ecologyShopAura: safeEcologyShopAura,
    qingboSignatureAura: safeQingboSignatureAura,
    compendiumDisplaySummary: displaySummary,
    spiritFinaleEffects: safeSpiritFinaleEffects,
  };
}

function shopSeasonCycleInfo(day = state.day) {
  const runtime = shopRuntime();
  if (runtime) return runtime.shopSeasonCycleInfo(day);
  const seasons = data.shopSeasons || [];
  if (seasons.length === 0) return { season: null, cycleIndex: 0, dayInSeason: 1, startDay: 1, cycleDays: 30 };
  const safeDay = Math.max(1, Number(day || 1));
  let remaining = safeDay - 1;
  let cycleIndex = 0;
  while (cycleIndex < 9999) {
    const season = seasons[cycleIndex % seasons.length];
    const cycleDays = Math.max(1, Number(season?.cycle_days || 30));
    if (remaining < cycleDays) {
      return {
        season,
        cycleIndex,
        dayInSeason: remaining + 1,
        startDay: safeDay - remaining,
        cycleDays,
      };
    }
    remaining -= cycleDays;
    cycleIndex += 1;
  }
  const fallback = seasons[0];
  return { season: fallback, cycleIndex: 0, dayInSeason: 1, startDay: 1, cycleDays: Math.max(1, Number(fallback?.cycle_days || 30)) };
}

function currentShopSeason(day = state.day) {
  return shopSeasonCycleInfo(day).season;
}

function currentShopSeasonStats() {
  state.shopStats = normalizeShopStats(state.shopStats);
  return state.shopStats.season;
}

function shouldTrackShopSeason() {
  return year2Unlocked();
}

function shopSeasonBuffValue(buffId = "") {
  syncFengmiTeaPartyState();
  return Number(state.shopStats.activeBuffs?.[buffId] || 0);
}

function shopSeasonRewardText(reward) {
  if (!reward) return "无";
  if (reward.reward_type === "preview") return "暂无实物奖励，先把招牌立稳";
  const rewardCount = Number(reward.reward_count || 0);
  const buffText = reward.bonus_buff && reward.bonus_buff !== "none" && Number(reward.bonus_value || 0) > 0
    ? ` · 赛季加成 ${shopSeasonBuffText(reward.bonus_buff, Number(reward.bonus_value || 0))}`
    : "";
  if (reward.reward_type === "item") return `${itemName(reward.reward_param)} x${rewardCount}${buffText}`;
  if (reward.reward_type === "building") return `${buildingName(data.buildingsById.get(reward.reward_param) || reward.reward_param)}${buffText}`;
  if (reward.reward_type === "recipe") return `${reward.reward_param}${buffText}`;
  if (reward.reward_type === "reputation") return `${reward.reward_param} ${rewardCount}${buffText}`;
  return `${reward.reward_type} ${reward.reward_param} x${rewardCount}${buffText}`;
}

function shopSeasonBuffText(buffId, value) {
  if (buffId === "buff_shop_fresh_bonus") return `鲜货偏好 +${Math.round(value * 100)}%`;
  if (buffId === "buff_shop_visit_bonus") return `来客倾向 +${Math.round(value * 100)}%`;
  if (buffId === "buff_term_profit_bonus") return `节气货品收益 +${Math.round(value * 100)}%`;
  if (buffId === "buff_machine_speed_year2") return `工坊运转 +${Math.round(value * 100)}%`;
  if (buffId === "buff_guest_purchase_up") return `贵客成交 +${Math.round(value * 100)}%`;
  if (buffId === "buff_shop_master_title") return `名铺号召 +${Math.round(value * 100)}%`;
  if (buffId === "buff_dessert_customer_up") return `百花茶会 +${Math.round(value * 100)}%`;
  return `${buffId} +${Math.round(value * 100)}%`;
}

function shopSeasonTitle(rankTier = "c") {
  const lines = {
    s: "这间店，已经不是凡仙镇的普通铺子了。",
    a: "你已经有了名铺的样子，再稳一点，就能真正压住一季。",
    b: "买卖能做成，但招牌还没立稳。",
    c: "这月撑过去了，但离“被人记住”还差几步。",
  };
  return lines[String(rankTier || "c").toLowerCase()] || lines.c;
}

function shopSeasonRules(season = currentShopSeason()) {
  const runtime = shopRuntime();
  if (runtime) return runtime.shopSeasonRules(season);
  return data.shopSettlementRules.filter((rule) => rule.season_id === season?.season_id);
}

function shopSeasonRewards(season = currentShopSeason()) {
  const runtime = shopRuntime();
  if (runtime) return runtime.shopSeasonRewards(season);
  return data.shopRankRewards
    .filter((reward) => reward.season_id === season?.season_id)
    .sort((a, b) => Number(b.score_min) - Number(a.score_min));
}

function shopSeasonMetricContext(stats = currentShopSeasonStats(), seasonDay = state.day) {
  syncFengmiTeaPartyState();
  return {
    stats,
    seasonDay,
    activeBuffs: state.shopStats.activeBuffs,
    marketBonusTags: currentTermConfig()?.market_bonus_tags || "",
    workshopMultiplier: workshopMultiplier(),
    builtBuildingsCount: state.builtBuildings.size,
    unlockedMachinesCount: state.unlockedMachines.size,
    fame: state.fame,
    shopShelfTheme: state.shopShelfTheme,
    missionDoneCount: state.missionDone.size,
    currentTermId: currentTermId(),
    resolvedRisksCount: state.resolvedRisks.size,
    dungeonClearsCount: state.dungeonClears.size,
  };
}

function shopMetricValue(part, stats = currentShopSeasonStats(), seasonDay = state.day) {
  const metricContext = shopSeasonMetricContext(stats, seasonDay);
  const runtimeValue = shopRuntime()?.shopSeasonMetricValue(part, metricContext);
  if (Number.isFinite(runtimeValue)) return runtimeValue;
  const avgTheme = stats.sessions ? Number(stats.themeTotal || 0) / stats.sessions : 0;
  const positiveRate = stats.visitors ? Number(stats.positive || 0) / stats.visitors : 0;
  const buyerRate = stats.visitors ? Number(stats.buyers || 0) / stats.visitors : 0;
  const guestVisits = Number(stats.customerVisits?.guest || 0) + Number(stats.customerVisits?.faction || 0);
  const guestBuys = Number(stats.customerBuys?.guest || 0) + Number(stats.customerBuys?.faction || 0);
  const guestRate = guestVisits ? guestBuys / guestVisits : buyerRate;
  const freshBuff = shopSeasonBuffValue("buff_shop_fresh_bonus");
  const visitBuff = shopSeasonBuffValue("buff_shop_visit_bonus");
  const profitBuff = shopSeasonBuffValue("buff_term_profit_bonus");
  const machineBuff = shopSeasonBuffValue("buff_machine_speed_year2");
  const guestBuff = shopSeasonBuffValue("buff_guest_purchase_up");
  const masterBuff = shopSeasonBuffValue("buff_shop_master_title");
  const values = {
    freshness_score: Math.min(100, 56 + avgTheme * 44 + freshBuff * 100),
    theme_score: Math.min(100, avgTheme * 100 + freshBuff * 30),
    sales_score: Math.min(100, Number(stats.sales || 0) / 3.2 * (1 + profitBuff + masterBuff * 0.5)),
    customer_score: positiveRate * 100,
    term_match_score: Math.min(100, avgTheme * 70 + (currentTermConfig()?.market_bonus_tags ? 20 : 0) + profitBuff * 100),
    quality_score: Math.min(100, 45 + workshopMultiplier() * 25 + machineBuff * 100),
    guest_score: Math.min(100, guestRate * 100 + guestBuff * 100),
    material_score: state.builtBuildings.size * 16,
    machine_score: Math.min(100, state.unlockedMachines.size * 28 + machineBuff * 120),
    reputation_score: Math.min(100, state.fame * 8 + masterBuff * 100),
    gift_score: state.shopShelfTheme.includes("gift") ? 100 : avgTheme * 60,
    premium_score: Math.min(100, state.fame * 10 + Number(stats.sales || 0) / 8 + guestBuff * 80),
    story_score: state.missionDone.size * 18,
    festival_score: currentTermId() === "term_dongzhi" ? 100 : seasonDay % 6 * 12,
    ritual_score: state.resolvedRisks.size * 20 + state.dungeonClears.size * 30,
    town_score: Math.min(100, state.builtBuildings.size * 12 + state.fame * 6 + visitBuff * 50),
  };
  return Math.max(0, Math.min(100, values[part] || 0));
}

function shopSeasonScore(season = currentShopSeason(), stats = currentShopSeasonStats(), seasonDay = state.day) {
  const rules = shopSeasonRules(season);
  const cycle = shopSeasonCycleInfo(seasonDay);
  const cycleKey = shopSeasonCycleKey(season || cycle.season, cycle.cycleIndex);
  const ledgerBonus = shuqiLegacyLedgerActive() ? Number(state.shopStats?.seasonScoreBoosts?.[cycleKey] || 0) : 0;
  const runtimePlanFromRules = shopRuntime()?.shopSeasonScoreFromRules({
    ...shopSeasonMetricContext(stats, seasonDay),
    rules,
    ledgerBonus,
  });
  if (runtimePlanFromRules) return runtimePlanFromRules;
  const parts = rules.map((rule) => {
    const raw = shopMetricValue(rule.score_part, stats, seasonDay);
    return { rule, raw };
  });
  const runtimePlan = shopRuntime()?.shopSeasonScorePlan({ parts, ledgerBonus });
  if (runtimePlan) return runtimePlan;
  const scoredParts = parts.map((part) => ({
    ...part,
    weighted: part.raw * Number(part.rule.weight || 0),
  }));
  const baseScore = Math.round(scoredParts.reduce((sum, part) => sum + part.weighted, 0) * 12);
  const score = Math.round(baseScore * (1 + ledgerBonus));
  return { score, baseScore, ledgerBonus, parts: scoredParts };
}

function shopSeasonRank(score, season = currentShopSeason()) {
  const runtime = shopRuntime();
  if (runtime) {
    const rank = runtime.shopSeasonRank(score, season);
    if (rank?.reward_param === "continue_shop") return { ...rank, reward_param: "继续经营" };
    return rank;
  }
  return shopSeasonRewards(season).find((reward) => score >= Number(reward.score_min)) || { rank_tier: "c", score_min: 0, reward_type: "preview", reward_param: "继续经营", reward_count: 0, bonus_buff: "none", bonus_value: 0 };
}

function shopSeasonLeadKey(map = {}) {
  const runtime = shopRuntime();
  if (runtime) return runtime.shopSeasonLeadKey(map);
  return Object.entries(map)
    .sort((a, b) => Number(b[1]) - Number(a[1]))[0]?.[0] || "";
}

