function drawOrderCraftPrepWorldBoard(ctx, spec = orderCraftPrepWorldBoardSpec(ctx.canvas.width, ctx.canvas.height)) {
  if (!spec?.rect) return false;
  const { rect, rows, top, anchor } = spec;
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const bob = settings.reducedMotion ? 0 : Math.sin(motion * 1.82) * 2.2;
  const cardY = rect.y + bob;
  const active = orderCraftPrepWorldBoardFocus?.day === state.day
    && orderCraftPrepWorldBoardFocus?.key === spec.key;

  ctx.save();
  ctx.strokeStyle = active ? "rgba(190, 79, 55, 0.84)" : "rgba(190, 79, 55, 0.46)";
  ctx.lineWidth = active ? 2.8 : 1.7;
  ctx.setLineDash([5, 8]);
  ctx.lineDashOffset = settings.reducedMotion ? 0 : -motion * 12;
  ctx.beginPath();
  ctx.moveTo(rect.x + 30, cardY + 18);
  ctx.quadraticCurveTo(rect.x + 96, cardY - 42, anchor.x, anchor.y);
  ctx.stroke();
  ctx.setLineDash([]);

  drawCanvasCard(ctx, rect.x, cardY, rect.width, rect.height, "rgba(255, 244, 232, 0.96)");
  ctx.strokeStyle = active ? "rgba(190, 79, 55, 0.88)" : "rgba(190, 79, 55, 0.58)";
  ctx.lineWidth = active ? 2.8 : 1.5;
  ctx.beginPath();
  ctx.roundRect(rect.x + 1.5, cardY + 1.5, rect.width - 3, rect.height - 3, 18);
  ctx.stroke();

  ctx.fillStyle = "rgba(190, 79, 55, 0.16)";
  ctx.beginPath();
  ctx.roundRect(rect.x + 14, cardY + 14, 56, 52, 16);
  ctx.fill();
  ctx.strokeStyle = "rgba(190, 79, 55, 0.66)";
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.roundRect(rect.x + 14, cardY + 14, 56, 52, 16);
  ctx.stroke();
  ctx.fillStyle = "#be4f37";
  ctx.font = "900 22px Microsoft YaHei";
  ctx.fillText("锅", rect.x + 31, cardY + 47);
  for (let puff = 0; puff < 3; puff += 1) {
    const lift = settings.reducedMotion ? puff * 5 : (motion * 18 + puff * 13) % 28;
    ctx.strokeStyle = `rgba(255, 253, 245, ${0.68 - puff * 0.12})`;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(rect.x + 30 + puff * 11, cardY + 17 - lift * 0.35, 6 + puff, Math.PI * 0.05, Math.PI * 1.2);
    ctx.stroke();
  }

  ctx.fillStyle = "#be4f37";
  ctx.font = "900 11px Microsoft YaHei";
  ctx.fillText(`${spec.cta} · ${spec.headline}`, rect.x + 84, cardY + 26);
  ctx.fillStyle = "#17231d";
  ctx.font = "800 15px Microsoft YaHei";
  ctx.fillText(top.orderTitle.slice(0, 18), rect.x + 84, cardY + 48);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "11px Microsoft YaHei";
  ctx.fillText(`${spec.detail} · ${top.machineText}`.slice(0, 34), rect.x + 84, cardY + 66);
  ctx.fillStyle = "#8f5f3f";
  ctx.font = "800 10px Microsoft YaHei";
  ctx.fillText(`原料 ${top.inputText}`.slice(0, 36), rect.x + 84, cardY + 82);

  rows.slice(0, 3).forEach((row, index) => {
    const rowY = cardY + 108 + index * 22;
    const primary = row.recipeId === top.recipeId && row.orderId === top.orderId;
    ctx.fillStyle = primary ? "rgba(190, 79, 55, 0.14)" : "rgba(255, 253, 245, 0.72)";
    ctx.beginPath();
    ctx.roundRect(rect.x + 16, rowY - 15, rect.width - 32, 18, 8);
    ctx.fill();
    ctx.fillStyle = primary ? "#be4f37" : "#8f5f3f";
    ctx.font = "900 10px Microsoft YaHei";
    ctx.fillText(primary ? "先做" : "可做", rect.x + 28, rowY - 2);
    ctx.fillStyle = "#17231d";
    ctx.font = "800 10px Microsoft YaHei";
    ctx.fillText(row.recipeTitle.slice(0, 13), rect.x + 64, rowY - 2);
    ctx.fillStyle = "#5d6f65";
    ctx.font = "10px Microsoft YaHei";
    ctx.fillText(`${row.itemName} ${row.haveText}`.slice(0, 14), rect.x + 178, rowY - 2);
  });

  ctx.fillStyle = "rgba(255, 253, 245, 0.92)";
  ctx.beginPath();
  ctx.roundRect(rect.x + rect.width - 55, cardY + 12, 40, 18, 9);
  ctx.fill();
  ctx.fillStyle = "#be4f37";
  ctx.font = "900 9px Microsoft YaHei";
  ctx.fillText("可点", rect.x + rect.width - 46, cardY + 25);
  ctx.restore();
  return true;
}

function orderSeedPrepTargetPlot(crop = null) {
  const waterPreferred = crop?.element_type === "water";
  return state.plots.find((plot) => !plot.cropId && !plot.debris && waterPreferred && (plot.waterSoil || plot.newlyExpanded))
    || state.plots.find((plot) => !plot.cropId && !plot.debris)
    || null;
}

function orderSeedPrepWorldRows(limit = 3) {
  const orders = visibleOrders();
  if (orders.some((order) => canDeliverOrder(order))) return [];
  if (orderCraftPrepWorldRows(1).length) return [];
  return orders
    .filter((order) => !canDeliverOrder(order))
    .flatMap((order) => {
      const status = orderNeedStatus(order);
      const missingByItem = new Map(status.missing.map((entry) => [entry.itemId, entry]));
      return orderProductionPlan(order)
        .filter((entry) => missingByItem.has(entry.itemId) && entry.action?.type === "seed" && !entry.action.disabled)
        .map((entry) => {
          const crop = data.cropsBySeed.get(entry.action.id);
          if (!crop || !hasItem(crop.seed_item_id, 1)) return null;
          const plot = orderSeedPrepTargetPlot(crop);
          if (!plot) return null;
          const missing = missingByItem.get(entry.itemId);
          const projected = seedProjectedHarvestSpec(crop, plot);
          const route = seedUseRouteSpec(crop, plot);
          const recommendation = seedSolarRecommendation(crop, plot);
          const rewardGold = Number(order.reward_gold || 0);
          const rewardFame = Number(order.reward_fame || 0);
          const outputHave = Number(state.inventory[entry.itemId] || 0);
          const projectedCount = Number(projected.count || 1);
          const enoughAfterHarvest = outputHave + projectedCount >= Number(missing.count || 1);
          const priority = (enoughAfterHarvest ? 72 : 44)
            + rewardGold / 28
            + rewardFame * 8
            + (recommendation.className === "boost" ? 18 : recommendation.className === "season" ? 10 : 0)
            + (plot.waterSoil ? 8 : 0)
            + (String(order.order_id || "").startsWith("order_year2_") ? 18 : 0);
          return {
            order,
            orderId: order.order_id,
            orderTitle: orderTitle(order),
            npc: npcName(order.issuer_id || order.reward_favor_npc),
            itemId: entry.itemId,
            itemName: itemName(entry.itemId),
            seedId: crop.seed_item_id,
            seedName: itemName(crop.seed_item_id),
            crop,
            plot,
            plotLabel: `(${plot.x + 1},${plot.y + 1})`,
            missingCount: Math.max(0, Number(missing.count || 1) - outputHave),
            haveText: `${outputHave}/${Number(missing.count || 1)}`,
            projectedCount,
            enoughAfterHarvest,
            growDays: Number(crop.grow_days || 1),
            recommendation,
            route,
            rewardText: [
              rewardGold ? `${rewardGold} 灵石` : "",
              rewardFame ? `声望 +${rewardFame}` : "",
            ].filter(Boolean).join(" / ") || "订单奖励",
            priority,
          };
        })
        .filter(Boolean);
    })
    .sort((a, b) => b.priority - a.priority || a.orderTitle.localeCompare(b.orderTitle, "zh-Hans-CN"))
    .slice(0, limit);
}

function orderSeedPrepWorldBoardSpec(width = 960, height = 640) {
  const rows = orderSeedPrepWorldRows(3);
  if (!rows.length) return null;
  const top = rows[0];
  const { tile, gap, originX, originY } = gridMetrics();
  const anchor = {
    x: originX + top.plot.x * (tile + gap) + tile * 0.5,
    y: originY + top.plot.y * (tile + gap) + tile * 0.5,
  };
  const cardWidth = 306;
  const cardHeight = 108 + rows.length * 22;
  const x = Math.max(38, Math.min(width - cardWidth - 336, 78));
  const y = Math.max(242, Math.min(height - cardHeight - 34, 306));
  return {
    key: `${state.day}:${rows.map((row) => `${row.orderId}:${row.seedId}:${row.plot.x},${row.plot.y}`).join("|")}`,
    day: state.day,
    rows,
    top,
    rect: { x, y, width: cardWidth, height: cardHeight },
    anchor,
    title: "主世界订单缺口可播种",
    headline: `${top.itemName} 还差 ${top.missingCount}`,
    detail: `${top.seedName} 可播 ${top.plotLabel}`,
    cta: "缺口可下种 · 可点",
  };
}

