  ctx.stroke();

  ctx.fillStyle = "rgba(224, 182, 109, 0.18)";
  ctx.beginPath();
  ctx.roundRect(rect.x + 14, cardY + 14, 56, 52, 16);
  ctx.fill();
  ctx.strokeStyle = "rgba(180, 125, 47, 0.66)";
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.roundRect(rect.x + 14, cardY + 14, 56, 52, 16);
