    ctx.fillStyle = primary ? "rgba(143, 95, 63, 0.14)" : "rgba(255, 248, 232, 0.72)";
    ctx.beginPath();
    ctx.roundRect(rect.x + 16, rowY - 15, rect.width - 32, 18, 8);
