function orderRewardNextUseSeedCandidate() {
  const crops = availableSeedCrops()
    .map((crop) => {
      const seedId = crop.seed_item_id;
      const price = buyPrice(seedId);
      const stock = Number(state.inventory[seedId] || 0);
      const livePlots = state.plots.filter((plot) => plot.seedItemId === seedId || plot.cropId === crop.crop_id).length;
      if (!price || stock + livePlots >= 3) return null;
      return {
        type: "seed",
        seedId,
        title: "补回种子",
        label: itemName(seedId),
        detail: `${stock} 包在袋 / 田里 ${livePlots} 格 · 3 包需 ${price * 3} 灵石`,
        metric: `库存 ${stock}`,
        selector: "#buySeedButton",
        fallbackSelector: "#seedRestockHint",
        panelGroup: "core",
        priority: Math.max(0, 4 - stock - livePlots) * 22 + (state.gold >= price * 3 ? 8 : 0),
      };
    })
    .filter(Boolean)
    .sort((a, b) => b.priority - a.priority);
  return crops[0] || null;
}

function orderRewardNextUseCandidate() {
  const readyOrder = visibleOrders().find((order) => canDeliverOrder(order));
  if (readyOrder) {
    return {
      type: "ready_order",
      orderId: readyOrder.order_id,
      title: "趁热接下一单",
      label: orderTitle(readyOrder),
      detail: `${npcName(readyOrder.issuer_id || readyOrder.reward_favor_npc)}还在等，库存已够`,
      metric: `奖励 ${Number(readyOrder.reward_gold || 0)} 灵石`,
      selector: `[data-order-card-id="${selectorDataValue(readyOrder.order_id)}"]`,
      fallbackSelector: "#orderPanel",
      panelGroup: "core",
      priority: 100,
    };
  }

  const recoveryOrder = visibleOrders()
    .filter((order) => !canDeliverOrder(order))
    .map((order) => ({ order, recovery: orderRecoverySpec(order) }))
    .find(({ recovery }) => recovery && !recovery.ready);
  if (recoveryOrder) {
    const { order, recovery } = recoveryOrder;
    const first = recovery.missingNeeds?.[0] || null;
    const action = first?.source?.action || null;
    return {
      type: action?.type === "recipe" ? "recipe" : action?.type === "seed" ? "seed" : "gap",
      orderId: order.order_id,
      recipeId: action?.type === "recipe" ? action.id : "",
      seedId: action?.type === "seed" ? action.id : "",
      title: "把回款补进缺口",
      label: recovery.title,
      detail: `${recovery.missingText} · ${recovery.routeText}`,
      metric: first ? `${itemName(first.itemId)}缺 ${first.missing}` : "缺口已圈出",
      selector: action?.type === "recipe" ? "#recipeSelect" : action?.type === "seed" ? "#seedSelect" : "#orderPanel",
      fallbackSelector: "#orderPanel",
      panelGroup: "core",
      priority: 82,
    };
  }

  const shelf = shopShelfPrepWorldBoardSpec(refs.world?.width || 960, refs.world?.height || 640);
  if (shelf?.itemId) {
    return {
      type: "shop",
      itemId: shelf.itemId,
      title: "把回款接到旧铺",
      label: shelf.itemName,
      detail: `${shelf.customerName}会看${shelf.hotTagLabel} · ${shelf.openingExpectation}`,
      metric: `${shelf.count} 份可摆`,
      selector: shelf.selector || '[data-shop-board="display-diagnosis"]',
      fallbackSelector: "#shopReport",
      panelGroup: "core",
      priority: 66,
    };
  }

  const seed = orderRewardNextUseSeedCandidate();
  if (seed) return seed;

  const recipe = recipeCraftPreviewSpec();
  if (recipe?.recipeId) {
    return {
      type: "recipe",
      recipeId: recipe.recipeId,
      title: "把回款变成下一锅",
      label: recipe.recipeName,
      detail: `${recipe.inputText} · ${recipe.orderLine}`,
      metric: recipe.craftable ? "可下锅" : "先备料",
      selector: "#recipeSelect",
      fallbackSelector: "#recipeCraftPreview",
      panelGroup: "core",
      priority: 42,
    };
  }

  return null;
}

