function qualityQuestItemIdForCrop(cropId = "") {
  if (cropId === BAIZHI_CROP_ID) return BAIZHI_QUALITY_ITEM_ID;
  return "";
}

function recordHarvestProgress(itemId, count = 0) {
  if (!itemId || Number(count) <= 0) return 0;
  state.harvestCounts[itemId] = Number(state.harvestCounts[itemId] || 0) + Number(count || 0);
  return Number(state.harvestCounts[itemId] || 0);
}

function harvestQualitySpec(crop = null, plot = null, amount = 1, affinity = cropSolarAffinity(crop, plot)) {
  const runtime = farmingRuntime();
  if (runtime) return runtime.harvestQualitySpec(crop, plot, amount, affinity);
  if (!crop) return { score: 0, tier: 1, label: "凡品", qualityItemId: "", qualityCount: 0 };
  const baseScore = Number(crop.base_quality_weight || 50);
  const affinityBonus = affinity.state === "boost" ? 14 : affinity.state === "season" ? 8 : affinity.state === "risk" ? -16 : 0;
  const soilBonus = plot?.waterSoil ? (crop.element_type === "water" ? 10 : 2) : 0;
  const spiritBonus = state.spirits.length > 0 ? 4 : 0;
  const cleanGrowBonus = plot?.watered ? 2 : 0;
  const score = baseScore + affinityBonus + soilBonus + spiritBonus + cleanGrowBonus;
  const tier = score >= 92 ? 3 : score >= 72 ? 2 : 1;
  const qualityItemId = tier >= 2 ? qualityQuestItemIdForCrop(crop.crop_id) : "";
  const qualityCount = qualityItemId
    ? Math.max(1, Math.min(Number(amount || 1), Math.round(Number(amount || 1) * (tier >= 3 ? 0.8 : 0.6))))
    : 0;
  return {
    score,
    tier,
    label: tier >= 3 ? "上品" : tier >= 2 ? "良品" : "凡品",
    qualityItemId,
    qualityCount,
  };
}

function aggregatedRecipeInputs(recipe = null) {
  if (!recipe) return [];
  const totals = new Map();
  for (const { itemId, count } of recipeInputs(recipe)) {
    totals.set(itemId, Number(totals.get(itemId) || 0) + Number(count || 1));
  }
  return [...totals.entries()].map(([itemId, count]) => ({ itemId, count }));
}

function recipeUsesItem(recipe = null, itemId = "") {
  return aggregatedRecipeInputs(recipe).some((input) => input.itemId === itemId);
}

function recipeCraftReady(recipe = null) {
  return Boolean(recipe && recipeUnlocked(recipe) && recipeMachine(recipe) && aggregatedRecipeInputs(recipe).every(({ itemId, count }) => hasItem(itemId, count)));
}

function outputRecipesFor(itemId = "") {
  if (!itemId) return [];
  return data.recipes.filter((recipe) => recipe.output_item_id === itemId);
}

function bestRecipeForOutput(itemId = "", { preferredInputId = "" } = {}) {
  const recipes = outputRecipesFor(itemId);
  if (!recipes.length) return null;
  const fallback = data.recipesByOutput.get(itemId) || recipes[0];
  return recipes
    .map((recipe) => {
      const craftable = recipeCraftReady(recipe);
      const unlocked = recipeUnlocked(recipe);
      const machineReady = Boolean(recipeMachine(recipe));
      const preferred = preferredInputId && recipeUsesItem(recipe, preferredInputId);
      const waterwayBridge = recipe.recipe_id === "recipe_helu_tangshui_shuihang" && state.completed.has("qinghe_water_fresh_return_order_done");
      return {
        recipe,
        score: (craftable ? 120 : unlocked && machineReady ? 86 : unlocked ? 62 : 24)
          + (preferred ? 28 : 0)
          + (waterwayBridge ? 12 : 0)
          + Math.min(12, Number(recipe.sell_value_weight || 1) * 4),
      };
    })
    .sort((a, b) => b.score - a.score || Number(a.recipe.base_process_time || 999) - Number(b.recipe.base_process_time || 999))[0]?.recipe || fallback;
}

function orderNeedStatus(order = null) {
  const needs = order ? orderNeeds(order) : [];
  const missing = needs
    .map(({ itemId, count }) => ({
      itemId,
      count,
      have: Number(state.inventory[itemId] || 0),
    }))
    .filter((entry) => entry.have < entry.count);
  return {
    needs,
    missing,
    ready: missing.length === 0,
    missingText: missing.map((entry) => `${itemName(entry.itemId)} ${entry.have}/${entry.count}`).join("、"),
  };
}

function harvestDirectOrderRoute(itemId = "", count = 1) {
  const candidates = visibleOrders()
    .map((order) => {
      const need = orderNeeds(order).find((entry) => entry.itemId === itemId);
      if (!need) return null;
      const status = orderNeedStatus(order);
      const have = Number(state.inventory[itemId] || 0);
      const itemReady = have >= Number(need.count || 1);
      return {
        score: (status.ready ? 130 : itemReady ? 102 : 86) + Math.min(30, Number(order.reward_gold || 0) / 20),
        type: "order",
        itemId,
        itemName: itemName(itemId),
        count: Number(count || 1),
        badge: status.ready ? "可交单" : "订单差这味",
        headline: status.ready ? `订单已备齐：${orderTitle(order)}` : `订单差这味：${orderTitle(order)}`,
        detail: status.ready
          ? `${npcName(order.issuer_id || order.reward_favor_npc)}要的${itemName(itemId)}已经够数，订单板可以直接交付。`
          : `${npcName(order.issuer_id || order.reward_favor_npc)}还在等这批${itemName(itemId)}，当前 ${have}/${Number(need.count || 1)}。`,
        logText: status.ready ? `可交 ${orderTitle(order)}` : `可补 ${orderTitle(order)}`,
        cta: status.ready ? "去订单板交付" : "继续补齐订单",
        orderId: order.order_id,
        orderTitle: orderTitle(order),
        orderNpc: npcName(order.issuer_id || order.reward_favor_npc),
        ready: status.ready,
        missingText: status.missingText,
        targetName: orderTitle(order),
        day: state.day,
      };
    })
    .filter(Boolean)
    .sort((a, b) => b.score - a.score);
  return candidates[0] || null;
}

function harvestRecipeOrderRoute(itemId = "", count = 1) {
  const candidates = [];
  for (const order of visibleOrders()) {
    for (const need of orderNeeds(order)) {
      const recipe = bestRecipeForOutput(need.itemId, { preferredInputId: itemId });
      if (!recipe || !recipeUsesItem(recipe, itemId)) continue;
      const status = orderNeedStatus(order);
      const readyToCraft = recipeCraftReady(recipe);
      candidates.push({
        score: (readyToCraft ? 92 : recipeUnlocked(recipe) ? 72 : 48) + Math.min(22, Number(order.reward_gold || 0) / 28),
        type: "order",
        itemId,
        itemName: itemName(itemId),
        count: Number(count || 1),
        badge: readyToCraft ? "可入锅接单" : "订单差这味",
        headline: readyToCraft ? `先入锅接单：${recipeName(recipe)}` : `订单差这味：${orderTitle(order)}`,
        detail: readyToCraft
          ? `${itemName(itemId)}够做${recipeName(recipe)}，出锅后可补 ${orderTitle(order)}。`
          : `${orderTitle(order)}需要${itemName(need.itemId)}，先备${recipeName(recipe)}的原料：${recipeInputStatus(recipe, 4)}。`,
        logText: readyToCraft ? `可做 ${recipeName(recipe)} 接 ${orderTitle(order)}` : `可备 ${orderTitle(order)}`,
        cta: readyToCraft ? "去工坊排产" : "按配方备料",
        recipeId: recipe.recipe_id,
        recipeName: recipeName(recipe),
        orderId: order.order_id,
        orderTitle: orderTitle(order),
        orderNpc: npcName(order.issuer_id || order.reward_favor_npc),
        ready: status.ready,
        missingText: status.missingText,
        targetName: orderTitle(order),
        day: state.day,
      });
    }
  }
  return candidates.sort((a, b) => b.score - a.score)[0] || null;
}

function harvestRecipeRoute(itemId = "", count = 1) {
  const candidates = data.recipes
    .filter((recipe) => recipeUsesItem(recipe, itemId))
    .map((recipe) => {
      const inputs = aggregatedRecipeInputs(recipe);
      const ownNeed = inputs.find((input) => input.itemId === itemId);
      const unlocked = recipeUnlocked(recipe);
      const machineReady = Boolean(recipeMachine(recipe));
      const craftable = recipeCraftReady(recipe);
      return {
        score: craftable ? 84 : unlocked && machineReady ? 68 : unlocked ? 54 : 28,
        type: "recipe",
        itemId,
        itemName: itemName(itemId),
        count: Number(count || 1),
        badge: "可入锅",
        headline: `可入锅：${recipeName(recipe)}`,
        detail: craftable
          ? `${itemName(itemId)}已经够用，${recipeMachineHint(recipe)}，可以直接做${recipeName(recipe)}。`
          : `${recipeName(recipe)}会用到${itemName(itemId)} ${Number(state.inventory[itemId] || 0)}/${Number(ownNeed?.count || 1)}，${recipeMachineHint(recipe)}。`,
        logText: `可做 ${recipeName(recipe)}`,
        cta: craftable ? "去工坊制作" : "继续备齐原料",
        recipeId: recipe.recipe_id,
        recipeName: recipeName(recipe),
        ready: craftable,
        targetName: recipeName(recipe),
        day: state.day,
      };
    })
    .sort((a, b) => b.score - a.score || a.targetName.localeCompare(b.targetName, "zh-Hans-CN"));
  return candidates[0] || null;
}

function harvestShopRoute(itemId = "", count = 1) {
  const item = data.itemsById.get(itemId);
  if (!item || item.item_type === "seed" || Number(item.sell_price_base || 0) <= 0) return null;
  const ecologyGarden = ecologyCourtyardSummary();
  const tags = shopTagsForItem(itemId, ecologyGarden).filter(Boolean);
  if (!tags.length) return null;
  const primaryTag = prioritizeShopTag(tags, new Map(tags.map((tag) => [tag, 1])), "crop");
  const theme = data.shopShelfThemes.find((entry) => entry.theme_tag === state.shopShelfTheme);
  const themeTags = splitTags(theme?.required_item_tags || "");
  const shelfFit = themeTags.includes(primaryTag) || tags.some((tag) => themeTags.includes(tag));
  const label = shopTagLabel(primaryTag);
  return {
    score: shelfFit ? 62 : 46,
    type: "shop",
    itemId,
    itemName: itemName(itemId),
    count: Number(count || 1),
    badge: "旧铺可卖",
    headline: `旧铺可卖：${label}`,
    detail: shelfFit
      ? `${itemName(itemId)}适合当前货架主题，可作为${label}摆上旧铺。`
      : `${itemName(itemId)}带有${label}标签，可留作旧铺鲜货或后续主题货架。`,
    logText: `可摆旧铺：${label}`,
    cta: "开铺试卖",
    shopTag: primaryTag,
    shopTagLabel: label,
    ready: true,
    targetName: label,
    day: state.day,
  };
}

function harvestUseRouteSafe(route = null) {
  if (!route) return null;
  return {
    type: route.type || "stock",
    itemId: route.itemId || "",
    itemName: route.itemName || itemName(route.itemId || ""),
    count: Number(route.count || 1),
    badge: route.badge || "收获去向",
    headline: route.headline || "",
    detail: route.detail || "",
    logText: route.logText || route.detail || "",
    cta: route.cta || "",
    recipeId: route.recipeId || "",
    recipeName: route.recipeName || "",
    orderId: route.orderId || "",
    orderTitle: route.orderTitle || "",
    orderNpc: route.orderNpc || "",
    shopTag: route.shopTag || "",
    shopTagLabel: route.shopTagLabel || "",
    targetName: route.targetName || route.recipeName || route.orderTitle || route.shopTagLabel || "",
    ready: Boolean(route.ready),
    missingText: route.missingText || "",
    day: Number(route.day || state.day),
  };
}

function harvestUseRouteSpec(itemId = "", count = 1) {
  if (!itemId) return null;
  const routeCandidates = [
    harvestDirectOrderRoute(itemId, count),
    harvestRecipeOrderRoute(itemId, count),
    harvestRecipeRoute(itemId, count),
    harvestShopRoute(itemId, count),
  ];
  const fallbackRoute = {
      type: "stock",
      itemId,
      itemName: itemName(itemId),
      count: Number(count || 1),
      badge: "收进仓",
      headline: `收获入仓：${itemName(itemId)}`,
      detail: `${itemName(itemId)}先收进仓库，后续配方、订单或旧铺标签会自动接上。`,
      logText: "先留作库存",
      cta: "继续经营",
      targetName: "库存",
      ready: true,
      day: state.day,
    };
  const route = farmingRuntime()?.harvestRouteSelectionPlan({
    candidates: routeCandidates,
    fallbackRoute,
    itemId,
    count,
    day: state.day,
  })?.route
    || routeCandidates.find(Boolean)
    || fallbackRoute;
  return harvestUseRouteSafe(route);
}

function harvestQualityStars(tier = 1) {
  const count = Math.max(1, Math.min(3, Number(tier || 1)));
  return "★".repeat(count) + "☆".repeat(3 - count);
}

function harvestFeedbackSpec(crop = null, amount = 1, quality = null, useRoute = null, bonuses = {}) {
  if (!crop) return null;
  const route = harvestUseRouteSafe(useRoute);
  const qualityTier = Number(quality?.tier || 1);
  const qualityCount = Number(quality?.qualityCount || 0);
  const bonusParts = [];
  if (Number(bonuses.harvestBonus || 0) > 0) bonusParts.push(`岗位熟练 +${bonuses.harvestBonus}`);
  if (Number(bonuses.cohabWaterBonus || 0) > 0) bonusParts.push(`同住水线 +${bonuses.cohabWaterBonus}`);
  if (Number(bonuses.pondCropBonus || 0) > 0) bonusParts.push(`灵池水位 +${bonuses.pondCropBonus}`);
  if (Number(bonuses.solarYieldAmount || 0) > 0) bonusParts.push(`节气适性 +${bonuses.solarYieldAmount}`);
  return {
    id: `${crop.crop_id}:${state.day}:${performance.now()}`,
    cropId: crop.crop_id,
    cropName: itemName(crop.crop_id),
    amount: Number(amount || 1),
    qualityLabel: quality?.label || "凡品",
    qualityTier,
    qualityStars: harvestQualityStars(qualityTier),
    qualityItemName: quality?.qualityItemId ? itemName(quality.qualityItemId) : "",
    qualityCount,
    route,
    routeBadge: route?.badge || "收进仓",
    routeHeadline: route?.headline || `收获入仓：${itemName(crop.crop_id)}`,
    routeDetail: route?.detail || "先收进仓库，后续配方、订单或旧铺标签会自动接上。",
    bonusText: bonusParts.length ? bonusParts.join(" · ") : "基础收获",
    firstHarvest: !state.completed.has("harvest"),
    day: state.day,
    createdAt: performance.now(),
  };
}

function seedProjectedHarvestSpec(crop = null, plot = selectedPlot()) {
  const runtime = farmingRuntime();
  if (runtime) return runtime.seedProjectedHarvestSpec(crop, plot);
  if (!crop) return { count: 1, affinity: null, yieldBonus: { amount: 0, text: "" } };
  const simulatedPlot = {
    ...(plot || {}),
    cropId: crop.crop_id,
    seedItemId: crop.seed_item_id,
  };
  const affinity = cropSolarAffinity(crop, simulatedPlot);
  const yieldBonus = cropSolarYieldBonus(crop, simulatedPlot, affinity);
  return {
    count: Math.max(1, Number(crop.harvest_yield_min || 1) + Number(yieldBonus.amount || 0)),
    affinity,
    yieldBonus,
  };
}

function seedProjectedHave(itemId = "", cropId = "", projectedCount = 1) {
  return Number(state.inventory[itemId] || 0) + (itemId === cropId ? Number(projectedCount || 0) : 0);
}

function seedRecipeReadyAfterHarvest(recipe = null, cropId = "", projectedCount = 1) {
  return Boolean(recipe && recipeUnlocked(recipe) && recipeMachine(recipe) && aggregatedRecipeInputs(recipe).every(({ itemId, count }) => seedProjectedHave(itemId, cropId, projectedCount) >= Number(count || 1)));
}

function seedUseRouteSafe(route = null) {
  const safe = harvestUseRouteSafe(route);
  return safe
    ? {
      ...safe,
      seedId: route.seedId || "",
      cropId: route.cropId || route.itemId || "",
      projectedCount: Number(route.projectedCount || safe.count || 1),
      growDays: Number(route.growDays || 1),
      previewText: route.previewText || "",
    }
    : null;
}

function seedDirectOrderRoute(crop = null, projectedCount = 1) {
  if (!crop) return null;
  const cropId = crop.crop_id;
  const candidates = visibleOrders()
    .map((order) => {
      const need = orderNeeds(order).find((entry) => entry.itemId === cropId);
      if (!need) return null;
      const haveAfter = seedProjectedHave(cropId, cropId, projectedCount);
      const readyAfter = haveAfter >= Number(need.count || 1);
      return {
        score: (readyAfter ? 124 : 90) + Math.min(28, Number(order.reward_gold || 0) / 22),
        type: "order",
        itemId: cropId,
        itemName: itemName(cropId),
        count: Number(projectedCount || 1),
        badge: readyAfter ? "成熟可交单" : "可补订单",
        headline: readyAfter ? `成熟后可交：${orderTitle(order)}` : `成熟后补单：${orderTitle(order)}`,
        detail: readyAfter
          ? `预计收获 ${projectedCount} 份，${npcName(order.issuer_id || order.reward_favor_npc)}要的${itemName(cropId)}会够数。`
          : `预计收获 ${projectedCount} 份，可把 ${orderTitle(order)} 推到 ${haveAfter}/${Number(need.count || 1)}。`,
        logText: readyAfter ? `成熟后可交 ${orderTitle(order)}` : `成熟后可补 ${orderTitle(order)}`,
        cta: "按订单备货",
        orderId: order.order_id,
        orderTitle: orderTitle(order),
        orderNpc: npcName(order.issuer_id || order.reward_favor_npc),
        ready: readyAfter,
        targetName: orderTitle(order),
        day: state.day,
      };
    })
    .filter(Boolean)
    .sort((a, b) => b.score - a.score);
  return candidates[0] || null;
}

function seedRecipeOrderRoute(crop = null, projectedCount = 1) {
  if (!crop) return null;
  const cropId = crop.crop_id;
  const candidates = [];
  for (const order of visibleOrders()) {
    for (const need of orderNeeds(order)) {
      const recipe = bestRecipeForOutput(need.itemId, { preferredInputId: cropId });
      if (!recipe || !recipeUsesItem(recipe, cropId)) continue;
      const readyAfter = seedRecipeReadyAfterHarvest(recipe, cropId, projectedCount);
      candidates.push({
        score: (readyAfter ? 104 : recipeUnlocked(recipe) ? 78 : 52) + Math.min(24, Number(order.reward_gold || 0) / 30),
        type: "order",
        itemId: cropId,
        itemName: itemName(cropId),
        count: Number(projectedCount || 1),
        badge: readyAfter ? "成熟可入锅接单" : "订单备料",
        headline: readyAfter ? `成熟后入锅接单：${recipeName(recipe)}` : `成熟后备料：${orderTitle(order)}`,
        detail: readyAfter
          ? `${itemName(cropId)}成熟后预计能做${recipeName(recipe)}，出锅可接 ${orderTitle(order)}。`
          : `${orderTitle(order)}需要${itemName(need.itemId)}，这颗种子会补上${recipeName(recipe)}的一味原料。`,
        logText: readyAfter ? `成熟后可做 ${recipeName(recipe)} 接 ${orderTitle(order)}` : `成熟后可备 ${orderTitle(order)}`,
        cta: readyAfter ? "成熟后进工坊" : "继续备齐配方",
        recipeId: recipe.recipe_id,
        recipeName: recipeName(recipe),
        orderId: order.order_id,
        orderTitle: orderTitle(order),
        orderNpc: npcName(order.issuer_id || order.reward_favor_npc),
        ready: readyAfter,
        targetName: orderTitle(order),
        day: state.day,
      });
    }
  }
  return candidates.sort((a, b) => b.score - a.score)[0] || null;
}

function seedRecipeRoute(crop = null, projectedCount = 1) {
  if (!crop) return null;
  const cropId = crop.crop_id;
  const candidates = data.recipes
    .filter((recipe) => recipeUsesItem(recipe, cropId))
    .map((recipe) => {
      const readyAfter = seedRecipeReadyAfterHarvest(recipe, cropId, projectedCount);
      return {
        score: readyAfter ? 88 : recipeUnlocked(recipe) ? 70 : 38,
        type: "recipe",
        itemId: cropId,
        itemName: itemName(cropId),
        count: Number(projectedCount || 1),
        badge: readyAfter ? "成熟可入锅" : "配方备料",
        headline: readyAfter ? `成熟后可入锅：${recipeName(recipe)}` : `成熟后可备：${recipeName(recipe)}`,
        detail: readyAfter
          ? `预计收获 ${projectedCount} 份，${recipeMachineHint(recipe)}，成熟后可直接做${recipeName(recipe)}。`
          : `${recipeName(recipe)}会用到${itemName(cropId)}，成熟后先看工坊原料是否齐全。`,
        logText: readyAfter ? `成熟后可做 ${recipeName(recipe)}` : `成熟后可备 ${recipeName(recipe)}`,
        cta: readyAfter ? "成熟后制作" : "继续备料",
        recipeId: recipe.recipe_id,
        recipeName: recipeName(recipe),
        ready: readyAfter,
        targetName: recipeName(recipe),
        day: state.day,
      };
    })
    .sort((a, b) => b.score - a.score || a.targetName.localeCompare(b.targetName, "zh-Hans-CN"));
  return candidates[0] || null;
}

function seedShopRoute(crop = null, projectedCount = 1) {
  if (!crop) return null;
  const route = harvestShopRoute(crop.crop_id, projectedCount);
  if (!route) return null;
  return {
    ...route,
    score: Number(route.score || 0) + 8,
    badge: "旧铺备货",
    headline: `成熟后可摆旧铺：${route.shopTagLabel}`,
    detail: `${itemName(crop.crop_id)}成熟后可作为${route.shopTagLabel}上架，适合在开铺前先攒鲜货。`,
    logText: `成熟后可摆旧铺：${route.shopTagLabel}`,
    cta: "成熟后试卖",
  };
}

function seedUseRouteSpec(cropOrSeed = null, plot = selectedPlot()) {
  const crop = typeof cropOrSeed === "string"
    ? data.cropsBySeed.get(cropOrSeed) || data.cropsById.get(cropOrSeed)
    : cropOrSeed;
  if (!crop) return null;
  const projected = seedProjectedHarvestSpec(crop, plot);
  const route = seedDirectOrderRoute(crop, projected.count)
    || seedRecipeOrderRoute(crop, projected.count)
    || seedRecipeRoute(crop, projected.count)
    || seedShopRoute(crop, projected.count)
    || {
      type: "stock",
      itemId: crop.crop_id,
      itemName: itemName(crop.crop_id),
      count: projected.count,
      badge: "成熟入仓",
      headline: `成熟后入仓：${itemName(crop.crop_id)}`,
      detail: `预计 ${Number(crop.grow_days || 1)} 夜后收获 ${projected.count} 份，后续配方、订单或旧铺标签会自动接上。`,
      logText: "成熟后先留作库存",
      cta: "继续规划",
      targetName: "库存",
      ready: true,
      day: state.day,
    };
  return seedUseRouteSafe({
    ...route,
    seedId: crop.seed_item_id,
    cropId: crop.crop_id,
    projectedCount: projected.count,
    growDays: Number(crop.grow_days || 1),
    previewText: `${Number(crop.grow_days || 1)} 夜后约 ${projected.count} 份`,
  });
}

function growingCropUseRouteSpec(plot = selectedPlot()) {
  if (!plot?.cropId) return null;
  const crop = data.cropsById.get(plot.cropId);
  if (!crop) return null;
  const route = seedUseRouteSpec(crop, plot);
  if (!route) return null;
  const growDays = Number(crop.grow_days || 1);
  const age = Math.max(0, state.day - Number(plot.plantedDay || state.day));
  const remaining = plot.mature ? 0 : Math.max(0, growDays - age);
  return {
    ...route,
    badge: plot.mature ? route.badge.replace("成熟", "可收") : route.badge,
    headline: plot.mature ? route.headline.replace("成熟后", "收获后") : route.headline,
    detail: plot.mature
      ? route.detail.replace(/预计\s*\d+\s*夜后/, "现在收获后")
      : route.detail,
    remainingDays: remaining,
    previewText: plot.mature ? `现在可收 · 约 ${route.projectedCount} 份` : `约 ${remaining} 夜后成熟 · ${route.projectedCount} 份`,
    liveText: plot.mature ? "收后去向" : "长成去向",
  };
}

