function focusCropGrowthMemoWorldFromCanvas(spec = cropGrowthMemoWorldSpec()) {
  const row = spec?.activeRow || spec?.top;
  if (!row?.plot) {
    addLog("田垄今日长势小札", "今天还没有可解读的已种作物，先播下一块田。");
    return renderLogs();
  }
  cropGrowthMemoWorldFocus = { key: spec.key, day: state.day, plotKey: `${row.x},${row.y}`, tone: row.tone };
  state.selected = { x: row.x, y: row.y };
  pulseAtPlot(row.plot, row.tone === "harvest" ? "harvest" : row.tone === "water" ? "water" : "plant", {
    harvestText: row.stageLabel,
  });
  addLog("点选田垄今日长势小札", `${row.cropName} 已定位到 (${row.x + 1},${row.y + 1})。${row.reason} ${spec.safetyText}`);
  if (row.action?.key === "order" && row.route?.orderId) return focusPlotRouteOrder(row.route.orderId);
  if (row.action?.key === "recipe" && row.route?.recipeId) return focusPlotRouteRecipe(row.route.recipeId);
  if (row.action?.key === "shop") return focusPlotRouteShop(row.route?.shopTag || "", row.route?.itemId || row.plot.cropId);
  if (row.action?.key === "term" || row.tone === "risk") {
    return queueStoryCompassFocusTarget({
      selector: row.action?.selector || "#riskPanel",
      fallbackSelector: row.action?.fallbackSelector || "#termPanel",
      label: "田垄今日长势小札：看风险",
      log: `${row.cropName} 的风险来源已定位到节气/风险面板。${spec.safetyText}`,
      panelGroup: row.action?.panelGroup || "systems",
      missingTitle: "田垄今日长势小札",
      missingLog: "节气风险面板暂时没有找到，先查看节气影响面板。",
    });
  }
  return queuePlotRouteFocusTarget({
    selector: row.action?.selector || "#selectedPlotCard",
    fallbackSelector: "#selectedPlotCard",
    label: `田垄今日长势小札：${row.action?.label || "看灵田"}`,
    log: `${row.cropName} 的灵田卡已定位。${row.reason} ${spec.safetyText}`,
    panelGroup: row.action?.panelGroup || "core",
    missingTitle: "田垄今日长势小札",
    missingLog: "灵田卡暂时没有找到，但田块已经选中。",
  });
}

