function spiritManorResourceStatus() {
  const building = spiritManorBuilding();
  const cost = demoBuildCost(building);
  const metalOwned = Number(state.inventory.item_metal_xuantie || 0) + Number(state.inventory.item_ore_iron || 0) + Number(state.inventory.item_ore_iron_raw || 0);
  const specialItem = cost.specialItem || building.cost_special_item || "item_cloth_liuyunsi";
  const specialOwned = specialItem ? Number(state.inventory[specialItem] || 0) : 0;
  const rows = [
    { id: "gold", label: "灵石", owned: Number(state.gold || 0), need: Number(cost.gold || 0) },
    { id: "wood", label: "木材", owned: Number(state.inventory.item_wood_basic || 0), need: Number(cost.wood || 0) },
    { id: "stone", label: "石材", owned: Number(state.inventory.item_stone_basic || 0), need: Number(cost.stone || 0) },
    { id: "metal", label: itemName("item_metal_xuantie"), owned: metalOwned, need: Number(cost.metal || 0) },
    { id: specialItem, label: itemName(specialItem), owned: specialOwned, need: Number(cost.specialCount || 0) },
  ].filter((row) => row.need > 0);
  const done = rows.filter((row) => row.owned >= row.need).length;
  return {
    rows,
    done,
    total: rows.length,
    summary: rows.map((row) => `${row.label} ${Math.min(row.owned, row.need)}/${row.need}`).join(" · "),
    missing: rows.filter((row) => row.owned < row.need).map((row) => `${row.label}差 ${row.need - row.owned}`).join("、"),
  };
}

