function startSpiritManorChapter(eventName = "百怪大院蓝图") {
  const firstStart = !state.completed.has(SPIRIT_MANOR_ENTRY_FLAG);
  state.completed.add(SPIRIT_MANOR_ENTRY_FLAG);
  state.completed.add(`quest_unlock_${SPIRIT_MANOR_QUEST_ID}`);
  state.triggeredEvents.add(SPIRIT_MANOR_ENTRY_EVENT_ID);
  if (firstStart) addNpcFavor("npc_atan", 8, "百怪大院蓝图");
  triggerSpiritManorFeedback("entry", eventName);
  queueDialogueGroup("dialogue_main_0301_spirit_manor");
  playCue("成就解锁");
  addLog("第三章开启", `${eventName}：阿檀已经把百怪大院蓝图摊开，精怪宿舍、岗位总览与情绪管理进入建设目标。`);
  return true;
}

function unlockSpiritManorOverview(eventName = "百怪大院建成") {
  const firstUnlock = !state.completed.has(SPIRIT_MANOR_OVERVIEW_FLAG);
  state.completed.add(SPIRIT_MANOR_OVERVIEW_FLAG);
  state.completed.add("spirit_housing_management");
  state.triggeredEvents.add(SPIRIT_MANOR_BUILD_EVENT_ID);
  if (!state.missionDone.has(SPIRIT_MANOR_QUEST_ID)) state.missionDone.add(SPIRIT_MANOR_QUEST_ID);
  if (firstUnlock) {
    addNpcFavor("npc_atan", 10, "百怪大院落成");
    state.fame += 5;
  }
  triggerSpiritManorFeedback("build", eventName);
  queueDialogueGroup("dialogue_main_0303_spirit_overview");
  playCue("成就解锁");
  addLog("百怪大院建成", `${eventName}：岗位总览、宿舍分配与情绪管理已接入精怪面板，洞天自动化进入第三章。`);
  if (!state.triggeredEvents.has(FACTION_ORDER_ENTRY_EVENT_ID)) {
    startFactionOrderChapter(localize("event_name_main_0302", "商会来客"));
  }
  return true;
}

