function chapter3TradeStarted() {
  return state.completed.has(CHAPTER_3_TRADE_FLAG)
    || state.triggeredEvents.has(FACTION_ORDER_ENTRY_EVENT_ID)
    || state.missionDone.has(FACTION_ORDER_QUEST_ID);
}

function fireRuinUnlocked() {
  return state.completed.has(FIRE_RUIN_UNLOCK_FLAG)
    || state.triggeredEvents.has(FIRE_RUIN_UNLOCK_EVENT_ID)
    || state.triggeredEvents.has(FIRE_RUIN_ENTRY_EVENT_ID);
}

function fireRuinEntered() {
  return state.completed.has(FIRE_RUIN_AREA_ID) || state.triggeredEvents.has(FIRE_RUIN_ENTRY_EVENT_ID);
}

function fireRuinFinished() {
  return state.completed.has(FIRE_RUIN_FINISH_FLAG)
    || state.triggeredEvents.has(FIRE_RUIN_FINISH_EVENT_ID)
    || state.defeatedBosses.has(FIRE_RUIN_BOSS_ID)
    || state.claimedQuestRewards.has(FACTION_ORDER_QUEST_ID);
}

function chapter3TradeFeedbackSpec(phase = "entry", eventName = "商会来客") {
  const quest = factionOrderQuest();
  const order = data.orders.find((entry) => entry.order_id === FACTION_ORDER_ID);
  const dungeon = fireRuinDungeon();
  const bossId = dungeonBossId(dungeon);
  const orderNeedText = order
    ? orderNeeds(order).map(({ itemId, count }) => `${itemName(itemId)} x${count}`).join(" · ")
    : `${itemName("item_drink_xuanxiang_lingniang")} x4 · ${itemName("item_gift_yunjin_lijuan")} x2`;
  const orderText = order ? orderTitle(order) : localize("order_name_faction_0001", FACTION_ORDER_ID);
  const titles = {
    entry: eventName,
    unlock: "炽砂旧采路",
    entry_area: eventName,
    finish: eventName,
  };
  const headline = phase === "unlock"
    ? "胡四海把旧采路摊给你了"
    : phase === "finish"
      ? "火位核心在洞天重新亮起"
    : phase === "entry_area"
      ? "热浪正从断阵里往外拱"
      : "外路第一张像样的大单到了";
  const detail = phase === "unlock"
    ? "门派采办首单交稳后，胡四海把夹在账页里的残图翻了出来，炽砂遗迹的旧采路终于重新认了门。"
    : phase === "finish"
      ? `${bossName(FIRE_RUIN_BOSS_ID)} 已伏，${itemName(FIRE_CORE_ITEM_ID)} 被压回阵眼。洞天的火位不再只是余烬，而像一颗重新跳动的炉心。`
    : phase === "entry_area"
      ? "断墙缝里还喘着旧火，首单背后的那条线果然通向一处炽砂残阵。门派客口中的“火脉”，就在更深处。"
      : "胡四海带来的不是散单，而是要看成套、稳定、像样的门派采办。把这单交漂亮，外路生意和炽砂线索才会真往你手里落。";
  const cta = phase === "unlock"
    ? `下一步：进入${dungeonName(dungeon)}，追查 ${bossName(bossId)} 与 ${itemName("item_special_huojing")}。`
    : phase === "finish"
      ? "下一步：领取第三章任务奖励，准备面对九曜大旱与二十四枢的终章前置。"
    : phase === "entry_area"
      ? `下一步：在${dungeonName(dungeon)}里继续深入，目标 ${bossName(bossId)}，带回 ${itemName("item_special_huojing")}。`
      : `下一步：在订单板交付 ${orderText}，备齐 ${orderNeedText}。`;
  const rewardHint = phase === "unlock"
    ? `${dungeonName(dungeon)} · Boss ${bossName(bossId)}`
    : phase === "finish"
      ? `${itemName(FIRE_CORE_ITEM_ID)} · 门派采办声望 · 第四章前置`
    : phase === "entry_area"
      ? `${bossName(bossId)} · ${itemName(FIRE_CORE_ITEM_ID)}`
      : `${questTitle(quest)} · 门派采办入口`;
  const orderHint = phase === "finish"
    ? "炽砂线已经能向外证明凡仙镇的稳定供给，后续门派大单会更看重精品柜、炼制炉与外路货。"
    : phase === "entry"
    ? `胡四海盯的是成套体面货：先备 ${orderNeedText}，把第一张门派采办单交稳。`
    : `${orderText} 已经把后路接上，接下来就看你敢不敢往火脉里走。`;
  const dungeonHint = phase === "finish"
    ? "炽砂遗迹的火位余波已经显示在洞天主场景；它会成为终章二十四枢的重要支点。"
    : phase === "entry"
    ? "首单完成后，炽砂遗迹会在秘境面板现形。"
    : "炽砂遗迹会压体力与补给节奏，入内前先看随行精怪、药品和 Boss 预期。";
  return {
    phase,
    eventId: phase === "entry" ? FACTION_ORDER_ENTRY_EVENT_ID : phase === "unlock" ? FIRE_RUIN_UNLOCK_EVENT_ID : phase === "finish" ? FIRE_RUIN_FINISH_EVENT_ID : FIRE_RUIN_ENTRY_EVENT_ID,
    questId: FACTION_ORDER_QUEST_ID,
    npcId: "npc_hu_sihai",
    areaId: FIRE_RUIN_AREA_ID,
    orderId: FACTION_ORDER_ID,
    title: titles[phase] || eventName,
    headline,
    detail,
    cta,
    rewardHint,
    orderHint,
    dungeonHint,
    createdAt: performance.now(),
  };
}

function triggerChapter3TradeFeedback(phase = "entry", eventName = "商会来客") {
  const feedback = chapter3TradeFeedbackSpec(phase, eventName);
  state.chapter3TradeFeedback = feedback;
  return feedback;
}

function chapter3TradePanelHint() {
  if (!chapter3TradeStarted() && !fireRuinUnlocked() && !fireRuinEntered() && !state.chapter3TradeFeedback) return null;
  const phase = fireRuinFinished() ? "finish" : fireRuinEntered() ? "entry_area" : fireRuinUnlocked() ? "unlock" : "entry";
  const eventName = phase === "entry"
    ? localize("event_name_main_0302", "商会来客")
    : phase === "unlock"
      ? localize("event_name_main_0305", "炽砂线索到手")
      : phase === "finish"
        ? localize("event_name_main_0307", "炽炎火精归位")
      : localize("event_name_main_0306", "炽砂遗迹开启");
  return state.chapter3TradeFeedback || chapter3TradeFeedbackSpec(phase, eventName);
}

function startFactionOrderChapter(eventName = "商会来客") {
  const firstStart = !chapter3TradeStarted();
  state.completed.add(CHAPTER_3_TRADE_FLAG);
  state.completed.add(`quest_unlock_${FACTION_ORDER_QUEST_ID}`);
  state.triggeredEvents.add(FACTION_ORDER_ENTRY_EVENT_ID);
  if (firstStart) addNpcFavor("npc_hu_sihai", 8, "商会来客");
  triggerChapter3TradeFeedback("entry", eventName);
  queueDialogueGroup("dialogue_main_0302_faction_order");
  playCue("成就解锁");
  addLog("商会来客", `${eventName}：胡四海把门派采办首单压到柜上，外路客真正开始按“成套、稳定、像样”的标准看你的货。`);
  return true;
}

function unlockFireRuin(eventName = "炽砂线索到手") {
  const firstUnlock = !fireRuinUnlocked();
  state.completed.add(FIRE_RUIN_UNLOCK_FLAG);
  state.triggeredEvents.add(FIRE_RUIN_UNLOCK_EVENT_ID);
  if (firstUnlock) addNpcFavor("npc_hu_sihai", 10, "炽砂旧采路");
  upsertWorldChange({
    key: FIRE_RUIN_UNLOCK_FLAG,
    dungeonId: FIRE_RUIN_AREA_ID,
    title: "炽砂旧采路重见天日",
    detail: "首单账页后头压着的残图被翻出来，旧采路尽头那道被风沙吞住的火门重新露了形。",
    rewardHint: `${dungeonName(fireRuinDungeon())} · Boss ${bossName(dungeonBossId(fireRuinDungeon()))}`,
    visualType: "embers_gate",
  });
  triggerChapter3TradeFeedback("unlock", eventName);
  playCue("成就解锁");
  addLog("炽砂线索到手", `${eventName}：胡四海把通往炽砂遗迹的旧采路摊给了你，秘境面板已经能看到这条火线。`);
  return true;
}

function startFireRuinExpedition(eventName = "炽砂遗迹开启") {
  if (!fireRuinUnlocked()) unlockFireRuin(localize("event_name_main_0305", "炽砂线索到手"));
  state.completed.add(FIRE_RUIN_AREA_ID);
  state.triggeredEvents.add(FIRE_RUIN_ENTRY_EVENT_ID);
  triggerChapter3TradeFeedback("entry_area", eventName);
  queueDialogueGroup("dialogue_main_0306_fire_ruin");
  playCue("成就解锁");
  addLog("炽砂遗迹", `${eventName}：旧采路尽头的残阵热浪还没死透，带回 ${itemName("item_special_huojing")} 才算真正把这条火线接稳。`);
  return true;
}

function finishFireRuinLine(eventName = "炽炎火精归位") {
  const plan = questRuntime()?.configuredEventFireRuinFinishActionPlan({
    event_id: FIRE_RUIN_FINISH_EVENT_ID,
    trigger_type: "on_boss_defeat",
    trigger_param: FIRE_RUIN_BOSS_ID,
    execute_group: "exec_finish_fire_ruin",
  });
  if (plan?.applies) {
    applyConfiguredEventActionPlan(plan, { eventName });
    return true;
  }
  const firstFinish = !state.completed.has(FIRE_RUIN_FINISH_FLAG);
  state.completed.add(FIRE_RUIN_FINISH_FLAG);
  state.completed.add("chapter_3_complete");
  state.completed.add("fire_core_restored");
  state.triggeredEvents.add(FIRE_RUIN_FINISH_EVENT_ID);
  if (!hasItem(FIRE_CORE_ITEM_ID, 1)) addItem(FIRE_CORE_ITEM_ID, 1);
  if (firstFinish) {
    addNpcFavor("npc_hu_sihai", 12, "炽炎火精");
    addNpcFavor("npc_shen_gudeng", 8, "炽砂遗迹归来");
    state.fame += 8;
  }
  upsertWorldChange({
    key: "fire_core_restored",
    dungeonId: FIRE_RUIN_AREA_ID,
    title: "火位核心归阵",
    detail: "炽炎火精压回阵眼后，旧采路的余烬不再乱窜，洞天工坊旁多出一圈稳定的赤金炉光。",
    rewardHint: `${itemName(FIRE_CORE_ITEM_ID)} · 高阶订单与终章前置`,
    visualType: "fire_core_beacon",
  });
  triggerChapter3TradeFeedback("finish", eventName);
  queueDialogueGroup("dialogue_main_0307_fire_ruin_finish");
  playCue("成就解锁");
  addLog("第三章收束", `${eventName}：${bossName(FIRE_RUIN_BOSS_ID)} 已伏，${itemName(FIRE_CORE_ITEM_ID)} 入手，门派大单与终章前置正式接上。`);
  updateMissions();
  checkQuestRewards();
  scanConfiguredEvents("fire_ruin:chapter_finish");
  return true;
}

function chapter4DroughtActive() {
  return state.completed.has(CHAPTER_4_DROUGHT_FLAG)
    || state.triggeredEvents.has(CHAPTER_4_DROUGHT_EVENT_ID)
    || state.missionDone.has(CHAPTER_4_DROUGHT_QUEST_ID);
}

function droughtReliefOrder() {
  return data.orders.find((order) => order.order_id === CHAPTER_4_DROUGHT_ORDER_ID);
}

function chapter4DroughtReliefDelivered() {
  return state.completed.has(CHAPTER_4_DROUGHT_RELIEF_DONE_FLAG)
    || state.completed.has(`${CHAPTER_4_DROUGHT_ORDER_ID}_delivered`)
    || state.completedOrders.has(CHAPTER_4_DROUGHT_ORDER_ID);
}

function chapter4ReliefSupplyCount() {
  return Math.max(
    Number(state.inventory[CHAPTER_4_DROUGHT_RELIEF_ITEM_ID] || 0),
    Number(state.harvestCounts[`collect_${CHAPTER_4_DROUGHT_RELIEF_ITEM_ID}`] || 0),
  );
}

function applyOrderRewardPool(order) {
  if (!order?.reward_item_group) return [];
  return rewardPoolEntries(order.reward_item_group)
    .filter((entry) => conditionMet(entry.condition_group || "always_true"))
    .map((entry) => applyRewardEntry(entry));
}

function chapter4DroughtFeedbackSpec(eventName = "九曜大旱降临") {
  const order = droughtReliefOrder();
  const orderNeedText = order
    ? orderNeeds(order).map(({ itemId, count }) => `${itemName(itemId)} x${count}`).join(" · ")
    : `${itemName("crop_qingshui_hulu")} x6 · ${itemName("item_med_zhixue_san")} x4 · ${itemName("crop_jinsui_yumi")} x8`;
  const delivered = chapter4DroughtReliefDelivered();
  const reliefCount = chapter4ReliefSupplyCount();
  return {
    eventId: CHAPTER_4_DROUGHT_EVENT_ID,
    questId: CHAPTER_4_DROUGHT_QUEST_ID,
    npcId: "npc_xubo",
    orderId: CHAPTER_4_DROUGHT_ORDER_ID,
    title: eventName,
    headline: delivered ? "第一批救援水囊送出去了" : "枯井把镇子的余裕敲空了",
    detail: delivered
      ? `许伯已经带人把水囊分到最撑不住的几户，救援物资 ${Math.min(reliefCount, 10)}/10。陆三笑在残碑前等你。`
      : "镇井见底，河床退线，凡仙镇不再只是来买货的地方。洞天灵泉必须先救人，再谈收成。",
    cta: delivered
      ? "下一步：领取九曜大旱任务奖励，前往残碑听陆三笑说明二十四枢。"
      : `下一步：优先完成${order ? orderTitle(order) : "大旱应急订单"}，备齐 ${orderNeedText}。`,
    rewardHint: delivered ? `${itemName(CHAPTER_4_DROUGHT_RELIEF_ITEM_ID)} ${Math.min(reliefCount, 10)}/10 · 二十四枢线索` : `${itemName(CHAPTER_4_DROUGHT_RELIEF_ITEM_ID)} 5/10 · 救灾作物种子已备`,
    orderHint: delivered ? "救援水囊已经发出，镇上的井边终于没有那么乱。任务书会结算第一段大旱救援。" : `许伯已经把救援名单压到柜上：${orderNeedText}。这张单优先级高于普通经营。`,
    worldHint: delivered ? "主场景的旱热仍在，但枯井旁已经出现临时水棚与排队秩序。" : "主场景会持续显示干裂田垄、枯井与热雾；干热天气会压低水分与作物成长。",
    createdAt: performance.now(),
  };
}

function triggerChapter4DroughtFeedback(eventName = "九曜大旱降临") {
  const feedback = chapter4DroughtFeedbackSpec(eventName);
  state.chapter4DroughtFeedback = feedback;
  return feedback;
}

function chapter4DroughtPanelHint() {
  if (!chapter4DroughtActive() && !state.chapter4DroughtFeedback) return null;
  return state.chapter4DroughtFeedback || chapter4DroughtFeedbackSpec(localize("event_name_main_0401", "九曜大旱降临"));
}

function startChapter4Drought(eventName = "九曜大旱降临") {
  const plan = questRuntime()?.configuredEventChapter4DroughtStartActionPlan({
    event_id: CHAPTER_4_DROUGHT_EVENT_ID,
    trigger_type: "on_day_start",
    trigger_param: "day_67",
    execute_group: "exec_world_state_drought",
  });
  if (plan?.applies) {
    applyConfiguredEventActionPlan(plan, { eventName });
    return true;
  }
  const firstStart = !state.completed.has(CHAPTER_4_DROUGHT_FLAG) && !state.triggeredEvents.has(CHAPTER_4_DROUGHT_EVENT_ID);
  state.completed.add(CHAPTER_4_DROUGHT_FLAG);
  state.completed.add("drought");
  state.completed.add(`quest_unlock_${CHAPTER_4_DROUGHT_QUEST_ID}`);
  state.triggeredEvents.add(CHAPTER_4_DROUGHT_EVENT_ID);
  state.weatherId = "weather_dry_heat";
  if (firstStart) {
    addNpcFavor("npc_xubo", 10, "九曜大旱先救人");
    addNpcFavor("npc_qinghe", 8, "借洞天灵泉");
    state.fame += 6;
    addItem(CHAPTER_4_DROUGHT_RELIEF_ITEM_ID, 5);
    addItem("seed_qingshui_hulu", 3);
    addItem("seed_jinsui_yumi", 3);
  }
  upsertWorldChange({
    key: CHAPTER_4_DROUGHT_FLAG,
    title: "凡仙镇枯井见底",
    detail: "主街井绳拖出空响，洞天灵泉被接成救命水线。田垄还能缓，镇上的人缓不得。",
    rewardHint: "应急订单 · 供水压力 · 二十四枢前置",
    visualType: "drought_cracked_well",
  });
  triggerChapter4DroughtFeedback(eventName);
  queueDialogueGroup("dialogue_main_0401_drought_start");
  playCue("成就解锁");
  addLog("第四章开启", `${eventName}：九曜大旱压到凡仙镇，${droughtReliefOrder() ? orderTitle(droughtReliefOrder()) : "应急救援订单"}已刷新，洞天灵泉先封出 5 份${itemName(CHAPTER_4_DROUGHT_RELIEF_ITEM_ID)}，清水葫芦和金穗玉米种子已上架救援。`);
  updateMissions();
  scanConfiguredEvents("chapter4:drought_start");
  return true;
}

function finishChapter4DroughtRelief(order, rewardTexts = []) {
  const firstRelief = !chapter4DroughtReliefDelivered();
  state.completed.add(CHAPTER_4_DROUGHT_RELIEF_DONE_FLAG);
  state.completed.add(`${CHAPTER_4_DROUGHT_ORDER_ID}_delivered`);
  if (firstRelief) {
    addNpcFavor("npc_xubo", 10, "大旱救援水囊");
    addNpcFavor("npc_qinghe", 8, "分水救镇");
    addNpcFavor("npc_lu_sanxiao", 6, "肯先救人");
  }
  upsertWorldChange({
    key: "drought_relief_water_shed",
    title: "枯井边立起水棚",
    detail: "第一批清水葫芦、止血散和耐存粗粮被封成救援水囊，井边从哭喊变成排队，凡仙镇终于多了一口喘息。",
    rewardHint: `${itemName(CHAPTER_4_DROUGHT_RELIEF_ITEM_ID)} ${Math.min(chapter4ReliefSupplyCount(), 10)}/10`,
    visualType: "drought_relief_shed",
  });
  triggerChapter4DroughtFeedback(order ? `${orderTitle(order)}送达` : "第一批救援水囊送达");
  checkQuestRewards();
  scanConfiguredEvents("chapter4:drought_relief");
  addLog("大旱救援", `第一批救援水囊送到镇上，${questTitle(data.quests.find((quest) => quest.quest_id === CHAPTER_4_DROUGHT_QUEST_ID) || { quest_id: CHAPTER_4_DROUGHT_QUEST_ID })}可以结算。${rewardTexts.length ? ` 额外获得：${rewardTexts.join("、")}。` : ""}`);
}

function startChapter4LuTruth(eventName = "陆三笑揭秘") {
  const plan = questRuntime()?.configuredEventChapter4LuTruthActionPlan({
    event_id: "event_main_0402",
    trigger_type: "on_trade_complete",
    trigger_param: CHAPTER_4_DROUGHT_ORDER_ID,
    execute_group: "exec_start_quest_main_0402",
  });
  if (plan?.applies) {
    applyConfiguredEventActionPlan(plan, { eventName });
    return true;
  }
  const firstStart = !state.completed.has("chapter4_lu_truth_started") && !state.completed.has(`quest_unlock_${CHAPTER_4_LU_TRUTH_QUEST_ID}`);
  state.completed.add("chapter4_lu_truth_started");
  state.completed.add(`quest_unlock_${CHAPTER_4_LU_TRUTH_QUEST_ID}`);
  if (firstStart) {
    addNpcFavor("npc_lu_sanxiao", 10, "二十四枢真相");
    state.fame += 4;
  }
  upsertWorldChange({
    key: "chapter4_twenty_four_pivots_revealed",
    title: "残碑显出二十四枢",
    detail: "陆三笑收起笑意，把守时一脉的后半句话交给你：节气大阵不是藏宝图，是责任书。",
    rewardHint: "二十四枢主线 · 终阵口诀",
    visualType: "solar_array_stela",
  });
  queueDialogueGroup("dialogue_main_0402_lu_truth");
  playCue("成就解锁");
  const granted = syncChapter4SpiritCores();
  addLog("第四章推进", `${eventName}：陆三笑在守阵残碑前说明二十四枢，终章重建大阵的真正目标浮出水面。${granted.length ? ` ${granted.map((source) => source.label).join("、")}归位。` : ""}`);
  updateMissions();
  if (chapter4FinalNestReady()) unlockFinalNest(localize("event_name_main_0404", "最终巢穴开启"));
  scanConfiguredEvents("chapter4:lu_truth");
  return true;
}

function chapter4SpiritCoreSources() {
  return [
    {
      flag: "core_mine",
      ready: state.dungeonClears.has("area_mine_qingyun") || state.defeatedBosses.has("boss_liejia_muwei") || state.completed.has("dungeon"),
      label: "青云矿洞枢石",
      detail: "第一枚来自裂甲木卫守住的旧矿脉。",
    },
    {
      flag: "core_herb",
      ready: state.dungeonClears.has(HERB_VALLEY_AREA_ID) || state.defeatedBosses.has(BAIZHI_BOSS_ID) || baizhiChapterFinished(),
      label: "雾隐药谷枢石",
      detail: "第二枚随百草母露一起从药脉里认回。",
    },
    {
      flag: "core_fire",
      ready: state.dungeonClears.has(FIRE_RUIN_AREA_ID) || state.defeatedBosses.has(FIRE_RUIN_BOSS_ID) || hasItem(FIRE_CORE_ITEM_ID, 1),
      label: "炽砂火位枢石",
      detail: "第三枚压在赤魇蝎后身后的火土残阵里。",
    },
    {
      flag: "core_relief",
      ready: chapter4DroughtReliefDelivered() || hasItem(CHAPTER_4_DROUGHT_RELIEF_ITEM_ID, 10),
      label: "凡仙水线枢石",
      detail: "第四枚不是战利品，是镇民接过救援水囊后重新托住的水线。",
    },
  ];
}

function chapter4SpiritCoreProgress() {
  const sources = chapter4SpiritCoreSources();
  const ready = sources.filter((source) => source.ready);
  return {
    sources,
    ready,
    count: Math.min(4, Math.max(ready.length, Number(state.inventory[CHAPTER_4_SPIRIT_CORE_ITEM_ID] || 0), Number(state.harvestCounts[`collect_${CHAPTER_4_SPIRIT_CORE_ITEM_ID}`] || 0))),
    missing: sources.filter((source) => !source.ready),
  };
}

function syncChapter4SpiritCores() {
  if (!state.completed.has("chapter4_lu_truth_started")) return [];
  const granted = [];
  for (const source of chapter4SpiritCoreSources()) {
    const flag = `chapter4_${source.flag}_granted`;
    if (!source.ready || state.completed.has(flag)) continue;
    addItem(CHAPTER_4_SPIRIT_CORE_ITEM_ID, 1);
    state.completed.add(flag);
    granted.push(source);
  }
  if (granted.length > 0) {
    const progress = chapter4SpiritCoreProgress();
    upsertWorldChange({
      key: "chapter4_spirit_cores_gathered",
      title: "四象枢石归位",
      detail: `${granted.map((source) => source.label).join("、")}亮起，二十四枢已有 ${progress.count}/4 枚枢石归位。`,
      rewardHint: `${itemName(CHAPTER_4_SPIRIT_CORE_ITEM_ID)} ${progress.count}/4`,
      visualType: "solar_array_stela",
    });
  }
  return granted;
}

function chapter4FinalNestReady() {
  syncChapter4SpiritCores();
  return chapter4SpiritCoreProgress().count >= 4 && hasItem(FIRE_CORE_ITEM_ID, 1);
}

function chapter4ArrayFeedbackSpec(eventName = "二十四枢") {
  const progress = chapter4SpiritCoreProgress();
  const hasFire = hasItem(FIRE_CORE_ITEM_ID, 1);
  const hasDinghai = hasItem(CHAPTER_4_DINGHAI_ITEM_ID, 1);
  const missing = [
    ...progress.missing.map((source) => source.label),
    hasFire ? "" : itemName(FIRE_CORE_ITEM_ID),
    hasDinghai ? "" : itemName(CHAPTER_4_DINGHAI_ITEM_ID),
  ].filter(Boolean);
  return {
    eventId: "event_main_0404",
    questId: CHAPTER_4_LU_TRUTH_QUEST_ID,
    npcId: "npc_lu_sanxiao",
    areaId: CHAPTER_4_FINAL_NEST_AREA_ID,
    title: eventName,
    headline: hasDinghai ? "终巢入口的水线被压住了" : `二十四枢正在认回旧时`,
    detail: hasDinghai
      ? "定海神珠已经压住终巢外翻涌的死水，噬灵螟巢入口现形。下一步是进入终巢，面对噬灵螟母。"
      : `四象枢石 ${progress.count}/4，炽炎火精 ${hasFire ? "已归位" : "未归位"}。${missing.length ? `还差：${missing.join("、")}。` : "青禾正在把最后一线水位引回阵脚。"}`,
    cta: hasDinghai ? `下一步：进入${dungeonName(data.dungeonsById.get(CHAPTER_4_FINAL_NEST_AREA_ID))}。` : "下一步：补齐枢石与火精，等待定海神珠凝成。",
    rewardHint: hasDinghai ? `${itemName(CHAPTER_4_DINGHAI_ITEM_ID)} · 终巢开启` : `${itemName(CHAPTER_4_SPIRIT_CORE_ITEM_ID)} ${progress.count}/4 · ${itemName(FIRE_CORE_ITEM_ID)} ${hasFire ? "1/1" : "0/1"}`,
    createdAt: performance.now(),
  };
}

function unlockFinalNest(eventName = "最终巢穴开启") {
  syncChapter4SpiritCores();
  const finalNestReady = chapter4FinalNestReady();
  const plan = questRuntime()?.configuredEventChapter4FinalNestUnlockActionPlan({
    event_id: "event_main_0404",
    event_name_key: "event_name_main_0404",
    trigger_type: "on_item_collected",
    trigger_param: CHAPTER_4_DINGHAI_ITEM_ID,
    condition_group: "quest_main_0402_active",
    execute_group: "exec_unlock_final_nest",
  }, finalNestReady);
  if (plan?.applies) {
    applyConfiguredEventActionPlan(plan, { eventName });
    return finalNestReady;
  }
  if (!finalNestReady) {
    const feedback = chapter4ArrayFeedbackSpec(eventName);
    state.chapter4DroughtFeedback = feedback;
    addLog("二十四枢未齐", `${feedback.detail} ${feedback.cta}`);
    return false;
  }
  const firstUnlock = !state.completed.has(CHAPTER_4_FINAL_NEST_UNLOCK_FLAG);
  state.completed.add(CHAPTER_4_FINAL_NEST_UNLOCK_FLAG);
  state.completed.add("quest_main_0402_ready");
  state.completed.add("building_unlock_build_solar_array_final");
  state.triggeredEvents.add("event_main_0404");
  if (!hasItem(CHAPTER_4_DINGHAI_ITEM_ID, 1)) addItem(CHAPTER_4_DINGHAI_ITEM_ID, 1);
  if (firstUnlock) {
    addNpcFavor("npc_lu_sanxiao", 10, "二十四枢归位");
    addNpcFavor("npc_qinghe", 10, "定海水线");
    state.fame += 8;
  }
  upsertWorldChange({
    key: CHAPTER_4_FINAL_NEST_UNLOCK_FLAG,
    dungeonId: CHAPTER_4_FINAL_NEST_AREA_ID,
    title: "噬灵螟巢现形",
    detail: "四枚灵脉枢石与炽炎火精齐鸣，青禾引水压住死潮，定海神珠从阵脚升起，终巢入口终于露出。",
    rewardHint: `${itemName(CHAPTER_4_DINGHAI_ITEM_ID)} · ${dungeonName(data.dungeonsById.get(CHAPTER_4_FINAL_NEST_AREA_ID))}`,
    visualType: "final_nest_gate",
  });
  state.chapter4DroughtFeedback = chapter4ArrayFeedbackSpec(eventName);
  queueDialogueGroup("dialogue_final_array");
  playCue("成就解锁");
  addLog("终巢开启", `${eventName}：${itemName(CHAPTER_4_DINGHAI_ITEM_ID)}入手，${dungeonName(data.dungeonsById.get(CHAPTER_4_FINAL_NEST_AREA_ID))}已经可以进入。`);
  checkQuestRewards();
  scanConfiguredEvents("chapter4:final_nest_unlock");
  return true;
}

