function baizhiShihuSeedUnlocked() {
  return state.completed.has("baizhi_order_visit") || state.claimedQuestRewards.has(BAIZHI_QUEST_ID);
}

function baizhiShihuProgress() {
  return {
    plantedCount: state.plots.filter((plot) => plot.cropId === BAIZHI_CROP_ID).length,
    harvestCount: Math.max(Number(state.harvestCounts[BAIZHI_CROP_ID] || 0), Number(state.inventory[BAIZHI_CROP_ID] || 0)),
    qualityCount: Number(state.inventory[BAIZHI_QUALITY_ITEM_ID] || 0),
    favorLevel: favorLevel(state.npcFavor.npc_baizhi || 0),
  };
}

function baizhiQuestRewardPreview() {
  const quest = data.quests.find((entry) => entry.quest_id === BAIZHI_QUEST_ID);
  if (!quest?.complete_reward_group) return "高级药园配方";
  return rewardPoolEntries(quest.complete_reward_group)
    .filter((entry) => conditionMet(entry.condition_group || "always_true"))
    .slice(0, 2)
    .map((entry) => applyRewardEntryPreview(entry))
    .join("、") || "高级药园配方";
}

function baizhiQuestGuidanceSpec(selectedSeedId = state.selectedSeedId) {
  if (!baizhiQuestGuidanceActive()) return null;
  const progress = baizhiShihuProgress();
  const rewardPreview = baizhiQuestRewardPreview();
  const recipePreview = `${localize("recipe_name_zhixue_san", "止血散")} / ${localize("recipe_name_shihu_huiyuan_san", "石斛回元散")}`;
  const seedSelected = selectedSeedId === BAIZHI_SEED_ID;
  const selectedSeedName = itemName(selectedSeedId);

  if (progress.harvestCount < 5) {
    if (progress.plantedCount <= 0) {
      return {
        mission: "下一步：先去补 3 包铁皮石斛种子，再在普通灵田播第一批。",
        restock: seedSelected
          ? `白芷之求：医馆要的就是铁皮石斛 · 先备 3 包 · 后续可做 ${recipePreview}`
          : `白芷要的不是 ${selectedSeedName}，而是铁皮石斛 · 先切回石斛再补 3 包`,
        plot: seedSelected
          ? "白芷之求：先把第一批石斛下地，目标收够 5 株，再追求良品以上。"
          : "白芷要的就是铁皮石斛。先在种子栏切回石斛，再播到这块灵田里。",
        progress: `当前 收获 ${progress.harvestCount}/5 · 良品 ${progress.qualityCount}/5 · 奖励 ${rewardPreview}`,
      };
    }
    return {
      mission: "下一步：继续补水入夜，先收够 5 株铁皮石斛。",
      restock: `白芷之求：基础石斛还没收齐 · 缺种就再备 3 包 · 后续可做 ${recipePreview}`,
      plot: "白芷之求：这批石斛已经下地，继续补水入夜，把 5 株基础量先收齐。",
      progress: `当前 收获 ${progress.harvestCount}/5 · 良品 ${progress.qualityCount}/5 · 奖励 ${rewardPreview}`,
    };
  }
  if (progress.favorLevel < 2) {
    return {
      mission: "下一步：去医馆见白芷，把这批石斛送去试药，把好感推进到 2 级。",
      restock: `基础石斛已备齐 · 可以继续补种冲良品 ${progress.qualityCount}/5 · 奖励 ${rewardPreview}`,
      plot: seedSelected
        ? "白芷之求：基础数量已够，接下来去医馆交谈，或者继续补种冲良品。"
        : "白芷已经在等这批石斛了。先去医馆谈谈，回来再补种也不迟。",
      progress: `当前 收获 ${progress.harvestCount}/5 · 好感 ${progress.favorLevel}/2 · 良品 ${progress.qualityCount}/5`,
    };
  }
  if (progress.qualityCount < 5) {
    return {
      mission: "下一步：继续培育良品以上铁皮石斛 5 株，准备完成医馆委托。",
      restock: `白芷之求：现在追良品石斛 ${progress.qualityCount}/5 · 缺种就再备 3 包 · 奖励 ${rewardPreview}`,
      plot: seedSelected
        ? "白芷之求：基础量已够，继续养这批石斛，目标良品以上 5 株。"
        : "基础石斛已经够了，现在要追良品以上。切回石斛继续种，会更稳。",
      progress: `当前 良品 ${progress.qualityCount}/5 · 基础石斛 ${progress.harvestCount}/5 · 奖励 ${rewardPreview}`,
    };
  }
  return {
    mission: "下一步：条件已经齐了，回医馆把委托收尾。",
    restock: `白芷之求：交付条件已齐，回医馆即可领取 ${rewardPreview}`,
    plot: "白芷之求：条件齐了。这块田可以继续补种，也可以先回医馆交委托。",
    progress: `当前 收获 ${progress.harvestCount}/5 · 良品 ${progress.qualityCount}/5 · 好感 ${progress.favorLevel}/2`,
  };
}

function shouldAutoFocusBaizhiSeed(selectedSeedId = state.selectedSeedId) {
  if (!baizhiQuestGuidanceActive()) return false;
  const progress = baizhiShihuProgress();
  if (progress.plantedCount > 0 || progress.harvestCount > 0 || progress.qualityCount > 0) return false;
  return [BAIZHI_SEED_ID, "seed_lingqi_bailuobo", "seed_qingya_baicai", ""].includes(selectedSeedId || "");
}

function maybeFocusBaizhiQuestSeed(crops = availableSeedCrops()) {
  if (!shouldAutoFocusBaizhiSeed()) return false;
  if (!crops.some((crop) => crop.seed_item_id === BAIZHI_SEED_ID)) return false;
  state.selectedSeedId = BAIZHI_SEED_ID;
  return true;
}

function baizhiQuestPlantFeedbackSpec(plot, crop) {
  const guidance = baizhiQuestGuidanceSpec(crop?.seed_item_id);
  return {
    questId: BAIZHI_QUEST_ID,
    plotX: Number(plot?.x || 0) + 1,
    plotY: Number(plot?.y || 0) + 1,
    title: "白芷之求",
    headline: "第一批铁皮石斛已经下地",
    detail: guidance?.plot || "白芷要的那批石斛，已经下地了。",
    cta: guidance?.progress || `继续补水入夜，先收够 5 株 ${itemName(BAIZHI_CROP_ID)}。`,
    rewardPreview: baizhiQuestRewardPreview(),
    createdAt: performance.now(),
  };
}

function triggerBaizhiQuestPlantFeedback(plot, crop) {
  const feedback = baizhiQuestPlantFeedbackSpec(plot, crop);
  state.baizhiQuestPlantFeedback = feedback;
  return feedback;
}

function baizhiQuestStageFeedbackSpec(phase = "harvest_ready") {
  const progress = baizhiShihuProgress();
  const rewardPreview = baizhiQuestRewardPreview();
  const map = {
    harvest_ready: {
      title: "白芷之求",
      headline: "药材基础量已经备齐",
      detail: "第一批铁皮石斛已经攒够，接下来该去医馆把试药的要求说清。",
      cta: `下一步：把白芷好感推进到 Lv.2。当前 ${progress.harvestCount}/5 株 · 奖励 ${rewardPreview}`,
    },
    favor_ready: {
      title: "医馆后室",
      headline: "白芷把要求说重了",
      detail: "她不缺一批能交差的药材，她缺的是能稳稳救人的净石斛。",
      cta: `下一步：继续追良品石斛。当前 好感 Lv.${progress.favorLevel}/2 · 良品 ${progress.qualityCount}/5`,
    },
    quality_ready: {
      title: "白芷之求",
      headline: "良品石斛已经凑齐",
      detail: "这批石斛的净度和灵性都够了，医馆与药谷的后续线索已经能接上。",
      cta: `下一步：回医馆收尾委托。当前 收获 ${progress.harvestCount}/5 · 良品 ${progress.qualityCount}/5`,
    },
  };
  return {
    phase,
    questId: BAIZHI_QUEST_ID,
    rewardPreview,
    createdAt: performance.now(),
    ...(map[phase] || map.harvest_ready),
  };
}

function triggerBaizhiQuestStageFeedback(phase = "harvest_ready") {
  const feedback = baizhiQuestStageFeedbackSpec(phase);
  state.baizhiQuestStageFeedback = feedback;
  return feedback;
}

function storyVisitFeedbackSpec(orderFeedback, questId = BAIZHI_QUEST_ID) {
  const quest = data.quests.find((entry) => entry.quest_id === questId) || {
    quest_id: questId,
    quest_name_key: "quest_name_main_0202",
    complete_reward_group: "pool_reward_main_0202",
  };
  const rewardPreview = rewardPoolEntries(quest.complete_reward_group)
    .filter((entry) => conditionMet(entry.condition_group || "always_true"))
    .slice(0, 2)
    .map((entry) => applyRewardEntryPreview(entry))
    .join("、") || "高级药园配方";
  return {
    eventId: "baizhi_order_visit",
    source: "first_order_delivery",
    npcId: "npc_baizhi",
    npcLabel: npcName("npc_baizhi"),
    title: "白芷来访",
    headline: "白芷顺着这波口碑找到了旧铺",
    detail: "她想请你稳定种一批铁皮石斛，不是为了卖，是为了救人。",
    bubble: "石斛之求",
    clue: "稳净石斛委托",
    questId,
    questLabel: questTitle(quest),
    areaText: areaName("area_clinic"),
    rewardPreview,
    orderTitle: orderFeedback?.title || "",
    cta: "等手头这波货忙完，去医馆听她把委托说完。",
    dialogueGroupId: "dialogue_baizhi_order_visit",
    createdAt: performance.now(),
    day: state.day,
    dialogueQueued: false,
    dialogueTimerScheduled: false,
    dialogueShown: false,
  };
}

function queueStoryVisitDialogue(feedback = state.storyVisitFeedback) {
  if (!feedback || feedback.dialogueQueued) return false;
  feedback.dialogueQueued = true;
  queueDialogueGroup(feedback.dialogueGroupId);
  return true;
}

function scheduleStoryVisitDialogue(delayMs = 1800, eventId = state.storyVisitFeedback?.eventId) {
  const feedback = state.storyVisitFeedback;
  if (!feedback || feedback.dialogueTimerScheduled) return false;
  feedback.dialogueTimerScheduled = true;
  setTimeout(() => {
    const latest = state.storyVisitFeedback;
    if (!latest || latest.eventId !== eventId || latest.dialogueQueued) return;
    queueStoryVisitDialogue(latest);
    render();
  }, delayMs);
  return true;
}

function triggerStoryVisitFeedback(orderFeedback) {
  if (!orderFeedback?.firstOrder || state.completed.has("baizhi_order_visit")) return null;
  const feedback = storyVisitFeedbackSpec(orderFeedback);
  state.storyVisitFeedback = feedback;
  complete("baizhi_order_visit");
  if (availableSeedCrops().some((crop) => crop.seed_item_id === BAIZHI_SEED_ID)) state.selectedSeedId = BAIZHI_SEED_ID;
  scheduleStoryVisitDialogue();
  addLog(feedback.title, `${feedback.detail} ${feedback.cta}`);
  return feedback;
}

function demoBuildCost(building) {
  const demoCosts = {
    build_storage_001: { gold: 60, wood: 0, stone: 0, metal: 0 },
    build_mill_001: { gold: 90, wood: 0, stone: 0, metal: 0 },
    build_lingjing_001: { gold: 120, wood: 0, stone: 0, metal: 0 },
    build_fishpond_lv1: { gold: 130, wood: 0, stone: 0, metal: 0 },
    build_solar_array_final: { gold: 1200, wood: 0, stone: 0, metal: 0, specialItem: CHAPTER_4_DINGHAI_ITEM_ID, specialCount: 1 },
  };
  return demoCosts[building.building_id] || {
    gold: Number(building.cost_gold || 0),
    wood: Number(building.cost_wood || 0),
    stone: Number(building.cost_stone || 0),
    metal: Number(building.cost_metal || 0),
    specialItem: building.cost_special_item,
    specialCount: Number(building.cost_special_count || 0),
  };
}

function buildingVisible(building) {
  if (!building) return false;
  if (building.building_id === "build_house_start") return false;
  if (state.builtBuildings.has(building.building_id)) return true;
  if (state.completed.has(`building_unlock_${building.building_id}`)) return true;
  if (building.unlock_type === "default" && String(building.function_tags || "").includes("machine")) return true;
  if (["build_storage_001", "build_mill_001", "build_lingjing_001", "build_furnace_001", "build_broken_bridge_repair"].includes(building.building_id)) return true;
  if (building.unlock_type === "chapter") {
    const chapter = Number(building.unlock_param || 1);
    if (chapter <= 2) return state.completed.has("shop") || state.missionDone.size >= 2 || baizhiQuestGuidanceActive() || baizhiChapterFinished();
    if (chapter <= 3) return chapter3TradeStarted() || spiritManorBuilt() || state.missionDone.size >= 5;
    if (chapter <= 4) return fireRuinUnlocked() || state.defeatedBosses.has("boss_chiyan_xiehou") || state.missionDone.size >= 7;
    return state.missionDone.size >= chapter;
  }
  if (building.unlock_type === "completed") return state.completed.has(building.unlock_param);
  if (building.unlock_type === "quest") {
    return state.activeSideQuests.has(building.unlock_param)
      || state.missionDone.has(building.unlock_param)
      || state.completed.has(building.unlock_param);
  }
  return false;
}

function buildableBuildings() {
  return data.buildings.filter(buildingVisible);
}

function canBuild(building) {
  const cost = demoBuildCost(building);
  if (state.builtBuildings.has(building.building_id)) return false;
  if (state.gold < (cost.gold || 0)) return false;
  if ((cost.wood || 0) > 0 && !hasItem("item_wood_basic", cost.wood)) return false;
  if ((cost.stone || 0) > 0 && !hasItem("item_stone_basic", cost.stone)) return false;
  if ((cost.metal || 0) > 0 && !hasItem("item_metal_xuantie", cost.metal) && !hasItem("item_ore_iron", cost.metal) && !hasItem("item_ore_iron_raw", cost.metal)) return false;
  if (cost.specialItem && cost.specialCount > 0 && !hasItem(cost.specialItem, cost.specialCount)) return false;
  return true;
}

function costText(building) {
  const cost = demoBuildCost(building);
  const parts = [`灵石 ${cost.gold || 0}`];
  if (cost.wood) parts.push(`木材 ${state.inventory.item_wood_basic || 0}/${cost.wood}`);
  if (cost.stone) parts.push(`石材 ${state.inventory.item_stone_basic || 0}/${cost.stone}`);
  if (cost.metal) parts.push(`${building.building_id === SPIRIT_MANOR_BUILDING_ID ? itemName("item_metal_xuantie") : "金属"} ${state.inventory.item_metal_xuantie || state.inventory.item_ore_iron || state.inventory.item_ore_iron_raw || 0}/${cost.metal}`);
  if (cost.specialItem && cost.specialCount) parts.push(`${itemName(cost.specialItem)} ${state.inventory[cost.specialItem] || 0}/${cost.specialCount}`);
  return parts.join(" · ");
}

function buildingCostRows(building) {
  if (!building) return [];
  const cost = demoBuildCost(building);
  const metalOwned = Number(state.inventory.item_metal_xuantie || 0)
    + Number(state.inventory.item_ore_iron || 0)
    + Number(state.inventory.item_ore_iron_raw || 0);
  return [
    {
      key: "gold",
      label: "灵石",
      owned: Number(state.gold || 0),
      need: Number(cost.gold || 0),
      detail: "旧铺、订单和日结会把灵石滚回来。",
      focusTitle: "洞天建设：经营筹资",
    },
    {
      key: "wood",
      label: "木材",
      owned: Number(state.inventory.item_wood_basic || 0),
      need: Number(cost.wood || 0),
      detail: "清荒、主线奖励和日常补料最稳。",
      focusTitle: "洞天建设：清荒补料",
    },
    {
      key: "stone",
      label: "石材",
      owned: Number(state.inventory.item_stone_basic || 0),
      need: Number(cost.stone || 0),
      detail: "清荒、后山碎石点和日常补给会慢慢补齐。",
      focusTitle: "洞天建设：清荒补料",
    },
    {
      key: "metal",
      label: building.building_id === SPIRIT_MANOR_BUILDING_ID ? itemName("item_metal_xuantie") : "金属",
      owned: metalOwned,
      need: Number(cost.metal || 0),
      detail: "矿洞、秘境和远路会把矿材送回来。",
      focusTitle: "洞天建设：矿材来源",
    },
    {
      key: "special",
      label: cost.specialItem ? itemName(cost.specialItem) : "",
      owned: cost.specialItem ? Number(state.inventory[cost.specialItem] || 0) : 0,
      need: Number(cost.specialCount || 0),
      detail: building.building_id === SPIRIT_MANOR_BUILDING_ID
        ? "阿檀的蓝图会把百怪大院的特殊材料线接出来。"
        : building.building_id === CHAPTER_4_FINAL_ARRAY_BUILDING_ID
          ? "终章协力、阵材和阵心钥物会一起汇到节气阵。"
          : "这项特殊材料通常跟主线、支线或系统入口绑定。",
      focusTitle: building.building_id === SPIRIT_MANOR_BUILDING_ID
        ? "洞天建设：百怪大院材料线"
        : building.building_id === CHAPTER_4_FINAL_ARRAY_BUILDING_ID
          ? "洞天建设：终阵材料线"
          : "洞天建设：特殊材料线",
    },
  ]
    .filter((row) => row.need > 0)
    .map((row) => ({
      ...row,
      missing: Math.max(0, Number(row.need || 0) - Number(row.owned || 0)),
      ready: Number(row.owned || 0) >= Number(row.need || 0),
    }));
}

function buildingCostStatusSpec(building) {
  const rows = buildingCostRows(building);
  const built = Boolean(building && state.builtBuildings.has(building.building_id));
  const blockedRows = rows.filter((row) => !row.ready);
  const ready = !built && blockedRows.length === 0;
  return {
    rows,
    built,
    ready,
    done: rows.filter((row) => row.ready).length,
    total: rows.length,
    blockedRows,
    missingText: blockedRows.map((row) => `${row.label}差 ${row.missing}`).join("、"),
    summary: rows.map((row) => `${row.label} ${Math.min(row.owned, row.need)}/${row.need}`).join(" · "),
    stateClass: built ? "built" : ready ? "ready" : "locked",
  };
}

function buildingRoleText(building) {
  if (!building) return "把洞天功能位接得更顺，让资源不只停在材料表上。";
  const machine = data.machinesByBuilding.get(building.building_id);
  if (building.building_id === "build_broken_bridge_repair") return "把后山矿路、新水田和第二只精怪线一起接上。";
  if (building.building_id === "build_fishpond_lv1") return "把灵池、水位、夜间照料和月莲生活线接起来。";
  if (building.building_id === SPIRIT_MANOR_BUILDING_ID) return "把宿舍、岗位牌和情绪看板接成第三章自动化核心。";
  if (building.building_id === CHAPTER_4_FINAL_ARRAY_BUILDING_ID) return "把终章支援、万年蟠桃和年后目标压进同一座节气阵。";
  if (machine) return `解锁 ${machineName(machine)}，让工坊把原料抬成更值钱的货。`;
  if (building.category === "farm") return "扩地、修渠或补生产设施，让田里和后山一起提速。";
  if (building.category === "spirit") return "让精怪岗位、羁绊和自动化更稳定。";
  return "补齐洞天功能位，把种田、工坊、旧铺和主线推进接得更顺。";
}

function buildingProgressText(building, status = buildingCostStatusSpec(building)) {
  if (!building) return "";
  if (status.built) return "已建成，作用已经接入洞天日常。";
  if (status.total === 0) return "当前不需要额外材料。";
  if (status.ready) return `材料 ${status.done}/${status.total} 项齐备，可立即动工。`;
  return `材料 ${status.done}/${status.total} 项到位，缺口 ${status.missingText || "待补齐"}。`;
}

function buildingNextStepText(building, status = buildingCostStatusSpec(building)) {
  if (!building) return "先回到建设面板确认这条线。";
  if (status.built) return "先看建设卡和相关系统，确认它已经怎样改变田里、工坊或主线。";
  if (status.ready) {
    if (building.building_id === "build_broken_bridge_repair") return "木石已经齐了，下一步把断桥与第一段灵渠接回去。";
    if (building.building_id === CHAPTER_4_FINAL_ARRAY_BUILDING_ID) return "阵材已经齐备，下一步把终章阵台真正立起来。";
    return "材料已齐，下一步按图施工，把这格功能落进洞天。";
  }
  const blocked = status.blockedRows[0];
  if (!blocked) return "先补齐最缺的一项材料，再回来按图施工。";
  if (blocked.focusTitle === "洞天建设：矿材来源") return "先从矿路和秘境补齐金属，再回来落这座建筑。";
  if (blocked.focusTitle === "洞天建设：清荒补料") return "先清荒补木石，顺手把洞天前期资源线再理一遍。";
  if (blocked.focusTitle === "洞天建设：百怪大院材料线") return "先顺着阿檀和百怪大院蓝图，把特殊材料线补齐。";
  if (blocked.focusTitle === "洞天建设：终阵材料线") return "先把终章协力和阵材线接稳，节气阵就能真正立起来。";
  return "先补齐最缺的一项材料，再回来按图施工。";
}

function buildingActionLabel(building, built = Boolean(building && state.builtBuildings.has(building.building_id)), ready = Boolean(building && canBuild(building))) {
  if (!building) return "看建设卡";
  if (built) return building.building_id === "build_broken_bridge_repair" ? "已修复" : "已建成";
  if (!ready) {
    if (building.building_id === "build_broken_bridge_repair") return "先补料再修渠";
    if (building.building_id === CHAPTER_4_FINAL_ARRAY_BUILDING_ID) return "阵材未齐";
    return "材料未齐";
  }
  if (building.building_id === "build_broken_bridge_repair") return "修复灵渠";
  if (building.building_id === SPIRIT_MANOR_BUILDING_ID) return "按蓝图建造";
  if (building.building_id === CHAPTER_4_FINAL_ARRAY_BUILDING_ID) return "搭起终阵";
  return "现在建造";
}

function buildingUiSpec(building) {
  if (!building) return null;
  const status = buildingCostStatusSpec(building);
  const machine = data.machinesByBuilding.get(building.building_id);
  return {
    buildingId: building.building_id,
    title: buildingName(building),
    subtitle: `${building.category} · ${building.function_tags || "基础功能"}${machine ? ` · 解锁 ${machineName(machine)}` : ""}`,
    built: status.built,
    ready: status.ready,
    stateClass: status.stateClass,
    roleText: buildingRoleText(building),
    progressText: buildingProgressText(building, status),
    nextStepText: buildingNextStepText(building, status),
    actionLabel: buildingActionLabel(building, status.built, status.ready),
    costRows: status.rows,
    costStatus: status,
    safety: "不会自动建造、修渠、扣材料或推进时间。",
  };
}

function canalRepairPrepSpec() {
  const building = data.buildingsById.get("build_broken_bridge_repair");
  if (!building) return null;
  const ui = buildingUiSpec(building);
  return {
    ...ui,
    title: "灵渠修复预备账",
    headline: ui.built
      ? "第一段水脉已经复流，新水田和后山矿路都打开了"
      : ui.ready
        ? "木石已经齐备，下一步就能把断桥与灵渠接回去"
        : "先把木石补齐，再把后山矿路、水田和精怪线一起点亮",
    safety: "只定位修复入口、建设卡或补料来源，不会自动修渠、不会自动扣材料或推进时间。",
  };
}

function focusBuildStructure(buildingId = "") {
  const building = data.buildingsById.get(buildingId) || null;
  if (!building) return addLog("洞天建设", "这张建设卡暂时没有找到。");
  const ui = buildingUiSpec(building);
  queueStoryCompassFocusTarget({
    selector: `[data-build-id="${selectorDataValue(buildingId)}"]`,
    fallbackSelector: "#buildPanel",
    label: `洞天建设：${ui.title}`,
    log: `${ui.title} 已在建设面板高亮。${ui.roleText} 当前 ${ui.progressText} 下一步：${ui.nextStepText} ${ui.safety}`,
    panelGroup: "systems",
    missingTitle: `洞天建设：${ui.title}`,
    missingLog: `建设面板暂时没有找到 ${ui.title}。${ui.safety}`,
  });
  return true;
}

function focusBuildCostSource(sourceKey = "gold", buildingId = "") {
  const building = data.buildingsById.get(buildingId) || null;
  if (!building) return addLog("洞天建设", "这条补料来源暂时没有找到对应建筑。");
  const ui = buildingUiSpec(building);
  const row = ui.costRows.find((entry) => entry.key === sourceKey) || ui.costRows[0];
  if (!row) return focusBuildStructure(buildingId);
  const safety = "不会自动建造、修渠、扣材料或推进时间。";
  const missingText = row.missing > 0 ? `还差 ${row.missing}。` : "当前这项已经齐备。";
  let selector = "#shopReport";
  let fallbackSelector = "#buildPanel";
  let panelGroup = "core";
  let label = row.focusTitle || `洞天建设：${row.label}`;
  let log = `${ui.title} 的 ${row.label}来源已定位。${missingText}${row.detail}${safety}`;
  if (label === "洞天建设：矿材来源") {
    selector = "#dungeonPanel";
    panelGroup = "systems";
    log = `${ui.title} 的矿材来源已定位。${missingText}矿洞、秘境和远路会把金属慢慢送回来。${safety}`;
  } else if (label === "洞天建设：清荒补料") {
    selector = "#selectedPlotCard";
    log = `${ui.title} 的清荒补料入口已定位。${missingText}朽木和碎石主要从清荒、前期奖励和零碎补料里攒出来。${safety}`;
  } else if (label === "洞天建设：百怪大院材料线") {
    selector = "#relationshipPanel";
    fallbackSelector = "#goalBookPanel";
    panelGroup = "story";
    log = `${ui.title} 的百怪大院材料线已定位。${missingText}先看阿檀、蓝图和中期精怪管理线，再回来落院。${safety}`;
  } else if (label === "洞天建设：终阵材料线") {
    selector = "#finalSupportPanel";
    panelGroup = "systems";
    log = `${ui.title} 的终阵材料线已定位。${missingText}先把终章协力、阵材和阵心钥物接稳，再回来搭阵。${safety}`;
  }
  queueStoryCompassFocusTarget({
    selector,
    fallbackSelector,
    label,
    log,
    panelGroup,
    missingTitle: label,
    missingLog: `${label} 对应入口暂时没有找到。${safety}`,
  });
  return true;
}

function spendBuildCost(building) {
  const cost = demoBuildCost(building);
  state.gold -= cost.gold || 0;
  if (cost.wood) addItem("item_wood_basic", -cost.wood);
  if (cost.stone) addItem("item_stone_basic", -cost.stone);
  if (cost.metal) {
    const metalId = hasItem("item_metal_xuantie", cost.metal) ? "item_metal_xuantie" : hasItem("item_ore_iron", cost.metal) ? "item_ore_iron" : "item_ore_iron_raw";
    addItem(metalId, -cost.metal);
  }
  if (cost.specialItem && cost.specialCount) addItem(cost.specialItem, -cost.specialCount);
}

function pondCatchReady() {
  const pondState = syncPondState();
  return state.builtBuildings.has("build_fishpond_lv1") && Number(pondState.lastCatchDay || 0) !== state.day;
}

function pondCropAutoWaterActive() {
  if (!state.builtBuildings.has("build_fishpond_lv1")) return false;
  if (!pondWaterControlUnlocked()) return false;
  return pondWaterLevelSpec(syncPondState().waterLevel).autoWater;
}

function recordPondCatch(count) {
  const pondState = syncPondState();
  const firstCatch = !pondState.firstCatchDone;
  const entry = {
    day: state.day,
    itemId: "item_fish_spiritling",
    itemName: itemName("item_fish_spiritling"),
    count,
    firstCatch,
    usedNet: hasItem("item_tool_fishing_net", 1),
  };
  pondState.unlocked = true;
  if (!pondState.builtDay) pondState.builtDay = state.day;
  pondState.firstCatchDone = true;
  pondState.lastCatchDay = state.day;
  pondState.lastCatch = { ...entry };
  pondState.history.unshift(entry);
  pondState.history = pondState.history.slice(0, 8);
  return entry;
}

function tryPondCatch() {
  if (!state.builtBuildings.has("build_fishpond_lv1")) return addLog("灵池未成", "先把灵池浅塘修起来，池水才能慢慢把鱼认回来。");
  if (!pondCatchReady()) return addLog("池水已静", "今天已经试过一网了，等明天水口再回鱼。");

  const count = (hasItem("item_tool_fishing_net", 1) ? 2 : 1) + pondCatchExtraCount();
  addItem("item_fish_spiritling", count);
  const catchInfo = recordPondCatch(count);
  const firstCatch = catchInfo.firstCatch;
  if (firstCatch) addNpcFavor("npc_qinghe", 1, "认回第一尾灵鱼");
  complete(firstCatch ? "pond_first_catch" : "pond_catch");
  triggerSideQuestPresentationForObjective("collect", "item_fish_spiritling", "after_collect");
  if (firstCatch) checkQuestRewards();
  if (state.completed.has("recipe_recipe_water_crop_intro")) state.selectedRecipeId = "recipe_water_crop_intro";
  if (firstCatch) triggerQinghePondProgressFeedback("catch", { catchInfo, count });
  playCue("浇水");
  addLog(
    "灵池试网",
    firstCatch
      ? `${hasItem("item_tool_fishing_net", 1) ? "引水鱼网轻轻一收" : "你拿竹筛在池口轻轻一试"}，${itemName("item_fish_spiritling")}便顺着活水翻了上来。`
      : `${itemName("item_fish_spiritling")} 又沿着新水口回来了，今日捞起 ${count} 尾。`,
  );
  render();
}

function adjustPondWaterLevel(level) {
  if (!state.builtBuildings.has("build_fishpond_lv1")) return addLog("灵池未成", "先把灵池浅塘修起来，才谈得上看水口。");
  if (!pondWaterControlUnlocked()) return addLog("还不会控水", "先把青禾的池塘线做完，再学着看水位、调水线。");
  const changed = setPondWaterLevel(level, "manual");
  if (!changed) return addLog("水位未变", `灵池现在已经是${pondWaterLevelSpec(level).label}。`);
  render();
}

function buildStructure(buildingId) {
  const building = data.buildingsById.get(buildingId);
  if (!building) return addLog("建筑不存在", "配置表中没有找到该建筑。");
  if (state.builtBuildings.has(buildingId)) return addLog("已经建成", `${buildingName(building)} 已经在洞天里。`);
  if (!canBuild(building)) return addLog("材料不足", `${buildingName(building)} 需要 ${costText(building)}。`);

  spendBuildCost(building);
  state.builtBuildings.add(buildingId);
  const machine = data.machinesByBuilding.get(buildingId);
  recordDailyIntentProgress("build", `建成 ${buildingName(building)}`, {
    title: "洞天建设",
    amount: 4,
    target: buildingId,
    rewardText: machine ? `解锁 ${machineName(machine)}` : "洞天功能推进",
  });
  state.recentlyBuiltStructureId = buildingId;
  state.recentlyBuiltStructureAt = performance.now();
  if (machine) state.unlockedMachines.add(machine.machine_id);
  if (buildingId === "build_lingjing_001") {
    state.plots.forEach((plot, index) => {
      if (index < 6) plot.watered = true;
    });
  }
  if (buildingId === "build_broken_bridge_repair") completeCanalRepairFromBridge("build");
  if (buildingId === "build_fishpond_lv1") {
    syncPondState();
    state.pondState.unlocked = true;
    state.pondState.builtDay = state.day;
    state.pondState.waterLevel = 1;
    addNpcFavor("npc_qinghe", 1, "修起灵池");
    triggerQinghePondProgressFeedback("build", { building });
  }
  if (buildingId === SPIRIT_MANOR_BUILDING_ID) {
    state.completed.add("spirit_manor_constructed");
    triggerSpiritManorFeedback("build", localize("event_name_main_0303", "百怪大院建成"));
  }
  if (buildingId === CHAPTER_4_FINAL_ARRAY_BUILDING_ID) unlockFinalPlanting(localize("event_name_main_0406", "终阵搭建完成"));

  complete(buildingId === "build_mill_001" ? "machine" : "build");
  if (buildingId === "build_fishpond_lv1") triggerSideQuestPresentationForObjective("build", buildingId, "after_build");
  playCue(buildingId === "build_fishpond_lv1" ? "浇水" : "灵渠复流");
  triggerCohabWeeklyEvents("on_build_complete", { buildingId, day: state.day });
  scanConfiguredEvents(`build:${buildingId}`);
  addLog("洞天建设", `${buildingName(building)} 建成。${
    buildingId === "build_fishpond_lv1"
      ? "池底重新吃进了第一口活水，明天就能来试一网。"
      : buildingId === SPIRIT_MANOR_BUILDING_ID
        ? "宿舍、岗位牌与情绪看板已经立起，精怪管理进入第三章。"
      : buildingId === CHAPTER_4_FINAL_ARRAY_BUILDING_ID
        ? `二十四节气大阵亮起，阵心吐出 ${itemName(CHAPTER_4_PANTAO_SEED_ID)}。`
      : machine
        ? `${machineName(machine)} 已接入工坊。`
        : "洞天功能得到扩展。"
  }`);
  render();
}

function workshopMultiplier() {
  let multiplier = 1;
  for (const machineId of state.unlockedMachines) {
    const machine = data.machines.find((entry) => entry.machine_id === machineId);
    multiplier += Number(machine?.speed_base_multiplier || 1) * 0.04;
  }
  if (state.builtBuildings.has("build_lingjing_001")) multiplier += 0.04;
  multiplier += cohabSharedBonusValue("medicine_output");
  multiplier += spiritFinaleEffectSummary().workshopSpeedBonus;
  multiplier += shopSeasonBuffValue("buff_machine_speed_year2");
  const taskLevel = spiritJobTaskEffectLevel("workshop");
  if (taskLevel >= 5) multiplier += 0.12;
  else if (taskLevel >= 3) multiplier += 0.06;
  return multiplier;
}

function availableDungeons() {
  const unlocked = data.dungeons.filter((dungeon, index) =>
    index === 0
    || (dungeon.area_id === HERB_VALLEY_AREA_ID && herbValleyUnlocked())
    || conditionMet(dungeon.unlock_condition_group));
  return unlocked.length > 0 ? unlocked : data.dungeons.slice(0, 1);
}

function currentDungeonConfig() {
  return state.dungeon ? data.dungeonsById.get(state.dungeon.areaId) : null;
}

function activeHiddenRotationForDungeon(dungeon = currentDungeonConfig()) {
  if (!dungeon) return null;
  const rotations = data.hiddenRotationsByArea.get(dungeon.area_id) || [];
  return rotations.find((rotation) =>
    conditionMet(rotation.unlock_condition_group)
    && (!rotation.season_window || rotation.season_window === currentTermId()),
  ) || null;
}

function dungeonRotationLabel(rotation, dungeon = data.dungeonsById.get(rotation?.area_id || "")) {
  if (!rotation) return "";
  const termLabel = localize(data.solarTermsById.get(rotation.season_window)?.term_name_key, rotation.season_window || "轮换");
  const dungeonLabel = dungeon ? dungeonName(dungeon) : "隐藏层";
  return `${termLabel} · ${dungeonLabel} ${rotation.note || rotation.theme_tag || "隐藏轮换"}`;
}

function dungeonRotationEntryEffect(rotation = activeHiddenRotationForDungeon()) {
  if (!rotation) {
    return {
      entryText: "",
      hazardReduce: 0,
      pathBonus: 0,
      bossGuard: 0,
    };
  }
  const map = {
    water_path_open: {
      entryText: "水脉先替你接回一段暗渠，入口会更好走。",
      hazardReduce: 2,
      pathBonus: 4,
      bossGuard: 1,
    },
    thunder_path_open: {
      entryText: "旧雷道的落点被先标出来，误踩的压力会轻不少。",
      hazardReduce: 2,
      pathBonus: 5,
      bossGuard: 2,
    },
    heat_core_active: {
      entryText: "火芯先稳住了遗迹里最躁的一段热浪。",
      hazardReduce: 1,
      pathBonus: 3,
      bossGuard: 4,
    },
    story_gate_open: {
      entryText: "守阵残脉先认出一条可走的影路，深处的压迫会松一截。",
      hazardReduce: 3,
      pathBonus: 6,
      bossGuard: 4,
    },
    ore_bloom_active: {
      entryText: "矿脉生发期开口更明显，顺着矿纹更容易找对落点。",
      hazardReduce: 1,
      pathBonus: 5,
      bossGuard: 2,
    },
  };
  return map[rotation.entry_modifier] || {
    entryText: rotation.note || "隐藏轮换会替你把入口先理顺一部分。",
    hazardReduce: 1,
    pathBonus: 3,
    bossGuard: 1,
  };
}

function rewardPoolAvailableEntries(poolId = "") {
  return rewardPoolEntries(poolId)
    .filter((entry) => !entry.condition_group || conditionGroupStatus(entry.condition_group).pass)
    .sort((a, b) => Number(a.entry_index || 0) - Number(b.entry_index || 0));
}

function rewardPoolPreviewText(poolId = "", limit = 2) {
  return rewardPoolAvailableEntries(poolId)
    .slice(0, limit)
    .map((entry) => applyRewardEntryPreview(entry))
    .join(" / ");
}

function applyDungeonRewardPoolEntry(entry, power = 1) {
  const count = Math.max(1, Math.round(Number(entry.reward_count || 1) * power));
  if (entry.reward_type === "buff" && entry.reward_param === "buff_trade_risk_down_next") {
    state.completed.add("buff_trade_risk_down_next");
    return {
      text: `下次商路风险 -${Math.max(4, count * 4)}%`,
      rewardType: entry.reward_type,
      rewardParam: entry.reward_param,
      rewardCount: count,
      itemId: "",
      count: 0,
    };
  }
  if (entry.reward_type === "bond_exp" && entry.reward_param === "selected_spirits") {
    const targets = state.spirits.slice(0, Math.min(2, state.spirits.length));
    for (const spirit of targets) addBondExp(spirit, count, "秘境残脉见闻");
    return {
      text: `${targets.length > 0 ? `${targets.map((spirit) => spirit.name).join("、")} ` : ""}羁绊 +${count}`,
      rewardType: entry.reward_type,
      rewardParam: entry.reward_param,
      rewardCount: count,
      itemId: "",
      count: 0,
    };
  }
  return {
    text: applyRewardEntry({
      reward_type: entry.reward_type,
      reward_param: entry.reward_param,
      reward_count: count,
    }),
    rewardType: entry.reward_type,
    rewardParam: entry.reward_param,
    rewardCount: count,
    itemId: entry.reward_type === "item" && entry.reward_param !== "item_gold_generic" ? entry.reward_param : "",
    count: entry.reward_type === "item" && entry.reward_param !== "item_gold_generic" ? count : 0,
  };
}

function resolveDungeonRewardPool(poolId = "", power = 1) {
  return rewardPoolAvailableEntries(poolId)
    .slice(0, 2)
    .map((entry) => applyDungeonRewardPoolEntry(entry, power))
    .filter((entry) => entry && entry.text);
}

function dungeonBossId(dungeon = currentDungeonConfig(), run = state.dungeon) {
  return run?.rotationBossId || activeHiddenRotationForDungeon(dungeon)?.boss_override || dungeon?.boss_id || "";
}

function currentDungeonMechanic(dungeon = currentDungeonConfig()) {
  if (!dungeon) return null;
  const termName = state.term;
  return data.dungeonSolarMechanics.find((entry) => entry.solar_term === termName)
    || data.dungeonSolarMechanics.find((entry) => entry.dungeon_id === ({
      mine: "dsm_001",
      herb: "dsm_002",
      ruin: "dsm_004",
      nest: "dsm_008",
    })[dungeon.dungeon_type])
    || data.dungeonSolarMechanics[0];
}

function normalizeDungeonSpiritTag(tag = "") {
  return String(tag || "").replace(/精怪$/, "").replace(/精$/, "").trim();
}

function dungeonSpiritLabel(spirit) {
  const config = spiritConfigFor(spirit);
  return spirit?.name || localize(config?.spirit_name_key, spirit?.id || "随行精怪");
}

