function dungeonSpiritSolutionMatchScore(spirit, profile) {
  if (!spirit || !profile) return 0;
  const config = spiritConfigFor(spirit);
  const lineId = spirit.lineId || config?.spirit_line_id || spiritLine(spirit.id);
  const names = [
    spirit.name,
    localize(config?.spirit_name_key, ""),
    lineId.replace("spirit_line_", ""),
  ].filter(Boolean);
  const matchNames = [profile.key, ...(profile.matchNames || [])].filter(Boolean);
  let score = 0;
  if ((profile.lineIds || []).includes(lineId)) score += 100;
  if (matchNames.some((name) => names.some((label) => label.includes(name)))) score += 70;
  const directScore = score;
  const mainJob = spiritMainJob(spirit);
  if (directScore <= 0 && !profile.jobFallback) return 0;
  if ((profile.matchJobs || []).includes(mainJob)) score += 24;
  for (const job of profile.matchJobs || []) {
    const level = Number(spirit.jobLevels?.[job] || 0);
    if (level > 0) score += 10 + level * 4;
  }
  if (score <= 0) return 0;
  return score + Number(spirit.bondLevel || 1) + Math.round(Number(spirit.stamina || 0) / 25);
}

function dungeonSpiritSolutionRows(mechanic = currentDungeonMechanic()) {
  return splitTags(mechanic?.recommended_spirits || "").map((tag) => {
    const profile = dungeonSpiritSolutionProfile(tag, mechanic);
    const match = state.spirits
      .map((spirit) => ({ spirit, score: dungeonSpiritSolutionMatchScore(spirit, profile) }))
      .filter((entry) => entry.score > 0)
      .sort((a, b) => b.score - a.score)[0]?.spirit || null;
    const impact = dungeonSpiritSolutionImpact(profile, mechanic, Boolean(match));
    return {
      tag,
      key: profile.key,
      ability: profile.ability,
      actionHint: profile.actionHint,
      matched: Boolean(match),
      spiritId: match?.id || "",
      spiritName: match ? dungeonSpiritLabel(match) : "",
      impact: impact.detail,
      shortImpact: impact.short,
      bossImpact: impact.boss,
      missingHint: `推荐 ${tag}；当前未触发 +8 解法。`,
    };
  });
}

function dungeonSpiritSolutionSpec(run = state.dungeon, mechanic = currentDungeonMechanic(), dungeon = currentDungeonConfig()) {
  if (!mechanic) return null;
  const rows = dungeonSpiritSolutionRows(mechanic);
  if (rows.length === 0) return null;
  const matchedRows = rows.filter((row) => row.matched);
  const primary = matchedRows[0] || rows[0];
  const active = matchedRows.length > 0;
  return {
    title: active ? "精怪解法卡" : "精怪解法卡 · 待补位",
    tone: dungeonMechanicTone(mechanic),
    active,
    rows,
    primary,
    solutionCount: matchedRows.length,
    advantage: active ? 8 : 0,
    summary: active
      ? `${primary.spiritName}正在用「${primary.ability}」破解${primary.key}机关。`
      : `推荐携带 ${rows.map((row) => row.tag).join(" / ")}，可把${dungeonName(dungeon)}的机关从硬扛变成解题。`,
    exactImpact: active
      ? primary.impact
      : "当前未触发探索压力 -8；主动顺应节气仍可推进，但容错和反馈会弱一些。",
    nextAction: active
      ? `${primary.actionHint}；继续点“顺应节气”会把这份解法写进本层节奏。`
      : `下一次可优先结缘或带上 ${rows.map((row) => row.tag).join(" / ")}。`,
  };
}

function dungeonSpiritSolutionLogText(spec = dungeonSpiritSolutionSpec(), phase = "explore") {
  if (!spec?.active || !spec.primary) return "";
  const row = spec.primary;
  const impact = phase === "boss" ? row.bossImpact : phase === "attune" ? row.actionHint : row.shortImpact;
  return `${row.spiritName}·${row.ability}：${impact}`;
}

function dungeonSpiritSolutionFeedbackFields(spec = dungeonSpiritSolutionSpec()) {
  if (!spec?.active || !spec.primary) {
    return {
      solutionKey: "",
      solutionAbility: "",
      solutionSpiritName: "",
    };
  }
  return {
    solutionKey: spec.primary.key || "",
    solutionAbility: spec.primary.ability || "",
    solutionSpiritName: spec.primary.spiritName || "",
  };
}

function dungeonSpiritSolutionMarkup(spec = dungeonSpiritSolutionSpec()) {
  if (!spec) return "";
  const rows = spec.rows.map((row) => `
    <div class="dungeon-spirit-solution-row ${row.matched ? "matched" : "missing"}">
      <b>${row.matched ? row.spiritName : row.tag}</b>
      <span>${row.ability}</span>
      <small>${row.matched ? row.shortImpact : row.missingHint}</small>
    </div>
  `).join("");
  return `
    <div class="dungeon-spirit-solution ${spec.active ? "active" : "missing"}" data-tone="${spec.tone}">
      <div class="dungeon-spirit-solution-head">
        <strong>${spec.title}</strong>
        <em>${spec.solutionCount}/${spec.rows.length} 命中</em>
      </div>
      <span class="dungeon-spirit-solution-summary">${spec.summary}</span>
      <small class="dungeon-spirit-solution-impact">${spec.exactImpact}</small>
      <div class="dungeon-spirit-solution-rows">${rows}</div>
      <small>${spec.nextAction}</small>
    </div>
  `;
}

function dungeonMechanicSolutionTriptychSpec(
  run = state.dungeon,
  mechanic = currentDungeonMechanic(),
  dungeon = currentDungeonConfig(),
  solution = dungeonSpiritSolutionSpec(run, mechanic, dungeon),
) {
  if (!mechanic || !dungeon) return null;
  const hud = run && !run.finished ? dungeonMechanicHudSpec(run, mechanic, dungeon) : null;
  const status = run && !run.finished ? dungeonMechanicStatus(run, mechanic, dungeon) : null;
  const activeSolution = solution?.active && solution.primary ? solution.primary : null;
  const recommendedText = splitTags(mechanic.recommended_spirits || "").join(" / ") || "随行精怪";
  const stampSummary = dungeonCompendiumEntrySummary(dungeonCompendiumEntry(dungeon, mechanic));
  const failureSummary = dungeonFailureInsightSummary(dungeonFailureInsight(dungeon, mechanic));
  const cleared = dungeonMechanicCleared(dungeon, mechanic);
  const change = dungeonWorldChangeForMechanic(dungeon, mechanic)
    || (state.dungeonWorldChanges || []).find((entry) => entry.dungeonId === dungeon.area_id)
    || null;
  const tone = dungeonMechanicTone(mechanic);
  const progressText = hud?.progressText || status?.summary || mechanic.field_rule || "节气场规正在改变路线。";
  const solutionBody = activeSolution
    ? `${activeSolution.spiritName}用「${activeSolution.ability}」接入机关。`
    : `推荐携带 ${recommendedText}，否则也能硬解，但容错更低。`;
  const solutionDetail = activeSolution
    ? activeSolution.impact || solution?.exactImpact || activeSolution.shortImpact
    : solution?.exactImpact || "未命中推荐精怪，探索压力不会下降，Boss 前稳场也较弱。";
  const outerChange = change?.title || mechanic.external_change || "洞天或小镇会出现可见变化";
  const rewardText = mechanic.main_reward || "节气材料 / 稀有线索";
  const failureText = mechanic.failure_compensation
    || failureSummary?.detail
    || failureSummary?.body
    || "失败后保留已发现路线、机关线索或节气印记碎片。";
  return {
    active: true,
    tone,
    title: "秘境节气解法三联牌",
    headline: `${mechanic.solar_term || state.term || "节气"} · ${dungeonName(dungeon)}`,
    cleared,
    cards: [
      {
        key: "field_rule",
        label: "场规怎么变",
        title: mechanic.field_rule || "节气改变秘境规则",
        body: progressText,
        detail: mechanic.puzzle_core || "先观察节奏，再决定推进方式。",
        tone: "rule",
      },
      {
        key: "spirit_solution",
        label: "精怪怎么解",
        title: activeSolution ? activeSolution.ability : `推荐 ${recommendedText}`,
        body: solutionBody,
        detail: solutionDetail,
        tone: activeSolution ? "good" : "warn",
      },
      {
        key: "outer_change",
        label: "赢了改哪里",
        title: outerChange,
        body: `奖励焦点：${rewardText}`,
        detail: cleared
          ? `${stampSummary?.title || "节气印记"} 已收录，外部变化已经写进洞天。`
          : `失败补偿：${failureText}`,
        tone: cleared ? "done" : "reward",
      },
    ],
    safety: "只解释秘境读法和定位入口，不会自动进入秘境、顺应节气、探索、挑战 Boss 或消耗资源。",
  };
}

function dungeonMechanicSolutionTriptychMarkup(spec = dungeonMechanicSolutionTriptychSpec()) {
  if (!spec?.active) return "";
  return `
    <div class="dungeon-solution-triptych ${spec.cleared ? "cleared" : ""}" data-tone="${spec.tone}" data-dungeon-board="solution-triptych">
      <div class="dungeon-solution-triptych-head">
        <strong>${spec.title}</strong>
        <em>${spec.headline}</em>
      </div>
      <div class="dungeon-solution-triptych-grid">
        ${spec.cards.map((card) => `
          <div class="dungeon-solution-card ${card.tone}">
            <b>${card.label}</b>
            <span>${card.title}</span>
            <small>${card.body}</small>
            <small>${card.detail}</small>
          </div>
        `).join("")}
      </div>
      <small>${spec.safety}</small>
    </div>
  `;
}

function dungeonFirstMechanicTheaterSpec(run = state.dungeon, mechanic = currentDungeonMechanic(), dungeon = currentDungeonConfig(), hud = dungeonMechanicHudSpec(run, mechanic, dungeon), solution = dungeonSpiritSolutionSpec(run, mechanic, dungeon)) {
  if (!run || run.finished || run.bossReady || !mechanic || !dungeon) return null;
  const progress = Math.max(0, Number(run.progress || 0));
  const firstTimeHere = !state.dungeonClears.has(dungeon.area_id);
  if (!firstTimeHere && progress > 1) return null;
  const tone = dungeonMechanicTone(mechanic);
  const theme = dungeonMechanicTheme(tone);
  const recommended = splitTags(mechanic.recommended_spirits || "").join(" / ") || "随行精怪";
  const activeSolution = solution?.active && solution.primary ? solution.primary : null;
  const failureText = mechanic.failure_compensation || "失败后保留关键见闻，下次更容易读懂机关。";
  const rewardText = mechanic.main_reward || "秘境材料";
  return {
    key: `${run.areaId}:${run.floor}:${progress}:${mechanic.dungeon_id}:first_mechanic_theater`,
    day: state.day,
    dungeonId: dungeon.area_id,
    mechanicId: mechanic.dungeon_id,
    tone,
    theme,
    title: progress <= 0 ? "首次秘境机制小剧场 · 可点" : "节气机关读法 · 可点",
    headline: `${mechanic.solar_term || state.term} · ${dungeonName(dungeon)}`,
    ruleText: mechanic.field_rule || "本层节气机制正在改变路线。",
    puzzleText: mechanic.puzzle_core || "观察机关节奏，再决定推进方式。",
    recommended,
    solutionText: activeSolution
      ? `${activeSolution.spiritName}可用「${activeSolution.ability}」`
      : `推荐带 ${recommended}，现在先靠观察硬解。`,
    exactImpact: activeSolution?.shortImpact || solution?.exactImpact || "未触发专属解法，仍可推进但容错较低。",
    rewardText,
    failureText,
    statusText: hud?.progressText || mechanic.field_rule || "节气机制正在运转。",
    actionText: hud?.actionReady ? `${hud.actionLabel}可用` : hud?.actionUsed ? "本层已顺应节气" : "先观察再推进",
    nextAction: hud?.actionReady
      ? `可在秘境面板手动点「${hud.actionLabel}」`
      : "先探索一层，观察机关如何变化",
    rect: { x: 52, y: 204, width: 306, height: 174 },
  };
}

function dungeonFirstMechanicTheaterAtCanvasPoint(px, py) {
  const spec = dungeonFirstMechanicTheaterSpec();
  if (!spec?.rect) return null;
  const { rect } = spec;
  return px >= rect.x && px <= rect.x + rect.width && py >= rect.y && py <= rect.y + rect.height ? spec : null;
}

function focusDungeonFirstMechanicTheaterFromCanvas(spec = dungeonFirstMechanicTheaterSpec()) {
  if (!spec) return false;
  dungeonFirstMechanicTheaterFocus = { key: spec.key, day: state.day, mechanicId: spec.mechanicId };
  queueStoryCompassFocusTarget({
    selector: ".dungeon-first-mechanic-theater",
    fallbackSelector: "#dungeonPanel",
    label: "点选首次秘境机制小剧场",
    log: `${spec.headline}：场规是「${spec.ruleText}」。解法：${spec.puzzleText}；${spec.solutionText}。奖励焦点：${spec.rewardText}；失败保底：${spec.failureText}。这里只定位秘境面板，不会自动探索、不会自动顺应节气、不会自动挑战 Boss。`,
    panelGroup: "systems",
    missingTitle: "点选首次秘境机制小剧场",
    missingLog: "秘境面板暂时没有找到；这张小剧场只负责解释机制，不会自动探索或顺应节气。",
  });
  return true;
}

function dungeonFirstMechanicTheaterMarkup(spec = dungeonFirstMechanicTheaterSpec()) {
  if (!spec) return "";
  return `
    <div class="dungeon-first-mechanic-theater" data-tone="${spec.tone}">
      <div class="dungeon-first-mechanic-head">
        <strong>${spec.title}</strong>
        <em>${spec.headline}</em>
      </div>
      <span>${spec.statusText} · ${spec.actionText}</span>
      <div class="dungeon-first-mechanic-grid">
        <small><b>场规</b>${spec.ruleText}</small>
        <small><b>解法</b>${spec.puzzleText}</small>
        <small><b>精怪</b>${spec.solutionText}</small>
        <small><b>保底</b>${spec.failureText}</small>
      </div>
      <small class="dungeon-first-mechanic-reward">奖励焦点：${spec.rewardText} · ${spec.nextAction}。这里只解释和定位，不会自动探索、顺应节气或挑战 Boss。</small>
    </div>
  `;
}

function dungeonStructureRouteSpec(run = state.dungeon, mechanic = currentDungeonMechanic(), dungeon = currentDungeonConfig(), hud = dungeonMechanicHudSpec(run, mechanic, dungeon), solution = dungeonSpiritSolutionSpec(run, mechanic, dungeon)) {
  if (!run || !mechanic || !dungeon) return null;
  const floor = Number(run.floor || dungeon.floor_start || 1);
  const maxFloor = Math.max(floor, Number(run.maxFloor || dungeon.floor_end || floor));
  const progress = Math.max(0, Number(run.progress || 0));
  const hasAttuned = Number(run.mechanicActionUses || 0) > 0 || Boolean(run.lastMechanicActionKey);
  const hasConflict = progress > 0 || Boolean(run.lastEnemyId) || Boolean(run.bossReady);
  const cleared = Boolean(run.finished && state.dungeonClears.has(dungeon.area_id));
  const failed = Boolean(run.finished && !state.dungeonClears.has(dungeon.area_id));
  const routeProgress = cleared ? 5
    : failed ? Math.max(2, Math.min(4, progress + 1))
      : run.bossReady ? 4
        : hasConflict ? 3
          : hasAttuned || progress > 0 ? 2
            : 1;
  const entryHint = run.rotationEntryText || run.roomEvent || "确认入口、体力和随行精怪。";
  const fieldHint = hud?.detail || mechanic.field_rule || "节气规则会改写路线。";
  const puzzleHint = solution?.active && solution.primary
    ? `${solution.primary.spiritName}用「${solution.primary.ability}」接入机关。`
    : `推荐 ${splitTags(mechanic.recommended_spirits || "").join(" / ") || "随行精怪"} 解开机关。`;
  const conflictHint = run.bossReady
    ? `${bossName(dungeonBossId(dungeon, run))} 已现身，读招后再反击。`
    : hasConflict
      ? `${data.enemiesById.get(run.lastEnemyId)?.enemy_name_key ? enemyName(data.enemiesById.get(run.lastEnemyId)) : "敌影"} 和 ${run.hazards?.[0]?.label || "场地压力"} 正在压场。`
      : "继续探索会遇到敌人、陷阱或 Boss 前摇。";
  const resolutionHint = cleared
    ? `已带来外部变化：${mechanic.external_change || "洞天生态变化"}。`
    : failed
      ? `${mechanic.failure_compensation || "保留已发现地图和少量材料"}，下次从见闻继续。`
      : `目标：${mechanic.main_reward || "带回节气奖励"}，并触发「${mechanic.external_change || "洞天生态变化"}」。`;
  const stages = [
    { key: "entry", label: "entry", title: "入场", text: entryHint, state: routeProgress >= 1 ? "done" : "pending" },
    { key: "field_rule", label: "field_rule", title: "场地规则", text: fieldHint, state: routeProgress >= 2 ? "done" : routeProgress === 1 ? "current" : "pending" },
    { key: "puzzle", label: "puzzle", title: "精怪解谜", text: puzzleHint, state: solution?.active ? "done" : routeProgress >= 2 ? "current" : "pending" },
    { key: "conflict", label: "conflict", title: "冲突", text: conflictHint, state: routeProgress >= 4 ? "done" : hasConflict ? "current" : "pending" },
    { key: "resolution", label: "resolution", title: "余波", text: resolutionHint, state: cleared ? "done" : failed ? "warn" : run.bossReady ? "current" : "pending" },
  ];
  return {
    title: "秘境五段结构",
    tone: dungeonMechanicTone(mechanic),
    theme: dungeonMechanicTheme(dungeonMechanicTone(mechanic)),
    dungeonName: dungeonName(dungeon),
    termLabel: mechanic.solar_term || state.term || "节气",
    routeProgress,
    floor,
    maxFloor,
    stages,
    activeStage: stages.find((stage) => stage.state === "current") || stages[Math.min(4, routeProgress - 1)] || stages[0],
    summary: `${mechanic.puzzle_core || "机关解谜"} · ${mechanic.external_change || "通关后改变外部世界"}`,
    nextAction: cleared
      ? "回目标册查看节气印记和秘境余波。"
      : failed
        ? "按失败见闻补状态或换随行精怪再来。"
        : run.bossReady
          ? "读 Boss 前摇并挑战 Boss。"
          : hasAttuned
            ? "继续探索一层，把当前节气节奏吃满。"
            : "先顺应节气或观察推荐精怪解法。",
  };
}

function dungeonStructureRouteMarkup(spec = dungeonStructureRouteSpec()) {
  if (!spec) return "";
  return `
    <div class="dungeon-structure-route" data-tone="${spec.tone}">
      <div class="dungeon-structure-head">
        <strong>${spec.title} · ${spec.termLabel}</strong>
        <em>${spec.floor}/${spec.maxFloor} 层</em>
      </div>
      <span>${spec.dungeonName}：${spec.summary}</span>
      <div class="dungeon-structure-steps">
        ${spec.stages.map((stage, index) => `
          <i class="${stage.state}">
            <b>${index + 1}. ${stage.title}</b>
            <em>${stage.label}</em>
            <small>${stage.text}</small>
          </i>
        `).join("")}
      </div>
      <small>当前：${spec.activeStage?.title || "入场"} · 下一步：${spec.nextAction}</small>
    </div>
  `;
}

function drawDungeonStructureRouteRibbon(ctx, spec = dungeonStructureRouteSpec(), x = 84, y = 184, width = 392, height = 72) {
  if (!spec?.stages?.length) return false;
  const theme = spec.theme || dungeonMechanicTheme(spec.tone);
  ctx.save();
  drawCanvasCard(ctx, x, y, width, height, "rgba(255, 253, 245, 0.82)");
  ctx.strokeStyle = `${theme.accent}77`;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.roundRect(x + 1, y + 1, width - 2, height - 2, 16);
  ctx.stroke();
  ctx.fillStyle = theme.accent;
  ctx.font = "800 12px Microsoft YaHei";
  ctx.fillText("秘境五段结构", x + 16, y + 22);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "10px Microsoft YaHei";
  ctx.fillText(`当前：${spec.activeStage?.title || "入场"} · ${spec.nextAction}`.slice(0, 42), x + 16, y + height - 12);

  const startX = x + 118;
  const laneY = y + 31;
  const gap = 50;
  ctx.strokeStyle = `${theme.accent}44`;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(startX + 8, laneY);
  ctx.lineTo(startX + gap * 4 + 8, laneY);
  ctx.stroke();
  spec.stages.slice(0, 5).forEach((stage, index) => {
    const dotX = startX + index * gap;
    const done = stage.state === "done";
    const current = stage.state === "current";
    const warn = stage.state === "warn";
    ctx.fillStyle = warn ? "rgba(190, 79, 55, 0.9)" : done ? `${theme.accent}dd` : current ? theme.glow : "rgba(255, 253, 245, 0.88)";
    ctx.strokeStyle = warn ? "rgba(190, 79, 55, 0.9)" : current || done ? theme.accent : "rgba(93, 111, 101, 0.22)";
    ctx.lineWidth = current ? 3 : 1.5;
    ctx.beginPath();
    ctx.arc(dotX + 8, laneY, current ? 10 : 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = done || warn ? "#fffdf5" : theme.accent;
    ctx.font = "900 8px Microsoft YaHei";
    ctx.fillText(String(index + 1), dotX + 5, laneY + 3);
    ctx.fillStyle = current ? "#17231d" : done ? theme.accent : "#5d6f65";
    ctx.font = "800 8px Microsoft YaHei";
    ctx.fillText(stage.title.slice(0, 3), dotX - 3, laneY + 23);
  });
  ctx.restore();
  return true;
}

function dungeonMechanicSupportLevel(mechanic = currentDungeonMechanic()) {
  if (!mechanic) return 0;
  let support = dungeonSpiritAdvantage(mechanic) > 0 ? 1 : 0;
  const text = `${mechanic.recommended_spirits || ""}${mechanic.puzzle_core || ""}${mechanic.field_rule || ""}`;
  if (text.includes("雷竹") && stormEscortActive()) support += 1;
  if (text.includes("灯影") && (nightLampComboActive() || state.completedRareSpiritEvents.has("rsea_018"))) support += 1;
  if (text.includes("月莲") && (moonPondComboActive() || yuelianRestRespiteActive())) support += 1;
  if (text.includes("花铃") && (hualingGuestCharmActive() || state.completedRareSpiritEvents.has("rsea_012"))) support += 1;
  if (text.includes("蜂蜜") && (fengmiDessertQualityActive() || fengmiHoneyFeastActive())) support += 1;
  if (text.includes("书契") && (shuqiLedgerInsightActive() || shuqiStockWarningActive() || shuqiLegacyLedgerActive())) support += 1;
  return support;
}

function createInitialDungeonMechanicState(mechanic = currentDungeonMechanic(), run = {}) {
  const hiddenRevealStart = Number(run.hiddenRevealPressureDown || 0) > 0 ? 1 : 0;
  switch (mechanic?.dungeon_id) {
    case "dsm_001":
      return { pillarsLit: 0, resonanceTurn: true, lastNote: "等雷声共振后再推进，雷木柱才会真正醒过来。" };
    case "dsm_002":
      return { waterLevel: 1, sluicesAligned: 0, lastNote: "平水时最好走，也最容易接上回渠闸口。" };
    case "dsm_003":
      return { cadence: 1, listened: 0, lastNote: "先听准虫鸣正拍，再决定往哪条林道钻。" };
    case "dsm_004":
      return { overflow: 0, lastNote: "先别急着贪满，每多采一层，谷底都会更躁。" };
    case "dsm_005":
      return { verifiedPaths: 0, lastNote: "先顺着倒影找真路，别被镜面骗着绕圈。" };
    case "dsm_006":
      return { coldStacks: 0, lastNote: "霜气会一层层压上来，拖得越久越难走。" };
    case "dsm_007":
      return { windShift: 0, routeMarks: 0, lastNote: "风会翻叶，也会把旧路重新露出来。" };
    case "dsm_008":
      return { lanternChain: Math.max(1, 1 + hiddenRevealStart), lastNote: "先把断掉的灯火链一盏盏接起来。" };
    default:
      return { lastNote: mechanic?.field_rule || "秘境机制正在变化。" };
  }
}

function normalizeDungeonMechanicState(mechanicState = {}, mechanic = currentDungeonMechanic(), run = state.dungeon) {
  const defaults = createInitialDungeonMechanicState(mechanic, run);
  return {
    ...defaults,
    ...mechanicState,
    pillarsLit: Math.max(0, Math.min(3, Number(mechanicState.pillarsLit ?? defaults.pillarsLit ?? 0))),
    resonanceTurn: mechanicState.resonanceTurn === undefined ? Boolean(defaults.resonanceTurn) : Boolean(mechanicState.resonanceTurn),
    waterLevel: Math.max(0, Math.min(2, Number(mechanicState.waterLevel ?? defaults.waterLevel ?? 1))),
    sluicesAligned: Math.max(0, Math.min(3, Number(mechanicState.sluicesAligned ?? defaults.sluicesAligned ?? 0))),
    cadence: Math.max(0, Math.min(2, Number(mechanicState.cadence ?? defaults.cadence ?? 1))),
    listened: Math.max(0, Math.min(3, Number(mechanicState.listened ?? defaults.listened ?? 0))),
    overflow: Math.max(0, Math.min(5, Number(mechanicState.overflow ?? defaults.overflow ?? 0))),
    verifiedPaths: Math.max(0, Math.min(3, Number(mechanicState.verifiedPaths ?? defaults.verifiedPaths ?? 0))),
    coldStacks: Math.max(0, Math.min(4, Number(mechanicState.coldStacks ?? defaults.coldStacks ?? 0))),
    windShift: Math.max(0, Math.min(1, Number(mechanicState.windShift ?? defaults.windShift ?? 0))),
    routeMarks: Math.max(0, Math.min(3, Number(mechanicState.routeMarks ?? defaults.routeMarks ?? 0))),
    lanternChain: Math.max(1, Math.min(7, Number(mechanicState.lanternChain ?? defaults.lanternChain ?? 1))),
    lastNote: String(mechanicState.lastNote ?? defaults.lastNote ?? ""),
  };
}

function syncDungeonMechanicState(run = state.dungeon, mechanic = currentDungeonMechanic(), dungeon = currentDungeonConfig()) {
  if (!run || !mechanic || !dungeon) return null;
  run.mechanicState = normalizeDungeonMechanicState(run.mechanicState, mechanic, run);
  return run.mechanicState;
}

function dungeonMechanicStatus(run = state.dungeon, mechanic = currentDungeonMechanic(), dungeon = currentDungeonConfig()) {
  const mechanicState = syncDungeonMechanicState(run, mechanic, dungeon);
  if (!mechanicState || !mechanic) return null;
  switch (mechanic.dungeon_id) {
    case "dsm_001":
      return { label: "雷木柱", summary: `${mechanicState.pillarsLit}/3 · ${mechanicState.resonanceTurn ? "共振将至" : "余震未稳"}`, detail: mechanicState.lastNote };
    case "dsm_002":
      return { label: "回渠水位", summary: `${["浅水", "平水", "丰水"][mechanicState.waterLevel] || "平水"} · 闸口 ${mechanicState.sluicesAligned}/3`, detail: mechanicState.lastNote };
    case "dsm_003":
      return { label: "虫鸣节拍", summary: `${["前拍", "正拍", "回拍"][mechanicState.cadence] || "正拍"} · 听准 ${mechanicState.listened}/3`, detail: mechanicState.lastNote };
    case "dsm_004":
      return { label: "满溢值", summary: `${mechanicState.overflow}/5 · 掉落 +${Math.round(mechanicState.overflow * 12)}%`, detail: mechanicState.lastNote };
    case "dsm_005":
      return { label: "倒影真路", summary: `已验证 ${mechanicState.verifiedPaths}/3 段`, detail: mechanicState.lastNote };
    case "dsm_006":
      return { label: "霜寒层数", summary: `${mechanicState.coldStacks}/4 · 越拖越冷`, detail: mechanicState.lastNote };
    case "dsm_007":
      return { label: "落叶旧路", summary: `${mechanicState.routeMarks}/3 · ${mechanicState.windShift ? "逆风覆路" : "顺风露路"}`, detail: mechanicState.lastNote };
    case "dsm_008":
      return { label: "长灯链", summary: `${mechanicState.lanternChain}/7 · ${mechanicState.lanternChain >= 4 ? "影路渐成" : "灯火未稳"}`, detail: mechanicState.lastNote };
    default:
      return { label: "节气机制", summary: mechanic.field_rule || mechanic.puzzle_core || "秘境机制", detail: mechanicState.lastNote };
  }
}

function dungeonMechanicActionKey(run = state.dungeon) {
  if (!run) return "";
  return run.bossReady ? `boss_${run.floor}` : `floor_${run.floor}`;
}

function dungeonMechanicActionSpec(run = state.dungeon, mechanic = currentDungeonMechanic(), dungeon = currentDungeonConfig()) {
  const mechanicState = syncDungeonMechanicState(run, mechanic, dungeon);
  if (!run || !mechanic || !mechanicState) return null;
  const used = run.lastMechanicActionKey === dungeonMechanicActionKey(run);
  const base = {
    cost: 5,
    used,
    disabled: used,
    detail: used ? "这一层已经顺着节气调过一次了，先把刚才稳住的节奏吃满。" : mechanicState.lastNote || mechanic.field_rule || "顺着节气去做一手准备。",
    label: "顺应节气",
  };
  switch (mechanic.dungeon_id) {
    case "dsm_001":
      return { ...base, label: used ? "本层已借雷" : "借雷点柱", detail: used ? base.detail : "趁雷声将近，主动去点亮一根雷木柱，把共振握在自己手里。" };
    case "dsm_002":
      return { ...base, label: used ? "本层已调闸" : "调闸稳水", detail: used ? base.detail : "先把水位调回平水，顺手接上一段回渠闸口。" };
    case "dsm_003":
      return { ...base, label: used ? "本层已听拍" : "驻足听拍", detail: used ? base.detail : "停下来听一轮虫鸣正拍，把下一段林道先认清。" };
    case "dsm_004":
      return { ...base, label: used ? "本层已稳谷" : "压住满溢", detail: used ? base.detail : "先把最躁的一股满溢压住，少吃一点灵压反扑。" };
    case "dsm_005":
      return { ...base, label: used ? "本层已验影" : "照影验路", detail: used ? base.detail : "主动照一次倒影，把这一层的真路先确认下来。" };
    case "dsm_006":
      return { ...base, label: used ? "本层已暖身" : "燃火暖身", detail: used ? base.detail : "先烧一轮暖火，别让霜气继续往骨头里压。" };
    case "dsm_007":
      return { ...base, label: used ? "本层已记路" : "压叶记路", detail: used ? base.detail : "把脚边残叶压住记成路标，免得下一阵风再把旧路吹没。" };
    case "dsm_008":
      return { ...base, label: used ? "本层已续灯" : "续起长灯", detail: used ? base.detail : "先去把断开的灯火链续上一截，让影路更稳一点。" };
    default:
      return base;
  }
}

function dungeonMechanicTone(mechanic = currentDungeonMechanic()) {
  switch (mechanic?.dungeon_id) {
    case "dsm_001":
      return "thunder";
    case "dsm_002":
      return "water";
    case "dsm_003":
      return "insect";
    case "dsm_004":
      return "overflow";
    case "dsm_005":
      return "mirror";
    case "dsm_006":
      return "frost";
    case "dsm_007":
      return "wind";
    case "dsm_008":
      return "lantern";
    default:
      return "mist";
  }
}

