function dungeonMechanicWorldPreviewAnchor(dungeon = null) {
  const anchors = {
    area_mine_qingyun: { x: 826, y: 256, label: "青云矿洞雷门" },
    area_herb_valley: { x: 844, y: 216, label: "雾隐药谷藤门" },
    area_ruin_fire: { x: 742, y: 206, label: "炽砂遗迹断门" },
    area_final_nest: { x: 858, y: 360, label: "终巢水门" },
  };
  return anchors[dungeon?.area_id] || { x: 808, y: 236, label: "秘境入口" };
}

function dungeonMechanicWorldPreviewRect() {
  const slots = [
    { x: 582, y: 82, width: 344, height: 152 },
    { x: 498, y: 196, width: 344, height: 152 },
    { x: 548, y: 330, width: 344, height: 152 },
    { x: 238, y: 138, width: 344, height: 152 },
  ];
  const rare = rareSpiritWorldInvitationSpec();
  const blocked = rare?.rect || null;
  const overlap = (a, b) => b
    && a.x < b.x + b.width
    && a.x + a.width > b.x
    && a.y < b.y + b.height
    && a.y + a.height > b.y;
  return slots.find((slot) => !overlap(slot, blocked)) || slots[0];
}

function dungeonMechanicWorldPreviewSpec() {
  if (state.dungeon && !state.dungeon.finished) return null;
  const dungeons = availableDungeons();
  if (dungeons.length === 0 || data.dungeonSolarMechanics.length === 0) return null;
  const revealedRotation = dengyingRevealedRotation();
  const candidates = dungeons
    .map((dungeon, index) => {
      const mechanic = currentDungeonMechanic(dungeon);
      if (!mechanic) return null;
      const cleared = state.dungeonClears.has(dungeon.area_id);
      const change = (state.dungeonWorldChanges || []).find((entry) => entry.dungeonId === dungeon.area_id) || null;
      const rotation = activeHiddenRotationForDungeon(dungeon);
      const solution = dungeonSpiritSolutionSpec(null, mechanic, dungeon);
      const failureInsight = dungeonFailureInsight(dungeon, mechanic);
      const failureSummary = dungeonFailureInsightSummary(failureInsight);
      const stampSummary = dungeonCompendiumEntrySummary(dungeonCompendiumEntry(dungeon, mechanic));
      const termMatch = mechanic.solar_term === state.term;
      const score = (revealedRotation?.area_id === dungeon.area_id ? 140 : 0)
        + (!cleared ? 90 : 0)
        + (termMatch ? 70 : 0)
        + (failureSummary ? 26 : 0)
        + (stampSummary ? 18 : 0)
        + (rotation ? 24 : 0)
        + (change ? 12 : 0)
        - index;
      return {
        dungeon,
        mechanic,
        cleared,
        change,
        rotation,
        solution,
        failureInsight,
        failureSummary,
        stampSummary,
        termMatch,
        score,
      };
    })
    .filter(Boolean)
    .sort((a, b) => b.score - a.score);
  const top = candidates[0];
  if (!top) return null;
  const { dungeon, mechanic, cleared, change, rotation, solution, failureSummary, stampSummary, termMatch } = top;
  const recommendedSpirits = splitTags(mechanic.recommended_spirits || "");
  const tone = dungeonMechanicTone(mechanic);
  const activeSolution = solution?.active && solution.primary;
  const rotationRewardText = rotation ? rewardPoolPreviewText(rotation.rare_drop_pool) : "";
  const mainRewardText = rotationRewardText || mechanic.main_reward || "节气材料/稀有线索";
  const safeguardText = failureSummary
    ? failureSummary.detail || failureSummary.body
    : stampSummary
      ? `${stampSummary.title} · ${stampSummary.detail}`
      : "失败也会保留路感、印记碎片和机关线索";
  const statusLabel = cleared
    ? "已通关"
    : revealedRotation?.area_id === dungeon.area_id
      ? "灯影显形"
      : rotation
        ? "隐藏轮换"
        : termMatch
          ? "今日节气"
          : "入口预告";
  return {
    id: "dungeon_mechanic_world_preview",
    dungeonId: dungeon.area_id,
    dungeonName: dungeonName(dungeon),
    mechanicId: mechanic.dungeon_id,
    termLabel: mechanic.solar_term || state.term || "节气",
    tone,
    theme: dungeonMechanicTheme(tone),
    statusLabel,
    title: "秘境机制预告 · 可点",
    headline: `${mechanic.solar_term || state.term} · ${mechanic.puzzle_core || "秘境机关正在变化"}`,
    fieldRule: mechanic.field_rule || "当前节气会改变秘境走法。",
    puzzleCore: mechanic.puzzle_core || "先观察机关，再决定推进节奏。",
    recommendedSpirits,
    recommendedSpiritText: recommendedSpirits.join(" / ") || "随行精怪",
    mainRewardText,
    safeguardText,
    stampText: stampSummary ? stampSummary.title : "节气印记未收录",
    failureText: failureSummary ? failureSummary.title : "失败保底线索",
    externalChange: change?.title || mechanic.external_change || "洞天生态变化",
    solutionText: activeSolution
      ? `${solution.primary.spiritName}命中${solution.primary.key}解法`
      : `推荐 ${recommendedSpirits.join(" / ") || "随行精怪"}`,
    supportCount: Number(solution?.solutionCount || 0),
    cleared,
    ready: !cleared,
    rect: dungeonMechanicWorldPreviewRect(),
    anchor: dungeonMechanicWorldPreviewAnchor(dungeon),
  };
}

function dungeonMechanicWorldPreviewAtCanvasPoint(px, py) {
  const spec = dungeonMechanicWorldPreviewSpec();
  if (!spec) return null;
  const { rect } = spec;
  return px >= rect.x && px <= rect.x + rect.width && py >= rect.y && py <= rect.y + rect.height
    ? spec
    : null;
}

function focusDungeonMechanicWorldPreviewFromCanvas(spec = dungeonMechanicWorldPreviewSpec()) {
  if (!spec) return false;
  const selector = state.dungeon && !state.dungeon.finished
    ? "#dungeonPanel"
    : `[data-dungeon-card-id="${selectorDataValue(spec.dungeonId)}"]`;
  queueStoryCompassFocusTarget({
    selector,
    fallbackSelector: "#dungeonPanel",
    label: `点选秘境机制：${spec.dungeonName}`,
    log: `${spec.dungeonName} 的${spec.termLabel}机制已在秘境面板高亮。规则：${spec.fieldRule}；解法：${spec.puzzleCore}。${spec.solutionText}，奖励焦点：${spec.mainRewardText}；失败保底：${spec.safeguardText}；通关后会带来「${spec.externalChange}」。`,
    panelGroup: "systems",
    missingTitle: "点选秘境机制：入口定位",
    missingLog: "秘境入口卡暂时没有找到，先确认系统深挖分组是否可见。",
  });
  return true;
}

function dungeonMechanicWorldRouteRect(previewRect = dungeonMechanicWorldPreviewSpec()?.rect) {
  const width = 424;
  const height = 98;
  if (!previewRect) return { x: 468, y: 254, width, height };
  const x = Math.max(24, Math.min(960 - width - 22, previewRect.x - 52));
  const belowY = previewRect.y + previewRect.height + 12;
  const y = belowY + height <= 616
    ? belowY
    : Math.max(64, previewRect.y - height - 12);
  return { x, y, width, height };
}

function dungeonMechanicWorldRouteSpec(preview = dungeonMechanicWorldPreviewSpec()) {
  if (!preview) return null;
  const dungeon = data.dungeonsById.get(preview.dungeonId) || availableDungeons().find((entry) => entry.area_id === preview.dungeonId) || null;
  const mechanic = data.dungeonSolarMechanics.find((entry) => entry.dungeon_id === preview.mechanicId) || currentDungeonMechanic(dungeon);
  if (!dungeon || !mechanic) return null;
  const solution = dungeonSpiritSolutionSpec(null, mechanic, dungeon);
  const recommendedSpirits = splitTags(mechanic.recommended_spirits || "");
  const activeSolution = solution?.active && solution.primary;
  const stages = [
    {
      key: "entry",
      label: "入场",
      title: preview.statusLabel || "入口预告",
      text: `${preview.dungeonName} · ${preview.termLabel}`,
      tone: "entry",
    },
    {
      key: "field_rule",
      label: "场规",
      title: mechanic.solar_term || preview.termLabel,
      text: mechanic.field_rule || "节气会改变秘境走法。",
      tone: "rule",
    },
    {
      key: "spirit_solution",
      label: "精怪",
      title: activeSolution ? solution.primary.spiritName : recommendedSpirits.join("/") || "随行",
      text: activeSolution ? solution.primary.shortImpact : `推荐 ${recommendedSpirits.join(" / ") || "随行精怪"}。`,
      tone: activeSolution ? "good" : "missing",
    },
    {
      key: "failure_safeguard",
      label: "保底",
      title: preview.failureText || "失败保底",
      text: preview.safeguardText || "失败也会保留路感和机关线索。",
      tone: "safe",
    },
    {
      key: "resolution",
      label: "余波",
      title: mechanic.main_reward || preview.mainRewardText,
      text: mechanic.external_change || preview.externalChange || "通关后改变洞天生态。",
      tone: "reward",
    },
  ];
  const supportCount = Number(solution?.solutionCount || 0);
  const supportText = activeSolution
    ? `${solution.primary.spiritName}已接入「${solution.primary.ability}」`
    : `带上 ${recommendedSpirits.join(" / ") || "推荐精怪"} 可触发精怪解法`;
  return {
    id: "dungeon_mechanic_world_route",
    key: `${state.day}:${preview.dungeonId}:${preview.mechanicId}:${supportCount}:${preview.statusLabel}:${preview.cleared ? 1 : 0}`,
    dungeonId: preview.dungeonId,
    dungeonName: preview.dungeonName,
    mechanicId: preview.mechanicId,
    termLabel: preview.termLabel,
    tone: preview.tone,
    theme: preview.theme || dungeonMechanicTheme(preview.tone),
    title: "秘境节气路线图 · 可点",
    headline: `${mechanic.puzzle_core || preview.puzzleCore} · ${mechanic.external_change || preview.externalChange}`,
    fieldRule: mechanic.field_rule || preview.fieldRule,
    supportText,
    supportCount,
    rewardText: preview.mainRewardText,
    safeguardText: preview.safeguardText,
    stages,
    rect: dungeonMechanicWorldRouteRect(preview.rect),
    anchor: preview.anchor,
  };
}

function dungeonMechanicWorldRouteAtCanvasPoint(px, py) {
  const spec = dungeonMechanicWorldRouteSpec();
  if (!spec?.rect) return null;
  const { rect } = spec;
  return px >= rect.x && px <= rect.x + rect.width && py >= rect.y && py <= rect.y + rect.height
    ? spec
    : null;
}

function focusDungeonMechanicWorldRouteFromCanvas(spec = dungeonMechanicWorldRouteSpec()) {
  if (!spec) return false;
  dungeonMechanicWorldRouteFocus = { key: spec.key, day: state.day, dungeonId: spec.dungeonId };
  queueStoryCompassFocusTarget({
    selector: `[data-dungeon-card-id="${selectorDataValue(spec.dungeonId)}"]`,
    fallbackSelector: "#dungeonPanel",
    label: `点选秘境节气路线：${spec.dungeonName}`,
    log: `${spec.dungeonName} 的秘境节气路线已定位：${spec.stages.map((stage) => `${stage.label}:${stage.title}`).join(" -> ")}。场地规则：${spec.fieldRule}；精怪解法：${spec.supportText}；失败保底：${spec.safeguardText}；通关余波：${spec.rewardText}。这里只定位到秘境面板，不会自动进入秘境、探索、顺应节气或挑战 Boss。`,
    panelGroup: "systems",
    missingTitle: "点选秘境节气路线",
    missingLog: "秘境节气路线已经点到，但秘境入口卡暂时没有找到。先打开系统深挖里的秘境探索面板查看入口与节气机制。",
  });
  return true;
}

function dungeonEntranceSilhouetteRect(preview = dungeonMechanicWorldPreviewSpec(), width = 960, height = 640) {
  const rectWidth = 352;
  const rectHeight = 126;
  const anchor = preview?.anchor || { x: 808, y: 236 };
  const routeRect = dungeonMechanicWorldRouteSpec(preview)?.rect || null;
  const atlasRect = dungeonSolarAtlasWorldSpec(width, height)?.rect || null;
  const blockers = [
    { x: 44, y: 42, width: 326, height: 96 },
    preview?.rect,
    routeRect,
    atlasRect,
  ].filter(Boolean);
  const overlap = (a, b) => a.x < b.x + b.width && a.x + a.width > b.x && a.y < b.y + b.height && a.y + a.height > b.y;
  const slots = [
    { x: anchor.x - rectWidth - 38, y: anchor.y + 28, width: rectWidth, height: rectHeight },
    { x: anchor.x - rectWidth - 46, y: anchor.y - rectHeight - 32, width: rectWidth, height: rectHeight },
    { x: anchor.x + 34, y: anchor.y + 26, width: rectWidth, height: rectHeight },
    { x: 36, y: height - rectHeight - 34, width: rectWidth, height: rectHeight },
  ].map((slot) => ({
    ...slot,
    x: Math.max(24, Math.min(width - rectWidth - 24, slot.x)),
    y: Math.max(58, Math.min(height - rectHeight - 28, slot.y)),
  }));
  return slots.find((slot) => !blockers.some((blocker) => overlap(slot, blocker))) || slots[0];
}

function dungeonEntranceSilhouetteSpec(width = 960, height = 640, preview = dungeonMechanicWorldPreviewSpec()) {
  if (!preview) return null;
  const dungeon = data.dungeonsById.get(preview.dungeonId) || availableDungeons().find((entry) => entry.area_id === preview.dungeonId) || null;
  const mechanic = data.dungeonSolarMechanics.find((entry) => entry.dungeon_id === preview.mechanicId) || currentDungeonMechanic(dungeon);
  if (!dungeon || !mechanic) return null;
  const solution = dungeonSpiritSolutionSpec(null, mechanic, dungeon);
  const activeSolution = solution?.active && solution.primary ? solution.primary : null;
  const recommendedSpirits = splitTags(mechanic.recommended_spirits || "");
  const recommendedText = recommendedSpirits.join(" / ") || "随行精怪";
  const rect = dungeonEntranceSilhouetteRect(preview, width, height);
  const theme = preview.theme || dungeonMechanicTheme(dungeonMechanicTone(mechanic));
  const nodeWidth = 96;
  const nodeGap = 14;
  const nodeStartX = rect.x + 22;
  const nodeY = rect.y + 62;
  const nodes = [
    {
      key: "field_rule",
      label: "场规味道",
      glyph: "味",
      title: `${mechanic.solar_term || preview.termLabel} · ${dungeonSolarAtlasKeyword(mechanic)}`,
      text: mechanic.field_rule || preview.fieldRule || "节气会改变秘境走法。",
      detail: mechanic.puzzle_core || preview.puzzleCore || "先观察机关，再决定推进节奏。",
      tone: "rule",
    },
    {
      key: "spirit_solution",
      label: "精怪解法",
      glyph: "解",
      title: activeSolution ? `${activeSolution.spiritName} · ${activeSolution.ability}` : `推荐 ${recommendedText}`,
      text: activeSolution ? activeSolution.shortImpact : `带上 ${recommendedText} 可触发精怪解法。`,
      detail: activeSolution ? activeSolution.actionHint || preview.solutionText : preview.solutionText || `推荐 ${recommendedText}`,
      tone: activeSolution ? "solution" : "missing",
    },
    {
      key: "external_change",
      label: "带回变化",
      glyph: "变",
      title: mechanic.main_reward || preview.mainRewardText || "节气材料/稀有线索",
      text: mechanic.external_change || preview.externalChange || "通关后改变洞天生态。",
      detail: preview.safeguardText || "失败也会保留路感、印记碎片和机关线索。",
      tone: "reward",
    },
  ].map((node, index) => ({
    ...node,
    rect: {
      x: nodeStartX + index * (nodeWidth + nodeGap),
      y: nodeY,
      width: nodeWidth,
      height: 46,
    },
  }));
  return {
    id: "dungeon_entrance_silhouette",
    key: `${state.day}:${preview.dungeonId}:${preview.mechanicId}:${solution?.solutionCount || 0}:${preview.cleared ? 1 : 0}`,
    title: "秘境入口剪影牌 · 可点",
    subtitle: `${preview.dungeonName} · ${preview.termLabel}入口辨识`,
    note: "只解释和定位，不自动进境",
    dungeonId: preview.dungeonId,
    dungeonName: preview.dungeonName,
    mechanicId: preview.mechanicId,
    termLabel: preview.termLabel,
    fieldRule: mechanic.field_rule || preview.fieldRule,
    supportText: activeSolution ? `${activeSolution.spiritName}接住${activeSolution.key}解法` : `推荐 ${recommendedText}`,
    externalChange: mechanic.external_change || preview.externalChange,
    safeguardText: preview.safeguardText,
    anchor: preview.anchor,
    rect,
    theme,
    tone: preview.tone || dungeonMechanicTone(mechanic),
    nodes,
  };
}

function dungeonEntranceSilhouetteAtCanvasPoint(px, py) {
  const spec = dungeonEntranceSilhouetteSpec();
  if (!spec?.rect) return null;
  const { rect } = spec;
  if (px < rect.x || px > rect.x + rect.width || py < rect.y || py > rect.y + rect.height) return null;
  const targetNode = spec.nodes.find((node) =>
    px >= node.rect.x && px <= node.rect.x + node.rect.width
    && py >= node.rect.y && py <= node.rect.y + node.rect.height,
  ) || spec.nodes[0];
  return { ...spec, targetNode };
}

function focusDungeonEntranceSilhouetteFromCanvas(spec = dungeonEntranceSilhouetteSpec()) {
  const node = spec?.targetNode || spec?.nodes?.[0] || null;
  if (!spec || !node) return false;
  dungeonEntranceSilhouetteWorldFocus = {
    day: state.day,
    key: spec.key,
    nodeKey: node.key,
    dungeonId: spec.dungeonId,
  };
  queueStoryCompassFocusTarget({
    selector: `[data-dungeon-card-id="${selectorDataValue(spec.dungeonId)}"]`,
    fallbackSelector: "#dungeonPanel",
    label: `点选秘境入口剪影：${node.label}`,
    log: `秘境入口剪影牌已定位「${spec.dungeonName}」的${node.label}。${node.title}：${node.text}；${node.detail}。入口剪影只解释和定位，不会自动进入秘境、探索、顺应节气、挑战 Boss 或消耗资源。`,
    panelGroup: "systems",
    missingTitle: "点选秘境入口剪影",
    missingLog: "秘境入口剪影已经点到，但对应秘境入口卡暂时不可见。先打开系统深挖里的秘境探索面板查看场规味道、精怪解法和带回变化；不会自动进入秘境、探索、顺应节气、挑战 Boss 或消耗资源。",
  });
  return true;
}

function dungeonSolarAtlasDungeonForMechanic(mechanic = null) {
  const map = {
    dsm_001: "area_mine_qingyun",
    dsm_002: HERB_VALLEY_AREA_ID,
    dsm_004: "area_ruin_fire",
    dsm_008: "area_final_nest",
  };
  const dungeonId = map[mechanic?.dungeon_id] || "";
  return dungeonId ? data.dungeonsById.get(dungeonId) || null : null;
}

function dungeonSolarAtlasKeyword(mechanic = null) {
  const keywords = {
    dsm_001: "雷声震动",
    dsm_002: "水位涨落",
    dsm_003: "虫鸣改路",
    dsm_004: "满溢取舍",
    dsm_005: "倒影真路",
    dsm_006: "寒气迟滞",
    dsm_007: "风向开路",
    dsm_008: "灯灭重组",
  };
  return keywords[mechanic?.dungeon_id] || String(mechanic?.field_rule || "节气机关").slice(0, 6);
}

function dungeonSolarAtlasWorldRect(width = 960, height = 640) {
  const rectWidth = 432;
  const rectHeight = 172;
  const previewRect = dungeonMechanicWorldPreviewSpec()?.rect;
  const routeRect = dungeonMechanicWorldRouteSpec()?.rect;
  const blockers = [previewRect, routeRect].filter(Boolean);
  const overlap = (a, b) => a.x < b.x + b.width && a.x + a.width > b.x && a.y < b.y + b.height && a.y + a.height > b.y;
  const slots = [
    { x: Math.max(24, width - rectWidth - 28), y: Math.max(54, height - rectHeight - 34), width: rectWidth, height: rectHeight },
    { x: 28, y: Math.max(54, height - rectHeight - 34), width: rectWidth, height: rectHeight },
    { x: Math.max(24, width - rectWidth - 28), y: 44, width: rectWidth, height: rectHeight },
    { x: 28, y: 154, width: rectWidth, height: rectHeight },
  ];
  return slots.find((slot) => !blockers.some((blocker) => overlap(slot, blocker))) || slots[0];
}

function dungeonSolarAtlasWorldSpec(width = 960, height = 640) {
  const mechanics = data.dungeonSolarMechanics || [];
  if (mechanics.length === 0 || state.dungeon && !state.dungeon.finished) return null;
  const availableIds = new Set(availableDungeons().map((dungeon) => dungeon.area_id));
  const rect = dungeonSolarAtlasWorldRect(width, height);
  const nodeWidth = 94;
  const nodeHeight = 44;
  const nodes = mechanics.slice(0, 8).map((mechanic, index) => {
    const dungeon = dungeonSolarAtlasDungeonForMechanic(mechanic);
    const dungeonId = dungeon?.area_id || "";
    const available = !dungeonId || availableIds.has(dungeonId);
    const cleared = dungeonId ? state.dungeonClears.has(dungeonId) : false;
    const change = dungeonId
      ? (state.dungeonWorldChanges || []).find((entry) => entry.dungeonId === dungeonId) || null
      : null;
    const tone = dungeonMechanicTone(mechanic);
    const recommendedSpirits = splitTags(mechanic.recommended_spirits || "");
    const column = index % 4;
    const row = Math.floor(index / 4);
    const nodeRect = {
      x: rect.x + 20 + column * 101,
      y: rect.y + 66 + row * 50,
      width: nodeWidth,
      height: nodeHeight,
    };
    const termMatch = mechanic.solar_term === state.term;
    const statusLabel = termMatch
      ? "今日"
      : change
        ? "余波"
        : cleared
          ? "已通"
          : available
            ? "可读"
            : "未开";
    return {
      index,
      mechanic,
      mechanicId: mechanic.dungeon_id,
      dungeon,
      dungeonId,
      dungeonName: dungeon ? dungeonName(dungeon) : "轮换秘境",
      available,
      cleared,
      change,
      termMatch,
      statusLabel,
      tone,
      theme: dungeonMechanicTheme(tone),
      termLabel: mechanic.solar_term || "节气",
      keyword: dungeonSolarAtlasKeyword(mechanic),
      fieldRule: mechanic.field_rule || "节气会改变秘境走法。",
      puzzleCore: mechanic.puzzle_core || "观察机关后决定推进节奏。",
      recommendedSpirits,
      recommendedSpiritText: recommendedSpirits.join(" / ") || "随行精怪",
      rewardText: mechanic.main_reward || "节气材料/稀有线索",
      externalChange: change?.title || mechanic.external_change || "洞天生态变化",
      rect: nodeRect,
      score: (termMatch ? 120 : 0) + (available && !cleared ? 60 : 0) + (change ? 38 : 0) + (cleared ? 16 : 0) - index,
    };
  });
  const preferred = nodes.slice().sort((a, b) => b.score - a.score)[0] || null;
  return {
    id: "dungeon_solar_atlas_world",
    key: `${state.day}:${state.term}:${nodes.map((node) => `${node.mechanicId}:${node.statusLabel}`).join("|")}`,
    title: "秘境节气图谱 · 可点",
    subtitle: "八境节气机关 · 场规关键词",
    note: "点击只定位，不会自动进入秘境",
    rect,
    nodes,
    preferred,
    availableCount: nodes.filter((node) => node.available).length,
    clearedCount: nodes.filter((node) => node.cleared).length,
  };
}

function dungeonSolarAtlasWorldAtCanvasPoint(px, py) {
  const spec = dungeonSolarAtlasWorldSpec();
  if (!spec?.rect) return null;
  const { rect } = spec;
  if (px < rect.x || px > rect.x + rect.width || py < rect.y || py > rect.y + rect.height) return null;
  const targetNode = spec.nodes.find((node) =>
    px >= node.rect.x && px <= node.rect.x + node.rect.width
    && py >= node.rect.y && py <= node.rect.y + node.rect.height,
  ) || spec.preferred;
  return targetNode ? { ...spec, targetNode } : spec;
}

function focusDungeonSolarAtlasWorldFromCanvas(spec = dungeonSolarAtlasWorldAtCanvasPoint(-1, -1) || dungeonSolarAtlasWorldSpec()) {
  const node = spec?.targetNode || spec?.preferred || null;
  if (!spec || !node) return false;
  dungeonSolarAtlasWorldFocus = {
    day: state.day,
    key: spec.key,
    mechanicId: node.mechanicId,
  };
  const selector = node.dungeonId && node.available
    ? `[data-dungeon-card-id="${selectorDataValue(node.dungeonId)}"]`
    : "#dungeonPanel";
  queueStoryCompassFocusTarget({
    selector,
    fallbackSelector: "#dungeonPanel",
    label: `点选秘境节气图谱：${node.termLabel}`,
    log: `秘境节气图谱已定位「${node.termLabel} · ${node.keyword}」。八境节气机关：${node.dungeonName}；场规关键词：${node.keyword}；规则：${node.fieldRule}；核心解法：${node.puzzleCore}；推荐精怪：${node.recommendedSpiritText}；奖励：${node.rewardText}；外部变化：${node.externalChange}。这里只高亮和解释，不会自动进入秘境、探索、顺应节气或挑战 Boss。`,
    panelGroup: "systems",
    missingTitle: "点选秘境节气图谱",
    missingLog: "秘境节气图谱已经点到，但对应入口卡暂时不可见。先打开系统深挖里的秘境探索面板查看八境节气机关。不会自动进入秘境。",
  });
  return true;
}

function drawDungeonMechanicWorldGlyph(ctx, spec, x, y, size, motion) {
  const tone = spec.tone;
  const theme = spec.theme;
  const cx = x + size / 2;
  const cy = y + size / 2;
  const pulse = settings.reducedMotion ? 0 : Math.sin(motion * 2.4) * 2.5;
  ctx.save();
  ctx.fillStyle = theme.soft;
  ctx.beginPath();
  ctx.roundRect(x, y, size, size, 17);
  ctx.fill();
  ctx.strokeStyle = `${theme.accent}88`;
  ctx.lineWidth = 2;
  ctx.stroke();

  ctx.strokeStyle = theme.accent;
  ctx.fillStyle = theme.accent;
  ctx.lineWidth = 3;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  if (tone === "thunder") {
    ctx.beginPath();
    ctx.moveTo(cx - 4, y + 11);
    ctx.lineTo(cx - 18, cy + 4);
    ctx.lineTo(cx + 2, cy + 1);
    ctx.lineTo(cx - 5, y + size - 10);
    ctx.lineTo(cx + 20, cy - 6);
    ctx.lineTo(cx + 3, cy - 3);
    ctx.closePath();
    ctx.fill();
    for (let i = 0; i < 3; i += 1) {
      const px = x + 17 + i * 16;
      ctx.fillRect(px, y + size - 22 - (i === 1 ? pulse : 0), 5, 18);
    }
  } else if (tone === "water") {
    for (let i = 0; i < 3; i += 1) {
      ctx.beginPath();
      ctx.moveTo(x + 12, y + 22 + i * 12 + pulse / 2);
      ctx.bezierCurveTo(x + 24, y + 12 + i * 12, x + 38, y + 32 + i * 12, x + size - 10, y + 20 + i * 12);
      ctx.stroke();
    }
    ctx.fillRect(cx - 18, y + 13, 7, size - 26);
    ctx.fillRect(cx + 12, y + 13, 7, size - 26);
  } else if (tone === "insect") {
    for (let i = 0; i < 6; i += 1) {
      const angle = motion * 0.8 + i;
      ctx.beginPath();
      ctx.arc(cx + Math.cos(angle) * (12 + i), cy + Math.sin(angle * 1.4) * 11, 3.5, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.beginPath();
    ctx.arc(cx, cy, 20 + pulse, -0.6, Math.PI * 1.15);
    ctx.stroke();
  } else if (tone === "overflow") {
    ctx.beginPath();
    ctx.ellipse(cx, cy + 10, 25, 15 + pulse / 2, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = "#8f5f3f";
    for (let i = 0; i < 4; i += 1) {
      ctx.beginPath();
      ctx.moveTo(x + 16, y + 16 + i * 11);
      ctx.lineTo(x + size - 16, y + 20 + i * 9);
      ctx.stroke();
    }
  } else if (tone === "mirror") {
    ctx.beginPath();
    ctx.ellipse(cx, cy - 5, 24, 13, -0.12, 0, Math.PI * 2);
    ctx.stroke();
    ctx.globalAlpha = 0.55;
    ctx.beginPath();
    ctx.ellipse(cx, cy + 21 + pulse / 2, 24, 8, 0.12, 0, Math.PI * 2);
    ctx.stroke();
    ctx.globalAlpha = 1;
    ctx.beginPath();
    ctx.moveTo(cx - 18, cy - 3);
    ctx.lineTo(cx + 18, cy - 3);
    ctx.stroke();
  } else if (tone === "frost") {
    for (let i = 0; i < 6; i += 1) {
      const angle = (Math.PI * 2 * i) / 6 + pulse / 30;
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.lineTo(cx + Math.cos(angle) * 25, cy + Math.sin(angle) * 25);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(cx + Math.cos(angle) * 14, cy + Math.sin(angle) * 14, 2.6, 0, Math.PI * 2);
      ctx.fill();
    }
  } else if (tone === "wind") {
    for (let i = 0; i < 3; i += 1) {
      ctx.beginPath();
      ctx.moveTo(x + 12, y + 20 + i * 15);
      ctx.bezierCurveTo(x + 34, y + 6 + i * 15 + pulse, x + 42, y + 34 + i * 10, x + size - 10, y + 17 + i * 13);
      ctx.stroke();
    }
    ctx.beginPath();
    ctx.ellipse(cx + 10, cy + 10, 11, 6, -0.7, 0, Math.PI * 2);
    ctx.fill();
  } else if (tone === "lantern") {
    for (let i = 0; i < 4; i += 1) {
      const lx = x + 15 + i * 15;
      const ly = y + 16 + i * 3;
      ctx.strokeStyle = "#5b3328";
      ctx.beginPath();
      ctx.moveTo(lx, ly - 8);
      ctx.lineTo(lx, ly + 9);
      ctx.stroke();
      ctx.fillStyle = i < 3 ? theme.accent : "#f6f0b6";
      ctx.beginPath();
      ctx.arc(lx, ly + 12 + pulse / 3, 8, 0, Math.PI * 2);
      ctx.fill();
    }
  } else {
    ctx.beginPath();
    ctx.arc(cx, cy, 22 + pulse, 0, Math.PI * 2);
    ctx.stroke();
    ctx.fillText("境", cx - 9, cy + 6);
  }
  ctx.restore();
}

function drawDungeonMechanicWorldPreview(ctx, spec = dungeonMechanicWorldPreviewSpec()) {
  if (!spec) return false;
  const { rect, anchor, theme } = spec;
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const pulse = settings.reducedMotion ? 0 : Math.sin(motion * 2) * 3;
  const cardY = rect.y + pulse;
  ctx.save();

  ctx.strokeStyle = `${theme.accent}66`;
  ctx.lineWidth = 3;
  ctx.setLineDash([8, 9]);
  ctx.lineDashOffset = settings.reducedMotion ? 0 : -motion * 11;
  ctx.beginPath();
  ctx.moveTo(anchor.x, anchor.y);
  ctx.quadraticCurveTo(rect.x + rect.width - 30, rect.y + rect.height + 24, rect.x + rect.width - 42, cardY + rect.height - 8);
  ctx.stroke();
  ctx.setLineDash([]);

  const glow = ctx.createRadialGradient(anchor.x, anchor.y, 8, anchor.x, anchor.y, 74);
  glow.addColorStop(0, theme.glow);
  glow.addColorStop(0.72, theme.soft);
  glow.addColorStop(1, "rgba(255, 253, 245, 0)");
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(anchor.x, anchor.y, 74 + pulse, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = `${theme.accent}cc`;
  ctx.beginPath();
  ctx.ellipse(anchor.x, anchor.y + 8, 34 + pulse, 13, -0.08, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "#fffdf5";
  ctx.font = "800 11px Microsoft YaHei";
  ctx.fillText(spec.termLabel.slice(0, 4), anchor.x - 18, anchor.y + 12);

  drawCanvasCard(ctx, rect.x, cardY, rect.width, rect.height, "rgba(255, 253, 245, 0.94)");
  ctx.strokeStyle = `${theme.accent}aa`;
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.roundRect(rect.x, cardY, rect.width, rect.height, 18);
  ctx.stroke();

  drawDungeonMechanicWorldGlyph(ctx, spec, rect.x + 16, cardY + 18, 70, motion);
  ctx.fillStyle = theme.accent;
  ctx.font = "900 10px Microsoft YaHei";
  ctx.fillText("可点", rect.x + 40, cardY + 101);

  ctx.fillStyle = theme.accent;
  ctx.font = "800 12px Microsoft YaHei";
  ctx.fillText(`${spec.title} · ${spec.statusLabel}`.slice(0, 24), rect.x + 100, cardY + 25);
  ctx.fillStyle = "#17231d";
  ctx.font = "800 16px Microsoft YaHei";
  ctx.fillText(`${spec.dungeonName}：${spec.headline}`.slice(0, 22), rect.x + 100, cardY + 51);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "12px Microsoft YaHei";
  ctx.fillText(spec.fieldRule.slice(0, 31), rect.x + 100, cardY + 72);

  ctx.fillStyle = theme.soft;
  ctx.beginPath();
  ctx.roundRect(rect.x + 100, cardY + 84, rect.width - 118, 22, 11);
  ctx.fill();
  ctx.fillStyle = "#8f5f3f";
  ctx.font = "800 10px Microsoft YaHei";
  ctx.fillText(`推荐 ${spec.recommendedSpiritText} · ${spec.solutionText}`.slice(0, 34), rect.x + 112, cardY + 99);

  ctx.fillStyle = "rgba(236, 248, 243, 0.82)";
  ctx.strokeStyle = `${theme.accent}33`;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.roundRect(rect.x + 100, cardY + 110, rect.width - 118, 20, 10);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = "#286f58";
  ctx.font = "800 9px Microsoft YaHei";
  ctx.fillText(`失败保底：${spec.safeguardText}`.slice(0, 38), rect.x + 112, cardY + 123);

  ctx.fillStyle = "rgba(255, 248, 232, 0.82)";
  ctx.beginPath();
  ctx.roundRect(rect.x + 18, cardY + rect.height - 22, rect.width - 36, 16, 8);
  ctx.fill();
  ctx.fillStyle = "#5d6f65";
  ctx.font = "700 9px Microsoft YaHei";
  ctx.fillText(`奖励：${spec.mainRewardText} · 余波：${spec.externalChange}`.slice(0, 46), rect.x + 30, cardY + rect.height - 10);

  ctx.restore();
  return true;
}

function drawDungeonMechanicWorldRoute(ctx, spec = dungeonMechanicWorldRouteSpec()) {
  if (!spec?.rect) return false;
  const { rect, theme } = spec;
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const pulse = settings.reducedMotion ? 0 : Math.sin(motion * 1.8) * 2;
  const active = dungeonMechanicWorldRouteFocus?.day === state.day
    && dungeonMechanicWorldRouteFocus?.key === spec.key;
  const cardY = rect.y + pulse;
  ctx.save();

  drawCanvasCard(ctx, rect.x, cardY, rect.width, rect.height, "rgba(255, 253, 245, 0.9)");
  ctx.strokeStyle = active ? `${theme.accent}ee` : `${theme.accent}77`;
  ctx.lineWidth = active ? 2.8 : 1.7;
  ctx.beginPath();
  ctx.roundRect(rect.x + 1.5, cardY + 1.5, rect.width - 3, rect.height - 3, 18);
  ctx.stroke();

  ctx.fillStyle = theme.soft;
  ctx.beginPath();
  ctx.roundRect(rect.x + 14, cardY + 14, 70, 70, 18);
  ctx.fill();
  drawDungeonMechanicWorldGlyph(ctx, spec, rect.x + 22, cardY + 22, 54, motion);
  ctx.fillStyle = theme.accent;
  ctx.font = "900 9px Microsoft YaHei";
  ctx.fillText("路线图", rect.x + 30, cardY + 87);

  ctx.fillStyle = theme.accent;
  ctx.font = "900 11px Microsoft YaHei";
  ctx.fillText(`${spec.title} · ${spec.termLabel}`.slice(0, 22), rect.x + 98, cardY + 21);
  ctx.fillStyle = "#17231d";
  ctx.font = "900 14px Microsoft YaHei";
  ctx.fillText(`${spec.dungeonName}：${spec.headline}`.slice(0, 31), rect.x + 98, cardY + 43);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "10px Microsoft YaHei";
  ctx.fillText(`${spec.supportText} · 保底 ${spec.safeguardText}`.slice(0, 49), rect.x + 98, cardY + 60);

  const startX = rect.x + 106;
  const laneY = cardY + 76;
  const gap = 61;
  ctx.strokeStyle = `${theme.accent}44`;
  ctx.lineWidth = 2.2;
  ctx.beginPath();
  ctx.moveTo(startX + 8, laneY);
  ctx.lineTo(startX + gap * 4 + 8, laneY);
  ctx.stroke();

  spec.stages.slice(0, 5).forEach((stage, index) => {
    const dotX = startX + index * gap;
    const isSolution = stage.key === "spirit_solution";
    const isSafe = stage.key === "failure_safeguard";
    const isReward = stage.key === "resolution";
    const strong = isSolution && spec.supportCount > 0;
    const fill = strong
      ? `${theme.accent}dd`
      : isSafe
        ? "rgba(202, 235, 210, 0.92)"
        : isReward
          ? "rgba(246, 240, 182, 0.92)"
          : "rgba(255, 253, 245, 0.94)";
    ctx.fillStyle = fill;
    ctx.strokeStyle = strong ? theme.accent : isSafe ? "#286f58" : isReward ? "#b47d2f" : `${theme.accent}88`;
    ctx.lineWidth = strong || (active && index === 2) ? 2.6 : 1.6;
    ctx.beginPath();
    ctx.arc(dotX + 8, laneY, strong ? 10 : 8.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = strong ? "#fffdf5" : isSafe ? "#286f58" : isReward ? "#8f5f3f" : theme.accent;
    ctx.font = "900 8px Microsoft YaHei";
    ctx.fillText(String(index + 1), dotX + 5, laneY + 3);
    ctx.fillStyle = strong ? theme.accent : "#5d6f65";
    ctx.font = "800 8px Microsoft YaHei";
    ctx.fillText(stage.label.slice(0, 3), dotX - 1, laneY + 21);
  });

  if (!settings.reducedMotion) {
    for (let i = 0; i < 5; i += 1) {
      const sparkX = startX + i * gap + 8 + Math.sin(motion * 1.6 + i) * 2;
      const sparkY = laneY - 17 + Math.cos(motion * 1.4 + i) * 3;
      ctx.fillStyle = i % 2 ? "rgba(255, 253, 245, 0.84)" : `${theme.accent}88`;
      ctx.beginPath();
      ctx.arc(sparkX, sparkY, 2.2, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  ctx.fillStyle = "rgba(255, 248, 232, 0.78)";
  ctx.beginPath();
  ctx.roundRect(rect.x + rect.width - 98, cardY + 14, 80, 20, 10);
  ctx.fill();
  ctx.fillStyle = "#8f5f3f";
  ctx.font = "900 9px Microsoft YaHei";
  ctx.fillText("只定位不进境", rect.x + rect.width - 88, cardY + 28);

  ctx.restore();
  return true;
}

function drawDungeonEntranceSilhouetteWorld(ctx, spec = dungeonEntranceSilhouetteSpec()) {
  if (!spec?.rect || !spec.nodes.length) return false;
  const { rect, anchor, theme } = spec;
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const pulse = settings.reducedMotion ? 0 : Math.sin(motion * 1.9) * 2.4;
  const activeNodeKey = dungeonEntranceSilhouetteWorldFocus?.day === state.day
    && dungeonEntranceSilhouetteWorldFocus?.key === spec.key
    ? dungeonEntranceSilhouetteWorldFocus.nodeKey
    : "";
  ctx.save();

  if (anchor) {
    ctx.strokeStyle = `${theme.accent}55`;
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 8]);
    ctx.lineDashOffset = settings.reducedMotion ? 0 : -motion * 7;
    ctx.beginPath();
    ctx.moveTo(anchor.x, anchor.y + 4);
    ctx.quadraticCurveTo(rect.x + rect.width * 0.72, rect.y + rect.height + 22, rect.x + rect.width - 28, rect.y + rect.height - 12);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  drawCanvasCard(ctx, rect.x, rect.y + pulse, rect.width, rect.height, "rgba(255, 253, 245, 0.91)");
  ctx.strokeStyle = activeNodeKey ? `${theme.accent}ee` : `${theme.accent}77`;
  ctx.lineWidth = activeNodeKey ? 2.5 : 1.6;
  ctx.beginPath();
  ctx.roundRect(rect.x + 1, rect.y + pulse + 1, rect.width - 2, rect.height - 2, 20);
  ctx.stroke();

  ctx.fillStyle = "rgba(23, 35, 29, 0.08)";
  ctx.beginPath();
  ctx.ellipse(rect.x + 54, rect.y + 35 + pulse, 44, 17, -0.12, 0, Math.PI * 2);
  ctx.fill();
  drawDungeonMechanicWorldGlyph(ctx, spec, rect.x + 24, rect.y + 15 + pulse, 42, motion);
  ctx.fillStyle = theme.accent;
  ctx.font = "900 9px Microsoft YaHei";
  ctx.fillText("入口辨识", rect.x + 24, rect.y + 58 + pulse);

  ctx.fillStyle = "#17231d";
  ctx.font = "900 14px Microsoft YaHei";
  ctx.fillText(spec.title, rect.x + 82, rect.y + 24 + pulse);
  ctx.fillStyle = "#8f5f3f";
  ctx.font = "800 10px Microsoft YaHei";
  ctx.fillText(`${spec.subtitle} · ${spec.note}`.slice(0, 38), rect.x + 82, rect.y + 43 + pulse);

  spec.nodes.forEach((node, index) => {
    const nodeRect = node.rect;
    const active = activeNodeKey === node.key;
    const isRule = node.key === "field_rule";
    const isSolution = node.key === "spirit_solution";
    const fill = isRule
      ? "rgba(236, 248, 243, 0.9)"
      : isSolution
        ? theme.soft
        : "rgba(255, 248, 232, 0.92)";
    const accent = isRule ? "#286f58" : isSolution ? theme.accent : "#b47d2f";
    const bob = active ? pulse / 1.7 : Math.sin(motion * 1.3 + index) * 0.8;
    ctx.fillStyle = fill;
    ctx.beginPath();
    ctx.roundRect(nodeRect.x, nodeRect.y + bob, nodeRect.width, nodeRect.height, 15);
    ctx.fill();
    ctx.strokeStyle = active ? `${accent}ee` : `${accent}77`;
    ctx.lineWidth = active ? 2.4 : 1.4;
    ctx.stroke();

    ctx.fillStyle = active ? accent : `${accent}dd`;
    ctx.beginPath();
    ctx.arc(nodeRect.x + 21, nodeRect.y + 20 + bob, active ? 14 : 12, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#fffdf5";
    ctx.font = "900 14px Microsoft YaHei";
    ctx.fillText(node.glyph, nodeRect.x + 14, nodeRect.y + 25 + bob);

    ctx.fillStyle = "#17231d";
    ctx.font = "900 10px Microsoft YaHei";
    ctx.fillText(node.label, nodeRect.x + 40, nodeRect.y + 18 + bob);
    ctx.fillStyle = active ? accent : "#5d6f65";
    ctx.font = "800 8px Microsoft YaHei";
    ctx.fillText(node.title.slice(0, 8), nodeRect.x + 40, nodeRect.y + 33 + bob);
  });

  const focusNode = spec.nodes.find((node) => node.key === activeNodeKey) || spec.nodes[0];
  if (focusNode) {
    ctx.fillStyle = "rgba(236, 248, 243, 0.76)";
    ctx.beginPath();
    ctx.roundRect(rect.x + 18, rect.y + rect.height - 19 + pulse, rect.width - 36, 14, 7);
    ctx.fill();
    ctx.fillStyle = "#286f58";
    ctx.font = "800 8px Microsoft YaHei";
    ctx.fillText(`${focusNode.label}：${focusNode.text}`.slice(0, 51), rect.x + 30, rect.y + rect.height - 9 + pulse);
  }

  ctx.restore();
  return true;
}

function dungeonEntranceFieldPreviewSafetyText() {
  return "只解释入口场规并定位秘境面板，不会自动进入秘境、探索、顺应节气、挑战 Boss、领取奖励或消耗资源";
}

function dungeonEntranceFieldPreviewRect(width = 960, height = 640, silhouette = dungeonEntranceSilhouetteSpec(width, height)) {
  const rectWidth = 348;
  const rectHeight = 132;
  const anchor = silhouette?.anchor || { x: 808, y: 236 };
  const base = silhouette?.rect || { x: 520, y: 238, width: 352, height: 126 };
  const slots = [
    { x: base.x - 28, y: base.y + base.height + 14, width: rectWidth, height: rectHeight },
    { x: base.x + base.width - rectWidth + 22, y: base.y - rectHeight - 14, width: rectWidth, height: rectHeight },
    { x: anchor.x - rectWidth - 42, y: anchor.y - 36, width: rectWidth, height: rectHeight },
    { x: Math.max(24, width - rectWidth - 28), y: Math.max(70, height - rectHeight - 36), width: rectWidth, height: rectHeight },
  ].map((slot) => ({
    ...slot,
    x: Math.max(24, Math.min(width - rectWidth - 24, slot.x)),
    y: Math.max(62, Math.min(height - rectHeight - 26, slot.y)),
  }));
  const blockers = [
    silhouette?.rect,
    dungeonMechanicWorldPreviewSpec()?.rect,
    dungeonMechanicWorldRouteSpec()?.rect,
    dungeonSolarAtlasWorldSpec(width, height)?.rect,
  ].filter(Boolean);
  const overlap = (a, b) => a.x < b.x + b.width && a.x + a.width > b.x && a.y < b.y + b.height && a.y + a.height > b.y;
  return slots.find((slot) => !blockers.some((blocker) => overlap(slot, blocker))) || slots[0];
}

function dungeonEntranceFieldPreviewWorldSpec(width = 960, height = 640, silhouette = dungeonEntranceSilhouetteSpec(width, height)) {
  if (!silhouette) return null;
  const dungeon = data.dungeonsById.get(silhouette.dungeonId) || availableDungeons().find((entry) => entry.area_id === silhouette.dungeonId) || null;
  const mechanic = data.dungeonSolarMechanics.find((entry) => entry.dungeon_id === silhouette.mechanicId) || currentDungeonMechanic(dungeon);
  if (!dungeon || !mechanic) return null;
  const solution = dungeonSpiritSolutionSpec(null, mechanic, dungeon);
  const activeSolution = solution?.active && solution.primary ? solution.primary : null;
  const recommendedSpirits = splitTags(mechanic.recommended_spirits || "");
  const spiritText = activeSolution
    ? `${activeSolution.spiritName}接住${activeSolution.ability}`
    : `推荐 ${recommendedSpirits.join(" / ") || "随行精怪"}`;
  const rect = dungeonEntranceFieldPreviewRect(width, height, silhouette);
  const theme = silhouette.theme || dungeonMechanicTheme(dungeonMechanicTone(mechanic));
  const acts = [
    {
      key: "field",
      badge: "规",
      title: "场规先动",
      detail: mechanic.field_rule || silhouette.fieldRule || "节气先改变秘境走法",
      accent: "#286f58",
    },
    {
      key: "spirit",
      badge: "精",
      title: "精怪应手",
      detail: activeSolution ? activeSolution.shortImpact || spiritText : spiritText,
      accent: theme.accent,
    },
    {
      key: "return",
      badge: "回",
      title: "带回洞天",
      detail: mechanic.external_change || silhouette.externalChange || "通关后改变洞天生态",
      accent: "#b47d2f",
    },
  ];
  return {
    id: "dungeon_entrance_field_preview",
    key: `${state.day}:${silhouette.dungeonId}:${silhouette.mechanicId}:${solution?.solutionCount || 0}:${mechanic.external_change || ""}`,
    day: state.day,
    title: "秘境入口场规预演 · 可点",
    headline: `${silhouette.dungeonName} 入境前三幕`,
    dungeonId: silhouette.dungeonId,
    dungeonName: silhouette.dungeonName,
    mechanicId: silhouette.mechanicId,
    termLabel: silhouette.termLabel,
    fieldRule: mechanic.field_rule || silhouette.fieldRule,
    puzzleCore: mechanic.puzzle_core || "先读懂场规再入境",
    spiritText,
    rewardText: mechanic.main_reward || "节气材料/稀有线索",
    externalChange: mechanic.external_change || silhouette.externalChange || "洞天生态变化",
    safeNote: dungeonEntranceFieldPreviewSafetyText(),
    rect,
    anchor: silhouette.anchor,
    theme,
    tone: silhouette.tone || dungeonMechanicTone(mechanic),
    acts,
  };
}

function dungeonEntranceFieldPreviewWorldAtCanvasPoint(px, py) {
  const spec = dungeonEntranceFieldPreviewWorldSpec(refs.world?.width || 960, refs.world?.height || 640);
  if (!spec?.rect) return null;
  const { rect } = spec;
  return px >= rect.x && px <= rect.x + rect.width && py >= rect.y && py <= rect.y + rect.height
    ? spec
    : null;
}

function focusDungeonEntranceFieldPreviewWorldFromCanvas(spec = dungeonEntranceFieldPreviewWorldSpec()) {
  if (!spec?.dungeonId) return false;
  dungeonEntranceFieldPreviewWorldFocus = {
    day: state.day,
    key: spec.key,
    dungeonId: spec.dungeonId,
    mechanicId: spec.mechanicId,
  };
  queueStoryCompassFocusTarget({
    selector: `[data-dungeon-card-id="${selectorDataValue(spec.dungeonId)}"]`,
    fallbackSelector: "#dungeonPanel",
    label: `点选秘境入口场规预演：${spec.dungeonName}`,
    log: `${spec.dungeonName} 入境前三幕：场规「${spec.fieldRule}」 -> 精怪「${spec.spiritText}」 -> 带回「${spec.externalChange}」。核心机关：${spec.puzzleCore}；奖励焦点：${spec.rewardText}。${spec.safeNote}。`,
    panelGroup: "systems",
    missingTitle: "点选秘境入口场规预演",
    missingLog: "秘境入口场规预演已经点到，但秘境面板暂时不可见。先打开系统深挖里的秘境探索面板查看入口规则；不会自动进入秘境、探索、挑战 Boss 或消耗资源。",
  });
  return true;
}

function drawDungeonEntranceFieldPreviewWorld(ctx, spec = dungeonEntranceFieldPreviewWorldSpec(ctx.canvas.width, ctx.canvas.height), motion = performance.now() / 1000) {
  if (!spec?.rect) return false;
  const { rect, anchor, theme } = spec;
  const active = dungeonEntranceFieldPreviewWorldFocus?.day === state.day
    && dungeonEntranceFieldPreviewWorldFocus?.key === spec.key;
  const pulse = settings.reducedMotion ? 0 : Math.sin(motion * 1.65) * 2.4;
  const cardY = rect.y + pulse;

  ctx.save();
  if (anchor) {
    ctx.strokeStyle = active ? `${theme.accent}cc` : `${theme.accent}55`;
    ctx.lineWidth = active ? 3 : 1.8;
    ctx.setLineDash([6, 8]);
    ctx.lineDashOffset = settings.reducedMotion ? 0 : -motion * 10;
    ctx.beginPath();
    ctx.moveTo(anchor.x, anchor.y + 8);
    ctx.quadraticCurveTo(rect.x + rect.width - 42, cardY - 26, rect.x + rect.width - 30, cardY + 24);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  drawCanvasCard(ctx, rect.x, cardY, rect.width, rect.height, "rgba(255, 253, 245, 0.94)");
  ctx.strokeStyle = active ? `${theme.accent}ee` : `${theme.accent}88`;
  ctx.lineWidth = active ? 2.8 : 1.7;
  ctx.beginPath();
  ctx.roundRect(rect.x + 1.5, cardY + 1.5, rect.width - 3, rect.height - 3, 18);
  ctx.stroke();

  ctx.fillStyle = theme.soft;
  ctx.beginPath();
  ctx.roundRect(rect.x + 14, cardY + 14, 58, 58, 16);
  ctx.fill();
  drawDungeonMechanicWorldGlyph(ctx, spec, rect.x + 21, cardY + 21, 44, motion);
  ctx.fillStyle = theme.accent;
  ctx.font = "900 8px Microsoft YaHei";
  ctx.fillText("三幕", rect.x + 31, cardY + 79);

  ctx.fillStyle = theme.accent;
  ctx.font = "900 11px Microsoft YaHei";
  ctx.fillText(spec.title.slice(0, 18), rect.x + 86, cardY + 24);
  ctx.fillStyle = "#17231d";
  ctx.font = "900 15px Microsoft YaHei";
  ctx.fillText(spec.headline.slice(0, 20), rect.x + 86, cardY + 47);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "10px Microsoft YaHei";
  ctx.fillText(`${spec.termLabel} · ${spec.puzzleCore}`.slice(0, 38), rect.x + 86, cardY + 64);

  const laneY = cardY + 88;
  ctx.strokeStyle = `${theme.accent}40`;
  ctx.lineWidth = 2.2;
  ctx.beginPath();
  ctx.moveTo(rect.x + 38, laneY);
  ctx.lineTo(rect.x + rect.width - 38, laneY);
  ctx.stroke();
  spec.acts.forEach((act, index) => {
    const actX = rect.x + 42 + index * 112;
    const strong = active && index === 1;
    ctx.fillStyle = strong ? `${act.accent}dd` : "rgba(255, 253, 245, 0.92)";
    ctx.strokeStyle = `${act.accent}88`;
    ctx.lineWidth = strong ? 2.6 : 1.5;
    ctx.beginPath();
    ctx.arc(actX, laneY, strong ? 12 : 10, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = strong ? "#fffdf5" : act.accent;
    ctx.font = "900 8px Microsoft YaHei";
    ctx.fillText(act.badge, actX - 4, laneY + 3);

    ctx.fillStyle = act.accent;
    ctx.font = "900 8px Microsoft YaHei";
    ctx.fillText(act.title.slice(0, 5), actX - 22, laneY + 24);
    ctx.fillStyle = "#5d6f65";
    ctx.font = "800 8px Microsoft YaHei";
    ctx.fillText(act.detail.slice(0, 10), actX - 32, laneY + 39);
  });

  ctx.fillStyle = "rgba(236, 248, 243, 0.74)";
  ctx.beginPath();
  ctx.roundRect(rect.x + 18, cardY + rect.height - 18, rect.width - 36, 14, 7);
  ctx.fill();
  ctx.fillStyle = "#286f58";
  ctx.font = "900 8px Microsoft YaHei";
  ctx.fillText(spec.safeNote.slice(0, 48), rect.x + 26, cardY + rect.height - 8);
  ctx.restore();
  return true;
}

function drawDungeonSolarAtlasWorld(ctx, spec = dungeonSolarAtlasWorldSpec()) {
  if (!spec?.rect || !spec.nodes.length) return false;
  const { rect } = spec;
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const activeMechanicId = dungeonSolarAtlasWorldFocus?.day === state.day && dungeonSolarAtlasWorldFocus?.key === spec.key
    ? dungeonSolarAtlasWorldFocus.mechanicId
    : "";
  const preferred = spec.preferred || spec.nodes[0];
  const frameTheme = preferred?.theme || dungeonMechanicTheme("mist");
  const pulse = settings.reducedMotion ? 0 : Math.sin(motion * 1.7) * 2.5;
  ctx.save();

  drawCanvasCard(ctx, rect.x, rect.y, rect.width, rect.height, "rgba(255, 253, 245, 0.9)");
  ctx.strokeStyle = `${frameTheme.accent}88`;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.roundRect(rect.x + 1, rect.y + 1, rect.width - 2, rect.height - 2, 20);
  ctx.stroke();

  ctx.fillStyle = "rgba(23, 35, 29, 0.08)";
  ctx.beginPath();
  ctx.ellipse(rect.x + rect.width - 62, rect.y + 35, 78 + pulse, 23, -0.16, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = `${frameTheme.accent}55`;
  ctx.lineWidth = 2;
  ctx.setLineDash([6, 9]);
  ctx.lineDashOffset = settings.reducedMotion ? 0 : -motion * 8;
  ctx.beginPath();
  ctx.ellipse(rect.x + rect.width - 62, rect.y + 35, 68, 18, -0.16, 0, Math.PI * 2);
  ctx.stroke();
  ctx.setLineDash([]);

  ctx.fillStyle = "#17231d";
  ctx.font = "900 14px Microsoft YaHei";
  ctx.fillText(spec.title, rect.x + 18, rect.y + 24);
  ctx.fillStyle = "#8f5f3f";
  ctx.font = "800 10px Microsoft YaHei";
  ctx.fillText(`${spec.subtitle} · 已开 ${spec.availableCount}/8 · 已通 ${spec.clearedCount}/8`, rect.x + 18, rect.y + 42);
  ctx.fillStyle = "rgba(255, 248, 232, 0.82)";
  ctx.beginPath();
  ctx.roundRect(rect.x + rect.width - 130, rect.y + 14, 112, 22, 11);
  ctx.fill();
  ctx.fillStyle = "#8f5f3f";
  ctx.font = "900 9px Microsoft YaHei";
  ctx.fillText("只定位不进境", rect.x + rect.width - 116, rect.y + 28);

  spec.nodes.forEach((node) => {
    const nodeRect = node.rect;
    const active = activeMechanicId === node.mechanicId;
    const strong = active || node.termMatch;
    const theme = node.theme;
    ctx.fillStyle = node.available ? theme.soft : "rgba(255, 253, 245, 0.58)";
    ctx.beginPath();
    ctx.roundRect(nodeRect.x, nodeRect.y + (strong ? pulse / 3 : 0), nodeRect.width, nodeRect.height, 14);
    ctx.fill();
    ctx.strokeStyle = active
      ? `${theme.accent}ee`
      : node.termMatch
        ? `${theme.accent}bb`
        : node.cleared
          ? "rgba(40, 111, 88, 0.55)"
          : "rgba(93, 111, 101, 0.22)";
    ctx.lineWidth = active ? 2.6 : node.termMatch ? 2.1 : 1.3;
    ctx.stroke();

    drawDungeonMechanicWorldGlyph(ctx, node, nodeRect.x + 6, nodeRect.y + 7, 30, motion);
    ctx.fillStyle = node.available ? "#17231d" : "#8f7b5d";
    ctx.font = "900 10px Microsoft YaHei";
    ctx.fillText(node.termLabel.slice(0, 3), nodeRect.x + 42, nodeRect.y + 17);
    ctx.fillStyle = theme.accent;
    ctx.font = "900 9px Microsoft YaHei";
    ctx.fillText(node.keyword.slice(0, 5), nodeRect.x + 42, nodeRect.y + 31);
    ctx.fillStyle = node.termMatch ? "#b47d2f" : node.cleared ? "#286f58" : node.available ? "#5d6f65" : "#8f7b5d";
    ctx.font = "800 8px Microsoft YaHei";
    ctx.fillText(node.statusLabel, nodeRect.x + nodeRect.width - 23, nodeRect.y + nodeRect.height - 7);
  });

  const focus = activeMechanicId
    ? spec.nodes.find((node) => node.mechanicId === activeMechanicId) || preferred
    : preferred;
  if (focus) {
    ctx.fillStyle = "rgba(236, 248, 243, 0.76)";
    ctx.beginPath();
    ctx.roundRect(rect.x + 18, rect.y + rect.height - 24, rect.width - 36, 16, 8);
    ctx.fill();
    ctx.fillStyle = "#286f58";
    ctx.font = "800 9px Microsoft YaHei";
    ctx.fillText(`场规关键词：${focus.keyword} · 推荐 ${focus.recommendedSpiritText} · 余波 ${focus.externalChange}`.slice(0, 58), rect.x + 30, rect.y + rect.height - 13);
  }

  ctx.restore();
  return true;
}

function dungeonMechanicHudSpec(run = state.dungeon, mechanic = currentDungeonMechanic(), dungeon = currentDungeonConfig()) {
  const mechanicState = syncDungeonMechanicState(run, mechanic, dungeon);
  if (!run || !mechanic || !mechanicState) return null;
  const status = dungeonMechanicStatus(run, mechanic, dungeon);
  const action = dungeonMechanicActionSpec(run, mechanic, dungeon);
  const support = dungeonMechanicSupportLevel(mechanic);
  const tone = dungeonMechanicTone(mechanic);
  const theme = dungeonMechanicTheme(tone);
  const term = data.solarTermsById.get(mechanic.solar_term) || data.solarTermsById.get(state.term);
  const hud = {
    tone,
    theme,
    title: status?.label || "节气机制",
    caption: localize(term?.term_name_key, mechanic.solar_term || state.term || "节气"),
    summary: status?.summary || mechanic.field_rule || "秘境灵气正在变化",
    detail: status?.detail || mechanic.field_rule || "",
    progressCurrent: 0,
    progressMax: 1,
    progressText: "当前节气机制正在运转。",
    nodes: [],
    tags: [],
    support,
    actionLabel: action?.label || "暂无主动应对",
    actionUsed: Boolean(action?.used),
    actionReady: Boolean(action && !action.used && !action.disabled),
  };
  const pushTag = (label, stateTag = "neutral") => {
    hud.tags.push({ label, state: stateTag });
  };

  switch (mechanic.dungeon_id) {
    case "dsm_001":
      hud.progressCurrent = mechanicState.pillarsLit;
      hud.progressMax = 3;
      hud.progressText = `已点亮 ${mechanicState.pillarsLit}/3 根雷木柱`;
      hud.nodes = ["一柱", "二柱", "三柱"].map((label, index) => ({
        label,
        active: index < mechanicState.pillarsLit,
        emphasis: index === mechanicState.pillarsLit && mechanicState.pillarsLit < 3,
      }));
      pushTag(mechanicState.resonanceTurn ? "共振将至" : "余震未稳", mechanicState.resonanceTurn ? "good" : "warn");
      break;
    case "dsm_002":
      hud.progressCurrent = mechanicState.sluicesAligned;
      hud.progressMax = 3;
      hud.progressText = `回渠闸口 ${mechanicState.sluicesAligned}/3 · 当前 ${["浅水", "平水", "丰水"][mechanicState.waterLevel] || "平水"}`;
      hud.nodes = ["浅", "平", "丰"].map((label, index) => ({
        label,
        active: index < mechanicState.sluicesAligned,
        emphasis: index === mechanicState.waterLevel,
      }));
      pushTag(`${["浅水", "平水", "丰水"][mechanicState.waterLevel] || "平水"}推进`, mechanicState.waterLevel === 1 ? "good" : "neutral");
      break;
    case "dsm_003":
      hud.progressCurrent = mechanicState.listened;
      hud.progressMax = 3;
      hud.progressText = `已听准 ${mechanicState.listened}/3 段虫鸣节拍`;
      hud.nodes = ["前拍", "正拍", "回拍"].map((label, index) => ({
        label,
        active: index < mechanicState.listened,
        emphasis: index === mechanicState.cadence,
      }));
      pushTag(`${["前拍", "正拍", "回拍"][mechanicState.cadence] || "正拍"}正在回响`, mechanicState.cadence === 1 ? "good" : "neutral");
      break;
    case "dsm_004":
      hud.progressCurrent = mechanicState.overflow;
      hud.progressMax = 5;
      hud.progressText = `谷底满溢 ${mechanicState.overflow}/5 · 掉落提升 ${Math.round(mechanicState.overflow * 12)}%`;
      hud.nodes = Array.from({ length: 5 }, (_, index) => ({
        label: `${index + 1}`,
        active: index < mechanicState.overflow,
        state: index >= 3 ? "warn" : "neutral",
      }));
      pushTag(mechanicState.overflow >= 4 ? "灵压躁动" : "还能压住", mechanicState.overflow >= 4 ? "warn" : "good");
      break;
    case "dsm_005":
      hud.progressCurrent = mechanicState.verifiedPaths;
      hud.progressMax = 3;
      hud.progressText = `已验明 ${mechanicState.verifiedPaths}/3 段倒影真路`;
      hud.nodes = ["一镜", "二镜", "三镜"].map((label, index) => ({
        label,
        active: index < mechanicState.verifiedPaths,
        emphasis: index === mechanicState.verifiedPaths && mechanicState.verifiedPaths < 3,
      }));
      pushTag(mechanicState.verifiedPaths > 0 ? "真路渐清" : "镜面扰路", mechanicState.verifiedPaths > 0 ? "good" : "warn");
      break;
    case "dsm_006":
      hud.progressCurrent = mechanicState.coldStacks;
      hud.progressMax = 4;
      hud.progressText = `霜寒压身 ${mechanicState.coldStacks}/4`;
      hud.nodes = ["初寒", "凝霜", "透骨", "封脉"].map((label, index) => ({
        label,
        active: index < mechanicState.coldStacks,
        state: "warn",
      }));
      pushTag(mechanicState.coldStacks <= 1 ? "保暖尚稳" : "寒气上身", mechanicState.coldStacks <= 1 ? "good" : "warn");
      break;
    case "dsm_007":
      hud.progressCurrent = mechanicState.routeMarks;
      hud.progressMax = 3;
      hud.progressText = `旧路标记 ${mechanicState.routeMarks}/3`;
      hud.nodes = ["路印", "叶痕", "旧阶"].map((label, index) => ({
        label,
        active: index < mechanicState.routeMarks,
      }));
      pushTag(mechanicState.windShift ? "逆风覆路" : "顺风露路", mechanicState.windShift ? "warn" : "good");
      break;
    case "dsm_008":
      hud.progressCurrent = mechanicState.lanternChain;
      hud.progressMax = 7;
      hud.progressText = `长灯已续 ${mechanicState.lanternChain}/7`;
      hud.nodes = Array.from({ length: 7 }, (_, index) => ({
        label: "灯",
        active: index < mechanicState.lanternChain,
        emphasis: index === mechanicState.lanternChain && mechanicState.lanternChain < 7,
      }));
      pushTag(mechanicState.lanternChain >= 4 ? "影路渐成" : "灯火未稳", mechanicState.lanternChain >= 4 ? "good" : "neutral");
      break;
    default:
      pushTag("机制运转中", "neutral");
      break;
  }

  pushTag(support > 0 ? `解法共鸣 +${support}` : "未形成共鸣", support >= 2 ? "good" : support > 0 ? "neutral" : "warn");
  if (action) pushTag(action.used ? "本层已顺应" : `可用 ${action.label}`, action.used ? "done" : action.disabled ? "warn" : "good");
  pushTag(run.bossReady ? `Boss P${run.bossPhase || 1}` : `层数 ${run.floor}/${run.maxFloor}`, run.bossReady ? "warn" : "neutral");
  hud.progressPercent = Math.max(0, Math.min(100, Math.round((hud.progressCurrent / Math.max(1, hud.progressMax)) * 100)));
  return hud;
}

function dungeonMechanicHudMarkup(hud = dungeonMechanicHudSpec()) {
  if (!hud) return "";
  const nodes = hud.nodes
    .map((node) => `<span class="dungeon-mechanic-node ${node.active ? "active" : ""} ${node.emphasis ? "emphasis" : ""} ${node.state || ""}">${node.label}</span>`)
    .join("");
  const tags = hud.tags
    .map((tag) => `<span class="dungeon-mechanic-tag ${tag.state || "neutral"}">${tag.label}</span>`)
    .join("");
  return `
    <div class="dungeon-mechanic-card" data-tone="${hud.tone}">
      <div class="dungeon-mechanic-head">
        <strong>${hud.title}</strong>
        <em>${hud.caption}</em>
      </div>
      <span class="dungeon-mechanic-summary">${hud.summary}</span>
      <div class="dungeon-mechanic-meter"><span style="width:${hud.progressPercent}%"></span></div>
      <div class="dungeon-mechanic-foot">
        <small>${hud.progressText}</small>
        <small>${hud.actionUsed ? "本层已顺应" : hud.actionReady ? "仍可主动应对" : "当前无需额外动作"}</small>
      </div>
      ${nodes ? `<div class="dungeon-mechanic-nodes">${nodes}</div>` : ""}
      ${tags ? `<div class="dungeon-mechanic-tags">${tags}</div>` : ""}
      <small class="dungeon-mechanic-note">${hud.detail}</small>
    </div>
  `;
}

function dungeonMechanicEffects(run = state.dungeon, mechanic = currentDungeonMechanic(), dungeon = currentDungeonConfig(), phase = "explore") {
  const mechanicState = syncDungeonMechanicState(run, mechanic, dungeon);
  const support = dungeonMechanicSupportLevel(mechanic);
  const effects = {
    enemyPowerDown: 0,
    damageUp: 0,
    damageDown: 0,
    bossGuard: 0,
    strikeBonus: 0,
    lootMultiplier: 1,
  };
  if (!mechanicState || !mechanic) return effects;
  const runtimeEffects = dungeonRuntime()?.dungeonMechanicEffects({
    mechanicId: mechanic.dungeon_id,
    mechanicState,
    support,
    phase,
  });
  if (runtimeEffects) return runtimeEffects;
  switch (mechanic.dungeon_id) {
    case "dsm_001":
      if (mechanicState.resonanceTurn) {
        effects.enemyPowerDown += 2 + support;
        if (mechanicState.pillarsLit >= 2) effects.strikeBonus += 16;
      } else {
        effects.damageUp += Math.max(1, 2 - support);
      }
      if (mechanicState.pillarsLit >= 3) effects.bossGuard += 3 + Math.min(2, support);
      break;
    case "dsm_002":
      if (mechanicState.waterLevel === 0) {
        effects.damageUp += Math.max(0, 1 - Math.min(1, support));
        effects.enemyPowerDown += support > 0 ? 1 : 0;
      } else if (mechanicState.waterLevel === 1) {
        effects.enemyPowerDown += 2 + support;
        effects.strikeBonus += 10;
      } else {
        effects.damageUp += support >= 2 ? 0 : 2;
        effects.lootMultiplier += 0.12;
      }
      if (mechanicState.sluicesAligned >= 3) effects.bossGuard += 3;
      break;
    case "dsm_003":
      if (mechanicState.cadence === 1 || support >= 2) effects.enemyPowerDown += 2 + support;
      if (mechanicState.cadence === 2 && support === 0) effects.damageUp += 2;
      if (mechanicState.listened >= 3) {
        effects.bossGuard += 2;
        effects.lootMultiplier += 0.1;
      }
      break;
    case "dsm_004": {
      const effectiveOverflow = Math.max(0, mechanicState.overflow - Math.min(2, support));
      effects.damageUp += Math.max(0, effectiveOverflow - 1);
      effects.lootMultiplier += mechanicState.overflow * 0.12;
      effects.strikeBonus += mechanicState.overflow * 6;
      effects.enemyPowerDown += support;
      break;
    }
    case "dsm_005":
      effects.enemyPowerDown += mechanicState.verifiedPaths + support;
      if (support === 0 && mechanicState.verifiedPaths === 0) effects.damageUp += 1;
      if (mechanicState.verifiedPaths >= 2) {
        effects.bossGuard += 2;
        effects.strikeBonus += mechanicState.verifiedPaths * 8;
      }
      break;
    case "dsm_006": {
      const effectiveCold = Math.max(0, mechanicState.coldStacks - support);
      effects.damageUp += effectiveCold;
      effects.damageDown += support >= 2 ? 1 : 0;
      if (mechanicState.coldStacks <= 1 && support > 0) effects.strikeBonus += 12;
      break;
    }
    case "dsm_007":
      if (mechanicState.routeMarks > 0) effects.enemyPowerDown += mechanicState.routeMarks + Math.min(1, support);
      if (mechanicState.routeMarks === 0 && mechanicState.windShift === 1) effects.damageUp += 1;
      if (mechanicState.routeMarks >= 2) {
        effects.lootMultiplier += 0.1;
        effects.bossGuard += 2;
      }
      break;
    case "dsm_008":
      effects.enemyPowerDown += Math.min(4, Math.floor(mechanicState.lanternChain / 2)) + Math.min(2, support);
      if (mechanicState.lanternChain < 3) effects.damageUp += Math.max(0, 2 - support);
      if (mechanicState.lanternChain >= 4) effects.bossGuard += 2 + Math.floor(mechanicState.lanternChain / 3);
      effects.strikeBonus += mechanicState.lanternChain * 8;
      if (mechanicState.lanternChain >= 7) effects.lootMultiplier += 0.15;
      break;
    default:
      break;
  }
  if (phase === "boss" && mechanic.dungeon_id === "dsm_001" && mechanicState.pillarsLit < 3) effects.damageUp += 1;
  return effects;
}

function advanceDungeonMechanicState(run = state.dungeon, mechanic = currentDungeonMechanic(), dungeon = currentDungeonConfig(), phase = "explore") {
  const mechanicState = syncDungeonMechanicState(run, mechanic, dungeon);
  const support = dungeonMechanicSupportLevel(mechanic);
  if (!mechanicState || !mechanic) return "";
  const advancePlan = dungeonRuntime()?.dungeonMechanicAdvancePlan({
    mechanicId: mechanic.dungeon_id,
    mechanicState,
    support,
    phase,
    hiddenRevealPressureDown: run?.hiddenRevealPressureDown,
  });
  const nextMechanicState = advancePlan?.nextState || null;
  const advancedValue = (key, fallback) => nextMechanicState?.[key] ?? fallback;
  let note = mechanicState.lastNote || "";
  switch (mechanic.dungeon_id) {
    case "dsm_001":
      if (mechanicState.resonanceTurn) {
        mechanicState.pillarsLit = Number(advancedValue("pillarsLit", Math.min(3, mechanicState.pillarsLit + (support >= 2 ? 2 : 1))));
        note = `雷声共振，雷木柱已点亮 ${mechanicState.pillarsLit}/3。`;
      } else {
        note = support > 0 ? "余震还在抖，但你已经借着灵纹看清了下一处雷木柱。" : "余震没散，机关暂时还压着路。";
      }
      mechanicState.resonanceTurn = Boolean(advancedValue("resonanceTurn", !mechanicState.resonanceTurn));
      break;
    case "dsm_002":
      if (mechanicState.waterLevel === 1 || support >= 2) mechanicState.sluicesAligned = Number(advancedValue("sluicesAligned", Math.min(3, mechanicState.sluicesAligned + 1)));
      note = `${["浅水", "平水", "丰水"][mechanicState.waterLevel] || "平水"}阶段走完，回渠闸口已接上 ${mechanicState.sluicesAligned}/3。`;
      mechanicState.waterLevel = Number(advancedValue("waterLevel", (mechanicState.waterLevel + 1) % 3));
      break;
    case "dsm_003":
      if (mechanicState.cadence === 1 || support >= 2) mechanicState.listened = Number(advancedValue("listened", Math.min(3, mechanicState.listened + 1)));
      note = `${["前拍", "正拍", "回拍"][mechanicState.cadence] || "正拍"}虫鸣掠过，已听准 ${mechanicState.listened}/3 段林道节拍。`;
      mechanicState.cadence = Number(advancedValue("cadence", (mechanicState.cadence + 1) % 3));
      break;
    case "dsm_004":
      mechanicState.overflow = Number(advancedValue("overflow", Math.min(5, mechanicState.overflow + (support >= 2 ? 1 : 2))));
      note = `谷底满溢涨到 ${mechanicState.overflow}/5，收益在抬，但灵压也跟着更躁。`;
      break;
    case "dsm_005":
      if (support > 0) mechanicState.verifiedPaths = Number(advancedValue("verifiedPaths", Math.min(3, mechanicState.verifiedPaths + 1)));
      note = support > 0
        ? `倒影里又确认了一段真路，已验证 ${mechanicState.verifiedPaths}/3 段。`
        : "倒影晃得厉害，你只勉强记住了大致方向。";
      break;
    case "dsm_006":
      mechanicState.coldStacks = Number(advancedValue("coldStacks", Math.max(0, Math.min(4, mechanicState.coldStacks + (support >= 2 ? 0 : 1) - (phase === "boss" && support >= 3 ? 1 : 0)))));
      note = support > 0
        ? `保暖还撑得住，但霜气已经压到 ${mechanicState.coldStacks}/4 层。`
        : `寒气继续往骨头里钻，霜寒已累到 ${mechanicState.coldStacks}/4 层。`;
      break;
    case "dsm_007":
      if (support > 0) mechanicState.routeMarks = Number(advancedValue("routeMarks", Math.min(3, mechanicState.routeMarks + 1)));
      mechanicState.windShift = Number(advancedValue("windShift", mechanicState.windShift ? 0 : 1));
      note = `${mechanicState.windShift ? "逆风" : "顺风"}一翻，落叶又露出 ${mechanicState.routeMarks}/3 段旧路痕。`;
      break;
    case "dsm_008":
      mechanicState.lanternChain = Number(advancedValue("lanternChain", Math.min(7, mechanicState.lanternChain + 1 + (support >= 2 ? 1 : 0))));
      note = `长灯链已接到 ${mechanicState.lanternChain}/7 盏，${mechanicState.lanternChain >= 4 ? "影路开始成形。": "还得继续把灯火接稳。"} `;
      break;
    default:
      note = mechanicState.lastNote || mechanic?.field_rule || "秘境机制正在变化。";
      break;
  }
  mechanicState.lastNote = note;
  return note;
}

function useDungeonMechanicAction() {
  const run = state.dungeon;
  const dungeon = currentDungeonConfig();
  const mechanic = currentDungeonMechanic(dungeon);
  if (!run || run.finished || !dungeon || !mechanic) return addLog("不在秘境", "先进入一处秘境，再顺着当下节气做动作。");
  const spec = dungeonMechanicActionSpec(run, mechanic, dungeon);
  if (!spec) return addLog("节气未定", "当前秘境还没有可操作的节气机制。");
  if (spec.used) return addLog("本层已顺节气", spec.detail);
  if (!spendStamina(spec.cost || 5)) return;
  const mechanicState = syncDungeonMechanicState(run, mechanic, dungeon);
  const support = dungeonMechanicSupportLevel(mechanic);
  const solutionSpec = dungeonSpiritSolutionSpec(run, mechanic, dungeon);
  const solutionText = dungeonSpiritSolutionLogText(solutionSpec, "attune");
  const actionPlan = dungeonRuntime()?.dungeonMechanicActionPlan({
    mechanicId: mechanic.dungeon_id,
    mechanicState,
    support,
    currentHp: run.hp,
  });
  const nextActionState = actionPlan?.nextState || null;
  const actionValue = (key, fallback) => nextActionState?.[key] ?? fallback;
  let detail = spec.detail;
  switch (mechanic.dungeon_id) {
    case "dsm_001":
      mechanicState.resonanceTurn = Boolean(actionValue("resonanceTurn", true));
      mechanicState.pillarsLit = Number(actionValue("pillarsLit", Math.min(3, mechanicState.pillarsLit + (support >= 2 ? 2 : 1))));
      detail = `你踩着雷前那一瞬把雷木柱又点亮了一段，当前 ${mechanicState.pillarsLit}/3。`;
      break;
    case "dsm_002":
      mechanicState.waterLevel = Number(actionValue("waterLevel", 1));
      mechanicState.sluicesAligned = Number(actionValue("sluicesAligned", Math.min(3, mechanicState.sluicesAligned + 1 + (support >= 2 ? 1 : 0))));
      detail = `你先把闸口调回平水，又接上了 ${mechanicState.sluicesAligned}/3 段回渠。`;
      break;
    case "dsm_003":
      mechanicState.cadence = Number(actionValue("cadence", 1));
      mechanicState.listened = Number(actionValue("listened", Math.min(3, mechanicState.listened + 1 + (support >= 2 ? 1 : 0))));
      detail = `你停下听准虫鸣正拍，已认清 ${mechanicState.listened}/3 段林道节奏。`;
      break;
    case "dsm_004":
      mechanicState.overflow = Number(actionValue("overflow", Math.max(0, mechanicState.overflow - (support >= 2 ? 3 : 2))));
      run.hp = actionPlan?.hpAfter === null || actionPlan?.hpAfter === undefined ? Math.min(100, run.hp + 4 + support) : Number(actionPlan.hpAfter);
      detail = `你把最躁的满溢先压了下去，当前只剩 ${mechanicState.overflow}/5，自己也缓回一些气。`;
      break;
    case "dsm_005":
      mechanicState.verifiedPaths = Number(actionValue("verifiedPaths", Math.min(3, mechanicState.verifiedPaths + 1 + (support >= 2 ? 1 : 0))));
      detail = `你顺着倒影先验出一段真路，已确认 ${mechanicState.verifiedPaths}/3 段。`;
      break;
    case "dsm_006":
      mechanicState.coldStacks = Number(actionValue("coldStacks", Math.max(0, mechanicState.coldStacks - (support >= 2 ? 3 : 2))));
      run.hp = actionPlan?.hpAfter === null || actionPlan?.hpAfter === undefined ? Math.min(100, run.hp + 3) : Number(actionPlan.hpAfter);
      detail = `你把暖火先烧起来，霜寒压回 ${mechanicState.coldStacks}/4 层，呼吸也顺了点。`;
      break;
    case "dsm_007":
      mechanicState.routeMarks = Number(actionValue("routeMarks", Math.min(3, mechanicState.routeMarks + 1 + (support >= 2 ? 1 : 0))));
      mechanicState.windShift = Number(actionValue("windShift", 0));
      detail = `你先压住叶脉把旧路记牢了，当前已留住 ${mechanicState.routeMarks}/3 段路标。`;
      break;
    case "dsm_008":
      mechanicState.lanternChain = Number(actionValue("lanternChain", Math.min(7, mechanicState.lanternChain + 2 + (support >= 2 ? 1 : 0))));
      detail = `你把断开的灯火链又续亮了几盏，当前已接到 ${mechanicState.lanternChain}/7。`;
      break;
    default:
      detail = spec.detail;
      break;
  }
  mechanicState.lastNote = detail;
  run.lastMechanicActionKey = dungeonMechanicActionKey(run);
  run.mechanicActionUses = Math.max(0, Number(run.mechanicActionUses || 0)) + 1;
  run.hazards = dungeonHazards(mechanic, run, dungeon);
  run.skillLog.unshift(`顺应节气：${spec.label}${solutionText ? ` · ${solutionText}` : ""}，${detail}`);
  run.skillLog = run.skillLog.slice(0, 5);
  run.log.unshift(`你主动顺着${mechanic.solar_term}的节气规则出了一手：${solutionText ? `${solutionText}；` : ""}${detail}`);
  run.log = run.log.slice(0, 6);
  triggerDungeonFeedback("attune", {
    mechanic,
    label: spec.label,
    detail: solutionText ? `${solutionText}；${detail}` : detail,
    ...dungeonSpiritSolutionFeedbackFields(solutionSpec),
    duration: 1080,
  });
  addLog("顺应节气", `${dungeonName(dungeon)} 里，你没有硬顶着走，而是先顺着节气做了一手准备。${solutionText ? `${solutionText}。` : ""}${detail}`);
  recordDungeonDayEcho("attune", run, dungeon, mechanic, {
    rewardText: detail,
    nextStepText: `明天若再进 ${dungeonName(dungeon)}，先确认「${spec.label}」是否已经把本层机关压稳。`,
  });
  render();
}

function dungeonEnemies(dungeon) {
  const group = dungeon?.enemy_group_id || "";
  const prefix = [
    ["mine", "enemy_mine"],
    ["herb", "enemy_herb"],
    ["fire", "enemy_fire"],
    ["final", "enemy_final"],
  ].find(([key]) => group.includes(key))?.[1] || "enemy_mine";
  const enemies = data.enemies.filter((enemy) => enemy.enemy_id.startsWith(prefix));
  return enemies.length > 0 ? enemies : data.enemies;
}

function bossSkillsFor(bossId) {
  const runtime = dungeonRuntime();
  if (runtime) return runtime.bossSkillsFor(bossId);
  return [...(data.bossSkillsByBoss.get(bossId) || [])]
    .sort((a, b) => Number(a.phase_index) - Number(b.phase_index) || Number(a.order_in_phase) - Number(b.order_in_phase));
}

function bossPhaseForPercent(bossId, hpPercent = 1) {
  const runtime = dungeonRuntime();
  if (runtime) return runtime.bossPhaseForPercent(bossId, hpPercent);
  const boss = data.bossesById.get(bossId);
  const phaseCount = Math.max(1, Number(boss?.phase_count || 1));
  if (phaseCount >= 3) {
    if (hpPercent <= 0.35) return 3;
    if (hpPercent <= 0.7) return 2;
    return 1;
  }
  if (phaseCount >= 2 && hpPercent <= 0.5) return 2;
  return 1;
}

function bossSkillForTurn(bossId, turn = 0, hpPercent = 1) {
  const runtime = dungeonRuntime();
  if (runtime) return runtime.bossSkillForTurn({ bossId, turn, hpPercent });
  const phase = bossPhaseForPercent(bossId, hpPercent);
  const skills = bossSkillsFor(bossId).filter((skill) => Number(skill.phase_index) === phase);
  if (skills.length === 0) return null;
  return skills[turn % skills.length];
}

function bossSkillTargetLabel(skill) {
  const target = String(skill?.target_rule || "");
  if (target.includes("line") || target.includes("charge") || target.includes("projectile")) return "直线穿透";
  if (target.includes("arc") || target.includes("cone")) return "扇形压场";
  if (target.includes("random") || target.includes("meteor") || target.includes("rain") || target.includes("tile")) return "散点落区";
  if (target.includes("ring") || target.includes("pulse") || target.includes("self")) return "环形震荡";
  return target ? "近身压迫" : "压场不明";
}

function bossSkillEffectLabel(skill) {
  const effectType = String(skill?.effect_type || "");
  if (effectType === "shield") return `护盾 ${Number(skill?.effect_param_1 || 0)}`;
  if (effectType === "dot" || effectType === "apply_dot") return "持续侵蚀";
  if (effectType === "stun" || effectType === "root") return "强控压制";
  if (effectType === "summon" || effectType === "spawn_add") return "召援续战";
  if (effectType === "drain") return "吸取续战";
  if (effectType === "execute") return "高危点名";
  if (effectType === "meteor" || effectType === "field_corrupt" || effectType === "spawn_hazard") return "场地压迫";
  if (effectType === "speed_up") return "狂化加速";
  if (effectType === "knockback") return "震退冲散";
  const pressure = skillImpact(skill);
  return pressure >= 10 ? "高压重击" : pressure >= 6 ? "中压攻势" : "试探前摇";
}

function bossSkillCounterMove(skill) {
  const target = String(skill?.target_rule || "");
  const effect = String(skill?.effect_type || "");
  if (effect === "execute" || target.includes("single_target_channel")) return "被点名时立刻保命，留一次恢复或精怪护场。";
  if (target.includes("line") || target.includes("charge") || target.includes("projectile")) return "横移离开直线，不要沿着轨迹后退。";
  if (target.includes("back_arc")) return "离开 Boss 身后扇区，等尾扫落完再贴近。";
  if (target.includes("arc") || target.includes("cone")) return "绕到侧翼，扇形亮起时不要贪最后一下。";
  if (target.includes("random") || target.includes("meteor") || target.includes("rain") || target.includes("tile")) return "先找空白落脚点，连续落区结束后再输出。";
  if (target.includes("ring") || target.includes("pulse") || target.includes("arena")) return "提前贴边或进内圈，等震荡波过去再反击。";
  if (target.includes("self") || effect === "shield" || effect === "speed_up") return "Boss 强化时优先破盾或拉开，别把资源交在硬甲上。";
  if (effect === "spawn_add" || effect === "summon") return "先清召唤物，别让小怪把走位路线堵死。";
  if (effect === "drain" || effect === "apply_dot" || effect === "field_corrupt") return "离开污染区并留一口恢复，持续伤害比首击更危险。";
  return "看地面预警，前摇结束后抓一轮短反击。";
}

function bossSkillCounterWindow(skill) {
  const castTime = Number(skill?.cast_time_sec || 0);
  const cooldown = Number(skill?.cooldown_sec || 0);
  const effect = String(skill?.effect_type || "");
  if (effect === "shield") return "破盾窗口";
  if (effect === "speed_up") return "转阶段空档";
  if (effect === "spawn_add" || effect === "summon") return "清场优先";
  if (effect === "execute") return "保命窗口";
  if (castTime >= 2) return `长前摇 ${castTime.toFixed(1)} 秒，先躲后打。`;
  if (cooldown >= 12) return "大招后冷却长，适合集中输出。";
  if (castTime > 0) return `短前摇 ${castTime.toFixed(1)} 秒，预判走位。`;
  return "瞬发招，保持移动别站桩。";
}

function bossSkillCounterSpiritHint(skill, solution = dungeonSpiritSolutionSpec(), supportSkill = spiritCombatSkills()[0]) {
  if (solution?.active && solution.primary) {
    return `${solution.primary.spiritName}可用「${solution.primary.ability}」稳住场域：${solution.primary.bossImpact || solution.primary.shortImpact}`;
  }
  if (supportSkill) return `${skillName(supportSkill)} 可抵消一段压力，但没有命中秘境解法。`;
  const target = String(skill?.target_rule || "");
  if (target.includes("line") || target.includes("charge")) return "带雷竹或灯影更容易看清冲线落点。";
  if (target.includes("random") || target.includes("tile") || target.includes("rain")) return "带书契或月莲可提前标出安全落脚点。";
  return "带一只协战精怪会让这类前摇更容易处理。";
}

function dungeonBossTelegraphSpec(skill, bossId, run = state.dungeon) {
  if (!skill || !bossId) return null;
  const castTime = Number(skill.cast_time_sec || 0);
  const pressure = skillImpact(skill);
  const phase = Number(run?.bossPhase || 1);
  const solution = dungeonSpiritSolutionSpec(run, currentDungeonMechanic(currentDungeonConfig()), currentDungeonConfig());
  const counterMove = bossSkillCounterMove(skill);
  const counterWindow = bossSkillCounterWindow(skill);
  const spiritHint = bossSkillCounterSpiritHint(skill, solution);
  const familiarity = run?.failureInsightKey ? state.dungeonFailureInsights?.[run.failureInsightKey] : dungeonFailureInsight(currentDungeonConfig(), currentDungeonMechanic(currentDungeonConfig()));
  const memoryHint = familiarity?.bossNextSkillId === skill.boss_skill_id || (familiarity?.bossSkillIds || []).includes(skill.boss_skill_id)
    ? `失利见闻已记录这招：稳场 +${Number(familiarity.bossGuard || 0)} · 反击 +${Number(familiarity.bossStrikeBonus || 0)}。`
    : "";
  return {
    bossLabel: bossName(bossId),
    skillLabel: skillName(skill),
    skillId: skill.boss_skill_id || "",
    targetLabel: bossSkillTargetLabel(skill),
    effectLabel: bossSkillEffectLabel(skill),
    castLabel: castTime > 0 ? `${castTime.toFixed(castTime >= 10 ? 0 : 1)} 秒` : "瞬发",
    pressure,
    tier: pressure >= 10 ? "high" : pressure >= 6 ? "mid" : "low",
    counterMove,
    counterWindow,
    spiritHint,
    memoryHint,
    answerTags: [bossSkillTargetLabel(skill), bossSkillEffectLabel(skill), counterWindow].filter(Boolean).slice(0, 3),
    note: `${bossName(bossId)} 正在蓄势 P${phase}，这次更偏 ${bossSkillTargetLabel(skill)}。`,
  };
}

function dungeonBossCounterMarkup(spec = null) {
  if (!spec) return "";
  return `
    <div class="dungeon-boss-counter ${spec.tier}">
      <div class="dungeon-boss-counter-head">
        <strong>读招应对 · ${spec.skillLabel}</strong>
        <em>${spec.targetLabel} · ${spec.effectLabel}</em>
      </div>
      <span>${spec.counterMove}</span>
      <div class="dungeon-boss-counter-tags">
        ${spec.answerTags.map((tag) => `<b>${tag}</b>`).join("")}
      </div>
      <small>反击窗口：${spec.counterWindow}</small>
      <small>精怪援护：${spec.spiritHint}</small>
      ${spec.memoryHint ? `<small>失利见闻：${spec.memoryHint}</small>` : ""}
    </div>
  `;
}

function spiritCombatSkills(spirit = state.spirits[0]) {
  const runtime = dungeonRuntime();
  if (runtime) return runtime.spiritCombatSkills({ spirit, dungeonClearCount: state.dungeonClears.size });
  if (!spirit) return [];
  const direct = data.spiritSkillsBySpirit.get(spirit.id) || [];
  const combat = data.spiritSkills.filter((skill) => skill.effect_type === "combat");
  return direct.length > 0 ? direct : combat.slice(0, state.dungeonClears.size > 0 ? 2 : 1);
}

function spiritCombatBonus(spirit = state.spirits[0]) {
  const runtime = dungeonRuntime();
  if (runtime) return runtime.spiritCombatBonus({ spirit, dungeonClearCount: state.dungeonClears.size });
  const skills = spiritCombatSkills(spirit);
  const skillBonus = skills.reduce((sum, skill) => {
    const value = Number(skill.effect_param_1 || 0);
    return sum + (skill.effect_type === "combat" ? Math.max(3, Math.round(value * 6)) : 1);
  }, 0);
  return skillBonus + (spirit ? Math.max(0, (spirit.jobLevels?.expedition || 0) * 3) : 0);
}

function skillImpact(skill) {
  const runtime = dungeonRuntime();
  if (runtime) return runtime.skillImpact(skill);
  if (!skill) return 0;
  const primary = Number(skill.effect_param_1 || 0);
  if (skill.effect_type === "damage") return primary;
  if (skill.effect_type === "spawn_hazard") return primary * 4;
  if (skill.effect_type === "shield") return Math.round(primary / 12);
  return Math.max(0, primary);
}

function companionPower() {
  const spirit = state.spirits[0];
  if (!spirit) return 0;
  return Math.round((18 + (spirit.bondLevel || 1) * 6 + Math.floor((spirit.mood || 0) / 12) + spiritCombatBonus(spirit)) * jobEfficiency(spirit, "expedition"));
}

function dungeonBossMaxHp(dungeon, run = state.dungeon) {
  const runtime = dungeonRuntime();
  if (runtime) return runtime.dungeonBossMaxHp({ bossId: dungeonBossId(dungeon, run), fallback: 1200 });
  const boss = data.bossesById.get(dungeonBossId(dungeon, run));
  return Math.max(300, Number(boss?.hp_total || 1200));
}

function bossHpPercent(run, dungeon = currentDungeonConfig()) {
  if (!run || !dungeon) return 1;
  const runtime = dungeonRuntime();
  if (runtime) return runtime.bossHpPercent({ run, bossId: dungeonBossId(dungeon, run), bossMaxHp: run?.bossMaxHp });
  const maxHp = run.bossMaxHp || dungeonBossMaxHp(dungeon);
  return Math.max(0, Math.min(1, Number(run.bossHp ?? maxHp) / maxHp));
}

function dungeonSpiritAdvantage(mechanic = currentDungeonMechanic()) {
  return dungeonSpiritSolutionSpec(state.dungeon, mechanic)?.advantage || 0;
}

function enemyAiLabel(enemy) {
  const labels = {
    charge: "直线冲撞",
    split: "分裂压场",
    dive: "俯冲骚扰",
    swarm: "群聚包围",
    spore_cloud: "孢雾铺场",
    burrow: "钻沙突袭",
    orbit: "环绕灼烧",
    drain: "吸灵消耗",
    guard: "重甲守卫",
  };
  return labels[enemy?.ai_type] || enemy?.ai_type || "游荡";
}

function enemyWeaknessText(enemy) {
  const aliases = {
    blunt: "钝击",
    water: "水",
    fire: "火",
    slash: "斩击",
    sound: "声",
    light: "光",
    wind: "风",
    cleanse: "净化",
    ice: "冰",
    earth: "土",
    purify: "纯化",
    pierce: "穿刺",
    thunder: "雷",
  };
  return splitTags(enemy?.weakness_tags || "").map((tag) => aliases[tag] || tag).join(" / ") || "无明显弱点";
}

function dungeonHazardProfile(mechanic, run = {}, dungeon = currentDungeonConfig()) {
  const text = `${mechanic?.solar_term || ""}${mechanic?.field_rule || ""}${mechanic?.puzzle_core || ""}`;
  const baseSeverity = 1 + ((Number(run.floor || 1) + Number(run.turn || 0) + state.day) % 3);
  const profiles = [
    { match: "雷", label: "雷声震柱", tone: "thunder", detail: "等雷声后激活机关，误入雷落点会被震伤。" },
    { match: "水位", label: "涨落水位", tone: "water", detail: "水位改变路线，水运或月莲类精怪可降低绕路风险。" },
    { match: "虫鸣", label: "虫鸣岔路", tone: "forest", detail: "跟随虫鸣节拍选路，急进会引来群聚敌人。" },
    { match: "满溢", label: "满溢风险", tone: "gold", detail: "采集越多收益越高，但满溢会推高本层伤害。" },
    { match: "倒影", label: "镜湖倒影", tone: "moon", detail: "真实道路藏在倒影里，灯影/月莲能提高辨路容错。" },
    { match: "霜", label: "寒霜迟滞", tone: "frost", detail: "停留越久行动越慢，火候精怪能帮忙保暖。" },
    { match: "风向", label: "落叶风向", tone: "wind", detail: "风会覆盖旧路，书契精怪能记录安全路径。" },
    { match: "灯", label: "长灯重组", tone: "lantern", detail: "灯灭后道路改写，维持灯火链才能接近核心。" },
  ];
  const profile = profiles.find((entry) => text.includes(entry.match)) || { label: "灵雾扰动", tone: dungeon?.dungeon_type || "mist", detail: mechanic?.field_rule || "秘境灵气混乱，路线和敌意都在变化。" };
  return {
    id: mechanic?.dungeon_id || dungeon?.area_id || "dungeon_hazard",
    label: profile.label,
    tone: profile.tone,
    severity: Math.min(5, baseSeverity + (profile.label === "满溢风险" ? Math.min(2, Number(run.progress || 0)) : 0)),
    detail: profile.detail,
  };
}

function dungeonHazards(mechanic = currentDungeonMechanic(), run = state.dungeon, dungeon = currentDungeonConfig()) {
  const hazards = [dungeonHazardProfile(mechanic, run, dungeon)];
  if (run?.lastEnemyId) {
    const enemy = data.enemiesById.get(run.lastEnemyId);
    hazards.push({
      id: `enemy_${enemy?.ai_type || "pressure"}`,
      label: enemyAiLabel(enemy),
      tone: enemy?.ai_type || "enemy",
      severity: Math.min(5, 1 + Math.round(Number(enemy?.move_speed || 1))),
      detail: `${enemyName(enemy)} 弱点：${enemyWeaknessText(enemy)}`,
    });
  }
  if (run?.bossReady) {
    const bossId = dungeonBossId(dungeon, run);
    hazards.push({
      id: "boss_aura",
      label: "Boss 威压",
      tone: "boss",
      severity: Math.max(2, bossPhaseForPercent(bossId, bossHpPercent(run, dungeon))),
      detail: `${bossName(bossId)} 正在蓄势，注意技能前摇。`,
    });
  }
  return hazards.slice(0, 3);
}

function dungeonHazardPressure(hazards = []) {
  return hazards.reduce((sum, hazard) => sum + Number(hazard.severity || 1) * 2, 0);
}

function lootConditionMet(condition = "always_true") {
  if (!condition || condition === "always_true") return true;
  if (condition === "chapter_2_or_more") return state.canalRepaired || state.dungeonClears.size > 0 || state.completed.has("repair");
  if (condition === "chapter_3_or_more") return state.dungeonClears.size >= 2 || state.defeatedBosses.has("boss_shixiang_tengmu");
  if (condition === "current_term_bailu") return state.term === "白露";
  if (condition === "boss_chiyan_xiehou_defeated") return state.defeatedBosses.has("boss_chiyan_xiehou");
  if (condition === "npc_baizhi_favor_3") return favorLevel(state.npcFavor.npc_baizhi || 0) >= 3;
  if (condition === "quest_main_0402_active") return state.completed.has("dungeon") || state.dungeonClears.size >= 3;
  if (condition === "quest_main_0403_active") return state.defeatedBosses.has("boss_shiling_mingmu");
  return conditionGroupStatus(condition).pass;
}

function rollLoot(poolId, floor = 1, countMultiplier = 1) {
  const pool = data.lootByPool.get(poolId) || [];
  if (pool.length === 0) return [];
  const conditionResults = Object.fromEntries(pool.map((entry) => [
    entry.condition_group || "always_true",
    lootConditionMet(entry.condition_group),
  ]));
  const lootPlan = dungeonRuntime()?.dungeonLootPlan({
    pool,
    floor,
    countMultiplier,
    day: state.day,
    runSeed: state.dungeon?.runSeed || 0,
    turn: state.dungeon?.turn || 0,
    conditionResults,
  });
  if (lootPlan) {
    for (const entry of lootPlan) addItem(entry.itemId, entry.count);
    return lootPlan;
  }
  const available = pool.filter((entry) => lootConditionMet(entry.condition_group));
  const weighted = available.length > 0 ? available : pool;
  const totalWeight = weighted.reduce((sum, entry) => sum + Math.max(1, Number(entry.weight || 1)), 0);
  let roll = ((state.day * 37) + (floor * 19) + ((state.dungeon?.runSeed || 0) * 11) + (state.dungeon?.turn || 0)) % totalWeight;
  const entry = weighted.find((candidate) => {
    roll -= Math.max(1, Number(candidate.weight || 1));
    return roll < 0;
  }) || weighted[0];
  const min = Number(entry.min_count || 1);
  const max = Number(entry.max_count || min);
  const baseCount = Math.min(max, min + (floor % Math.max(1, max - min + 1)));
  const count = Math.max(1, Math.ceil(baseCount * countMultiplier));
  addItem(entry.item_id, count);
  return [{ itemId: entry.item_id, count }];
}

function dungeonWorldChangeKey(dungeon, mechanic) {
  return `${dungeon?.area_id || "unknown"}:${mechanic?.dungeon_id || "term"}`;
}

function dungeonFailureInsightKey(dungeon = currentDungeonConfig(), mechanic = currentDungeonMechanic(dungeon)) {
  return dungeonWorldChangeKey(dungeon, mechanic);
}

function dungeonFailureInsight(dungeon = currentDungeonConfig(), mechanic = currentDungeonMechanic(dungeon)) {
  const key = dungeonFailureInsightKey(dungeon, mechanic);
  return key ? state.dungeonFailureInsights?.[key] || null : null;
}

function dungeonFailureInsightNote(reason = "battle", dungeon = currentDungeonConfig(), mechanic = currentDungeonMechanic(dungeon), insight = {}) {
  const revealedFloor = Math.max(1, Number(insight.revealedFloor || dungeon?.floor_start || 1));
  const bossPhaseSeen = Math.max(0, Number(insight.bossPhaseSeen || 0));
  const overflowRelief = Math.max(0, Number(insight.overflowRelief || 0));
  if (reason === "boss") {
    const bestPercent = Math.max(0, Math.min(100, Number(insight.bossBestPercent || 100)));
    const nextSkill = insight.bossNextSkillName ? `，下一招多半是 ${insight.bossNextSkillName}` : "";
    return `${bossName(dungeonBossId(dungeon))} 的 P${Math.max(1, bossPhaseSeen)} 起手已经记住了，最低压到 ${bestPercent}%${nextSkill}，下次更早能看懂前摇。`;
  }
  if (reason === "overflow") {
    return `谷底最躁的满溢点已经被你记下，下次开局风险会先压低 ${overflowRelief}。`;
  }
  if (reason === "retreat") {
    return `${dungeonName(dungeon)} 前 ${revealedFloor} 层的转角和路感记下来了，下次不会再摸黑试。`;
  }
  return `${dungeonName(dungeon)} 前 ${revealedFloor} 层的路已经看熟了一些，下次开局会更稳。`;
}

function dungeonFailureInsightSummary(insight = null) {
  if (!insight) return null;
  const parts = [];
  if (Number(insight.revealedFloor || 0) > 0) parts.push(`记住前 ${insight.revealedFloor} 层`);
  if (Number(insight.pathBonus || 0) > 0) parts.push(`路压 -${insight.pathBonus}`);
  if (Number(insight.bossPhaseSeen || 0) > 0) parts.push(`Boss P${insight.bossPhaseSeen}`);
  if (Number(insight.bossBestPercent || 0) > 0 && Number(insight.bossBestPercent || 100) < 100) parts.push(`最低 ${insight.bossBestPercent}%`);
  if (Number(insight.bossFamiliarity || 0) > 0) parts.push(`熟悉度 ${insight.bossFamiliarity}`);
  if (Number(insight.bossGuard || 0) > 0) parts.push(`稳场 +${insight.bossGuard}`);
  if (Number(insight.bossStrikeBonus || 0) > 0) parts.push(`反击 +${insight.bossStrikeBonus}`);
  if (Number(insight.overflowRelief || 0) > 0) parts.push(`满溢减压 ${insight.overflowRelief}`);
  return {
    title: insight.lastReason === "boss" ? "Boss 失利见闻" : insight.lastReason === "overflow" ? "满溢记忆" : "失利见闻",
    body: insight.note || "这处秘境已经留下了一点可复用的路感。",
    detail: parts.join(" · ") || "下一次进入时会比上次更能看懂节奏。",
    bossMemory: insight.bossNextSkillName ? `已看招式：${(insight.bossSkillNames || []).slice(0, 3).join(" / ") || insight.bossNextSkillName} · 下次盯防 ${insight.bossNextSkillName}` : "",
  };
}

function dungeonBossFamiliarityMarkup(insight = null) {
  if (!insight || Number(insight.bossFamiliarity || 0) <= 0) return "";
  const skillText = (insight.bossSkillNames || []).slice(0, 3).join(" / ") || insight.bossNextSkillName || "已记录起手";
  const bestText = Number(insight.bossBestPercent || 100) < 100 ? `最低压到 ${Number(insight.bossBestPercent || 100)}%` : "已看见 Boss 起手";
  return `
    <div class="dungeon-boss-familiarity">
      <strong>Boss 熟悉度 ${Number(insight.bossFamiliarity || 0)}/5 · ${bestText}</strong>
      <span>已看招式：${skillText}</span>
      <small>下次收益：稳场 +${Number(insight.bossGuard || 0)} · 反击 +${Number(insight.bossStrikeBonus || 0)}${insight.bossNextSkillName ? ` · 盯防 ${insight.bossNextSkillName}` : ""}</small>
    </div>
  `;
}

function recordDungeonFailureInsight(reason = "battle", run = state.dungeon, dungeon = currentDungeonConfig(), mechanic = currentDungeonMechanic(dungeon)) {
  if (!run || !dungeon || !mechanic) return null;
  const key = dungeonFailureInsightKey(dungeon, mechanic);
  const previous = state.dungeonFailureInsights?.[key] || {};
  const bossId = dungeonBossId(dungeon, run);
  const insight = dungeonRuntime()?.dungeonFailureInsightPlan({
    key,
    reason,
    day: state.day,
    previous,
    run,
    dungeon,
    mechanic,
    bossId,
  }) || (() => {
    const failures = Math.max(0, Number(previous.failures || 0)) + 1;
    const revealedFloor = Math.max(Number(previous.revealedFloor || 0), Number(run.floor || dungeon?.floor_start || 1));
    const bossPhaseSeen = Math.max(Number(previous.bossPhaseSeen || 0), reason === "boss" || run.bossReady ? Number(run.bossPhase || 1) : 0);
    const bossPercentNow = Math.ceil(bossHpPercent(run, dungeon) * 100);
    const previousBestPercent = Number(previous.bossBestPercent || 100);
    const bossBestPercent = reason === "boss" || run.bossReady ? Math.min(previousBestPercent, bossPercentNow) : previousBestPercent;
    const lastBossSkillId = String(run.lastBossSkillId || "");
    const previousSkillIds = Array.isArray(previous.bossSkillIds) ? previous.bossSkillIds : [];
    const bossSkillIds = [...new Set([...previousSkillIds, lastBossSkillId].filter(Boolean))].slice(-5);
    const nextBossSkill = run.bossReady ? bossSkillForTurn(bossId, Number(run.turn || 0), bossHpPercent(run, dungeon)) : null;
    const bossFamiliarity = reason === "boss" || run.bossReady
      ? Math.min(5, Math.max(Number(previous.bossFamiliarity || 0), Math.ceil((100 - bossBestPercent) / 20) + Math.max(0, bossPhaseSeen - 1) + Math.min(1, bossSkillIds.length)))
      : Number(previous.bossFamiliarity || 0);
    const basePathBonus = Math.min(3, 1 + Math.floor(failures / 2));
    const pathBonus = Math.max(Number(previous.pathBonus || 0), reason === "boss" ? Math.max(1, basePathBonus - 1) : basePathBonus);
    const overflowRelief = Math.max(
      Number(previous.overflowRelief || 0),
      mechanic?.dungeon_id === "dsm_004" && Number(run.mechanicState?.overflow || 0) >= 4 ? 2 : 0,
    );
    const bossGuard = Math.max(Number(previous.bossGuard || 0), bossPhaseSeen > 0 ? Math.min(4, bossPhaseSeen + Math.floor(bossFamiliarity / 2)) : 0);
    const bossStrikeBonus = Math.max(Number(previous.bossStrikeBonus || 0), bossFamiliarity > 0 ? Math.min(90, 18 * bossFamiliarity) : 0);
    return {
      key,
      dungeonId: dungeon?.area_id || "",
      mechanicId: mechanic?.dungeon_id || "",
      failures,
      lastReason: reason,
      unlockedDay: state.day,
      revealedFloor,
      pathBonus,
      bossPhaseSeen,
      bossGuard,
      bossStrikeBonus,
      bossFamiliarity,
      bossBestPercent,
      bossSkillIds,
      bossNextSkillId: nextBossSkill?.boss_skill_id || "",
      overflowRelief,
    };
  })();
  insight.bossSkillNames = (Array.isArray(insight.bossSkillIds) ? insight.bossSkillIds : [])
    .map((skillId) => skillName(data.bossSkills.find((skill) => skill.boss_skill_id === skillId)))
    .filter(Boolean);
  const nextBossSkill = insight.bossNextSkillId ? data.bossSkills.find((skill) => skill.boss_skill_id === insight.bossNextSkillId) : null;
  insight.bossNextSkillName = nextBossSkill ? skillName(nextBossSkill) : "";
  insight.note = dungeonFailureInsightNote(reason, dungeon, mechanic, insight);
  const summary = dungeonFailureInsightSummary(insight);
  const codexText = {
    title: summary?.title || "秘境失利见闻",
    headline: `${dungeonName(dungeon)} 的路感被记住了`,
    problem: reason === "boss" ? `${bossName(dungeonBossId(dungeon))} 把你逼退` : reason === "overflow" ? "节气机关满溢压住了推进" : "秘境探索中途撤退",
    insight: insight.note || summary?.body || "这处秘境已经留下了一点可复用的路感。",
    nextAction: summary?.detail || "下次进入时会比上次更能看懂节奏。",
    support: summary?.bossMemory || (Number(insight.pathBonus || 0) > 0 ? `下次路压 -${insight.pathBonus}` : "已保留探索见闻"),
    rewardText: summary?.bossMemory || (Number(insight.pathBonus || 0) > 0 ? `下次路压 -${insight.pathBonus}` : "已保留探索见闻"),
    tone: reason === "boss" ? "boss" : "learn",
    icon: reason === "boss" ? "魇" : "境",
  };
  const applyPlan = dungeonRuntime()?.dungeonFailureInsightApplyPlan({
    key,
    reason,
    insight,
    insights: state.dungeonFailureInsights || {},
    codexText,
  }) || {
    nextInsights: {
      ...(state.dungeonFailureInsights || {}),
      [key]: insight,
    },
    codexEntry: {
      id: `failure_dungeon_${key}`,
      type: "dungeon",
      sourceId: key,
      ...codexText,
    },
  };
  state.dungeonFailureInsights = applyPlan.nextInsights;
  recordFailureCodexEntry(applyPlan.codexEntry);
  return insight;
}

function dungeonPostBattleSideEffectActions(plan, dungeon, bossId) {
  if (Array.isArray(plan?.actions) && plan.actions.length > 0) return plan.actions;
  const actions = [];
  if (plan?.seasonalGoal) actions.push({ kind: "seasonal_goal", ...plan.seasonalGoal });
  for (const hook of plan?.storyHooks || []) actions.push({ kind: "story_hook", hook });
  for (const key of plan?.completionKeys || ["dungeon"]) actions.push({ kind: "completion", key });
  if (plan?.cohabEvent) actions.push({ kind: "cohab_event", ...plan.cohabEvent });
  if (actions.length === 0) {
    if (currentTermId() === "term_dongzhi") actions.push({ kind: "seasonal_goal", category: "seasonal", key: "lanternDungeonClears", amount: 1 });
    if (bossId === BAIZHI_BOSS_ID) actions.push({ kind: "story_hook", hook: "herb_valley_baizhi_finish" });
    if (bossId === FIRE_RUIN_BOSS_ID) actions.push({ kind: "story_hook", hook: "fire_ruin_finish" });
    if (bossId === CHAPTER_4_FINAL_BOSS_ID) actions.push({ kind: "story_hook", hook: "chapter4_pantao_finale" });
    actions.push({ kind: "completion", key: "dungeon" });
    actions.push({ kind: "cohab_event", trigger: "on_dungeon_return", areaId: dungeon?.area_id || "" });
  }
  return actions;
}

function applyDungeonPostBattleSideEffectAction(action, dungeon, bossId) {
  if (!action?.kind) return false;
  if (action.kind === "seasonal_goal") {
    addGoalBookProgress(action.category, action.key, Number(action.amount || 1));
    return true;
  }
  if (action.kind === "story_hook") {
    if (action.hook === "herb_valley_baizhi_finish") finishHerbValleyBaizhiLine(localize("event_name_main_0207", "百草母露入手"));
    if (action.hook === "fire_ruin_finish") finishFireRuinLine(localize("event_name_main_0307", "炽炎火精归位"));
    if (action.hook === "chapter4_pantao_finale") startChapter4PantaoFinale(localize("event_name_main_0405", "终章决战收束"));
    return true;
  }
  if (action.kind === "completion") {
    complete(action.key || "dungeon");
    return true;
  }
  if (action.kind === "cohab_event") {
    triggerCohabWeeklyEvents(action.trigger || "on_dungeon_return", { areaId: action.areaId || dungeon?.area_id || "", bossId, day: state.day });
    return true;
  }
  return false;
}

function applyDungeonPostBattleSideEffectPlan(plan, dungeon, bossId) {
  const actions = dungeonPostBattleSideEffectActions(plan, dungeon, bossId);
  for (const action of actions) applyDungeonPostBattleSideEffectAction(action, dungeon, bossId);
  return actions;
}

function solarTermConfigByLabel(label = state.term) {
  return data.solarTerms.find((entry) => localize(entry.term_name_key, entry.term_id) === label || entry.term_id === label) || currentTermConfig();
}

function dungeonCompendiumKey(dungeon = currentDungeonConfig(), mechanic = currentDungeonMechanic(dungeon)) {
  return dungeonWorldChangeKey(dungeon, mechanic);
}

function dungeonStampLabel(dungeon = currentDungeonConfig(), mechanic = currentDungeonMechanic(dungeon)) {
  const termConfig = solarTermConfigByLabel(mechanic?.solar_term || state.term);
  const termLabel = localize(termConfig?.term_name_key, mechanic?.solar_term || termConfig?.term_id || state.term);
  const suffix = {
    dsm_001: "雷印",
    dsm_002: "水印",
    dsm_003: "鸣印",
    dsm_004: "丰印",
    dsm_005: "镜印",
    dsm_006: "霜印",
    dsm_007: "叶印",
    dsm_008: "灯印",
  }[mechanic?.dungeon_id] || "印记";
  return `${termLabel}${suffix}`;
}

function dungeonCompendiumEntry(dungeon = currentDungeonConfig(), mechanic = currentDungeonMechanic(dungeon)) {
  const key = dungeonCompendiumKey(dungeon, mechanic);
  return key ? state.dungeonCompendium?.[key] || null : null;
}

function dungeonCompendiumEntries() {
  return Object.values(state.dungeonCompendium || {});
}

function ensureDungeonCompendiumEntry(dungeon = currentDungeonConfig(), mechanic = currentDungeonMechanic(dungeon)) {
  if (!dungeon || !mechanic) return null;
  const key = dungeonCompendiumKey(dungeon, mechanic);
  const termConfig = solarTermConfigByLabel(mechanic.solar_term || state.term);
  const existing = state.dungeonCompendium?.[key];
  if (existing) return { ...existing };
  return {
    key,
    dungeonId: dungeon.area_id || "",
    mechanicId: mechanic.dungeon_id || "",
    dungeonLabel: dungeonName(dungeon),
    termId: termConfig?.term_id || currentTermId(),
    termLabel: localize(termConfig?.term_name_key, mechanic.solar_term || state.term),
    stampLabel: dungeonStampLabel(dungeon, mechanic),
    rewardHint: mechanic.main_reward || "",
    externalChange: mechanic.external_change || "",
    puzzleHint: mechanic.puzzle_core || "",
    shardCount: 0,
    unlocked: false,
    cleared: false,
    clearCount: 0,
    bestFloor: 0,
    bossSeen: false,
    bossPhaseSeen: 0,
    firstShardDay: null,
    firstUnlockDay: null,
    firstClearDay: null,
    lastUpdateDay: null,
    note: "",
  };
}

function dungeonCompendiumEntrySummary(entry = null) {
  if (!entry) return null;
  const baseDetail = entry.rewardHint || entry.externalChange || entry.puzzleHint || "可为年轮试炼提供节气共鸣。";
  if (entry.cleared) {
    return {
      state: "done",
      title: `${entry.stampLabel} 已凝成`,
      body: `${entry.dungeonLabel} 已通关 · 节气共鸣可直接带入试炼。`,
      detail: `${baseDetail} · 通关 ${entry.clearCount} 次 · 最深 ${entry.bestFloor} 层`,
    };
  }
  if (entry.unlocked) {
    return {
      state: "ready",
      title: `${entry.stampLabel} 已拼成`,
      body: `${entry.shardCount}/3 碎片已成印，但还没真正镇住这处秘境。`,
      detail: `${baseDetail} · 先去完成一次 Boss 击破，会把印记真正坐实。`,
    };
  }
  return {
    state: "pending",
    title: `${entry.stampLabel} 碎片 ${entry.shardCount}/3`,
    body: `${entry.dungeonLabel} 已留下见闻，但印记还没拼完整。`,
    detail: `${baseDetail} · 再推进或撤离时还能继续收碎片。`,
  };
}

function dungeonCompendiumProgress() {
  const entries = dungeonCompendiumEntries().sort((a, b) => {
    const dayA = Number(a.firstClearDay || a.firstUnlockDay || a.firstShardDay || 0);
    const dayB = Number(b.firstClearDay || b.firstUnlockDay || b.firstShardDay || 0);
    return dayB - dayA || String(a.termId).localeCompare(String(b.termId));
  });
  return {
    total: data.dungeonSolarMechanics.length,
    entries,
    unlocked: entries.filter((entry) => entry.unlocked).length,
    cleared: entries.filter((entry) => entry.cleared).length,
    shards: entries.reduce((sum, entry) => sum + Math.max(0, Number(entry.shardCount || 0) - (entry.unlocked ? 3 : 0)), 0),
  };
}

function grantDungeonCompendiumProgress(mode = "shard", amount = 1, run = state.dungeon, dungeon = currentDungeonConfig(), mechanic = currentDungeonMechanic(dungeon)) {
  if (!run || !dungeon || !mechanic) return null;
  const entry = ensureDungeonCompendiumEntry(dungeon, mechanic);
  const beforeUnlock = Boolean(entry.unlocked);
  const beforeClear = Boolean(entry.cleared);
  entry.bestFloor = Math.max(Number(entry.bestFloor || 0), Number(run.floor || dungeon.floor_start || 1));
  entry.bossSeen = entry.bossSeen || Boolean(run.bossReady) || mode === "clear";
  entry.bossPhaseSeen = Math.max(Number(entry.bossPhaseSeen || 0), Number(run.bossPhase || 0));
  entry.lastUpdateDay = state.day;

  if (mode === "clear") {
    entry.shardCount = 3;
    entry.unlocked = true;
    entry.cleared = true;
    entry.clearCount = Math.max(0, Number(entry.clearCount || 0)) + 1;
    if (!entry.firstShardDay) entry.firstShardDay = state.day;
    if (!entry.firstUnlockDay) entry.firstUnlockDay = state.day;
    if (!entry.firstClearDay) entry.firstClearDay = state.day;
    entry.note = `${entry.stampLabel} 已真正镇住，可为年轮试炼提供稳定共鸣。`;
  } else {
    entry.shardCount = Math.min(3, Math.max(0, Number(entry.shardCount || 0)) + Math.max(1, Number(amount || 1)));
    if (!entry.firstShardDay) entry.firstShardDay = state.day;
    if (entry.shardCount >= 3) {
      entry.unlocked = true;
      if (!entry.firstUnlockDay) entry.firstUnlockDay = state.day;
    }
    entry.note = entry.unlocked
      ? `${entry.stampLabel} 已由碎片拼成，但还差一次真正通关。`
      : `${entry.stampLabel} 碎片 ${entry.shardCount}/3，年轮的边角已经被你摸出来了。`;
  }

  state.dungeonCompendium = {
    ...(state.dungeonCompendium || {}),
    [entry.key]: entry,
  };

  const summary = dungeonCompendiumEntrySummary(entry);
  return {
    entry,
    summary,
    text: mode === "clear"
      ? beforeClear ? `${entry.stampLabel} 再鸣一次` : `凝成 ${entry.stampLabel}`
      : entry.unlocked && !beforeUnlock ? `拼成 ${entry.stampLabel}` : `${entry.stampLabel} 碎片 ${entry.shardCount}/3`,
  };
}

function dungeonDayEchoOutcomeSpec(outcome = "explore") {
  const outcomes = {
    attune: {
      label: "顺应节气",
      tone: "good",
      next: "明天再进秘境时，先看同一张三联牌，确认哪条机关已经被你摸顺。",
    },
    explore: {
      label: "探索推进",
      tone: "good",
      next: "明天可以继续从秘境面板判断体力、随行精怪和当前场规，再决定推进或撤离。",
    },
    boss_ready: {
      label: "Boss 现身",
      tone: "warn",
      next: "明天先回看 Boss 前摇和精怪解法，再手动决定挑战或撤离。",
    },
    failed: {
      label: "探索失利",
      tone: "warn",
      next: "明天先进失败见闻看保留了哪段路感，再换精怪或补体力重进。",
    },
    boss_failed: {
      label: "Boss 失利",
      tone: "warn",
      next: "明天先看 Boss 熟悉度和下一招盯防，再补精怪羁绊或装备后手动挑战。",
    },
    clear: {
      label: "Boss 击破",
      tone: "done",
      next: "明天去目标册翻开秘境回忆页，把印记、外部变化和年轮试炼共鸣接上。",
    },
    retreat: {
      label: "主动撤离",
      tone: "note",
      next: "明天先看撤离带回的见闻和印记碎片，再决定是否继续压深层。",
    },
  };
  return outcomes[outcome] || outcomes.explore;
}

function dungeonDayEchoRewardText(outcome = "explore", extras = {}, dungeon = currentDungeonConfig(), mechanic = currentDungeonMechanic(dungeon)) {
  const lootEntries = extras.bossLoot || extras.loot || [];
  const lootText = Array.isArray(lootEntries) && lootEntries.length > 0
    ? lootEntries.map((entry) => `${itemName(entry.itemId)} x${entry.count}`).join("、")
    : "";
  const rotationText = Array.isArray(extras.rotationRewards) && extras.rotationRewards.length > 0
    ? `隐藏层回响：${extras.rotationRewards.join("、")}`
    : "";
  return [
    extras.rewardText || lootText,
    extras.stampGain?.text ? `节气印记：${extras.stampGain.text}` : "",
    extras.aftermath?.change?.title ? `外部变化：${extras.aftermath.change.title}` : "",
    rotationText,
    extras.aftermath?.clue?.spiritName ? `稀有精怪线索：${extras.aftermath.clue.spiritName}` : "",
  ].filter(Boolean).join("；") || (outcome === "clear"
    ? mechanic?.main_reward || "Boss 掉落和外部变化已写进洞天"
    : mechanic?.failure_compensation || "保留路感、掉落或节气印记碎片");
}

function dungeonDayEchoSpec(run = state.dungeon, dungeon = currentDungeonConfig(), mechanic = currentDungeonMechanic(dungeon), outcome = "explore", extras = {}) {
  if (!dungeon || !mechanic) return null;
  const outcomeSpec = dungeonDayEchoOutcomeSpec(outcome);
  const solutionSpec = dungeonSpiritSolutionSpec(run, mechanic, dungeon);
  const activeSolution = solutionSpec?.active && solutionSpec.primary ? solutionSpec.primary : null;
  const recommendedText = splitTags(mechanic.recommended_spirits || "").join(" / ") || "随行精怪";
  const hud = run ? dungeonMechanicHudSpec(run, mechanic, dungeon) : null;
  const status = run ? dungeonMechanicStatus(run, mechanic, dungeon) : null;
  const failureInsight = extras.failureInsight || dungeonFailureInsight(dungeon, mechanic);
  const failureSummary = dungeonFailureInsightSummary(failureInsight);
  const stampEntry = extras.stampGain?.entry || dungeonCompendiumEntry(dungeon, mechanic);
  const stampSummary = dungeonCompendiumEntrySummary(stampEntry);
  const worldChange = extras.aftermath?.change
    || dungeonWorldChangeForMechanic(dungeon, mechanic)
    || null;
  const rewardText = dungeonDayEchoRewardText(outcome, extras, dungeon, mechanic);
  const solutionText = activeSolution
    ? `${activeSolution.spiritName}用「${activeSolution.ability}」接入机关`
    : `推荐 ${recommendedText}，当前仍可先靠观察硬解`;
  const supportText = activeSolution
    ? activeSolution.impact || solutionSpec?.exactImpact || activeSolution.shortImpact
    : solutionSpec?.exactImpact || `未命中推荐精怪；补上 ${recommendedText} 后，机关容错会更高。`;
  const failureText = failureSummary
    ? `${failureSummary.title}：${failureSummary.body} · ${failureSummary.detail}`
    : mechanic.failure_compensation || "失败后仍会保留路线见闻、印记碎片或少量材料。";
  const stampText = extras.stampGain?.text || stampSummary?.title || "尚未形成完整节气印记";
  const externalChangeText = worldChange?.title || mechanic.external_change || "通关后会把外部变化写进洞天主场景";
  return {
    key: `${state.day}:${dungeon.area_id}:${mechanic.dungeon_id}:${outcome}:${Number(run?.turn || 0)}:${Number(run?.floor || 0)}`,
    day: state.day,
    dungeonId: dungeon.area_id || "",
    dungeonName: dungeonName(dungeon),
    mechanicId: mechanic.dungeon_id || "",
    solarTerm: mechanic.solar_term || state.term || currentTermId(),
    tone: outcomeSpec.tone,
    outcome,
    outcomeLabel: outcomeSpec.label,
    fieldRule: mechanic.field_rule || "节气规则正在改写秘境路线。",
    puzzleCore: mechanic.puzzle_core || "先观察机关节奏，再决定推进方式。",
    progressText: hud?.progressText || status?.summary || mechanic.field_rule || "当前秘境节气机制仍在运转。",
    solutionText,
    supportText,
    rewardText,
    failureText,
    externalChangeText,
    stampText,
    nextStepText: extras.nextStepText || outcomeSpec.next,
    memoryKey: stampEntry?.key || "",
    failureKey: failureInsight?.key || dungeonFailureInsightKey(dungeon, mechanic),
    floorText: run ? `第 ${Number(run.floor || dungeon.floor_start || 1)}/${Number(run.maxFloor || dungeon.floor_end || 1)} 层` : `${dungeon.floor_start}-${dungeon.floor_end} 层`,
    bossText: extras.bossId ? bossName(extras.bossId) : run?.bossReady || outcome.includes("boss") ? bossName(dungeonBossId(dungeon, run)) : "",
    safety: "这里只定位/回看，不会自动进入秘境、探索、顺应节气或挑战 Boss，也不会消耗资源。",
  };
}

function recordDungeonDayEcho(outcome = "explore", run = state.dungeon, dungeon = currentDungeonConfig(), mechanic = currentDungeonMechanic(dungeon), extras = {}) {
  const spec = dungeonDayEchoSpec(run, dungeon, mechanic, outcome, extras);
  if (!spec) return null;
  state.lastDungeonDayEcho = spec;
  state.dungeonDayEchoHistory = [
    spec,
    ...(state.dungeonDayEchoHistory || []).filter((entry) => entry?.key !== spec.key),
  ].slice(0, 8);
  return spec;
}

function dungeonDayEchoArchiveRows(limit = 4) {
  const rows = [
    state.lastDungeonDayEcho,
    ...(state.dungeonDayEchoHistory || []),
    state.lastDaySummary?.dungeonDayEcho,
  ]
    .filter(Boolean)
    .map((entry) => dungeonDayEchoDaySummarySpec(entry, entry.day))
    .filter(Boolean);
  const seen = new Set();
  return rows
    .filter((entry) => {
      if (seen.has(entry.key)) return false;
      seen.add(entry.key);
      return true;
    })
    .sort((a, b) => Number(b.day || 0) - Number(a.day || 0) || String(b.key).localeCompare(String(a.key)))
    .slice(0, limit);
}

function dungeonDayEchoArchiveRune(text = "", fallback = "境") {
  const value = String(text || "");
  if (value.includes("雷")) return "雷";
  if (value.includes("水") || value.includes("渠") || value.includes("闸")) return "水";
  if (value.includes("灯") || value.includes("光") || value.includes("影")) return "灯";
  if (value.includes("风") || value.includes("叶")) return "风";
  if (value.includes("霜") || value.includes("寒") || value.includes("暖")) return "霜";
  if (value.includes("虫") || value.includes("鸣") || value.includes("蜂")) return "鸣";
  if (value.includes("月") || value.includes("镜") || value.includes("莲")) return "月";
  if (value.includes("满") || value.includes("溢") || value.includes("土")) return "满";
  if (value.includes("精怪") || value.includes("萝卜")) return "精";
  if (value.includes("印记") || value.includes("碎片")) return "印";
  if (value.includes("材料") || value.includes("掉落") || value.includes("矿")) return "材";
  return fallback;
}

function dungeonDayEchoArchiveScrollSpec(row = null) {
  if (!row) {
    return {
      title: "余烬画卷未展开",
      subtitle: "第一缕秘境余烬还在等你带回洞天。",
      nodes: [
        { key: "rule", label: "场规", rune: "境", text: "节气机关待识别", mode: "route", disabled: true },
        { key: "spirit", label: "精怪", rune: "精", text: "随行解法待落笔", mode: "route", disabled: true },
        { key: "carry", label: "带回", rune: "印", text: "奖励与印记待收录", mode: "memory", disabled: true },
        { key: "tomorrow", label: "明日", rune: "晨", text: "下一步待生成", mode: "panel", disabled: true },
      ],
    };
  }
  return {
    title: `${row.solarTerm} · ${row.outcomeLabel}`,
    subtitle: `${row.dungeonName} · ${row.floorText}`,
    nodes: [
      { key: "rule", label: "场规", rune: dungeonDayEchoArchiveRune(row.fieldRule, "境"), text: row.fieldRule, mode: "route" },
      { key: "spirit", label: "精怪", rune: dungeonDayEchoArchiveRune(row.solutionText || row.supportText, "精"), text: row.solutionText, mode: "route" },
      { key: "carry", label: "带回", rune: dungeonDayEchoArchiveRune(`${row.rewardText}${row.stampText}`, row.outcome === "clear" ? "印" : "获"), text: row.rewardText, mode: "memory", disabled: !row.memoryKey },
      { key: "tomorrow", label: "明日", rune: row.outcome === "clear" ? "变" : "补", text: row.nextStepText, mode: "panel" },
    ],
  };
}

function dungeonDayEchoArchiveScrollMarkup(row = null) {
  const spec = dungeonDayEchoArchiveScrollSpec(row);
  const archiveKey = selectorDataValue(row?.key || "");
  return `
    <div class="dungeon-echo-scroll ${row?.tone || "empty"}" data-dungeon-echo-scroll="${archiveKey}">
      <div class="dungeon-echo-scroll-head">
        <b>秘境余烬画卷</b>
        <small>${spec.title} · ${spec.subtitle}</small>
      </div>
      <div class="dungeon-echo-scroll-track">
        ${spec.nodes.map((node, index) => `
          <button type="button" class="dungeon-echo-scroll-node ${node.key}" data-dungeon-echo-archive="${archiveKey}" data-dungeon-echo-mode="${node.mode}" ${node.disabled ? "disabled" : ""}>
            <i>${node.rune}</i>
            <b>${index + 1}. ${node.label}</b>
            <span>${node.text}</span>
          </button>
        `).join("")}
      </div>
    </div>
  `;
}

function focusDungeonDayEchoArchiveEntry(key = "", mode = "panel") {
  const entry = dungeonDayEchoArchiveRows(8).find((row) => row.key === key) || dungeonDayEchoArchiveRows(1)[0] || null;
  if (!entry) return addLog("秘境余烬手账", "还没有可回看的秘境余烬。先在秘境里探索、撤离、失利或通关一次，手账就会落笔。");
  if (mode === "memory") {
    const page = entry.memoryKey ? dungeonMemoryPageSpec(state.dungeonCompendium?.[entry.memoryKey]) : null;
    if (page) {
      openDungeonMemoryPage(entry.memoryKey);
      addLog("秘境余烬手账", `${page.title} 已打开。这里只回看已收录回忆页，不会自动进入秘境、探索、顺应节气或挑战 Boss。`);
      return;
    }
  }
  const selector = mode === "route" ? ".dungeon-solution-triptych" : mode === "memory" ? "#goalBookPanel" : "#dungeonPanel";
  queueStoryCompassFocusTarget({
    selector,
    fallbackSelector: mode === "route" ? "#dungeonPanel" : "#goalBookPanel",
    label: "秘境余烬手账",
    log: `第 ${entry.day} 天 · ${entry.headline}：场规「${entry.fieldRule}」；精怪解法「${entry.solutionText}」；带回「${entry.rewardText}」；下一步「${entry.nextStepText}」。这里只定位/回看，不会自动进入秘境、探索、顺应节气或挑战 Boss，也不会消耗资源。`,
    panelGroup: mode === "route" || mode === "panel" ? "systems" : "core",
    missingTitle: "秘境余烬手账",
    missingLog: "对应的秘境或目标册入口暂时没有找到；这条手账只负责回看，不会自动进入秘境或消耗资源。",
  });
}

function dungeonDayEchoDaySummarySpec(summaryEcho = state.lastDungeonDayEcho, day = state.lastDaySummary?.day) {
  if (!summaryEcho) return null;
  if (day && Number(summaryEcho.day || 0) !== Number(day)) return null;
  const cards = [
    {
      key: "rule",
      label: "场规怎么变",
      title: summaryEcho.fieldRule,
      body: summaryEcho.progressText || summaryEcho.puzzleCore,
      tone: "rule",
    },
    {
      key: "solution",
      label: "精怪怎么解",
      title: summaryEcho.solutionText,
      body: summaryEcho.supportText,
      tone: summaryEcho.solutionText?.includes("推荐") ? "warn" : "good",
    },
    {
      key: "carry",
      label: "带回了什么",
      title: summaryEcho.outcomeLabel,
      body: `${summaryEcho.rewardText} · ${summaryEcho.stampText}`,
      tone: summaryEcho.tone,
    },
    {
      key: "tomorrow",
      label: "明日怎么进",
      title: summaryEcho.nextStepText,
      body: summaryEcho.outcome === "clear" ? summaryEcho.externalChangeText : summaryEcho.failureText,
      tone: summaryEcho.outcome === "clear" ? "done" : "note",
    },
  ];
  return {
    ...summaryEcho,
    title: "秘境节气余烬复盘",
    headline: `${summaryEcho.solarTerm} · ${summaryEcho.dungeonName} · ${summaryEcho.outcomeLabel}`,
    cards,
  };
}

function dungeonDayEchoDaySummaryMarkup(summaryEcho = state.lastDaySummary?.dungeonDayEcho || state.lastDungeonDayEcho) {
  const spec = dungeonDayEchoDaySummarySpec(summaryEcho, summaryEcho?.day);
  if (!spec) return "";
  return `
    <div class="day-summary-dungeon-echo ${spec.tone || "note"}">
      <div class="day-summary-dungeon-echo-head">
        <span>
          <strong>${spec.title}</strong>
          <small>${spec.headline} · ${spec.floorText}</small>
        </span>
        <em>${spec.bossText || "节气机关"}</em>
      </div>
      <div class="day-summary-dungeon-echo-grid">
        ${spec.cards.map((card) => `
          <button type="button" class="day-summary-dungeon-echo-card ${card.tone || "note"}" data-day-summary-dungeon-echo="${card.key === "tomorrow" ? "panel" : card.key === "carry" ? "memory" : "route"}">
            <b>${card.label}</b>
            <span>${card.title}</span>
            <small>${card.body}</small>
          </button>
        `).join("")}
      </div>
      <div class="day-summary-dungeon-echo-actions">
        <button type="button" data-day-summary-dungeon-echo="panel">回看秘境面板</button>
        <button type="button" data-day-summary-dungeon-echo="route">定位三联牌</button>
        <button type="button" data-day-summary-dungeon-echo="memory" ${spec.memoryKey ? "" : "disabled"}>翻回忆页</button>
      </div>
      <small>${spec.safety}</small>
    </div>
  `;
}

function focusDaySummaryDungeonEcho(mode = "panel") {
  const spec = dungeonDayEchoDaySummarySpec(state.lastDaySummary?.dungeonDayEcho || state.lastDungeonDayEcho);
  if (!spec) return addLog("秘境余烬复盘", "昨夜没有可回看的秘境节气余烬，先进入一处秘境并留下探索、撤离或通关记录。");
  if (mode === "memory") {
    const page = spec.memoryKey ? dungeonMemoryPageSpec(state.dungeonCompendium?.[spec.memoryKey]) : null;
    if (page) {
      openDungeonMemoryPage(spec.memoryKey);
      addLog("秘境余烬复盘", `${page.title} 已打开。这里只回看已收录回忆页，不会自动进入秘境、探索、顺应节气或挑战 Boss。`);
      return;
    }
    return queueStoryCompassFocusTarget({
      selector: "#goalBookPanel",
      fallbackSelector: "#goalBookPanel",
      label: "秘境节气余烬复盘",
      log: `${spec.dungeonName} 的印记还没形成可翻回忆页。先回看失败见闻和秘境三联牌，明天再手动进入秘境推进。`,
      panelGroup: "core",
      missingTitle: "秘境节气余烬复盘",
      missingLog: "目标册暂时没有找到；这条复盘只负责回看，不会自动进入秘境或消耗资源。",
    });
  }
  const selector = mode === "route" ? ".dungeon-solution-triptych" : "#dungeonPanel";
  queueStoryCompassFocusTarget({
    selector,
    fallbackSelector: "#dungeonPanel",
    label: mode === "route" ? "秘境节气余烬复盘：三联牌" : "秘境节气余烬复盘",
    log: `${spec.headline} 已定位。场规：${spec.fieldRule}；精怪解法：${spec.solutionText}；带回：${spec.rewardText}；明日：${spec.nextStepText}。${spec.safety}`,
    panelGroup: "systems",
    missingTitle: "秘境节气余烬复盘",
    missingLog: "秘境面板暂时没有找到；这条复盘只负责定位和回看，不会自动进入秘境、探索、顺应节气或挑战 Boss。",
  });
}

function solarTrialCompendiumSupport(trial) {
  const progress = dungeonCompendiumProgress();
  const termEntries = progress.entries.filter((entry) => entry.termId === trial.term_id);
  const termProgress = termEntries.reduce((sum, entry) => sum + (entry.cleared ? 40 : 0) + (entry.unlocked ? 20 : 0) + Math.min(2, Number(entry.shardCount || 0)) * 10, 0);
  const globalProgress = progress.unlocked * 4 + progress.cleared * 3;
  const markScore = Math.min(100, termProgress + globalProgress);
  const bonus = Math.min(10, Math.round(markScore / 12));
  const summary = termEntries.length > 0
    ? termEntries.map((entry) => dungeonCompendiumEntrySummary(entry)?.title || entry.stampLabel).join(" / ")
    : `全图鉴 ${progress.unlocked}/${progress.total}`;
  return {
    markScore,
    bonus,
    summary,
    termEntries,
    progress,
  };
}

function dungeonMemorySceneText(entry = {}) {
  const scenes = {
    dsm_001: "雷声刚退，三根雷木柱把湿石照成暗金，竹影像电纹一样沿碑面闪灭。",
    dsm_002: "回渠水线一段段接上，浅青色的波纹从碑脚抬起，把旧脉重新照亮。",
    dsm_003: "林间虫鸣忽强忽弱，花粉沿着弧线悬住，像一页会发声的乐谱。",
    dsm_004: "谷底的饱满灵压在碑沿慢慢流动，像刚从满溢边缘被按回去的金色潮气。",
    dsm_005: "镜湖把月白色的印纹倒映成两层，真路和倒影在碑后缓缓对齐。",
    dsm_006: "霜纹一圈圈爬上石角，中央却被一簇暖光烘开，像有人替寒气留了退路。",
    dsm_007: "残叶绕着碑座盘旋，风一翻，旧路的木牌影子就被一块块吹出来。",
    dsm_008: "七点灯火沿碑身依次连亮，像冬夜里终于接稳的一条长长影路。",
  };
  return scenes[entry.mechanicId] || `${entry.dungeonLabel || "这处秘境"} 的节气痕迹被压进了洞天的年轮碑。`;
}

function dungeonMemoryCaption(entry = {}) {
  return entry.externalChange || entry.rewardHint || entry.puzzleHint || "这段见闻已经被收进洞天年鉴。";
}

function dungeonMechanicCleared(dungeon, mechanic) {
  if (!dungeon || !mechanic) return false;
  return state.dungeonClears.has(dungeon.area_id)
    || (state.dungeonWorldChanges || []).some((entry) =>
      entry.mechanicId === mechanic.dungeon_id
      && entry.dungeonId === dungeon.area_id);
}

function dungeonWorldChangeForMechanic(dungeon, mechanic) {
  if (!dungeon || !mechanic) return null;
  return (state.dungeonWorldChanges || []).find((entry) =>
    entry.mechanicId === mechanic.dungeon_id
    && entry.dungeonId === dungeon.area_id) || null;
}

function dungeonMemoryPageSpec(entry = null) {
  if (!entry) return null;
  const resonance = solarTrialCompendiumSupport({ term_id: entry.termId });
  return {
    key: entry.key,
    title: `${entry.termLabel}回忆页 · ${entry.stampLabel}`,
    subtitle: `${entry.dungeonLabel} · ${entry.cleared ? "通关印记" : entry.unlocked ? "拼成印记" : "碎片收录"}`,
    scene: dungeonMemorySceneText(entry),
    caption: dungeonMemoryCaption(entry),
    resonance: resonance.bonus > 0 ? `同节气试炼共鸣 +${resonance.bonus}` : "同节气试炼仍待更多印记共鸣",
    footer: entry.cleared ? `Boss 已镇定 · 通关 ${entry.clearCount} 次 · 最深 ${entry.bestFloor} 层` : `碎片 ${entry.shardCount}/3 · 最深 ${entry.bestFloor} 层`,
    tag: entry.cleared ? "纪念碑已点亮" : entry.unlocked ? "年轮印记已拼成" : "碎片仍在收集",
  };
}

function dungeonCompendiumMemoryPages(limit = 4) {
  return dungeonCompendiumEntries()
    .slice()
    .sort((a, b) => Number(b.lastUpdateDay || 0) - Number(a.lastUpdateDay || 0) || Number(b.firstClearDay || 0) - Number(a.firstClearDay || 0))
    .slice(0, limit)
    .map((entry) => dungeonMemoryPageSpec(entry))
    .filter(Boolean);
}

function openDungeonMemoryPage(key = "") {
  if (state.activeCutscene) return addLog("演出进行中", "先把当前镜头看完，再翻回忆页。");
  const entry = state.dungeonCompendium?.[key];
  const page = dungeonMemoryPageSpec(entry);
  if (!page) return addLog("暂无回忆页", "先在秘境里留下至少一枚节气印记，再回来翻年鉴。");
  state.activeDungeonMemoryPage = key;
  state.activeTownLifeMemoryPage = null;
  state.activeTownLifeShopMomentPage = null;
  complete("dungeon_memory_page");
  playCue("对话翻页");
  addLog("翻开回忆页", `${page.title} 被重新摊开：${page.caption}`);
  render();
}

function closeDungeonMemoryPage() {
  if (!state.activeDungeonMemoryPage) return;
  state.activeDungeonMemoryPage = null;
  render();
}

function dungeonSeasonPrimerSpec(dungeons = availableDungeons(), term = currentTermConfig(), weather = currentWeatherConfig()) {
  const revealedRotation = dengyingRevealedRotation();
  const lanternState = syncDengyingLanternState();
  const revealUsedToday = Number(lanternState.revealUsedDay || 0) === state.day;
  const compendium = dungeonCompendiumProgress();
  const dungeonTypeText = {
    mine: "矿洞",
    herb: "药谷",
    ruin: "遗迹",
    nest: "巢穴",
  };
  const rows = (dungeons || []).map((dungeon) => {
    const mechanic = currentDungeonMechanic(dungeon);
    if (!dungeon || !mechanic) return null;
    const bossId = dungeonBossId(dungeon);
    const tone = dungeonMechanicTone(mechanic);
    const recommendedText = splitTags(mechanic.recommended_spirits || "").join(" / ") || "随行精怪";
    const rewardText = String(mechanic.main_reward || "节气材料 / 稀有线索").replace(/\|/g, " / ");
    const fieldRule = mechanic.field_rule || "节气场规正在改变入口节奏。";
    const puzzleText = mechanic.puzzle_core || "先看路线，再决定推进与撤离。";
    const stampSummary = dungeonCompendiumEntrySummary(dungeonCompendiumEntry(dungeon, mechanic));
    const failureSummary = dungeonFailureInsightSummary(dungeonFailureInsight(dungeon, mechanic));
    const worldChange = dungeonWorldChangeForMechanic(dungeon, mechanic)
      || (state.dungeonWorldChanges || []).find((entry) => entry.dungeonId === dungeon.area_id)
      || null;
    const rotation = activeHiddenRotationForDungeon(dungeon);
    const rewardPreview = rotation?.rare_drop_pool ? rewardPoolPreviewText(rotation.rare_drop_pool) : "";
    const bossSkillText = bossSkillsFor(bossId).slice(0, 2).map(skillName).join(" / ") || "待配置";
    const rowRevealed = revealedRotation?.area_id === dungeon.area_id;
    const cleared = dungeonMechanicCleared(dungeon, mechanic);
    const currentChangeText = worldChange?.title || mechanic.external_change || "洞天生态变化";
    const noteText = rowRevealed
      ? `今夜灯影已照亮隐藏入口${revealUsedToday ? "，现在去看卡面即可。" : "，点进去前先看场规和奖励焦点。"}`
      : failureSummary
        ? `${failureSummary.title}：${failureSummary.detail}`
        : stampSummary
          ? `印记进度：${stampSummary.title}`
          : "点击定位秘境卡";
    return {
      key: dungeon.area_id,
      dungeonId: dungeon.area_id,
      dungeonName: dungeonName(dungeon),
      tone,
      cleared,
      today: rowRevealed || Boolean(rotation && !cleared),
      kicker: `${mechanic.solar_term || state.term || "节气"} · ${dungeonTypeText[dungeon.dungeon_type] || dungeon.dungeon_type || "秘境"}`,
      title: `${dungeonName(dungeon)} · Boss ${bossName(bossId)}`,
      summary: `${fieldRule} · ${puzzleText}`,
      detail: `推荐 ${recommendedText} · 奖励 ${rewardText} · ${worldChange ? `已生效 ${worldChange.title}` : `打完会改 ${currentChangeText}`}${rewardPreview ? ` · 隐藏奖励 ${rewardPreview}` : ""}`,
      actionText: `${noteText} · Boss 看招 ${bossSkillText}`,
      guideText: `场规 ${fieldRule}；推荐 ${recommendedText}；奖励 ${rewardText}；${worldChange ? `当前已生效 ${worldChange.title}` : `打完会改 ${currentChangeText}`}。`,
      safety: "只定位秘境卡，不会自动进入秘境、探索、顺应节气、挑战 Boss、领取奖励或消耗资源。",
    };
  }).filter(Boolean);
  const termName = localize(term?.term_name_key, term?.term_id || currentTermId());
  const weatherName = localize(weather?.weather_name_key, weather?.weather_id || state.weatherId || "天气");
  return {
    active: rows.length > 0,
    title: "八境节气入境总览",
    headline: "进入前先看场规、推荐精怪、奖励和外部变化",
    detail: `把秘境从“能不能进”变成“为什么值得去、该带谁去、打完会改哪里”。${termName} · ${weatherName}，已收录 ${compendium.unlocked}/${compendium.total} 枚节气印记，已通关 ${compendium.cleared} 处秘境。`,
    safety: "只定位秘境卡，不会自动进入秘境、探索、顺应节气、挑战 Boss、领取奖励或消耗资源。",
    termName,
    weatherName,
    rows,
    today: rows.some((row) => row.today),
    cleared: rows.length > 0 && rows.every((row) => row.cleared),
  };
}

function dungeonSeasonPrimerMarkup(spec = dungeonSeasonPrimerSpec()) {
  if (!spec?.active) return "";
  return `
    <div class="dungeon-card dungeon-season-primer ${spec.cleared ? "cleared" : ""} ${spec.today ? "today" : ""}">
      <div class="dungeon-season-primer-head">
        <span>
          <strong>${spec.title}</strong>
          <small>${spec.headline}</small>
        </span>
        <em>${spec.termName} · ${spec.weatherName}</em>
      </div>
      <div class="dungeon-season-primer-detail">${spec.detail}</div>
      <div class="dungeon-season-primer-grid">
        ${spec.rows.map((row) => `
          <button
            type="button"
            class="dungeon-season-primer-row ${row.tone} ${row.cleared ? "cleared" : ""} ${row.today ? "today" : ""}"
            data-dungeon-season-primer="${selectorDataValue(row.key)}"
          >
            <b>${row.kicker}</b>
            <span>${row.title}</span>
            <small>${row.summary}</small>
            <small>${row.detail}</small>
            <i>${row.actionText}</i>
          </button>
        `).join("")}
      </div>
      <div class="dungeon-season-primer-safe">${spec.safety}</div>
    </div>
  `;
}

function dungeonWorldVisualType(mechanic, dungeon) {
  const external = `${mechanic?.main_reward || ""}${mechanic?.external_change || ""}`;
  if (external.includes("灯路") || external.includes("长明")) return "lantern_road";
  if (external.includes("月莲") || external.includes("静池") || external.includes("镜")) return "moon_pool";
  if (external.includes("灵渠") || external.includes("水系")) return "spirit_channel";
  if (external.includes("土壤") || external.includes("满溢")) return "rich_soil";
  if (external.includes("花蜜") || external.includes("蜂蜜")) return "flower_honey";
  if (external.includes("暖身") || external.includes("寒")) return "warm_hearth";
  if (external.includes("旧物") || external.includes("NPC")) return "old_relic";
  const text = `${mechanic?.recommended_spirits || ""}${external}${dungeon?.dungeon_type || ""}`;
  if (text.includes("雷竹") || text.includes("商路")) return "thunder_route";
  if (text.includes("灵渠") || text.includes("水位") || text.includes("水系")) return "spirit_channel";
  if (text.includes("花蜜") || text.includes("蜂蜜") || text.includes("花铃")) return "flower_honey";
  if (text.includes("土壤") || text.includes("满溢")) return "rich_soil";
  if (text.includes("月莲") || text.includes("静池") || text.includes("镜")) return "moon_pool";
  if (text.includes("暖身") || text.includes("寒")) return "warm_hearth";
  if (text.includes("旧物") || text.includes("NPC")) return "old_relic";
  if (text.includes("灯") || text.includes("长明")) return "lantern_road";
  return "spirit_mark";
}

function rareSpiritEventForMechanic(mechanic) {
  if (!mechanic) return null;
  const text = `${mechanic.recommended_spirits || ""}${mechanic.main_reward || ""}${mechanic.external_change || ""}`;
  const candidates = data.rareSpiritEvents
    .filter((event) => text.includes(event.spirit_name))
    .sort((a, b) => (a.event_stage === "first_meet" ? -1 : 1) - (b.event_stage === "first_meet" ? -1 : 1));
  if (candidates.length > 0) return candidates[0];
  if (text.includes("水系")) return data.rareSpiritEvents.find((event) => event.spirit_id === "spirit_yuelian");
  if (text.includes("花蜜")) return data.rareSpiritEvents.find((event) => event.spirit_id === "spirit_fengmi");
  return null;
}

function rareSpiritClueForEvent(event) {
  if (!event) return null;
  return (state.rareSpiritClues || []).find((clue) => clue.entryId === event.entry_id || clue.spiritId === event.spirit_id);
}

function applyDungeonWorldChange(dungeon, mechanic, bossLoot = []) {
  const key = dungeonWorldChangeKey(dungeon, mechanic);
  let change = (state.dungeonWorldChanges || []).find((entry) => entry.key === key);
  const visualType = dungeonWorldVisualType(mechanic, dungeon);
  if (!change) {
    change = {
      key,
      dungeonId: dungeon?.area_id || "",
      mechanicId: mechanic?.dungeon_id || "",
      title: mechanic?.external_change || `${dungeonName(dungeon)} 外部生态改变`,
      detail: mechanic?.puzzle_core || "秘境核心被修复，洞天出现新的可见变化。",
      rewardHint: mechanic?.main_reward || bossLoot.map((entry) => itemName(entry.itemId)).join("|"),
      visualType,
      unlockedDay: state.day,
    };
    state.dungeonWorldChanges.push(change);
    complete("dungeon_world_change");
    if (visualType === "spirit_channel") state.canalRepaired = true;
  }

  const rareEvent = rareSpiritEventForMechanic(mechanic);
  let clue = rareSpiritClueForEvent(rareEvent);
  if (rareEvent && !clue) {
    clue = {
      clueId: `clue_${rareEvent.entry_id}`,
      entryId: rareEvent.entry_id,
      spiritId: rareEvent.spirit_id,
      spiritName: rareEvent.spirit_name,
      sourceDungeonId: dungeon?.area_id || "",
      sourceMechanicId: mechanic?.dungeon_id || "",
      sceneSummary: rareEvent.scene_summary,
      exclusiveAction: rareEvent.exclusive_action,
      giftReward: rareEvent.gift_reward,
      unlockedDay: state.day,
    };
    state.rareSpiritClues.push(clue);
    complete("rare_spirit_clue");
  }

  return { change, clue };
}

function dungeonWorldChangeLandmarkLabel(change = {}) {
  const labels = {
    thunder_route: "雷竹路",
    spirit_channel: "灵渠水光",
    flower_honey: "花蜜庭",
    rich_soil: "满溢沃土",
    moon_pool: "月莲静池",
    warm_hearth: "暖身灶",
    old_relic: "旧物牌",
    lantern_road: "长灯路",
    waterway_fresh_route: "水航鲜货",
    waterway_trade_boat: "莲泽水航",
    lotus_basin_trade_return: "莲泽返货",
    lotus_basin_followup_order: "莲泽续订",
    herb_valley_gate: "药谷藤门",
    embers_gate: "炽砂断门",
    fire_core_beacon: "火位核心",
    drought_cracked_well: "主街枯井",
    drought_relief_shed: "井边水棚",
    final_nest_gate: "终巢水门",
    solar_array_stela: "终阵蓝图",
    spirit_mark: "节气印",
  };
  return labels[change.visualType] || change.title || "洞天改景";
}

function dungeonWorldChangeLandmarkAnchor(change = {}, index = 0, width = refs.world?.width || 960, height = refs.world?.height || 640) {
  const anchors = {
    thunder_route: { x: 780, y: 318 },
    spirit_channel: { x: 544, y: 412 },
    flower_honey: { x: 96, y: 318 },
    rich_soil: { x: 168, y: 210 },
    moon_pool: { x: 628, y: 506 },
    warm_hearth: { x: 502, y: 476 },
    old_relic: { x: 236, y: 424 },
    lantern_road: { x: 648, y: 142 },
    waterway_fresh_route: { x: 760, y: 498 },
    waterway_trade_boat: { x: 760, y: 498 },
    lotus_basin_trade_return: { x: 760, y: 498 },
    lotus_basin_followup_order: { x: 760, y: 498 },
    herb_valley_gate: { x: 760, y: 202 },
    embers_gate: { x: 666, y: 202 },
    fire_core_beacon: { x: 490, y: 538 },
    drought_cracked_well: { x: 694, y: 344 },
    drought_relief_shed: { x: 786, y: 354 },
    final_nest_gate: { x: 782, y: 394 },
    solar_array_stela: { x: 594, y: 186 },
  };
  const anchor = anchors[change.visualType] || {
    x: Math.max(38, Math.min(width - 170, width - 204 - index * 30)),
    y: Math.max(130, Math.min(height - 92, height - 176 - index * 34)),
  };
  return {
    x: Math.max(24, Math.min(width - 166, anchor.x)),
    y: Math.max(96, Math.min(height - 68, anchor.y)),
  };
}

function dungeonWorldChangeLandmarkTone(change = {}) {
  const type = change.visualType || "";
  if (["spirit_channel", "moon_pool", "waterway_fresh_route", "waterway_trade_boat", "lotus_basin_trade_return", "lotus_basin_followup_order"].includes(type)) return "water";
  if (["thunder_route", "lantern_road", "fire_core_beacon", "embers_gate", "warm_hearth"].includes(type)) return "ember";
  if (["flower_honey", "rich_soil", "herb_valley_gate"].includes(type)) return "good";
  if (["old_relic", "drought_cracked_well", "drought_relief_shed", "final_nest_gate", "solar_array_stela"].includes(type)) return "gold";
  return "note";
}

function dungeonWorldChangeLandmarkRows(width = refs.world?.width || 960, height = refs.world?.height || 640, limit = 4) {
  const changes = (state.dungeonWorldChanges || [])
    .filter((change) => change?.visualType && change.visualType !== "final_banquet")
    .slice()
    .sort((a, b) => Number(b.unlockedDay || 0) - Number(a.unlockedDay || 0) || String(b.key || "").localeCompare(String(a.key || "")))
    .slice(0, limit);
  return changes.map((change, index) => {
    const anchor = dungeonWorldChangeLandmarkAnchor(change, index, width, height);
    const rect = {
      x: anchor.x,
      y: anchor.y,
      width: 148,
      height: 46,
    };
    return {
      ...change,
      label: dungeonWorldChangeLandmarkLabel(change),
      tone: dungeonWorldChangeLandmarkTone(change),
      rect,
      index,
      detailText: change.rewardHint || change.detail || change.title || "秘境余波已经写进洞天主场景。",
    };
  });
}

function dungeonWorldChangeLandmarkAtCanvasPoint(px, py) {
  const rows = dungeonWorldChangeLandmarkRows();
  return rows.find((row) =>
    px >= row.rect.x
    && px <= row.rect.x + row.rect.width
    && py >= row.rect.y
    && py <= row.rect.y + row.rect.height,
  ) || null;
}

function focusDungeonWorldChangeLandmarkFromCanvas(row = null) {
  if (!row) return false;
  const selector = row.dungeonId
    ? `[data-dungeon-card-id="${selectorDataValue(row.dungeonId)}"]`
    : "#dungeonPanel";
  queueStoryCompassFocusTarget({
    selector,
    fallbackSelector: "#dungeonPanel",
    label: "秘境外部变化小景",
    log: `${row.label} 已定位：${row.title || row.detail}。来源秘境 ${row.dungeonId || "已记录"}，奖励/余波：${row.detailText}。这里只定位和解释洞天改景，不会自动进入秘境、探索、顺应节气、挑战 Boss 或消耗资源。`,
    panelGroup: "systems",
    missingTitle: "秘境外部变化小景",
    missingLog: "秘境面板暂时没有找到；洞天改景签只负责回看，不会自动进入秘境或消耗资源。",
  });
  return true;
}

function focusDungeonSeasonPrimer(rowKey = "") {
  const spec = dungeonSeasonPrimerSpec();
  const row = spec.rows.find((entry) => entry.key === rowKey) || spec.rows[0];
  if (!row) return addLog("八境节气入境总览", "当前还没有可定位的秘境卡。");
  queueStoryCompassFocusTarget({
    selector: `[data-dungeon-card-id="${selectorDataValue(row.dungeonId)}"]`,
    fallbackSelector: "#dungeonPanel",
    label: `八境节气入境总览：${row.dungeonName}`,
    log: `${row.dungeonName} 已在秘境面板高亮。${row.guideText}${row.safety}`,
    panelGroup: "systems",
    missingTitle: `八境节气入境总览：${row.dungeonName}`,
    missingLog: `${row.dungeonName} 对应的秘境卡暂时没有找到。${row.safety}`,
  });
  return true;
}

function startDungeon(areaId = availableDungeons()[0]?.area_id) {
  if (state.dungeon && !state.dungeon.finished) return addLog("秘境进行中", "先推进、挑战或撤离当前秘境。");
  const dungeon = data.dungeonsById.get(areaId);
  if (!dungeon) return addLog("秘境未开放", "当前没有可进入的秘境。");
  if (!spendStamina(10)) return;
  const mechanic = currentDungeonMechanic(dungeon);
  const lanternState = syncDengyingLanternState();
  const revealedRotation = dengyingRevealedRotation();
  const seasonalRotation = activeHiddenRotationForDungeon(dungeon);
  const hiddenRevealActive = Boolean(revealedRotation && revealedRotation.area_id === areaId && Number(lanternState.revealUsedDay || 0) !== state.day);
  const activeRotation = hiddenRevealActive ? { ...seasonalRotation, ...revealedRotation } : seasonalRotation;
  const rotationEffect = dungeonRotationEntryEffect(activeRotation);
  const rotationBossId = activeRotation?.boss_override || dungeon.boss_id;
  const bossMaxHp = dungeonBossMaxHp({ ...dungeon, boss_id: rotationBossId });
  const hiddenRevealPressureDown = hiddenRevealActive ? Math.max(2, Math.round(Number(dengyingHiddenRevealSkill()?.effect_param_1 || 1) * 4)) : 0;
  const failureInsight = dungeonFailureInsight(dungeon, mechanic);
  const failureSummary = dungeonFailureInsightSummary(failureInsight);
  if (hiddenRevealActive) lanternState.revealUsedDay = state.day;
  recordDailyIntentProgress("explore", `进入 ${dungeonName(dungeon)}`, {
    title: "秘境入场",
    amount: 2,
    target: areaId,
    rewardText: mechanic?.puzzle_core || "带回材料与节气见闻",
  });

  state.dungeon = {
    areaId,
    floor: Number(dungeon.floor_start || 1),
    maxFloor: Number(dungeon.floor_end || 1),
    hp: 100,
    bossHp: bossMaxHp,
    bossMaxHp,
    bossPhase: 1,
    bossShield: 0,
    progress: 0,
    turn: 0,
    loot: [],
    lastLoot: [],
    lastEnemyId: null,
    hazards: [],
    combatMoment: "entry",
    roomEvent: activeRotation ? `${activeRotation.note || mechanic?.puzzle_core || "辨路、战斗、带回材料。"} · ${rotationEffect.entryText}` : mechanic?.puzzle_core || "辨路、战斗、带回材料。",
    solarMechanicId: mechanic?.dungeon_id || "",
    skillLog: [],
    log: [],
    runSeed: state.day + state.completed.size + state.dungeonClears.size,
    rotationId: activeRotation?.rotation_id || "",
    rotationThemeTag: activeRotation?.theme_tag || "",
    rotationRewardFocus: activeRotation?.reward_focus || "",
    rotationEntryModifier: activeRotation?.entry_modifier || "",
    rotationRareDropPool: activeRotation?.rare_drop_pool || "",
    rotationBossId,
    rotationLabel: dungeonRotationLabel(activeRotation, dungeon),
    rotationEntryText: rotationEffect.entryText,
    rotationHazardReduce: rotationEffect.hazardReduce,
    rotationPathBonus: rotationEffect.pathBonus,
    rotationBossGuard: rotationEffect.bossGuard,
    rotationRewards: [],
    failureInsightKey: failureInsight?.key || "",
    failureInsightNote: failureInsight?.note || "",
    failureInsightPathBonus: Math.max(0, Number(failureInsight?.pathBonus || 0)),
    failureInsightRevealedFloor: Math.max(0, Number(failureInsight?.revealedFloor || 0)),
    failureInsightBossPhaseSeen: Math.max(0, Number(failureInsight?.bossPhaseSeen || 0)),
    failureInsightBossGuard: Math.max(0, Number(failureInsight?.bossGuard || 0)),
    failureInsightBossStrikeBonus: Math.max(0, Number(failureInsight?.bossStrikeBonus || 0)),
    failureInsightBossFamiliarity: Math.max(0, Number(failureInsight?.bossFamiliarity || 0)),
    failureInsightBossBestPercent: Math.max(0, Number(failureInsight?.bossBestPercent || 0)),
    failureInsightBossNextSkillName: String(failureInsight?.bossNextSkillName || ""),
    failureInsightOverflowRelief: Math.max(0, Number(failureInsight?.overflowRelief || 0)),
    mechanicState: createInitialDungeonMechanicState(mechanic, { hiddenRevealPressureDown }),
    lastMechanicActionKey: "",
    mechanicActionUses: 0,
    hiddenReveal: hiddenRevealActive,
    hiddenRevealConsumed: false,
    hiddenRevealRotationId: hiddenRevealActive ? revealedRotation.rotation_id || "" : "",
    hiddenRevealModifier: hiddenRevealActive ? revealedRotation.entry_modifier || "" : "",
    hiddenRevealThemeTag: hiddenRevealActive ? revealedRotation.theme_tag || "" : "",
    hiddenRevealRewardFocus: hiddenRevealActive ? revealedRotation.reward_focus || "" : "",
    hiddenRevealPressureDown,
    bossReady: false,
    finished: false,
  };
  state.dungeon.hazards = dungeonHazards(mechanic, state.dungeon, dungeon);
  const mechanicStatus = dungeonMechanicStatus(state.dungeon, mechanic, dungeon);
  state.completed.add(areaId);
  complete("dungeon_enter");
  addLog("进入秘境", `${dungeonName(dungeon)} 开启。${activeRotation ? `${activeRotation.note}；${rotationEffect.entryText}` : mechanic?.field_rule || "灵气紊乱，步步都要看清。"}${mechanicStatus ? ` 当前节气机制：${mechanicStatus.label} · ${mechanicStatus.summary}。` : ""}${failureSummary ? ` 失利见闻：${failureSummary.detail}。` : ""}${hiddenRevealActive ? "灯影还替你把隐藏入口提前照亮了。" : ""}`);
  scanConfiguredEvents(`dungeon:${areaId}`);
  render();
}

function exploreDungeon() {
  const run = state.dungeon;
  const dungeon = currentDungeonConfig();
  if (!run || run.finished || !dungeon) return addLog("未在秘境", "先选择一处秘境进入。");
  if (run.bossReady) return addLog("Boss 已现身", "秘境深处已经锁定，现在应挑战 Boss 或撤离。");
  if (!spendStamina(8)) return;

  const enemies = dungeonEnemies(dungeon);
  const enemy = enemies[(run.floor + state.day + run.progress) % Math.max(enemies.length, 1)];
  const mechanic = currentDungeonMechanic(dungeon);
  const hazards = dungeonHazards(mechanic, { ...run, lastEnemyId: enemy?.enemy_id }, dungeon);
  const supportSkill = spiritCombatSkills()[0];
  const supportText = supportSkill ? `；${skillName(supportSkill)} 提供随行压制` : "";
  const spiritPower = companionPower();
  const hazardPressure = dungeonHazardPressure(hazards);
  const solutionSpec = dungeonSpiritSolutionSpec(run, mechanic, dungeon);
  const solutionLog = dungeonSpiritSolutionLogText(solutionSpec, "explore");
  const mechanicBonus = solutionSpec?.advantage || 0;
  const mechanicEffects = dungeonMechanicEffects(run, mechanic, dungeon, "explore");
  const rotationHazardReduce = Number(run.rotationHazardReduce || 0);
  const rotationPathBonus = Number(run.rotationPathBonus || 0);
  const hiddenRevealPressureDown = run.hiddenReveal && !run.hiddenRevealConsumed ? Number(run.hiddenRevealPressureDown || 0) : 0;
  const failureInsightPathBonus = run.floor <= Math.max(1, Number(run.failureInsightRevealedFloor || 0)) ? Number(run.failureInsightPathBonus || 0) : 0;
  const failureInsightOverflowRelief = mechanic?.dungeon_id === "dsm_004" ? Number(run.failureInsightOverflowRelief || 0) : 0;
  const explorePlan = dungeonRuntime()?.dungeonExplorePlan({
    enemy,
    hazardPressure,
    spiritPower,
    mechanicBonus,
    rotationHazardReduce,
    rotationPathBonus,
    hiddenRevealPressureDown,
    failureInsightPathBonus,
    failureInsightOverflowRelief,
    mechanicEffects,
  }) || (() => {
    const fallbackEnemyPower = Math.max(8, Number(enemy?.atk || 16) + Number(enemy?.def || 6) + hazardPressure - spiritPower - mechanicBonus - rotationHazardReduce - rotationPathBonus - hiddenRevealPressureDown - failureInsightPathBonus - failureInsightOverflowRelief - mechanicEffects.enemyPowerDown);
    return {
      enemyPower: fallbackEnemyPower,
      damage: Math.max(4, Math.round(fallbackEnemyPower / 4) + mechanicEffects.damageUp - mechanicEffects.damageDown),
    };
  })();
  const enemyPower = explorePlan.enemyPower;
  const damage = explorePlan.damage;
  const loot = rollLoot(enemy?.drop_pool_id || dungeon.resource_group_id, run.floor, mechanicEffects.lootMultiplier);
  const lootText = loot.map((entry) => `${itemName(entry.itemId)} x${entry.count}`).join("、") || "少量灵砂";
  const exploreStatePlan = dungeonRuntime()?.dungeonExploreStatePlan({
    hp: run.hp,
    damage,
    progress: run.progress,
    turn: run.turn,
    enemyId: enemy?.enemy_id || null,
    lootCount: loot.length,
  }) || null;
  run.hp = Number(exploreStatePlan?.hpAfter ?? Math.max(0, run.hp - damage));
  run.loot.push(...loot);
  recordDailyIntentProgress("explore", `${dungeonName(dungeon)} 推进一层`, {
    title: "秘境推进",
    amount: 2,
    target: dungeon.area_id,
    rewardText: lootText,
  });
  run.lastLoot = loot;
  run.lastEnemyId = exploreStatePlan?.lastEnemyId ?? enemy?.enemy_id ?? null;
  run.hazards = hazards;
  run.roomEvent = `${mechanic?.puzzle_core || "观察路线"} · ${hazards[0]?.label || "灵雾扰动"}`;
  run.combatMoment = exploreStatePlan?.combatMoment || (damage >= 16 ? "danger" : loot.length > 0 ? "loot" : "steady");
  run.progress = Number(exploreStatePlan?.progressAfter ?? run.progress + 1);
  run.turn = Number(exploreStatePlan?.turnAfter ?? run.turn + 1);
  const mechanicNote = advanceDungeonMechanicState(run, mechanic, dungeon, "explore");
  if (hiddenRevealPressureDown > 0) run.hiddenRevealConsumed = true;
  run.skillLog.unshift(`随行技能：${supportSkill ? skillName(supportSkill) : "基础协同"}，战力 ${spiritPower}${solutionLog ? `，${solutionLog}` : mechanicBonus ? `，精怪解法 +${mechanicBonus}` : ""}${rotationPathBonus > 0 ? `，隐藏层辨路 +${rotationPathBonus}` : ""}${rotationHazardReduce > 0 ? `，入口减压 -${rotationHazardReduce}` : ""}${hiddenRevealPressureDown > 0 ? `，灯影照路 -${hiddenRevealPressureDown}` : ""}${failureInsightPathBonus > 0 ? `，旧见闻减压 -${failureInsightPathBonus}` : ""}${failureInsightOverflowRelief > 0 ? `，满溢记忆 -${failureInsightOverflowRelief}` : ""}${mechanicEffects.enemyPowerDown > 0 ? `，机制压场 -${mechanicEffects.enemyPowerDown}` : ""}${mechanicEffects.lootMultiplier > 1 ? `，掉落 +${Math.round((mechanicEffects.lootMultiplier - 1) * 100)}%` : ""}`);
  run.skillLog = run.skillLog.slice(0, 5);
  run.log.unshift(`${run.floor} 层遭遇 ${enemyName(enemy)}（${enemyAiLabel(enemy)}，弱点 ${enemyWeaknessText(enemy)}），${run.rotationEntryText ? `${run.rotationEntryText}` : ""}${hiddenRevealPressureDown > 0 ? "灯影先把入口照亮，开局压力被削去一截，" : ""}${hazards[0]?.label || "灵雾"}造成额外压力，损失 ${damage} HP${supportText}${solutionLog ? `；${solutionLog}` : ""}，获得 ${lootText}。${mechanicNote ? ` ${mechanicNote}` : ""}`);

  if (state.spirits[0]) {
    state.spirits[0].stamina = Math.max(0, (state.spirits[0].stamina || 0) - 8);
    addBondExp(state.spirits[0], 2, "随行秘境");
    addJobExp(state.spirits[0], "expedition", 2, "秘境随行");
  }

  const exploreOutcomePlan = dungeonRuntime()?.dungeonExploreOutcomePlan({
    hp: run.hp,
    floor: run.floor,
    maxFloor: run.maxFloor,
    stamina: state.stamina,
  }) || null;

  if (exploreOutcomePlan?.outcome === "failed" || run.hp <= 0) {
    run.finished = Boolean(exploreOutcomePlan?.finished ?? true);
    run.combatMoment = exploreOutcomePlan?.combatMoment || "failed";
    state.stamina = Number(exploreOutcomePlan?.staminaAfter ?? Math.max(25, state.stamina - 12));
    const failurePlan = dungeonRuntime()?.dungeonFailureRewardPlan({
      outcome: "explore_failed",
      mechanicId: mechanic?.dungeon_id || "",
      overflow: run.mechanicState?.overflow || 0,
      floor: run.floor,
    }) || null;
    const failureReason = failurePlan?.failureReason || (mechanic?.dungeon_id === "dsm_004" && Number(run.mechanicState?.overflow || 0) >= 4 ? "overflow" : "battle");
    const failureInsight = recordDungeonFailureInsight(failureReason, run, dungeon, mechanic);
    const stampGain = grantDungeonCompendiumProgress(failurePlan?.stampKind || "shard", Number(failurePlan?.stampAmount ?? (failureReason === "overflow" ? 2 : run.floor >= 3 ? 2 : 1)), run, dungeon, mechanic);
    addLog("秘境撤退", `${mechanic?.failure_compensation || "你保住了已带出的掉落。"} ${failureInsight?.note || "下次进入会更容易读懂机关。"} ${stampGain ? `节气印记：${stampGain.text}。` : ""}`);
    recordDungeonDayEcho("failed", run, dungeon, mechanic, {
      loot,
      rewardText: lootText,
      failureInsight,
      stampGain,
    });
  } else if (exploreOutcomePlan?.outcome === "boss_ready" || run.floor >= run.maxFloor) {
    run.bossReady = Boolean(exploreOutcomePlan?.bossReady ?? true);
    run.hazards = dungeonHazards(mechanic, run, dungeon);
    run.combatMoment = exploreOutcomePlan?.combatMoment || "boss_ready";
    const bossId = dungeonBossId(dungeon, run);
    const nextSkill = bossSkillForTurn(bossId, run.turn, bossHpPercent(run, dungeon));
    const telegraph = dungeonBossTelegraphSpec(nextSkill, bossId, run);
    triggerDungeonFeedback("boss_warning", {
      mechanic,
      label: telegraph ? `下一招 · ${telegraph.skillLabel}` : `${bossName(bossId)} 已现身`,
      detail: telegraph ? `${telegraph.targetLabel} · 前摇 ${telegraph.castLabel} · ${telegraph.effectLabel}` : "Boss 气息已经压到洞口。",
      ...dungeonSpiritSolutionFeedbackFields(solutionSpec),
      targetRule: nextSkill?.target_rule || "",
      castTime: Number(nextSkill?.cast_time_sec || 0),
      danger: telegraph?.pressure || 0,
      phase: run.bossPhase || 1,
      duration: 1320,
    });
    addLog("秘境深处", `${dungeonName(dungeon)} 的 Boss 气息已经压到洞口。`);
    recordDungeonDayEcho("boss_ready", run, dungeon, mechanic, {
      loot,
      rewardText: lootText,
      bossId,
    });
  } else {
    run.floor = Number(exploreOutcomePlan?.floorAfter ?? run.floor + 1);
    triggerDungeonFeedback(run.combatMoment === "danger" ? "hazard" : "explore", {
      mechanic,
      label: run.combatMoment === "danger" ? `险象 · ${hazards[0]?.label || "灵雾压场"}` : `推进至第 ${run.floor} 层`,
      detail: solutionLog ? `${solutionLog}；${mechanicNote || run.roomEvent || `${dungeonName(dungeon)} 的路还在往前开。`}` : mechanicNote || run.roomEvent || `${dungeonName(dungeon)} 的路还在往前开。`,
      ...dungeonSpiritSolutionFeedbackFields(solutionSpec),
      danger: hazards[0]?.severity || 0,
      duration: run.combatMoment === "danger" ? 1140 : 920,
    });
    addLog("秘境推进", `${dungeonName(dungeon)} 推进到第 ${run.floor} 层。`);
    recordDungeonDayEcho("explore", run, dungeon, mechanic, {
      loot,
      rewardText: lootText,
      nextStepText: `明天可继续从第 ${run.floor} 层节奏判断推进、撤离或改带推荐精怪。`,
    });
  }

  complete("dungeon_explore");
  render();
}

function challengeDungeonBoss() {
  const run = state.dungeon;
  const dungeon = currentDungeonConfig();
  if (!run || run.finished || !dungeon) return addLog("未在秘境", "先进入秘境。");
  if (!run.bossReady) return addLog("Boss 未现身", "先探索到秘境最深处。");
  if (!spendStamina(14)) return;

  const bossId = dungeonBossId(dungeon, run);
  const boss = data.bossesById.get(bossId);
  run.bossMaxHp = run.bossMaxHp || dungeonBossMaxHp(dungeon, run);
  run.bossHp = Math.min(run.bossMaxHp, run.bossHp ?? run.bossMaxHp);
  const beforePercent = bossHpPercent(run, dungeon);
  const bossSkill = bossSkillForTurn(bossId, run.turn, beforePercent);
  const phase = bossPhaseForPercent(bossId, beforePercent);
  const supportSkill = spiritCombatSkills()[0];
  const spiritPower = companionPower();
  const mechanic = currentDungeonMechanic(dungeon);
  const solutionSpec = dungeonSpiritSolutionSpec(run, mechanic, dungeon);
  const solutionBossLog = dungeonSpiritSolutionLogText(solutionSpec, "boss");
  const mechanicEffects = dungeonMechanicEffects(run, mechanic, dungeon, "boss");
  const rotationBossGuard = Number(run.rotationBossGuard || 0);
  const rotationPathBonus = Number(run.rotationPathBonus || 0);
  const failureInsightBossGuard = Number(run.failureInsightBossGuard || 0);
  const failureInsightBossStrikeBonus = Number(run.failureInsightBossStrikeBonus || 0);
  const hazards = dungeonHazards(mechanic, run, dungeon);
  const hazardPressure = dungeonHazardPressure(hazards);
  const exchangePlan = dungeonRuntime()?.dungeonBossExchangePlan({
    boss,
    bossSkill,
    supportSkill,
    bossShield: run.bossShield,
    phase,
    maxFloor: run.maxFloor,
    spiritPower,
    hazardPressure,
    rotationBossGuard,
    rotationPathBonus,
    failureInsightBossGuard,
    failureInsightBossStrikeBonus,
    mechanicEffects,
  }) || (() => {
    const bossPressure = Math.max(20, Math.round(Number(boss?.hp_total || 1200) / 90) + Number(boss?.phase_count || 1) * 6);
    const skillPressure = skillImpact(bossSkill);
    const supportGuard = supportSkill ? Math.max(2, Math.round(Number(supportSkill.effect_param_1 || 1) * 4)) : 0;
    const baseStrike = 260 + run.maxFloor * 28 + Math.round(spiritPower * 7) + rotationPathBonus * 8 + failureInsightBossStrikeBonus + mechanicEffects.strikeBonus + (supportSkill?.effect_type === "combat" ? Math.round(Number(supportSkill.effect_param_1 || 1) * 90) : 0);
    const shieldAfterSkill = bossSkill?.effect_type === "shield" ? Math.max(run.bossShield || 0, Number(bossSkill.effect_param_1 || 0)) : Number(run.bossShield || 0);
    const absorbed = Math.min(shieldAfterSkill, Math.round(baseStrike * 0.45));
    return {
      bossPressure,
      skillPressure,
      supportGuard,
      damage: Math.max(8, bossPressure + skillPressure + hazardPressure - Math.round(spiritPower / 3) - supportGuard - rotationBossGuard - failureInsightBossGuard - mechanicEffects.bossGuard + mechanicEffects.damageUp - mechanicEffects.damageDown),
      baseStrike,
      shieldAfterSkill,
      absorbed,
      bossShieldAfter: Math.max(0, shieldAfterSkill - absorbed),
      bossDamage: Math.max(80, baseStrike - absorbed - phase * 12),
    };
  })();
  const supportGuard = exchangePlan.supportGuard;
  const damage = exchangePlan.damage;
  const absorbed = exchangePlan.absorbed;
  const bossDamage = exchangePlan.bossDamage;
  const exchangeStatePlan = dungeonRuntime()?.dungeonBossExchangeStatePlan({
    bossId,
    hp: run.hp,
    bossHp: run.bossHp,
    bossMaxHp: run.bossMaxHp,
    bossShieldAfter: exchangePlan.bossShieldAfter,
    turn: run.turn,
    phaseBefore: phase,
    damage,
    bossDamage,
  }) || null;
  run.bossShield = Number(exchangeStatePlan?.bossShieldAfter ?? exchangePlan.bossShieldAfter);
  run.bossHp = Number(exchangeStatePlan?.bossHpAfter ?? Math.max(0, run.bossHp - bossDamage));
  run.hp = Number(exchangeStatePlan?.hpAfter ?? Math.max(0, run.hp - damage));
  run.turn = Number(exchangeStatePlan?.turnAfter ?? run.turn + 1);
  run.bossPhase = Number(exchangeStatePlan?.bossPhaseAfter ?? bossPhaseForPercent(bossId, bossHpPercent(run, dungeon)));
  run.lastBossSkillId = bossSkill?.boss_skill_id || "";
  run.lastBossSkillName = skillName(bossSkill);
  const usedTelegraph = dungeonBossTelegraphSpec(bossSkill, bossId, run);
  const mechanicNote = advanceDungeonMechanicState(run, mechanic, dungeon, "boss");
  run.hazards = dungeonHazards(mechanic, run, dungeon);
  run.combatMoment = exchangeStatePlan?.combatMoment || (run.bossHp <= 0 ? "boss_defeat" : run.hp <= 0 ? "failed" : phase !== run.bossPhase ? "phase_shift" : "boss_exchange");
  run.skillLog.unshift(`${bossName(bossId)} P${phase} 使用 ${skillName(bossSkill)}（${bossSkill?.target_rule || "pressure"}），${supportSkill ? `${skillName(supportSkill)} 抵消 ${supportGuard}` : "无精怪技能抵消"}${solutionBossLog ? `，${solutionBossLog}` : ""}${rotationBossGuard > 0 ? `，隐藏层卸力 ${rotationBossGuard}` : ""}${failureInsightBossGuard > 0 ? `，失利见闻稳场 ${failureInsightBossGuard}` : ""}${failureInsightBossStrikeBonus > 0 ? `，Boss 熟悉度反击 +${failureInsightBossStrikeBonus}` : ""}${mechanicEffects.bossGuard > 0 ? `，节气稳场 ${mechanicEffects.bossGuard}` : ""}，你反击 ${bossDamage} 点${absorbed ? `，护盾吸收 ${absorbed}` : ""}，自身损失 ${damage} HP。应对：${usedTelegraph?.counterMove || "看地面前摇。"} `);
  run.skillLog = run.skillLog.slice(0, 5);
  run.log.unshift(`Boss 交锋：${skillName(bossSkill)} 前摇 ${bossSkill?.cast_time_sec || "?"} 秒，${bossName(bossId)} 剩余 ${Math.ceil(bossHpPercent(run, dungeon) * 100)}%。${solutionBossLog ? ` ${solutionBossLog}。` : ""}${mechanicNote ? ` ${mechanicNote}` : ""}`);
  run.log = run.log.slice(0, 6);

  if (run.hp <= 0 && run.bossHp > 0) {
    const failurePlan = dungeonRuntime()?.dungeonFailureRewardPlan({ outcome: "boss_failed" }) || null;
    run.finished = Boolean(failurePlan?.finished ?? true);
    const failureInsight = recordDungeonFailureInsight(failurePlan?.failureReason || "boss", run, dungeon, mechanic);
    const stampGain = grantDungeonCompendiumProgress(failurePlan?.stampKind || "shard", Number(failurePlan?.stampAmount ?? 2), run, dungeon, mechanic);
    addLog("Boss 战失利", `${bossName(bossId)} 以 ${skillName(bossSkill)} 把你逼退。${mechanic?.failure_compensation || "已发现的 Boss 阶段会保留在日志里。"} ${failureInsight?.note || "带上精怪、提升羁绊后再来。"} ${stampGain ? `节气印记：${stampGain.text}。` : ""}`);
    recordDungeonDayEcho("boss_failed", run, dungeon, mechanic, {
      failureInsight,
      stampGain,
      bossId,
      nextStepText: `明天先盯防 ${skillName(bossSkill)}，再手动决定是否挑战 ${bossName(bossId)}。`,
    });
    render();
    return;
  }

  if (run.bossHp > 0) {
    const nextSkill = bossSkillForTurn(bossId, run.turn, bossHpPercent(run, dungeon));
    const nextTelegraph = dungeonBossTelegraphSpec(nextSkill, bossId, run);
    triggerDungeonFeedback(run.combatMoment === "phase_shift" ? "boss_phase" : "boss_warning", {
      mechanic,
      label: run.combatMoment === "phase_shift" ? `${bossName(bossId)} 转入 P${run.bossPhase}` : nextTelegraph ? `下一招 · ${nextTelegraph.skillLabel}` : `${bossName(bossId)} 继续压场`,
      detail: nextTelegraph ? `${nextTelegraph.targetLabel} · 前摇 ${nextTelegraph.castLabel} · ${nextTelegraph.effectLabel}` : `当前阶段 P${run.bossPhase}。`,
      ...dungeonSpiritSolutionFeedbackFields(solutionSpec),
      targetRule: nextSkill?.target_rule || "",
      castTime: Number(nextSkill?.cast_time_sec || 0),
      danger: nextTelegraph?.pressure || 0,
      phase: run.bossPhase,
      duration: 1360,
    });
    addLog("Boss 交锋", `${bossName(bossId)} 剩余 ${Math.ceil(bossHpPercent(run, dungeon) * 100)}%，当前阶段 P${run.bossPhase}。${nextSkill ? `注意下一次 ${skillName(nextSkill)}。` : "下一招还在变招。"} `);
    complete("dungeon_boss_exchange");
    render();
    return;
  }

  const bossLoot = rollLoot(dungeon.resource_group_id, run.maxFloor + 1, mechanicEffects.lootMultiplier);
  const clearPlan = dungeonRuntime()?.dungeonBossClearPlan({
    areaId: dungeon.area_id,
    bossId,
    bossLoot,
    hasBaizhiMotherDew: hasItem(BAIZHI_MOTHER_DEW_ITEM_ID, 1),
    hasFireCore: hasItem(FIRE_CORE_ITEM_ID, 1),
    hasDinghaiItem: hasItem(CHAPTER_4_DINGHAI_ITEM_ID, 1),
  }) || (() => {
    const guaranteedLoot = [];
    if (bossId === BAIZHI_BOSS_ID && !hasItem(BAIZHI_MOTHER_DEW_ITEM_ID, 1)) guaranteedLoot.push({ itemId: BAIZHI_MOTHER_DEW_ITEM_ID, count: 1 });
    if (bossId === FIRE_RUIN_BOSS_ID && !hasItem(FIRE_CORE_ITEM_ID, 1)) guaranteedLoot.push({ itemId: FIRE_CORE_ITEM_ID, count: 1 });
    if (bossId === CHAPTER_4_FINAL_BOSS_ID && !hasItem(CHAPTER_4_DINGHAI_ITEM_ID, 1)) guaranteedLoot.push({ itemId: CHAPTER_4_DINGHAI_ITEM_ID, count: 1 });
    const fallbackLoot = [...bossLoot, ...guaranteedLoot];
    return {
      finished: true,
      fameDelta: 5,
      clearAreaId: dungeon.area_id,
      defeatedBossId: bossId,
      guaranteedLoot,
      bossLoot: fallbackLoot,
      lastLoot: fallbackLoot,
    };
  })();
  for (const entry of clearPlan?.guaranteedLoot || []) addItem(entry.itemId, entry.count);
  const finalBossLoot = clearPlan?.bossLoot || bossLoot;
  run.loot.push(...finalBossLoot);
  run.lastLoot = clearPlan?.lastLoot || finalBossLoot;
  run.finished = Boolean(clearPlan?.finished ?? true);
  state.dungeonClears.add(clearPlan?.clearAreaId || dungeon.area_id);
  state.defeatedBosses.add(clearPlan?.defeatedBossId || bossId);
  state.fame += Number(clearPlan?.fameDelta ?? 5);
  recordDailyIntentProgress("explore", `击破 ${bossName(bossId)}`, {
    title: "Boss 击破",
    amount: 6,
    target: dungeon.area_id,
    rewardText: `声望 +5 · ${finalBossLoot.map((entry) => `${itemName(entry.itemId)} x${entry.count}`).join("、") || "秘境余波"}`,
  });
  const sideEffectPlan = dungeonRuntime()?.dungeonPostBattleSideEffectPlan({
    areaId: dungeon.area_id,
    bossId,
    termId: currentTermId(),
  }) || {
    completionKeys: ["dungeon"],
    seasonalGoal: currentTermId() === "term_dongzhi" ? { category: "seasonal", key: "lanternDungeonClears", amount: 1 } : null,
    storyHooks: [
      bossId === BAIZHI_BOSS_ID ? "herb_valley_baizhi_finish" : "",
      bossId === FIRE_RUIN_BOSS_ID ? "fire_ruin_finish" : "",
      bossId === CHAPTER_4_FINAL_BOSS_ID ? "chapter4_pantao_finale" : "",
    ].filter(Boolean),
    cohabEvent: { trigger: "on_dungeon_return", areaId: dungeon.area_id },
  };
  const rotationRewards = run.rotationRareDropPool ? resolveDungeonRewardPool(run.rotationRareDropPool, run.hiddenReveal ? 1.25 : 1) : [];
  const rotationRewardItems = rotationRewards
    .filter((entry) => entry.itemId && entry.count > 0)
    .map((entry) => ({ itemId: entry.itemId, count: entry.count }));
  if (rotationRewardItems.length > 0) {
    run.loot.push(...rotationRewardItems);
    run.lastLoot = [...finalBossLoot, ...rotationRewardItems];
  }
  run.rotationRewards = rotationRewards.map((entry) => entry.text);
  const stampGain = grantDungeonCompendiumProgress("clear", 3, run, dungeon, mechanic);
  const aftermath = applyDungeonWorldChange(dungeon, mechanic, finalBossLoot);
  const postBattleActions = applyDungeonPostBattleSideEffectPlan(sideEffectPlan, dungeon, bossId);
  addLog("Boss 击破", `${bossName(bossId)} 已击败，最后化解了 ${skillName(bossSkill)}。${stampGain ? `；${stampGain.text}` : ""}${aftermath.change?.title || `${dungeonName(dungeon)} 外部生态发生变化。`}${aftermath.clue ? `；发现 ${aftermath.clue.spiritName} 线索：${aftermath.clue.sceneSummary}` : ""}${rotationRewards.length > 0 ? `；隐藏层回响：${rotationRewards.map((entry) => entry.text).join("、")}` : ""} 声望 +5。`);
  recordDungeonDayEcho("clear", run, dungeon, mechanic, {
    bossLoot: run.lastLoot || finalBossLoot,
    stampGain,
    aftermath,
    bossId,
    rotationRewards: rotationRewards.map((entry) => entry.text),
    postBattleActions,
  });
  render();
}

function leaveDungeon() {
  if (!state.dungeon) return addLog("不在秘境", "当前没有正在探索的秘境。");
  const run = state.dungeon;
  const dungeon = currentDungeonConfig();
  const mechanic = currentDungeonMechanic(dungeon);
  const failurePlan = dungeonRuntime()?.dungeonFailureRewardPlan({
    outcome: "retreat",
    mechanicId: mechanic?.dungeon_id || "",
    overflow: run.mechanicState?.overflow || 0,
    bossReady: run.bossReady,
    finished: run.finished,
    progress: run.progress,
    alreadyCleared: state.dungeonClears.has(run.areaId),
  }) || null;
  const shouldRecord = failurePlan?.shouldRecord ?? (!run.finished && Number(run.progress || 0) > 0 && !state.dungeonClears.has(run.areaId));
  const failureInsight = shouldRecord
    ? recordDungeonFailureInsight(failurePlan?.failureReason || (mechanic?.dungeon_id === "dsm_004" && Number(run.mechanicState?.overflow || 0) >= 4 ? "overflow" : "retreat"), run, dungeon, mechanic)
    : null;
  const stampGain = shouldRecord ? grantDungeonCompendiumProgress(failurePlan?.stampKind || "shard", Number(failurePlan?.stampAmount ?? (run.bossReady ? 2 : 1)), run, dungeon, mechanic) : null;
  state.dungeon.finished = Boolean(failurePlan?.finished ?? true);
  addLog("撤离秘境", `你带着已有掉落回到洞天，下一次可以重新进入。${failureInsight?.note ? ` ${failureInsight.note}` : ""}${stampGain ? ` 节气印记：${stampGain.text}。` : ""}`);
  if (shouldRecord) {
    recordDungeonDayEcho("retreat", run, dungeon, mechanic, {
      loot: run.loot || [],
      failureInsight,
      stampGain,
    });
  }
  render();
}

function favorLevel(value) {
  const runtimeLevel = npcRuntime()?.favorLevel(value);
  if (Number.isFinite(runtimeLevel)) return runtimeLevel;
  if (value >= 100) return 5;
  if (value >= 70) return 4;
  if (value >= 45) return 3;
  if (value >= 20) return 2;
  if (value >= 5) return 1;
  return 0;
}

function addNpcFavor(npcId, value, source) {
  if (!npcId || Number(value) <= 0) return;
  const before = state.npcFavor[npcId] || 0;
  const after = Math.min(100, before + Number(value));
  const beforeLevel = favorLevel(before);
  const afterLevel = favorLevel(after);
  state.npcFavor[npcId] = after;
  addLog("好感提升", `${npcName(npcId)} 因${source}好感 +${value}，当前 ${after}/100。`);
  checkFavorRewards(npcId);
  if (npcId === "npc_baizhi" && baizhiQuestGuidanceActive() && beforeLevel < 2 && afterLevel >= 2) {
    state.completed.add("baizhi_shihu_favor_ready");
    if (!state.activeDialogue.some((line) => line.groupId === "dialogue_baizhi_favor_2") && !queuedDialogueGroups.includes("dialogue_baizhi_favor_2")) {
      queueDialogueGroup("dialogue_baizhi_favor_2");
    }
    triggerBaizhiQuestStageFeedback("favor_ready");
  }
  updateMissions();
  checkQuestRewards();
  scanConfiguredEvents(`favor:${npcId}`);
  scanTownLifeRelationshipMemories(npcId);
}

function unlockFavorQuest(questId, npcId) {
  if (!questId) return `任务 ${questId}`;
  const mainQuest = data.quests.find((entry) => entry.quest_id === questId);
  if (mainQuest) {
    state.completed.add(`quest_unlock_${questId}`);
    return `主线线索 ${questTitle(mainQuest)}`;
  }
  const sideQuest = data.sideQuests.find((entry) => entry.quest_id === questId);
  if (sideQuest) {
    const alreadyActive = state.activeSideQuests.has(questId);
    state.activeSideQuests.add(questId);
    if (!alreadyActive) triggerSideQuestPresentation(questId, "after_accept");
    return alreadyActive ? `支线线索 ${questTitle(sideQuest)}` : `支线开启 ${questTitle(sideQuest)}`;
  }
  state.completed.add(`quest_unlock_${questId}`);
  return `${npcName(npcId)} 的后续任务线索已记下`;
}

function applyFavorReward(npcId, reward) {
  const count = Math.max(1, Number(reward.reward_count || 1));
  if (reward.reward_type === "scene") {
    const hasDialogue = (data.dialoguesByGroup.get(reward.reward_param) || []).length > 0;
    if (!hasDialogue) {
      state.completed.add(`scene_${reward.reward_param}`);
      return `剧情线索 ${reward.reward_param}`;
    }
    const extraQuest = npcId === "npc_qinghe" && reward.reward_param === "dialogue_qinghe_favor_1"
      ? unlockFavorQuest("quest_side_0205_qinghe_pond", npcId)
      : "";
    if (npcId === "npc_qinghe" && reward.reward_param === "dialogue_qinghe_favor_3") {
      syncPondState();
      state.pondState.waterControlUnlocked = true;
      state.pondState.waterControlMastery = true;
      complete("pond_water_mastery");
    }
    const queued = queueDialogueGroup(reward.reward_param);
    return `${queued ? "对白已接上" : "对白待播"}：${localize(`${reward.reward_param}_001`, reward.reward_param)}${extraQuest ? ` · ${extraQuest}` : ""}`;
  }
  if (reward.reward_type === "item") {
    addItem(reward.reward_param, count);
    return `${itemName(reward.reward_param)} x${count}`;
  }
  if (reward.reward_type === "recipe") {
    state.completed.add(`recipe_${reward.reward_param}`);
    return `配方解锁 ${reward.reward_param}`;
  }
  if (reward.reward_type === "quest") {
    return unlockFavorQuest(reward.reward_param, npcId);
  }
  if (reward.reward_type === "building") {
    state.completed.add(`building_unlock_${reward.reward_param}`);
    return `建筑许可 ${buildingName(data.buildingsById.get(reward.reward_param) || reward.reward_param)}`;
  }
  if (reward.reward_type === "discount") {
    state.completed.add(`discount_${reward.reward_param}`);
    return `关系折扣 ${reward.reward_param}`;
  }
  return favorRewardSummary(reward);
}

function checkFavorRewards(npcId) {
  const rewardPlan = npcRuntime()?.claimableFavorRewards({
    npcId,
    favorValue: state.npcFavor[npcId] || 0,
    rewards: data.favorRewards,
    claimedRewardIds: [...state.claimedFavorRewards],
  }) || {
    level: favorLevel(state.npcFavor[npcId] || 0),
    rewards: data.favorRewards.filter((entry) => entry.npc_id === npcId)
      .filter((reward) => Number(reward.favor_level) <= favorLevel(state.npcFavor[npcId] || 0) && !state.claimedFavorRewards.has(reward.reward_id)),
    rewardIds: [],
  };
  for (const reward of rewardPlan.rewards) {
    state.claimedFavorRewards.add(reward.reward_id);
    const text = applyFavorReward(npcId, reward);
    addLog("关系奖励", `${npcName(npcId)} Lv.${reward.favor_level} 解锁：${text}`);
  }
}

function townDailyClockMinute(day = state.day) {
  return 360 + ((Math.max(1, Number(day || 1)) * 90) % 720);
}

function clockMinuteText(minute = townDailyClockMinute()) {
  const safeMinute = Math.max(0, Math.min(1439, Number(minute || 0)));
  const hour = Math.floor(safeMinute / 60);
  const rest = safeMinute % 60;
  return `${String(hour).padStart(2, "0")}:${String(rest).padStart(2, "0")}`;
}

function scheduleActionLabel(schedule) {
  const actionParam = schedule?.action_param || "";
  const paramLabels = {
    town_affairs: "翻镇务簿",
    inspect_bridge_and_stalls: "巡看桥头摊位",
    public_meeting: "听街坊报事",
    drought_relief: "调度井水救急",
    forge_tools: "锻农具",
    upgrade_orders: "核工坊升级单",
    drink_and_repair: "温酒修旧镰",
    clinic_diagnosis: "坐堂问诊",
    medicine_brewing: "煎药看火",
    emergency_treatment: "处理暑热急症",
    storytelling: "讲一段镇口旧闻",
    collect_rumors: "收街巷传闻",
    host_festival_story: "主持冬至灯故事",
    open_trade_booth: "支起客商货摊",
    leave_for_route: "清点远行货箱",
    not_spawned_before_ch2: "尚未到镇",
    woodworking: "刨木开榫",
    check_build_sites: "量新屋地基",
    sketch_furniture: "画家具草图",
    fish_and_water_check: "验河水与鱼线",
    dew_collection_teach: "教白露采露",
    inspect_waterline: "沿旧渠巡水线",
    meditation: "闭目调息",
    sword_drill: "练一套静剑",
    quiet_conversation: "在灯下听人说话",
  };
  const typeLabels = {
    work: "忙活",
    walk: "巡走",
    idle: "歇脚",
    talk: "闲谈",
    festival: "节庆",
  };
  return paramLabels[actionParam] || typeLabels[schedule?.action_type] || schedule?.action_type || "日常";
}

function schedulePriority(schedule, termId = currentTermId(), weather = currentWeatherConfig()) {
  const runtimePlan = npcRuntime()?.schedulePriority(schedule, {
    termId,
    season: currentTermConfig()?.season,
    weatherId: weather?.weather_id,
    disasterTag: weather?.disaster_tag,
    droughtActive: chapter4DroughtActive(),
  });
  if (runtimePlan) return runtimePlan.score;
  let score = 0;
  if (schedule?.solar_term === termId) score += 8;
  if (schedule?.weather_tag === weather.weather_id || schedule?.weather_tag === weather.disaster_tag) score += 6;
  if (schedule?.season === currentTermConfig()?.season) score += 3;
  if (chapter4DroughtActive() && String(schedule?.action_param || "").includes("drought")) score += 12;
  if (schedule?.action_type === "festival") score += 4;
  return score;
}

function scheduleMatchesNow(schedule, minute = townDailyClockMinute(), term = currentTermConfig(), weather = currentWeatherConfig()) {
  const runtimePlan = npcRuntime()?.scheduleMatchesNow(schedule, {
    minute,
    termId: term?.term_id,
    season: term?.season,
    weatherId: weather?.weather_id,
    disasterTag: weather?.disaster_tag,
  });
  if (runtimePlan) return runtimePlan.matches;
  if (!schedule) return false;
  if (schedule.season !== "all" && schedule.season !== term?.season) return false;
  if (schedule.solar_term !== "all" && schedule.solar_term !== term?.term_id) return false;
  if (schedule.weather_tag !== "all" && schedule.weather_tag !== weather.weather_id && schedule.weather_tag !== weather.disaster_tag) return false;
  return minute >= Number(schedule.time_start || 0) && minute < Number(schedule.time_end || 1440);
}

function currentScheduleFor(npcId) {
  const schedules = data.schedulesByNpc.get(npcId) || [];
  const minute = townDailyClockMinute();
  const weather = currentWeatherConfig();
  const term = currentTermConfig();
  const matches = schedules
    .filter((schedule) => scheduleMatchesNow(schedule, minute, term, weather))
    .sort((a, b) => schedulePriority(b, term?.term_id, weather) - schedulePriority(a, term?.term_id, weather));
  return matches[0] || schedules[0] || null;
}

function npcLifeArchetype(npc, schedule) {
  const role = npc?.npc_role || "";
  if (npc?.npc_id === "npc_baizhi" || role === "healer") return "healer";
  if (npc?.npc_id === "npc_zhang_tieshan" || npc?.npc_id === "npc_atan") return "crafter";
  if (npc?.npc_id === "npc_hu_sihai" || role === "merchant") return "trader";
  if (npc?.npc_id === "npc_shen_gudeng") return "rogue_cultivator";
  if (schedule?.action_type === "festival") return "guest";
  return "villager";
}

function npcTownLifeBark(npc, schedule) {
  const archetype = npcLifeArchetype(npc, schedule);
  const contextOrder = [];
  if (chapter4DroughtActive() || currentWeatherConfig().disaster_tag === "drought" || String(schedule?.action_param || "").includes("drought")) contextOrder.push("world_state");
  if (currentTermId() === "term_dongzhi" || schedule?.action_type === "festival") contextOrder.push("festival");
  contextOrder.push("ambient");
  for (const context of contextOrder) {
    const bark = data.npcBarks.find((entry) => {
      if (entry.context_type !== context) return false;
      if (entry.speaker_group !== archetype && entry.speaker_group !== "villager") return false;
      return conditionMet(entry.condition_group || "always_true");
    });
    if (bark) return localize(bark.text_key, "");
  }
  return `${npcName(npc?.npc_id)}正把今天的小事慢慢做完，凡仙镇也跟着稳了一点。`;
}

function townLifeStatus(schedule, npcId = "") {
  if (chapter4DroughtActive() && (String(schedule?.action_param || "").includes("drought") || ["npc_xubo", "npc_baizhi", "npc_qinghe"].includes(npcId))) {
    return { key: "urgent", label: "救灾" };
  }
  if (schedule?.action_type === "festival" || currentTermId() === "term_dongzhi") return { key: "festival", label: "节庆" };
  if (schedule?.area_id === "area_none") return { key: "away", label: "未到镇" };
  if (schedule?.action_type === "work") return { key: "work", label: "当值" };
  if (schedule?.action_type === "walk") return { key: "walk", label: "巡走" };
  return { key: "daily", label: "日常" };
}

function townLifeRowScore(row) {
  const statusScore = { urgent: 40, festival: 32, work: 22, walk: 18, daily: 12, away: -6 }[row.status.key] || 0;
  return statusScore + row.level * 3 + schedulePriority(row.schedule);
}

