function townLifeRows(limit = 6) {
  const reputationStage = shopReputationStageSpec();
  return data.npcs
    .filter((npc) => npc.npc_id !== "npc_system")
    .map((npc) => {
      const schedule = currentScheduleFor(npc.npc_id);
      const value = state.npcFavor[npc.npc_id] || 0;
      const level = favorLevel(value);
      const status = townLifeStatus(schedule, npc.npc_id);
      return {
        npc,
        schedule,
        value,
        level,
        status,
        area: schedule ? areaName(schedule.area_id) : "镇中未见",
        action: scheduleActionLabel(schedule),
        bark: npcTownLifeBark(npc, schedule),
      };
    })
    .map((row) => ({
      ...row,
      shopReputationBark: shopReputationTownBarkSpec(row, reputationStage),
      shopMomentBark: townLifeShopMomentBarkSpec(row),
      careChainBark: careChainEchoSpec(state.careChainState, row),
      weatherMoment: townLifeWeatherMomentSpec(row),
    }))
    .sort((a, b) => townLifeRowScore(b) - townLifeRowScore(a))
    .slice(0, limit);
}

function townLifeGreetingKey(npcId = "", day = state.day) {
  return `${day}:${npcId}`;
}

function townLifeGreetingSeen(npcId = "", day = state.day) {
  const townState = syncTownLifeInteractionState();
  return Boolean(townState.greetedByDay[townLifeGreetingKey(npcId, day)]);
}

function townLifeGreetingLine(row) {
  if (!row) return "镇上的风声从街口慢慢落下来。";
  const area = row.area || "镇中";
  const action = row.action || "日常";
  const status = row.status?.key || "daily";
  const weatherLine = townLifeWeatherGreetingLine(row);
  const lines = {
    urgent: `${npcName(row.npc.npc_id)}抬头冲你点了点头，手上还忙着${action}。${weatherLine}`,
    festival: `${npcName(row.npc.npc_id)}在${area}把灯影往上扶了扶。${weatherLine}`,
    walk: `${npcName(row.npc.npc_id)}从${area}经过，顺手把今天的见闻讲给你听。${weatherLine}`,
    work: `${npcName(row.npc.npc_id)}正在${area}${action}，看见你来便放慢了手上的活。${weatherLine}`,
    daily: `${npcName(row.npc.npc_id)}在${area}跟你寒暄了几句。${weatherLine}`,
  };
  return lines[status] || `${npcName(row.npc.npc_id)}在${area}跟你寒暄了几句。${weatherLine}`;
}

function townLifeGreetingSafetyText() {
  return "这里只定位今日寒暄确认入口，不会自动寒暄、写入来往记录、增加好感、承接小托付或触发关系记忆。";
}

function townLifeGreetingKeepsakeNodes(row = null) {
  if (!row?.npc?.npc_id) return [];
  const npcId = row.npc.npc_id;
  const selector = `button[data-canvas-town-greet="${selectorDataValue(npcId)}"], button[data-town-life-greet="${selectorDataValue(npcId)}"], button[data-town-opportunity-greet="${selectorDataValue(npcId)}"]`;
  const weatherMoment = row.weatherMoment || townLifeWeatherMomentSpec(row);
  return [
    {
      key: "place",
      label: "在哪遇见",
      badge: "地",
      title: row.area || "凡仙镇",
      text: `${row.action || "日常"} · ${row.status?.label || "今日动线"}`,
      detail: weatherMoment ? `${weatherMoment.label} · ${weatherMoment.prop}` : "镇民今日动线已在关系面板展开。",
      selector,
    },
    {
      key: "talk",
      label: "会聊什么",
      badge: "言",
      title: "今日近况",
      text: townLifeGreetingLine(row),
      detail: "寒暄后会写入今日来往，并可能带出小托付。",
      selector,
    },
    {
      key: "confirm",
      label: "确认入口",
      badge: "聊",
      title: "关系面板确认",
      text: "定位“打个招呼”按钮",
      detail: "只定位确认，不自动寒暄",
      selector,
    },
  ].map((node) => ({
    ...node,
    shortLabel: townLifeWorldBoardShortText(node.label, 6),
    shortTitle: townLifeWorldBoardShortText(node.title, 8),
    shortText: townLifeWorldBoardShortText(node.text, 14),
  }));
}

function townLifeGreetingKeepsakeSpec(target = null, rows = townLifeRows(6), canvasWidth = refs.world?.width || 960, canvasHeight = refs.world?.height || 640) {
  const activeFocus = townLifeGreetingKeepsakeWorldFocus?.day === state.day ? townLifeGreetingKeepsakeWorldFocus : null;
  const npcId = target?.row?.npc?.npc_id || target?.npcId || activeFocus?.npcId || "";
  if (!npcId || townLifeGreetingSeen(npcId)) return null;
  const visibleRows = (rows || townLifeRows(6)).filter((entry) => entry.status.key !== "away").slice(0, 5);
  const row = target?.row
    || visibleRows.find((entry) => entry.npc.npc_id === npcId)
    || canvasTownLifeFocusRow(npcId)
    || null;
  if (!row?.npc?.npc_id || row.status?.key === "away") return null;
  const rowIndex = visibleRows.findIndex((entry) => entry.npc.npc_id === row.npc.npc_id);
  const point = rowIndex >= 0 ? townLifeWorldPoint(visibleRows[rowIndex], rowIndex) : activeFocus?.point || null;
  const width = 320;
  const height = 152;
  const preferLeft = point ? point.x > canvasWidth * 0.46 : false;
  const rect = {
    x: Math.max(18, Math.min(canvasWidth - width - 18, point ? point.x + (preferLeft ? -width - 34 : 72) : 302)),
    y: Math.max(78, Math.min(canvasHeight - height - 28, point ? point.y - 154 : 286)),
    width,
    height,
  };
  const nodes = townLifeGreetingKeepsakeNodes(row);
  const nodeWidth = Math.floor((width - 52) / 3);
  nodes.forEach((node, index) => {
    node.rect = {
      x: rect.x + 16 + index * (nodeWidth + 10),
      y: rect.y + 98,
      width: nodeWidth,
      height: 34,
    };
  });
  const greetingLine = townLifeGreetingLine(row);
  return {
    key: `${state.day}:${npcId}:greeting_keepsake:${row.area}:${row.status?.key || "daily"}`,
    day: state.day,
    npcId,
    row,
    point,
    rect,
    nodes,
    activeNode: target?.activeNode || nodes.find((node) => node.key === activeFocus?.nodeKey) || nodes[2] || nodes[0],
    title: "今日寒暄留签 · 可点",
    subtitle: `${npcName(npcId)} · ${row.area || "凡仙镇"}`,
    lineText: townLifeWorldBoardShortText(greetingLine, 25),
    routeText: townLifeWorldBoardShortText(`${row.action || "日常"} · ${row.status?.label || "今日动线"}`, 22),
    safety: "只定位确认，不自动寒暄",
    tone: row.status?.key || "daily",
  };
}

function townLifeGreetingKeepsakeAtCanvasPoint(px, py) {
  const spec = townLifeGreetingKeepsakeSpec();
  if (!spec?.rect || townLifeGreetingKeepsakeWorldFocus?.day !== state.day) return null;
  const { rect } = spec;
  if (px < rect.x || px > rect.x + rect.width || py < rect.y || py > rect.y + rect.height) return null;
  const activeNode = spec.nodes.find((node) => {
    const nodeRect = node.rect;
    return nodeRect && px >= nodeRect.x && px <= nodeRect.x + nodeRect.width && py >= nodeRect.y && py <= nodeRect.y + nodeRect.height;
  }) || spec.nodes[2] || spec.nodes[0];
  return { ...spec, activeNode };
}

function focusTownLifeGreetingKeepsakeFromCanvas(target = null, options = {}) {
  const npcId = target?.npcId || target?.row?.npc?.npc_id || "";
  const spec = townLifeGreetingKeepsakeSpec(target, townLifeRows(6));
  if (!spec?.npcId) {
    addLog("今日寒暄留签", `${npcId ? npcName(npcId) : "这位镇民"}今天暂时没有可定位的寒暄入口。${townLifeGreetingSafetyText()}`);
    return renderLogs();
  }
  const activeNode = target?.activeNode
    || spec.nodes.find((node) => node.key === options.nodeKey)
    || spec.nodes[2]
    || spec.nodes[0];
  townLifeGreetingKeepsakeWorldFocus = {
    key: spec.key,
    nodeKey: activeNode?.key || "confirm",
    day: state.day,
    npcId: spec.npcId,
    point: spec.point ? { x: Math.round(spec.point.x), y: Math.round(spec.point.y) } : null,
    source: options.source || "canvas",
  };
  canvasTownLifeFocus = {
    npcId: spec.npcId,
    day: state.day,
    area: spec.row?.area || "凡仙镇",
    action: spec.row?.action || "今日寒暄",
    source: "town_life_greeting_keepsake",
    point: spec.point ? { x: Math.round(spec.point.x), y: Math.round(spec.point.y) } : null,
  };
  queueStoryCompassFocusTarget({
    selector: activeNode?.selector || `button[data-canvas-town-greet="${selectorDataValue(spec.npcId)}"], button[data-town-life-greet="${selectorDataValue(spec.npcId)}"]`,
    fallbackSelector: "#relationshipPanel",
    label: options.source === "keepsake" ? `点选今日寒暄留签：${activeNode?.label || "确认入口"}` : "今日寒暄留签",
    log: `${npcName(spec.npcId)} · ${activeNode?.label || "确认入口"}：${activeNode?.title || spec.row.area}。${activeNode?.text || spec.lineText} ${activeNode?.detail || ""}。${townLifeGreetingSafetyText()}`,
    panelGroup: "systems",
    missingTitle: "今日寒暄留签",
    missingLog: `${npcName(spec.npcId)}的寒暄按钮暂时没有找到，先打开关系面板查看今日动线。${townLifeGreetingSafetyText()}`,
  });
  return true;
}

function townLifeErrandKey(npcId = "", day = state.day) {
  return `${day}:${npcId}`;
}

function townLifeErrandTemplate(row) {
  const npcId = row?.npc?.npc_id || "";
  const roleTemplates = {
    npc_xubo: { itemId: "crop_lingqi_bailuobo", count: 2, title: "镇公所添菜", request: "许伯想给值夜的人添两份家常菜根。", gold: 24, fame: 1, favor: 2 },
    npc_zhang_tieshan: { itemId: "item_ore_copper", count: 1, title: "铁匠补铜", request: "张铁山缺一块顺手的铜矿，想先把农具补牢。", gold: 32, fame: 0, favor: 2 },
    npc_baizhi: { itemId: "item_material_clean_water", count: 1, title: "医馆清水", request: "白芷想先留一份净水煎药，免得下午来人时手忙。", gold: 18, fame: 0, favor: 2 },
    npc_lu_sanxiao: { itemId: "item_drink_lingcha", count: 1, title: "茶寮添谈资", request: "陆三笑说有壶灵茶，今晚故事能讲得更顺。", gold: 36, fame: 1, favor: 2 },
    npc_hu_sihai: { itemId: "item_food_plain_ration", count: 1, title: "客商路粮", request: "胡四海想带一份耐放路粮，试试你家货路稳不稳。", gold: 40, fame: 1, favor: 2 },
    npc_atan: { itemId: "item_wood_basic", count: 2, title: "木作棚补料", request: "阿檀想先凑两段木料，把新屋草样钉起来。", gold: 20, fame: 0, favor: 2 },
    npc_qinghe: { itemId: "crop_luzhu_qin", count: 1, title: "河岸尝鲜", request: "青禾想要一把带水气的露珠芹，试试旧渠水线的味。", gold: 34, fame: 1, favor: 2 },
    npc_shen_gudeng: { itemId: "item_med_zhixue_san", count: 1, title: "客栈备药", request: "沈孤灯想备一包止血散，出门前不喜欢欠准备。", gold: 45, fame: 0, favor: 2 },
  };
  const urgent = row?.status?.key === "urgent";
  if (urgent) {
    const moment = row?.weatherMoment || townLifeWeatherMomentSpec(row);
    return {
      itemId: "item_material_clean_water",
      count: 2,
      title: "救急清水",
      request: `${moment?.text ? `${moment.text} ` : ""}${npcName(npcId)}请你先拿两份净水过去，镇上今天实在缺这口水。`,
      gold: 36,
      fame: 2,
      favor: 3,
      weatherMomentKey: moment?.key || "",
      weatherLabel: moment?.label || "",
      weatherTone: moment?.tone || "",
      weatherHint: moment ? `${moment.weatherName} · ${moment.detail}` : "",
    };
  }
  const baseTemplate = roleTemplates[npcId] || { itemId: "crop_lingqi_bailuobo", count: 1, title: "街坊小托付", request: `${npcName(npcId)}想顺手收一份家常灵植。`, gold: 18, fame: 0, favor: 1 };
  return townLifeWeatherErrandTemplate(row, baseTemplate);
}

function townLifeErrandForRow(row) {
  if (!row || row.status?.key === "away") return null;
  const townState = syncTownLifeInteractionState();
  const key = townLifeErrandKey(row.npc.npc_id);
  const existing = townState.errandsByDay[key];
  if (existing) return { ...existing, key };
  const template = townLifeErrandTemplate(row);
  return {
    key,
    day: state.day,
    npcId: row.npc.npc_id,
    npcName: npcName(row.npc.npc_id),
    area: row.area,
    action: row.action,
    status: row.status.key,
    statusLabel: row.status.label,
    weatherMomentKey: template.weatherMomentKey || row.weatherMoment?.key || "",
    weatherLabel: template.weatherLabel || row.weatherMoment?.label || "",
    weatherTone: template.weatherTone || row.weatherMoment?.tone || "",
    weatherHint: template.weatherHint || row.weatherMoment?.detail || "",
    itemId: template.itemId,
    itemName: itemName(template.itemId),
    count: template.count,
    title: template.title,
    request: template.request,
    rewardGold: template.gold,
    rewardFame: template.fame,
    rewardFavor: template.favor,
    completed: false,
  };
}

function townLifeErrandStatus(row) {
  const errand = townLifeErrandForRow(row);
  if (!errand) return null;
  const have = Number(state.inventory[errand.itemId] || 0);
  return {
    ...errand,
    have,
    ready: have >= Number(errand.count || 1),
  };
}

function townLifeErrandMaturePlotForItem(itemId = "") {
  const crop = cropForHarvestTarget(itemId);
  const cropIds = new Set([itemId, crop?.crop_id, crop?.output_item_id].filter(Boolean));
  return state.plots.find((plot) => plot.mature && cropIds.has(plot.cropId)) || null;
}

function townLifeErrandRouteCandidates(errand = null) {
  if (!errand?.itemId) return [];
  const itemId = errand.itemId;
  const need = Math.max(1, Number(errand.count || 1));
  const have = Number(state.inventory[itemId] || 0);
  const candidates = [];
  if (have >= need) {
    candidates.push({
      type: "stock",
      label: "背包已够",
      title: `${itemName(itemId)} ${have}/${need}`,
      detail: `${errand.npcName || "镇民"}要的${itemName(itemId)}已经备齐，可以回关系卡交付今日小托付。`,
      action: "deliver",
      buttonLabel: "交付小托付",
      score: 140,
    });
  }

  const maturePlot = townLifeErrandMaturePlotForItem(itemId);
  if (maturePlot) {
    candidates.push({
      type: "harvest",
      label: "田里可收",
      title: `灵田 (${maturePlot.x + 1},${maturePlot.y + 1}) · ${itemName(maturePlot.cropId)}`,
      detail: `先把成熟的${itemName(maturePlot.cropId)}收进背包，再回去交给${errand.npcName || "镇民"}。`,
      action: "harvest",
      x: maturePlot.x,
      y: maturePlot.y,
      buttonLabel: "定位收获",
      score: 124,
    });
  }

  const outputRecipe = bestRecipeForOutput(itemId);
  if (outputRecipe) {
    const missingInput = aggregatedRecipeInputs(outputRecipe)
      .find(({ itemId: inputId, count }) => !hasItem(inputId, count));
    const inputPlot = missingInput ? townLifeErrandMaturePlotForItem(missingInput.itemId) : null;
    if (inputPlot) {
      candidates.push({
        type: "harvest",
        label: "先收原料",
        title: `灵田 (${inputPlot.x + 1},${inputPlot.y + 1}) · ${itemName(inputPlot.cropId)}`,
        detail: `${recipeName(outputRecipe)}还差${itemName(missingInput.itemId)}，这块田成熟后就能把配方往前推。`,
        action: "harvest",
        x: inputPlot.x,
        y: inputPlot.y,
        buttonLabel: "定位收获",
        score: recipeCraftReady(outputRecipe) ? 112 : 104,
      });
    }
    candidates.push({
      type: "recipe",
      label: recipeCraftReady(outputRecipe) ? "可立即制作" : recipeUnlocked(outputRecipe) ? "看配方备料" : "配方未解锁",
      title: recipeName(outputRecipe),
      detail: `${recipeMachineHint(outputRecipe)} · 原料 ${recipeInputStatus(outputRecipe, 4) || "无需额外原料"} · ${recipeUnlocked(outputRecipe) ? "做成后就能交托付。" : recipeUnlockHint(outputRecipe)}`,
      action: "recipe",
      recipeId: outputRecipe.recipe_id,
      buttonLabel: recipeCraftReady(outputRecipe) ? "制作路线" : "看配方",
      score: recipeCraftReady(outputRecipe) ? 118 : recipeUnlocked(outputRecipe) ? 92 : 48,
    });
  }

  const crop = cropForHarvestTarget(itemId);
  if (crop && availableSeedCrops().some((entry) => entry.seed_item_id === crop.seed_item_id)) {
    const route = seedUseRouteSpec(crop);
    candidates.push({
      type: "seed",
      label: "种植补货",
      title: itemName(crop.seed_item_id),
      detail: route?.detail || `${Number(crop.grow_days || 1)} 夜后可收 ${itemName(crop.crop_id)}，适合提前备下镇民天气托付。`,
      action: "seed",
      seedId: crop.seed_item_id,
      buttonLabel: "看种子",
      score: Number(state.inventory[crop.seed_item_id] || 0) > 0 ? 86 : 72,
    });
  }

  if (itemId === "item_material_clean_water") {
    const debrisPlot = state.plots.find((plot) => plot.debris) || null;
    candidates.push({
      type: "material",
      label: debrisPlot ? "清荒取水" : "净水来源",
      title: debrisPlot ? `灵田 (${debrisPlot.x + 1},${debrisPlot.y + 1})` : "背包与精怪岗位",
      detail: debrisPlot
        ? "清理荒草或碎石常会带回净水，适合马上补这类雨旱天气托付。"
        : "净水可从清荒、夜间工坊/庭院精怪岗位、关系回礼和部分日结奖励里补到。",
      action: debrisPlot ? "field" : "inventory",
      x: debrisPlot?.x,
      y: debrisPlot?.y,
      selector: debrisPlot ? "#selectedPlotCard" : "#inventoryList",
      buttonLabel: debrisPlot ? "定位清荒" : "看净水来源",
      score: debrisPlot ? 82 : 54,
    });
  }

  if (!candidates.length) {
    const source = orderItemSourceSpec(itemId, need);
    candidates.push({
      type: "inventory",
      label: "查看来源",
      title: itemName(itemId),
      detail: source.detail || "先看背包、订单来源、秘境和商路奖励，确认这件托付物从哪里补。",
      action: source.action?.type || "inventory",
      recipeId: source.action?.type === "recipe" ? source.action.id : "",
      seedId: source.action?.type === "seed" ? source.action.id : "",
      selector: "#inventoryList",
      buttonLabel: source.action?.type === "recipe" ? "看配方" : source.action?.type === "seed" ? "看种子" : "看备货路线",
      score: 28,
    });
  }

  return candidates
    .filter((entry) => entry.action === "deliver" || entry.action === "harvest" || entry.action === "recipe" || entry.action === "seed" || entry.action === "field" || entry.action === "inventory")
    .sort((a, b) => Number(b.score || 0) - Number(a.score || 0))
    .slice(0, 3);
}

function townLifeErrandRouteSpec(errand = null) {
  const candidates = townLifeErrandRouteCandidates(errand);
  const route = candidates[0] || null;
  if (!route) return null;
  const missing = Math.max(0, Number(errand?.count || 1) - Number(errand?.have || state.inventory[errand?.itemId] || 0));
  return {
    ...route,
    candidates,
    itemId: errand?.itemId || route.itemId || "",
    itemName: errand?.itemName || itemName(errand?.itemId || route.itemId || ""),
    missing,
    headline: missing > 0 ? `还差 ${missing} 份` : "已经备齐",
    buttonLabel: route.buttonLabel || "看备货路线",
  };
}

function townLifeErrandRouteWorldPalette(route = {}) {
  const type = route.type || route.action || "inventory";
  const palettes = {
    harvest: { accent: "#48a868", soft: "rgba(72, 168, 104, 0.2)", glyph: "收" },
    recipe: { accent: "#8f5f3f", soft: "rgba(143, 95, 63, 0.18)", glyph: "炊" },
    seed: { accent: "#286f58", soft: "rgba(40, 111, 88, 0.18)", glyph: "种" },
    material: { accent: "#4d91a6", soft: "rgba(77, 145, 166, 0.2)", glyph: "水" },
    inventory: { accent: "#4d91a6", soft: "rgba(77, 145, 166, 0.18)", glyph: "备" },
    stock: { accent: "#b47d2f", soft: "rgba(224, 182, 109, 0.2)", glyph: "交" },
  };
  return palettes[type] || palettes.inventory;
}

function townLifeErrandRoutePlotWorldPoint(plot, label = "灵田", originX = 300, originY = 142, tile = 72, gap = 8) {
  if (!plot) return null;
  return {
    x: originX + Number(plot.x || 0) * (tile + gap) + tile / 2,
    y: originY + Number(plot.y || 0) * (tile + gap) + tile / 2,
    label,
  };
}

function townLifeErrandRouteWorldTargetPoint(route = {}, originX = 300, originY = 142, tile = 72, gap = 8) {
  if ((route.action === "harvest" || route.action === "field") && Number.isFinite(Number(route.x)) && Number.isFinite(Number(route.y))) {
    const plot = state.plots.find((entry) => entry.x === Number(route.x) && entry.y === Number(route.y));
    const point = townLifeErrandRoutePlotWorldPoint(plot, route.action === "harvest" ? "收获灵田" : "清荒取水", originX, originY, tile, gap);
    if (point) return point;
  }
  if (route.action === "recipe") {
    const point = dailyIntentWorldTargetPoint({ key: "build" }, originX, originY, tile, gap);
    return { ...point, label: "工坊配方" };
  }
  if (route.action === "seed") {
    const emptyPlot = state.plots.find((plot) => !plot.debris && !plot.cropId) || selectedPlot() || state.plots[0];
    const point = townLifeErrandRoutePlotWorldPoint(emptyPlot, "播种灵田", originX, originY, tile, gap);
    if (point) return point;
  }
  if (route.action === "deliver") return { x: 728, y: 118, label: "回镇交付" };
  if (route.action === "inventory") return { x: 238, y: 104, label: "背包来源" };
  return dailyIntentWorldTargetPoint({ key: "field" }, originX, originY, tile, gap);
}

function townLifeErrandRouteWorldSourcePoint(row = null) {
  const npcId = row?.npc?.npc_id || "";
  const rows = townLifeRows(6).filter((entry) => entry.status.key !== "away").slice(0, 5);
  const index = rows.findIndex((entry) => entry.npc.npc_id === npcId);
  const sourceRow = index >= 0 ? rows[index] : row;
  const point = sourceRow ? townLifeWorldPoint(sourceRow, Math.max(0, index)) : townAreaWorldPoint("area_town_main", 0);
  return {
    x: point.x + 78,
    y: point.y + 68,
    label: npcId ? npcName(npcId).slice(0, 4) : "镇民",
  };
}

function queueTownLifeErrandRouteWorldFocus(row = null, errand = null, route = null) {
  if (!row || !errand || !route) return null;
  const { tile, gap, originX, originY } = gridMetrics();
  const palette = townLifeErrandRouteWorldPalette(route);
  const key = `${state.day}:${row.npc.npc_id}:${errand.itemId}:${route.action}:${route.x ?? ""}:${route.y ?? ""}:${route.recipeId || ""}:${route.seedId || ""}`;
  townLifeErrandRouteWorldFocus = {
    key,
    day: state.day,
    npcId: row.npc.npc_id,
    npcName: errand.npcName || npcName(row.npc.npc_id),
    itemName: errand.itemName || route.itemName || itemName(errand.itemId),
    missing: Math.max(0, Number(errand.count || 1) - Number(errand.have || 0)),
    label: route.label || "备货路线",
    title: route.title || route.itemName || "备货目标",
    detail: route.detail || "按这条路线把托付物补齐。",
    headline: route.headline || "",
    action: route.action || "",
    type: route.type || route.action || "inventory",
    routeX: Number.isFinite(Number(route.x)) ? Number(route.x) : null,
    routeY: Number.isFinite(Number(route.y)) ? Number(route.y) : null,
    recipeId: route.recipeId || "",
    seedId: route.seedId || "",
    selector: route.selector || "",
    source: townLifeErrandRouteWorldSourcePoint(row),
    target: townLifeErrandRouteWorldTargetPoint(route, originX, originY, tile, gap),
    accent: palette.accent,
    soft: palette.soft,
    glyph: palette.glyph,
    createdAt: typeof performance !== "undefined" ? performance.now() : Date.now(),
    duration: 5600,
  };
  if (typeof window !== "undefined") {
    window.setTimeout(() => {
      if (townLifeErrandRouteWorldFocus?.key === key) {
        townLifeErrandRouteWorldFocus = null;
        drawWorld();
      }
    }, townLifeErrandRouteWorldFocus.duration);
  }
  return townLifeErrandRouteWorldFocus;
}

function townLifeErrandRouteWorldFocusAtCanvasPoint(px, py) {
  const focus = townLifeErrandRouteWorldFocus;
  if (!focus || Number(focus.day || 0) !== Number(state.day || 0) || !focus.target) return null;
  const now = typeof performance !== "undefined" ? performance.now() : Date.now();
  if (now - Number(focus.createdAt || now) > Number(focus.duration || 5600)) {
    townLifeErrandRouteWorldFocus = null;
    return null;
  }
  const target = focus.target;
  return px >= target.x - 54 && px <= target.x + 118 && py >= target.y - 78 && py <= target.y + 38
    ? focus
    : null;
}

function focusTownLifeErrandRouteWorldTarget(focus = townLifeErrandRouteWorldFocus) {
  if (!focus) return false;
  addLog("点选备货终点", `${focus.npcName || "镇民"}的${focus.itemName || "托付物"}路线终点已重新定位：${focus.label || focus.title || "备货目标"}。`);
  if (focus.action === "harvest" && Number.isFinite(Number(focus.routeX)) && Number.isFinite(Number(focus.routeY))) {
    return focusDaySummaryMaturePlot(focus.routeX, focus.routeY);
  }
  if (focus.action === "field" && Number.isFinite(Number(focus.routeX)) && Number.isFinite(Number(focus.routeY))) {
    const plot = state.plots.find((entry) => entry.x === Number(focus.routeX) && entry.y === Number(focus.routeY));
    if (plot) {
      state.selected = { x: plot.x, y: plot.y };
      pulseAtPlot(plot, plot.debris ? "clear" : "work");
    }
    queuePlotRouteFocusTarget({
      selector: "#selectedPlotCard",
      fallbackSelector: "#selectedPlotCard",
      label: "天气托付备货",
      log: `${focus.npcName || "镇民"}还在等 ${focus.itemName || "托付物"}。${focus.detail || "先处理这块灵田，再查看托付物来源。"}`,
      panelGroup: "core",
      missingTitle: "天气托付备货",
      missingLog: "灵田卡片暂时没有找到，先点击主画面地块再确认下一步。",
    });
    return true;
  }
  if (focus.action === "recipe" && focus.recipeId) return focusPlotRouteRecipe(focus.recipeId);
  if (focus.action === "seed" && focus.seedId) return focusPlotRouteSeed(focus.seedId);
  if (focus.action === "deliver" && focus.npcId) return focusTownLifeErrandDeliveryConfirm(focus.npcId, { source: "routeFocus" });
  queuePlotRouteFocusTarget({
    selector: focus.selector || "#inventoryList",
    fallbackSelector: "#inventoryList",
    label: "天气托付备货",
    log: `${focus.npcName || "镇民"}还在等 ${focus.itemName || "托付物"}。${focus.detail || "先从背包和来源提示确认下一步。"}`,
    panelGroup: "core",
    missingTitle: "天气托付备货",
    missingLog: "备货终点暂时没有找到，先从背包、灵田和工坊检查来源。",
  });
  return true;
}

function townLifeErrandDeliverySafetyText() {
  return "这里只定位小托付交付入口，不会自动交付托付、扣除物品、发放回礼、增加好感或消耗资源。";
}

function townLifeErrandDeliveryKeepsakeNodes(row = null, errand = null) {
  if (!row?.npc?.npc_id || !errand) return [];
  const selector = `button[data-town-life-errand="${selectorDataValue(row.npc.npc_id)}"]`;
  const haveText = `${errand.itemName || itemName(errand.itemId)} ${Number(state.inventory[errand.itemId] || 0)}/${Math.max(1, Number(errand.count || 1))}`;
  const rewardText = `${Number(errand.rewardGold || 0)} 灵石${errand.rewardFame ? ` / 声望 +${errand.rewardFame}` : ""}${errand.rewardFavor ? ` / 好感 +${errand.rewardFavor}` : ""}`;
  return [
    {
      key: "npc",
      label: "交给谁",
      badge: "人",
      title: errand.npcName || npcName(row.npc.npc_id),
      text: `${row.area || "凡仙镇"} · ${row.action || "今日动线"}`,
      detail: errand.request || `${errand.npcName || npcName(row.npc.npc_id)}正在等这件小托付。`,
      selector,
    },
    {
      key: "item",
      label: "带什么",
      badge: "物",
      title: haveText,
      text: errand.title || "今日小托付",
      detail: `背包已备齐 ${haveText}`,
      selector,
    },
    {
      key: "confirm",
      label: "确认入口",
      badge: "交",
      title: "关系面板确认",
      text: rewardText,
      detail: "只定位确认，不自动交付",
      selector,
    },
  ].map((node) => ({
    ...node,
    shortLabel: townLifeWorldBoardShortText(node.label, 6),
    shortTitle: townLifeWorldBoardShortText(node.title, 8),
    shortText: townLifeWorldBoardShortText(node.text, 14),
  }));
}

function townLifeErrandDeliveryKeepsakeSpec(target = null, rows = townLifeRows(6), canvasWidth = refs.world?.width || 960, canvasHeight = refs.world?.height || 640) {
  const activeFocus = townLifeErrandDeliveryKeepsakeWorldFocus?.day === state.day ? townLifeErrandDeliveryKeepsakeWorldFocus : null;
  const npcId = target?.errand?.npcId || target?.row?.npc?.npc_id || target?.npcId || activeFocus?.npcId || "";
  if (!npcId) return null;
  const visibleRows = (rows || townLifeRows(6)).filter((entry) => entry.status.key !== "away").slice(0, 5);
  const row = target?.row
    || visibleRows.find((entry) => entry.npc.npc_id === npcId)
    || canvasTownLifeFocusRow(npcId)
    || null;
  if (!row?.npc?.npc_id) return null;
  const errand = target?.errand || townLifeErrandStatus(row);
  if (!errand || errand.completed || !errand.ready) return null;
  const rowIndex = visibleRows.findIndex((entry) => entry.npc.npc_id === row.npc.npc_id);
  const point = rowIndex >= 0 ? townLifeWorldPoint(visibleRows[rowIndex], rowIndex) : activeFocus?.point || null;
  const width = 318;
  const height = 152;
  const preferLeft = point ? point.x > canvasWidth * 0.58 : false;
  const rect = {
    x: Math.max(18, Math.min(canvasWidth - width - 18, point ? point.x + (preferLeft ? -width - 26 : 70) : 386)),
    y: Math.max(84, Math.min(canvasHeight - height - 28, point ? point.y - 118 : 348)),
    width,
    height,
  };
  const nodes = townLifeErrandDeliveryKeepsakeNodes(row, errand);
  const nodeWidth = Math.floor((width - 52) / 3);
  nodes.forEach((node, index) => {
    node.rect = {
      x: rect.x + 16 + index * (nodeWidth + 10),
      y: rect.y + 98,
      width: nodeWidth,
      height: 34,
    };
  });
  const haveText = `${errand.itemName || itemName(errand.itemId)} ${Number(state.inventory[errand.itemId] || 0)}/${Math.max(1, Number(errand.count || 1))}`;
  const rewardText = `${Number(errand.rewardGold || 0)} 灵石${errand.rewardFame ? ` · 声望 +${errand.rewardFame}` : ""}${errand.rewardFavor ? ` · 好感 +${errand.rewardFavor}` : ""}`;
  return {
    key: `${state.day}:${row.npc.npc_id}:${errand.key || errand.itemId}:errand_delivery_keepsake`,
    day: state.day,
    npcId: row.npc.npc_id,
    row,
    errand,
    point,
    rect,
    nodes,
    activeNode: target?.activeNode || nodes.find((node) => node.key === activeFocus?.nodeKey) || nodes[2] || nodes[0],
    title: "小托付交付留签 · 可点",
    subtitle: `${errand.npcName || npcName(row.npc.npc_id)} · ${errand.title || "今日小托付"}`,
    haveText: townLifeWorldBoardShortText(haveText, 20),
    rewardText: townLifeWorldBoardShortText(rewardText, 24),
    requestText: townLifeWorldBoardShortText(errand.request || "这件小托付已经备齐，等待面板确认。", 25),
    safety: "只定位确认，不自动交付",
  };
}

function townLifeErrandDeliveryKeepsakeAtCanvasPoint(px, py) {
  const spec = townLifeErrandDeliveryKeepsakeSpec();
  if (!spec?.rect || townLifeErrandDeliveryKeepsakeWorldFocus?.day !== state.day) return null;
  const { rect } = spec;
  if (px < rect.x || px > rect.x + rect.width || py < rect.y || py > rect.y + rect.height) return null;
  const activeNode = spec.nodes.find((node) => {
    const nodeRect = node.rect;
    return nodeRect && px >= nodeRect.x && px <= nodeRect.x + nodeRect.width && py >= nodeRect.y && py <= nodeRect.y + nodeRect.height;
  }) || spec.nodes[2] || spec.nodes[0];
  return { ...spec, activeNode };
}

function focusTownLifeErrandDeliveryConfirm(npcId = "", options = {}) {
  const row = townLifeRows(12).find((entry) => entry.npc.npc_id === npcId);
  if (!row) {
    addLog("小托付交付留签", `今天没在镇上找到这位镇民。${townLifeErrandDeliverySafetyText()}`);
    return renderLogs();
  }
  const errand = townLifeErrandStatus(row);
  if (!errand) {
    addLog("小托付交付留签", `${npcName(npcId)}今天暂时没有可交的小托付。${townLifeErrandDeliverySafetyText()}`);
    return renderLogs();
  }
  if (errand.completed) {
    addLog("小托付交付留签", `${errand.title} 今天已经办妥了。${townLifeErrandDeliverySafetyText()}`);
    return renderLogs();
  }
  const route = townLifeErrandRouteSpec(errand);
  if (route) queueTownLifeErrandRouteWorldFocus(row, errand, route);
  const spec = errand.ready ? townLifeErrandDeliveryKeepsakeSpec({ row, errand }, townLifeRows(6)) : null;
  const activeNode = spec?.nodes?.find((node) => node.key === options.nodeKey)
    || spec?.nodes?.[2]
    || spec?.nodes?.[0]
    || null;
  if (spec?.rect) {
    townLifeErrandDeliveryKeepsakeWorldFocus = {
      key: spec.key,
      nodeKey: activeNode?.key || "confirm",
      day: state.day,
      npcId: row.npc.npc_id,
      errandKey: errand.key || errand.itemId,
      point: spec.point ? { x: Math.round(spec.point.x), y: Math.round(spec.point.y) } : null,
      source: options.source || "canvas",
    };
    canvasTownLifeFocus = {
      npcId: row.npc.npc_id,
      day: state.day,
      area: row.area || "凡仙镇",
      action: row.action || "小托付",
      source: "town_life_errand_delivery_keepsake",
      point: spec.point ? { x: Math.round(spec.point.x), y: Math.round(spec.point.y) } : null,
    };
  }
  const haveText = `${errand.itemName} ${Number(state.inventory[errand.itemId] || 0)}/${errand.count}`;
  const rewardText = `回礼 ${errand.rewardGold} 灵石${errand.rewardFame ? ` / 声望 +${errand.rewardFame}` : ""}${errand.rewardFavor ? ` / 好感 +${errand.rewardFavor}` : ""}`;
  const readyText = errand.ready ? "材料已经备齐，请在关系面板点明确按钮交付。" : "材料还没备齐，先看备货路线。";
  queueStoryCompassFocusTarget({
    selector: activeNode?.selector || `button[data-town-life-errand="${selectorDataValue(npcId)}"]`,
    fallbackSelector: "#relationshipPanel",
    label: options.source === "plaque" ? "点选小托付交付牌" : options.source === "keepsake" ? `点选小托付交付留签：${activeNode?.label || "确认入口"}` : "小托付交付留签",
    log: `${errand.npcName} · ${activeNode?.label || "确认入口"}：${activeNode?.title || errand.title}。${activeNode?.text || haveText} ${activeNode?.detail || readyText}。${rewardText}。${townLifeErrandDeliverySafetyText()}`,
    panelGroup: "story",
    missingTitle: "小托付交付留签",
    missingLog: `${errand.npcName}的小托付按钮暂时没有找到，先打开关系面板查看凡仙镇今日动线。${townLifeErrandDeliverySafetyText()}`,
  });
  return true;
}

function focusTownLifeErrandRoute(npcId = "") {
  const row = townLifeRows(12).find((entry) => entry.npc.npc_id === npcId);
  if (!row) {
    addLog("天气托付备货", "今天没在镇上找到这位镇民，先看凡仙镇今日动线。");
    return renderLogs();
  }
  const errand = townLifeErrandStatus(row);
  if (!errand) {
    addLog("天气托付备货", "这位镇民今天暂时没有可追的小托付。");
    return renderLogs();
  }
  if (errand.completed) {
    addLog("天气托付备货", `${errand.title} 今天已经办妥了。`);
    return renderLogs();
  }
  if (errand.ready) return focusTownLifeErrandDeliveryConfirm(npcId, { source: "route" });
  const route = townLifeErrandRouteSpec(errand);
  if (!route) {
    addLog("天气托付备货", `${errand.npcName}还在等 ${errand.itemName} ${errand.have}/${errand.count}，先看背包和今日机会。`);
    return renderLogs();
  }
  queueTownLifeErrandRouteWorldFocus(row, errand, route);
  if (route.action === "harvest") return focusDaySummaryMaturePlot(route.x, route.y);
  if (route.action === "recipe" && route.recipeId) return focusPlotRouteRecipe(route.recipeId);
  if (route.action === "seed" && route.seedId) return focusPlotRouteSeed(route.seedId);
  const selector = route.action === "field" && Number.isFinite(Number(route.x)) && Number.isFinite(Number(route.y))
    ? "#selectedPlotCard"
    : route.selector || "#inventoryList";
  if (route.action === "field" && Number.isFinite(Number(route.x)) && Number.isFinite(Number(route.y))) {
    const plot = state.plots.find((entry) => entry.x === Number(route.x) && entry.y === Number(route.y));
    if (plot) state.selected = { x: plot.x, y: plot.y };
  }
  queuePlotRouteFocusTarget({
    selector,
    fallbackSelector: "#inventoryList",
    label: "天气托付备货",
    log: `${errand.npcName}还在等 ${errand.itemName} ${errand.have}/${errand.count}。${route.label}：${route.detail}`,
    panelGroup: "core",
    missingTitle: "天气托付备货",
    missingLog: "备货入口暂时没有找到，先确认核心试玩面板是否可见，再从背包、灵田和工坊检查来源。",
  });
}

function acceptTownLifeErrand(row) {
  const errand = townLifeErrandForRow(row);
  if (!errand) return null;
  const townState = syncTownLifeInteractionState();
  if (!townState.errandsByDay[errand.key]) townState.errandsByDay[errand.key] = errand;
  return townState.errandsByDay[errand.key];
}

function completeTownLifeErrand(npcId = "") {
  const row = townLifeRows(12).find((entry) => entry.npc.npc_id === npcId);
  if (!row) return addLog("今日小托付", "今天没在镇上找到这位镇民的小托付。");
  const townState = syncTownLifeInteractionState();
  const errand = acceptTownLifeErrand(row);
  if (!errand) return addLog("今日小托付", "这件小托付暂时接不上。");
  if (errand.completed) {
    addLog("今日小托付", `${errand.title} 今天已经办妥了。`);
    return render();
  }
  if (!hasItem(errand.itemId, errand.count)) {
    addLog("今日小托付", `${errand.npcName}还在等 ${errand.itemName} ${Number(state.inventory[errand.itemId] || 0)}/${errand.count}。`);
    return render();
  }
  addItem(errand.itemId, -Number(errand.count || 1));
  const favorBefore = Number(state.npcFavor[errand.npcId] || 0);
  state.gold += Number(errand.rewardGold || 0);
  state.fame += Number(errand.rewardFame || 0);
  addNpcFavor(errand.npcId, Number(errand.rewardFavor || 0), `今日小托付 · ${errand.title}`);
  const favorAfter = Number(state.npcFavor[errand.npcId] || 0);
  errand.completed = true;
  errand.completedDay = state.day;
  townState.errandsByDay[errand.key] = errand;
  townState.errandHistory.unshift({ ...errand });
  townState.errandHistory = townState.errandHistory.slice(0, 12);
  const weatherEcho = recordTownLifeWeatherErrandEcho(errand);
  const unlockedMemories = recordTownLifeInteraction(errand.npcId, "errand");
  state.townLifeErrandFeedback = townLifeErrandFeedbackSpec(errand, weatherEcho, {
    favorBefore,
    favorAfter,
    unlockedMemories,
  });
  recordDailyIntentProgress("relationship", `${errand.npcName} 托付「${errand.title}」办妥`, {
    amount: 3,
    rewardText: `${weatherEcho ? `${weatherEcho.label} · ` : ""}好感 +${errand.rewardFavor} · 灵石 +${errand.rewardGold}${errand.rewardFame ? ` · 声望 +${errand.rewardFame}` : ""}`,
    target: `npc:${errand.npcId}`,
  });
  addLog("今日小托付完成", `${errand.npcName}收下 ${errand.itemName} x${errand.count}，回礼 ${errand.rewardGold} 灵石${errand.rewardFame ? `、声望 +${errand.rewardFame}` : ""}、好感 +${errand.rewardFavor}。${weatherEcho ? ` ${weatherEcho.summary}` : ""}`);
  playCue("任务完成");
  render();
}

function townLifeGiftKey(npcId = "", day = state.day) {
  return `${day}:${npcId}`;
}

function townLifeGiftSeen(npcId = "", day = state.day) {
  return Boolean(syncTownLifeInteractionState().giftsByDay[townLifeGiftKey(npcId, day)]);
}

function giftItemTags(itemId = "") {
  const item = data.itemsById.get(itemId);
  if (!item) return [];
  return splitTags(item.tags || item.item_tags || "");
}

function giftTagAliasMatches(preference = "", itemTags = [], item = {}) {
  const aliases = {
    practical: ["food", "staple", "portable_food", "tool", "wood", "stone", "material"],
    metal: ["metal", "ore", "copper", "iron", "rare"],
    ore: ["ore", "metal", "copper", "iron"],
    food_hot: ["spicy", "fire", "food", "staple"],
    warm_food: ["food", "staple", "winter_food", "spicy"],
    herb: ["herb", "medicine", "heal_hp", "heal_sp", "clean_food"],
    tea: ["tea", "drink", "story"],
    gift_refined: ["gift", "premium", "festival", "archive"],
    rare_goods: ["rare", "premium", "trade", "gem", "route_rare"],
    cool_drink: ["drink", "water_food", "refreshing", "cooling"],
    battle_food: ["patrol", "guard", "medicine", "recover_sp", "portable_food"],
    strong_drink: ["drink", "brew", "premium"],
    medicines: ["medicine", "heal_hp", "heal_sp"],
    wood: ["wood", "build"],
    cloth: ["cloth", "fiber"],
    fish: ["fish", "pond", "water_food"],
    sweet: ["dessert", "sweet_food", "honey", "festival"],
    flowers: ["flower", "festival", "gift"],
    luxury: ["premium", "legend", "gift"],
    waste: ["spoiled", "cheap_junk"],
  };
  const candidates = aliases[preference] || [preference];
  return candidates.some((tag) => itemTags.includes(tag) || item.item_type === tag || String(item.item_id || "").includes(tag));
}

function giftMatchScore(npc, itemId = "") {
  const item = data.itemsById.get(itemId);
  if (!npc || !item) return null;
  if (item.item_type === "seed" || item.item_type === "currency" || splitTags(item.tags || "").includes("quest")) return null;
  const tags = giftItemTags(itemId);
  const likes = splitTags(npc.gift_like_tags || "");
  const dislikes = splitTags(npc.gift_dislike_tags || "");
  const likeHits = likes.filter((tag) => giftTagAliasMatches(tag, tags, item));
  const dislikeHits = dislikes.filter((tag) => giftTagAliasMatches(tag, tags, item));
  const rarity = Number(item.rarity || 1);
  const sellPrice = Number(item.sell_price_base || 0);
  const baseScore = likeHits.length * 18 + rarity * 4 + Math.min(14, Math.floor(sellPrice / 40)) - dislikeHits.length * 16;
  const favorGain = Math.max(1, Math.min(10, 2 + likeHits.length * 3 + Math.max(0, rarity - 1) - dislikeHits.length * 3));
  const tone = dislikeHits.length > 0 ? "bad" : likeHits.length > 0 ? "liked" : "plain";
  return {
    itemId,
    itemName: itemName(itemId),
    tags,
    likeHits,
    dislikeHits,
    score: baseScore,
    favorGain,
    tone,
    reason: likeHits.length
      ? `合 ${npcName(npc.npc_id)} 的 ${likeHits.slice(0, 2).join(" / ")} 偏好`
      : dislikeHits.length
        ? `踩到 ${dislikeHits.slice(0, 2).join(" / ")} 忌口`
        : "普通心意，胜在顺手",
  };
}

function recommendedNpcGift(npcId = "") {
  const npc = data.npcsById.get(npcId);
  if (!npc || npc.npc_id === "npc_system") return null;
  return Object.entries(state.inventory)
    .filter(([, count]) => Number(count || 0) > 0)
    .map(([itemId]) => giftMatchScore(npc, itemId))
    .filter(Boolean)
    .sort((a, b) => b.score - a.score || b.favorGain - a.favorGain)[0] || null;
}

function giveRecommendedNpcGift(npcId = "") {
  const npc = data.npcsById.get(npcId);
  if (!npc || npc.npc_id === "npc_system") return addLog("赠礼失败", "今天没有找到合适的赠礼对象。");
  const townState = syncTownLifeInteractionState();
  const key = townLifeGiftKey(npcId);
  if (townState.giftsByDay[key]) {
    addLog("今日已赠礼", `${npcName(npcId)}今天已经收过一份心意了。`);
    return render();
  }
  const gift = recommendedNpcGift(npcId);
  if (!gift) {
    addLog("没有合适礼物", `${npcName(npcId)}今天没有合适的可赠物。先准备带标签的食物、饮品、药材、材料或礼品。`);
    return render();
  }
  addItem(gift.itemId, -1);
  addNpcFavor(npcId, gift.favorGain, `每日赠礼 · ${gift.itemName}`);
  const entry = {
    day: state.day,
    npcId,
    npcName: npcName(npcId),
    itemId: gift.itemId,
    itemName: gift.itemName,
    favorGain: gift.favorGain,
    tone: gift.tone,
    reason: gift.reason,
  };
  townState.giftsByDay[key] = entry;
  townState.giftHistory.unshift(entry);
  townState.giftHistory = townState.giftHistory.slice(0, 16);
  recordTownLifeInteraction(npcId, "gift");
  recordDailyIntentProgress("relationship", `${entry.npcName} 收下 ${entry.itemName}`, {
    amount: 2,
    rewardText: `好感 +${entry.favorGain} · ${entry.reason}`,
    target: `npc:${npcId}`,
  });
  playCue("任务完成");
  addLog("每日赠礼", `${entry.npcName} 收下 ${entry.itemName}：${entry.reason}，好感 +${entry.favorGain}。`);
  render();
}

function townLifeGiftSafetyText() {
  return "这里只定位今日赠礼确认入口，不会自动赠礼、扣除物品、增加好感或写入赠礼记录。";
}

function townLifeGiftKeepsakeNodes(row = null, gift = null) {
  if (!row?.npc?.npc_id || !gift) return [];
  const npcId = row.npc.npc_id;
  const selector = `button[data-canvas-town-gift="${selectorDataValue(npcId)}"], button[data-npc-gift="${selectorDataValue(npcId)}"], button[data-town-opportunity-gift="${selectorDataValue(npcId)}"]`;
  return [
    {
      key: "npc",
      label: "送给谁",
      badge: "人",
      title: npcName(npcId),
      text: `${row.area || "凡仙镇"} · ${row.action || "今日动线"}`,
      detail: `好感 Lv.${row.level ?? favorLevel(state.npcFavor[npcId] || 0)} · 今日还没收礼`,
      selector,
    },
    {
      key: "gift",
      label: "送什么",
      badge: "礼",
      title: gift.itemName,
      text: gift.reason || "普通心意，胜在顺手",
      detail: `好感 +${gift.favorGain} · ${gift.tone === "liked" ? "合偏好" : gift.tone === "bad" ? "有忌口" : "顺手礼"}`,
      selector,
    },
    {
      key: "confirm",
      label: "确认入口",
      badge: "送",
      title: "关系面板确认",
      text: `赠出 ${gift.itemName}`,
      detail: "只定位确认，不自动赠礼",
      selector,
    },
  ].map((node) => ({
    ...node,
    shortLabel: townLifeWorldBoardShortText(node.label, 6),
    shortTitle: townLifeWorldBoardShortText(node.title, 8),
    shortText: townLifeWorldBoardShortText(node.text, 14),
  }));
}

function townLifeGiftKeepsakeSpec(target = null, rows = townLifeRows(6), canvasWidth = refs.world?.width || 960, canvasHeight = refs.world?.height || 640) {
  const activeFocus = townLifeGiftKeepsakeWorldFocus?.day === state.day ? townLifeGiftKeepsakeWorldFocus : null;
  const npcId = target?.gift?.npcId || target?.row?.npc?.npc_id || target?.npcId || activeFocus?.npcId || "";
  if (!npcId || townLifeGiftSeen(npcId)) return null;
  const visibleRows = (rows || townLifeRows(6)).filter((entry) => entry.status.key !== "away").slice(0, 5);
  const row = target?.row
    || visibleRows.find((entry) => entry.npc.npc_id === npcId)
    || canvasTownLifeFocusRow(npcId)
    || null;
  if (!row?.npc?.npc_id) return null;
  const gift = target?.gift || recommendedNpcGift(npcId);
  if (!gift) return null;
  const rowIndex = visibleRows.findIndex((entry) => entry.npc.npc_id === row.npc.npc_id);
  const point = rowIndex >= 0 ? townLifeWorldPoint(visibleRows[rowIndex], rowIndex) : activeFocus?.point || null;
  const width = 318;
  const height = 152;
  const preferLeft = point ? point.x > canvasWidth * 0.58 : false;
  const rect = {
    x: Math.max(18, Math.min(canvasWidth - width - 18, point ? point.x + (preferLeft ? -width - 28 : 70) : 354)),
    y: Math.max(84, Math.min(canvasHeight - height - 28, point ? point.y + 54 : 322)),
    width,
    height,
  };
  const nodes = townLifeGiftKeepsakeNodes(row, gift);
  const nodeWidth = Math.floor((width - 52) / 3);
  nodes.forEach((node, index) => {
    node.rect = {
      x: rect.x + 16 + index * (nodeWidth + 10),
      y: rect.y + 98,
      width: nodeWidth,
      height: 34,
    };
  });
  return {
    key: `${state.day}:${npcId}:${gift.itemId}:gift_keepsake`,
    day: state.day,
    npcId,
    row,
    gift: { ...gift, npcId },
    point,
    rect,
    nodes,
    activeNode: target?.activeNode || nodes.find((node) => node.key === activeFocus?.nodeKey) || nodes[2] || nodes[0],
    title: "今日赠礼留签 · 可点",
    subtitle: `${npcName(npcId)} · ${gift.itemName}`,
    giftLine: townLifeWorldBoardShortText(`${gift.itemName} · 好感 +${gift.favorGain}`, 22),
    reasonText: townLifeWorldBoardShortText(gift.reason || "普通心意，胜在顺手", 25),
    safety: "只定位确认，不自动赠礼",
    tone: gift.tone || "plain",
  };
}

function townLifeGiftKeepsakeAtCanvasPoint(px, py) {
  const spec = townLifeGiftKeepsakeSpec();
  if (!spec?.rect || townLifeGiftKeepsakeWorldFocus?.day !== state.day) return null;
  const { rect } = spec;
  if (px < rect.x || px > rect.x + rect.width || py < rect.y || py > rect.y + rect.height) return null;
  const activeNode = spec.nodes.find((node) => {
    const nodeRect = node.rect;
    return nodeRect && px >= nodeRect.x && px <= nodeRect.x + nodeRect.width && py >= nodeRect.y && py <= nodeRect.y + nodeRect.height;
  }) || spec.nodes[2] || spec.nodes[0];
  return { ...spec, activeNode };
}

function focusTownLifeGiftKeepsakeFromCanvas(target = null, options = {}) {
  const npcId = target?.npcId || target?.row?.npc?.npc_id || "";
  const spec = townLifeGiftKeepsakeSpec(target, townLifeRows(6));
  if (!spec?.gift || !spec.npcId) {
    addLog("今日赠礼留签", `${npcId ? npcName(npcId) : "这位镇民"}今天暂无可定位的推荐赠礼。${townLifeGiftSafetyText()}`);
    return renderLogs();
  }
  const activeNode = target?.activeNode
    || spec.nodes.find((node) => node.key === options.nodeKey)
    || spec.nodes[2]
    || spec.nodes[0];
  townLifeGiftKeepsakeWorldFocus = {
    key: spec.key,
    nodeKey: activeNode?.key || "confirm",
    day: state.day,
    npcId: spec.npcId,
    giftItemId: spec.gift.itemId,
    point: spec.point ? { x: Math.round(spec.point.x), y: Math.round(spec.point.y) } : null,
    source: options.source || "canvas",
  };
  canvasTownLifeFocus = {
    npcId: spec.npcId,
    day: state.day,
    area: spec.row?.area || "凡仙镇",
    action: spec.row?.action || "今日赠礼",
    source: "town_life_gift_keepsake",
    point: spec.point ? { x: Math.round(spec.point.x), y: Math.round(spec.point.y) } : null,
  };
  queueStoryCompassFocusTarget({
    selector: activeNode?.selector || `button[data-canvas-town-gift="${selectorDataValue(spec.npcId)}"], button[data-npc-gift="${selectorDataValue(spec.npcId)}"]`,
    fallbackSelector: "#relationshipPanel",
    label: options.source === "keepsake" ? `点选今日赠礼留签：${activeNode?.label || "确认入口"}` : "今日赠礼留签",
    log: `${npcName(spec.npcId)} · ${activeNode?.label || "确认入口"}：${activeNode?.title || spec.gift.itemName}。${activeNode?.text || spec.gift.reason} ${activeNode?.detail || ""}。${townLifeGiftSafetyText()}`,
    panelGroup: "systems",
    missingTitle: "今日赠礼留签",
    missingLog: `${npcName(spec.npcId)}的赠礼按钮暂时没有找到，先打开关系面板查看推荐赠礼。${townLifeGiftSafetyText()}`,
  });
  return true;
}

function greetTownLifeNpc(npcId = "") {
  const row = townLifeRows(12).find((entry) => entry.npc.npc_id === npcId)
    || (() => {
      const npc = data.npcsById.get(npcId);
      if (!npc || npc.npc_id === "npc_system") return null;
      const schedule = currentScheduleFor(npcId);
      return {
        npc,
        schedule,
        value: state.npcFavor[npcId] || 0,
        level: favorLevel(state.npcFavor[npcId] || 0),
        status: townLifeStatus(schedule, npcId),
        area: schedule ? areaName(schedule.area_id) : "镇中未见",
        action: scheduleActionLabel(schedule),
        bark: npcTownLifeBark(npc, schedule),
      };
    })();
  if (!row) return addLog("镇民寒暄", "今天暂时没在镇上遇到这位镇民。");
  const townState = syncTownLifeInteractionState();
  const key = townLifeGreetingKey(row.npc.npc_id);
  if (townState.greetedByDay[key]) {
    addLog("今日已寒暄", `${npcName(row.npc.npc_id)}已经把今天的近况告诉过你了，晚些再来镇上看看。`);
    return render();
  }
  const weatherMoment = row.weatherMoment || townLifeWeatherMomentSpec(row);
  const favorGain = row.status.key === "urgent" ? 3 : row.status.key === "festival" ? 2 : 1;
  const entry = {
    day: state.day,
    npcId: row.npc.npc_id,
    npcName: npcName(row.npc.npc_id),
    area: row.area,
    action: row.action,
    status: row.status.key,
    statusLabel: row.status.label,
    line: townLifeGreetingLine(row),
    weatherMomentKey: weatherMoment?.key || "",
    weatherLabel: weatherMoment?.label || "",
    weatherName: weatherMoment?.weatherName || "",
    favorGain,
  };
  townState.greetedByDay[key] = true;
  townState.last = entry;
  townState.history.unshift(entry);
  townState.history = townState.history.slice(0, 12);
  const errand = acceptTownLifeErrand(row);
  addNpcFavor(row.npc.npc_id, favorGain, `今日镇民动线 · ${row.status.label}`);
  state.activeDialogue = [
    ...state.activeDialogue.slice(-3),
    {
      speakerId: row.npc.npc_id,
      speaker: entry.npcName,
      text: entry.line,
      groupId: `town_life_greeting_${row.npc.npc_id}`,
      lineOrder: 0,
    },
  ];
  recordTownLifeInteraction(row.npc.npc_id, "greet");
  recordDailyIntentProgress("relationship", `${entry.npcName} 在${entry.area}寒暄`, {
    amount: errand ? 2 : 1,
    rewardText: `好感 +${favorGain}${entry.weatherLabel ? ` · ${entry.weatherLabel}` : ""}${errand ? ` · 小托付：${errand.title}` : ""}`,
    target: `npc:${row.npc.npc_id}`,
  });
  playCue("对话翻页");
  addLog("镇民寒暄", `${entry.npcName} · ${entry.area}：${entry.line} 好感 +${favorGain}。${errand ? ` 今日小托付：${errand.title}，需要 ${errand.itemName} x${errand.count}${errand.weatherLabel ? `，缘由：${errand.weatherLabel}` : ""}。` : ""}`);
  render();
}

function townLifeNpcAtCanvasPoint(px, py) {
  return townLifeRows(6)
    .filter((row) => row.status.key !== "away")
    .slice(0, 5)
    .map((row, index) => ({ row, point: townLifeWorldPoint(row, index) }))
    .find(({ point }) => px >= point.x - 18 && px <= point.x + 58 && py >= point.y - 32 && py <= point.y + 66)
    ?.row || null;
}

function townLifeRelationshipWorldBoardAtCanvasPoint(px, py) {
  const spec = townLifeRelationshipWorldBoardSpec();
  if (!spec?.rect) return null;
  const { rect } = spec;
  return px >= rect.x && px <= rect.x + rect.width && py >= rect.y && py <= rect.y + rect.height
    ? spec
    : null;
}

function focusTownLifeRelationshipWorldBoardFromCanvas(spec = townLifeRelationshipWorldBoardSpec()) {
  if (!spec) return false;
  const row = spec.row || canvasTownLifeFocusRow(spec.npcId);
  if (spec.npcId) {
    const visibleRows = townLifeRows(6).filter((entry) => entry.status.key !== "away").slice(0, 5);
    const pointIndex = visibleRows.findIndex((entry) => entry.npc.npc_id === spec.npcId);
    const point = pointIndex >= 0 ? townLifeWorldPoint(visibleRows[pointIndex], pointIndex) : spec.point;
    canvasTownLifeFocus = {
      npcId: spec.npcId,
      day: state.day,
      area: row?.area || spec.area,
      action: row?.action || spec.action,
      source: "relationship_board",
      point: point ? { x: Math.round(point.x), y: Math.round(point.y) } : null,
    };
  }
  townLifeRelationshipWorldBoardFocus = {
    key: spec.key,
    day: state.day,
    npcId: spec.npcId,
    title: spec.title,
    actionLabel: spec.actionLabel,
  };
  queueStoryCompassFocusTarget({
    selector: spec.npcId ? `[data-npc-id="${selectorDataValue(spec.npcId)}"]` : ".town-life-opportunity-board",
    fallbackSelector: ".town-life-opportunity-board",
    label: "点选关系路标",
    log: spec.npcId
      ? `${spec.npcName} · ${spec.title}：${spec.detail} 已高亮关系卡；下一步建议 ${spec.actionLabel}。`
      : `${spec.title}：${spec.detail} 已展开今日关系机会。`,
    panelGroup: "systems",
    missingTitle: "点选关系路标",
    missingLog: "关系路标已经判断出今日机会，但关系面板里暂时没有找到对应卡片。",
  });
  return true;
}

function townLifeErrandRouteCueAtCanvasPoint(px, py) {
  return townLifeErrandPlaqueAtCanvasPoint(px, py)?.row || null;
}

function townLifeErrandPlaqueAtCanvasPoint(px, py) {
  return townLifeRows(6)
    .filter((row) => row.status.key !== "away")
    .slice(0, 5)
    .map((row, index) => ({ row, cue: townLifeErrandRouteCueSpec(row), point: townLifeWorldPoint(row, index) }))
    .find(({ cue, point }) => cue && px >= point.x + 36 && px <= point.x + 120 && py >= point.y + 48 && py <= point.y + 90)
    || null;
}

function townLifeFeaturedBubbleSpec(rowsInput = null) {
  const rows = rowsInput || townLifeRows(6).filter((row) => row.status.key !== "away");
  if (!rows.length) return null;
  const townState = syncTownLifeInteractionState();
  const recentWeatherErrand = townState.lastWeatherErrand?.day === state.day ? townState.lastWeatherErrand : null;
  const recentGreeting = townState.last?.day === state.day ? townState.last : null;
  const featured = recentWeatherErrand
    ? rows.find((row) => row.npc.npc_id === recentWeatherErrand.npcId) || rows[0]
    : recentGreeting
      ? rows.find((row) => row.npc.npc_id === recentGreeting.npcId) || rows[0]
      : rows.find((row) => row.shopMomentBark) || rows.find((row) => row.careChainBark) || rows.find((row) => row.shopReputationBark) || rows.find((row) => row.status.key === "urgent" || row.status.key === "festival") || rows[0];
  const index = Math.max(0, rows.indexOf(featured));
  const point = townLifeWorldPoint(featured, index);
  const ambientBarkAllowed = !recentWeatherErrand && !recentGreeting;
  const shopMomentBark = ambientBarkAllowed ? featured.shopMomentBark : null;
  const careChainBark = ambientBarkAllowed && !shopMomentBark ? featured.careChainBark : null;
  const reputationBark = ambientBarkAllowed && !shopMomentBark && !careChainBark ? featured.shopReputationBark : null;
  const weatherErrandForFeatured = recentWeatherErrand?.npcId === featured.npc.npc_id ? recentWeatherErrand : null;
  const bubbleText = weatherErrandForFeatured
    ? weatherErrandForFeatured.summary
    : recentGreeting?.npcId === featured.npc.npc_id ? recentGreeting.line : shopMomentBark?.line || shopMomentBark?.summary || careChainBark?.townLine || reputationBark?.line || featured.bark;
  const width = weatherErrandForFeatured || shopMomentBark || careChainBark || reputationBark ? 198 : 178;
  const shortLimit = shopMomentBark ? 16 : 20;
  return {
    featured,
    point,
    rect: { x: point.x + 42, y: point.y + 8, width, height: 42 },
    bubbleText,
    shortBark: bubbleText.length > shortLimit ? `${bubbleText.slice(0, shortLimit)}...` : bubbleText,
    recentGreeting,
    weatherErrandForFeatured,
    shopMomentBark,
    careChainBark,
    reputationBark,
  };
}

function townLifeShopMomentBubbleAtCanvasPoint(px, py) {
  const bubble = townLifeFeaturedBubbleSpec();
  if (!bubble?.shopMomentBark) return null;
  const { rect } = bubble;
  if (px < rect.x || px > rect.x + rect.width || py < rect.y || py > rect.y + rect.height) return null;
  return { row: bubble.featured, moment: bubble.shopMomentBark, rect };
}

function townLifeShopMomentMarkerRect(point = null) {
  if (!point) return null;
  return { x: point.x + 30, y: point.y - 20, width: 48, height: 28 };
}

function townLifeShopMomentMarkerAtCanvasPoint(px, py) {
  return townLifeRows(6)
    .filter((row) => row.status.key !== "away")
    .slice(0, 5)
    .map((row, index) => ({ row, moment: row.shopMomentBark, point: townLifeWorldPoint(row, index) }))
    .find(({ moment, point }) => {
      const rect = moment ? townLifeShopMomentMarkerRect(point) : null;
      return rect && px >= rect.x && px <= rect.x + rect.width && py >= rect.y && py <= rect.y + rect.height;
    })
    || null;
}

function townLifePassalongSafetyText() {
  return "这里只定位镇上传话来源和回看入口，不会自动寒暄、赠礼、接支线、交托付、交单、开铺、领奖、播放对白或消耗资源。";
}

function townLifePassalongCandidateForRow(row = null) {
  if (!row?.npc?.npc_id || row.status?.key === "away") return null;
  const npcId = row.npc.npc_id;
  const npcLabel = npcName(npcId);
  const opening = syncShopOpeningState();
  const reputation = row.shopReputationBark || shopReputationTownBarkSpec(row);
  const careEcho = row.careChainBark || careChainEchoSpec(state.careChainState, row);
  const weatherMoment = row.weatherMoment || townLifeWeatherMomentSpec(row);
  const firstSale = opening.firstSale || opening.lastSession?.firstSale || null;
  const candidates = [];
  if (reputation) {
    candidates.push({
      id: `shop:${reputation.stageName || "stage"}:${npcId}`,
      type: "shop_reputation",
      tone: reputation.tone || "shop",
      badge: "铺",
      title: "旧铺名声顺路传开",
      headline: reputation.label || reputation.stageName || "镇上传话",
      line: reputation.line,
      detail: reputation.detail,
      sourceLabel: reputation.stageName || "旧铺名声",
      routeLabel: "看旧铺名声",
      selector: `[data-shop-reputation-stage="${selectorDataValue(shopReputationStageSpec().stageKey)}"]`,
      fallbackSelector: "#shopReport",
      panelGroup: "core",
      priority: 136 + Number(shopReputationStageSpec().progressCount || 0),
    });
  }
  if (firstSale && (opening.summaryUnlocked || state.completed.has("shop") || state.completed.has("first_shop_sale_summary"))) {
    candidates.push({
      id: `first_sale:${firstSale.itemId || firstSale.itemName || "goods"}:${npcId}`,
      type: "first_sale_seen",
      tone: "warm",
      badge: "账",
      title: "首单被镇上看见",
      headline: `${firstSale.itemName || "第一件货"}有了第一句后话`,
      line: `${npcLabel}顺路听见有人提起旧铺首单：${firstSale.name || "第一位顾客"}买走${firstSale.itemName || "一件货"}，这扇门开始被记住了。`,
      detail: `成交原因：${firstSale.reasonText || firstSale.reviewQuote || "货、价和今日客需对上了。"} 这会把旧铺从一次买卖推向熟客苗头。`,
      sourceLabel: "旧铺首单",
      routeLabel: "看首单账页",
      selector: "[data-shop-board=\"opening\"]",
      fallbackSelector: "#shopReport",
      panelGroup: "core",
      priority: 122,
    });
  }
  if (careEcho) {
    candidates.push({
      id: `care:${careEcho.tone || "chain"}:${npcId}`,
      type: "care_chain",
      tone: careEcho.tone || "care",
      badge: "生",
      title: "洞天生机传到镇上",
      headline: careEcho.title || careEcho.stageName || "照应成线",
      line: careEcho.townLine || `${npcLabel}听见洞天这几日有人照应，顺手把这句好话带回镇上。`,
      detail: `${careEcho.detail || "连续照应让镇民开始把洞天当成稳定日常。"}${careEcho.streak ? ` · 连续照应 ${careEcho.streak} 日` : ""}`,
      sourceLabel: careEcho.stageName || "洞天照应札记",
      routeLabel: "看照应札记",
      selector: ".care-chain-journal",
      fallbackSelector: "#goalBookPanel",
      panelGroup: "core",
      priority: 118 + Number(careEcho.streak || 0),
    });
  }
  if (state.canalRepaired || state.completed.has("repair")) {
    candidates.push({
      id: `canal:${npcId}`,
      type: "canal_repaired",
      tone: "water",
      badge: "渠",
      title: "灵渠复流传进镇口",
      headline: "水路重新有了声音",
      line: `${npcLabel}经过镇口时说，洞天那边的水声已经能听见了，断掉的路像是重新接回凡仙镇。`,
      detail: `${weatherMoment?.label ? `${weatherMoment.label}里，` : ""}灵渠复流让水田、料理和镇上小托付都多了一条能被看见的来路。`,
      sourceLabel: "灵渠修复",
      routeLabel: "看修复路线",
      selector: "#missionPanel",
      fallbackSelector: "#goalBookPanel",
      panelGroup: "core",
      priority: 110,
    });
  }
  if ((state.completed.has("clear") || Number(state.clearedDebris || 0) > 0) && !state.completed.has("shop")) {
    candidates.push({
      id: `clear:${npcId}`,
      type: "grotto_clear",
      tone: "sprout",
      badge: "露",
      title: "清荒露纹被人看见",
      headline: "第一口气传到镇上",
      line: `${npcLabel}顺路看见洞天露纹亮了一下，说那块荒地终于不像被人忘在山里。`,
      detail: "清荒后的露纹不只是特效，它把修复目标提前变成镇民能看见的一点变化。",
      sourceLabel: "开场清荒",
      routeLabel: "看复苏总览",
      selector: "#missionPanel",
      fallbackSelector: "#goalBookPanel",
      panelGroup: "core",
      priority: 96,
    });
  }
  return candidates
    .filter((candidate) => candidate.line)
    .sort((a, b) => Number(b.priority || 0) - Number(a.priority || 0))[0] || null;
}

function townLifePassalongRows(rowsInput = null, limit = 3) {
  const rows = (rowsInput || townLifeRows(6))
    .filter((row) => row.status.key !== "away")
    .slice(0, 5);
  return rows
    .map((row, index) => {
      const passalong = townLifePassalongCandidateForRow(row);
      if (!passalong) return null;
      return {
        row,
        index,
        point: townLifeWorldPoint(row, index),
        passalong,
      };
    })
    .filter(Boolean)
    .sort((a, b) => Number(b.passalong.priority || 0) - Number(a.passalong.priority || 0))
    .slice(0, limit);
}

function townLifePassalongLanternSpec(target = null, rows = townLifeRows(6), canvasWidth = refs.world?.width || 960, canvasHeight = refs.world?.height || 640) {
  const activeFocus = townLifePassalongLanternWorldFocus?.day === state.day ? townLifePassalongLanternWorldFocus : null;
  const passalongRows = townLifePassalongRows(rows, 3);
  const picked = target?.row && target?.passalong
    ? { row: target.row, index: target.index || 0, point: target.point || townLifeWorldPoint(target.row, target.index || 0), passalong: target.passalong }
    : activeFocus?.npcId
      ? passalongRows.find((entry) => entry.row.npc.npc_id === activeFocus.npcId && entry.passalong.type === activeFocus.type) || passalongRows[0]
      : passalongRows[0];
  if (!picked?.row?.npc?.npc_id || !picked.passalong) return null;
  const { row, passalong, point } = picked;
  const width = 328;
  const height = 156;
  const preferLeft = point ? point.x > canvasWidth * 0.54 : false;
  const rect = {
    x: Math.max(18, Math.min(canvasWidth - width - 18, point ? point.x + (preferLeft ? -width - 38 : 76) : 354)),
    y: Math.max(70, Math.min(canvasHeight - height - 24, point ? point.y - 132 : 282)),
    width,
    height,
  };
  const nodes = [
    {
      key: "who",
      label: "谁捎来",
      badge: "人",
      title: npcName(row.npc.npc_id),
      text: `${row.area || "凡仙镇"} · ${row.action || "今日动线"}`,
      detail: passalong.line,
      selector: `[data-npc-id="${selectorDataValue(row.npc.npc_id)}"]`,
      fallbackSelector: "#relationshipPanel",
      panelGroup: "systems",
    },
    {
      key: "what",
      label: "捎哪件事",
      badge: passalong.badge || "话",
      title: passalong.headline,
      text: passalong.detail,
      detail: passalong.sourceLabel,
      selector: passalong.selector,
      fallbackSelector: passalong.fallbackSelector,
      panelGroup: passalong.panelGroup || "core",
    },
    {
      key: "where",
      label: "回看入口",
      badge: "看",
      title: passalong.routeLabel || "定位来源",
      text: "定位这句传话背后的关系、店铺或目标册证据。",
      detail: "只定位来源，不自动推进",
      selector: passalong.selector,
      fallbackSelector: passalong.fallbackSelector,
      panelGroup: passalong.panelGroup || "core",
    },
  ].map((node) => ({
    ...node,
    shortLabel: townLifeWorldBoardShortText(node.label, 6),
    shortTitle: townLifeWorldBoardShortText(node.title, 8),
    shortText: townLifeWorldBoardShortText(node.text, 15),
  }));
  const nodeWidth = Math.floor((width - 52) / 3);
  nodes.forEach((node, index) => {
    node.rect = {
      x: rect.x + 16 + index * (nodeWidth + 10),
      y: rect.y + 100,
      width: nodeWidth,
      height: 34,
    };
  });
  return {
    key: `${state.day}:${row.npc.npc_id}:${passalong.type}:${passalong.id}:passalong_lantern`,
    day: state.day,
    npcId: row.npc.npc_id,
    row,
    point,
    rect,
    passalong,
    nodes,
    activeNode: target?.activeNode || nodes.find((node) => node.key === activeFocus?.nodeKey) || nodes[2] || nodes[0],
    title: "镇民顺路捎话灯 · 可点",
    subtitle: `${npcName(row.npc.npc_id)} · ${passalong.title}`,
    shortLine: townLifeWorldBoardShortText(passalong.line, 27),
    shortDetail: townLifeWorldBoardShortText(passalong.detail, 24),
    safety: "只定位来源，不自动推进",
  };
}

function townLifePassalongLanternAtCanvasPoint(px, py) {
  const spec = townLifePassalongLanternSpec();
  if (!spec?.rect) return null;
  const { rect } = spec;
  if (px < rect.x || px > rect.x + rect.width || py < rect.y || py > rect.y + rect.height) return null;
  const activeNode = spec.nodes.find((node) => {
    const nodeRect = node.rect;
    return nodeRect && px >= nodeRect.x && px <= nodeRect.x + nodeRect.width && py >= nodeRect.y && py <= nodeRect.y + nodeRect.height;
  }) || spec.nodes[2] || spec.nodes[0];
  return { ...spec, activeNode };
}

function townLifePassalongMarkerAtCanvasPoint(px, py) {
  return townLifePassalongRows(townLifeRows(6), 3)
    .find(({ point }) => {
      const rect = point ? { x: point.x + 72, y: point.y - 10, width: 76, height: 34 } : null;
      return rect && px >= rect.x && px <= rect.x + rect.width && py >= rect.y && py <= rect.y + rect.height;
    })
    || null;
}

function focusTownLifePassalongLanternFromCanvas(target = null, options = {}) {
  const spec = townLifePassalongLanternSpec(target, townLifeRows(6));
  if (!spec?.npcId || !spec.passalong) {
    addLog("镇民顺路捎话灯", `今天暂时没有可定位的镇上传话。${townLifePassalongSafetyText()}`);
    return renderLogs();
  }
  const activeNode = target?.activeNode
    || spec.nodes.find((node) => node.key === options.nodeKey)
    || spec.nodes[2]
    || spec.nodes[0];
  townLifePassalongLanternWorldFocus = {
    key: spec.key,
    nodeKey: activeNode?.key || "where",
    day: state.day,
    npcId: spec.npcId,
    type: spec.passalong.type,
    source: options.source || "canvas",
    point: spec.point ? { x: Math.round(spec.point.x), y: Math.round(spec.point.y) } : null,
  };
  canvasTownLifeFocus = {
    npcId: spec.npcId,
    day: state.day,
    area: spec.row?.area || "凡仙镇",
    action: spec.row?.action || "镇上传话",
    source: "town_life_passalong_lantern",
    point: spec.point ? { x: Math.round(spec.point.x), y: Math.round(spec.point.y) } : null,
  };
  queueStoryCompassFocusTarget({
    selector: activeNode?.selector || spec.passalong.selector || `[data-npc-id="${selectorDataValue(spec.npcId)}"]`,
    fallbackSelector: activeNode?.fallbackSelector || spec.passalong.fallbackSelector || "#relationshipPanel",
    label: options.source === "marker" ? "点选镇民顺路捎话灯" : `点选镇民顺路捎话灯：${activeNode?.label || "回看入口"}`,
    log: `${npcName(spec.npcId)} · ${activeNode?.label || "回看入口"}：${activeNode?.title || spec.passalong.title}。${activeNode?.text || spec.passalong.line} ${activeNode?.detail || ""}。${townLifePassalongSafetyText()}`,
    panelGroup: activeNode?.panelGroup || spec.passalong.panelGroup || "core",
    missingTitle: "镇民顺路捎话灯",
    missingLog: `${npcName(spec.npcId)}的传话来源暂时没有找到，先打开关系面板或目标册回看。${townLifePassalongSafetyText()}`,
  });
  return true;
}

function canvasTownLifeFocusRow(npcId = "") {
  const row = townLifeRows(12).find((entry) => entry.npc.npc_id === npcId);
  if (row) return row;
  const npc = data.npcsById.get(npcId);
  if (!npc || npc.npc_id === "npc_system") return null;
  const schedule = currentScheduleFor(npcId);
  const fallbackRow = {
    npc,
    schedule,
    value: state.npcFavor[npcId] || 0,
    level: favorLevel(state.npcFavor[npcId] || 0),
    status: townLifeStatus(schedule, npcId),
    area: schedule ? areaName(schedule.area_id) : "镇中未见",
    action: scheduleActionLabel(schedule),
    bark: npcTownLifeBark(npc, schedule),
    shopReputationBark: null,
    shopMomentBark: null,
  };
  fallbackRow.shopReputationBark = shopReputationTownBarkSpec(fallbackRow);
  fallbackRow.shopMomentBark = townLifeShopMomentBarkSpec(fallbackRow);
  fallbackRow.careChainBark = careChainEchoSpec(state.careChainState, fallbackRow);
  fallbackRow.weatherMoment = townLifeWeatherMomentSpec(fallbackRow);
  return fallbackRow;
}

function focusTownLifeNpcFromCanvas(row) {
  if (!row?.npc?.npc_id) return false;
  const pointIndex = townLifeRows(6)
    .filter((entry) => entry.status.key !== "away")
    .slice(0, 5)
    .findIndex((entry) => entry.npc.npc_id === row.npc.npc_id);
  const point = pointIndex >= 0 ? townLifeWorldPoint(row, pointIndex) : null;
  canvasTownLifeFocus = {
    npcId: row.npc.npc_id,
    day: state.day,
    area: row.area,
    action: row.action,
    source: "canvas",
    point: point ? { x: Math.round(point.x), y: Math.round(point.y) } : null,
  };
  const greetingSpec = townLifeGreetingKeepsakeSpec({ row }, townLifeRows(6));
  townLifeGreetingKeepsakeWorldFocus = greetingSpec?.rect
    ? {
      key: greetingSpec.key,
      nodeKey: "confirm",
      day: state.day,
      npcId: row.npc.npc_id,
      point: greetingSpec.point ? { x: Math.round(greetingSpec.point.x), y: Math.round(greetingSpec.point.y) } : null,
      source: "npc",
    }
    : null;
  const giftSpec = townLifeGiftKeepsakeSpec({ row }, townLifeRows(6));
  townLifeGiftKeepsakeWorldFocus = giftSpec?.rect
    ? {
      key: giftSpec.key,
      nodeKey: "confirm",
      day: state.day,
      npcId: row.npc.npc_id,
      giftItemId: giftSpec.gift.itemId,
      point: giftSpec.point ? { x: Math.round(giftSpec.point.x), y: Math.round(giftSpec.point.y) } : null,
      source: "npc",
    }
    : null;
  if (settings.panelGroup !== "systems") {
    settings.panelGroup = "systems";
    saveSettings();
  }
  playCue("对话翻页");
  addLog("主画面遇见", `${npcName(row.npc.npc_id)}正在${row.area}${row.action}，关系面板已展开今日互动。`);
  render();
  return true;
}

function canvasTownLifeFocusSpec() {
  const npcId = canvasTownLifeFocus?.npcId || "";
  if (!npcId) return null;
  const row = canvasTownLifeFocusRow(npcId);
  if (!row) return null;
  const greetingSeen = townLifeGreetingSeen(npcId);
  const errand = townLifeErrandStatus(row);
  const gift = recommendedNpcGift(npcId);
  const giftDone = townLifeGiftSeen(npcId);
  const memory = latestTownLifeMemory(npcId);
  const sideClue = sideQuestClueForNpc(npcId);
  const counts = townLifeInteractionCounts(npcId);
  const weatherMoment = row.weatherMoment || townLifeWeatherMomentSpec(row);
  const weatherErrandEcho = latestTownLifeWeatherErrand(npcId);
  const focusAge = Math.max(0, state.day - Number(canvasTownLifeFocus.day || state.day));
  const sourceText = focusAge > 0
    ? `第 ${canvasTownLifeFocus.day} 天从主画面点选，今日动线已刷新`
    : "刚从主画面点到这位镇民";
  return {
    row,
    npcId,
    greetingSeen,
    errand,
    gift,
    giftDone,
    memory,
    sideClue,
    counts,
    weatherMoment,
    weatherErrandEcho,
    sourceText,
    canGreet: row.status.key !== "away" && !greetingSeen,
    canErrand: Boolean(greetingSeen && errand && !errand.completed && errand.ready),
    canGift: Boolean(!giftDone && gift),
  };
}

function canvasTownLifeFocusMarkup() {
  const focus = canvasTownLifeFocusSpec();
  if (!focus) return "";
  const { row, npcId, greetingSeen, errand, gift, giftDone, memory, sideClue, counts, weatherMoment, weatherErrandEcho } = focus;
  const shopMoment = latestTownLifeShopMoment(npcId);
  const errandState = errand?.completed ? "done" : errand?.ready ? "ready" : "pending";
  const errandRoute = errand && !errand.completed && !errand.ready ? townLifeErrandRouteSpec(errand) : null;
  const errandMarkup = errand
    ? `<span class="canvas-town-life-errand ${errandState}">${greetingSeen ? "今日小托付" : "寒暄后可接"}：${errand.title} · ${errand.itemName} ${errand.have}/${errand.count} · 回礼 ${errand.rewardGold} 灵石${errand.rewardFame ? ` / 声望 +${errand.rewardFame}` : ""}${errand.weatherHint ? `<small>天气缘由：${errand.weatherHint}</small>` : ""}</span>`
    : `<span class="canvas-town-life-errand pending">今日小托付：这位镇民暂时不在可承接状态。</span>`;
  const errandRouteMarkup = errandRoute
    ? `<span class="canvas-town-life-errand-route ${errandRoute.type}">天气托付备货：${errandRoute.label} · ${errandRoute.title}<small>${errandRoute.headline} · ${errandRoute.detail}</small></span>`
    : "";
  const giftMarkup = giftDone
    ? `<span class="canvas-town-life-gift done">今日已赠礼：${syncTownLifeInteractionState().giftsByDay[townLifeGiftKey(npcId)]?.itemName || "一份心意"}</span>`
    : gift
      ? `<span class="canvas-town-life-gift ${gift.tone}">推荐赠礼：${gift.itemName} · ${gift.reason} · 好感 +${gift.favorGain}</span>`
      : `<span class="canvas-town-life-gift empty">推荐赠礼：背包里暂无合适礼物。</span>`;
  const memoryMarkup = memory
    ? `<span class="canvas-town-life-memory unlocked">最近记忆：${memory.title} · ${memory.summary}</span>`
    : `<span class="canvas-town-life-memory pending">最近记忆：还没有写进关系册的小事。</span>`;
  const shopMomentMarkup = shopMoment
    ? `<span class="canvas-town-life-shop ${shopMoment.fresh ? "fresh" : "archive"}">旧铺后话：${shopMoment.summary}${shopMoment.rewardText ? ` · ${shopMoment.rewardText}` : ""}</span>`
    : `<span class="canvas-town-life-shop empty">旧铺后话：等一笔从旧铺接到镇上的顺手来往落下来。</span>`;
  const sideQuestMarkup = sideClue
    ? `<span class="canvas-town-life-side ${sideClue.status}">支线线索：${questTitle(sideClue.quest)} · ${sideQuestClueStatusText(sideClue)}${sideClue.currentStep ? ` · ${stepLabel(sideClue.currentStep)}` : ""}</span>`
    : `<span class="canvas-town-life-side empty">支线线索：今天先从日常寒暄、托付和赠礼积累关系。</span>`;
  const reputationBark = row.shopReputationBark || shopReputationTownBarkSpec(row);
  const reputationMarkup = reputationBark
    ? `<span class="canvas-town-life-reputation ${reputationBark.tone}">镇上传话：${reputationBark.line}<small>${reputationBark.stageName} · ${reputationBark.detail}</small></span>`
    : "";
  const careChainBark = row.careChainBark || careChainEchoSpec(state.careChainState, row);
  const careChainMarkup = careChainBark
    ? `<span class="canvas-town-life-reputation care-chain ${careChainBark.tone}">洞天生机：${careChainBark.townLine}<small>${careChainBark.stageName} · 连续照应 ${careChainBark.streak} 日 · ${careChainBark.detail}</small></span>`
    : "";
  const passalong = townLifePassalongCandidateForRow(row);
  const passalongMarkup = passalong
    ? `<span class="canvas-town-life-reputation passalong ${passalong.tone}">顺路捎话：${passalong.line}<small>${passalong.sourceLabel} · ${passalong.detail}</small></span>`
    : "";
  const weatherMomentMarkup = weatherMoment
    ? `<span class="canvas-town-life-weather ${weatherMoment.tone || "water"}">镇民天气小景：${weatherMoment.label} · ${weatherMoment.prop}<small>${weatherMoment.text}<br />${weatherMoment.detail}</small></span>`
    : "";
  const weatherErrandEchoMarkup = weatherErrandEcho
    ? `<span class="canvas-town-life-weather-echo ${weatherErrandEcho.tone || "gold"}">${weatherErrandEcho.title}<small>${weatherErrandEcho.summary}<br />${weatherErrandEcho.rewardText}</small></span>`
    : "";
  const errandButtonLabel = !greetingSeen ? "先寒暄接托付" : errand?.completed ? "托付已办妥" : errand?.ready ? "交付小托付" : "材料不足";
  const sideButtonLabel = sideClue?.rewardReady ? "去领取奖励" : sideClue?.active ? "追踪支线" : sideClue?.ready ? "承接支线" : "线索未满";
  return `
    <div class="canvas-town-life-focus ${row.status.key}" data-canvas-town-focus="${npcId}">
      <div class="canvas-town-life-hero">
        <img src="${npcPortraitSrc(npcId)}" alt="${npcName(npcId)}头像" loading="lazy" />
        <div>
          <strong>主画面遇见 · ${npcName(npcId)}</strong>
          <span>${row.area} · ${row.action} · ${row.status.label}</span>
        </div>
      </div>
      <small>${focus.sourceText} · 好感 Lv.${row.level}（${row.value}/100）· 来往 ${counts.total} 次</small>
      <span class="canvas-town-life-bark">“${row.bark}”</span>
      ${weatherMomentMarkup}
      ${weatherErrandEchoMarkup}
      ${passalongMarkup}
      ${careChainMarkup}
      ${reputationMarkup}
      ${errandMarkup}
      ${errandRouteMarkup}
      ${shopMomentMarkup}
      ${giftMarkup}
      ${memoryMarkup}
      ${sideQuestMarkup}
      <div class="canvas-town-life-actions">
        <button type="button" data-canvas-town-greet="${npcId}" ${focus.canGreet ? "" : "disabled"}>${greetingSeen ? "今日已寒暄" : row.status.key === "away" ? "不在镇上" : "打个招呼"}</button>
        <button type="button" data-canvas-town-errand="${npcId}" ${focus.canErrand ? "" : "disabled"}>${errandButtonLabel}</button>
        ${errandRoute ? `<button type="button" data-canvas-town-errand-route="${npcId}">${errandRoute.buttonLabel || "看备货路线"}</button>` : ""}
        <button type="button" data-canvas-town-gift="${npcId}" ${focus.canGift ? "" : "disabled"}>${giftDone ? "今日已赠" : gift ? "赠送推荐礼物" : "无合适礼物"}</button>
        ${sideClue ? `<button type="button" data-canvas-town-side-quest="${sideClue.quest.quest_id}" data-canvas-town-side-npc="${npcId}" ${sideClue.ready || sideClue.active || sideClue.rewardReady ? "" : "disabled"}>${sideButtonLabel}</button>` : ""}
        ${shopMoment ? `<button type="button" data-canvas-town-shop-npc="${npcId}" data-canvas-town-shop-id="${shopMoment.id}">翻看旧铺后话</button>` : ""}
        ${memory ? `<button type="button" data-canvas-town-memory-npc="${npcId}" data-canvas-town-memory-id="${memory.memoryId}">翻看最近记忆</button>` : ""}
        <button type="button" data-canvas-town-close="${npcId}">收起</button>
      </div>
    </div>
  `;
}

function townLifeNextMemoryPreview(npcId = "") {
  const memories = TOWN_LIFE_MEMORY_BOOK[npcId] || [];
  const remembered = syncTownLifeInteractionState().memoryByNpc?.[npcId] || {};
  const runtimePlan = npcRuntime()?.nextRelationshipMemory({
    npcId,
    memories,
    rememberedMemoryIds: Object.keys(remembered),
  });
  if (runtimePlan && "memory" in runtimePlan) return runtimePlan.memory || null;
  return memories.find((memory) => !remembered[memory.id]) || null;
}

