function earlyRewardNextDelightSpec() {
  const rows = data.earlyRewardPacing
    .slice()
    .sort((a, b) => Number(a.time_min || 0) - Number(b.time_min || 0) || String(a.pace_id).localeCompare(String(b.pace_id)));
  if (!rows.length) return null;
  const guide = earlyRewardPacingGuideSpec();
  const audit = earlyRewardCadenceAuditSpec();
  const activeWindow = audit?.activeWindow || null;
  const previous = rows.filter(earlyRewardDone).slice(-1)[0] || null;
  const activePace = guide.active || activeWindow?.rewards?.[0] || rows[rows.length - 1];
  const completedId = activeWindow?.completedId || earlyRewardCompletedId(activePace) || "day_summary";
  const target = activeWindow?.target || earlyRewardWorldRoadsignTarget(completedId);
  const bridge = activeWindow?.bridge || null;
  const mode = guide.mode || "next";
  const complete = mode === "complete";
  const phase = complete ? "明日主轴接力" : activePace.phase;
  const minuteText = complete ? "180 分钟后" : `${Number(activePace.time_min || 0)} 分钟`;
  const action = complete ? "查看日终总结和明早第一步" : activePace.player_action;
  const instant = complete ? "明早第一步、目标册和日终灯笺一起亮起" : activePace.instant_feedback;
  const delayed = complete
    ? "每日目标、第二年目标册、自由目标和长期养成继续接力"
    : activePace.delayed_feedback || activePace.success_metric || "下一段目标会跟上";
  const successMetric = complete ? "玩家愿意再推进一天" : activePace.success_metric || activePace.delayed_feedback || "玩家知道下一步为什么值得做";
  const currentNode = previous
    ? `${previous.time_min} 分钟 · ${previous.phase}`
    : "0 分钟 · 初入洞天";
  const nextNode = `${minuteText} · ${phase}`;
  const bridgeTitle = bridge?.title || (complete ? "日终目标桥接" : activeWindow?.title || "下一步反馈桥接");
  const bridgeDetail = bridge?.detail || (complete
    ? "把今天的收入、成长、解锁和风险收进总结，再交给明早第一步。"
    : `${activeWindow?.label || "当前 15 分钟窗口"} 内用可见反馈承接等待，不让节奏空掉。`);
  return {
    active: true,
    mode,
    paceId: activePace.pace_id || "",
    completedId,
    phase,
    minuteText,
    action,
    instant,
    delayed,
    successMetric,
    currentNode,
    nextNode,
    targetLabel: target?.label || "定位下一步",
    bridgeTitle,
    bridgeDetail,
    bridgeSource: bridge?.source || activeWindow?.source || "前三小时奖励节奏诊断",
    windowLabel: activeWindow?.label || "15 分钟窗口",
    headline: complete
      ? "前三小时奖励链已经接上，下一处爽点交给日终后的长线目标。"
      : `现在追「${phase}」，玩家能立刻看到「${instant}」。`,
    cadenceText: "每15分钟一个反馈",
    safety: "只定位下一处爽点，不会自动播种、浇水、收获、开铺、定价、补货、交单、派工、处理风险、入夜或消耗资源。",
  };
}

