function dailyIntentMicroTaskSpec(boardRows = null, recommended = null, trend = null) {
  if (!Array.isArray(boardRows)) {
    const board = dailyIntentBoardSpec();
    return board.microTask || null;
  }
  const todaysTrail = (state.dailyIntentTrail || [])
    .map(normalizeDailyIntentTrailEntry)
    .filter((entry) => Number(entry.day || 0) === Number(state.day || 0));
  const todayScores = new Map();
  for (const entry of todaysTrail) todayScores.set(entry.intent, Number(todayScores.get(entry.intent) || 0) + Number(entry.amount || 1));
  const intent = (trend?.pendingToday || Number(trend?.count || 0) >= 2)
    ? trend.intent
    : recommended?.key || boardRows[0]?.key || "field";
  const row = boardRows.find((entry) => entry.key === intent) || recommended || boardRows[0] || null;
  if (!row) return null;
  const copy = dailyIntentMicroTaskCopy(row.key);
  const scene = dailyIntentWorldSceneLabel(row.key);
  const score = Number(todayScores.get(row.key) || 0);
  const done = score > 0;
  return {
    key: row.key,
    tone: row.tone || row.key,
    title: copy.title,
    headline: done ? `${copy.title}已落笔` : copy.headline,
    detail: done
      ? `今天已经留下 ${score} 点${dailyIntentReviewMeta(row.key).label}足迹，入夜会自动写进日结和手账。`
      : copy.detail,
    rewardHint: done
      ? `已完成：主世界的「${scene.title}」会继续提示这条路线。`
      : copy.rewardHint,
    sceneLabel: scene.title,
    actionLabel: scene.action,
    action: row.action,
    target: row.target || "",
    cta: done ? "查看这条线" : copy.cta || row.cta || "定位行动",
    done,
    score,
    trendTitle: trend?.title || "今日主轴",
    trendPending: Boolean(trend?.pendingToday),
  };
}

function dailyIntentMicroTaskMarkup(task = dailyIntentMicroTaskSpec()) {
  if (!task) return "";
  return `
    <div class="daily-intent-micro-task ${task.tone || task.key || "field"} ${task.done ? "done" : "active"}">
      <div>
        <strong>今日主轴小事 · ${task.title}</strong>
        <span>${task.headline}</span>
        <small>${task.detail}</small>
        <small>${task.rewardHint}</small>
      </div>
      <button type="button" data-daily-intent-micro-task="${task.key}" data-daily-intent-micro-action="${task.action}" data-daily-intent-micro-target="${task.target || ""}">${task.cta}</button>
    </div>
  `;
}

function dailyIntentMicroTaskReviewSpec(day = state.day, intent = "field", trail = state.dailyIntentTrail || []) {
  const safeIntent = intent || "field";
  const copy = dailyIntentMicroTaskCopy(safeIntent);
  const scene = dailyIntentWorldSceneLabel(safeIntent);
  const moment = dailyIntentMicroTaskMomentCopy(safeIntent);
  const momentDone = Boolean(state.dailyIntentMilestones?.[`micro:${Number(day || state.day)}:${safeIntent}`]);
  const score = (trail || [])
    .map(normalizeDailyIntentTrailEntry)
    .filter((entry) => Number(entry.day || 0) === Number(day || 0) && entry.intent === safeIntent)
    .reduce((sum, entry) => sum + Number(entry.amount || 1), 0);
  return {
    intent: safeIntent,
    tone: dailyIntentReviewMeta(safeIntent).tone,
    title: copy.title,
    sceneLabel: scene.title,
    done: score > 0,
    score,
    text: score > 0
      ? `${copy.title}完成：${momentDone ? `${moment.title}已触发，` : ""}${scene.title}会在主世界留下回响，今日已记 ${score} 点。`
      : `${copy.title}未完成：明天可从${scene.title}或每日三选里补上这条线。`,
  };
}

