function updateShopControlsFromUi() {
  const beforePrice = state.shopPriceMultiplier;
  const beforeTheme = state.shopShelfTheme;
  const nextPrice = Number(refs.shopPriceMultiplier.value) / 100;
  const nextTheme = refs.shopShelfTheme.value;
  state.shopPriceMultiplier = nextPrice;
  state.shopShelfTheme = nextTheme;
  if (Math.abs(nextPrice - beforePrice) >= 0.01) {
    triggerShopActionFeedback(nextPrice < beforePrice ? "price_down" : "price_adjust", {
      beforePrice,
      afterPrice: nextPrice,
      detail: nextPrice < beforePrice ? "手动把价签往留客侧压了一格。" : "手动把价签往利润侧抬了一格。",
    });
  } else if (nextTheme !== beforeTheme) {
    const theme = data.shelfThemesByTag.get(nextTheme);
    triggerShopActionFeedback("theme_fit", {
      theme,
      themeName: theme?.note || nextTheme,
      detail: `${theme?.note || nextTheme} 已换到旧铺门面。`,
    });
  }
  render();
}

function availableSeedCrops() {
  return data.crops.filter((crop, index) => {
    if (index < 2) return true;
    if (crop.seed_item_id === "seed_luzhu_qin") return state.canalRepaired || state.canalRestorationState?.waterCropUnlocked;
    if (crop.seed_item_id === BAIZHI_SEED_ID) return baizhiShihuSeedUnlocked();
    if (["seed_guyu_chaya", "seed_yinling_liuyuncao"].includes(crop.seed_item_id)) return state.completed.has("shop") || state.missionDone.size >= 3 || hasItem(crop.seed_item_id, 1);
    if (["seed_penhuo_xiaolajiao", "seed_yuewen_huanggua", "seed_hedeng_lianzi"].includes(crop.seed_item_id)) return chapter3TradeStarted() || state.missionDone.size >= 5 || hasItem(crop.seed_item_id, 1);
    if (["seed_shuangtang_nangua", "seed_shanli_lingshu", "seed_qiusui_zhima", "seed_xuanxiang_dao", "seed_bailu_yiner"].includes(crop.seed_item_id)) return chapter4DroughtActive() || year2Unlocked() || hasItem(crop.seed_item_id, 1);
    if (["seed_xuewen_luoman", "seed_hanyu_baicai", "seed_binglu_bohe", "seed_xuehuo_lingjiang", "seed_xuanshuang_lanmei", "seed_dongcang_yaoshen"].includes(crop.seed_item_id)) return year2Unlocked() || hasItem(crop.seed_item_id, 1);
    if (["seed_qingshui_hulu", "seed_jinsui_yumi"].includes(crop.seed_item_id)) return chapter4DroughtActive() || hasItem(crop.seed_item_id, 1);
    if (crop.seed_item_id === "seed_shuihang_lianshi") return state.completed.has("year2_water_lotus_seed_unlocked") || hasItem(crop.seed_item_id, 1);
    if (crop.seed_item_id === CHAPTER_4_PANTAO_SEED_ID) return state.completed.has("final_pantao_planting_unlocked") || hasItem(CHAPTER_4_PANTAO_SEED_ID, 1);
    return hasItem(crop.seed_item_id, 1);
  });
}

function recipeUnlocked(recipe) {
  if (!recipe) return false;
  if (state.completed.has(`recipe_${recipe.recipe_id}`)) return true;
  if (recipe.unlock_type === "default" || recipe.recipe_id === "recipe_bailuobo_tang" || recipe.recipe_id === "recipe_qingchao_baicai") return true;
  if (recipe.unlock_type === "repair") return state.canalRepaired || state.canalRestorationState?.waterCropUnlocked || hasItem("crop_luzhu_qin", 1);
  if (recipe.unlock_type === "building") return state.builtBuildings.has(recipe.unlock_param);
  if (recipe.unlock_type === "completed") return state.completed.has(recipe.unlock_param);
  if (recipe.unlock_type === "quest") return state.missionDone.has(recipe.unlock_param) || state.activeSideQuests.has(recipe.unlock_param) || state.completed.has(recipe.unlock_param);
  if (recipe.unlock_type === "festival" || recipe.unlock_type === "chapter") return conditionMet(recipe.unlock_param);
  if (recipe.unlock_type === "npc_favor") {
    const favorMatch = String(recipe.unlock_param || "").match(/^npc_(.+)_favor_(\d+)$/);
    if (!favorMatch) return false;
    const npcId = `npc_${favorMatch[1]}`;
    return favorLevel(state.npcFavor[npcId] || 0) >= Number(favorMatch[2] || 0);
  }
  return false;
}

function availableRecipes() {
  return data.recipes.filter(recipeUnlocked);
}

function applyProductionControlsToUi() {
  refs.seedSelect.innerHTML = "";
  const crops = availableSeedCrops();
  if (!crops.some((crop) => crop.seed_item_id === state.selectedSeedId)) state.selectedSeedId = crops[0]?.seed_item_id || "seed_lingqi_bailuobo";
  maybeFocusBaizhiQuestSeed(crops);
  for (const crop of crops) {
    const recommendation = seedSolarRecommendation(crop);
    const seedRoute = seedUseRouteSpec(crop);
    const baizhiMarked = baizhiQuestGuidanceActive() && crop.seed_item_id === BAIZHI_SEED_ID;
    const option = document.createElement("option");
    option.value = crop.seed_item_id;
    option.textContent = `${itemName(crop.seed_item_id)} · ${recommendation.text}${seedRoute ? ` · ${seedRoute.badge}` : ""}${baizhiMarked ? " · 白芷委托" : ""}`;
    refs.seedSelect.append(option);
  }
  refs.seedSelect.value = state.selectedSeedId;

  refs.recipeSelect.innerHTML = "";
  const recipes = availableRecipes();
  if (!recipes.some((recipe) => recipe.recipe_id === state.selectedRecipeId)) state.selectedRecipeId = recipes[0]?.recipe_id || "recipe_bailuobo_tang";
  for (const recipe of recipes) {
    const option = document.createElement("option");
    option.value = recipe.recipe_id;
    option.textContent = recipeName(recipe);
    refs.recipeSelect.append(option);
  }
  refs.recipeSelect.value = state.selectedRecipeId;
}

function updateProductionControlsFromUi() {
  state.selectedSeedId = refs.seedSelect.value;
  state.selectedRecipeId = refs.recipeSelect.value;
  render();
}

function updateSeedRestockUi() {
  if (!refs.buySeedButton || !refs.seedRestockHint) return;
  const seedId = state.selectedSeedId;
  const crop = data.cropsBySeed.get(seedId);
  const recommendation = seedSolarRecommendation(crop);
  const baizhiGuidance = baizhiQuestGuidanceSpec(seedId);
  const price = buyPrice(seedId);
  const stock = state.inventory[seedId] || 0;
  const count = 3;
  const total = price * count;
  refs.buySeedButton.textContent = price > 0 ? `${seedId === BAIZHI_SEED_ID && baizhiGuidance ? "备" : "补"} ${count} 包` : "暂未上架";
  refs.buySeedButton.disabled = !price || state.gold < total;
  refs.seedRestockHint.className = `seed-restock-hint ${recommendation.className}${baizhiGuidance ? " quest" : ""}`;
  refs.seedRestockHint.textContent = baizhiGuidance
    ? price > 0
      ? `${baizhiGuidance.restock} · 库存 ${stock} · 单价 ${price} · 合计 ${total} 灵石`
      : `${baizhiGuidance.restock} · ${recommendation.detail}`
    : price > 0
      ? `库存 ${stock} · 单价 ${price} · 合计 ${total} 灵石 · ${recommendation.detail}`
      : `${itemName(seedId)} 暂无买价配置 · ${recommendation.detail}`;
}

