  const qingboSignatureFeedback = maybeCompleteQingboWaterFreshSignatureLine(openingFeedback, report, restockFulfillment);
  const lingchiMenuFeedback = maybeCompleteLingchiWaterFreshMenuLine(openingFeedback, report);
