function canalExpandedFieldPlaqueSpec(width = refs.world?.width || 960, height = refs.world?.height || 640) {
  const restoration = syncCanalRestorationState();
  if (!state.canalRepaired || !restoration.restored) return null;
  const { tile, gap, originX, originY } = gridMetrics();
  const waterPlots = state.plots
    .filter((plot) => (plot.newlyExpanded || plot.waterSoil) && !plot.debris)
    .sort((a, b) => (b.newlyExpanded ? 1 : 0) - (a.newlyExpanded ? 1 : 0) || a.y - b.y || a.x - b.x);
  if (!waterPlots.length) return null;
  const expandedPlots = waterPlots.filter((plot) => plot.newlyExpanded);
  const focusPlots = (expandedPlots.length ? expandedPlots : waterPlots).slice(0, 12);
  const plotMarks = focusPlots.map((plot, index) => ({
    x: plot.x,
    y: plot.y,
    planted: Boolean(plot.cropId),
    newlyExpanded: Boolean(plot.newlyExpanded),
    screenX: originX + plot.x * (tile + gap),
    screenY: originY + plot.y * (tile + gap),
    centerX: originX + plot.x * (tile + gap) + tile / 2,
    centerY: originY + plot.y * (tile + gap) + tile / 2,
    index,
  }));
  const minX = Math.min(...plotMarks.map((plot) => plot.screenX));
  const maxX = Math.max(...plotMarks.map((plot) => plot.screenX + tile));
  const minY = Math.min(...plotMarks.map((plot) => plot.screenY));
  const maxY = Math.max(...plotMarks.map((plot) => plot.screenY + tile));
  const targetPlot = waterPlots.find((plot) => !plot.cropId)
    || waterPlots.find((plot) => plot.newlyExpanded)
    || waterPlots[0];
  const seedId = restoration.unlockedSeedId || "seed_luzhu_qin";
  const seedName = restoration.unlockedSeedName || itemName(seedId);
  const plantedCount = waterPlots.filter((plot) => plot.cropId).length;
  const openCount = waterPlots.filter((plot) => !plot.cropId).length;
  const dayText = Number(restoration.day || 0) > 0 ? `第 ${restoration.day} 天复流` : "复流后常驻";
  const nextAction = openCount > 0
    ? `把 ${seedName} 接进空水田`
    : "检查露珠芹成熟，再接凉拌灵芹";
  const cardWidth = 282;
  const cardHeight = 108;
  const rect = {
    x: Math.max(18, Math.min(width - cardWidth - 18, minX - 28)),
    y: Math.max(24, Math.min(height - cardHeight - 24, maxY + 20)),
    width: cardWidth,
    height: cardHeight,
  };
  return {
    key: `${state.day}:${restoration.day}:${waterPlots.length}:${plantedCount}:${openCount}:expanded_field_plaque`,
    title: "复流水田铭牌 · 可点",
    headline: "这片地已永久接入灵渠",
    detail: `${waterPlots.length} 格水润灵田常驻 · 已种 ${plantedCount} 格 · 空水田 ${openCount} 格`,
    memoryText: `${dayText} · 地图边界向右扩出 ${Number(restoration.expandedPlots || restoration.last?.expandedPlots || waterPlots.length)} 格`,
    mapEvidenceText: `新水田已写入地图：${focusPlots.length} 格高亮为永久水田`,
    tomorrowFirstStep: openCount > 0
      ? `明天第一步：播下 ${seedName}`
      : "明天第一步：检查水线成熟并接工坊",
    acceptanceLine: "vsa_007 录屏证据：复流水田铭牌证明地块扩张是永久写入地图。",
    nextAction,
    seedId,
    seedName,
    targetPlot: targetPlot ? { x: targetPlot.x, y: targetPlot.y } : null,
    plotMarks,
    bounds: { minX, maxX, minY, maxY },
    rect,
    safeNote: "只定位水田与灵田卡，不会自动播种或建造。",
  };
}

function canalExpandedFieldPlaqueAtCanvasPoint(px, py) {
  const spec = canalExpandedFieldPlaqueSpec(refs.world?.width || 960, refs.world?.height || 640);
  if (!spec?.rect) return null;
  const { rect, bounds } = spec;
  const onCard = px >= rect.x && px <= rect.x + rect.width && py >= rect.y && py <= rect.y + rect.height;
  const onFieldGroup = px >= bounds.minX - 10 && px <= bounds.maxX + 10 && py >= bounds.minY - 10 && py <= bounds.maxY + 10;
  return onCard || onFieldGroup ? spec : null;
}

