function canalDaySummaryPlanSpec() {
  const restoration = syncCanalRestorationState();
  if (!restoration.waterCropUnlocked && !state.canalRepaired) return null;
  syncPondState();
  const seedId = restoration.unlockedSeedId || "seed_luzhu_qin";
  const seedName = itemName(seedId);
  const waterCropPlanted = state.completed.has("first_water_crop_plant")
    || state.plots.some((plot) => plot.cropId === "crop_luzhu_qin")
    || Number(state.inventory.crop_luzhu_qin || 0) > 0;
  const waterCropCount = Number(state.inventory.crop_luzhu_qin || 0);
  const dishCount = Number(state.inventory.item_food_liangban_lingqin || 0);
  const nightCare = Math.max(0, Number(state.pondState?.nightWaterCropCareDays || 0));
  const yuelianEvent = data.rareSpiritEvents.find((entry) => entry.entry_id === "rsea_005");
  const yuelianClue = rareSpiritClueForEvent(yuelianEvent);
  const yuelianDone = yuelianEvent ? rareSpiritEventDone(yuelianEvent) || rareSpiritOwned(yuelianEvent) : false;
  const canCook = waterCropCount >= 2 || dishCount > 0;
  const steps = [
    {
      key: "plant",
      label: waterCropPlanted ? "露珠芹线已接上" : "明早先种露珠芹",
      detail: waterCropPlanted
        ? "水润灵田已经不只是扩地，而是新的料理原料线。"
        : `${seedName} 已在种子栏等着，先把第一格水田种起来。`,
      stateClass: waterCropPlanted ? "done" : "ready",
      buttonLabel: waterCropPlanted ? "回看水田" : "定位水田",
    },
    {
      key: "clue",
      label: yuelianDone ? "月莲线已结缘" : yuelianClue ? `月莲水痕 ${Math.min(3, nightCare)}/3` : "月莲水痕待发现",
      detail: yuelianDone
        ? "月莲已经从水痕变成伙伴，后续看静养和羁绊线。"
        : yuelianClue
          ? "夜里照看水田，水面会把第二精怪的痕迹留下来。"
          : "修渠后的夜水还没安静下来，先把水田种起来。",
      stateClass: yuelianDone ? "done" : yuelianClue ? nightCare >= 3 ? "ready" : "active" : "pending",
      buttonLabel: yuelianDone ? "看目标册" : "看月莲水痕",
    },
    {
      key: "recipe",
      label: dishCount > 0 ? "凉拌灵芹已出锅" : canCook ? "可做凉拌灵芹" : "备第一盘凉拌灵芹",
      detail: dishCount > 0
        ? "清润水鲜已经能进订单或旧铺头排。"
        : canCook
          ? "露珠芹已够，去工坊把修渠后的第一盘口味做出来。"
          : "收两份露珠芹后，工坊会接上青禾的清口尝鲜订单。",
      stateClass: dishCount > 0 ? "done" : canCook ? "ready" : "pending",
      buttonLabel: dishCount > 0 ? "看订单/旧铺" : "看工坊",
    },
  ];
  return {
    title: "新渠明日计划",
    headline: yuelianClue && !yuelianDone ? "水田、清口料理和第二精怪线索已经接成一条线。" : "灵渠复流后，先把新水田变成稳定生产线。",
    advice: dishCount > 0
      ? "明天把凉拌灵芹交给青禾或摆上旧铺，观察哪类顾客认这口清润。"
      : waterCropPlanted
        ? "明天先顾水、等露珠芹成熟，再把它做成第一盘凉拌灵芹。"
        : "明天第一件事：点水田、种露珠芹，让灵渠修复变成新的菜品和伙伴期待。",
    seedId,
    seedName,
    waterCropPlanted,
    waterCropCount,
    dishCount,
    nightCare,
    yuelianEventId: yuelianEvent?.entry_id || "",
    yuelianClued: Boolean(yuelianClue),
    yuelianDone,
    steps,
  };
}

function focusCanalDaySummaryPlan(action = "plant") {
  const plan = canalDaySummaryPlanSpec();
  if (!plan) return addLog("新渠明日计划", "灵渠水线还没有接上，先完成第一段灵渠修复。");
  if (action === "clue") {
    if (focusYuelianCanalClueFromCanvas()) return true;
    queueStoryCompassFocusTarget({
      selector: plan.yuelianEventId ? `[data-rare-event-id="${selectorDataValue(plan.yuelianEventId)}"]` : "#goalBookPanel",
      fallbackSelector: "#goalBookPanel",
      label: "新渠明日计划：月莲水痕",
      log: plan.yuelianClued
        ? "目标册已定位到月莲水痕。继续夜间照料水田，第二精怪线会从线索慢慢长成初见。"
        : "月莲水痕还没稳定，先把水田种起来，夜里水面才会留下痕迹。",
      panelGroup: "core",
      missingTitle: "月莲水痕定位",
      missingLog: "目标册暂时没有找到月莲线索，先查看稀有精怪追踪区。",
    });
    return true;
  }
  if (action === "recipe") {
    state.selectedRecipeId = "recipe_liangban_lingqin";
    queueStoryCompassFocusTarget({
      selector: "#recipeSelect",
      fallbackSelector: "#craftButton",
      label: "新渠明日计划：凉拌灵芹",
      log: plan.dishCount > 0
        ? "凉拌灵芹已经出锅。接下来可以看订单板或旧铺头排，把水线料理变成收入和口碑。"
        : "已切到凉拌灵芹配方。备齐露珠芹和净水后，把修渠后的第一盘口味做出来。",
      panelGroup: "core",
      missingTitle: "凉拌灵芹定位",
      missingLog: "工坊配方入口暂时没有找到，先确认核心试玩分组是否可见。",
    });
    return true;
  }
  return focusCanalTomorrowGoalFromCanvas(canalTomorrowGoalSpec());
}

