function luzhuQinHarvestRouteWorldSpec() {
  if (!state.completed.has("first_luzhu_qin_harvest")) return null;
  if (state.completed.has("first_lingqin_dish_crafted")) return null;
  const cropId = "crop_luzhu_qin";
  const cropCount = Number(state.inventory[cropId] || 0);
  if (cropCount <= 0) return null;
  const recipeId = "recipe_liangban_lingqin";
  const outputItemId = "item_food_liangban_lingqin";
  const orderId = "order_demo_0002";
  const recipe = data.recipes.find((entry) => entry.recipe_id === recipeId);
  const visibleOrder = visibleOrders().find((entry) => entry.order_id === orderId) || null;
  const knownOrder = visibleOrder || allOrderConfigs().find((entry) => entry.order_id === orderId) || null;
  const routeTags = shopTagsForItem(outputItemId, ecologyCourtyardSummary());
  const shopTag = prioritizeShopTag(routeTags, new Map(routeTags.map((tag) => [tag, 1])), "fresh");
  const shopTagText = shopTagLabel(shopTag);
  const waterPlot = state.plots.find((plot) => plot.cropId === cropId)
    || state.plots.find((plot) => (plot.waterSoil || plot.newlyExpanded) && !plot.debris)
    || selectedPlot();
  const { tile, gap, originX, originY } = gridMetrics();
  const plotX = waterPlot ? originX + waterPlot.x * (tile + gap) : originX + 6 * (tile + gap);
  const plotY = waterPlot ? originY + waterPlot.y * (tile + gap) : originY + 3 * (tile + gap);
  const cardWidth = 334;
  const cardHeight = 126;
  const rect = {
    x: Math.max(18, Math.min(960 - cardWidth - 18, plotX - 48)),
    y: Math.max(28, Math.min(640 - cardHeight - 24, plotY + tile + 18)),
    width: cardWidth,
    height: cardHeight,
  };
  const stepWidth = 98;
  const stepY = rect.y + 74;
  const steps = [
    {
      key: "stock",
      label: "水田初收",
      value: `入仓 x${cropCount}`,
      detail: "露珠芹已经不是田里的提示，而是背包里的新原料。",
      tone: "stock",
      rect: { x: rect.x + 18, y: stepY, width: stepWidth, height: 28 },
    },
    {
      key: "recipe",
      label: "工坊凉拌",
      value: recipe ? recipeName(recipe).slice(0, 6) : "凉拌灵芹",
      detail: "切到凉拌灵芹配方，确认露珠芹和净水是否齐。",
      tone: "recipe",
      rect: { x: rect.x + 118, y: stepY, width: stepWidth, height: 28 },
    },
    {
      key: "market",
      label: visibleOrder ? "青禾清口单" : "旧铺清润货",
      value: visibleOrder ? "订单/旧铺" : shopTagText,
      detail: visibleOrder
        ? `${orderTitle(visibleOrder)} 会接住第一盘凉拌灵芹。`
        : `先按 ${shopTagText} 留作旧铺货，等清口订单亮起。`,
      tone: "market",
      rect: { x: rect.x + 218, y: stepY, width: stepWidth, height: 28 },
    },
  ];
  return {
    key: `${state.day}:${cropCount}:${visibleOrder ? visibleOrder.order_id : "shop"}:luzhu_qin_harvest_route`,
    title: "露珠芹入仓去向签 · 可点",
    headline: "新渠第一把菜已经有去处",
    detail: `仓中 ${itemName(cropId)} x${cropCount}，下一步接 ${recipe ? recipeName(recipe) : "凉拌灵芹"}。`,
    routeText: visibleOrder ? "水田初收 -> 工坊凉拌灵芹 -> 青禾清口单" : `水田初收 -> 工坊凉拌灵芹 -> 旧铺${shopTagText}`,
    safeNote: "只定位配方、订单或旧铺，不会自动加工、交单、开铺或消耗露珠芹",
    cropId,
    cropName: itemName(cropId),
    cropCount,
    recipeId,
    recipeName: recipe ? recipeName(recipe) : "凉拌灵芹",
    outputItemId,
    orderId,
    orderVisible: Boolean(visibleOrder),
    orderTitle: knownOrder ? orderTitle(knownOrder) : "青禾清口尝鲜订单",
    shopTag,
    shopTagText,
    targetPlot: waterPlot ? { x: waterPlot.x, y: waterPlot.y } : null,
    anchor: { x: plotX + tile * 0.5, y: plotY + tile * 0.56 },
    rect,
    steps,
  };
}

function luzhuQinHarvestRouteWorldAtCanvasPoint(px, py) {
  const spec = luzhuQinHarvestRouteWorldSpec();
  if (!spec?.rect) return null;
  for (const step of spec.steps || []) {
    const rect = step.rect;
    if (rect && px >= rect.x && px <= rect.x + rect.width && py >= rect.y && py <= rect.y + rect.height) {
      return { ...spec, action: step.key, actionStep: step };
    }
  }
  const { rect, anchor } = spec;
  const onCard = px >= rect.x && px <= rect.x + rect.width && py >= rect.y && py <= rect.y + rect.height;
  const onAnchor = px >= anchor.x - 28 && px <= anchor.x + 28 && py >= anchor.y - 24 && py <= anchor.y + 24;
  return onCard || onAnchor ? { ...spec, action: "recipe", actionStep: spec.steps?.[1] || null } : null;
}

function focusLuzhuQinHarvestRouteWorldFromCanvas(spec = luzhuQinHarvestRouteWorldSpec()) {
  if (!spec) return false;
  const action = spec.action || "recipe";
  luzhuQinHarvestRouteWorldFocus = { key: spec.key, day: state.day, action };
  const plot = spec.targetPlot
    ? state.plots.find((entry) => entry.x === spec.targetPlot.x && entry.y === spec.targetPlot.y)
    : null;
  if (plot) {
    state.selected = { x: plot.x, y: plot.y };
    pulseAtPlot(plot, "harvest", { harvestText: "露珠芹入仓" });
  }
  if (action === "stock") {
    queueStoryCompassFocusTarget({
      selector: "#inventoryList",
      fallbackSelector: "#selectedPlotCard",
      label: "露珠芹入仓去向签",
      log: `${spec.cropName} 已入仓 x${spec.cropCount}。${spec.actionStep?.detail || "先确认背包和水田，再接工坊配方。"} ${spec.safeNote}。`,
      panelGroup: "core",
      missingTitle: "露珠芹入仓定位",
      missingLog: "背包列表暂时没有找到；已保留水田选中，只用于确认库存去向。",
    });
    return true;
  }
  if (action === "market") {
    if (spec.orderVisible) return focusPlotRouteOrder(spec.orderId);
    return focusPlotRouteShop(spec.shopTag, spec.outputItemId);
  }
  return focusPlotRouteRecipe(spec.recipeId);
}

