function lingqinDishRouteWorldSpec() {
  if (!state.completed.has("first_lingqin_dish_crafted")) return null;
  if (state.completed.has("first_water_crop_order_delivery") || state.completedOrders.has("order_demo_0002")) return null;
  const itemId = "item_food_liangban_lingqin";
  const itemCount = Number(state.inventory[itemId] || 0);
  if (itemCount <= 0) return null;
  const orderId = "order_demo_0002";
  const visibleOrder = visibleOrders().find((entry) => entry.order_id === orderId) || null;
  const knownOrder = visibleOrder || allOrderConfigs().find((entry) => entry.order_id === orderId) || null;
  const orderReady = Boolean(visibleOrder && canDeliverOrder(visibleOrder));
  const missingText = visibleOrder ? routeMissingText(visibleOrder) : "";
  const routeTags = shopTagsForItem(itemId, ecologyCourtyardSummary());
  const shopTag = prioritizeShopTag(routeTags, new Map(routeTags.map((tag) => [tag, 1])), "fresh");
  const shopTagText = shopTagLabel(shopTag);
  const rect = { x: 292, y: 238, width: 346, height: 132 };
  const stepY = rect.y + 80;
  const stepWidth = 100;
  const steps = [
    {
      key: "stock",
      label: "成品入仓",
      value: `凉拌 x${itemCount}`,
      detail: `${itemName(itemId)} 已在仓中，先确认这盘水线成品还没被用掉。`,
      tone: "stock",
      rect: { x: rect.x + 18, y: stepY, width: stepWidth, height: 30 },
    },
    {
      key: "order",
      label: orderReady ? "青禾可交" : "青禾清口单",
      value: visibleOrder ? (orderReady ? "库存已齐" : `缺 ${missingText || "余料"}`) : "待上板",
      detail: visibleOrder
        ? orderReady
          ? `${orderTitle(visibleOrder)} 已备齐，只等玩家手动交付。`
          : `${orderTitle(visibleOrder)} 已上板，还差 ${missingText || "几件货"}。`
        : `${knownOrder ? orderTitle(knownOrder) : "青禾清口尝鲜订单"} 暂时未上板，先留成品等剧情或订单刷新。`,
      tone: "order",
      rect: { x: rect.x + 122, y: stepY, width: stepWidth, height: 30 },
    },
    {
      key: "shop",
      label: "旧铺清润货",
      value: shopTagText,
      detail: `如果不急着交单，也能按 ${shopTagText} 留给旧铺头排试卖。`,
      tone: "shop",
      rect: { x: rect.x + 226, y: stepY, width: stepWidth, height: 30 },
    },
  ];
  return {
    key: `${state.day}:${itemCount}:${visibleOrder ? visibleOrder.order_id : "no_order"}:${orderReady ? 1 : 0}:lingqin_dish_route`,
    id: "lingqin_dish_route_note",
    title: orderReady ? "凉拌灵芹可交签 · 可点" : "凉拌灵芹上案去向签 · 可点",
    headline: orderReady ? "青禾这一单已经能手动交付" : "第一盘清润菜已经等着变现",
    detail: visibleOrder
      ? `${itemName(itemId)} x${itemCount} · ${orderReady ? "订单材料已齐" : `订单还差 ${missingText || "余料"}`}。`
      : `${itemName(itemId)} x${itemCount} · 先看订单板或旧铺清润货签。`,
    routeText: orderReady
      ? "成品入仓 -> 青禾清口单 -> 手动交付入账"
      : "成品入仓 -> 青禾清口单/旧铺清润货",
    safeNote: "只定位订单板或旧铺，不会自动交单、开铺或消耗凉拌灵芹",
    itemId,
    itemName: itemName(itemId),
    itemCount,
    orderId,
    orderVisible: Boolean(visibleOrder),
    orderReady,
    orderTitle: knownOrder ? orderTitle(knownOrder) : "青禾清口尝鲜订单",
    missingText,
    shopTag,
    shopTagText,
    anchor: { x: 514, y: 420 },
    rect,
    steps,
  };
}

function lingqinDishRouteWorldAtCanvasPoint(px, py) {
  const spec = lingqinDishRouteWorldSpec();
  if (!spec?.rect) return null;
  for (const step of spec.steps || []) {
    const rect = step.rect;
    if (rect && px >= rect.x && px <= rect.x + rect.width && py >= rect.y && py <= rect.y + rect.height) {
      return { ...spec, action: step.key, actionStep: step };
    }
  }
  const { rect } = spec;
  return px >= rect.x && px <= rect.x + rect.width && py >= rect.y && py <= rect.y + rect.height
    ? { ...spec, action: spec.orderVisible ? "order" : "shop", actionStep: spec.orderVisible ? spec.steps?.[1] : spec.steps?.[2] }
    : null;
}

function focusLingqinDishRouteWorldFromCanvas(spec = lingqinDishRouteWorldSpec()) {
  if (!spec) return false;
  const action = spec.action || (spec.orderVisible ? "order" : "shop");
  lingqinDishRouteWorldFocus = { key: spec.key, day: state.day, action };
  if (action === "shop") return focusPlotRouteShop(spec.shopTag, spec.itemId);
  if (action === "stock") {
    queueStoryCompassFocusTarget({
      selector: "#inventoryList",
      fallbackSelector: "#recipeSelect",
      label: "凉拌灵芹上案去向签",
      log: `${spec.itemName} 已入仓 x${spec.itemCount}。${spec.actionStep?.detail || "先确认成品库存，再决定交青禾清口单或留作旧铺清润货。"} ${spec.safeNote}。`,
      panelGroup: "core",
      missingTitle: "凉拌灵芹库存定位",
      missingLog: "背包列表暂时没有找到；先查看工坊/订单区确认成品去向。",
    });
    return true;
  }
  if (spec.orderVisible) return focusPlotRouteOrder(spec.orderId);
  queueStoryCompassFocusTarget({
    selector: "#orderPanel",
    fallbackSelector: "#shopReport",
    label: "凉拌灵芹上案去向签",
    log: `${spec.orderTitle} 暂时没有在订单板上。先留住 ${spec.itemName}，或把它按 ${spec.shopTagText} 放进旧铺路线预览。${spec.safeNote}。`,
    panelGroup: "core",
    missingTitle: "青禾清口单定位",
    missingLog: "订单面板暂时没有找到；先查看旧铺反馈或工坊库存，等待青禾清口单上板。",
  });
  return true;
}

function waterCropOrderFeedbackSpec(order = null, deliveryFeedback = null) {
  if (!order || order.order_id !== "order_demo_0002" || !deliveryFeedback) return null;
  const need = orderNeeds(order).find((entry) => entry.itemId === "item_food_liangban_lingqin");
  const favorGain = Number(deliveryFeedback.favorGain || order.reward_favor_value || 0);
  return {
    title: "青禾清口单交付",
    label: "水系链路闭环 · 新渠入账",
    headline: "新渠第一盘口味卖成了",
    detail: `${orderTitle(order)} 已交付，${itemName(need?.itemId || "item_food_liangban_lingqin")} 从水田、灶台一路走到账本。`,
    rewardText: `${Number(deliveryFeedback.rewardGold || 0)} 灵石入账 · 声望 +${Number(deliveryFeedback.rewardFame || 0)} · 青禾好感 +${favorGain}`,
    routeText: "修渠 -> 露珠芹 -> 凉拌灵芹 -> 青禾清口单",
    nextAdvice: "水系料理已经证明能赚钱，下一步可以扩灵池、稳水位，接更深的青禾水脉线。",
    orderId: order.order_id,
    orderTitle: orderTitle(order),
    npcId: "npc_qinghe",
    npcLabel: npcName("npc_qinghe"),
    itemId: need?.itemId || "item_food_liangban_lingqin",
    itemName: itemName(need?.itemId || "item_food_liangban_lingqin"),
    itemCount: Number(need?.count || 1),
    rewardGold: Number(deliveryFeedback.rewardGold || 0),
    rewardFame: Number(deliveryFeedback.rewardFame || 0),
    favorGain,
    createdAt: performance.now(),
  };
}

function triggerWaterCropOrderFeedback(order = null, deliveryFeedback = null) {
  const feedback = waterCropOrderFeedbackSpec(order, deliveryFeedback);
  if (!feedback) return null;
  state.waterCropOrderFeedback = feedback;
  complete("first_water_crop_order_delivery");
  return feedback;
}

function qingheWaterTasteNoteSpec() {
  const quest = data.sideQuests.find((entry) => entry.quest_id === "quest_side_0205_qinghe_pond");
  const building = data.buildingsById.get("build_fishpond_lv1");
  if (!quest || !building) return null;
  const pondBuilt = state.builtBuildings.has(building.building_id);
  if (pondBuilt || state.claimedQuestRewards.has(quest.quest_id)) return null;
  const waterTasteDone = state.completedOrders.has("order_demo_0002")
    || state.completed.has("first_water_crop_order_delivery")
    || state.completed.has("qinghe_pond_entry_feedback")
    || state.activeSideQuests.has(quest.quest_id);
  if (!waterTasteDone) return null;
  const steps = data.sideQuestStepsByQuest.get(quest.quest_id) || [];
  const buildStep = steps.find((step) => step.objective_type === "build") || steps[0] || null;
  const fishStep = steps.find((step) => step.target_id === "item_fish_spiritling") || steps[1] || null;
  const accepted = state.activeSideQuests.has(quest.quest_id);
  const visible = sideQuestVisible(quest);
  const ready = accepted || visible || favorLevel(Number(state.npcFavor.npc_qinghe || 0)) >= 1;
  const costText = [
    Number(building.cost_gold || 0) > 0 ? `${Number(building.cost_gold || 0)} 灵石` : "",
    Number(building.cost_wood || 0) > 0 ? `木材 ${Number(building.cost_wood || 0)}` : "",
    Number(building.cost_stone || 0) > 0 ? `石材 ${Number(building.cost_stone || 0)}` : "",
  ].filter(Boolean).join(" / ") || "少量材料";
  return {
    id: "qinghe_water_taste_note",
    title: "青禾试水笺 · 可点",
    headline: accepted ? "灵池浅塘可动工" : ready ? "旧池塘线已露头" : "青禾还在认这口水",
    detail: accepted
      ? `${questTitle(quest)} 已承接，先修 ${buildingName(building)}。`
      : ready
        ? "清口单之后，青禾愿意带你去认旧池水口。"
        : "继续找青禾说话，把水线口味落成一心托付。",
    routeText: "青禾一心 -> 建灵池浅塘 -> 第一网灵鱼 -> 清波鱼脍",
    questId: quest.quest_id,
    questTitle: questTitle(quest),
    npcId: "npc_qinghe",
    npcLabel: npcName("npc_qinghe"),
    buildingId: building.building_id,
    buildingName: buildingName(building),
    buildCostText: costText,
    accepted,
    ready,
    firstStepText: buildStep ? stepLabel(buildStep) : `建造 ${buildingName(building)}`,
    secondStepText: fishStep ? stepLabel(fishStep) : `捞起第一尾${itemName("item_fish_spiritling")}`,
    rect: { x: 568, y: 386, width: 254, height: 94 },
  };
}

function pondFirstCatchNoteSpec() {
  syncPondState();
  if (!state.builtBuildings.has("build_fishpond_lv1") || state.pondState.firstCatchDone) return null;
  const ready = pondCatchReady();
  const fishName = itemName("item_fish_spiritling");
  const hasNet = hasItem("item_tool_fishing_net", 1);
  return {
    id: "pond_first_catch_note",
    title: "灵池第一网 · 可点",
    headline: ready ? "池口有鱼影" : "池水还在聚鱼",
    detail: ready
      ? `${hasNet ? "引水鱼网已备，" : ""}先试一网认回${fishName}。`
      : "今天水口还静，等明天再来试网。",
    routeText: "试第一网 -> 清波鱼脍配方 -> 水鲜上架",
    fishName,
    ready,
    hasNet,
    waterText: pondWaterLevelText(state.pondState.waterLevel),
    rect: { x: 704, y: 314, width: 232, height: 86 },
  };
}

function pondOvernightWorldSpec() {
  const pondState = syncPondState();
  if (!state.builtBuildings.has("build_fishpond_lv1") || pondState.firstCatchDone) return null;
  const ready = pondCatchReady();
  const builtDay = Number(pondState.builtDay || state.day);
  const daysSinceBuilt = Math.max(0, Number(state.day || 1) - builtDay);
  const triedToday = Number(pondState.lastCatchDay || 0) === Number(state.day || 1);
  const fishName = itemName("item_fish_spiritling");
  const title = ready ? "灵池第一网晨签 · 可点" : "灵池养水过夜签 · 可点";
  const headline = ready ? "水面已经有第一尾鱼影" : "池底正在养住第一口活水";
  const detail = ready
    ? `灵池浅塘已养水 ${daysSinceBuilt} 夜，可以手动试第一网。`
    : triedToday
      ? "今天已经试过水口，等明天回纹再来。"
      : "先让池水静一夜，明天回来认第一尾灵鱼。";
  const steps = [
    { key: "built", label: "灵池建成", value: builtDay === state.day ? "今日" : `${daysSinceBuilt}夜前`, tone: "built" },
    { key: "water", label: ready ? "鱼影浮动" : "养水过夜", value: ready ? "可试网" : "聚鱼中", tone: "water" },
    { key: "catch", label: "第一网", value: fishName.slice(0, 4), tone: "catch" },
  ];
  return {
    key: `${state.day}:${builtDay}:${ready ? 1 : 0}:${triedToday ? 1 : 0}:pond_overnight`,
    id: "pond_overnight_note",
    title,
    headline,
    detail,
    routeText: "灵池建成 -> 养水过夜 -> 第一网灵鱼 -> 清波鱼脍",
    safeNote: "只定位灵池试网按钮，不会自动捞鱼、发奖励或推进支线",
    ready,
    triedToday,
    builtDay,
    daysSinceBuilt,
    fishName,
    waterText: pondWaterLevelText(pondState.waterLevel),
    anchor: { x: 874, y: 438 },
    rect: { x: 642, y: 456, width: 286, height: 104 },
    steps,
  };
}

function pondOvernightWorldAtCanvasPoint(px, py) {
  const spec = pondOvernightWorldSpec();
  if (!spec?.rect) return null;
  const { rect, anchor } = spec;
  const onCard = px >= rect.x && px <= rect.x + rect.width && py >= rect.y && py <= rect.y + rect.height;
  const onAnchor = px >= anchor.x - 56 && px <= anchor.x + 56 && py >= anchor.y - 28 && py <= anchor.y + 28;
  return onCard || onAnchor ? spec : null;
}

function focusPondOvernightWorldFromCanvas(spec = pondOvernightWorldSpec()) {
  if (!spec) return false;
  pondOvernightWorldFocus = { key: spec.key, day: state.day };
  queueStoryCompassFocusTarget({
    selector: '[data-pond-action="catch"]',
    fallbackSelector: ".build-panel",
    label: `点选灵池：${spec.title.replace(" · 可点", "")}`,
    log: spec.ready
      ? `${spec.headline}。已定位灵池试网按钮，由你手动点击才会捞起 ${spec.fishName}。${spec.safeNote}。`
      : `${spec.headline}。${spec.detail} 当前水位：${spec.waterText}；下一步是等水口回纹后手动试第一网。${spec.safeNote}。`,
    panelGroup: "systems",
    missingTitle: "灵池养水定位",
    missingLog: "灵池试网按钮暂时没有找到，先确认系统深挖分组和建造面板是否可见。",
  });
  return true;
}

function qingboDishRouteNoteSpec() {
  syncPondState();
  const dishId = "item_food_qingbo_yukuai";
  const recipeId = "recipe_water_crop_intro";
  const recipe = data.recipes.find((entry) => entry.recipe_id === recipeId) || null;
  const fishCaught = state.pondState.firstCatchDone || state.completed.has("pond_first_catch") || hasItem("item_fish_spiritling", 1);
  const dishCount = Number(state.inventory[dishId] || 0);
  const crafted = dishCount > 0 || state.completed.has("first_qingbo_yukuai_crafted");
  if (!fishCaught && !crafted) return null;
  if (state.completed.has("first_qingbo_yukuai_sold")) return null;
  const recipeReady = Boolean(recipe && recipeUnlocked(recipe));
  const ingredients = recipe
    ? recipeInputs(recipe).map(({ itemId, count }) => ({
      itemId,
      itemName: itemName(itemId),
      count,
      have: Number(state.inventory[itemId] || 0),
    }))
    : [];
  const missing = ingredients.filter((entry) => entry.have < entry.count);
  const readyToCraft = recipeReady && missing.length === 0;
  const phase = crafted ? "shop" : recipeReady ? "craft" : "reward";
  const missingText = missing
    .slice(0, 2)
    .map((entry) => `${entry.itemName} ${entry.have}/${entry.count}`)
    .join(" / ");
  return {
    id: "qingbo_dish_route_note",
    type: phase,
    title: phase === "shop" ? "清波鱼脍上架笺 · 可点" : "清波鱼脍上案笺 · 可点",
    headline: phase === "shop" ? "旧铺该试水鲜了" : readyToCraft ? "灵鱼能上案了" : recipeReady ? "还差一味水鲜料" : "先领清波配方",
    detail: phase === "shop"
      ? `${itemName(dishId)} x${dishCount} 已入仓，开铺看第一位水鲜顾客。`
      : readyToCraft
        ? `${recipe ? recipeName(recipe) : "清波鱼脍"} 原料已齐，去工坊做第一盘。`
        : recipeReady
          ? `工坊还差 ${missingText || "几味原料"}。`
          : "第一网灵鱼已回池，先回青禾支线领配方。",
    routeText: phase === "shop" ? "清波鱼脍 -> 旧铺首卖 -> 水鲜招牌" : "灵鱼 -> 清波鱼脍 -> 旧铺水鲜",
    recipeId,
    recipeName: recipe ? recipeName(recipe) : "清波鱼脍",
    dishId,
    dishName: itemName(dishId),
    dishCount,
    recipeReady,
    readyToCraft,
    missingText,
    price: Number(data.itemsById.get(dishId)?.sell_price_base || 128),
    rect: { x: 338, y: 446, width: 294, height: 94 },
  };
}

function qingboIngredientTriadWorldSpec() {
  syncPondState();
  const recipeId = "recipe_water_crop_intro";
  const dishId = "item_food_qingbo_yukuai";
  const recipe = data.recipes.find((entry) => entry.recipe_id === recipeId) || null;
  const fishCaught = state.pondState.firstCatchDone || state.completed.has("pond_first_catch") || hasItem("item_fish_spiritling", 1);
  if (!fishCaught || state.completed.has("first_qingbo_yukuai_crafted") || Number(state.inventory[dishId] || 0) > 0) return null;
  const recipeReady = Boolean(recipe && recipeUnlocked(recipe));
  const fallbackInputs = [
    { itemId: "item_fish_spiritling", count: 1 },
    { itemId: "crop_luzhu_qin", count: 1 },
    { itemId: "item_material_clean_water", count: 1 },
  ];
  const inputs = (recipe ? recipeInputs(recipe) : fallbackInputs)
    .filter((entry) => entry.itemId)
    .slice(0, 3)
    .map((entry) => ({
      ...entry,
      itemName: itemName(entry.itemId),
      have: Number(state.inventory[entry.itemId] || 0),
      ready: Number(state.inventory[entry.itemId] || 0) >= Number(entry.count || 1),
    }));
  const missing = inputs.filter((entry) => !entry.ready);
  const readyToCraft = recipeReady && missing.length === 0;
  const primaryMissing = missing[0] || null;
  const rect = { x: 374, y: 352, width: 322, height: 118 };
  return {
    key: `${state.day}:${recipeReady ? 1 : 0}:${inputs.map((entry) => `${entry.itemId}_${entry.have}_${entry.count}`).join(":")}:qingbo_triad`,
    id: "qingbo_ingredient_triad_note",
    title: readyToCraft ? "清波鱼脍三味齐签 · 可点" : "清波鱼脍备料三味签 · 可点",
    headline: readyToCraft ? "灵鱼、露珠芹和净水都到案了" : recipeReady ? "清波鱼脍还差一味料" : "先把清波鱼脍配方收束出来",
    detail: readyToCraft
      ? `${recipe ? recipeName(recipe) : "清波鱼脍"} 原料已齐，可以手动去工坊开做。`
      : recipeReady
        ? `当前缺 ${primaryMissing ? `${primaryMissing.itemName} ${primaryMissing.have}/${primaryMissing.count}` : "几味材料"}。`
        : "第一尾灵鱼已入仓，先回青禾支线收束配方奖励。",
    routeText: "灵鱼 -> 露珠芹 -> 净水 -> 清波鱼脍",
    safeNote: "只定位配方或缺料来源，不会自动加工、补料或消耗灵鱼",
    recipeId,
    recipeName: recipe ? recipeName(recipe) : "清波鱼脍",
    dishId,
    dishName: itemName(dishId),
    recipeReady,
    readyToCraft,
    missingText: missing.map((entry) => `${entry.itemName} ${entry.have}/${entry.count}`).join(" / "),
    primaryMissingId: primaryMissing?.itemId || "",
    inputs,
    rect,
    anchor: { x: 706, y: 420 },
  };
}

function qingboIngredientTriadWorldAtCanvasPoint(px, py) {
  const spec = qingboIngredientTriadWorldSpec();
  if (!spec?.rect) return null;
  const { rect, anchor } = spec;
  const onCard = px >= rect.x && px <= rect.x + rect.width && py >= rect.y && py <= rect.y + rect.height;
  const onAnchor = px >= anchor.x - 40 && px <= anchor.x + 40 && py >= anchor.y - 26 && py <= anchor.y + 26;
  return onCard || onAnchor ? spec : null;
}

function focusQingboIngredientTriadWorldFromCanvas(spec = qingboIngredientTriadWorldSpec()) {
  if (!spec) return false;
  qingboIngredientTriadWorldFocus = { key: spec.key, day: state.day };
  if (spec.readyToCraft) {
    return focusPlotRouteRecipe(spec.recipeId);
  }
  if (!spec.recipeReady) {
    queueStoryCompassFocusTarget({
      selector: `[data-side-quest-id="${selectorDataValue("quest_side_0205_qinghe_pond")}"]`,
      fallbackSelector: ".mission-panel",
      label: "清波鱼脍备料三味签",
      log: `第一尾灵鱼已经回池，但 ${spec.recipeName} 配方还没有收束。先定位青禾灵池支线，手动领取或完成配方奖励。${spec.safeNote}。`,
      panelGroup: "core",
      missingTitle: "清波鱼脍配方定位",
      missingLog: "青禾灵池支线卡暂时没有找到，先从任务面板或关系面板确认配方奖励。",
    });
    return true;
  }
  if (spec.primaryMissingId === "crop_luzhu_qin") {
    const crop = data.cropsById.get("crop_luzhu_qin");
    if (crop?.seed_item_id) return focusPlotRouteSeed(crop.seed_item_id);
  }
  if (spec.primaryMissingId === "item_fish_spiritling" || spec.primaryMissingId === "item_material_clean_water") {
    queueStoryCompassFocusTarget({
      selector: spec.primaryMissingId === "item_fish_spiritling" ? '[data-pond-action="catch"]' : ".build-panel",
      fallbackSelector: ".build-panel",
      label: "清波鱼脍备料三味签",
      log: `清波鱼脍还差 ${spec.missingText || "一味材料"}。${spec.primaryMissingId === "item_fish_spiritling" ? "已定位灵池试网入口，手动试网才会获得灵鱼。" : "已定位系统/建造面板，可查看净水、灵井、精怪工坊整理等来源。"} ${spec.safeNote}。`,
      panelGroup: "systems",
      missingTitle: "清波鱼脍缺料定位",
      missingLog: "对应的灵池或建造入口暂时没有找到，先确认系统深挖分组是否可见。",
    });
    return true;
  }
  return focusPlotRouteRecipe(spec.recipeId);
}

function qingboFirstSaleRestockSeedWorldSpec() {
  if (!state.completed.has("first_qingbo_yukuai_sold")) return null;
  if (state.completed.has("qingbo_water_fresh_restock_done") || state.completed.has("qingbo_water_fresh_signature_line")) return null;
  const opening = syncShopOpeningState();
  const target = opening.restockTarget?.status === "active" ? opening.restockTarget : null;
  const qingboTarget = target && target.itemId === "item_food_qingbo_yukuai" && shopRestockTargetIsWaterFresh(target) ? target : null;
  const sale = opening.firstSale?.itemId === "item_food_qingbo_yukuai"
    ? opening.firstSale
    : (state.shopReport || []).find((entry) => entry.reason === "qinghe_pond" && String(entry.detail || entry.text || "").includes("清波鱼脍首卖")) || null;
  if (!qingboTarget && !sale) return null;
  const desiredCount = Number(qingboTarget?.desiredCount || 2);
  const have = Number(state.inventory.item_food_qingbo_yukuai || 0);
  const ready = qingboTarget ? shopRestockTargetReady(qingboTarget) : have >= desiredCount;
  const customerName = sale?.name || "水鲜顾客";
  const reviewQuote = sale?.reviewQuote || sale?.returnPreview?.summary || "这口灵池鲜味被客人记住了";
  const routeText = "首卖成交 -> 顾客记住 -> 补两份接回头客";
  return {
    key: `${state.day}:${have}:${desiredCount}:${ready ? 1 : 0}:qingbo_first_sale_seed`,
    id: "qingbo_first_sale_restock_seed_note",
    title: ready ? "水鲜首卖补货缘由 · 可点" : "清波鱼脍首卖回头客种子签 · 可点",
    headline: ready ? "两份水鲜已经接上回头苗头" : "第一位客人把水鲜记住了",
    detail: ready
      ? `${itemName("item_food_qingbo_yukuai")} ${have}/${desiredCount}，先回旧铺完成补货，再开铺验证回头客。`
      : `${customerName}买走后，旧铺要把${itemName("item_food_qingbo_yukuai")}补到 ${desiredCount} 份。`,
    reviewQuote,
    routeText,
    customerName,
    itemId: "item_food_qingbo_yukuai",
    itemName: itemName("item_food_qingbo_yukuai"),
    have,
    desiredCount,
    ready,
    targetId: qingboTarget?.id || "",
    rect: { x: 522, y: 326, width: 314, height: 112 },
    anchor: { x: 248, y: 254 },
    safeNote: "只定位旧铺补货追踪、配方或旧铺报告，不会自动开铺、完成补货、加工或消耗材料",
  };
}

function qingboFirstSaleRestockSeedWorldAtCanvasPoint(px, py) {
  const spec = qingboFirstSaleRestockSeedWorldSpec();
  if (!spec?.rect) return null;
  const { rect, anchor } = spec;
  const onCard = px >= rect.x && px <= rect.x + rect.width && py >= rect.y && py <= rect.y + rect.height;
  const onAnchor = px >= anchor.x - 56 && px <= anchor.x + 56 && py >= anchor.y - 30 && py <= anchor.y + 30;
  return onCard || onAnchor ? spec : null;
}

