function qingheLotusBasinLongOrderWorldNoteSpec() {
  if (!state.completed.has("qinghe_lotus_basin_followup_order_done") && !state.completedOrders.has("order_year2_water_0002")) return null;
  const opening = syncShopOpeningState();
  const target = opening.restockTarget?.status === "active" && opening.restockTarget.source === "lianze_waterway_reorder"
    ? opening.restockTarget
    : null;
  const restockDone = state.completed.has("lianze_waterway_reorder_restock_done");
  const followup = restockDone ? waterwayReorderFollowupSpec(sellableInventoryGoods(), currentShelfTheme()) : null;
  const ledger = restockDone ? waterwayLongOrderLedgerSpec(state.shopReport, followup) : null;
  const have = target?.itemId ? Number(state.inventory[target.itemId] || 0) : 0;
  const ready = target ? shopRestockTargetReady(target) : false;
  const phase = target
    ? ready ? "restock_ready" : "restock"
    : restockDone
      ? ledger?.stable
        ? "stable"
        : ledger?.started
          ? "ledger"
          : followup?.stocked
            ? "visit"
            : "stock"
      : "open_shop";
  const progressText = ledger ? `${ledger.progress}/${ledger.target}` : "0/3";
  return {
    id: "qinghe_lotus_basin_long_order_note",
    phase,
    title: phase === "stable"
      ? "莲泽长单已稳 · 可点"
      : phase === "ledger"
        ? "莲泽长单账 · 可点"
        : phase === "visit"
          ? "莲泽回订复访 · 可点"
          : phase === "stock"
            ? "熟路货架待补 · 可点"
            : phase === "restock_ready"
              ? "莲泽回订补货可完 · 可点"
              : phase === "restock"
                ? "莲泽回订补货牌 · 可点"
                : "莲泽长单待起账 · 可点",
    headline: phase === "stable"
      ? "旧铺成了水航熟路补给点"
      : phase === "ledger"
        ? `长单账进度 ${progressText}`
        : phase === "visit"
          ? "水航客会回来看不断档货"
          : phase === "stock"
            ? "回订兑现了，货架还要厚"
            : phase === "restock_ready"
              ? `${target.itemName} 已补够`
              : phase === "restock"
                ? `${target.itemName} ${have}/${target.desiredCount}`
                : "先开铺让水航客回门",
    detail: phase === "stable"
      ? "保持水鲜、饮品和路线稀货不断档，水航客会把旧铺当作长期据点。"
      : phase === "ledger"
        ? ledger.headline
        : phase === "visit"
          ? `${followup.leadItemName} 已能接复访，下一次开铺看水航客是否认货。`
          : phase === "stock"
            ? followup.detail
            : phase === "restock_ready"
              ? "回旧铺完成补货目标，让水航客把熟路货记成不断档。"
              : phase === "restock"
                ? `期限第 ${target.dueDay} 天，先按路线补厚这件熟路货。`
                : "续订单已交付，下一次开铺会让水航客挑选熟路货并生成回订补货线索。",
    routeText: "续订单 -> 回订补货 -> 水航复访 -> 长单账",
    ready,
    targetItemId: target?.itemId || followup?.leadItemId || "",
    targetItemName: target?.itemName || followup?.leadItemName || "水航熟路货",
    have,
    desiredCount: Number(target?.desiredCount || 0),
    dueDay: Number(target?.dueDay || 0),
    progressText,
    ledgerStarted: Boolean(ledger?.started),
    ledgerStable: Boolean(ledger?.stable),
    stocked: Boolean(followup?.stocked),
    rect: { x: 528, y: 318, width: 348, height: 104 },
  };
}

