function activeStoryVisitFeedback(now = performance.now()) {
  const feedback = state.storyVisitFeedback;
  if (!feedback) return null;
  if (state.claimedQuestRewards.has(feedback.questId)) {
    state.storyVisitFeedback = null;
    return null;
  }
  const dialogueActive = state.activeDialogue.some((line) => line.groupId === feedback.dialogueGroupId);
  if (dialogueActive) feedback.dialogueShown = true;
  const age = now - Number(feedback.createdAt || 0);
  const expireAt = feedback.dialogueShown ? 7600 : 15000;
  if (age > expireAt) {
    state.storyVisitFeedback = null;
    return null;
  }
  return {
    ...feedback,
    age,
    fresh: age < 6200,
    fade: age < 6200 ? 1 : Math.max(0, 1 - (age - 6200) / 1400),
  };
}

