function drawShopSaleFeedback(ctx, width, height, feedback = activeShopSaleFeedback()) {
  if (!feedback || state.activeCutscene || state.activeDialogue.length > 0) return;
  const pulse = settings.reducedMotion ? 0 : Math.sin(performance.now() / 280) * 4;
  const x = 46;
  const y = 214 + pulse;
  const decisionPath = Array.isArray(feedback.decisionPath) ? feedback.decisionPath.slice(0, 3) : [];
  const returnPathSteps = Array.isArray(feedback.returnPathSteps) ? feedback.returnPathSteps.slice(0, 3) : [];
  const cardHeight = feedback.returnPreview ? (feedback.firstSale ? 276 : 248) : feedback.firstSale || decisionPath.length >= 3 ? 226 : 192;
  const exchangeProgress = settings.reducedMotion ? 1 : Math.min(1, Math.max(0, feedback.age || 0) / 1350);
  const previewText = feedback.returnPreview
    ? `回头客 ${feedback.returnPreview.chance}% · ${feedback.returnPreview.cta}`
    : feedback.hotTagLabel
      ? `热卖预告 ${feedback.hotTagLabel} · ${feedback.cta}`
      : feedback.cta;
  ctx.save();
  ctx.globalAlpha = feedback.fade;
  drawCanvasCard(ctx, x, y, 396, cardHeight, "rgba(255, 248, 232, 0.95)");
  ctx.fillStyle = "rgba(224, 182, 109, 0.18)";
  ctx.beginPath();
  ctx.arc(x + 356, y + 28, 42, 0, Math.PI * 2);
  ctx.fill();

  if (images.customer) {
    ctx.drawImage(images.customer, x + 18, y + 22, 64, 64);
  } else {
    ctx.fillStyle = "#b47d2f";
    ctx.beginPath();
    ctx.roundRect(x + 28, y + 34, 44, 42, 16);
    ctx.fill();
    ctx.fillStyle = "#fff0d4";
    ctx.beginPath();
    ctx.arc(x + 51, y + 28, 16, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.fillStyle = "#b47d2f";
  ctx.font = "700 13px Microsoft YaHei";
  ctx.fillText(feedback.qingboFirstSale ? "水鲜首卖" : feedback.firstSale ? "旧铺首单" : "旧铺成交", x + 96, y + 26);
  ctx.fillStyle = "#17231d";
  ctx.font = "700 18px Microsoft YaHei";
  ctx.fillText(feedback.headline.slice(0, 18), x + 96, y + 52);
  ctx.fillStyle = "#8f5f3f";
  ctx.font = "700 14px Microsoft YaHei";
  ctx.fillText(`${feedback.customerName} · ${feedback.itemName} · ${feedback.price} 灵石`.slice(0, 27), x + 96, y + 76);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "12px Microsoft YaHei";
  if (feedback.needBubbleText) {
    ctx.fillStyle = "rgba(255, 253, 245, 0.92)";
    ctx.strokeStyle = "rgba(224, 182, 109, 0.42)";
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.roundRect(x + 94, y + 86, 258, 25, 12);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = "#8f5f3f";
    ctx.font = "700 11px Microsoft YaHei";
    ctx.fillText(`想法泡泡：${feedback.needBubbleText}`.slice(0, 30), x + 108, y + 103);
  } else {
    ctx.fillText(feedback.reasonText.slice(0, 32), x + 96, y + 96);
  }
  const pathY = feedback.needBubbleText ? y + 126 : y + 116;
  if (decisionPath.length) {
    ctx.fillStyle = "#5d6f65";
    ctx.font = "11px Microsoft YaHei";
    decisionPath.slice(1).forEach((line, index) => {
      ctx.fillText(line.slice(0, 42), x + 96, pathY + index * 17);
    });
  }
  const visitLineActive = (feedback.returningCustomer && feedback.returnVisitText) || (feedback.introducedCustomer && feedback.introducedVisitText);
  if (feedback.returningCustomer && feedback.returnVisitText) {
    ctx.fillStyle = "#286f58";
    ctx.font = "12px Microsoft YaHei";
    ctx.fillText(`熟脸回门：${feedback.returnVisitText}`.slice(0, 34), x + 96, pathY + decisionPath.length * 12);
  } else if (feedback.introducedCustomer && feedback.introducedVisitText) {
    ctx.fillStyle = "#b47d2f";
    ctx.font = "12px Microsoft YaHei";
    ctx.fillText(`熟客带新客：${feedback.introducedVisitText}`.slice(0, 34), x + 96, pathY + decisionPath.length * 12);
  } else if (feedback.reviewQuote && !decisionPath.some((line) => line.includes("顾客短评"))) {
    ctx.fillStyle = "#8f5f3f";
    ctx.font = "12px Microsoft YaHei";
    ctx.fillText(`顾客短评：${feedback.reviewQuote}`.slice(0, 34), x + 96, visitLineActive ? y + 136 : pathY + 17);
  }
  drawShopSaleExchangeAnimation(ctx, x + 34, y + 68, feedback, exchangeProgress);
  if (returnPathSteps.length) {
    const routeY = y + cardHeight - 82;
    ctx.fillStyle = feedback.returnPreview?.tone === "good" ? "rgba(40, 111, 88, 0.12)" : feedback.returnPreview?.tone === "mid" ? "rgba(224, 182, 109, 0.16)" : "rgba(255, 253, 245, 0.68)";
    ctx.strokeStyle = feedback.returnPreview?.tone === "good" ? "rgba(40, 111, 88, 0.32)" : "rgba(224, 182, 109, 0.38)";
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.roundRect(x + 18, routeY, 360, 50, 16);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = feedback.returnPreview?.tone === "good" ? "#286f58" : "#b47d2f";
    ctx.font = "800 11px Microsoft YaHei";
    ctx.fillText((feedback.returnPathTitle || "回头客苗头").slice(0, 13), x + 30, routeY + 17);
    returnPathSteps.forEach((step, index) => {
      const nodeX = x + 32 + index * 114;
      const nodeY = routeY + 25;
      const nodeColor = step.tone === "need" ? "#4d91a6" : step.tone === "reason" ? "#8f5f3f" : feedback.returnPreview?.tone === "good" ? "#286f58" : "#b47d2f";
      if (index > 0) {
        ctx.strokeStyle = "rgba(143, 95, 63, 0.26)";
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(nodeX - 30, nodeY + 10);
        ctx.lineTo(nodeX - 6, nodeY + 10);
        ctx.stroke();
      }
      ctx.fillStyle = `${nodeColor}22`;
      ctx.beginPath();
      ctx.roundRect(nodeX, nodeY, 88, 18, 9);
      ctx.fill();
      ctx.fillStyle = nodeColor;
      ctx.font = "800 9px Microsoft YaHei";
      ctx.fillText(`${step.label}：${String(step.text || "").slice(0, 6)}`, nodeX + 7, nodeY + 12);
    });
  }
  ctx.fillStyle = "#5d6f65";
  ctx.font = "12px Microsoft YaHei";
  ctx.fillText(previewText.slice(0, 46), x + 24, y + cardHeight - 18);
  ctx.restore();
}

function drawShopRestockFulfillmentFeedback(ctx, width, height, feedback = activeShopRestockFulfillmentFeedback()) {
  if (!feedback || state.activeCutscene || state.activeDialogue.length > 0) return;
  const age = Number(feedback.age || 0);
  const p = settings.reducedMotion ? 1 : Math.min(1, Math.max(0, age / 1500));
  const ease = p < 0.5 ? 2 * p * p : 1 - ((-2 * p + 2) ** 2) / 2;
  const pulse = settings.reducedMotion ? 0 : Math.sin(performance.now() / 310) * 4;
  const x = Math.max(34, width - 438);
  const y = 182 + pulse;
  const shelfX = x + 38;
  const shelfY = y + 74;
  const crateX = x + 258 - (1 - ease) * 72;
  const crateY = shelfY + 28 - Math.sin(ease * Math.PI) * (settings.reducedMotion ? 0 : 14);
  const waterFresh = Boolean(feedback.waterFresh);
  const accent = waterFresh ? "#4d91a6" : feedback.themeMatched ? "#286f58" : "#b47d2f";
  const soft = waterFresh ? "rgba(77, 145, 166, 0.2)" : feedback.themeMatched ? "rgba(40, 111, 88, 0.18)" : "rgba(224, 182, 109, 0.2)";

  ctx.save();
  ctx.globalAlpha = feedback.fade;

  const glow = ctx.createRadialGradient(x + 252, y + 82, 18, x + 252, y + 82, 210);
  glow.addColorStop(0, waterFresh ? "rgba(159, 209, 223, 0.46)" : feedback.themeMatched ? "rgba(202, 235, 210, 0.42)" : "rgba(246, 240, 182, 0.38)");
  glow.addColorStop(0.58, soft);
  glow.addColorStop(1, waterFresh ? "rgba(77, 145, 166, 0)" : "rgba(224, 182, 109, 0)");
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(x + 252, y + 84, 210, 0, Math.PI * 2);
  ctx.fill();

  drawCanvasCard(ctx, x, y, 392, 172, waterFresh ? "rgba(241, 249, 251, 0.96)" : "rgba(255, 248, 232, 0.95)");
  ctx.fillStyle = soft;
  ctx.beginPath();
  ctx.roundRect(x + 18, y + 20, 356, 52, 20);
  ctx.fill();

  ctx.fillStyle = accent;
  ctx.font = "700 13px Microsoft YaHei";
  ctx.fillText(waterFresh ? "水鲜补货兑现演出" : "补货兑现演出", x + 32, y + 42);
  ctx.fillStyle = "#17231d";
  ctx.font = "700 18px Microsoft YaHei";
  ctx.fillText(feedback.headline.slice(0, 18), x + 32, y + 64);

  ctx.fillStyle = waterFresh ? "rgba(77, 145, 166, 0.76)" : "rgba(143, 95, 63, 0.78)";
  ctx.beginPath();
  ctx.roundRect(shelfX, shelfY + 38, 168, 18, 8);
  ctx.fill();
  ctx.fillStyle = "rgba(255, 253, 245, 0.74)";
  ctx.beginPath();
  ctx.roundRect(shelfX + 12, shelfY, 144, 46, 12);
  ctx.fill();
  ctx.strokeStyle = "rgba(143, 95, 63, 0.24)";
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.roundRect(shelfX + 20, shelfY + 8, 128, 30, 8);
  ctx.stroke();

  for (let i = 0; i < 4; i += 1) {
    const itemX = shelfX + 30 + i * 29;
    const rise = settings.reducedMotion ? 0 : Math.sin(ease * Math.PI + i * 0.7) * 3;
    ctx.fillStyle = waterFresh ? i % 2 === 0 ? accent : "#286f58" : i % 2 === 0 ? accent : "#dea952";
    ctx.beginPath();
    if (waterFresh) {
      ctx.ellipse(itemX + 9, shelfY + 27 - rise, 11, 7, -0.18, 0, Math.PI * 2);
    } else {
      ctx.roundRect(itemX, shelfY + 15 - rise, 18, 23, 6);
    }
    ctx.fill();
    ctx.fillStyle = "rgba(255, 253, 245, 0.78)";
    if (waterFresh) {
      ctx.beginPath();
      ctx.arc(itemX + 14, shelfY + 25 - rise, 1.6, 0, Math.PI * 2);
      ctx.fill();
    } else {
      ctx.fillRect(itemX + 5, shelfY + 22 - rise, 8, 2);
    }
  }

  ctx.fillStyle = "rgba(23, 35, 29, 0.16)";
  ctx.beginPath();
  ctx.ellipse(crateX + 34, crateY + 42, 42, 10, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = waterFresh ? "#4d91a6" : "#8f5f3f";
  ctx.beginPath();
  ctx.roundRect(crateX, crateY, 68, 42, 10);
  ctx.fill();
  ctx.strokeStyle = "rgba(255, 253, 245, 0.45)";
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(crateX + 10, crateY + 12);
  ctx.lineTo(crateX + 58, crateY + 32);
  ctx.moveTo(crateX + 58, crateY + 12);
  ctx.lineTo(crateX + 10, crateY + 32);
  ctx.stroke();

  ctx.fillStyle = "rgba(255, 253, 245, 0.94)";
  ctx.beginPath();
  ctx.roundRect(x + 214, y + 78, 148, 58, 16);
  ctx.fill();
  ctx.strokeStyle = `${accent}66`;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.roundRect(x + 224, y + 88, 128, 38, 12);
  ctx.stroke();
  ctx.fillStyle = waterFresh ? "#4d91a6" : "#be4f37";
  ctx.font = "700 15px Microsoft YaHei";
  ctx.fillText(waterFresh ? "水鲜" : "兑现", x + 236, y + 111);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "12px Microsoft YaHei";
  ctx.fillText(`${feedback.itemName} ${feedback.count}/${feedback.desiredCount}`.slice(0, 15), x + 278, y + 111);

  const chipY = y + 144;
  feedback.chips.slice(0, 3).forEach((chip, index) => {
    const chipX = x + 24 + index * 116;
    const chipColor = chip.tone === "good" ? "#286f58" : "#b47d2f";
    ctx.fillStyle = chip.tone === "good" ? "rgba(202, 235, 210, 0.76)" : "rgba(246, 240, 182, 0.78)";
    ctx.beginPath();
    ctx.roundRect(chipX, chipY, 104, 22, 11);
    ctx.fill();
    ctx.fillStyle = chipColor;
    ctx.font = "700 11px Microsoft YaHei";
    ctx.fillText(`${chip.label} ${chip.value}`.slice(0, 10), chipX + 10, chipY + 15);
  });

  if (!settings.reducedMotion) {
    for (let i = 0; i < 9; i += 1) {
      const moteAge = (age / 900 + i * 0.17) % 1;
      const moteX = x + 236 + Math.cos(i * 1.7) * (42 + moteAge * 42);
      const moteY = y + 88 + Math.sin(i * 1.2) * 20 - moteAge * 34;
      ctx.fillStyle = waterFresh
        ? i % 2 === 0 ? "rgba(159, 209, 223, 0.78)" : "rgba(202, 235, 210, 0.72)"
        : i % 2 === 0 ? "rgba(246, 240, 182, 0.78)" : "rgba(202, 235, 210, 0.72)";
      ctx.beginPath();
      ctx.arc(moteX, moteY, 2.4 + (1 - moteAge) * 1.8, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  ctx.fillStyle = "#5d6f65";
  ctx.font = "12px Microsoft YaHei";
  ctx.fillText(`${feedback.tagLabel} · ${feedback.detail}`.slice(0, 42), x + 28, y + 132);
  ctx.restore();
}

