function drawSpiritSproutFeedback(ctx, width, height, feedback = activeSpiritSproutFeedback()) {
  if (!feedback || state.activeCutscene || state.activeDialogue.length > 0) return;
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const bob = settings.reducedMotion ? 0 : Math.sin(motion * 3.2) * 5;
  const accent = feedback.tone === "born" ? "#be4f37" : feedback.tone === "peek" ? "#b47d2f" : "#286f58";
  const glowColor = feedback.tone === "born" ? "rgba(190, 79, 55, 0.28)" : feedback.tone === "peek" ? "rgba(224, 182, 109, 0.28)" : "rgba(202, 235, 210, 0.3)";
  const x = Math.round(width / 2 - 228);
  const y = 84 + bob;

  ctx.save();
  ctx.globalAlpha = Number(feedback.fade ?? 1);
  const glow = ctx.createRadialGradient(x + 88, y + 64, 16, x + 88, y + 64, 190);
  glow.addColorStop(0, glowColor);
  glow.addColorStop(0.54, "rgba(246, 240, 182, 0.12)");
  glow.addColorStop(1, "rgba(246, 240, 182, 0)");
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(x + 88, y + 64, 190, 0, Math.PI * 2);
  ctx.fill();

  drawCanvasCard(ctx, x, y, 456, 138, "rgba(255, 253, 245, 0.95)");
  ctx.fillStyle = "rgba(237, 243, 223, 0.76)";
  ctx.beginPath();
  ctx.roundRect(x + 20, y + 22, 88, 88, 24);
  ctx.fill();
  ctx.strokeStyle = accent;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.roundRect(x + 28, y + 30, 72, 72, 20);
  ctx.stroke();

  if (feedback.stage === "peek" || feedback.stage === "born") {
    ctx.fillStyle = feedback.stage === "born" ? "#fffdf5" : "#f5f0b6";
    ctx.beginPath();
    ctx.arc(x + 64, y + 68 + bob * 0.2, 22, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#286f58";
    ctx.beginPath();
    ctx.arc(x + 56, y + 62 + bob * 0.2, 3.4, 0, Math.PI * 2);
    ctx.arc(x + 72, y + 62 + bob * 0.2, 3.4, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = "#286f58";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(x + 64, y + 70 + bob * 0.2, 8, 0.18, Math.PI - 0.18);
    ctx.stroke();
    ctx.fillStyle = "#48a868";
    ctx.beginPath();
    ctx.ellipse(x + 52, y + 42 + bob * 0.15, 12, 6, -0.55, 0, Math.PI * 2);
    ctx.ellipse(x + 76, y + 42 + bob * 0.15, 12, 6, 0.55, 0, Math.PI * 2);
    ctx.fill();
  } else {
    const tremble = settings.reducedMotion ? 0 : Math.sin(motion * 12) * 3;
    ctx.fillStyle = "#48a868";
    ctx.beginPath();
    ctx.ellipse(x + 56 + tremble, y + 64, 18, 8, -0.45, 0, Math.PI * 2);
    ctx.ellipse(x + 74 + tremble, y + 58, 18, 8, 0.45, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = accent;
    ctx.font = "900 28px Microsoft YaHei";
    ctx.fillText("?", x + 56 + tremble, y + 47);
  }

  ctx.fillStyle = accent;
  ctx.font = "700 13px Microsoft YaHei";
  ctx.fillText(String(feedback.label || "成精预告").slice(0, 14), x + 132, y + 34);
  ctx.fillStyle = "#17231d";
  ctx.font = "800 21px Microsoft YaHei";
  ctx.fillText(String(feedback.headline || feedback.title || "田垄里有异动").slice(0, 18), x + 132, y + 62);
  ctx.fillStyle = "#286f58";
  ctx.font = "13px Microsoft YaHei";
  ctx.fillText(String(feedback.shortDetail || feedback.detail || "").slice(0, 36), x + 132, y + 90);
  ctx.fillStyle = "#8f5f3f";
  ctx.font = "700 12px Microsoft YaHei";
  ctx.fillText(String(feedback.cta || "继续照料这株作物").slice(0, 40), x + 132, y + 116);
  ctx.restore();
}

function ecologyOrderFeedbackAnchor(comboId = "") {
  const anchors = {
    eco_rain_herb_garden: { x: 388, y: 302 },
    eco_fire_feast_hall: { x: 566, y: 464 },
    eco_night_lamp_path: { x: 694, y: 236 },
    eco_cloud_warehouse: { x: 738, y: 318 },
    eco_flower_guest_yard: { x: 670, y: 408 },
    eco_moon_pond: { x: 900, y: 410 },
    eco_honey_orchard: { x: 736, y: 438 },
    eco_book_order_room: { x: 724, y: 382 },
  };
  return anchors[comboId] || { x: 760, y: 406 };
}

function drawEcologyDailyVisualAccent(ctx, feedback, anchor, motion, pulse, accent) {
  const type = feedback.visualType || "spirit_mark";
  ctx.save();
  ctx.translate(anchor.x, anchor.y);
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  if (type === "field_totem") {
    ctx.strokeStyle = "rgba(77, 145, 166, 0.7)";
    ctx.lineWidth = 2;
    for (let i = 0; i < 5; i += 1) {
      const x = -34 + i * 17;
      const lift = Math.sin(motion * 2 + i) * 3;
      ctx.beginPath();
      ctx.moveTo(x, 16);
      ctx.quadraticCurveTo(x + 4, -2 + lift, x + 16, -18 + lift);
      ctx.stroke();
      ctx.fillStyle = i % 2 ? "rgba(202, 235, 210, 0.82)" : "rgba(159, 209, 223, 0.78)";
      ctx.beginPath();
      ctx.ellipse(x + 15, -18 + lift, 5, 8, 0.7, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.fillStyle = "rgba(255, 253, 245, 0.9)";
    ctx.beginPath();
    ctx.ellipse(0, 12, 38, 9, 0, 0, Math.PI * 2);
    ctx.fill();
  } else if (type === "warm_hearth") {
    ctx.fillStyle = "rgba(190, 79, 55, 0.2)";
    ctx.beginPath();
    ctx.ellipse(0, 18, 48, 14, 0, 0, Math.PI * 2);
    ctx.fill();
    for (let i = 0; i < 4; i += 1) {
      const flame = Math.max(0, 16 + Math.sin(motion * 3 + i) * 6);
      ctx.fillStyle = i % 2 ? "rgba(246, 240, 182, 0.86)" : "rgba(240, 165, 78, 0.82)";
      ctx.beginPath();
      ctx.moveTo(-18 + i * 12, 10);
      ctx.quadraticCurveTo(-10 + i * 12, -flame, -2 + i * 12, 10);
      ctx.closePath();
      ctx.fill();
    }
  } else if (type === "lantern_road") {
    ctx.strokeStyle = "rgba(180, 125, 47, 0.62)";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(-54, 18);
    ctx.quadraticCurveTo(-8, -20 + pulse, 54, 10);
    ctx.stroke();
    for (let i = 0; i < 4; i += 1) {
      const x = -42 + i * 28;
      const y = 11 + Math.sin(motion * 1.8 + i) * 3;
      ctx.fillStyle = "rgba(246, 240, 182, 0.86)";
      ctx.beginPath();
      ctx.roundRect(x - 6, y - 13, 12, 18, 5);
      ctx.fill();
      ctx.strokeStyle = accent;
      ctx.stroke();
    }
  } else if (type === "thunder_route") {
    ctx.strokeStyle = "rgba(246, 240, 182, 0.72)";
    ctx.lineWidth = 3;
    ctx.setLineDash([9, 7]);
    ctx.lineDashOffset = settings.reducedMotion ? 0 : -motion * 24;
    ctx.beginPath();
    ctx.moveTo(-54, 20);
    ctx.bezierCurveTo(-20, -34, 20, 32, 56, -16);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = "rgba(255, 253, 245, 0.9)";
    ctx.beginPath();
    ctx.roundRect(-18, -14, 38, 28, 6);
    ctx.fill();
    ctx.strokeStyle = "rgba(143, 156, 154, 0.86)";
    ctx.stroke();
    ctx.fillStyle = "rgba(143, 95, 63, 0.74)";
    ctx.fillRect(-9, -5, 20, 2);
    ctx.fillRect(-9, 3, 14, 2);
  } else if (type === "flower_honey") {
    for (let i = 0; i < 8; i += 1) {
      const angle = motion * 0.6 + i * 0.78;
      const x = Math.cos(angle) * (32 + (i % 2) * 9);
      const y = Math.sin(angle) * 16;
      ctx.fillStyle = i % 3 === 0 ? "rgba(224, 182, 109, 0.86)" : "rgba(216, 127, 141, 0.76)";
      ctx.beginPath();
      ctx.ellipse(x, y, 4, 8, angle, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.fillStyle = "rgba(23, 35, 29, 0.78)";
    ctx.beginPath();
    ctx.arc(18 + Math.sin(motion * 4) * 5, -10, 3, 0, Math.PI * 2);
    ctx.fill();
  } else if (type === "moon_pond") {
    ctx.strokeStyle = "rgba(77, 145, 166, 0.72)";
    ctx.lineWidth = 2;
    for (let i = 0; i < 3; i += 1) {
      ctx.beginPath();
      ctx.ellipse(0, 14, 28 + i * 14 + Math.max(0, pulse), 7 + i * 3, 0, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.fillStyle = "rgba(246, 240, 182, 0.86)";
    ctx.beginPath();
    ctx.arc(-8, -22, 18, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "rgba(248, 252, 247, 0.94)";
    ctx.beginPath();
    ctx.arc(0, -26, 18, 0, Math.PI * 2);
    ctx.fill();
  } else if (type === "old_relic") {
    for (let i = 0; i < 3; i += 1) {
      const open = Math.sin(motion * 2 + i) * 5;
      ctx.fillStyle = "rgba(255, 253, 245, 0.92)";
      ctx.beginPath();
      ctx.roundRect(-28 + i * 18, -16 - open, 24, 34, 4);
      ctx.fill();
      ctx.strokeStyle = "rgba(143, 95, 63, 0.72)";
      ctx.stroke();
      ctx.fillStyle = "rgba(143, 95, 63, 0.58)";
      ctx.fillRect(-22 + i * 18, -3 - open, 12, 2);
    }
  } else {
    ctx.strokeStyle = accent;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(0, 0, 28 + Math.max(0, pulse), 0.2, Math.PI * 1.8);
    ctx.stroke();
    ctx.fillStyle = "rgba(255, 253, 245, 0.9)";
    ctx.beginPath();
    ctx.arc(0, 0, 10, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.restore();
}

function drawEcologyOrderFeedback(ctx, width, height, feedback = activeEcologyOrderFeedback()) {
  if (!feedback || state.activeCutscene || state.activeDialogue.length > 0) return;
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const pulse = settings.reducedMotion ? 0 : Math.sin(motion * 3) * 5;
  const anchor = ecologyOrderFeedbackAnchor(feedback.comboId);
  const routeEnd = { x: 462, y: 326 };
  const accent = feedback.tierAccent || "#286f58";

  ctx.save();
  ctx.globalAlpha = feedback.fade;
  const glow = ctx.createRadialGradient(anchor.x, anchor.y, 10, anchor.x, anchor.y, 148 + Math.max(0, pulse));
  glow.addColorStop(0, "rgba(246, 240, 182, 0.42)");
  glow.addColorStop(0.46, "rgba(202, 235, 210, 0.18)");
  glow.addColorStop(1, "rgba(202, 235, 210, 0)");
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(anchor.x, anchor.y, 150 + Math.max(0, pulse), 0, Math.PI * 2);
  ctx.fill();

  ctx.strokeStyle = "rgba(246, 240, 182, 0.72)";
  ctx.lineWidth = 6;
  ctx.lineCap = "round";
  ctx.setLineDash([18, 12]);
  ctx.lineDashOffset = settings.reducedMotion ? 0 : -motion * 34;
  ctx.beginPath();
  ctx.moveTo(anchor.x, anchor.y);
  ctx.bezierCurveTo(anchor.x - 48, anchor.y - 78, routeEnd.x + 64, routeEnd.y - 56, routeEnd.x, routeEnd.y);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.strokeStyle = accent;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(anchor.x, anchor.y);
  ctx.bezierCurveTo(anchor.x - 48, anchor.y - 78, routeEnd.x + 64, routeEnd.y - 56, routeEnd.x, routeEnd.y);
  ctx.stroke();

  for (let i = 0; i < 7; i += 1) {
    const t = ((motion * 0.16 + i / 7) % 1);
    const inv = 1 - t;
    const x = inv ** 3 * anchor.x
      + 3 * inv ** 2 * t * (anchor.x - 48)
      + 3 * inv * t ** 2 * (routeEnd.x + 64)
      + t ** 3 * routeEnd.x;
    const y = inv ** 3 * anchor.y
      + 3 * inv ** 2 * t * (anchor.y - 78)
      + 3 * inv * t ** 2 * (routeEnd.y - 56)
      + t ** 3 * routeEnd.y;
    ctx.fillStyle = i % 2 ? "rgba(255, 253, 245, 0.9)" : "rgba(224, 182, 109, 0.84)";
    ctx.beginPath();
    ctx.arc(x, y, 3.2 + (i % 3), 0, Math.PI * 2);
    ctx.fill();
  }

  drawEcologyComboMotif(ctx, feedback.comboId, anchor.x, anchor.y - 24 + pulse * 0.2, 0, motion);

  const cardX = Math.max(34, Math.min(width - 348, anchor.x - 292));
  const cardY = Math.max(132, Math.min(height - 132, anchor.y - 128));
  drawCanvasCard(ctx, cardX, cardY, 328, 112, "rgba(255, 248, 232, 0.94)");
  ctx.fillStyle = "rgba(202, 235, 210, 0.26)";
  ctx.beginPath();
  ctx.roundRect(cardX + 16, cardY + 16, 58, 72, 18);
  ctx.fill();
  drawEcologyComboMotif(ctx, feedback.comboId, cardX + 45, cardY + 48, 1, motion);

  ctx.fillStyle = accent;
  ctx.font = "700 12px Microsoft YaHei";
  ctx.fillText(`${feedback.tierLabel} · 订单回响`, cardX + 88, cardY + 28);
  ctx.fillStyle = "#17231d";
  ctx.font = "700 17px Microsoft YaHei";
  ctx.fillText(feedback.headline.slice(0, 18), cardX + 88, cardY + 54);
  ctx.fillStyle = "#8f5f3f";
  ctx.font = "700 12px Microsoft YaHei";
  ctx.fillText(`${feedback.orderTitle} · ${feedback.npcLabel}`.slice(0, 30), cardX + 88, cardY + 76);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "11px Microsoft YaHei";
  ctx.fillText(`${feedback.matchedTagText} · ${feedback.focusText}`.slice(0, 36), cardX + 88, cardY + 96);
  ctx.restore();
}

function drawEcologyDailyFeedback(ctx, width, height, feedback = activeEcologyDailyFeedback()) {
  if (!feedback || state.activeCutscene || state.activeDialogue.length > 0) return;
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const pulse = settings.reducedMotion ? 0 : Math.sin(motion * 2.8) * 4;
  const anchor = ecologyOrderFeedbackAnchor(feedback.comboId);
  const accent = feedback.tierAccent || "#286f58";

  ctx.save();
  ctx.globalAlpha = feedback.fade;
  const glow = ctx.createRadialGradient(anchor.x, anchor.y, 8, anchor.x, anchor.y, 116 + Math.max(0, pulse));
  glow.addColorStop(0, "rgba(255, 253, 245, 0.48)");
  glow.addColorStop(0.48, "rgba(202, 235, 210, 0.2)");
  glow.addColorStop(1, "rgba(202, 235, 210, 0)");
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(anchor.x, anchor.y, 120 + Math.max(0, pulse), 0, Math.PI * 2);
  ctx.fill();

  for (let i = 0; i < 10; i += 1) {
    const angle = (Math.PI * 2 * i) / 10 + motion * 0.35;
    const radius = 32 + (i % 3) * 10 + Math.max(0, pulse);
    ctx.fillStyle = i % 2 ? "rgba(246, 240, 182, 0.78)" : "rgba(202, 235, 210, 0.72)";
    ctx.beginPath();
    ctx.arc(anchor.x + Math.cos(angle) * radius, anchor.y + Math.sin(angle) * radius * 0.62, 2.8, 0, Math.PI * 2);
    ctx.fill();
  }
  drawEcologyDailyVisualAccent(ctx, feedback, anchor, motion, pulse, accent);
  drawEcologyComboMotif(ctx, feedback.comboId, anchor.x, anchor.y - 20 + pulse * 0.2, 1, motion);

  const cardX = Math.max(36, Math.min(width - 314, anchor.x - 254));
  const cardY = Math.max(86, Math.min(height - 112, anchor.y - 112));
  drawCanvasCard(ctx, cardX, cardY, 294, 92, "rgba(248, 252, 247, 0.94)");
  ctx.fillStyle = accent;
  ctx.font = "700 12px Microsoft YaHei";
  ctx.fillText(`${feedback.tierLabel || "生态庭院"} · 夜间小事`, cardX + 20, cardY + 26);
  ctx.fillStyle = "#17231d";
  ctx.font = "700 17px Microsoft YaHei";
  ctx.fillText(`${feedback.title} · ${feedback.comboName}`.slice(0, 18), cardX + 20, cardY + 52);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "12px Microsoft YaHei";
  const rewardText = feedback.rewards?.length ? `收获 ${feedback.rewards.map((reward) => reward.text).join("、")}` : feedback.moodText;
  ctx.fillText(rewardText.slice(0, 32), cardX + 20, cardY + 74);
  ctx.restore();
}

function drawEcologyInspectionFeedback(ctx, width, height, feedback = activeEcologyInspectionFeedback()) {
  if (!feedback || state.activeCutscene || state.activeDialogue.length > 0) return;
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const pulse = settings.reducedMotion ? 0 : Math.sin(motion * 3.2) * 4;
  const anchor = { x: feedback.x || ecologyOrderFeedbackAnchor(feedback.comboId).x, y: feedback.y || ecologyOrderFeedbackAnchor(feedback.comboId).y };
  const accent = feedback.tierAccent || "#286f58";
  const previewNodes = feedback.previewOnly ? (feedback.nodes || ecologyInspectionKeepsakeNodes(feedback)).slice(0, 3) : [];
  const cardWidth = previewNodes.length ? 336 : 308;
  const cardHeight = previewNodes.length ? 154 : 106;

  ctx.save();
  ctx.globalAlpha = feedback.fade;
  const glow = ctx.createRadialGradient(anchor.x, anchor.y, 8, anchor.x, anchor.y, 118 + Math.max(0, pulse));
  glow.addColorStop(0, "rgba(246, 240, 182, 0.44)");
  glow.addColorStop(0.45, "rgba(202, 235, 210, 0.2)");
  glow.addColorStop(1, "rgba(202, 235, 210, 0)");
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(anchor.x, anchor.y, 122 + Math.max(0, pulse), 0, Math.PI * 2);
  ctx.fill();

  ctx.strokeStyle = accent;
  ctx.lineWidth = 2;
  ctx.setLineDash([10, 8]);
  ctx.lineDashOffset = settings.reducedMotion ? 0 : -motion * 26;
  ctx.beginPath();
  ctx.arc(anchor.x, anchor.y, 34 + Math.max(0, pulse), 0, Math.PI * 2);
  ctx.stroke();
  ctx.setLineDash([]);
  drawEcologyDailyVisualAccent(ctx, feedback, anchor, motion, pulse, accent);
  drawEcologyComboMotif(ctx, feedback.comboId, anchor.x, anchor.y - 22 + pulse * 0.15, 2, motion);

  const cardX = Math.max(32, Math.min(width - cardWidth - 28, anchor.x - 232));
  const cardY = Math.max(92, Math.min(height - cardHeight - 28, anchor.y - 118));
  drawCanvasCard(ctx, cardX, cardY, cardWidth, cardHeight, "rgba(255, 248, 232, 0.95)");
  ctx.fillStyle = accent;
  ctx.font = "700 12px Microsoft YaHei";
  ctx.fillText(`${feedback.landmarkLabel || "生态庭院"} · ${feedback.previewOnly ? "生态巡看留签" : "今日巡看"}`, cardX + 20, cardY + 25);
  ctx.fillStyle = "#17231d";
  ctx.font = "700 17px Microsoft YaHei";
  ctx.fillText((feedback.headline || "庭院有新动静").slice(0, 18), cardX + 20, cardY + 50);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "12px Microsoft YaHei";
  ctx.fillText(`${feedback.caretakerName || "精怪"}：${feedback.actionText || "照看庭院"}`.slice(0, 28), cardX + 20, cardY + 72);
  ctx.fillStyle = feedback.previewOnly ? "#286f58" : feedback.alreadyInspected ? "#8f5f3f" : "#b47d2f";
  ctx.font = "700 11px Microsoft YaHei";
  const rewardText = feedback.previewOnly
    ? "只预览定位 · 不记录巡看 / 不发奖励"
    : feedback.alreadyInspected
      ? "今日已巡看 · 可继续观察但不重复收益"
      : `灵石 +${feedback.rewardGold || 0} · 全体心情 +${feedback.rewardMood || 0}`;
  ctx.fillText(rewardText.slice(0, 34), cardX + 20, cardY + 92);
  if (previewNodes.length) {
    const nodeY = cardY + 108;
    const nodeWidth = 94;
    previewNodes.forEach((node, index) => {
      const nodeX = cardX + 18 + index * 104;
      const focused = feedback.activeNodeKey === node.key;
      ctx.fillStyle = focused ? `${accent}22` : "rgba(255, 253, 245, 0.82)";
      ctx.strokeStyle = focused ? `${accent}88` : "rgba(143, 95, 63, 0.18)";
      ctx.lineWidth = focused ? 1.8 : 1;
      ctx.beginPath();
      ctx.roundRect(nodeX, nodeY, nodeWidth, 28, 10);
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = focused ? accent : "#8f5f3f";
      ctx.font = "800 9px Microsoft YaHei";
      ctx.fillText(node.label.slice(0, 5), nodeX + 8, nodeY + 12);
      ctx.fillStyle = "#5d6f65";
      ctx.font = "8px Microsoft YaHei";
      ctx.fillText(node.title.slice(0, 8), nodeX + 8, nodeY + 23);
    });
  }
  ctx.restore();
}

function drawWorkshopCraftFeedback(ctx, width, height, feedback = activeWorkshopCraftFeedback()) {
  if (!feedback || state.activeCutscene || state.activeDialogue.length > 0) return;
  const now = performance.now();
  const pulse = settings.reducedMotion ? 0 : Math.sin(now / 300) * 5;
  const orderMatch = feedback.orderMatch || null;
  const firstAroma = Boolean(feedback.firstAroma);
  const cardWidth = firstAroma ? 378 : 318;
  const cardHeight = orderMatch ? (firstAroma ? 178 : 148) : (firstAroma ? 156 : 128);
  const x = Math.max(28, Math.min(width - cardWidth - 28, width - cardWidth - 42));
  const y = firstAroma ? 118 + pulse : 142 + pulse;
  const accent = firstAroma ? "#b47d2f" : orderMatch?.ready ? "#286f58" : "#be4f37";
  ctx.save();
  ctx.globalAlpha = feedback.fade;

  if (firstAroma) {
    const glow = ctx.createRadialGradient(x + 82, y + 70, 16, x + 82, y + 70, 210);
    glow.addColorStop(0, "rgba(246, 240, 182, 0.42)");
    glow.addColorStop(0.48, "rgba(224, 182, 109, 0.18)");
    glow.addColorStop(1, "rgba(224, 182, 109, 0)");
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(x + 82, y + 70, 210, 0, Math.PI * 2);
    ctx.fill();
  }

  drawCanvasCard(ctx, x, y, cardWidth, cardHeight, "rgba(255, 248, 232, 0.96)");
  ctx.fillStyle = firstAroma ? "rgba(224, 182, 109, 0.18)" : "rgba(190, 79, 55, 0.14)";
  ctx.beginPath();
  ctx.arc(x + cardWidth - 40, y + 30, 42, 0, Math.PI * 2);
  ctx.fill();

  for (let puff = 0; puff < (firstAroma ? 7 : 3); puff += 1) {
    const lift = settings.reducedMotion ? puff * 7 : ((now / 28) + puff * 13) % (firstAroma ? 48 : 26);
    const drift = firstAroma ? Math.sin(now / 420 + puff) * 7 : 0;
    ctx.fillStyle = puff % 2 ? "rgba(255, 253, 245, 0.78)" : "rgba(246, 240, 182, 0.62)";
    ctx.beginPath();
    ctx.arc(x + 42 + puff * 14 + drift, y + 58 - lift, Math.max(3, 9 - puff * 0.7), 0, Math.PI * 2);
    ctx.fill();
  }
  if (firstAroma) {
    ctx.strokeStyle = "rgba(224, 182, 109, 0.62)";
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 7]);
    ctx.lineDashOffset = settings.reducedMotion ? 0 : -now / 36;
    ctx.beginPath();
    ctx.moveTo(x + 70, y + 54);
    ctx.bezierCurveTo(x + 132, y + 24, x + 220, y + 34, x + cardWidth - 58, y + 70);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  ctx.fillStyle = "#8f5f3f";
  ctx.beginPath();
  ctx.roundRect(x + 22, y + 64, 56, 24, 10);
  ctx.fill();
  ctx.strokeStyle = "rgba(255, 253, 245, 0.72)";
  ctx.strokeRect(x + 30, y + 70, 40, 10);

  ctx.fillStyle = accent;
  ctx.font = "700 13px Microsoft YaHei";
  ctx.fillText(firstAroma ? "加工动画 · 香气特效" : "工坊出锅", x + 94, y + 26);
  ctx.fillStyle = "#17231d";
  ctx.font = "700 18px Microsoft YaHei";
  ctx.fillText(feedback.headline.slice(0, firstAroma ? 20 : 18), x + 94, y + 52);
  ctx.fillStyle = "#8f5f3f";
  ctx.font = "700 15px Microsoft YaHei";
  ctx.fillText(`${feedback.outputItemName} x${feedback.outputCount}`, x + 94, y + 76);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "12px Microsoft YaHei";
  ctx.fillText(feedback.detail.slice(0, firstAroma ? 36 : 28), x + 94, y + 98);
  ctx.fillText((feedback.orderTitle ? `${feedback.orderTitle} · ${feedback.orderNpc}` : feedback.cta).slice(0, firstAroma ? 34 : 28), x + 94, y + 116);
  if (firstAroma) {
    const ticketX = x + cardWidth - 132;
    const ticketY = y + 58;
    ctx.fillStyle = "rgba(255, 253, 245, 0.94)";
    ctx.strokeStyle = "rgba(224, 182, 109, 0.48)";
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.roundRect(ticketX, ticketY, 104, 50, 12);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = "#b47d2f";
    ctx.font = "800 12px Microsoft YaHei";
    ctx.fillText("第一张订单出现", ticketX + 10, ticketY + 20);
    ctx.fillStyle = "#5d6f65";
    ctx.font = "11px Microsoft YaHei";
    ctx.fillText((orderMatch?.orderTitle || "订单板亮了").slice(0, 8), ticketX + 12, ticketY + 38);
  }
  if (orderMatch) {
    ctx.fillStyle = orderMatch.ready ? "rgba(237, 243, 223, 0.92)" : "rgba(255, 248, 232, 0.92)";
    ctx.strokeStyle = orderMatch.ready ? "rgba(40, 111, 88, 0.32)" : "rgba(224, 182, 109, 0.38)";
    ctx.beginPath();
    ctx.roundRect(x + 22, y + cardHeight - 26, cardWidth - 44, 22, 10);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = orderMatch.ready ? "#286f58" : "#8f5f3f";
    ctx.font = "700 11px Microsoft YaHei";
    ctx.fillText((orderMatch.ready ? `订单板亮了：${orderMatch.orderTitle} 可交` : `订单接上线：还差 ${orderMatch.missingText || "余料"}`).slice(0, firstAroma ? 34 : 26), x + 36, y + cardHeight - 11);
  }
  ctx.restore();
}

