function drawYuelianCanalClueSign(ctx, spec = yuelianCanalClueSpec()) {
  if (!spec) return false;
  const { rect } = spec;
  const { tile, gap, originX, originY } = gridMetrics();
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const pulse = settings.reducedMotion ? 0 : Math.sin(motion * 2.2) * 3;
  const plot = spec.plot
    ? state.plots.find((entry) => entry.x === spec.plot.x && entry.y === spec.plot.y)
    : null;
  const plotX = plot ? originX + plot.x * (tile + gap) : rect.x - 12;
  const plotY = plot ? originY + plot.y * (tile + gap) : rect.y - 12;
  const lotusX = plotX + tile * 0.7;
  const lotusY = plotY + tile * 0.74;

  ctx.save();
  ctx.fillStyle = "rgba(159, 209, 223, 0.22)";
  ctx.beginPath();
  ctx.ellipse(lotusX, lotusY, tile * 0.54 + pulse, tile * 0.17, 0, 0, Math.PI * 2);
  ctx.fill();

  for (let i = 0; i < 6; i += 1) {
    const angle = motion * 0.35 + i * Math.PI / 3;
    ctx.fillStyle = i % 2 ? "rgba(255, 253, 245, 0.8)" : "rgba(159, 209, 223, 0.78)";
    ctx.beginPath();
    ctx.ellipse(lotusX + Math.cos(angle) * 15, lotusY - 4 + Math.sin(angle) * 8, 5, 12, angle, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.strokeStyle = "rgba(159, 209, 223, 0.74)";
  ctx.lineWidth = 2;
  ctx.setLineDash([6, 7]);
  ctx.lineDashOffset = settings.reducedMotion ? 0 : -motion * 14;
  ctx.beginPath();
  ctx.moveTo(rect.x + 26, rect.y + pulse + 8);
  ctx.quadraticCurveTo(rect.x - 20, rect.y - 16, lotusX, lotusY);
  ctx.stroke();
  ctx.setLineDash([]);

  drawCanvasCard(ctx, rect.x, rect.y + pulse, rect.width, rect.height, "rgba(236, 248, 243, 0.9)");
  ctx.strokeStyle = "rgba(159, 209, 223, 0.78)";
  ctx.lineWidth = 1.7;
  ctx.beginPath();
  ctx.roundRect(rect.x, rect.y + pulse, rect.width, rect.height, 18);
  ctx.stroke();

  ctx.fillStyle = "rgba(159, 209, 223, 0.24)";
  ctx.beginPath();
  ctx.roundRect(rect.x + 12, rect.y + 13 + pulse, 38, 38, 14);
  ctx.fill();
  ctx.fillStyle = "#4d91a6";
  ctx.font = "900 18px Microsoft YaHei";
  ctx.fillText("莲", rect.x + 22, rect.y + 39 + pulse);

  ctx.fillStyle = "#286f58";
  ctx.font = "800 13px Microsoft YaHei";
  ctx.fillText(spec.title.slice(0, 12), rect.x + 62, rect.y + 21 + pulse);
  ctx.fillStyle = "#17231d";
  ctx.font = "800 14px Microsoft YaHei";
  ctx.fillText(spec.headline.slice(0, 11), rect.x + 62, rect.y + 40 + pulse);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "11px Microsoft YaHei";
  ctx.fillText(spec.detail.slice(0, 14), rect.x + 62, rect.y + 57 + pulse);
  ctx.fillStyle = "#8f5f3f";
  ctx.font = "700 10px Microsoft YaHei";
  ctx.fillText(spec.hint.slice(0, 22), rect.x + 16, rect.y + 69 + pulse);
  ctx.restore();
  return true;
}

