function focusSolarTermMoodScene(action = "term", target = "") {
  if (action === "field") {
    if (target) return focusSolarFieldBoardPlot(target);
    return focusGenericSleepPrepTarget({
      selector: "#selectedPlotCard",
      fallbackSelector: "#termPanel",
      label: "今日画境：田地",
      log: "已定位灵田卡，只辅助查看今日节气下最适合处理的田块；不会自动播种、浇水、收获、入夜或消耗资源。",
      panelGroup: "core",
      pulseClass: "story-compass-focus-pulse",
    });
  }
  if (action === "shop") {
    return focusGenericSleepPrepTarget({
      selector: state.shopReport.length > 0 ? "#shopReport" : "#recipeSelect",
      fallbackSelector: "#shopReport",
      label: "今日画境：旧铺",
      log: "已定位旧铺与备货信息，只辅助查看天气货签和应季商品；不会自动开铺、定价、补货、交单或消耗资源。",
      panelGroup: "core",
      pulseClass: "story-compass-focus-pulse",
    });
  }
  if (action === "spirit") {
    if (target) return focusAutomationJobLine(target);
    return focusGenericSleepPrepTarget({
      selector: "#spiritList",
      fallbackSelector: "#selectedPlotCard",
      label: "今日画境：精怪",
      log: "已定位精怪入口，只辅助查看成精路线和岗位氛围；不会自动触发成精、切岗、派工、喂食、入夜或消耗资源。",
      panelGroup: "core",
      pulseClass: "story-compass-focus-pulse",
    });
  }
  if (action === "risk") return focusSleepPrepRisk();
  if (action === "weather_life") {
    if (target) return focusDaySummaryWeatherLife(target);
    return focusGenericSleepPrepTarget({
      selector: "#termPanel",
      fallbackSelector: "#riskPanel",
      label: "今日画境：天气小景",
      log: "今日天气小景先回到节气影响面板查看；这里只辅助回看氛围，不会处理风险、开铺、入夜或消耗资源。",
      panelGroup: "systems",
      pulseClass: "story-compass-focus-pulse",
    });
  }
  return focusGenericSleepPrepTarget({
    selector: "#termPanel",
    fallbackSelector: "#riskPanel",
    label: "今日画境：节气",
    log: "已定位节气影响面板，只辅助查看当前节气、天气、成长和市场标签；不会自动处理风险、入夜或消耗资源。",
    panelGroup: "systems",
    pulseClass: "story-compass-focus-pulse",
  });
}

