function syncSolarTermMoodStampArchiveForDay(day = state.day, trail = state.solarTermMoodTrail || []) {
  const stamp = solarTermMoodStampArchiveEntryForDay(day, trail);
  if (!stamp) return null;
  const archive = (state.solarTermMoodStampArchive || [])
    .map(normalizeSolarTermMoodStampArchiveEntry)
    .filter((entry) => entry.stampId !== stamp.stampId);
  state.solarTermMoodStampArchive = [stamp, ...archive].slice(0, 24);
  return stamp;
}

