function recordSolarTermMoodPanelRoute(routeKey = "", action = "", target = "") {
  if (!routeKey) return null;
  const scene = solarTermMoodSceneSpec();
  const route = scene?.routes?.find((row) => row.key === routeKey) || null;
  if (!route) return null;
  return recordSolarTermMoodTrail({
    key: `${scene.key}:${route.key}`,
    source: "term_panel",
    label: route.label,
    title: route.title,
    detail: route.detail,
    tone: route.tone,
    action: action || route.action,
    target: target || route.target || "",
  });
}

function focusSolarTermMoodStampArchive(stampId = "") {
  const spec = solarTermMoodStampArchiveSpec(8);
  const row = spec.rows.find((entry) => entry.stampId === stampId) || spec.today || spec.rows[0] || null;
  if (!row) return focusSolarTermMoodScene("term", "");
  const missingRoute = row.rows.find((entry) => !entry.visited) || null;
  const focusRoute = missingRoute || row.rows.find((entry) => entry.visited) || null;
  const routeEntry = focusRoute?.entry || null;
  addLog("目标册：节气画境印记", `${row.isToday ? "今日" : `第 ${row.day} 天`} ${row.termName} · ${row.weatherName}：${row.complete ? "四路读懂，已收进合图印。" : row.detail} ${row.safetyText}`);
  if (row.isToday) {
    if (routeEntry) return focusSolarTermMoodScene(routeEntry.action, routeEntry.target);
    if (focusRoute?.key) return focusSolarTermMoodScene(focusRoute.key, "");
    return focusSolarTermMoodScene("term", "");
  }
  return focusGenericSleepPrepTarget({
    selector: "#termPanel",
    fallbackSelector: "#goalBookPanel",
    label: "节气画境印记",
    log: `已翻到第 ${row.day} 天的节气画境印记；旧日印记只作收藏回看，不切换时间，也不会执行任何操作。`,
    panelGroup: "systems",
    pulseClass: "story-compass-focus-pulse",
  });
}

function focusSolarTermMoodStampArchiveRoute(stampId = "", routeKey = "") {
  const spec = solarTermMoodStampArchiveSpec(8);
  const row = spec.rows.find((entry) => entry.stampId === stampId) || spec.today || spec.rows[0] || null;
  if (!row) return focusSolarTermMoodScene("term", "");
  const route = row.rows.find((entry) => entry.key === routeKey) || row.rows[0] || null;
  if (!route) return focusSolarTermMoodStampArchive(row.stampId);
  const routeEntry = route.entry ? normalizeSolarTermMoodTrailEntry(route.entry) : null;
  const routeTitle = routeEntry?.title || route.label;
  addLog(
    "目标册：画境路线页",
    `${row.isToday ? "今日" : `第 ${row.day} 天`} ${row.termName} · ${row.weatherName} / ${route.label}：${route.visited ? routeTitle : "这一路还没读懂"}。这里只翻看或定位路线页，不会自动播种、浇水、收获、开铺、派工、处理风险、入夜或消耗资源。`,
  );
  if (row.isToday) {
    if (!route.visited && route.key) {
      const recorded = recordSolarTermMoodPanelRoute(route.key);
      if (recorded) return focusSolarTermMoodScene(recorded.action, recorded.target);
    }
    if (routeEntry) return focusSolarTermMoodScene(routeEntry.action, routeEntry.target);
    return focusSolarTermMoodScene(route.key || "term", "");
  }
  const routeSelector = `button[data-solar-mood-stamp="${selectorDataValue(row.stampId)}"][data-solar-mood-stamp-route="${selectorDataValue(route.key)}"]`;
  return focusGenericSleepPrepTarget({
    selector: routeSelector,
    fallbackSelector: "#goalBookPanel",
    label: "节气画境路线页",
    log: `已翻到第 ${row.day} 天的 ${route.label} 路线页；旧日印记只作收藏回看，不切换时间，也不会执行任何经营动作。`,
    panelGroup: "core",
    pulseClass: "story-compass-focus-pulse",
  });
}

