    fallbackSelector: "#relationshipPanel",
    panelGroup: "story",
    log: row
      ? `${npcLabel} 今日在${row.locationName || "镇上"}，关系面板会定位到这条动线。${GROTTO_LIFE_PULSE_SAFETY_TEXT}`
      : `镇上今天没有特别醒目的动线，先看关系面板和支线入口。${GROTTO_LIFE_PULSE_SAFETY_TEXT}`,
