function focusHarvestStorageRouteWorldFromCanvas(spec = harvestStorageRouteWorldSpec()) {
  if (!spec?.cropId) return false;
  harvestStorageRouteWorldFocus = { key: spec.key, day: state.day, cropId: spec.cropId };
  if (spec.plot) state.selected = { x: spec.plot.x, y: spec.plot.y };
  if (spec.plot) {
    const plot = state.plots.find((entry) => entry.x === spec.plot.x && entry.y === spec.plot.y);
    if (plot) pulseAtPlot(plot, "work", { harvestText: "已入仓" });
  }
  addLog(
    "点选收获入仓去向留签",
    `${spec.cropName} x${spec.amount} 已入仓，当前库存 ${spec.stock}。路线：${spec.routeText}，下一步：${spec.actionLabel}。${spec.safety}。`,
  );
  if (spec.route?.orderId) return focusPlotRouteOrder(spec.route.orderId);
  if (spec.route?.recipeId) return focusPlotRouteRecipe(spec.route.recipeId);
  if (spec.route?.type === "shop" || spec.route?.shopTag) return focusPlotRouteShop(spec.route.shopTag || "", spec.route.itemId || spec.cropId);
  queuePlotRouteFocusTarget({
    selector: "#inventoryList",
    fallbackSelector: "#selectedPlotCard",
    label: "收获入仓去向留签",
    log: `${spec.cropName} 已定位到背包库存。${spec.routeDetail} ${spec.safety}。`,
    panelGroup: "core",
    missingTitle: "收获入仓去向留签",
    missingLog: "背包列表暂时没有找到；先看灵田卡和日志确认这批收成已入仓。",
  });
  return true;
}

