function drawTownLifeErrandRouteWorldFocus(ctx, width, height) {
  const focus = townLifeErrandRouteWorldFocus;
  if (!focus || Number(focus.day || 0) !== Number(state.day || 0) || !focus.source || !focus.target) {
    townLifeErrandRouteWorldFocus = null;
    return;
  }
  const now = typeof performance !== "undefined" ? performance.now() : Date.now();
  const elapsed = Math.max(0, now - Number(focus.createdAt || now));
  const duration = Math.max(1, Number(focus.duration || 5600));
  if (elapsed > duration) {
    townLifeErrandRouteWorldFocus = null;
    return;
  }
  const progress = Math.max(0, Math.min(1, elapsed / duration));
  const fade = progress < 0.78 ? 1 : Math.max(0, 1 - (progress - 0.78) / 0.22);
  const motion = settings.reducedMotion ? 0 : now / 1000;
  const pulse = settings.reducedMotion ? 0 : Math.sin(motion * 4) * 4;
  return drawTownLifeErrandRouteWorldFocusWorld({
    ctx,
    width,
    height,
    focus,
    progress,
    fade,
    motion,
    pulse,
    reducedMotion: settings.reducedMotion,
    drawCanvasCard,
  });
}

