function drawSpiritJobShiftFeedback(ctx, width, height, feedback = activeSpiritJobShiftFeedback()) {
  if (!feedback || state.activeCutscene || state.activeDialogue.length > 0) return;
  const age = Number(feedback.age || 0);
  const p = settings.reducedMotion ? 1 : Math.min(1, age / 1250);
  const ease = p < 0.5 ? 2 * p * p : 1 - ((-2 * p + 2) ** 2) / 2;
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const station = feedback.station || { x: 320, y: 320, size: 82 };
  const targetX = station.x + station.size * 0.54;
  const targetY = station.y + station.size * 0.44;
  const startX = Math.max(64, Math.min(width - 64, 128 + (state.spirits.findIndex((spirit) => spirit.id === feedback.spiritId) + 1) * 42));
  const startY = height - 92;
  const tokenX = startX + (targetX - startX) * ease;
  const tokenY = startY + (targetY - startY) * ease - Math.sin(ease * Math.PI) * (settings.reducedMotion ? 0 : 42);
  drawSpiritJobShiftFeedbackWorld({
    ctx,
    width,
    height,
    feedback,
    station,
    motion,
    reducedMotion: settings.reducedMotion,
    startX,
    startY,
    targetX,
    targetY,
    tokenX,
    tokenY,
    drawCanvasCard,
  });
}

function drawSpiritNightWorkFeedback(ctx, width, height, feedback = activeSpiritNightWorkFeedback()) {
  if (!feedback || state.activeCutscene || state.activeDialogue.length > 0) return;
  const age = Number(feedback.age || 0);
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const progress = settings.reducedMotion ? 1 : Math.min(1, age / 1800);
  const wave = Math.sin(progress * Math.PI);
  return drawSpiritNightWorkFeedbackWorld({
    ctx,
    width,
    height,
    feedback,
    motion,
    progress,
    wave,
    reducedMotion: settings.reducedMotion,
    drawCanvasCard,
  });
}

