function drawSpiritColony(ctx) {
  ctx.save();
  drawSpiritJobSynergyNetwork(ctx);
  spiritCanvasTargets().forEach(({ spirit, station, index }) => {
    const job = spirit.job || "farm";
    const profile = spiritVisualProfile(spirit);
    drawSpiritWorkRangeAura(ctx, spirit, station, index);
    drawSpiritAutomationTrail(ctx, spirit, station, index);
    drawSpiritSeasonalWorkTrail(ctx, spirit, station, index);
    drawSpiritJobEffect(ctx, spirit, station.x, station.y, station.size, profile);
    drawSpiritFinaleCompanionAnchor(ctx, spirit, station, index);
    if (index === 0) drawSpiritAura(ctx, station.x - 12, station.y + station.size * 0.08, `岗位：${jobName(job)}`);
    if (index < 5) drawSpiritJobPersonaBubble(ctx, spirit, station, index);
    drawSpiritWorldLifeStatus(ctx, spirit, station, index);
    drawSpiritSprite(ctx, spirit, station.x, station.y, station.size);
    drawSpiritIdentityMemoryNameplate(ctx, spirit, station, index);
    if (index < 6) drawSpiritDailyChoreProp(ctx, spirit, station, index);
    drawSpiritCompanionCareHint(ctx, spirit, station, index);
  });

  drawSpiritMoodRepairWorldScene(ctx);
  drawSpiritCareNeedWorldBoard(ctx);
  drawSpiritCropScoutWorld(ctx);

  const interactionEchoTarget = spiritInteractionWorldEchoTarget();
  if (interactionEchoTarget) {
    if (interactionEchoTarget.entry.type === "theater") {
      drawRareSpiritTheaterMoment(ctx, interactionEchoTarget.entry, interactionEchoTarget.spirit, interactionEchoTarget.station);
      ctx.restore();
      return;
    }
    drawSpiritInteractionWorldEcho(ctx, interactionEchoTarget);
    drawSpiritBondHeartlineWorld(ctx, spiritBondHeartlineWorldSpec(interactionEchoTarget));
    drawSpiritInteractionMemoryTriptychWorld(ctx, spiritInteractionMemoryTriptychWorldSpec(interactionEchoTarget));
  }

  if (state.spirits.length > 8) {
    drawCanvasCard(ctx, 696, 552, 206, 54, "rgba(255, 253, 245, 0.82)");
    ctx.fillStyle = "#286f58";
    ctx.font = "700 14px Microsoft YaHei";
    ctx.fillText(`还有 ${state.spirits.length - 8} 只精怪在洞天深处忙碌`, 714, 584);
  }
  ctx.restore();
}

function firstTwoSpiritDuoWorldSpec(width = refs.world?.width || 960, height = refs.world?.height || 640, livingState = currentLivingWorldState()) {
  const luobo = state.spirits.find((spirit) => (spirit.lineId || spiritLine(spirit.id)) === "spirit_line_luobo") || null;
  const lajiao = state.spirits.find((spirit) => (
    spirit.id === "spirit_lajiao_01"
    || (spirit.lineId || spiritLine(spirit.id)) === "spirit_line_lajiao"
  )) || null;
  if (!luobo || !lajiao) return null;
  const targets = spiritCanvasTargets();
  const luoboTarget = targets.find(({ spirit }) => spirit.id === luobo.id);
  const lajiaoTarget = targets.find(({ spirit }) => spirit.id === lajiao.id);
  const luoboStation = luoboTarget?.station || spiritJobStation({ ...luobo, job: "farm" }, 0, 0);
  const lajiaoStation = lajiaoTarget?.station || spiritJobStation({ ...lajiao, job: "workshop" }, 0, 1);
  const queue = livingState?.queue || state.workshopQueue || [];
  const lineSpec = workshopProductionLineSpec(queue);
  const focus = workshopQueueFocusSpec(queue);
  const assistDone = state.completed.has("assist");
  const craftDone = state.completed.has("craft");
  const lajiaoIntroDone = state.completedSpiritEvents.has("spirit_event_lajiao_01");
  const active = Boolean(lineSpec.activeJob || queue.length > 0);
  const tone = active ? "working" : assistDone && craftDone ? "linked" : "new";
  const headline = active
    ? "田里递料，灶边接火"
    : assistDone && craftDone
      ? "第一条伙伴生产链连上了"
      : "两只小伙伴正在认路";
  const detail = active
    ? `${luobo.name} 把田里的新鲜气递到后厂，${lajiao.name} 正在守 ${focus.outputItemName || lineSpec.activeJob?.outputItemName || "这一锅"}。`
    : assistDone && craftDone
      ? `${luobo.name} 负责省下手脚，${lajiao.name} 负责稳住火候，前店后厂开始像一个家。`
      : "先让萝卜精完成协助、再让工坊出一锅，协作线会更亮。";
  const focusSpirit = lajiaoIntroDone ? luobo : lajiao;
  const x = Math.max(24, Math.min(width - 306, 314));
  const y = Math.max(104, Math.min(height - 132, 414));
  return {
    key: `${state.day}:${luobo.id}:${lajiao.id}:${tone}:${queue.length}:${focus.progress || 0}`,
    day: state.day,
    luobo,
    lajiao,
    focusSpirit,
    focusSpiritId: focusSpirit.id,
    focusSpiritName: focusSpirit.name,
    tone,
    active,
    assistDone,
    craftDone,
    lajiaoIntroDone,
    headline,
    detail,
    title: "萝卜精 x 辣椒火灵协作小景",
    cta: "双精怪协作 · 可点",
    progress: Math.max(0, Math.min(100, Number(focus.progress || lineSpec.activeJob?.progress || (assistDone && craftDone ? 100 : assistDone || craftDone ? 54 : 24)))),
    recipeText: active ? focus.outputItemName || lineSpec.activeJob?.outputItemName || "工坊排产" : craftDone ? "第一锅已出" : "等第一锅",
    farmText: assistDone ? "3x3 浇水已会" : "等一次协助",
    rewardText: lajiaoIntroDone ? "两只伙伴已互相认路" : "辣椒火灵初见仍可记忆",
    rect: { x, y, width: 286, height: 114 },
    luoboAnchor: {
      x: luoboStation.x + luoboStation.size * 0.55,
      y: luoboStation.y + luoboStation.size * 0.62,
    },
    lajiaoAnchor: {
      x: lajiaoStation.x + lajiaoStation.size * 0.5,
      y: lajiaoStation.y + lajiaoStation.size * 0.56,
    },
  };
}

function firstTwoSpiritDuoWorldAtCanvasPoint(px, py) {
  const spec = firstTwoSpiritDuoWorldSpec(refs.world?.width || 960, refs.world?.height || 640);
  if (!spec?.rect) return null;
  const { rect } = spec;
  return (
    px >= rect.x
    && px <= rect.x + rect.width
    && py >= rect.y
    && py <= rect.y + rect.height
  ) ? spec : null;
}

function focusFirstTwoSpiritDuoWorldFromCanvas(spec = firstTwoSpiritDuoWorldSpec()) {
  if (!spec?.focusSpiritId) return false;
  firstTwoSpiritDuoWorldFocus = { key: spec.key, day: state.day };
  canvasSpiritCareFocus = {
    spiritId: spec.focusSpiritId,
    day: state.day,
    seasonal: {
      label: "双精怪协作小景",
      detail: spec.headline,
      effect: `${spec.detail} ${spec.rewardText}`,
    },
  };
  spiritFocusTarget = {
    selector: `[data-spirit-id="${selectorDataValue(spec.focusSpiritId)}"]`,
    spiritName: spec.focusSpiritName,
  };
  if (settings.panelGroup !== "core") {
    settings.panelGroup = "core";
    saveSettings();
  }
  playCue("对话翻页");
  addLog("点选双精怪协作", `${spec.headline}：${spec.detail} 伙伴栏已高亮 ${spec.focusSpiritName}，你可以继续摸摸、喂食、换岗或查看事件。`);
  render();
  return true;
}

function drawFirstTwoSpiritDuoWorld(ctx, spec = firstTwoSpiritDuoWorldSpec(), motion = 0) {
  if (!spec?.rect) return false;
  const focused = firstTwoSpiritDuoWorldFocus?.day === state.day
    && firstTwoSpiritDuoWorldFocus?.key === spec.key;
  const bob = settings.reducedMotion ? 0 : Math.sin(motion * 2.2) * 3;
  const pulse = settings.reducedMotion ? 0.5 : (Math.sin(motion * 3.4) + 1) / 2;
  const accent = spec.active ? "#be4f37" : spec.assistDone && spec.craftDone ? "#286f58" : "#b47d2f";
  return drawFirstTwoSpiritDuoWorldWorld({
    ctx,
    spec,
    motion,
    bob,
    pulse,
    accent,
    focused,
    reducedMotion: settings.reducedMotion,
    drawCanvasCard,
  });
}

function drawCareChainSpiritEcho(ctx, livingState = currentLivingWorldState()) {
  const echo = livingState.careChainEcho || careChainEchoSpec(livingState.careChainStage || state.careChainState);
  if (!echo || state.spirits.length === 0) return;
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const targets = spiritCanvasTargets().slice(0, Math.min(3, state.spirits.length));
  if (!targets.length) return;
  ctx.save();
  targets.forEach(({ station }, index) => {
    const x = station.x + station.size * 0.66 + index * 4;
    const y = station.y + station.size * 0.18 + Math.sin(motion * 2 + index) * 2;
    ctx.fillStyle = index % 2 ? "rgba(202, 235, 210, 0.86)" : "rgba(246, 240, 182, 0.9)";
    ctx.strokeStyle = "rgba(40, 111, 88, 0.34)";
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    if (echo.tone === "town") {
      ctx.roundRect(x, y, 22, 28, 7);
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = "#286f58";
      ctx.font = "700 10px Microsoft YaHei";
      ctx.fillText("灯", x + 5, y + 18);
    } else if (echo.tone === "rooted") {
      ctx.roundRect(x, y, 28, 20, 6);
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = "#286f58";
      ctx.font = "700 10px Microsoft YaHei";
      ctx.fillText("先顾", x + 4, y + 14);
    } else {
      ctx.arc(x + 11, y + 11, 10, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = "#8f5f3f";
      ctx.font = "700 10px Microsoft YaHei";
      ctx.fillText(index % 2 ? "签" : "篮", x + 5, y + 15);
    }
  });
  drawCanvasCard(ctx, 646, 508, 230, 54, "rgba(237, 243, 223, 0.84)");
  ctx.fillStyle = "#286f58";
  ctx.font = "700 13px Microsoft YaHei";
  ctx.fillText(`精怪主动照应 · ${echo.stageName}`, 664, 530);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "11px Microsoft YaHei";
  ctx.fillText(echo.spiritLine.slice(0, 28), 664, 548);
  ctx.restore();
}

