    subtitle: "伙伴肖像簿 · 可点",
    selector: "#goalBookPanel",
    fallbackSelector: "#spiritList",
    rect: { x: 708, y: 122, width: 206, height: 126 },
    anchor: { x: 836, y: 246 },
    sectionTitle: "六线人格",
    overviewTitle: "角色总览",
    moodTitle: "今日神态",
