function ecologyLineLabel(lineId = "") {
  const labels = {
    spirit_line_shui: "水脉精",
    spirit_line_yaoyuan: "药园精",
    spirit_line_lajiao: "灶火椒灵",
    spirit_line_meishi: "美食精",
    spirit_line_suan: "蒜头巡灵",
    spirit_line_dengying: "灯影精",
    spirit_line_yunshu: "云书精",
    spirit_line_caikuang: "采矿精",
    spirit_line_hualing: "花铃精",
    spirit_line_bucao: "补草精",
    spirit_line_yuelian: "月莲精",
    spirit_line_fengmi: "蜂蜜精",
    spirit_line_shuqi: "书契精",
  };
  return labels[lineId] || lineId.replace("spirit_line_", "");
}

function ecologyComboEffectText(combo) {
  const labels = {
    medicine_quality: "药品品质",
    cook_speed: "烹饪速度",
    night_risk_reduce: "夜路风险",
    logistics_bonus: "物流收益",
    customer_stay_bonus: "顾客停留",
    spirit_mood_cost_reduce: "心情消耗",
    dessert_quality: "甜品品质",
    order_forecast: "订单预判",
  };
  const label = labels[combo?.effect_type] || combo?.effect_type || "庭院加成";
  const value = Number(combo?.effect_param_1 || 0);
  if (!Number.isFinite(value) || value === 0) return label;
  if (combo?.effect_type === "night_risk_reduce" || combo?.effect_type === "spirit_mood_cost_reduce") {
    return `${label} -${Math.round(value * 100)}%`;
  }
  if (value > 0 && value < 1) return `${label} +${Math.round(value * 100)}%`;
  return `${label} +${value}`;
}

function ecologyComboUnlockHint(combo) {
  if (!combo) return "继续收集精怪与造景";
  const lines = splitTags(combo.required_spirit_lines).slice(0, 2).map(ecologyLineLabel).join(" + ");
  const tags = splitTags(combo.required_building_tags).slice(0, 2).join(" / ");
  return `${lines || "精怪线"} · ${tags || combo.required_area_tag || "庭院造景"}`;
}

function ecologyComboRequirementRows(combo) {
  if (!combo) return [];
  const ownedLines = new Set(state.spirits.map((spirit) => spirit.lineId || spiritLine(spirit.id)));
  const rows = splitTags(combo.required_spirit_lines).map((lineId) => ({
    key: `line:${lineId}`,
    label: `结缘 ${ecologyLineLabel(lineId)}`,
    done: ownedLines.has(lineId),
  }));

  if (combo.combo_id === "eco_moon_pond") {
    rows.push(
      { key: "building:fishpond", label: "修好灵池", done: state.builtBuildings.has("build_fishpond_lv1") },
      { key: "event:rsea_006", label: "完成月莲静池记忆", done: state.completedRareSpiritEvents.has("rsea_006") },
    );
    return rows;
  }
  if (combo.combo_id === "eco_night_lamp_path") {
    rows.push(
      { key: "event:rsea_008", label: "完成灯影离座", done: state.completedRareSpiritEvents.has("rsea_008") },
      { key: "experience:night", label: "经历一次秘境或巡夜风险", done: state.completed.has("dungeon_explore") || state.resolvedRisks.size > 0 },
    );
    return rows;
  }

  const requiredTags = splitTags(combo.required_building_tags);
  const builtMatches = data.buildings.filter((building) => state.builtBuildings.has(building.building_id));
  requiredTags.forEach((tag) => {
    rows.push({
      key: `building-tag:${tag}`,
      label: `布置 ${tag} 造景`,
      done: builtMatches.some((building) => (building.function_tags || "").includes(tag) || String(building.category || "").includes(tag)),
    });
  });
  return rows;
}

function ecologyCourtyardGoalRows() {
  syncGoalBookState();
  return data.spiritEcologyCombos.map((combo) => {
    const requirements = ecologyComboRequirementRows(combo);
    const doneCount = requirements.filter((entry) => entry.done).length;
    const active = ecologyComboActive(combo);
    const claimed = Boolean(state.goalBookState.ecologyClaims?.[combo.combo_id]);
    return {
      combo,
      comboId: combo.combo_id,
      name: ecologyComboName(combo),
      effectText: ecologyComboEffectText(combo),
      unlockHint: ecologyComboUnlockHint(combo),
      requirements,
      doneCount,
      totalCount: Math.max(1, requirements.length),
      active,
      claimed,
      ready: active && !claimed,
      progressText: `${Math.min(doneCount, requirements.length)}/${Math.max(1, requirements.length)}`,
      missingText: requirements.filter((entry) => !entry.done).slice(0, 2).map((entry) => entry.label).join("、"),
    };
  });
}

function ecologyCourtyardGoalRewardText(row) {
  const effect = row?.effectText || "庭院加成";
  return `${itemName("item_stone_spirit_shard")} x1 · 灵石 28 · ${effect}常驻可视`;
}

function ecologyCourtyardTier(score = 0) {
  if (score >= 88) {
    return {
      label: "甲等庭院",
      shortLabel: "甲等",
      accent: "#286f58",
      note: "主题、功能、生活事件和稀有造景已经连成完整共同体。",
    };
  }
  if (score >= 72) {
    return {
      label: "乙等庭院",
      shortLabel: "乙等",
      accent: "#4d91a6",
      note: "庭院已经能稳定服务经营与陪伴，再补几处专属事件就会非常完整。",
    };
  }
  if (score >= 56) {
    return {
      label: "丙等庭院",
      shortLabel: "丙等",
      accent: "#b47d2f",
      note: "主题轮廓已经立住，但还缺关键精怪、造景或小剧场支撑。",
    };
  }
  if (score > 0) {
    return {
      label: "初成庭院",
      shortLabel: "初成",
      accent: "#8f5f3f",
      note: "已经有生态共鸣的雏形，再补一两条生活线就会活起来。",
    };
  }
  return {
    label: "待布置庭院",
    shortLabel: "待布置",
    accent: "#5d6f65",
    note: "先完成第一批精怪共鸣，庭院才会真正像家。",
  };
}

function ecologyCourtyardSceneText(comboId = "") {
  const rows = {
    eco_rain_herb_garden: "药圃边常有细雨停着，草木和药香把田气压得很稳。",
    eco_fire_feast_hall: "灶火和席面连在一起，工坊那边会把饭香一路送到旧铺门前。",
    eco_night_lamp_path: "巡夜灯一盏接一盏亮起，连晚归的精怪都知道该往哪条路回家。",
    eco_cloud_warehouse: "货箱和路牌被理得很顺，商路回来的货不再堆成一团乱麻。",
    eco_flower_guest_yard: "花架和礼架一起留客，院里总像有人刚刚来过又舍不得走。",
    eco_moon_pond: "月色会在池边多停一会儿，夜里忙完的精怪也更愿意在这里歇脚。",
    eco_honey_orchard: "花树和蜜箱把西边田埂变成了甜香角落，连风都像带着回味。",
    eco_book_order_room: "账页和货签被收进同一间小屋，明天该补什么总能先看出来。",
  };
  return rows[comboId] || "庭院里多出一处真正有人会停下来的据点。";
}

function ecologyCourtyardScoreBreakdown(ecologyGoals = ecologyCourtyardGoalRows()) {
  syncRareSpiritLifeState();
  const memoryResonance = ecologyDailyMemoryResonance();
  const claimedGoals = ecologyGoals.filter((row) => row.claimed);
  const scoredGoals = ecologyGoals.filter((row) => row.claimed || row.active);
  const comboLines = [...new Set(scoredGoals.flatMap((row) => splitTags(row.combo?.required_spirit_lines)))];
  const distinctAreas = new Set(scoredGoals.map((row) => row.combo?.required_area_tag || "").filter(Boolean)).size;
  const ecologyMomentLines = new Set(Object.values(state.rareSpiritLifeState?.momentsBySpirit || {}).map((moment) => moment.lineId));
  const ecologyTheaterLines = new Set((state.rareSpiritLifeState.history || []).filter((entry) => entry.type === "theater").map((entry) => entry.lineId));
  const ecologyGiftLines = new Set((state.rareSpiritGifts || []).map((gift) => {
    const event = data.rareSpiritEvents.find((entry) => entry.entry_id === gift.entryId);
    return rareSpiritLineId(event);
  }).filter(Boolean));
  const supportedSpirits = comboLines.filter((lineId) => {
    const spirit = state.spirits.find((entry) => (entry.lineId || spiritLine(entry.id)) === lineId);
    if (!spirit) return false;
    const bondLevel = Math.max(Number(spirit.bondLevel || 1), bondLevelFor(spirit, spirit.bondExp));
    return bondLevel >= 5 || ecologyMomentLines.has(lineId);
  }).length;
  const highMoodCount = state.spirits.filter((spirit) => Number(spirit.mood || 0) >= 80).length;
  const themedMomentCount = comboLines.filter((lineId) => ecologyMomentLines.has(lineId)).length;
  const themedTheaterCount = comboLines.filter((lineId) => ecologyTheaterLines.has(lineId)).length;
  const themedGiftCount = comboLines.filter((lineId) => ecologyGiftLines.has(lineId)).length;

  const themeConsistency = Math.min(30, scoredGoals.length * 7 + claimedGoals.length * 2 + (claimedGoals.length >= 3 ? 5 : 0));
  const functionClosure = Math.min(25, distinctAreas * 5 + scoredGoals.length * 2 + (scoredGoals.length >= 4 ? 3 : 0));
  const spiritComfort = comboLines.length > 0
    ? Math.min(20, Math.round((supportedSpirits / comboLines.length) * 14) + Math.min(6, highMoodCount))
    : 0;
  const rareDecor = Math.min(15, claimedGoals.length * 4 + (claimedGoals.length >= 4 ? 3 : 0));
  const lifeEvents = Math.min(10, themedTheaterCount * 2 + Math.min(4, themedMomentCount) + Math.min(2, themedGiftCount) + memoryResonance.lifeScoreBonus);
  const total = themeConsistency + functionClosure + spiritComfort + rareDecor + lifeEvents;
  return {
    themeConsistency,
    functionClosure,
    spiritComfort,
    rareDecor,
    lifeEvents,
    memoryResonance: ecologyDailyMemoryResonanceSnapshot(memoryResonance),
    total,
    tier: ecologyCourtyardTier(total),
  };
}

function claimEcologyCourtyardGoal(comboId) {
  const row = ecologyCourtyardGoalRows().find((entry) => entry.comboId === comboId);
  if (!row) return addLog("生态目标不存在", comboId);
  if (row.claimed) return addLog("生态造景已收录", `${row.name} 已经记入生态庭院。`);
  if (!row.active) return addLog("生态共鸣未成", `${row.name} 还差 ${row.missingText || row.unlockHint}。`);
  syncGoalBookState();
  state.goalBookState.ecologyClaims[row.comboId] = `day:${state.day}`;
  addItem("item_stone_spirit_shard", 1);
  state.gold += 28;
  state.completed.add(`ecology_goal_${row.comboId}`);
  upsertWorldChange({
    key: `ecology_courtyard_${row.comboId}`,
    title: row.name,
    detail: `${row.name} 被正式收进生态庭院：${row.effectText}。精怪们把这处造景当作新的日常据点，往后主场景会持续显示这份生态共鸣。`,
    rewardHint: ecologyCourtyardGoalRewardText(row),
    visualType: row.comboId === "eco_moon_pond" ? "moon_pond" : row.comboId === "eco_night_lamp_path" ? "lantern_road" : "field_totem",
  });
  const rewardText = ecologyCourtyardGoalRewardText(row);
  complete("ecology_courtyard_goal_claim");
  triggerGoalClaimFeedback("ecology", {
    headline: row.name,
    detail: `${row.effectText} · 主场景会留下这处生态共鸣。`,
    rewardText,
  });
  playCue("成就解锁");
  addLog("生态造景完成", `${row.name}：领取 ${rewardText}。`);
  render();
}

function ecologyCourtyardSummary() {
  syncGoalBookState();
  syncRareSpiritLifeState();
  const ecologyGoals = ecologyCourtyardGoalRows();
  const activeCombos = activeEcologyCombos().map((combo) => ({
    comboId: combo.combo_id,
    name: ecologyComboName(combo),
    effectText: ecologyComboEffectText(combo),
    unlockHint: ecologyComboUnlockHint(combo),
    claimed: Boolean(state.goalBookState.ecologyClaims?.[combo.combo_id]),
  }));
  const claimedCombos = ecologyGoals
    .filter((row) => row.claimed)
    .map((row) => ({
      comboId: row.comboId,
      name: row.name,
      effectText: row.effectText,
      unlockHint: row.unlockHint,
      claimed: true,
      sceneText: ecologyCourtyardSceneText(row.comboId),
    }));
  const nextCombo = data.spiritEcologyCombos.find((combo) => !ecologyComboActive(combo));
  const moments = state.spirits
    .map((spirit) => rareSpiritMomentForSpirit(spirit))
    .filter(Boolean);
  const featuredMoment = moments.length
    ? moments[(state.day + activeCombos.length) % moments.length]
    : null;
  const featuredSpirit = featuredMoment
    ? state.spirits.find((spirit) => spirit.id === featuredMoment.spiritId)
    : null;
  const unresolvedClues = (state.rareSpiritClues || []).filter((clue) => !state.completedRareSpiritEvents?.has(clue.entryId));
  const scoreBreakdown = ecologyCourtyardScoreBreakdown(ecologyGoals);
  const scoreTier = scoreBreakdown.tier;
  const sceneRows = (claimedCombos.length > 0 ? claimedCombos : activeCombos)
    .slice(0, 3)
    .map((combo) => ({
      comboId: combo.comboId,
      name: combo.name,
      effectText: combo.effectText,
      text: combo.sceneText || ecologyCourtyardSceneText(combo.comboId),
    }));

  return {
    activeCount: activeCombos.length,
    totalCombos: data.spiritEcologyCombos.length,
    activeCombos,
    claimedCombos,
    topCombo: activeCombos[0] || null,
    nextCombo: nextCombo
      ? {
        comboId: nextCombo.combo_id,
        name: ecologyComboName(nextCombo),
        effectText: ecologyComboEffectText(nextCombo),
        unlockHint: ecologyComboUnlockHint(nextCombo),
      }
      : null,
    moments,
    featuredMoment,
    featuredProfile: featuredSpirit ? spiritVisualProfile(featuredSpirit) : null,
    clueCount: (state.rareSpiritClues || []).length,
    unresolvedClueCount: unresolvedClues.length,
    giftCount: (state.rareSpiritGifts || []).length,
    rareEventCount: Number(state.completedRareSpiritEvents?.size || 0),
    claimedGoalCount: ecologyGoals.filter((row) => row.claimed).length,
    readyGoalCount: ecologyGoals.filter((row) => row.ready).length,
    scoreBreakdown,
    score: scoreBreakdown.total,
    tier: scoreTier,
    sceneRows,
  };
}

function ecologyVisitorFocusArchetypes(ecologyGarden = ecologyCourtyardSummary(), goods = sellableInventoryGoods()) {
  const score = Number(ecologyGarden.score || ecologyGarden.scoreBreakdown?.total || 0);
  const comboIds = new Set([...(ecologyGarden.claimedCombos || []), ...(ecologyGarden.activeCombos || [])].map((combo) => combo.comboId).filter(Boolean));
  const goodsTags = new Set(goods.flatMap(({ itemId, item }) => shopTagsForItem(item || itemId, ecologyGarden)));
  const archetypes = [];
  if (score >= 56 && (goodsTags.has("ecology_product") || goodsTags.has("spirit_crafted"))) archetypes.push("pilgrim");
  if (score >= 72 && goodsTags.has("route_rare")) archetypes.push("collector");
  if (comboIds.has("eco_flower_guest_yard") || comboIds.has("eco_honey_orchard")) archetypes.push("guest");
  if (comboIds.has("eco_cloud_warehouse")) archetypes.push("trader");
  if (comboIds.has("eco_book_order_room") || comboIds.has("eco_rain_herb_garden")) archetypes.push("faction");
  return [...new Set(archetypes)];
}

function ecologyCustomerVisitBias(customer, ecologyGarden = ecologyCourtyardSummary(), goods = sellableInventoryGoods()) {
  const score = Number(ecologyGarden.score || ecologyGarden.scoreBreakdown?.total || 0);
  if (score <= 0) return 0;
  const unlockCondition = customerProfile(customer).unlock_condition_group || "";
  if (unlockCondition && !conditionMet(unlockCondition)) return 0;
  const comboIds = new Set([...(ecologyGarden.claimedCombos || []), ...(ecologyGarden.activeCombos || [])].map((combo) => combo.comboId).filter(Boolean));
  const goodsTags = new Set(goods.flatMap(({ itemId, item }) => shopTagsForItem(item || itemId, ecologyGarden)));

  if (customer.archetype === "pilgrim") {
    if (!goodsTags.has("ecology_product") && !goodsTags.has("spirit_crafted")) return score >= 72 ? 0.12 : 0;
    return score >= 88 ? 0.9 : score >= 72 ? 0.55 : score >= 56 ? 0.28 : 0.08;
  }
  if (customer.archetype === "collector") {
    if (!goodsTags.has("route_rare") && !goodsTags.has("spirit_crafted")) return score >= 88 ? 0.12 : 0;
    return score >= 88 ? 0.78 : score >= 72 ? 0.38 : 0.14;
  }
  if (customer.archetype === "guest") {
    if (comboIds.has("eco_flower_guest_yard")) return score >= 88 ? 0.45 : 0.24;
    if (comboIds.has("eco_honey_orchard")) return 0.18;
    return 0;
  }
  if (customer.archetype === "trader") return comboIds.has("eco_cloud_warehouse") ? 0.18 : 0;
  if (customer.archetype === "faction") return comboIds.has("eco_book_order_room") ? 0.14 : comboIds.has("eco_rain_herb_garden") ? 0.08 : 0;
  return 0;
}

function ecologyCustomerVisitCapacity(ecologyGarden = ecologyCourtyardSummary()) {
  const score = Number(ecologyGarden.score || ecologyGarden.scoreBreakdown?.total || 0);
  if (score >= 88) return 2;
  if (score >= 72) return 1;
  return 0;
}

function activeEcologyShopAura(day = state.day, ecologyGarden = ecologyCourtyardSummary(), goods = sellableInventoryGoods()) {
  const ecologyState = syncEcologyDailyState();
  const last = ecologyState.last;
  if (!last || Number(last.day || 0) !== Number(day || state.day)) return null;
  const comboId = last.comboId || "";
  const profile = ecologyCommodityProfile(comboId);
  const matchingGoods = goods.filter(({ itemId, item }) => ecologyTagMatchesCombo(shopTagsForItem(item || itemId, ecologyGarden), comboId, itemId));
  const inspectionCareActive = Boolean(last.inspectionCare?.active);
  const score = Number(ecologyGarden.score || ecologyGarden.scoreBreakdown?.total || last.score || 0);
  const focusTags = profile.tags.slice(0, 4);
  const preferredArchetypes = [...new Set(profile.shopArchetypes || [])];
  const visitorBonus = Math.min(1, (preferredArchetypes.length > 0 && (matchingGoods.length > 0 || score >= 72)) ? 1 : 0);
  const budgetBonus = Math.min(0.08, 0.03 + (matchingGoods.length > 0 ? 0.02 : 0) + (inspectionCareActive ? 0.02 : 0) + (score >= 88 ? 0.01 : 0));
  const title = last.title || "庭院夜息";
  return {
    active: true,
    day,
    comboId,
    comboName: last.comboName || "生态庭院",
    title,
    focusText: profile.focusText,
    auraText: profile.auraText,
    focusTags,
    preferredArchetypes,
    visitorBonus,
    budgetBonus,
    matchingGoodCount: matchingGoods.length,
    matchedGoodsText: matchingGoods.slice(0, 2).map(({ itemId }) => itemName(itemId)).join(" / "),
    inspectionCareActive,
    inspectionSummary: last.inspectionCare?.summary || "",
    summary: `${title}留下的余韵偏向${profile.focusText}，今日开铺会轻轻牵动${preferredArchetypes.slice(0, 2).map(customerDisplayName).join(" / ") || "懂货客"}。`,
  };
}

function ecologyShopAuraCustomerBias(customer, ecologyShopAura = activeEcologyShopAura()) {
  if (!ecologyShopAura?.active || !customer) return 0;
  if (!ecologyShopAura.preferredArchetypes?.includes(customer.archetype)) return 0;
  return ecologyShopAura.matchingGoodCount > 0 ? 0.32 : 0.16;
}

function ecologyShopAuraBudgetBonus(customerView, choice, ecologyShopAura = activeEcologyShopAura(), ecologyGarden = ecologyCourtyardSummary()) {
  if (!ecologyShopAura?.active || !customerView || !choice) return 0;
  const archetypeMatch = ecologyShopAura.preferredArchetypes?.includes(customerView.archetype);
  const itemTags = shopTagsForItem(choice.item || choice.itemId, ecologyGarden);
  const goodsMatch = ecologyTagMatchesCombo(itemTags, ecologyShopAura.comboId, choice.itemId || "");
  if (!archetypeMatch && !goodsMatch) return 0;
  return ecologyShopAura.budgetBonus * (archetypeMatch && goodsMatch ? 1 : 0.55);
}

function ecologyShopAuraPurchaseNote(customer, choice, ecologyShopAura = activeEcologyShopAura(), ecologyGarden = ecologyCourtyardSummary()) {
  const bonus = ecologyShopAuraBudgetBonus(customer, choice, ecologyShopAura, ecologyGarden);
  if (!bonus) return "";
  return `${ecologyShopAura.title}的庭院夜事余韵让${customerDisplayName(customer.archetype)}多看了${itemName(choice.itemId)}一眼`;
}

function ecologyVisitorMixSummary(customers = [], ecologyGarden = ecologyCourtyardSummary(), goods = sellableInventoryGoods()) {
  const focusArchetypes = ecologyVisitorFocusArchetypes(ecologyGarden, goods);
  if (!focusArchetypes.length) return null;
  const focusSet = new Set(focusArchetypes);
  const counts = customers.reduce((acc, customer) => {
    if (!focusSet.has(customer.archetype)) return acc;
    acc[customer.archetype] = Number(acc[customer.archetype] || 0) + 1;
    return acc;
  }, {});
  const lines = Object.entries(counts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 3)
    .map(([archetype, count]) => `${count} 位${customerDisplayName(archetype)}`);
  if (!lines.length) return null;
  const activeScenes = (ecologyGarden.sceneRows || []).slice(0, 2).map((row) => row.name).join(" / ");
  const goodsText = ["ecology_product", "spirit_crafted", "route_rare"].filter((tag) => goods.some(({ itemId, item }) => shopTagsForItem(item || itemId, ecologyGarden).includes(tag))).map(shopTagLabel).join(" / ");
  return {
    headline: `${ecologyGarden.tier.label}来客`,
    text: `${ecologyGarden.tier.label}把 ${lines.join(" / ")} 引到了门前。`,
    detail: `${activeScenes || "庭院造景"} 正在替你招呼更能看懂 ${goodsText || "洞天气息"} 的客群。`,
  };
}

