function drawWorkshopLineFeedback(ctx, width, height, feedback = activeWorkshopLineFeedback()) {
  if (!feedback || state.activeCutscene || state.activeDialogue.length > 0) return;
  const age = Number(feedback.age || 0);
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const p = settings.reducedMotion ? 1 : Math.min(1, age / 1300);
  const accent = feedback.accent || "#b47d2f";
  const route = [
    { x: 804, y: 434 },
    { x: 708, y: 470 },
    { x: 618, y: 502 },
    { x: 520, y: 522 },
    { x: 404, y: 470 },
    { x: 290, y: 398 },
  ];
  const orderPoint = { x: 692, y: 418 };
  const targetPoint = feedback.kind === "order_ready" || feedback.kind === "order_pending" ? orderPoint : route[route.length - 1];
  const current = feedback.kind === "queued"
    ? { x: 804 + Math.sin(p * Math.PI) * 26, y: 434 - Math.sin(p * Math.PI) * 24 }
    : pointOnPolyline([...route.slice(0, -1), targetPoint], p);

  ctx.save();
  ctx.globalAlpha = feedback.fade;
  ctx.strokeStyle = `${accent}88`;
  ctx.lineWidth = 5;
  ctx.lineCap = "round";
  ctx.setLineDash([14, 10]);
  ctx.lineDashOffset = settings.reducedMotion ? 0 : -motion * 32;
  ctx.beginPath();
  if (feedback.kind === "queued") {
    ctx.moveTo(774, 458);
    ctx.quadraticCurveTo(812, 384, 858, 438);
  } else {
    route.forEach((point, index) => {
      if (index === 0) ctx.moveTo(point.x, point.y);
      else if (index < route.length - 1) ctx.lineTo(point.x, point.y);
    });
    ctx.lineTo(targetPoint.x, targetPoint.y);
  }
  ctx.stroke();
  ctx.setLineDash([]);

  const glow = ctx.createRadialGradient(current.x, current.y, 8, current.x, current.y, 78);
  glow.addColorStop(0, "rgba(246, 240, 182, 0.48)");
  glow.addColorStop(0.55, `${accent}33`);
  glow.addColorStop(1, "rgba(246, 240, 182, 0)");
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(current.x, current.y, 78, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = "#8f5f3f";
  ctx.beginPath();
  ctx.roundRect(current.x - 22, current.y - 14, 44, 28, 8);
  ctx.fill();
  ctx.fillStyle = feedback.kind === "queued" ? "#be4f37" : accent;
  ctx.beginPath();
  ctx.roundRect(current.x - 14, current.y - 25, 28, 18, 7);
  ctx.fill();
  ctx.fillStyle = "#fffdf5";
  ctx.font = "700 10px Microsoft YaHei";
  ctx.fillText(feedback.kind === "queued" ? "上灶" : "出锅", current.x - 11, current.y - 12);

  if (!settings.reducedMotion) {
    for (let i = 0; i < 7; i += 1) {
      const t = (p + i * 0.12) % 1;
      const mote = feedback.kind === "queued"
        ? { x: 800 + Math.cos(t * Math.PI * 2) * 34, y: 426 + Math.sin(t * Math.PI * 2) * 20 }
        : pointOnPolyline([...route.slice(0, -1), targetPoint], t);
      ctx.fillStyle = i % 2 ? "rgba(255, 248, 232, 0.72)" : "rgba(246, 240, 182, 0.68)";
      ctx.beginPath();
      ctx.arc(mote.x, mote.y - i * 1.5, 2.6, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  const cardX = Math.max(34, Math.min(width - 330, current.x - 156));
  const cardY = Math.max(96, Math.min(height - 132, current.y - 112));
  drawCanvasCard(ctx, cardX, cardY, 306, 104, "rgba(255, 248, 232, 0.95)");
  ctx.fillStyle = `${accent}22`;
  ctx.beginPath();
  ctx.roundRect(cardX + 18, cardY + 18, 54, 58, 16);
  ctx.fill();
  ctx.fillStyle = accent;
  ctx.font = "700 24px Microsoft YaHei";
  ctx.fillText(feedback.kind === "queued" ? "灶" : feedback.orderMatch?.ready ? "单" : "香", cardX + 32, cardY + 56);
  ctx.font = "700 12px Microsoft YaHei";
  ctx.fillText("工坊产线回声", cardX + 88, cardY + 28);
  ctx.fillStyle = "#17231d";
  ctx.font = "700 17px Microsoft YaHei";
  ctx.fillText(feedback.title.slice(0, 16), cardX + 88, cardY + 52);
  ctx.fillStyle = "#8f5f3f";
  ctx.font = "700 12px Microsoft YaHei";
  ctx.fillText(`${feedback.outputItemName} x${feedback.outputCount} · ${feedback.verb}`.slice(0, 25), cardX + 88, cardY + 74);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "11px Microsoft YaHei";
  ctx.fillText((feedback.orderMatch ? `${feedback.orderMatch.orderTitle} · ${feedback.detail}` : feedback.detail).slice(0, 34), cardX + 20, cardY + 94);
  ctx.restore();
}

