function drawShopFirstSaleReceipt(ctx, spec = shopFirstSaleReceiptWorldSpec(), motion = 0) {
  if (!spec) return;
  const { rect } = spec;
  const pulse = settings.reducedMotion ? 0 : Math.sin(motion * 2.2) * 2;
  ctx.save();
  ctx.fillStyle = "rgba(23, 35, 29, 0.14)";
  ctx.beginPath();
  ctx.ellipse(rect.x + rect.width * 0.5, rect.y + rect.height + 7, rect.width * 0.42, 8, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "rgba(255, 248, 232, 0.95)";
  ctx.strokeStyle = "rgba(224, 182, 109, 0.56)";
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.roundRect(rect.x, rect.y + pulse, rect.width, rect.height, 14);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = "rgba(224, 182, 109, 0.18)";
  ctx.beginPath();
  ctx.arc(rect.x + 24, rect.y + 22 + pulse, 16, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "#b47d2f";
  ctx.font = "900 15px Microsoft YaHei";
  ctx.fillText("单", rect.x + 16, rect.y + 28 + pulse);
  ctx.fillStyle = "#286f58";
  ctx.font = "800 11px Microsoft YaHei";
  ctx.fillText("首单成交 · 可点", rect.x + 48, rect.y + 21 + pulse);
  ctx.fillStyle = "#17231d";
  ctx.font = "700 12px Microsoft YaHei";
  ctx.fillText(`${spec.customerName} 买走 ${spec.itemName}`.slice(0, 18), rect.x + 48, rect.y + 40 + pulse);
  ctx.fillStyle = "#8f5f3f";
  ctx.font = "11px Microsoft YaHei";
  ctx.fillText(`为什么买：${spec.reasonText}`.slice(0, 31), rect.x + 14, rect.y + 59 + pulse);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "10px Microsoft YaHei";
  ctx.fillText(`顾客短评：${spec.reviewQuote}`.slice(0, 31), rect.x + 14, rect.y + 75 + pulse);
  if (spec.returnPreview) {
    const accent = spec.returnTone === "good" ? "#286f58" : spec.returnTone === "mid" ? "#b47d2f" : "#8f5f3f";
    ctx.fillStyle = spec.returnTone === "good" ? "rgba(40, 111, 88, 0.12)" : "rgba(224, 182, 109, 0.16)";
    ctx.beginPath();
    ctx.roundRect(rect.x + 12, rect.y + 84 + pulse, rect.width - 24, 24, 11);
    ctx.fill();
    ctx.fillStyle = accent;
    ctx.font = "800 10px Microsoft YaHei";
    ctx.fillText(`回头苗头 ${spec.returnChance}% · ${spec.returnSummary || "明日认门"}`.slice(0, 28), rect.x + 22, rect.y + 100 + pulse);
    ctx.fillStyle = "#5d6f65";
    ctx.font = "9px Microsoft YaHei";
    ctx.fillText((spec.returnCta || "明天继续补同类货").slice(0, 30), rect.x + 18, rect.y + 115 + pulse);
  }
  if (spec.price > 0) {
    ctx.fillStyle = "#b47d2f";
    ctx.font = "800 10px Microsoft YaHei";
    ctx.fillText(`+${spec.price}`, rect.x + rect.width - 42, rect.y + 21 + pulse);
  }
  ctx.restore();
}

function drawShopCourtyardActivity(ctx, livingState) {
  const theme = livingState.shopTheme;
  const displayDiagnosis = shopDisplayDiagnosisSpec(sellableInventoryGoods(), theme, data.customers, livingState.ecologyGarden);
  const compendiumDisplays = activeShopCompendiumDisplays(sellableInventoryGoods(), theme, 2);
  const solarMoodDisplay = solarTermMoodShopDisplaySpec();
  const ecologyShopAura = activeEcologyShopAura(state.day, livingState.ecologyGarden, sellableInventoryGoods());
  const qingboSignatureAura = qingboWaterFreshSignatureAura(sellableInventoryGoods(), theme);
  const crowdHeat = shopCrowdHeatSpec();
  const journeySpec = shopCustomerJourneySpec();
  const leaveRecovery = shopLeaveRecoveryWorldSpec(normalizeShopOpeningState(state.shopOpeningState));
  const doorstepVignette = shopDoorstepCustomerVignetteSpec(normalizeShopOpeningState(state.shopOpeningState), journeySpec);
  const restockTarget = normalizeShopOpeningState(state.shopOpeningState).restockTarget;
  const actionFeedback = activeShopActionFeedback();
  const reputationStage = livingState.shopReputationStage || shopReputationStageSpec();
  const careChainEcho = livingState.careChainEcho || careChainEchoSpec(livingState.careChainStage || state.careChainState);
  const weatherShelf = shopWeatherShelfRecommendationSpec();
  const weatherShelfCustomer = shopWeatherShelfCustomerVignetteSpec(weatherShelf);
  const forecastBoard = shopCustomerForecastWorldSpec(
    normalizeShopOpeningState(state.shopOpeningState),
    sellableInventoryGoods(),
    displayDiagnosis,
    shopWeatherCustomerReactionSpec({ opening: normalizeShopOpeningState(state.shopOpeningState) }),
    weatherShelf,
    journeySpec,
  );
  const waterwayBrokerScene = shopWaterwayBrokerSceneSpec();
  const waterwayShelfSpotlight = shopWaterwayShelfSpotlightSpec(sellableInventoryGoods(), theme, waterwayBrokerScene);
  const waterwayBrowse = shopWaterwayCustomerBrowseSpec(normalizeShopOpeningState(state.shopOpeningState), state.shopReport, waterwayShelfSpotlight);
  const waterwayReorderFollowupScene = shopWaterwayReorderFollowupSceneSpec(normalizeShopOpeningState(state.shopOpeningState), state.shopReport, waterwayReorderFollowupSpec(sellableInventoryGoods(), theme));
  const waterwayStandingOrderSupply = waterwayStandingOrderSupplySpec(sellableInventoryGoods(), theme);
  const returningTrail = shopReturningTrailWorldSpec(normalizeShopOpeningState(state.shopOpeningState));
  if (livingState.shopSpirits <= 0 && state.shopReport.length === 0 && compendiumDisplays.length === 0 && !solarMoodDisplay && !ecologyShopAura && !qingboSignatureAura && !crowdHeat.active && !journeySpec.active && !leaveRecovery && !doorstepVignette.active && !waterwayBrokerScene?.active && !waterwayShelfSpotlight?.active && !waterwayBrowse?.active && !waterwayReorderFollowupScene?.active && !waterwayStandingOrderSupply?.active && !returningTrail && !restockTarget && !actionFeedback && !displayDiagnosis.active && !weatherShelf?.active && !weatherShelfCustomer.active && !forecastBoard?.active && !(reputationStage?.progressCount > 0) && !careChainEcho) return;
  const palette = {
    fresh_market: "#7ba66c",
    clean_herb: "#9fd1df",
    forge_supply: "#b47d2f",
    road_pack: "#e0b66d",
    gift_banquet: "#d87f8d",
    ritual_batch: "#8c7ab8",
    relief_support: "#5d8b52",
  };
  const color = palette[theme?.theme_tag] || "#7ba66c";
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  ctx.save();
  drawEcologyShopAuraAtShop(ctx, ecologyShopAura, motion);
  drawQingboWaterFreshSignatureSign(ctx, qingboSignatureAura, motion);
  drawShopReputationStageSign(ctx, livingState, motion);
  drawCareChainShopEcho(ctx, livingState, motion);
  drawShopDoorstepCustomerVignette(ctx, doorstepVignette, motion);
  drawShopWaterwayBrokerScene(ctx, waterwayBrokerScene, motion);
  drawShopWaterwayShelfSpotlight(ctx, waterwayShelfSpotlight, motion);
  drawShopWaterwayCustomerBrowse(ctx, waterwayBrowse, motion);
  drawShopWaterwayReorderFollowupScene(ctx, waterwayReorderFollowupScene, motion);
  drawShopWaterwayStandingOrderSupplyScene(ctx, waterwayStandingOrderSupply, motion);
  drawShopWeatherShelfSign(ctx, weatherShelf, motion);
  drawShopWeatherShelfCustomerVignette(ctx, weatherShelfCustomer, motion);
  drawShopDailyGoodsEyeWorld(ctx, shopDailyGoodsEyeWorldSpec(ctx.canvas.width, ctx.canvas.height), motion);
  drawShopCustomerPickShadowWorld(ctx, shopCustomerPickShadowWorldSpec(ctx.canvas.width, ctx.canvas.height), motion);
  drawShopSpiritGreeterWorld(ctx, shopSpiritGreeterWorldSpec(ctx.canvas.width, ctx.canvas.height, livingState), motion);
  drawShopShelfPrepWorldBoard(ctx, shopShelfPrepWorldBoardSpec(ctx.canvas.width, ctx.canvas.height), motion);
  drawShopRestockRunnerWorld(ctx, shopRestockRunnerWorldSpec(ctx.canvas.width, ctx.canvas.height), motion);
  drawShopCustomerForecastWorldBoard(ctx, forecastBoard, motion);
  drawShopWeatherShelfActionEcho(ctx, actionFeedback, motion);
  drawShopCustomerJourneyBoard(ctx, journeySpec, motion);
  drawShopLeaveRecoveryWorldNote(ctx, leaveRecovery, motion);
  ctx.strokeStyle = color;
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(82, 220);
  ctx.bezierCurveTo(126, 198, 176, 202, 214, 226);
  ctx.stroke();
  for (let i = 0; i < 4; i += 1) {
    const x = 96 + i * 30;
    ctx.fillStyle = i % 2 ? color : "#fffdf5";
    ctx.beginPath();
    ctx.moveTo(x, 220);
    ctx.lineTo(x + 14, 242);
    ctx.lineTo(x + 28, 220);
    ctx.closePath();
    ctx.fill();
  }
  if (state.completedRareSpiritEvents.has("rsea_002")) {
    for (let i = 0; i < 6; i += 1) {
      const petalX = 94 + i * 24 + Math.sin(motion + i) * 6;
      const petalY = 208 + (i % 2) * 12 + Math.cos(motion * 1.2 + i) * 4;
      ctx.fillStyle = i % 2 ? "rgba(216, 127, 141, 0.88)" : "rgba(242, 210, 139, 0.82)";
      ctx.beginPath();
      ctx.ellipse(petalX, petalY, 7, 4, motion + i * 0.2, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  if (state.completedRareSpiritEvents.has("rsea_012")) {
    for (let i = 0; i < 3; i += 1) {
      const poleX = 102 + i * 46;
      ctx.strokeStyle = "#8f5f3f";
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(poleX, 186);
      ctx.lineTo(poleX, 236);
      ctx.stroke();
      ctx.fillStyle = i % 2 ? "rgba(216, 127, 141, 0.84)" : "rgba(242, 210, 139, 0.84)";
      ctx.beginPath();
      ctx.moveTo(poleX, 188);
      ctx.lineTo(poleX + 22, 194 + Math.sin(motion * 1.4 + i) * 4);
      ctx.lineTo(poleX, 202);
      ctx.closePath();
      ctx.fill();
    }
    for (let i = 0; i < 3; i += 1) {
      const guestX = 214 + i * 28;
      const guestY = 246 + (i % 2) * 10 + Math.sin(motion + i * 0.8) * 2;
      ctx.fillStyle = "rgba(23, 35, 29, 0.16)";
      ctx.beginPath();
      ctx.arc(guestX, guestY + 16, 11, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = i === 1 ? "rgba(242, 210, 139, 0.7)" : "rgba(255, 253, 245, 0.66)";
      ctx.beginPath();
      ctx.arc(guestX, guestY - 2, 6, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = i === 1 ? "rgba(216, 127, 141, 0.74)" : "rgba(143, 95, 63, 0.68)";
      ctx.beginPath();
      ctx.moveTo(guestX - 8, guestY + 10);
      ctx.lineTo(guestX + 8, guestY + 10);
      ctx.lineTo(guestX + 12, guestY + 28);
      ctx.lineTo(guestX - 12, guestY + 28);
      ctx.closePath();
      ctx.fill();
    }
  }
  if (state.completedRareSpiritEvents.has("rsea_009")) {
    for (let i = 0; i < 4; i += 1) {
      const pageX = 118 + i * 26 + Math.sin(motion * 1.1 + i) * 4;
      const pageY = 248 + (i % 2) * 10 + Math.cos(motion + i * 0.7) * 3;
      ctx.fillStyle = "rgba(255, 253, 245, 0.9)";
      ctx.beginPath();
      ctx.roundRect(pageX, pageY, 16, 22, 4);
      ctx.fill();
      ctx.strokeStyle = "rgba(143, 95, 63, 0.72)";
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.fillStyle = i % 2 ? "rgba(143, 95, 63, 0.7)" : "rgba(23, 35, 29, 0.56)";
      ctx.fillRect(pageX + 4, pageY + 6, 8, 2);
      ctx.fillRect(pageX + 4, pageY + 11, 8, 2);
      ctx.fillRect(pageX + 4, pageY + 16, 6, 2);
    }
  }
  if (state.completedRareSpiritEvents.has("rsea_013")) {
    const lowStockGoods = shuqiLowStockGoods();
    const tagCount = Math.max(2, Math.min(4, lowStockGoods.length || 2));
    for (let i = 0; i < tagCount; i += 1) {
      const tagX = 224 + i * 26;
      const tagY = 190 + (i % 2) * 18 + Math.sin(motion * 1.3 + i * 0.5) * 4;
      ctx.strokeStyle = lowStockGoods.length > 0 ? "rgba(190, 79, 55, 0.58)" : "rgba(224, 182, 109, 0.58)";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(tagX, 176);
      ctx.lineTo(tagX + 2, tagY);
      ctx.stroke();
      ctx.fillStyle = lowStockGoods[i] ? "rgba(239, 217, 208, 0.94)" : "rgba(255, 246, 215, 0.92)";
      ctx.beginPath();
      ctx.roundRect(tagX - 8, tagY, 18, 24, 4);
      ctx.fill();
      ctx.strokeStyle = "rgba(143, 95, 63, 0.7)";
      ctx.stroke();
      ctx.fillStyle = lowStockGoods[i] ? "rgba(190, 79, 55, 0.82)" : "rgba(143, 95, 63, 0.72)";
      ctx.fillRect(tagX - 3, tagY + 6, 8, 2);
      ctx.fillRect(tagX - 3, tagY + 11, 8, 2);
      ctx.fillRect(tagX - 3, tagY + 16, 6, 2);
    }
  }
  if (state.completedRareSpiritEvents.has("rsea_014")) {
    ctx.fillStyle = "rgba(224, 182, 109, 0.86)";
    ctx.beginPath();
    ctx.roundRect(176, 232, 42, 28, 6);
    ctx.fill();
    ctx.strokeStyle = "rgba(143, 95, 63, 0.72)";
    ctx.lineWidth = 2;
    ctx.stroke();
    for (let i = 0; i < 3; i += 1) {
      const sparkX = 184 + i * 12 + Math.sin(motion * 1.4 + i) * 2;
      const sparkY = 224 + Math.cos(motion + i * 0.7) * 4;
      ctx.fillStyle = "rgba(255, 253, 245, 0.88)";
      ctx.beginPath();
      ctx.arc(sparkX, sparkY, 3, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  if (state.completedRareSpiritEvents.has("rsea_015")) {
    for (let i = 0; i < 3; i += 1) {
      const jarX = 254 + i * 24;
      const jarBob = Math.sin(motion * 1.2 + i * 0.8) * 2;
      ctx.fillStyle = i === 1 ? "rgba(224, 182, 109, 0.92)" : "rgba(242, 210, 139, 0.88)";
      ctx.beginPath();
      ctx.roundRect(jarX, 218 + jarBob, 16, 24, 5);
      ctx.fill();
      ctx.strokeStyle = "rgba(143, 95, 63, 0.72)";
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.fillStyle = "rgba(255, 253, 245, 0.78)";
      ctx.fillRect(jarX + 4, 224 + jarBob, 8, 5);
    }
  }
  if (state.completedRareSpiritEvents.has("rsea_016")) {
    ctx.fillStyle = "rgba(255, 244, 216, 0.9)";
    ctx.beginPath();
    ctx.ellipse(310, 230, 44, 18, 0, 0, Math.PI * 2);
    ctx.fill();
    for (let i = 0; i < 4; i += 1) {
      const cupX = 284 + i * 16;
      const cupY = 222 + (i % 2) * 8 + Math.cos(motion * 1.4 + i) * 2;
      ctx.fillStyle = "rgba(224, 182, 109, 0.92)";
      ctx.beginPath();
      ctx.arc(cupX, cupY, 5, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = "rgba(255, 253, 245, 0.84)";
      ctx.beginPath();
      ctx.arc(cupX, cupY - 1, 2, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  const liveFocus = normalizeShopOpeningState(state.shopOpeningState).liveFocus;
  if (liveFocus) {
    drawShopCrowdHeat(ctx, livingState, motion);
    drawShopCustomerJourneyTrace(ctx, journeySpec, motion);
    ctx.fillStyle = "rgba(255, 253, 245, 0.9)";
    ctx.beginPath();
    ctx.roundRect(52, 258, 146, 74, 14);
    ctx.fill();
    ctx.strokeStyle = "rgba(40, 111, 88, 0.22)";
    ctx.lineWidth = 2;
    ctx.stroke();
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.roundRect(68, 286, 40, 20, 6);
    ctx.fill();
    ctx.fillStyle = "rgba(255, 253, 245, 0.9)";
    ctx.fillRect(74, 292, 28, 3);
    ctx.fillStyle = "#17231d";
    ctx.font = "700 12px Microsoft YaHei";
    ctx.fillText(liveFocus.topItemName ? liveFocus.topItemName.slice(0, 6) : liveFocus.hotTagLabel, 116, 282);
    ctx.fillStyle = "#286f58";
    ctx.font = "12px Microsoft YaHei";
    ctx.fillText(`成交 ${liveFocus.buyers} · 离店 ${liveFocus.leavers}`, 116, 302);
    ctx.fillStyle = liveFocus.topBlocker ? "#be4f37" : "#8f5f3f";
    ctx.fillText(liveFocus.topBlockerLabel, 116, 322);
    drawShopWaterwayShelfSpotlight(ctx, waterwayShelfSpotlight, motion);
  }
  drawShopFirstSaleReceipt(ctx, shopFirstSaleReceiptWorldSpec(normalizeShopOpeningState(state.shopOpeningState)), motion);
  drawShopFirstSaleLessonWorld(ctx, shopFirstSaleLessonWorldSpec(normalizeShopOpeningState(state.shopOpeningState)), motion);
  drawShopReturningTrailWorld(ctx, returningTrail, motion);

  compendiumDisplays.forEach((display, index) => {
    drawShopCompendiumDisplayMotif(ctx, display, 132 + index * 42, 258 + (index % 2) * 4, index, motion);
  });
  drawSolarTermMoodShopDisplayWorld(ctx, solarTermMoodShopDisplayWorldSpec(solarMoodDisplay), motion);
  drawCompendiumDisplayAudience(ctx, compendiumDisplays, motion);

  if (livingState.shopSpirits > 0) {
    const restockPath = [
      { x: 244, y: 298 },
      { x: 218, y: 264 },
      { x: 184, y: 236 },
      { x: 154, y: 210 },
    ];
    ctx.strokeStyle = "rgba(180, 125, 47, 0.34)";
    ctx.lineWidth = 4;
    ctx.setLineDash([8, 10]);
    ctx.lineDashOffset = settings.reducedMotion ? 0 : -motion * 16;
    ctx.beginPath();
    restockPath.forEach((routePoint, routeIndex) => {
      if (routeIndex === 0) ctx.moveTo(routePoint.x, routePoint.y);
      else ctx.lineTo(routePoint.x, routePoint.y);
    });
    ctx.stroke();
    ctx.setLineDash([]);
    const runnerCount = Math.min(3, Math.max(1, livingState.shopSpirits));
    for (let runner = 0; runner < runnerCount; runner += 1) {
      const point = pointOnPolyline(restockPath, ((motion * 0.2) + runner * 0.28) % 1);
      const bob = Math.sin(motion * 4 + runner) * (settings.reducedMotion ? 0 : 2);
    ctx.fillStyle = "#fff6d7";
    ctx.beginPath();
      ctx.arc(point.x, point.y + bob, 14, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#286f58";
      ctx.fillRect(point.x - 10, point.y + 8 + bob, 20, 10);
    ctx.fillStyle = "#8f5f3f";
      ctx.fillRect(point.x + 8, point.y - 4 + bob, 12, 10);
      ctx.fillStyle = runner % 2 ? "rgba(246, 240, 182, 0.82)" : "rgba(224, 182, 109, 0.82)";
      ctx.beginPath();
      ctx.roundRect(point.x + 15, point.y + 6 + bob, 14, 11, 4);
      ctx.fill();
    }
    ctx.fillStyle = "rgba(255, 248, 232, 0.9)";
    ctx.beginPath();
    ctx.roundRect(152, 184, 104, 26, 11);
    ctx.fill();
    ctx.fillStyle = "#b47d2f";
    ctx.font = "700 11px Microsoft YaHei";
    ctx.fillText("补货跑动 · 货架接上", 164, 201);
  }

  if (state.shopReport.length > 0) {
    ctx.fillStyle = "rgba(255, 248, 232, 0.88)";
    ctx.beginPath();
    ctx.roundRect(224, 250, 146, 26, 12);
    ctx.fill();
    ctx.fillStyle = "#17231d";
    ctx.font = "700 12px Microsoft YaHei";
    ctx.fillText(theme?.note || "旧铺主题陈列", 236, 268);
  }
  drawShopDisplayDiagnosisSign(ctx, displayDiagnosis, motion);
  drawShopRestockTargetSign(ctx, restockTarget, motion);
  ctx.restore();
}

function drawShopDisplayDiagnosisSign(ctx, spec = shopDisplayDiagnosisSpec(), motion = 0) {
  if (!spec?.active) return;
  const x = 56;
  const y = 186;
  const w = 158;
  const h = 66;
  const pulse = settings.reducedMotion ? 0 : Math.sin(motion * 2.1) * 2;
  const accent = spec.tone === "warn" ? "#be4f37" : spec.tone === "good" ? "#286f58" : "#b47d2f";
  const feature = spec.featuredGoods[0];
  ctx.save();
  ctx.fillStyle = "rgba(255, 248, 232, 0.92)";
  ctx.strokeStyle = spec.tone === "warn" ? "rgba(190, 79, 55, 0.58)" : "rgba(40, 111, 88, 0.36)";
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.roundRect(x, y + pulse, w, h, 14);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = accent;
  ctx.font = "700 12px Microsoft YaHei";
  ctx.fillText("货架陈列", x + 14, y + 20 + pulse);
  ctx.fillStyle = "#17231d";
  ctx.font = "700 12px Microsoft YaHei";
  ctx.fillText(`主题 ${spec.themeScore}% · ${spec.hotTagLabel}`.slice(0, 15), x + 14, y + 39 + pulse);
  ctx.fillStyle = accent;
  ctx.font = "11px Microsoft YaHei";
  ctx.fillText(`主推 ${feature ? feature.itemName : "可卖货"}`.slice(0, 16), x + 14, y + 56 + pulse);
  ctx.fillStyle = spec.tone === "warn" ? "rgba(190, 79, 55, 0.14)" : "rgba(224, 182, 109, 0.2)";
  ctx.beginPath();
  ctx.arc(x + w - 22, y + 22 + pulse, 13, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = accent;
  ctx.font = "700 11px Microsoft YaHei";
  ctx.fillText(spec.tone === "warn" ? "调" : "推", x + w - 28, y + 26 + pulse);
  ctx.restore();
}

function drawShopRestockTargetSign(ctx, target = normalizeShopOpeningState(state.shopOpeningState).restockTarget, motion = 0) {
  if (!target || target.status !== "active") return;
  const have = target.itemId ? Number(state.inventory[target.itemId] || 0) : sellableInventoryGoods().length;
  const ready = shopRestockTargetReady(target);
  const overdue = state.day > target.dueDay;
  const waterFresh = shopRestockTargetIsWaterFresh(target);
  const waterwayReorder = target.source === "lianze_waterway_reorder";
  const pulse = settings.reducedMotion ? 0 : Math.sin(motion * 2.2) * 2;
  const x = 220;
  const y = 278;
  const w = 168;
  const h = 76;
  ctx.save();
  ctx.fillStyle = waterFresh
    ? ready
      ? "rgba(226, 244, 238, 0.95)"
      : "rgba(226, 241, 247, 0.94)"
    : ready
    ? "rgba(237, 243, 223, 0.94)"
    : overdue
      ? "rgba(255, 240, 232, 0.94)"
      : "rgba(255, 248, 232, 0.94)";
  ctx.strokeStyle = waterFresh ? "rgba(77, 145, 166, 0.62)" : ready ? "rgba(40, 111, 88, 0.58)" : overdue ? "rgba(190, 79, 55, 0.58)" : "rgba(180, 125, 47, 0.5)";
  ctx.lineWidth = ready ? 3 : 2;
  ctx.beginPath();
  ctx.roundRect(x, y + pulse, w, h, 14);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = waterFresh ? "#4d91a6" : ready ? "#286f58" : overdue ? "#be4f37" : "#8f5f3f";
  ctx.font = "700 12px Microsoft YaHei";
  ctx.fillText(ready ? "补货可完成" : overdue ? "补货逾期" : waterwayReorder ? "水航回订" : waterFresh ? "水鲜补货" : "补货追踪", x + 14, y + 20 + pulse);
  ctx.fillStyle = "#17231d";
  ctx.font = "700 13px Microsoft YaHei";
  ctx.fillText(target.itemName.slice(0, 8), x + 14, y + 40 + pulse);
  ctx.fillStyle = waterFresh ? "#4d91a6" : ready ? "#286f58" : overdue ? "#be4f37" : "#8f5f3f";
  ctx.font = "12px Microsoft YaHei";
  ctx.fillText(`${have}/${target.desiredCount} · 第${target.dueDay}天`, x + 14, y + 60 + pulse);
  ctx.fillStyle = waterFresh ? "rgba(77, 145, 166, 0.18)" : ready ? "rgba(40, 111, 88, 0.18)" : "rgba(180, 125, 47, 0.16)";
  ctx.beginPath();
  ctx.arc(x + w - 22, y + 22 + pulse, ready ? 13 : 10, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = waterFresh ? "#4d91a6" : ready ? "#286f58" : "#8f5f3f";
  ctx.font = "700 11px Microsoft YaHei";
  ctx.fillText(ready ? "成" : waterwayReorder ? "航" : waterFresh ? "鲜" : "货", x + w - 28, y + 26 + pulse);
  ctx.restore();
}

function drawShopCompendiumDisplayMotif(ctx, display, x, y, index = 0, motion = 0) {
  const pulse = settings.reducedMotion ? 0 : Math.sin(motion * 2.4 + index) * 2;
  const glow = display.entry.cleared ? 8 : 6;
  ctx.save();
  ctx.fillStyle = "rgba(23, 35, 29, 0.12)";
  ctx.beginPath();
  ctx.ellipse(x + 16, y + 20, 20, 6, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = display.palette.card;
  ctx.strokeStyle = display.palette.accent;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.roundRect(x, y - 10, 32, 34, 8);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = display.palette.glow;
  ctx.beginPath();
  ctx.arc(x + 16, y - 2, glow + Math.max(0, pulse), 0, Math.PI * 2);
  ctx.fill();

  ctx.strokeStyle = display.palette.accent;
  ctx.fillStyle = display.palette.accent;
  ctx.lineWidth = 2;
  const motif = display.motif || "seed";
  if (motif === "thunder") {
    ctx.beginPath();
    ctx.moveTo(x + 17, y - 9);
    ctx.lineTo(x + 9, y + 6 + pulse);
    ctx.lineTo(x + 18, y + 5 + pulse);
    ctx.lineTo(x + 13, y + 22);
    ctx.lineTo(x + 25, y + 4);
    ctx.lineTo(x + 17, y + 5);
    ctx.stroke();
  } else if (motif === "water") {
    for (let i = 0; i < 3; i += 1) {
      ctx.beginPath();
      ctx.arc(x + 16, y + 7, 7 + i * 5 + pulse * 0.4, 0.18, Math.PI - 0.18);
      ctx.stroke();
    }
  } else if (motif === "bloom") {
    for (let i = 0; i < 5; i += 1) {
      const angle = (Math.PI * 2 * i) / 5 + motion * 0.2;
      ctx.beginPath();
      ctx.ellipse(x + 16 + Math.cos(angle) * 7, y + 7 + Math.sin(angle) * 5, 4, 7, angle, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.fillStyle = display.palette.glow;
    ctx.beginPath();
    ctx.arc(x + 16, y + 7, 3, 0, Math.PI * 2);
    ctx.fill();
  } else if (motif === "earth") {
    for (let i = 0; i < 3; i += 1) {
      ctx.beginPath();
      ctx.roundRect(x + 7 + i * 6, y + 16 - i * 5, 5, 8 + i * 3, 2);
      ctx.fill();
    }
    ctx.strokeRect(x + 7, y + 16, 18, 4);
  } else if (motif === "moon") {
    ctx.beginPath();
    ctx.arc(x + 18, y + 5, 9, Math.PI * 0.24, Math.PI * 1.78);
    ctx.stroke();
    ctx.fillStyle = "rgba(255, 253, 245, 0.74)";
    ctx.beginPath();
    ctx.arc(x + 21, y + 2, 4, 0, Math.PI * 2);
    ctx.fill();
  } else if (motif === "frost") {
    for (let i = 0; i < 6; i += 1) {
      const angle = (Math.PI * i) / 3;
      ctx.beginPath();
      ctx.moveTo(x + 16, y + 7);
      ctx.lineTo(x + 16 + Math.cos(angle) * (10 + pulse * 0.5), y + 7 + Math.sin(angle) * (10 + pulse * 0.5));
      ctx.stroke();
    }
  } else if (motif === "wind") {
    for (let i = 0; i < 2; i += 1) {
      ctx.beginPath();
      ctx.moveTo(x + 5, y + 5 + i * 8);
      ctx.bezierCurveTo(x + 13, y - 1 + i * 8 + pulse, x + 20, y + 12 + i * 5, x + 28, y + 4 + i * 8);
      ctx.stroke();
    }
  } else if (motif === "lantern") {
    ctx.fillStyle = display.palette.glow;
    ctx.beginPath();
    ctx.roundRect(x + 10, y - 4, 13, 18, 6);
    ctx.fill();
    ctx.strokeRect(x + 10, y - 4, 13, 18);
    ctx.beginPath();
    ctx.moveTo(x + 16, y + 14);
    ctx.lineTo(x + 16, y + 23 + pulse);
    ctx.stroke();
  } else {
    ctx.beginPath();
    ctx.ellipse(x + 16, y + 8, 6, 11, 0, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.ellipse(x + 21, y + 4, 5, 3, -0.5, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.fillStyle = "rgba(143, 95, 63, 0.78)";
  ctx.font = "9px Microsoft YaHei";
  ctx.fillText(index === 0 ? "印" : "记", x + 11, y + 22);
  ctx.restore();
}

function drawCompendiumDisplayAudience(ctx, compendiumDisplays = [], motion = 0) {
  if (!compendiumDisplays.length || state.shopReport.length === 0) return;
  const remark = normalizeShopOpeningState(state.shopOpeningState).needBubbles.find((entry) => entry.compendiumRemark)
    || state.shopReport.find((entry) => entry.reason === "compendium");
  const focus = compendiumDisplays[0];
  const bob = settings.reducedMotion ? 0 : Math.sin(motion * 2.1) * 2.5;
  const x = 222;
  const y = 272 + bob;
  ctx.save();
  ctx.strokeStyle = focus.palette.accent;
  ctx.lineWidth = 2;
  ctx.setLineDash([5, 5]);
  ctx.beginPath();
  ctx.moveTo(x + 8, y + 14);
  ctx.lineTo(148, 264);
  ctx.stroke();
  ctx.setLineDash([]);

  ctx.fillStyle = "rgba(23, 35, 29, 0.16)";
  ctx.beginPath();
  ctx.ellipse(x + 18, y + 42, 24, 7, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "rgba(255, 253, 245, 0.84)";
  ctx.beginPath();
  ctx.arc(x + 18, y + 4, 12, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = focus.palette.accent;
  ctx.beginPath();
  ctx.roundRect(x + 4, y + 16, 30, 36, 12);
  ctx.fill();
  ctx.fillStyle = focus.palette.glow;
  ctx.beginPath();
  ctx.arc(x + 28, y + 2, 4, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = "rgba(255, 248, 232, 0.92)";
  ctx.beginPath();
  ctx.roundRect(x - 12, y - 34, 96, 24, 10);
  ctx.fill();
  ctx.strokeStyle = "rgba(143, 95, 63, 0.24)";
  ctx.stroke();
  ctx.fillStyle = "#8f5f3f";
  ctx.font = "700 11px Microsoft YaHei";
  const label = remark?.compendiumDisplay || focus.shortTitle || "节气印记";
  ctx.fillText(`看${String(label).slice(0, 4)}`, x, y - 18);
  ctx.restore();
}

function drawYear2OrderPrepTable(ctx, livingState) {
  if (!year2Unlocked()) return;
  const order = year2OrderPreview(1)[0] || year2FirstWeekOrder();
  if (!order) return;
  const needStatus = year2OrderNeedStatus(order);
  const needs = orderNeeds(order).slice(0, 3);
  const ready = needStatus.completion >= 1;
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const x = 382;
  const y = 262;
  const width = 244;
  const height = 126;
  const progress = Math.max(0.06, Math.min(1, needStatus.completion || 0));

  ctx.save();
  ctx.fillStyle = "rgba(23, 35, 29, 0.14)";
  ctx.beginPath();
  ctx.ellipse(x + width / 2, y + height + 14, width * 0.48, 16, 0, 0, Math.PI * 2);
  ctx.fill();

  drawCanvasCard(ctx, x, y, width, height, ready ? "rgba(255, 248, 232, 0.94)" : "rgba(255, 253, 245, 0.88)");

  ctx.fillStyle = ready ? "rgba(224, 182, 109, 0.22)" : "rgba(77, 145, 166, 0.16)";
  ctx.beginPath();
  ctx.roundRect(x + 14, y + 12, width - 28, 30, 12);
  ctx.fill();
  ctx.fillStyle = ready ? "#b47d2f" : "#286f58";
  ctx.font = "700 13px Microsoft YaHei";
  ctx.fillText(ready ? "名铺订单已备齐" : "名铺订单备货台", x + 26, y + 32);
  ctx.fillStyle = "#17231d";
  ctx.font = "700 12px Microsoft YaHei";
  ctx.fillText(orderTitle(order).slice(0, 11), x + 128, y + 32);

  ctx.fillStyle = "rgba(23, 35, 29, 0.12)";
  ctx.beginPath();
  ctx.roundRect(x + 22, y + 54, width - 44, 10, 999);
  ctx.fill();
  ctx.fillStyle = ready ? "#b47d2f" : "#4d91a6";
  ctx.beginPath();
  ctx.roundRect(x + 22, y + 54, Math.max(18, (width - 44) * progress), 10, 999);
  ctx.fill();
  ctx.fillStyle = "#5d6f65";
  ctx.font = "11px Microsoft YaHei";
  ctx.fillText(`备货 ${needStatus.readyCount}/${needStatus.totalCount}`, x + 22, y + 80);
  ctx.fillStyle = ready ? "#b47d2f" : "#be4f37";
  ctx.fillText(ready ? "可交付" : `缺 ${Math.max(0, needStatus.totalCount - needStatus.readyCount)}`, x + width - 68, y + 80);

  needs.forEach(({ itemId, count }, index) => {
    const have = Number(state.inventory[itemId] || 0);
    const itemReady = have >= count;
    const boxX = x + 22 + index * 66;
    const boxY = y + 90 + Math.sin(motion * 2 + index) * (settings.reducedMotion ? 0 : 2);
    ctx.fillStyle = itemReady ? "rgba(224, 182, 109, 0.22)" : "rgba(239, 217, 208, 0.86)";
    ctx.beginPath();
    ctx.roundRect(boxX, boxY, 54, 28, 9);
    ctx.fill();
    ctx.strokeStyle = itemReady ? "rgba(180, 125, 47, 0.45)" : "rgba(190, 79, 55, 0.32)";
    ctx.lineWidth = 2;
    ctx.stroke();
    ctx.fillStyle = itemReady ? "#b47d2f" : "#be4f37";
    ctx.font = "700 10px Microsoft YaHei";
    ctx.fillText(itemReady ? "已备" : "缺货", boxX + 8, boxY + 12);
    ctx.fillStyle = "#17231d";
    ctx.font = "10px Microsoft YaHei";
    ctx.fillText(`${itemName(itemId).slice(0, 4)} ${Math.min(have, count)}/${count}`, boxX + 7, boxY + 24);
  });

  if (livingState?.shopSpirits > 0 || state.spirits.some((spirit) => spirit.job === "shop" || spirit.job === "workshop")) {
    const spiritX = x + width - 34 + Math.sin(motion * 2.4) * (settings.reducedMotion ? 0 : 3);
    const spiritY = y + height - 12 + Math.cos(motion * 2.1) * (settings.reducedMotion ? 0 : 2);
    ctx.fillStyle = "rgba(23, 35, 29, 0.14)";
    ctx.beginPath();
    ctx.ellipse(spiritX, spiritY + 11, 15, 5, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = ready ? "#e0b66d" : "#caebd2";
    ctx.beginPath();
    ctx.arc(spiritX, spiritY - 4, 11, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#286f58";
    ctx.beginPath();
    ctx.roundRect(spiritX - 9, spiritY + 7, 18, 16, 7);
    ctx.fill();
    ctx.fillStyle = "#fffdf5";
    ctx.font = "700 10px Microsoft YaHei";
    ctx.fillText("查", spiritX - 5, spiritY + 18);
  }

  ctx.strokeStyle = ready ? "rgba(224, 182, 109, 0.58)" : "rgba(77, 145, 166, 0.42)";
  ctx.lineWidth = 2;
  ctx.setLineDash([5, 5]);
  ctx.beginPath();
  ctx.moveTo(x + 34, y + 10);
  ctx.bezierCurveTo(x + 10, y - 16, x - 40, y - 22, 206, 230);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.restore();
}

function drawYear2ShopSeasonBillboard(ctx) {
  if (!year2Unlocked()) return;
  state.shopStats = normalizeShopStats(state.shopStats);
  const cycle = shopSeasonCycleInfo();
  const season = cycle.season;
  if (!season) return;
  const pending = state.shopStats.pendingSettlement;
  const settlement = pending
    ? {
      score: Number(pending.score || 0),
      rank: { rank_tier: pending.rankTier || "c" },
      parts: (pending.parts || []).map((part) => ({
        label: part.displayName || part.scorePart || "评分项",
        raw: Number(part.raw || 0),
        note: part.note || "",
      })),
      title: pending.seasonName,
      subtitle: `月评出炉 · ${String(pending.rankTier || "c").toUpperCase()} 档 · 奖励待领`,
      weakPart: pending.weakPart || "暂无明显短板",
      advice: pending.advice || shopSeasonTitle(pending.rankTier),
      reward: shopSeasonRewardText(pending.reward),
      dayText: `第 ${pending.cycleStartDay || cycle.startDay}-${pending.cycleEndDay || (cycle.startDay + cycle.cycleDays - 1)} 天`,
    }
    : (() => {
      const score = shopSeasonScore(season, currentShopSeasonStats());
      const rank = shopSeasonRank(score.score, season);
      const weakest = score.parts.slice().sort((a, b) => Number(a.raw || 0) - Number(b.raw || 0))[0] || null;
      return {
        score: score.score,
        rank,
        parts: score.parts.map((part) => ({
          label: part.rule?.display_name || part.rule?.score_part || "评分项",
          raw: Number(part.raw || 0),
          note: shopSeasonAdviceForPart(part),
        })),
        title: season.season_name,
        subtitle: `赛季第 ${cycle.dayInSeason}/${cycle.cycleDays} 天 · 当前 ${String(rank.rank_tier || "c").toUpperCase()} 档`,
        weakPart: weakest?.rule?.display_name || "暂无明显短板",
        advice: weakest ? shopSeasonAdviceForPart(weakest) : shopSeasonTitle(rank.rank_tier),
        reward: shopSeasonRewardText(rank),
        dayText: splitTags(season.score_focus_tags).slice(0, 3).join(" / "),
      };
    })();

  const rankTier = String(settlement.rank?.rank_tier || "c").toLowerCase();
  const rankPalette = {
    s: { accent: "#b47d2f", glow: "rgba(224, 182, 109, 0.32)", ink: "#8f5f3f" },
    a: { accent: "#286f58", glow: "rgba(202, 235, 210, 0.28)", ink: "#286f58" },
    b: { accent: "#4d91a6", glow: "rgba(159, 209, 223, 0.25)", ink: "#4d7474" },
    c: { accent: "#be4f37", glow: "rgba(190, 79, 55, 0.18)", ink: "#8f5f3f" },
  }[rankTier] || { accent: "#8f5f3f", glow: "rgba(143, 95, 63, 0.18)", ink: "#8f5f3f" };
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const x = 672;
  const y = 56;
  const width = 236;
  const height = 178;

  ctx.save();
  ctx.fillStyle = rankPalette.glow;
  ctx.beginPath();
  ctx.ellipse(x + width / 2, y + height / 2, width * 0.56, height * 0.58, 0, 0, Math.PI * 2);
  ctx.fill();
  drawCanvasCard(ctx, x, y, width, height, pending ? "rgba(255, 248, 232, 0.96)" : "rgba(255, 253, 245, 0.86)");

  ctx.strokeStyle = rankPalette.accent;
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.roundRect(x + 10, y + 10, width - 20, height - 20, 18);
  ctx.stroke();

  ctx.fillStyle = rankPalette.accent;
  ctx.beginPath();
  ctx.roundRect(x + width - 58, y + 18, 38, 38, 14);
  ctx.fill();
  ctx.fillStyle = "#fffdf5";
  ctx.font = "700 24px Microsoft YaHei";
  ctx.fillText(String(settlement.rank?.rank_tier || "c").toUpperCase(), x + width - 46, y + 45);

  ctx.fillStyle = "#17231d";
  ctx.font = "700 15px Microsoft YaHei";
  ctx.fillText(settlement.title.slice(0, 10), x + 22, y + 32);
  ctx.fillStyle = rankPalette.ink;
  ctx.font = "700 11px Microsoft YaHei";
  ctx.fillText(settlement.subtitle.slice(0, 22), x + 22, y + 52);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "11px Microsoft YaHei";
  ctx.fillText(settlement.dayText.slice(0, 24), x + 22, y + 69);

  ctx.fillStyle = "rgba(23, 35, 29, 0.1)";
  ctx.beginPath();
  ctx.roundRect(x + 22, y + 80, width - 44, 10, 999);
  ctx.fill();
  const nextScore = rankTier === "s" ? Math.max(1150, settlement.score) : Number(shopSeasonRewards(season).find((reward) => String(reward.rank_tier || "").toLowerCase() === (rankTier === "a" ? "s" : rankTier === "b" ? "a" : "b"))?.score_min || 920);
  const progress = Math.max(0.08, Math.min(1, settlement.score / Math.max(1, nextScore)));
  ctx.fillStyle = rankPalette.accent;
  ctx.beginPath();
  ctx.roundRect(x + 22, y + 80, Math.max(18, (width - 44) * progress), 10, 999);
  ctx.fill();
  ctx.fillStyle = "#17231d";
  ctx.font = "700 12px Microsoft YaHei";
  ctx.fillText(`总分 ${settlement.score}`, x + 22, y + 108);
  ctx.fillStyle = pending ? "#b47d2f" : "#5d6f65";
  ctx.font = "11px Microsoft YaHei";
  ctx.fillText((pending ? `奖励 ${settlement.reward}` : `预计 ${settlement.reward}`).slice(0, 24), x + 88, y + 108);

  settlement.parts.slice(0, 4).forEach((part, index) => {
    const rowY = y + 122 + index * 12;
    const raw = Math.max(0, Math.min(100, Number(part.raw || 0)));
    ctx.fillStyle = "#5d6f65";
    ctx.font = "10px Microsoft YaHei";
    ctx.fillText(String(part.label).slice(0, 5), x + 22, rowY);
    ctx.fillStyle = "rgba(23, 35, 29, 0.1)";
    ctx.beginPath();
    ctx.roundRect(x + 72, rowY - 8, 86, 6, 999);
    ctx.fill();
    ctx.fillStyle = raw < 45 ? "#be4f37" : raw < 72 ? "#b47d2f" : "#286f58";
    ctx.beginPath();
    ctx.roundRect(x + 72, rowY - 8, Math.max(8, 86 * raw / 100), 6, 999);
    ctx.fill();
    ctx.fillStyle = "#8f5f3f";
    ctx.fillText(`${Math.round(raw)}%`, x + 166, rowY);
  });

  ctx.fillStyle = pending ? "rgba(224, 182, 109, 0.16)" : "rgba(255, 248, 232, 0.82)";
  ctx.beginPath();
  ctx.roundRect(x + 18, y + height - 28, width - 36, 18, 9);
  ctx.fill();
  ctx.fillStyle = pending ? "#b47d2f" : "#be4f37";
  ctx.font = "700 10px Microsoft YaHei";
  ctx.fillText((pending ? "月评待领" : `短板 ${settlement.weakPart}`).slice(0, 14), x + 28, y + height - 16);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "10px Microsoft YaHei";
  ctx.fillText(settlement.advice.slice(0, 20), x + 104, y + height - 16);

  if (pending || rankTier === "s") {
    for (let i = 0; i < 6; i += 1) {
      const sparkX = x + 30 + i * 32;
      const sparkY = y - 4 + Math.sin(motion * 2.2 + i) * 4;
      ctx.fillStyle = i % 2 ? "rgba(224, 182, 109, 0.88)" : "rgba(255, 253, 245, 0.86)";
      ctx.beginPath();
      ctx.arc(sparkX, sparkY, 2.5, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.restore();
}

function drawYear2SolarTrialDial(ctx) {
  if (!year2Unlocked()) return;
  const trial = recommendedSolarTrial();
  if (!trial) return;
  const active = state.activeSolarTrial?.trialId === trial.trial_id ? state.activeSolarTrial : null;
  const score = evaluateSolarTrialScore(trial);
  const rank = solarTrialRank(score);
  const support = solarTrialCompendiumSupport(trial);
  const runProgress = solarTrialRunProgress(active, trial);
  const scoreBreakdown = solarTrialScoreBreakdown(trial, active);
  const tags = splitTags(trial.required_loop_tags).slice(0, 3);
  const termName = localize(data.solarTermsById.get(trial.term_id)?.term_name_key, trial.term_id);
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const x = 646;
  const y = 250;
  const width = 262;
  const height = 132;
  const centerX = x + 54;
  const centerY = y + 66;
  const totalDays = Math.max(1, Number(trial.challenge_days || 3));
  const remaining = active ? runProgress.remaining : Number(trial.challenge_days || 3);
  const progress = active ? runProgress.progress : Math.max(0.08, Math.min(1, score / 100));
  const palette = {
    term_guyu: { accent: "#5d8b52", glow: "rgba(202, 235, 210, 0.3)", glyph: "雨" },
    term_dashu: { accent: "#be4f37", glow: "rgba(190, 79, 55, 0.2)", glyph: "暑" },
    term_bailu: { accent: "#4d91a6", glow: "rgba(159, 209, 223, 0.28)", glyph: "露" },
    term_dongzhi: { accent: "#b47d2f", glow: "rgba(224, 182, 109, 0.28)", glyph: "灯" },
    term_dahan: { accent: "#8c7ab8", glow: "rgba(215, 210, 236, 0.24)", glyph: "寒" },
  }[trial.term_id] || { accent: "#286f58", glow: "rgba(202, 235, 210, 0.24)", glyph: "试" };

  ctx.save();
  ctx.fillStyle = palette.glow;
  ctx.beginPath();
  ctx.ellipse(centerX, centerY, 72, 54, 0, 0, Math.PI * 2);
  ctx.fill();
  drawCanvasCard(ctx, x, y, width, height, active ? "rgba(255, 248, 232, 0.94)" : "rgba(255, 253, 245, 0.86)");

  ctx.strokeStyle = "rgba(23, 35, 29, 0.12)";
  ctx.lineWidth = 10;
  ctx.beginPath();
  ctx.arc(centerX, centerY, 34, -Math.PI / 2, Math.PI * 1.5);
  ctx.stroke();
  ctx.strokeStyle = palette.accent;
  ctx.lineWidth = 10;
  ctx.beginPath();
  ctx.arc(centerX, centerY, 34, -Math.PI / 2, -Math.PI / 2 + Math.PI * 2 * progress);
  ctx.stroke();

  for (let i = 0; i < 8; i += 1) {
    const angle = motion * 0.18 + (Math.PI * 2 * i) / 8;
    const dotX = centerX + Math.cos(angle) * 46;
    const dotY = centerY + Math.sin(angle) * 46;
    ctx.fillStyle = i % 2 ? "rgba(255, 253, 245, 0.84)" : palette.accent;
    ctx.beginPath();
    ctx.arc(dotX, dotY, i % 2 ? 2 : 2.8, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.fillStyle = "#fffdf5";
  ctx.beginPath();
  ctx.arc(centerX, centerY, 24, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = palette.accent;
  ctx.font = "700 22px Microsoft YaHei";
  ctx.fillText(palette.glyph, centerX - 11, centerY + 8);

  ctx.fillStyle = active ? "#be4f37" : "#286f58";
  ctx.font = "700 12px Microsoft YaHei";
  ctx.fillText(active ? "年轮试炼进行中" : "年轮试炼预告", x + 108, y + 26);
  ctx.fillStyle = "#17231d";
  ctx.font = "700 15px Microsoft YaHei";
  ctx.fillText(solarTrialName(trial).slice(0, 12), x + 108, y + 49);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "11px Microsoft YaHei";
  ctx.fillText(`${termName} · ${active ? `${runProgress.phaseLabel} ${runProgress.dayIndex}/${totalDays}` : `挑战 ${trial.challenge_days} 天`}`.slice(0, 22), x + 108, y + 68);

  ctx.fillStyle = "rgba(23, 35, 29, 0.1)";
  ctx.beginPath();
  ctx.roundRect(x + 108, y + 78, 112, 8, 999);
  ctx.fill();
  ctx.fillStyle = palette.accent;
  ctx.beginPath();
  ctx.roundRect(x + 108, y + 78, Math.max(12, 112 * score / 100), 8, 999);
  ctx.fill();
  ctx.fillStyle = "#17231d";
  ctx.font = "700 11px Microsoft YaHei";
  ctx.fillText(`预估 ${score} / ${rank}`, x + 226, y + 86);
  if (active) {
    ctx.fillStyle = runProgress.actedToday ? "#286f58" : "#be4f37";
    ctx.font = "700 10px Microsoft YaHei";
    ctx.fillText(runProgress.actedToday ? "今日已记" : `剩余 ${remaining} 天 · 待推进`, x + 108, y + 92);
  }

  tags.forEach((tag, index) => {
    const chipX = x + 108 + index * 48;
    ctx.fillStyle = index === 0 ? palette.glow : "rgba(255, 248, 232, 0.86)";
    ctx.beginPath();
    ctx.roundRect(chipX, y + 96, 42, 20, 10);
    ctx.fill();
    ctx.fillStyle = palette.accent;
    ctx.font = "700 10px Microsoft YaHei";
    ctx.fillText(tag.slice(0, 5), chipX + 7, y + 110);
  });

  ctx.fillStyle = support.bonus > 0 ? "#b47d2f" : "#8f5f3f";
  ctx.font = "10px Microsoft YaHei";
  ctx.fillText((active && scoreBreakdown.actionBoost > 0 ? `手账加压 ${scoreBreakdown.actionBoost} · ${support.summary}` : support.bonus > 0 ? `印记共鸣 +${support.bonus} · ${support.summary}` : `印记未鸣 · ${support.summary}`).slice(0, 32), x + 18, y + height - 12);

  if (active || rank === "S" || rank === "A") {
    ctx.strokeStyle = palette.accent;
    ctx.lineWidth = 2;
    ctx.setLineDash([4, 6]);
    ctx.beginPath();
    ctx.moveTo(centerX - 24, y + height + 2);
    ctx.bezierCurveTo(centerX - 50, y + height + 36, 560, 504, 496, 530);
    ctx.stroke();
    ctx.setLineDash([]);
  }
  ctx.restore();
}

function drawCohabCourtyard(ctx, livingState) {
  if (livingState.cohabRoutes.length === 0) return;
  const buffRouteIds = new Set(livingState.activeBuffs.map((entry) => entry.routeId));
  const hasRoute = (epilogueId) => livingState.cohabRoutes.some((entry) => entry.epilogue_id === epilogueId);
  const routeGlow = (epilogueId, color, x, y, radiusX, radiusY) => {
    if (!buffRouteIds.has(epilogueId)) return;
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.ellipse(x, y, radiusX, radiusY, 0, 0, Math.PI * 2);
    ctx.fill();
  };

  ctx.save();
  if (hasRoute("cohab_baizhi_01")) {
    routeGlow("cohab_baizhi_01", "rgba(202, 235, 210, 0.28)", 222, 266, 54, 18);
    ctx.strokeStyle = "#8f5f3f";
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(188, 220);
    ctx.lineTo(188, 280);
    ctx.lineTo(246, 280);
    ctx.lineTo(246, 220);
    ctx.stroke();
    ["#5d8b52", "#9fd1df", "#e0b66d"].forEach((color, index) => {
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.ellipse(200 + index * 18, 238 + (index % 2) * 10, 8, 14, index * 0.3, 0, Math.PI * 2);
      ctx.fill();
    });
    ctx.fillStyle = "#caebd2";
    ctx.beginPath();
    ctx.roundRect(256, 258, 16, 18, 4);
    ctx.fill();
  }

  if (hasRoute("cohab_hu_01")) {
    routeGlow("cohab_hu_01", "rgba(230, 198, 94, 0.24)", 306, 334, 64, 20);
    ctx.fillStyle = "#8f5f3f";
    ctx.beginPath();
    ctx.roundRect(272, 290, 36, 26, 6);
    ctx.roundRect(314, 300, 34, 22, 6);
    ctx.fill();
    ctx.strokeStyle = "#b47d2f";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(332, 258);
    ctx.lineTo(332, 302);
    ctx.stroke();
    ctx.fillStyle = "#e6c65e";
    ctx.beginPath();
    ctx.moveTo(332, 258);
    ctx.lineTo(362, 268);
    ctx.lineTo(332, 282);
    ctx.closePath();
    ctx.fill();
  }

  if (hasRoute("cohab_atan_01")) {
    routeGlow("cohab_atan_01", "rgba(242, 210, 139, 0.2)", 250, 198, 54, 18);
    ctx.fillStyle = "#8f5f3f";
    ctx.fillRect(218, 176, 52, 10);
    ctx.fillRect(224, 186, 8, 28);
    ctx.fillRect(256, 186, 8, 28);
    ctx.strokeStyle = "#e0b66d";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(272, 166);
    ctx.lineTo(294, 146);
    ctx.lineTo(316, 176);
    ctx.stroke();
  }

  if (hasRoute("cohab_qinghe_01")) {
    routeGlow("cohab_qinghe_01", "rgba(159, 209, 223, 0.24)", 674, 548, 78, 24);
    ctx.fillStyle = "rgba(77, 145, 166, 0.34)";
    ctx.beginPath();
    ctx.ellipse(664, 550, 64, 20, -0.1, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = "#5d8b52";
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(718, 524, 18, 0, Math.PI * 2);
    ctx.moveTo(718, 506);
    ctx.lineTo(718, 542);
    ctx.moveTo(700, 524);
    ctx.lineTo(736, 524);
    ctx.stroke();
    ctx.fillStyle = "#fffdf5";
    ctx.beginPath();
    ctx.arc(640, 540, 8, 0, Math.PI * 2);
    ctx.arc(682, 556, 6, 0, Math.PI * 2);
    ctx.fill();
  }

  if (hasRoute("cohab_shen_01")) {
    routeGlow("cohab_shen_01", "rgba(246, 240, 182, 0.24)", 560, 302, 64, 22);
    ctx.fillStyle = "#5b3328";
    ctx.fillRect(540, 260, 8, 48);
    ctx.fillRect(584, 268, 8, 42);
    ctx.fillStyle = "rgba(246, 240, 182, 0.68)";
    ctx.beginPath();
    ctx.arc(544, 274, 10, 0, Math.PI * 2);
    ctx.arc(588, 282, 9, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#be4f37";
    ctx.beginPath();
    ctx.moveTo(564, 296);
    ctx.lineTo(582, 330);
    ctx.lineTo(544, 330);
    ctx.closePath();
    ctx.fill();
  }

  if (livingState.cohabRoutes.length >= 2) {
    const steamBob = settings.reducedMotion ? 0 : Math.sin(performance.now() / 320) * 2;
    ctx.fillStyle = "#8f5f3f";
    ctx.beginPath();
    ctx.roundRect(154, 316, 92, 18, 8);
    ctx.fill();
    ctx.fillRect(166, 334, 8, 18);
    ctx.fillRect(226, 334, 8, 18);
    ctx.fillStyle = "#fffdf5";
    [174, 194, 214, 234].forEach((x) => {
      ctx.beginPath();
      ctx.arc(x, 312, 6, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = "rgba(23, 35, 29, 0.18)";
      ctx.stroke();
    });
    ctx.fillStyle = "rgba(255, 253, 245, 0.46)";
    [182, 218].forEach((x, index) => {
      ctx.beginPath();
      ctx.arc(x, 300 - index * 6 + steamBob, 5, 0, Math.PI * 2);
      ctx.fill();
    });
  }
  ctx.restore();
}

function drawCohabLifeNote(ctx, livingState) {
  const spec = cohabAfterglowWindowSpec(livingState, ctx.canvas.width, ctx.canvas.height);
  if (!spec?.rect) return;
  const { life, rect, palette } = spec;
  const latest = life.latest;
  const buff = life.activeBuff;
  const activeNodeKey = cohabAfterglowWindowWorldFocus?.day === state.day
    && cohabAfterglowWindowWorldFocus?.key === spec.key
    ? cohabAfterglowWindowWorldFocus.nodeKey
    : "";
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const x = rect.x;
  const y = rect.y;
  const width = rect.width;
  const height = rect.height;
  const accent = palette.accent;
  const bob = settings.reducedMotion ? 0 : Math.sin(motion * 1.4) * 1.5;

  ctx.save();
  ctx.fillStyle = "rgba(23, 35, 29, 0.13)";
  ctx.beginPath();
  ctx.ellipse(x + width / 2, y + height + 10 + bob, width * 0.43, 13, 0, 0, Math.PI * 2);
  ctx.fill();
  drawCanvasCard(ctx, x, y + bob, width, height, palette.soft);

  ctx.fillStyle = "rgba(255, 253, 245, 0.92)";
  ctx.beginPath();
  ctx.roundRect(x + 14, y + 14 + bob, 54, 70, 16);
  ctx.fill();
  ctx.strokeStyle = "rgba(143, 95, 63, 0.22)";
  ctx.stroke();
  const homeX = x + 24;
  const homeY = y + 46 + bob;
  ctx.fillStyle = accent;
  ctx.beginPath();
  ctx.moveTo(homeX, homeY);
  ctx.lineTo(homeX + 17, homeY - 18);
  ctx.lineTo(homeX + 34, homeY);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = "#8f5f3f";
  ctx.beginPath();
  ctx.roundRect(homeX + 5, homeY, 24, 24, 5);
  ctx.fill();
  ctx.fillStyle = "#fffdf5";
  ctx.fillRect(homeX + 14, homeY + 10, 6, 14);
  if (life.routeCount >= 2) {
    ctx.fillStyle = "rgba(224, 182, 109, 0.78)";
    ctx.beginPath();
    ctx.arc(homeX + 33 + Math.sin(motion * 2) * 2, homeY - 16, 4, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.fillStyle = accent;
  ctx.font = "700 12px Microsoft YaHei";
  ctx.fillText(`同住后日谈窗灯 · ${life.routeCount} 线`, x + 82, y + 28 + bob);
  ctx.fillStyle = "#17231d";
  ctx.font = "700 14px Microsoft YaHei";
  ctx.fillText(spec.headline.slice(0, 18), x + 82, y + 50 + bob);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "11px Microsoft YaHei";
  ctx.fillText(spec.detail.slice(0, 26), x + 82, y + 68 + bob);

  ctx.fillStyle = palette.glow;
  ctx.beginPath();
  ctx.roundRect(x + 82, y + 78 + bob, width - 100, 20, 10);
  ctx.fill();
  ctx.fillStyle = buff ? "#b47d2f" : "#8f5f3f";
  ctx.font = "700 10px Microsoft YaHei";
  const buffText = buff
    ? `余韵 ${buff.label} 至第 ${buff.expiresDay} 天`
    : spec.nextEvent
      ? `下一件小事：${spec.nextRoute?.route_name || "同住"} · ${spec.nextEvent.event_name || spec.nextEvent.scene_key || "日常"}`
      : "下一件小事：等下一次日夜流转";
  ctx.fillText(buffText.slice(0, 28), x + 92, y + 92 + bob);

  for (const node of spec.nodes) {
    const nodeRect = node.rect;
    const active = activeNodeKey === node.key;
    ctx.fillStyle = active ? "rgba(255, 253, 245, 0.94)" : "rgba(255, 253, 245, 0.64)";
    ctx.strokeStyle = active ? "rgba(224, 182, 109, 0.86)" : `${accent}33`;
    ctx.lineWidth = active ? 1.8 : 1;
    ctx.beginPath();
    ctx.roundRect(nodeRect.x, nodeRect.y + bob, nodeRect.width, nodeRect.height, 10);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = `${accent}22`;
    ctx.beginPath();
    ctx.roundRect(nodeRect.x + 5, nodeRect.y + 6 + bob, 19, 16, 7);
    ctx.fill();
    ctx.fillStyle = accent;
    ctx.font = "900 9px Microsoft YaHei";
    ctx.fillText(node.badge, nodeRect.x + 10, nodeRect.y + 18 + bob);
    ctx.fillStyle = "#17231d";
    ctx.font = "800 9px Microsoft YaHei";
    ctx.fillText(node.shortLabel, nodeRect.x + 29, nodeRect.y + 14 + bob);
    ctx.fillStyle = "#5d6f65";
    ctx.font = "8px Microsoft YaHei";
    ctx.fillText(node.shortTitle, nodeRect.x + 29, nodeRect.y + 24 + bob);
  }

  for (let i = 0; i < Math.min(5, life.routeCount); i += 1) {
    ctx.fillStyle = i % 2 ? "rgba(202, 235, 210, 0.78)" : "rgba(224, 182, 109, 0.72)";
    ctx.beginPath();
    ctx.arc(x + 22 + i * 9, y + height - 8 + bob + Math.sin(motion * 1.8 + i) * 1.5, 3, 0, Math.PI * 2);
    ctx.fill();
  }
  if (activeNodeKey) {
    ctx.strokeStyle = "rgba(224, 182, 109, 0.78)";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.roundRect(x + 4, y + 4 + bob, width - 8, height - 8, 18);
    ctx.stroke();
  }
  ctx.restore();
}

function drawEcologyComboMotif(ctx, comboId, x, y, index = 0, motion = 0) {
  const pulse = settings.reducedMotion ? 0 : Math.sin(motion * 2 + index) * 2;
  const palette = {
    eco_rain_herb_garden: { accent: "#4d91a6", glow: "rgba(202, 235, 210, 0.34)", glyph: "雨" },
    eco_fire_feast_hall: { accent: "#be4f37", glow: "rgba(240, 165, 78, 0.28)", glyph: "火" },
    eco_night_lamp_path: { accent: "#b47d2f", glow: "rgba(246, 240, 182, 0.34)", glyph: "灯" },
    eco_cloud_warehouse: { accent: "#8f9c9a", glow: "rgba(223, 247, 238, 0.32)", glyph: "云" },
    eco_flower_guest_yard: { accent: "#d87f8d", glow: "rgba(216, 127, 141, 0.28)", glyph: "花" },
    eco_moon_pond: { accent: "#4d91a6", glow: "rgba(159, 209, 223, 0.32)", glyph: "月" },
    eco_honey_orchard: { accent: "#b47d2f", glow: "rgba(224, 182, 109, 0.32)", glyph: "蜜" },
    eco_book_order_room: { accent: "#8f5f3f", glow: "rgba(255, 253, 245, 0.38)", glyph: "账" },
  }[comboId] || { accent: "#286f58", glow: "rgba(202, 235, 210, 0.3)", glyph: "灵" };

  ctx.save();
  ctx.fillStyle = "rgba(23, 35, 29, 0.12)";
  ctx.beginPath();
  ctx.ellipse(x, y + 17, 22, 7, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = palette.glow;
  ctx.beginPath();
  ctx.arc(x, y, 17 + Math.max(0, pulse), 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "rgba(255, 248, 232, 0.9)";
  ctx.beginPath();
  ctx.roundRect(x - 16, y - 18, 32, 36, 12);
  ctx.fill();
  ctx.strokeStyle = palette.accent;
  ctx.lineWidth = 2;
  ctx.stroke();
  ctx.fillStyle = palette.accent;
  ctx.font = "700 16px Microsoft YaHei";
  ctx.fillText(palette.glyph, x - 8, y + 5);

  if (comboId === "eco_honey_orchard") {
    ctx.fillStyle = "#17231d";
    ctx.beginPath();
    ctx.arc(x + 20, y - 8 + pulse, 3, 0, Math.PI * 2);
    ctx.fill();
  } else if (comboId === "eco_night_lamp_path") {
    ctx.strokeStyle = palette.accent;
    ctx.beginPath();
    ctx.moveTo(x, y + 18);
    ctx.lineTo(x, y + 30 + pulse);
    ctx.stroke();
  } else if (comboId === "eco_flower_guest_yard") {
    for (let i = 0; i < 3; i += 1) {
      ctx.fillStyle = i % 2 ? "#f2d28b" : "#d87f8d";
      ctx.beginPath();
      ctx.ellipse(x - 22 + i * 8, y + 4 + pulse, 3, 6, i, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.restore();
}

function drawEcologyMemoryResonanceMarks(ctx, x, y, width, height, resonance, motion = 0, accent = "#286f58") {
  const memoryResonance = resonance || { tier: 0 };
  const memoryTier = Number(memoryResonance.tier || 0);
  if (memoryTier <= 0) return;

  const tierName = memoryTier >= 3 ? "百息成院" : memoryTier >= 2 ? "夜札成册" : "院声初熟";
  const yardX = x + 14;
  const yardY = y + 14;
  const yardW = 78;
  const yardH = 88;
  const pulse = settings.reducedMotion ? 0 : Math.sin(motion * 2.3) * 1.8;
  const shimmer = settings.reducedMotion ? 0 : Math.sin(motion * 1.4) * 0.12;

  ctx.save();
  ctx.globalAlpha = 0.84;
  ctx.strokeStyle = memoryTier >= 3 ? "rgba(77, 145, 166, 0.46)" : memoryTier >= 2 ? "rgba(180, 125, 47, 0.42)" : "rgba(246, 240, 182, 0.46)";
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.roundRect(yardX + 6, yardY + 6, yardW - 12, yardH - 12, 17);
  ctx.stroke();

  const lightCount = memoryTier >= 3 ? 7 : memoryTier >= 2 ? 5 : 3;
  for (let i = 0; i < lightCount; i += 1) {
    const lightX = yardX + 14 + i * 9;
    const lightY = yardY + 17 + Math.sin(motion * 1.7 + i) * 1.6;
    const radius = 2.3 + (i % 2) * 0.9 + (memoryTier >= 3 ? Math.max(0, pulse) * 0.18 : 0);
    ctx.fillStyle = i % 2 ? "rgba(246, 240, 182, 0.86)" : "rgba(224, 182, 109, 0.74)";
    ctx.beginPath();
    ctx.arc(lightX, lightY, radius, 0, Math.PI * 2);
    ctx.fill();
  }

  if (memoryTier >= 2) {
    ctx.save();
    ctx.translate(yardX + 48, yardY + 64);
    ctx.rotate(-0.12);
    ctx.fillStyle = "rgba(255, 253, 245, 0.88)";
    ctx.strokeStyle = "rgba(143, 95, 63, 0.46)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.roundRect(-15, -13, 30, 24, 5);
    ctx.fill();
    ctx.stroke();
    ctx.strokeStyle = "rgba(180, 125, 47, 0.46)";
    for (let i = 0; i < 3; i += 1) {
      ctx.beginPath();
      ctx.moveTo(-9, -5 + i * 6);
      ctx.lineTo(10, -7 + i * 6);
      ctx.stroke();
    }
    ctx.restore();

    for (let i = 0; i < 5; i += 1) {
      ctx.fillStyle = i % 2 ? "rgba(216, 127, 141, 0.58)" : "rgba(242, 210, 139, 0.62)";
      ctx.beginPath();
      ctx.ellipse(yardX + 20 + i * 11, yardY + 72 + Math.sin(motion + i) * 1.8, 2.4, 5, 0.7 + i, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  if (memoryTier >= 3) {
    ctx.strokeStyle = `rgba(77, 145, 166, ${0.5 + shimmer})`;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(yardX + 25, yardY + 37, 18 + pulse * 0.4, -0.75, 1.85);
    ctx.stroke();
    ctx.strokeStyle = "rgba(91, 51, 40, 0.42)";
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(yardX + 9, yardY + 48);
    ctx.quadraticCurveTo(yardX + 39, yardY + 34 + pulse, yardX + 69, yardY + 48);
    ctx.stroke();
    for (let i = 0; i < 4; i += 1) {
      const beadX = yardX + 16 + i * 16;
      const beadY = yardY + 48 + Math.sin(motion * 1.3 + i) * 1.3;
      ctx.fillStyle = i % 2 ? "rgba(202, 235, 210, 0.72)" : "rgba(246, 240, 182, 0.78)";
      ctx.beginPath();
      ctx.roundRect(beadX - 3, beadY - 2, 6, 8, 3);
      ctx.fill();
    }
  }

  ctx.fillStyle = memoryTier >= 3 ? "#4d91a6" : memoryTier >= 2 ? "#8f5f3f" : accent;
  ctx.font = "700 9px Microsoft YaHei";
  ctx.fillText(tierName, yardX + 12, yardY + yardH - 8);
  ctx.restore();
}

function drawRareSpiritEcologyYard(ctx, livingState) {
  const garden = livingState?.ecologyGarden;
  if (!garden) return;
  const memoryResonance = garden.scoreBreakdown?.memoryResonance || ecologyDailyMemoryResonanceSnapshot();
  const memoryTier = Number(memoryResonance.tier || 0);
  if (garden.activeCount <= 0 && garden.moments.length === 0 && garden.clueCount <= 0 && garden.giftCount <= 0 && memoryTier <= 0) return;

  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const x = 646;
  const y = 406;
  const width = 270;
  const height = 126;
  const accent = garden.topCombo?.comboId === "eco_moon_pond" ? "#4d91a6"
    : garden.topCombo?.comboId === "eco_flower_guest_yard" ? "#d87f8d"
      : garden.topCombo?.comboId === "eco_honey_orchard" ? "#b47d2f"
        : garden.topCombo?.comboId === "eco_night_lamp_path" ? "#b47d2f"
          : "#286f58";
  const moment = garden.featuredMoment;
  const profile = garden.featuredProfile || { base: "#fff6d7", accent, glow: "rgba(246, 240, 182, 0.24)", glyph: "灵" };
  const yardAccent = garden.tier?.accent || accent;
  const topScene = garden.sceneRows[0] || null;
  const breakdownText = `主题 ${garden.scoreBreakdown?.themeConsistency || 0}/30 · 功能 ${garden.scoreBreakdown?.functionClosure || 0}/25 · 生活 ${garden.scoreBreakdown?.lifeEvents || 0}/10`;

  ctx.save();
  ctx.fillStyle = "rgba(23, 35, 29, 0.14)";
  ctx.beginPath();
  ctx.ellipse(x + width / 2, y + height + 13, width * 0.46, 15, 0, 0, Math.PI * 2);
  ctx.fill();
  drawCanvasCard(ctx, x, y, width, height, "rgba(255, 248, 232, 0.9)");

  ctx.fillStyle = "rgba(202, 235, 210, 0.28)";
  ctx.beginPath();
  ctx.roundRect(x + 14, y + 14, 78, 88, 20);
  ctx.fill();
  ctx.strokeStyle = "rgba(40, 111, 88, 0.28)";
  ctx.lineWidth = 2;
  ctx.stroke();
  drawEcologyMemoryResonanceMarks(ctx, x, y, width, height, memoryResonance, motion, yardAccent);

  for (let i = 0; i < 5; i += 1) {
    const grassX = x + 26 + i * 12;
    const sway = settings.reducedMotion ? 0 : Math.sin(motion * 1.6 + i) * 3;
    ctx.strokeStyle = i % 2 ? "#5d8b52" : "#286f58";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(grassX, y + 92);
    ctx.quadraticCurveTo(grassX + sway, y + 70, grassX + 7 + sway, y + 58);
    ctx.stroke();
  }

  const activeMotifs = garden.activeCombos.length
    ? garden.activeCombos.slice(0, 3)
    : garden.nextCombo ? [garden.nextCombo] : [];
  activeMotifs.forEach((combo, index) => {
    drawEcologyComboMotif(ctx, combo.comboId, x + 36 + index * 24, y + 42 + (index % 2) * 8, index, motion);
  });

  if (moment) {
    const bob = settings.reducedMotion ? 0 : Math.sin(motion * 2.2) * 3;
    ctx.fillStyle = profile.glow;
    ctx.beginPath();
    ctx.arc(x + 72, y + 28 + bob, 18, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = profile.base;
    ctx.beginPath();
    ctx.arc(x + 72, y + 28 + bob, 11, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = profile.accent;
    ctx.beginPath();
    ctx.roundRect(x + 63, y + 38 + bob, 18, 18, 7);
    ctx.fill();
    ctx.fillStyle = "#fffdf5";
    ctx.font = "700 10px Microsoft YaHei";
    ctx.fillText(profile.glyph, x + 67, y + 51 + bob);
  }

  ctx.fillStyle = yardAccent;
  ctx.font = "700 12px Microsoft YaHei";
  ctx.fillText(`生态庭院 · ${garden.tier?.label || "待布置"} ${garden.score} 分`, x + 108, y + 28);
  ctx.fillStyle = "#17231d";
  ctx.font = "700 14px Microsoft YaHei";
  const comboLine = topScene
    ? `${topScene.name} · 已收 ${garden.claimedGoalCount}/${garden.totalCombos}`
    : garden.topCombo
      ? `${garden.topCombo.name} · ${garden.topCombo.effectText}`
      : garden.nextCombo
        ? `待养成：${garden.nextCombo.name}`
        : "精怪们在院里各忙各的";
  ctx.fillText(comboLine.slice(0, 18), x + 108, y + 50);

  ctx.fillStyle = "#5d6f65";
  ctx.font = "11px Microsoft YaHei";
  const momentLine = topScene
    ? topScene.text
    : moment
      ? `稀有精怪日常：${moment.spiritName}${moment.actionShort}`
      : garden.nextCombo
        ? `下一处造景：${garden.nextCombo.unlockHint}`
        : "继续布置庭院，新的精怪会留下动静";
  ctx.fillText(momentLine.slice(0, 26), x + 108, y + 70);

  ctx.fillStyle = "rgba(23, 35, 29, 0.08)";
  ctx.beginPath();
  ctx.roundRect(x + 108, y + 80, width - 124, 32, 12);
  ctx.fill();
  ctx.fillStyle = garden.readyGoalCount > 0 ? "#b47d2f" : garden.unresolvedClueCount > 0 ? "#be4f37" : yardAccent;
  ctx.font = "700 10px Microsoft YaHei";
  const claimText = garden.readyGoalCount > 0
    ? `可收录 ${garden.readyGoalCount} · ${garden.tier?.shortLabel || "初成"}继续长`
    : memoryTier > 0
      ? `${memoryResonance.label} · 已记 ${memoryResonance.nights} 夜`
      : breakdownText;
  ctx.fillText(claimText.slice(0, 22), x + 120, y + 94);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "9px Microsoft YaHei";
  const defaultNextLine = garden.topCombo
    ? `下一目标 ${garden.nextCombo ? garden.nextCombo.name : garden.claimedGoalCount >= garden.totalCombos ? "全组合已收录" : "收录现有共鸣"}`
    : garden.nextCombo?.unlockHint || "等待第一份生态共鸣";
  const nextLine = memoryTier > 0 && garden.readyGoalCount <= 0
    ? `后续夜事 心情 +${memoryResonance.moodBonus} 灵石 +${memoryResonance.goldBonus}`
    : defaultNextLine;
  ctx.fillText(nextLine.slice(0, 26), x + 120, y + 106);

  if (garden.activeCount > 0 || garden.unresolvedClueCount > 0) {
    for (let i = 0; i < 8; i += 1) {
      const moteX = x + 18 + i * 29;
      const moteY = y - 2 + Math.sin(motion * 1.8 + i) * 4;
      ctx.fillStyle = i % 2 ? "rgba(255, 253, 245, 0.82)" : "rgba(202, 235, 210, 0.78)";
      ctx.beginPath();
      ctx.arc(moteX, moteY, 2.4, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.restore();
}

