function drawEcologyLandmarkFoundation(ctx, combo, spec, motion = 0, pulse = 0) {
  if (!spec) return;
  const claimed = Boolean(combo?.claimed);
  const sway = settings.reducedMotion ? 0 : Math.sin(motion * 1.5 + spec.anchorX * 0.01) * 1.5;

  ctx.save();
  ctx.fillStyle = "rgba(23, 35, 29, 0.12)";
  ctx.beginPath();
  ctx.ellipse(spec.anchorX, spec.y + spec.height - 3, spec.width * 0.45, 10, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = claimed ? spec.glow : "rgba(255, 248, 232, 0.26)";
  ctx.beginPath();
  ctx.roundRect(spec.x, spec.y, spec.width, spec.height, 18);
  ctx.fill();
  ctx.strokeStyle = claimed ? `${spec.accent}88` : "rgba(93, 111, 101, 0.28)";
  ctx.lineWidth = claimed ? 2 : 1.2;
  ctx.stroke();

  ctx.fillStyle = claimed ? "rgba(255, 253, 245, 0.78)" : "rgba(255, 253, 245, 0.44)";
  for (let i = 0; i < (claimed ? 4 : 2); i += 1) {
    const stoneX = spec.x + 12 + i * Math.max(14, spec.width / 5);
    const stoneY = spec.y + spec.height - 12 + (i % 2) * 2;
    ctx.beginPath();
    ctx.ellipse(stoneX, stoneY, 5, 3, 0, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.fillStyle = claimed ? spec.accent : "rgba(93, 111, 101, 0.54)";
  ctx.beginPath();
  ctx.roundRect(spec.x + spec.width - 24, spec.y + 7 + sway, 18, 18, 7);
  ctx.fill();
  ctx.fillStyle = "#fffdf5";
  ctx.font = "700 10px Microsoft YaHei";
  ctx.fillText(spec.glyph, spec.x + spec.width - 20, spec.y + 20 + sway);

  if (claimed) {
    ctx.strokeStyle = "rgba(246, 240, 182, 0.58)";
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.arc(spec.anchorX, spec.anchorY, Math.min(22, spec.width * 0.24) + pulse * 0.18, 0.2, Math.PI * 1.6);
    ctx.stroke();
  }
  ctx.restore();
}

function drawEcologyLandmarkNameplate(ctx, combo, spec) {
  if (!spec) return;
  const claimed = Boolean(combo?.claimed);
  const status = claimed ? "已收录" : "共鸣中";
  const plateWidth = 68;
  const plateHeight = 24;

  ctx.save();
  ctx.globalAlpha *= claimed ? 0.94 : 0.58;
  ctx.fillStyle = "rgba(255, 248, 232, 0.86)";
  ctx.beginPath();
  ctx.roundRect(spec.labelX, spec.labelY, plateWidth, plateHeight, 9);
  ctx.fill();
  ctx.strokeStyle = claimed ? `${spec.accent}66` : "rgba(93, 111, 101, 0.22)";
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.fillStyle = claimed ? spec.accent : "#5d6f65";
  ctx.font = "700 10px Microsoft YaHei";
  ctx.fillText(spec.label, spec.labelX + 8, spec.labelY + 11);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "8px Microsoft YaHei";
  ctx.fillText(status, spec.labelX + 8, spec.labelY + 21);
  ctx.restore();
}

function ecologyLandmarkInspectionAura(comboId = "") {
  const ecologyState = syncEcologyDailyState();
  const inspectedToday = ecologyState.inspectionDay === state.day && ecologyState.inspectedCombos.includes(comboId);
  const latest = (ecologyState.inspectionHistory || []).find((entry) => entry.comboId === comboId) || null;
  if (!inspectedToday && !latest) return null;
  return {
    inspectedToday,
    latest,
    label: inspectedToday ? "今日已巡" : latest?.day ? `第${latest.day}日巡看` : "巡看留痕",
    caretakerName: latest?.caretakerName || "值守精怪",
    actionText: latest?.actionText || "照看庭院",
    summary: latest?.summary || "这里还留着上次巡看的灵息。",
  };
}

function drawEcologyLandmarkInspectionAura(ctx, combo, spec, aura, motion = 0, pulse = 0) {
  if (!spec || !aura) return;
  const accent = spec.accent || "#286f58";
  const activeAlpha = aura.inspectedToday ? 0.82 : 0.34;
  const ring = Math.min(44, Math.max(24, spec.width * 0.34)) + Math.max(0, pulse) * 0.45;

  ctx.save();
  ctx.globalAlpha *= activeAlpha;
  const glow = ctx.createRadialGradient(spec.anchorX, spec.anchorY, 6, spec.anchorX, spec.anchorY, ring * 2.4);
  glow.addColorStop(0, "rgba(246, 240, 182, 0.36)");
  glow.addColorStop(0.48, "rgba(202, 235, 210, 0.18)");
  glow.addColorStop(1, "rgba(202, 235, 210, 0)");
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(spec.anchorX, spec.anchorY, ring * 2.1, 0, Math.PI * 2);
  ctx.fill();

  ctx.strokeStyle = aura.inspectedToday ? "rgba(246, 240, 182, 0.86)" : `${accent}55`;
  ctx.lineWidth = aura.inspectedToday ? 2.4 : 1.4;
  ctx.setLineDash(aura.inspectedToday ? [8, 6] : [4, 8]);
  ctx.lineDashOffset = settings.reducedMotion ? 0 : -motion * 16;
  ctx.beginPath();
  ctx.ellipse(spec.anchorX, spec.anchorY + 5, ring, ring * 0.42, 0, 0, Math.PI * 2);
  ctx.stroke();
  ctx.setLineDash([]);

  for (let i = 0; i < (aura.inspectedToday ? 5 : 3); i += 1) {
    const angle = motion * 0.7 + i * (Math.PI * 2 / 5);
    const moteX = spec.anchorX + Math.cos(angle) * (ring * 0.78);
    const moteY = spec.anchorY + Math.sin(angle) * (ring * 0.34) - 8;
    ctx.fillStyle = i % 2 ? "rgba(246, 240, 182, 0.82)" : "rgba(255, 253, 245, 0.78)";
    ctx.beginPath();
    ctx.arc(moteX, moteY, aura.inspectedToday ? 3.1 : 2.2, 0, Math.PI * 2);
    ctx.fill();
  }

  if (aura.inspectedToday) {
    const tagX = spec.labelX + 48;
    const tagY = spec.labelY - 18;
    ctx.globalAlpha *= 0.94;
    ctx.fillStyle = "rgba(255, 248, 232, 0.9)";
    ctx.beginPath();
    ctx.roundRect(tagX, tagY, 70, 25, 10);
    ctx.fill();
    ctx.strokeStyle = `${accent}77`;
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.fillStyle = accent;
    ctx.font = "700 10px Microsoft YaHei";
    ctx.fillText("今日已巡", tagX + 10, tagY + 16);
  }

  const noteText = `${aura.caretakerName} · ${aura.actionText}`;
  const noteWidth = Math.min(136, Math.max(88, noteText.length * 9));
  const noteX = Math.max(18, Math.min(940 - noteWidth, spec.anchorX - noteWidth / 2));
  const noteY = spec.anchorY + spec.height * 0.28 + (aura.inspectedToday ? 32 : 22);
  ctx.globalAlpha *= aura.inspectedToday ? 0.88 : 0.62;
  ctx.fillStyle = "rgba(255, 253, 245, 0.82)";
  ctx.beginPath();
  ctx.roundRect(noteX, noteY, noteWidth, 25, 10);
  ctx.fill();
  ctx.fillStyle = aura.inspectedToday ? accent : "#5d6f65";
  ctx.font = "700 9px Microsoft YaHei";
  ctx.fillText(noteText.slice(0, 14), noteX + 9, noteY + 16);
  ctx.restore();
}

function drawEcologyInspectionKeepsakeFocus(ctx, combo, spec, inspection, motion = 0, pulse = 0) {
  const focus = ecologyInspectionKeepsakeWorldFocus;
  if (!combo || !spec || !inspection || !focus) return;
  if (focus.day !== state.day) {
    ecologyInspectionKeepsakeWorldFocus = null;
    return;
  }
  if (focus.comboId !== combo.comboId) return;
  const accent = spec.accent || inspection.tierAccent || "#286f58";
  const width = refs.world?.width || 960;
  const height = refs.world?.height || 640;
  const nodes = ecologyInspectionKeepsakeNodes(inspection);
  const cardWidth = 244;
  const cardHeight = 116;
  const cardX = Math.max(18, Math.min(width - cardWidth - 18, spec.anchorX - cardWidth / 2));
  const cardY = Math.max(74, Math.min(height - cardHeight - 24, spec.anchorY - cardHeight - 54 + pulse * 0.2));

  ctx.save();
  ctx.strokeStyle = `${accent}66`;
  ctx.lineWidth = 2;
  ctx.setLineDash([6, 7]);
  ctx.lineDashOffset = settings.reducedMotion ? 0 : -motion * 15;
  ctx.beginPath();
  ctx.moveTo(spec.anchorX, spec.anchorY - 8);
  ctx.quadraticCurveTo(cardX + cardWidth * 0.5, cardY + cardHeight + 26, cardX + cardWidth * 0.5, cardY + cardHeight - 2);
  ctx.stroke();
  ctx.setLineDash([]);

  ctx.fillStyle = "rgba(23, 35, 29, 0.16)";
  ctx.beginPath();
  ctx.ellipse(cardX + cardWidth * 0.5, cardY + cardHeight + 7, cardWidth * 0.34, 7, 0, 0, Math.PI * 2);
  ctx.fill();
  drawCanvasCard(ctx, cardX, cardY, cardWidth, cardHeight, "rgba(255, 248, 232, 0.96)");
  ctx.strokeStyle = accent;
  ctx.lineWidth = 2.6;
  ctx.beginPath();
  ctx.roundRect(cardX, cardY, cardWidth, cardHeight, 16);
  ctx.stroke();

  ctx.fillStyle = `${accent}22`;
  ctx.beginPath();
  ctx.roundRect(cardX + 12, cardY + 12, 38, 38, 12);
  ctx.fill();
  ctx.fillStyle = accent;
  ctx.font = "900 18px Microsoft YaHei";
  ctx.fillText("巡", cardX + 23, cardY + 37);
  ctx.fillStyle = accent;
  ctx.font = "800 11px Microsoft YaHei";
  ctx.fillText("生态巡看留签 · 可点", cardX + 60, cardY + 22);
  ctx.fillStyle = "#17231d";
  ctx.font = "800 14px Microsoft YaHei";
  ctx.fillText((inspection.landmarkLabel || inspection.comboName || "生态庭院").slice(0, 12), cardX + 60, cardY + 42);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "9px Microsoft YaHei";
  ctx.fillText("只预览定位，不会结算收益".slice(0, 20), cardX + 60, cardY + 58);

  nodes.slice(0, 3).forEach((node, index) => {
    const nodeX = cardX + 14 + index * 78;
    const nodeY = cardY + 72;
    const focused = focus.nodeKey === node.key;
    ctx.fillStyle = focused ? `${accent}22` : "rgba(255, 253, 245, 0.84)";
    ctx.strokeStyle = focused ? `${accent}88` : "rgba(93, 111, 101, 0.2)";
    ctx.lineWidth = focused ? 1.8 : 1;
    ctx.beginPath();
    ctx.roundRect(nodeX, nodeY, 68, 26, 9);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = focused ? accent : "#8f5f3f";
    ctx.font = "800 8px Microsoft YaHei";
    ctx.fillText(node.label.slice(0, 5), nodeX + 8, nodeY + 11);
    ctx.fillStyle = "#5d6f65";
    ctx.font = "8px Microsoft YaHei";
    ctx.fillText(node.title.slice(0, 6), nodeX + 8, nodeY + 22);
  });
  ctx.restore();
}

function drawEcologyCourtyardLeylines(ctx, combos, resonance, motion = 0) {
  const points = (combos || [])
    .map((combo) => {
      const spec = ecologyLandmarkVisualSpec(combo.comboId);
      return spec ? { combo, spec } : null;
    })
    .filter(Boolean);
  const memoryTier = Number(resonance?.tier || 0);
  if (points.length < 2 && memoryTier <= 0) return;

  const hub = { x: 486, y: 386 };
  const alpha = memoryTier >= 3 ? 0.42 : memoryTier >= 2 ? 0.32 : points.some(({ combo }) => combo.claimed) ? 0.22 : 0.14;
  const lineColor = memoryTier >= 3 ? "#4d91a6" : memoryTier >= 2 ? "#b47d2f" : "#286f58";

  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.strokeStyle = lineColor;
  ctx.lineWidth = memoryTier >= 3 ? 2.8 : memoryTier >= 2 ? 2.1 : 1.4;
  if (memoryTier <= 1) ctx.setLineDash([8, 10]);
  for (const { spec } of points) {
    ctx.beginPath();
    ctx.moveTo(hub.x, hub.y);
    ctx.quadraticCurveTo((hub.x + spec.anchorX) / 2, Math.min(hub.y, spec.anchorY) - 34, spec.anchorX, spec.anchorY);
    ctx.stroke();
  }
  ctx.setLineDash([]);

  if (memoryTier >= 2 && points.length >= 3) {
    ctx.globalAlpha = alpha * 0.82;
    ctx.beginPath();
    points.forEach(({ spec }, index) => {
      if (index === 0) ctx.moveTo(spec.anchorX, spec.anchorY);
      else ctx.quadraticCurveTo(hub.x, hub.y, spec.anchorX, spec.anchorY);
    });
    ctx.stroke();
  }

  if (memoryTier >= 3) {
    ctx.globalAlpha = 0.56;
    points.slice(0, 6).forEach(({ spec }, index) => {
      const t = (motion * 0.16 + index * 0.17) % 1;
      const moteX = hub.x + (spec.anchorX - hub.x) * t;
      const moteY = hub.y + (spec.anchorY - hub.y) * t - Math.sin(t * Math.PI) * 18;
      ctx.fillStyle = index % 2 ? "rgba(246, 240, 182, 0.82)" : "rgba(202, 235, 210, 0.78)";
      ctx.beginPath();
      ctx.arc(moteX, moteY, 3, 0, Math.PI * 2);
      ctx.fill();
    });
  }

  ctx.globalAlpha = memoryTier > 0 ? 0.84 : 0.52;
  ctx.fillStyle = "rgba(255, 248, 232, 0.86)";
  ctx.beginPath();
  ctx.roundRect(hub.x - 45, hub.y - 18, memoryTier > 0 ? 112 : 76, 34, 14);
  ctx.fill();
  ctx.strokeStyle = `${lineColor}66`;
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.fillStyle = lineColor;
  ctx.font = "700 11px Microsoft YaHei";
  ctx.fillText(memoryTier > 0 ? "庭院余脉" : "生态余脉", hub.x - 32, hub.y - 3);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "8px Microsoft YaHei";
  ctx.fillText(memoryTier > 0 ? resonance.label : "造景相连", hub.x - 32, hub.y + 10);
  ctx.restore();
}

