function dungeonPalette(dungeon, mechanic) {
  const text = `${dungeon?.dungeon_type || ""}${mechanic?.field_rule || ""}${mechanic?.solar_term || ""}`;
  if (text.includes("雷")) return { top: "#14211f", mid: "#304840", bottom: "#101716", accent: "#e6c65e", glow: "rgba(246, 240, 182, 0.22)", hazard: "rgba(230, 198, 94, 0.32)", boss: "#be4f37" };
  if (text.includes("水") || text.includes("谷雨")) return { top: "#10242c", mid: "#2f5e66", bottom: "#101b20", accent: "#7ac3d5", glow: "rgba(202, 235, 210, 0.22)", hazard: "rgba(77, 145, 166, 0.34)", boss: "#7f5570" };
  if (text.includes("火") || dungeon?.dungeon_type === "ruin") return { top: "#261a16", mid: "#5d3025", bottom: "#160f0d", accent: "#f0a54e", glow: "rgba(190, 79, 55, 0.26)", hazard: "rgba(190, 79, 55, 0.36)", boss: "#de5f3f" };
  if (dungeon?.dungeon_type === "nest") return { top: "#151427", mid: "#32304e", bottom: "#0e0d18", accent: "#b9a7e8", glow: "rgba(185, 167, 232, 0.22)", hazard: "rgba(126, 93, 150, 0.36)", boss: "#775a9f" };
  return { top: "#1d2521", mid: "#344136", bottom: "#171b18", accent: "#dea952", glow: "rgba(222, 169, 82, 0.16)", hazard: "rgba(222, 169, 82, 0.22)", boss: "#be4f37" };
}

function drawDungeonBar(ctx, x, y, width, height, value, max, color, label) {
  const ratio = Math.max(0, Math.min(1, Number(value || 0) / Math.max(1, Number(max || 1))));
  ctx.save();
  ctx.fillStyle = "rgba(23, 35, 29, 0.22)";
  ctx.beginPath();
  ctx.roundRect(x, y, width, height, height / 2);
  ctx.fill();
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.roundRect(x, y, width * ratio, height, height / 2);
  ctx.fill();
  ctx.fillStyle = "#fffdf5";
  ctx.font = "700 12px Microsoft YaHei";
  ctx.fillText(label, x + 10, y + height - 5);
  ctx.restore();
}

function drawDungeonTelegraph(ctx, skill, cx, cy, palette) {
  if (!skill) return;
  const target = skill.target_rule || "";
  ctx.save();
  ctx.strokeStyle = palette.accent;
  ctx.fillStyle = palette.hazard;
  ctx.lineWidth = 4;

  if (target.includes("line") || target.includes("charge") || target.includes("projectile")) {
    ctx.beginPath();
    ctx.moveTo(cx - 170, cy + 74);
    ctx.lineTo(cx + 190, cy - 40);
    ctx.stroke();
    ctx.fillStyle = palette.accent;
    ctx.beginPath();
    ctx.moveTo(cx + 190, cy - 40);
    ctx.lineTo(cx + 158, cy - 48);
    ctx.lineTo(cx + 174, cy - 12);
    ctx.closePath();
    ctx.fill();
  } else if (target.includes("arc") || target.includes("cone")) {
    ctx.beginPath();
    ctx.moveTo(cx, cy + 20);
    ctx.arc(cx, cy + 20, 138, -0.86, 0.86);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  } else if (target.includes("random") || target.includes("meteor") || target.includes("rain") || target.includes("tile")) {
    for (let i = 0; i < 6; i += 1) {
      const x = cx - 150 + ((i * 67 + state.day * 11) % 300);
      const y = cy - 88 + ((i * 43 + Number(skill.order_in_phase || 0) * 19) % 188);
      ctx.beginPath();
      ctx.arc(x, y, 18 + (i % 2) * 12, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    }
  } else if (target.includes("ring") || target.includes("pulse") || target.includes("self")) {
    ctx.beginPath();
    ctx.arc(cx, cy, 118, 0, Math.PI * 2);
    ctx.stroke();
    ctx.globalAlpha = 0.42;
    ctx.beginPath();
    ctx.arc(cx, cy, 76, 0, Math.PI * 2);
    ctx.fill();
  } else {
    ctx.beginPath();
    ctx.ellipse(cx, cy, 160, 68, -0.1, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.globalAlpha = 1;
  ctx.fillStyle = "#fffdf5";
  ctx.font = "700 15px Microsoft YaHei";
  ctx.fillText(`前摇：${skillName(skill)}`, cx - 86, cy + 148);
  ctx.restore();
}

function drawDungeonBossCounterCard(ctx, spec = null, x = 54, y = 206, width = 246, height = 118) {
  if (!spec) return;
  const accent = spec.tier === "high" ? "#be4f37" : spec.tier === "mid" ? "#b47d2f" : "#4d91a6";
  const motion = settings.reducedMotion ? 0 : Math.sin(performance.now() / 360) * 2;
  ctx.save();
  drawCanvasCard(ctx, x, y + motion, width, height, spec.tier === "high" ? "rgba(255, 246, 238, 0.9)" : "rgba(255, 253, 245, 0.86)");
  ctx.fillStyle = accent;
  ctx.font = "700 15px Microsoft YaHei";
  ctx.fillText("读招应对", x + 18, y + 27 + motion);
  ctx.fillStyle = "#17231d";
  ctx.font = "700 14px Microsoft YaHei";
  ctx.fillText(`${spec.skillLabel} · ${spec.castLabel}`.slice(0, 21), x + 18, y + 50 + motion);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "12px Microsoft YaHei";
  ctx.fillText(spec.counterMove.slice(0, 24), x + 18, y + 73 + motion);
  ctx.fillStyle = accent;
  ctx.font = "700 12px Microsoft YaHei";
  ctx.fillText(`窗口：${spec.counterWindow}`.slice(0, 22), x + 18, y + 94 + motion);
  ctx.fillStyle = "rgba(23, 35, 29, 0.08)";
  ctx.beginPath();
  ctx.roundRect(x + width - 58, y + 22 + motion, 36, 62, 16);
  ctx.fill();
  ctx.strokeStyle = accent;
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(x + width - 48, y + 42 + motion);
  ctx.lineTo(x + width - 28, y + 42 + motion);
  ctx.moveTo(x + width - 38, y + 32 + motion);
  ctx.lineTo(x + width - 38, y + 62 + motion);
  ctx.stroke();
  ctx.fillStyle = accent;
  ctx.font = "700 11px Microsoft YaHei";
  ctx.fillText(spec.tier === "high" ? "危" : "躲", x + width - 45, y + 78 + motion);
  ctx.restore();
}

function drawDungeonEnemyShape(ctx, enemy, x, y, scale, palette) {
  const size = 72 * scale;
  ctx.save();
  ctx.fillStyle = "rgba(23, 35, 29, 0.28)";
  ctx.beginPath();
  ctx.ellipse(x, y + size * 0.46, size * 0.92, size * 0.18, 0, 0, Math.PI * 2);
  ctx.fill();

  const ai = enemy?.ai_type || "charge";
  ctx.fillStyle = ai.includes("spore") || ai.includes("swarm") ? "#7a8f54" : ai.includes("burrow") || ai.includes("orbit") ? "#be4f37" : ai.includes("drain") || ai.includes("guard") ? "#4c3f67" : palette.accent;
  ctx.beginPath();
  if (ai === "dive") {
    ctx.moveTo(x - size * 0.76, y - size * 0.08);
    ctx.lineTo(x, y - size * 0.42);
    ctx.lineTo(x + size * 0.76, y - size * 0.08);
    ctx.lineTo(x, y + size * 0.34);
    ctx.closePath();
  } else if (ai === "guard") {
    ctx.roundRect(x - size * 0.48, y - size * 0.42, size * 0.96, size * 0.92, 18);
  } else {
    ctx.ellipse(x, y, size * 0.56, size * 0.44, 0, 0, Math.PI * 2);
  }
  ctx.fill();

  ctx.fillStyle = "#fffdf5";
  ctx.beginPath();
  ctx.arc(x - size * 0.18, y - size * 0.06, 4.5 * scale, 0, Math.PI * 2);
  ctx.arc(x + size * 0.18, y - size * 0.06, 4.5 * scale, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "#fffdf5";
  ctx.font = `700 ${Math.round(16 * scale)}px Microsoft YaHei`;
  ctx.fillText(enemyName(enemy), x - size * 0.58, y + size * 0.74);
  ctx.restore();
}

function drawDungeonLootNodes(ctx, run, width, height, palette) {
  const loot = (run.lastLoot?.length ? run.lastLoot : run.loot?.slice(-3)) || [];
  ctx.save();
  for (let i = 0; i < Math.max(loot.length, 3); i += 1) {
    const entry = loot[i];
    const x = width - 210 + i * 48;
    const y = height - 128 + ((i + run.turn) % 2) * 22;
    const pulse = settings.reducedMotion ? 0 : Math.sin((performance.now() + i * 130) / 360) * 4;
    ctx.fillStyle = entry ? palette.accent : "rgba(255, 253, 245, 0.24)";
    ctx.beginPath();
    ctx.moveTo(x, y - 18 - pulse);
    ctx.lineTo(x + 16, y);
    ctx.lineTo(x, y + 18 + pulse);
    ctx.lineTo(x - 16, y);
    ctx.closePath();
    ctx.fill();
    if (entry) {
      ctx.fillStyle = "#fffdf5";
      ctx.font = "700 12px Microsoft YaHei";
      ctx.fillText(`x${entry.count}`, x + 14, y + 5);
    }
  }
  ctx.restore();
}

function drawDungeonSkillBadges(ctx, run, x, y) {
  const lines = (run.skillLog || []).slice(0, 3);
  ctx.save();
  lines.forEach((line, index) => {
    ctx.fillStyle = "rgba(255, 253, 245, 0.78)";
    ctx.beginPath();
    ctx.roundRect(x, y + index * 38, 330, 30, 12);
    ctx.fill();
    ctx.fillStyle = "#17231d";
    ctx.font = "12px Microsoft YaHei";
    ctx.fillText(line.length > 28 ? `${line.slice(0, 28)}...` : line, x + 14, y + index * 38 + 20);
  });
  ctx.restore();
}

function drawDungeonMechanicWorldCard(ctx, hud, x = 598, y = 48, width = 280, height = 188) {
  if (!hud) return;
  const theme = hud.theme || dungeonMechanicTheme(hud.tone);
  const chipPalette = {
    good: theme.soft,
    neutral: "rgba(255, 253, 245, 0.72)",
    warn: "rgba(190, 79, 55, 0.12)",
    done: "rgba(40, 111, 88, 0.14)",
  };
  drawCanvasCard(ctx, x, y, width, height, theme.card);

  ctx.save();
  ctx.fillStyle = "#17231d";
  ctx.font = "700 17px Microsoft YaHei";
  ctx.fillText(hud.title, x + 22, y + 30);
  ctx.fillStyle = theme.accent;
  ctx.font = "700 12px Microsoft YaHei";
  ctx.fillText(hud.caption.slice(0, 8), x + width - 72, y + 30);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "13px Microsoft YaHei";
  ctx.fillText(hud.summary.slice(0, 22), x + 22, y + 54);

  ctx.fillStyle = "rgba(23, 35, 29, 0.1)";
  ctx.beginPath();
  ctx.roundRect(x + 22, y + 66, width - 44, 10, 999);
  ctx.fill();
  ctx.fillStyle = theme.accent;
  ctx.beginPath();
  ctx.roundRect(x + 22, y + 66, Math.max(26, (width - 44) * (hud.progressPercent / 100)), 10, 999);
  ctx.fill();

  ctx.fillStyle = "#5d6f65";
  ctx.font = "12px Microsoft YaHei";
  ctx.fillText(hud.progressText.slice(0, 30), x + 22, y + 92);

  hud.tags.slice(0, 3).forEach((tag, index) => {
    const chipX = x + 22 + index * 80;
    ctx.fillStyle = chipPalette[tag.state] || chipPalette.neutral;
    ctx.beginPath();
    ctx.roundRect(chipX, y + 104, 72, 22, 11);
    ctx.fill();
    ctx.fillStyle = tag.state === "warn" ? "#be4f37" : tag.state === "good" || tag.state === "done" ? "#286f58" : "#5d6f65";
    ctx.font = "700 11px Microsoft YaHei";
    ctx.fillText(tag.label.slice(0, 6), chipX + 8, y + 119);
  });

  const columns = Math.max(1, Math.min(4, hud.nodes.length || 1));
  const nodeWidth = Math.floor((width - 44 - (columns - 1) * 8) / columns);
  hud.nodes.slice(0, 8).forEach((node, index) => {
    const column = index % columns;
    const row = Math.floor(index / columns);
    const nodeX = x + 22 + column * (nodeWidth + 8);
    const nodeY = y + 134 + row * 24;
    ctx.fillStyle = node.active ? theme.soft : "rgba(255, 253, 245, 0.66)";
    if (node.state === "warn" && node.active) ctx.fillStyle = "rgba(190, 79, 55, 0.14)";
    ctx.beginPath();
    ctx.roundRect(nodeX, nodeY, nodeWidth, 20, 10);
    ctx.fill();
    ctx.strokeStyle = node.emphasis ? theme.accent : "rgba(23, 35, 29, 0.08)";
    ctx.lineWidth = node.emphasis ? 2 : 1;
    ctx.stroke();
    ctx.fillStyle = node.active ? "#17231d" : "#5d6f65";
    ctx.font = "700 11px Microsoft YaHei";
    ctx.fillText(node.label.slice(0, 4), nodeX + 8, nodeY + 14);
  });
  ctx.restore();
}

function dungeonSpiritSolutionVisualSpec(solution = dungeonSpiritSolutionSpec()) {
  if (!solution?.active || !solution.primary) return null;
  const spirit = state.spirits.find((entry) => entry.id === solution.primary.spiritId) || state.spirits[0];
  const profile = spirit ? spiritVisualProfile(spirit) : { accent: "#e0b66d", base: "#fffdf5", glow: "rgba(246, 240, 182, 0.24)", glyph: "灵" };
  const visualMap = {
    雷竹: { mode: "thunder", label: "雷纹引柱", anchor: { x: 112, y: 386 }, target: { x: 674, y: 256 } },
    灯影: { mode: "lantern", label: "灯影照路", anchor: { x: 112, y: 386 }, target: { x: 674, y: 212 } },
    月莲: { mode: "mirror", label: "月莲压影", anchor: { x: 112, y: 386 }, target: { x: 674, y: 468 } },
    花铃: { mode: "insect", label: "铃音定拍", anchor: { x: 112, y: 386 }, target: { x: 674, y: 260 } },
    蜂蜜: { mode: "honey", label: "甜香引群", anchor: { x: 112, y: 386 }, target: { x: 410, y: 356 } },
    书契: { mode: "ledger", label: "账页标路", anchor: { x: 112, y: 386 }, target: { x: 674, y: 260 } },
    水运: { mode: "water", label: "水线接渠", anchor: { x: 112, y: 386 }, target: { x: 674, y: 456 } },
    火候: { mode: "flame", label: "暖火护身", anchor: { x: 112, y: 386 }, target: { x: 674, y: 304 } },
    采集: { mode: "gather", label: "灵压探点", anchor: { x: 112, y: 386 }, target: { x: 410, y: 356 } },
  };
  const visual = visualMap[solution.primary.key] || { mode: "spirit", label: "精怪解法", anchor: { x: 112, y: 386 }, target: { x: 674, y: 260 } };
  return {
    ...visual,
    key: solution.primary.key,
    ability: solution.primary.ability,
    spiritName: solution.primary.spiritName,
    shortImpact: solution.primary.shortImpact,
    profile,
    tone: solution.tone,
    active: solution.active,
  };
}

function drawDungeonSpiritSolutionMotif(ctx, spec, x, y, motion = 0) {
  if (!spec) return;
  const profile = spec.profile;
  ctx.save();
  ctx.translate(x, y);
  ctx.strokeStyle = profile.accent;
  ctx.fillStyle = profile.accent;
  ctx.lineWidth = 2.5;
  if (spec.mode === "thunder") {
    ctx.beginPath();
    ctx.moveTo(-10, -18);
    ctx.lineTo(6, -2);
    ctx.lineTo(-4, 2);
    ctx.lineTo(12, 20);
    ctx.stroke();
  } else if (spec.mode === "lantern") {
    ctx.beginPath();
    ctx.roundRect(-12, -16, 24, 30, 8);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(0, motion, 7, 0, Math.PI * 2);
    ctx.fill();
  } else if (spec.mode === "mirror" || spec.mode === "water") {
    ctx.beginPath();
    ctx.ellipse(0, 0, 22, 10, 0, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-18, 6 + motion);
    ctx.quadraticCurveTo(0, 12 - motion, 18, 6 + motion);
    ctx.stroke();
  } else if (spec.mode === "insect") {
    for (let i = 0; i < 3; i += 1) {
      ctx.beginPath();
      ctx.arc(0, 0, 10 + i * 7 + motion, -0.4, Math.PI * 1.4);
      ctx.stroke();
    }
  } else if (spec.mode === "honey") {
    for (let i = 0; i < 5; i += 1) {
      ctx.beginPath();
      ctx.arc(-14 + i * 7, Math.sin(i + motion) * 5, 4, 0, Math.PI * 2);
      ctx.fill();
    }
  } else if (spec.mode === "ledger") {
    ctx.beginPath();
    ctx.roundRect(-16, -18, 32, 36, 5);
    ctx.stroke();
    for (let i = 0; i < 3; i += 1) {
      ctx.beginPath();
      ctx.moveTo(-9, -7 + i * 9);
      ctx.lineTo(10, -7 + i * 9);
      ctx.stroke();
    }
  } else if (spec.mode === "flame") {
    ctx.beginPath();
    ctx.moveTo(0, -22);
    ctx.bezierCurveTo(18, -4, 12, 18, 0, 22);
    ctx.bezierCurveTo(-14, 12, -14, -2, 0, -22);
    ctx.fill();
  } else if (spec.mode === "gather") {
    ctx.beginPath();
    ctx.arc(0, 0, 18, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-22, 0);
    ctx.lineTo(22, 0);
    ctx.moveTo(0, -22);
    ctx.lineTo(0, 22);
    ctx.stroke();
  } else {
    ctx.font = "700 22px Microsoft YaHei";
    ctx.fillText(profile.glyph || "灵", -11, 8);
  }
  ctx.restore();
}

function drawDungeonSpiritSolutionTrace(ctx, run = state.dungeon, mechanic = currentDungeonMechanic(), dungeon = currentDungeonConfig(), solution = dungeonSpiritSolutionSpec(run, mechanic, dungeon)) {
  const spec = dungeonSpiritSolutionVisualSpec(solution);
  if (!run || !spec) return;
  const theme = dungeonMechanicTheme(spec.tone);
  const now = settings.reducedMotion ? 0 : performance.now();
  const motion = settings.reducedMotion ? 0 : Math.sin(now / 360) * 4;
  const progress = settings.reducedMotion ? 0.72 : (Math.sin(now / 980) + 1) / 2;
  const ax = spec.anchor.x;
  const ay = spec.anchor.y;
  const tx = spec.target.x;
  const ty = spec.target.y;
  const mx = ax + (tx - ax) * 0.52;
  const my = Math.min(ay, ty) - 92 - motion;

  ctx.save();
  ctx.globalAlpha = 0.74;
  ctx.strokeStyle = spec.profile.accent || theme.accent;
  ctx.lineWidth = 5;
  ctx.setLineDash([16, 12]);
  ctx.lineDashOffset = -now / 46;
  ctx.beginPath();
  ctx.moveTo(ax + 58, ay + 74);
  ctx.quadraticCurveTo(mx, my, tx, ty);
  ctx.stroke();
  ctx.setLineDash([]);

  ctx.globalAlpha = 0.32;
  ctx.strokeStyle = theme.glow;
  ctx.lineWidth = 14;
  ctx.beginPath();
  ctx.moveTo(ax + 58, ay + 74);
  ctx.quadraticCurveTo(mx, my, tx, ty);
  ctx.stroke();

  const beadT = 0.18 + progress * 0.72;
  const beadX = (1 - beadT) * (1 - beadT) * (ax + 58) + 2 * (1 - beadT) * beadT * mx + beadT * beadT * tx;
  const beadY = (1 - beadT) * (1 - beadT) * (ay + 74) + 2 * (1 - beadT) * beadT * my + beadT * beadT * ty;
  ctx.globalAlpha = 0.92;
  ctx.fillStyle = spec.profile.glow || theme.glow;
  ctx.beginPath();
  ctx.arc(beadX, beadY, 18 + motion / 2, 0, Math.PI * 2);
  ctx.fill();
  drawDungeonSpiritSolutionMotif(ctx, spec, beadX, beadY, motion / 4);

  ctx.globalAlpha = 0.9;
  drawCanvasCard(ctx, 248, 500, 286, 58, "rgba(255, 253, 245, 0.76)");
  ctx.fillStyle = spec.profile.accent || theme.accent;
  ctx.font = "700 13px Microsoft YaHei";
  ctx.fillText(spec.label, 270, 522);
  ctx.fillStyle = "#17231d";
  ctx.font = "700 14px Microsoft YaHei";
  ctx.fillText(`${spec.spiritName} · ${spec.ability}`.slice(0, 22), 270, 544);
  ctx.restore();
}

function drawDungeonSpiritSolutionWorldCard(ctx, solution = dungeonSpiritSolutionSpec(), x = 598, y = 244, width = 280, height = 126) {
  const spec = dungeonSpiritSolutionVisualSpec(solution);
  if (!spec) return;
  const theme = dungeonMechanicTheme(spec.tone);
  const motion = settings.reducedMotion ? 0 : Math.sin(performance.now() / 420) * 3;
  drawCanvasCard(ctx, x, y, width, height, "rgba(255, 253, 245, 0.82)");
  ctx.save();
  ctx.fillStyle = spec.profile.glow || theme.soft;
  ctx.beginPath();
  ctx.roundRect(x + 18, y + 18, 54, 54, 18);
  ctx.fill();
  drawDungeonSpiritSolutionMotif(ctx, spec, x + 45, y + 45 + motion / 2, motion / 4);
  ctx.fillStyle = "#17231d";
  ctx.font = "700 16px Microsoft YaHei";
  ctx.fillText("精怪解法入场", x + 86, y + 34);
  ctx.fillStyle = spec.profile.accent || theme.accent;
  ctx.font = "700 13px Microsoft YaHei";
  ctx.fillText(`${spec.spiritName} · ${spec.ability}`.slice(0, 20), x + 86, y + 56);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "12px Microsoft YaHei";
  ctx.fillText((solution.primary?.shortImpact || spec.shortImpact || "机关容错提高").slice(0, 26), x + 86, y + 78);
  ctx.fillStyle = "rgba(23, 35, 29, 0.1)";
  ctx.beginPath();
  ctx.roundRect(x + 22, y + 94, width - 44, 8, 999);
  ctx.fill();
  ctx.fillStyle = spec.profile.accent || theme.accent;
  ctx.beginPath();
  ctx.roundRect(x + 22, y + 94, Math.max(38, (width - 44) * 0.72), 8, 999);
  ctx.fill();
  ctx.fillStyle = "#5d6f65";
  ctx.font = "11px Microsoft YaHei";
  ctx.fillText("画面反馈：光轨正在把随行精怪接入节气机关", x + 22, y + 118);
  ctx.restore();
}

function drawDungeonFirstMechanicTheater(ctx, spec = dungeonFirstMechanicTheaterSpec()) {
  if (!spec?.rect) return false;
  const { rect, theme } = spec;
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const pulse = settings.reducedMotion ? 0 : Math.sin(motion * 1.9) * 2.2;
  const active = dungeonFirstMechanicTheaterFocus?.day === state.day
    && dungeonFirstMechanicTheaterFocus?.key === spec.key;
  const cardY = rect.y + pulse;
  const rows = [
    { label: "场规", text: spec.ruleText, color: theme.accent },
    { label: "解法", text: spec.puzzleText, color: theme.glow },
    { label: "精怪", text: spec.solutionText, color: spec.exactImpact.includes("未触发") ? "#b47d2f" : "#286f58" },
    { label: "保底", text: spec.failureText, color: "#8f5f3f" },
  ];

  ctx.save();
  ctx.strokeStyle = active ? `${theme.accent}cc` : `${theme.accent}66`;
  ctx.lineWidth = active ? 3 : 2;
  ctx.setLineDash([9, 9]);
  ctx.lineDashOffset = settings.reducedMotion ? 0 : -motion * 12;
  ctx.beginPath();
  ctx.moveTo(610, 258);
  ctx.quadraticCurveTo(rect.x + rect.width + 28, cardY + 42, rect.x + rect.width - 12, cardY + 96);
  ctx.stroke();
  ctx.setLineDash([]);

  drawCanvasCard(ctx, rect.x, cardY, rect.width, rect.height, "rgba(255, 253, 245, 0.92)");
  ctx.strokeStyle = active ? theme.accent : `${theme.accent}88`;
  ctx.lineWidth = active ? 3 : 2;
  ctx.beginPath();
  ctx.roundRect(rect.x, cardY, rect.width, rect.height, 18);
  ctx.stroke();

  drawDungeonMechanicWorldGlyph(ctx, spec, rect.x + 14, cardY + 14, 58, motion);
  ctx.fillStyle = theme.accent;
  ctx.font = "900 11px Microsoft YaHei";
  ctx.fillText(spec.title.slice(0, 18), rect.x + 86, cardY + 22);
  ctx.fillStyle = "#17231d";
  ctx.font = "900 16px Microsoft YaHei";
  ctx.fillText(spec.headline.slice(0, 18), rect.x + 86, cardY + 46);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "800 9px Microsoft YaHei";
  ctx.fillText(`${spec.statusText} · ${spec.actionText}`.slice(0, 38), rect.x + 86, cardY + 64);

  rows.forEach((row, index) => {
    const rowX = rect.x + 18 + (index % 2) * 136;
    const rowY = cardY + 82 + Math.floor(index / 2) * 35;
    ctx.fillStyle = index === 2 && !spec.exactImpact.includes("未触发")
      ? "rgba(237, 243, 223, 0.82)"
      : "rgba(255, 248, 232, 0.78)";
    ctx.strokeStyle = `${row.color}44`;
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.roundRect(rowX, rowY, 126, 28, 11);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = row.color;
    ctx.font = "900 8px Microsoft YaHei";
    ctx.fillText(row.label, rowX + 8, rowY + 11);
    ctx.fillStyle = "#17231d";
    ctx.font = "800 8px Microsoft YaHei";
    ctx.fillText(String(row.text || "").slice(0, 12), rowX + 8, rowY + 23);
  });

  ctx.fillStyle = "rgba(255, 253, 245, 0.9)";
  ctx.beginPath();
  ctx.roundRect(rect.x + 16, cardY + rect.height - 20, rect.width - 32, 15, 8);
  ctx.fill();
  ctx.fillStyle = "#8f5f3f";
  ctx.font = "900 8px Microsoft YaHei";
  ctx.fillText(`奖励焦点：${spec.rewardText} · 不会自动探索/顺应节气/Boss`.slice(0, 46), rect.x + 24, cardY + rect.height - 9);
  ctx.restore();
  return true;
}

function dungeonMechanicAtmosphereSpec(run = state.dungeon, mechanic = currentDungeonMechanic(), dungeon = currentDungeonConfig(), hud = dungeonMechanicHudSpec(run, mechanic, dungeon)) {
  const mechanicState = syncDungeonMechanicState(run, mechanic, dungeon);
  if (!run || !mechanic || !mechanicState || !hud) return null;
  const base = {
    tone: hud.tone,
    theme: hud.theme || dungeonMechanicTheme(hud.tone),
    title: "节气场域",
    name: "灵雾场域",
    label: mechanic.field_rule || "灵气正在改写秘境。",
    intensity: Math.max(0.18, Math.min(1, (hud.progressCurrent + 1) / Math.max(1, hud.progressMax + 1))),
  };
  switch (mechanic.dungeon_id) {
    case "dsm_001":
      return { ...base, name: "雷声场域", label: mechanicState.resonanceTurn ? "雷声将至，雷木柱在等一次共振。" : "余震还没散，地脉里有金色裂光。", intensity: Math.max(base.intensity, mechanicState.resonanceTurn ? 0.72 : 0.42) };
    case "dsm_002":
      return { ...base, name: "水位线", label: `${["浅水", "平水", "丰水"][mechanicState.waterLevel] || "平水"}正在涨落，闸口会随水线明暗。`, intensity: Math.max(base.intensity, (mechanicState.waterLevel + 1) / 3) };
    case "dsm_003":
      return { ...base, name: "虫鸣回廊", label: `${["前拍", "正拍", "回拍"][mechanicState.cadence] || "正拍"}的虫鸣把林道一层层推开。`, intensity: Math.max(base.intensity, mechanicState.cadence === 1 ? 0.72 : 0.46) };
    case "dsm_004":
      return { ...base, name: "满溢灵压", label: `满溢值 ${mechanicState.overflow}/5，越亮的地方越可能藏高收益。`, intensity: Math.max(base.intensity, mechanicState.overflow / 5) };
    case "dsm_005":
      return { ...base, name: "镜湖倒路", label: `倒影里已验出 ${mechanicState.verifiedPaths}/3 段真路。`, intensity: Math.max(base.intensity, (mechanicState.verifiedPaths + 1) / 4) };
    case "dsm_006":
      return { ...base, name: "寒露霜环", label: `霜寒层数 ${mechanicState.coldStacks}/4，边缘结霜越厚行动越吃紧。`, intensity: Math.max(base.intensity, mechanicState.coldStacks / 4) };
    case "dsm_007":
      return { ...base, name: "落叶风脉", label: mechanicState.windShift ? "逆风正在覆路，叶线会把旧路重新遮住。" : "顺风正在露路，叶线指向能走的旧阶。", intensity: Math.max(base.intensity, (mechanicState.routeMarks + 1) / 4) };
    case "dsm_008":
      return { ...base, name: "灯路影链", label: `长灯链 ${mechanicState.lanternChain}/7，灯火越连贯影路越稳定。`, intensity: Math.max(base.intensity, mechanicState.lanternChain / 7) };
    default:
      return base;
  }
}

function drawDungeonMechanicAtmosphere(ctx, width, height, run = state.dungeon, mechanic = currentDungeonMechanic(), dungeon = currentDungeonConfig(), hud = dungeonMechanicHudSpec(run, mechanic, dungeon)) {
  const mechanicState = syncDungeonMechanicState(run, mechanic, dungeon);
  const spec = dungeonMechanicAtmosphereSpec(run, mechanic, dungeon, hud);
  if (!run || !mechanicState || !spec) return;
  const { theme, tone } = spec;
  const now = settings.reducedMotion ? 0 : performance.now();
  const wave = settings.reducedMotion ? 0 : Math.sin(now / 620) * 1;
  const slowWave = settings.reducedMotion ? 0 : Math.sin(now / 1120) * 1;

  ctx.save();
  const fieldGlow = ctx.createRadialGradient(674, 262, 24, 674, 262, 420);
  fieldGlow.addColorStop(0, theme.soft);
  fieldGlow.addColorStop(0.56, `rgba(255, 253, 245, ${0.04 + spec.intensity * 0.08})`);
  fieldGlow.addColorStop(1, "rgba(255, 253, 245, 0)");
  ctx.fillStyle = fieldGlow;
  ctx.fillRect(0, 0, width, height);

  switch (tone) {
    case "thunder": {
      ctx.strokeStyle = "rgba(246, 240, 182, 0.2)";
      ctx.lineWidth = 2;
      for (let i = 0; i < 7; i += 1) {
        const x = 112 + i * 118;
        ctx.beginPath();
        ctx.moveTo(x, 28);
        ctx.lineTo(x + 20 + wave * 6, 84);
        ctx.lineTo(x - 8, 124);
        ctx.lineTo(x + 28, 178);
        ctx.stroke();
      }
      ctx.strokeStyle = theme.glow;
      ctx.lineWidth = mechanicState.resonanceTurn ? 4 : 2;
      [582, 674, 766].forEach((x, index) => {
        ctx.globalAlpha = index < mechanicState.pillarsLit || mechanicState.resonanceTurn ? 0.5 : 0.18;
        ctx.beginPath();
        ctx.arc(x, 392, 58 + index * 14 + wave * 8, 0, Math.PI * 2);
        ctx.stroke();
      });
      break;
    }
    case "water": {
      const waterTop = 498 - mechanicState.waterLevel * 38 + slowWave * 6;
      ctx.fillStyle = "rgba(77, 145, 166, 0.12)";
      ctx.fillRect(0, waterTop, width, height - waterTop);
      for (let i = 0; i < 5; i += 1) {
        ctx.strokeStyle = i === mechanicState.waterLevel + 1 ? theme.glow : "rgba(255, 253, 245, 0.18)";
        ctx.lineWidth = i === mechanicState.waterLevel + 1 ? 4 : 2;
        ctx.beginPath();
        const y = waterTop + i * 22;
        ctx.moveTo(84, y);
        for (let x = 84; x <= width - 84; x += 60) {
          ctx.quadraticCurveTo(x + 30, y + Math.sin((x + now / 12) / 34) * 8, x + 60, y);
        }
        ctx.stroke();
      }
      break;
    }
    case "insect": {
      for (let i = 0; i < 6; i += 1) {
        const active = i % 3 === mechanicState.cadence;
        ctx.strokeStyle = active ? "rgba(202, 235, 210, 0.48)" : "rgba(255, 253, 245, 0.15)";
        ctx.lineWidth = active ? 4 : 2;
        ctx.beginPath();
        ctx.arc(160 + i * 86, 292 + Math.sin(i) * 26, 38 + i * 10 + wave * 5, -0.3, Math.PI * 1.35);
        ctx.stroke();
      }
      ctx.fillStyle = theme.soft;
      for (let i = 0; i < 18; i += 1) {
        const x = 90 + ((i * 71 + run.turn * 13) % (width - 180));
        const y = 170 + ((i * 43 + run.floor * 19) % 250);
        ctx.beginPath();
        ctx.arc(x, y + wave * 6, 3 + (i % 3), 0, Math.PI * 2);
        ctx.fill();
      }
      break;
    }
    case "overflow": {
      const pressure = mechanicState.overflow / 5;
      const overflowGradient = ctx.createLinearGradient(0, height - 220, 0, height);
      overflowGradient.addColorStop(0, "rgba(224, 182, 109, 0)");
      overflowGradient.addColorStop(1, `rgba(224, 182, 109, ${0.16 + pressure * 0.16})`);
      ctx.fillStyle = overflowGradient;
      ctx.fillRect(0, height - 240, width, 240);
      for (let i = 0; i < 20; i += 1) {
        const x = 86 + ((i * 83 + run.turn * 31) % (width - 172));
        const y = height - 78 - ((i * 27 + run.floor * 17) % 136);
        ctx.fillStyle = i % 3 === 0 ? "rgba(190, 79, 55, 0.22)" : theme.soft;
        ctx.beginPath();
        ctx.arc(x, y - wave * 8, 5 + pressure * 8 + (i % 2) * 4, 0, Math.PI * 2);
        ctx.fill();
      }
      break;
    }
    case "mirror": {
      ctx.fillStyle = "rgba(159, 209, 223, 0.12)";
      ctx.beginPath();
      ctx.ellipse(width / 2, height - 128, width * 0.42, 58, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = "rgba(255, 253, 245, 0.28)";
      ctx.lineWidth = 2;
      for (let i = 0; i < 4; i += 1) {
        ctx.beginPath();
        ctx.ellipse(width / 2, height - 128 + i * 7, width * (0.24 + i * 0.06), 16 + i * 6, 0, 0, Math.PI * 2);
        ctx.stroke();
      }
      ctx.globalAlpha = 0.22 + mechanicState.verifiedPaths * 0.08;
      ctx.fillStyle = theme.glow;
      ctx.beginPath();
      ctx.roundRect(626, height - 194, 96, 82, 36);
      ctx.fill();
      break;
    }
    case "frost": {
      const frostAlpha = 0.08 + mechanicState.coldStacks * 0.035;
      const frostGradient = ctx.createRadialGradient(width / 2, height / 2, 120, width / 2, height / 2, 560);
      frostGradient.addColorStop(0, "rgba(255, 255, 255, 0)");
      frostGradient.addColorStop(1, `rgba(202, 235, 210, ${frostAlpha})`);
      ctx.fillStyle = frostGradient;
      ctx.fillRect(0, 0, width, height);
      ctx.strokeStyle = "rgba(255, 255, 255, 0.32)";
      ctx.lineWidth = 2;
      for (let i = 0; i < 10; i += 1) {
        const x = 42 + i * 92;
        const y = i % 2 ? 56 : height - 60;
        ctx.beginPath();
        ctx.moveTo(x - 14, y);
        ctx.lineTo(x + 14, y);
        ctx.moveTo(x, y - 14);
        ctx.lineTo(x, y + 14);
        ctx.stroke();
      }
      break;
    }
    case "wind": {
      const direction = mechanicState.windShift ? -1 : 1;
      for (let i = 0; i < 7; i += 1) {
        const y = 132 + i * 58;
        const startX = direction > 0 ? 44 : width - 44;
        const endX = direction > 0 ? width - 74 : 74;
        ctx.strokeStyle = i < mechanicState.routeMarks + 2 ? "rgba(242, 210, 139, 0.32)" : "rgba(255, 253, 245, 0.12)";
        ctx.lineWidth = i < mechanicState.routeMarks + 2 ? 4 : 2;
        ctx.beginPath();
        ctx.moveTo(startX, y);
        ctx.bezierCurveTo(startX + direction * 180, y - 42, endX - direction * 210, y + 44 + wave * 12, endX, y - 8);
        ctx.stroke();
      }
      ctx.fillStyle = "rgba(180, 125, 47, 0.22)";
      for (let i = 0; i < 18; i += 1) {
        const x = 86 + ((i * 67 + run.turn * 29) % (width - 172));
        const y = 120 + ((i * 41 + run.floor * 23) % (height - 240));
        ctx.beginPath();
        ctx.ellipse(x, y + wave * 10, 12, 5, direction * 0.45, 0, Math.PI * 2);
        ctx.fill();
      }
      break;
    }
    case "lantern": {
      ctx.fillStyle = "rgba(91, 51, 40, 0.16)";
      ctx.beginPath();
      ctx.moveTo(84, height - 82);
      ctx.bezierCurveTo(264, height - 238, 506, height - 182, 674, 320);
      ctx.bezierCurveTo(750, 256, 784, 224, 832, 168);
      ctx.lineTo(860, 188);
      ctx.bezierCurveTo(780, 286, 754, 342, 674, 386);
      ctx.bezierCurveTo(490, height - 112, 260, height - 118, 92, height - 38);
      ctx.closePath();
      ctx.fill();
      let previous = null;
      for (let i = 0; i < 7; i += 1) {
        const lit = i < mechanicState.lanternChain;
        const t = i / 6;
        const x = 116 + t * 650;
        const y = height - 92 - Math.sin(t * Math.PI) * 238;
        if (previous) {
          ctx.strokeStyle = lit ? "rgba(240, 165, 78, 0.34)" : "rgba(255, 253, 245, 0.1)";
          ctx.lineWidth = 4;
          ctx.beginPath();
          ctx.moveTo(previous.x, previous.y);
          ctx.lineTo(x, y);
          ctx.stroke();
        }
        ctx.fillStyle = lit ? theme.glow : "rgba(255, 253, 245, 0.12)";
        ctx.beginPath();
        ctx.arc(x, y + wave * 5, lit ? 13 : 8, 0, Math.PI * 2);
        ctx.fill();
        previous = { x, y };
      }
      break;
    }
    default: {
      ctx.fillStyle = "rgba(255, 253, 245, 0.1)";
      for (let i = 0; i < 10; i += 1) {
        ctx.beginPath();
        ctx.ellipse(92 + i * 88, 170 + (i % 4) * 54 + wave * 8, 42, 16, -0.12, 0, Math.PI * 2);
        ctx.fill();
      }
      break;
    }
  }

  ctx.globalAlpha = 0.88;
  drawCanvasCard(ctx, 72, 202, 292, 62, "rgba(255, 253, 245, 0.72)");
  ctx.fillStyle = theme.accent;
  ctx.font = "700 12px Microsoft YaHei";
  ctx.fillText(spec.title, 94, 224);
  ctx.fillStyle = "#17231d";
  ctx.font = "700 17px Microsoft YaHei";
  ctx.fillText(spec.name.slice(0, 10), 94, 247);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "12px Microsoft YaHei";
  ctx.fillText(spec.label.slice(0, 31), 178, 247);
  ctx.restore();
}

function drawActiveDungeonMechanicOverlay(ctx, width, height, run = state.dungeon, mechanic = currentDungeonMechanic(), dungeon = currentDungeonConfig(), hud = dungeonMechanicHudSpec(run, mechanic, dungeon)) {
  const mechanicState = syncDungeonMechanicState(run, mechanic, dungeon);
  if (!run || !mechanic || !mechanicState || !hud) return;
  const theme = hud.theme || dungeonMechanicTheme(hud.tone);
  const pulse = settings.reducedMotion ? 0 : Math.sin(performance.now() / 420) * 6;

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  switch (hud.tone) {
    case "thunder": {
      const positions = [582, 674, 766];
      positions.forEach((x, index) => {
        const lit = index < mechanicState.pillarsLit;
        ctx.fillStyle = lit ? theme.soft : "rgba(255, 253, 245, 0.08)";
        ctx.beginPath();
        ctx.roundRect(x - 14, 404, 28, 96, 14);
        ctx.fill();
        ctx.fillStyle = lit ? theme.glow : "rgba(255, 253, 245, 0.14)";
        ctx.beginPath();
        ctx.arc(x, 390, lit ? 16 + pulse / 3 : 10, 0, Math.PI * 2);
        ctx.fill();
      });
      if (mechanicState.resonanceTurn) {
        ctx.strokeStyle = theme.glow;
        ctx.lineWidth = 5;
        ctx.beginPath();
        ctx.moveTo(520, 82);
        ctx.lineTo(566, 134 + pulse / 3);
        ctx.lineTo(544, 184);
        ctx.lineTo(598, 238);
        ctx.lineTo(574, 302);
        ctx.stroke();
      }
      break;
    }
    case "water": {
      const waterTop = 486 - mechanicState.waterLevel * 32;
      ctx.fillStyle = theme.soft;
      ctx.beginPath();
      ctx.roundRect(98, waterTop, width - 196, height - waterTop - 84, 24);
      ctx.fill();
      for (let i = 0; i < 3; i += 1) {
        const gateX = 214 + i * 174;
        ctx.fillStyle = i < mechanicState.sluicesAligned ? theme.accent : "rgba(93, 111, 101, 0.24)";
        ctx.fillRect(gateX, waterTop - 46, 12, 56);
        ctx.fillRect(gateX + 34, waterTop - 46, 12, 56);
        ctx.fillStyle = i === mechanicState.waterLevel ? theme.glow : "rgba(255, 253, 245, 0.16)";
        ctx.fillRect(gateX - 12, waterTop - 8, 70, 8);
      }
      break;
    }
    case "insect": {
      for (let i = 0; i < 3; i += 1) {
        ctx.strokeStyle = i === mechanicState.cadence ? theme.accent : "rgba(255, 253, 245, 0.22)";
        ctx.lineWidth = i === mechanicState.cadence ? 5 : 2;
        ctx.beginPath();
        ctx.arc(674, 260, 72 + i * 24 + pulse / 4, 0.55, Math.PI * 2.1);
        ctx.stroke();
      }
      for (let i = 0; i < mechanicState.listened; i += 1) {
        const x = 594 + i * 62;
        const y = 474 - (i % 2) * 26;
        ctx.fillStyle = theme.glow;
        ctx.beginPath();
        ctx.arc(x, y + pulse / 4, 10, 0, Math.PI * 2);
        ctx.fill();
      }
      break;
    }
    case "overflow": {
      ctx.fillStyle = "rgba(224, 182, 109, 0.1)";
      ctx.fillRect(0, height - 164, width, 164);
      for (let i = 0; i < mechanicState.overflow * 5; i += 1) {
        const x = 120 + ((i * 94 + run.turn * 17) % (width - 240));
        const y = height - 92 - ((i * 29 + run.floor * 18) % 138) - pulse;
        ctx.fillStyle = i % 2 ? theme.accent : theme.glow;
        ctx.beginPath();
        ctx.arc(x, y, 5 + (i % 3), 0, Math.PI * 2);
        ctx.fill();
      }
      break;
    }
    case "mirror": {
      ctx.fillStyle = "rgba(255, 253, 245, 0.12)";
      ctx.beginPath();
      ctx.ellipse(674, 468, 176, 28, 0, 0, Math.PI * 2);
      ctx.fill();
      for (let i = 0; i < Math.max(1, mechanicState.verifiedPaths + 1); i += 1) {
        const offset = i * 26;
        ctx.strokeStyle = i < mechanicState.verifiedPaths ? theme.accent : "rgba(255, 253, 245, 0.18)";
        ctx.lineWidth = i < mechanicState.verifiedPaths ? 4 : 2;
        ctx.beginPath();
        ctx.moveTo(544 - offset, 454);
        ctx.quadraticCurveTo(674, 382 - offset / 2, 804 + offset, 454);
        ctx.stroke();
      }
      break;
    }
    case "frost": {
      const points = [
        { x: 154, y: 124 },
        { x: 294, y: 520 },
        { x: 722, y: 140 },
        { x: 836, y: 488 },
      ];
      points.forEach((point, index) => {
        if (index >= mechanicState.coldStacks) return;
        ctx.strokeStyle = index < mechanicState.coldStacks - 1 ? theme.glow : theme.accent;
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.moveTo(point.x - 18, point.y);
        ctx.lineTo(point.x + 18, point.y);
        ctx.moveTo(point.x, point.y - 18);
        ctx.lineTo(point.x, point.y + 18);
        ctx.moveTo(point.x - 12, point.y - 12);
        ctx.lineTo(point.x + 12, point.y + 12);
        ctx.moveTo(point.x - 12, point.y + 12);
        ctx.lineTo(point.x + 12, point.y - 12);
        ctx.stroke();
      });
      ctx.strokeStyle = "rgba(255, 255, 255, 0.24)";
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.arc(674, 260, 126 + pulse / 3, 0, Math.PI * 2);
      ctx.stroke();
      break;
    }
    case "wind": {
      const direction = mechanicState.windShift ? -1 : 1;
      for (let i = 0; i < 3; i += 1) {
        const startX = direction > 0 ? 96 : width - 96;
        const endX = direction > 0 ? width - 140 : 140;
        const baseY = 210 + i * 86;
        ctx.strokeStyle = i < mechanicState.routeMarks ? theme.accent : "rgba(255, 253, 245, 0.18)";
        ctx.lineWidth = i < mechanicState.routeMarks ? 4 : 2;
        ctx.beginPath();
        ctx.moveTo(startX, baseY);
        ctx.bezierCurveTo(startX + direction * 140, baseY - 36, endX - direction * 160, baseY + 26 + pulse / 4, endX, baseY - 14);
        ctx.stroke();
      }
      break;
    }
    case "lantern": {
      let previous = null;
      for (let i = 0; i < 7; i += 1) {
        const t = i / 6;
        const x = 164 + t * 520;
        const y = 120 + Math.sin(t * Math.PI) * 102;
        if (previous) {
          ctx.strokeStyle = i < mechanicState.lanternChain ? "rgba(240, 165, 78, 0.42)" : "rgba(255, 253, 245, 0.12)";
          ctx.lineWidth = 4;
          ctx.beginPath();
          ctx.moveTo(previous.x, previous.y);
          ctx.lineTo(x, y);
          ctx.stroke();
        }
        ctx.fillStyle = i < mechanicState.lanternChain ? theme.glow : "rgba(255, 253, 245, 0.14)";
        ctx.beginPath();
        ctx.arc(x, y + pulse / 5, i < mechanicState.lanternChain ? 11 : 7, 0, Math.PI * 2);
        ctx.fill();
        previous = { x, y };
      }
      break;
    }
    default: {
      for (let i = 0; i < 8; i += 1) {
        ctx.fillStyle = "rgba(255, 253, 245, 0.12)";
        ctx.beginPath();
        ctx.arc(122 + i * 94, 118 + (i % 2) * 18 + pulse / 3, 12, 0, Math.PI * 2);
        ctx.fill();
      }
      break;
    }
  }

  ctx.restore();
}

function dungeonMechanicStageSetSpec(run = state.dungeon, mechanic = currentDungeonMechanic(), dungeon = currentDungeonConfig(), hud = dungeonMechanicHudSpec(run, mechanic, dungeon)) {
  const mechanicState = syncDungeonMechanicState(run, mechanic, dungeon);
  if (!run || !mechanic || !mechanicState || !hud) return null;
  const theme = hud.theme || dungeonMechanicTheme(hud.tone);
  const nodeCount = Math.max(3, Math.min(7, hud.nodes.length || hud.progressMax || 3));
  const nodes = Array.from({ length: nodeCount }, (_, index) => {
    const hudNode = hud.nodes[index] || { label: `${index + 1}`, active: index < hud.progressCurrent };
    return {
      ...hudNode,
      x: 238 + index * (448 / Math.max(1, nodeCount - 1)),
      y: 476 - Math.sin((index / Math.max(1, nodeCount - 1)) * Math.PI) * 72,
    };
  });
  const nextNode = nodes.find((node) => !node.active) || nodes[nodes.length - 1];
  const toneLabels = {
    thunder: "雷木机关舞台",
    water: "回渠闸口舞台",
    insect: "虫鸣林道舞台",
    overflow: "满溢取舍舞台",
    mirror: "镜湖真路舞台",
    frost: "寒露霜窖舞台",
    wind: "落叶旧路舞台",
    lantern: "长灯影路舞台",
    mist: "秘境机关舞台",
  };
  return {
    tone: hud.tone,
    theme,
    title: toneLabels[hud.tone] || toneLabels.mist,
    mechanicName: hud.title,
    progressText: hud.progressText,
    actionHint: hud.actionReady ? `可主动：${hud.actionLabel}` : hud.actionUsed ? "本层已顺应节气" : hud.tags[0]?.label || mechanic.field_rule || "观察机关变化",
    fieldRule: mechanic.field_rule || "",
    puzzleCore: mechanic.puzzle_core || "",
    progressPercent: hud.progressPercent,
    nodes,
    nextNode,
  };
}

function drawDungeonMechanicStageToken(ctx, spec, node, index, motion = 0) {
  const { theme, tone } = spec;
  const active = Boolean(node.active);
  const emphasis = Boolean(node.emphasis) || node === spec.nextNode;
  const pulse = settings.reducedMotion ? 0 : Math.sin(motion * 2.2 + index) * 3;
  const radius = active ? 13 + pulse * 0.25 : emphasis ? 12 + pulse * 0.18 : 9;

  ctx.save();
  ctx.fillStyle = active ? theme.glow : emphasis ? theme.soft : "rgba(255, 253, 245, 0.22)";
  ctx.beginPath();
  ctx.arc(node.x, node.y, radius + 9, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = active ? theme.accent : "rgba(255, 253, 245, 0.72)";
  ctx.strokeStyle = active ? theme.accent : emphasis ? `${theme.accent}88` : "rgba(23, 35, 29, 0.22)";
  ctx.lineWidth = active || emphasis ? 3 : 1.5;
  ctx.beginPath();
  ctx.arc(node.x, node.y, radius, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();

  ctx.fillStyle = active ? "#fffdf5" : theme.accent;
  ctx.font = "800 10px Microsoft YaHei";
  const glyphs = {
    thunder: active ? "雷" : "柱",
    water: active ? "闸" : "水",
    insect: active ? "拍" : "鸣",
    overflow: active ? "溢" : "压",
    mirror: active ? "真" : "镜",
    frost: active ? "霜" : "寒",
    wind: active ? "路" : "叶",
    lantern: active ? "灯" : "影",
    mist: "境",
  };
  ctx.fillText(glyphs[tone] || glyphs.mist, node.x - 6, node.y + 4);

  if (active || emphasis) {
    ctx.fillStyle = "rgba(255, 253, 245, 0.82)";
    ctx.beginPath();
    ctx.roundRect(node.x - 22, node.y + 18, 44, 18, 9);
    ctx.fill();
    ctx.fillStyle = active ? "#286f58" : "#8f5f3f";
    ctx.font = "700 9px Microsoft YaHei";
    ctx.fillText(String(node.label || `${index + 1}`).slice(0, 4), node.x - 12, node.y + 31);
  }

  ctx.restore();
}

function drawDungeonMechanicStageSet(ctx, width, height, run = state.dungeon, mechanic = currentDungeonMechanic(), dungeon = currentDungeonConfig(), hud = dungeonMechanicHudSpec(run, mechanic, dungeon)) {
  const spec = dungeonMechanicStageSetSpec(run, mechanic, dungeon, hud);
  if (!spec) return false;
  const motion = settings.reducedMotion ? 0 : performance.now() / 1000;
  const pulse = settings.reducedMotion ? 0 : Math.sin(motion * 2) * 4;
  const { theme, nodes, tone } = spec;

  ctx.save();
  ctx.globalAlpha = 0.92;
  ctx.strokeStyle = "rgba(255, 253, 245, 0.22)";
  ctx.lineWidth = 18;
  ctx.lineCap = "round";
  ctx.beginPath();
  nodes.forEach((node, index) => {
    if (index === 0) ctx.moveTo(node.x, node.y);
    else {
      const previous = nodes[index - 1];
      ctx.quadraticCurveTo((previous.x + node.x) / 2, Math.min(previous.y, node.y) - 26 - pulse * 0.25, node.x, node.y);
    }
  });
  ctx.stroke();

  ctx.strokeStyle = `${theme.accent}77`;
  ctx.lineWidth = 5;
  ctx.setLineDash([16, 12]);
  ctx.lineDashOffset = settings.reducedMotion ? 0 : -motion * 18;
  ctx.beginPath();
  nodes.forEach((node, index) => {
    if (index === 0) ctx.moveTo(node.x, node.y);
    else {
      const previous = nodes[index - 1];
      ctx.quadraticCurveTo((previous.x + node.x) / 2, Math.min(previous.y, node.y) - 26 - pulse * 0.25, node.x, node.y);
    }
  });
  ctx.stroke();
  ctx.setLineDash([]);

  if (tone === "mirror" || tone === "water") {
    ctx.fillStyle = tone === "mirror" ? "rgba(159, 209, 223, 0.2)" : "rgba(77, 145, 166, 0.2)";
    ctx.beginPath();
    ctx.ellipse(462, 492, 248, 34 + pulse * 0.3, -0.02, 0, Math.PI * 2);
    ctx.fill();
  } else if (tone === "overflow") {
    ctx.fillStyle = "rgba(224, 182, 109, 0.18)";
    ctx.beginPath();
    ctx.ellipse(462, 506, 286, 42 + pulse * 0.5, 0, 0, Math.PI * 2);
    ctx.fill();
  } else if (tone === "frost") {
    ctx.strokeStyle = "rgba(255, 255, 255, 0.24)";
    ctx.lineWidth = 2;
    for (let i = 0; i < 6; i += 1) {
      const x = 214 + i * 92;
      ctx.beginPath();
      ctx.moveTo(x - 16, 510 + (i % 2) * 8);
      ctx.lineTo(x + 16, 510 + (i % 2) * 8);
      ctx.moveTo(x, 494 + (i % 2) * 8);
      ctx.lineTo(x, 526 + (i % 2) * 8);
      ctx.stroke();
    }
  } else if (tone === "wind") {
    ctx.fillStyle = "rgba(180, 125, 47, 0.24)";
    for (let i = 0; i < 12; i += 1) {
      ctx.beginPath();
      ctx.ellipse(184 + i * 44, 474 + Math.sin(motion + i) * 16, 12, 5, -0.42, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  nodes.forEach((node, index) => drawDungeonMechanicStageToken(ctx, spec, node, index, motion));

  const cardX = 170;
  const cardY = 528;
  drawCanvasCard(ctx, cardX, cardY, 466, 74, "rgba(255, 253, 245, 0.82)");
  ctx.fillStyle = theme.soft;
  ctx.beginPath();
  ctx.roundRect(cardX + 18, cardY + 18, 58, 38, 14);
  ctx.fill();
  ctx.fillStyle = theme.accent;
  ctx.font = "900 18px Microsoft YaHei";
  ctx.fillText(tone === "lantern" ? "灯" : tone === "thunder" ? "雷" : tone === "water" ? "闸" : tone === "insect" ? "鸣" : tone === "mirror" ? "镜" : tone === "frost" ? "霜" : tone === "wind" ? "叶" : tone === "overflow" ? "溢" : "境", cardX + 38, cardY + 44);
  ctx.fillStyle = "#17231d";
  ctx.font = "800 15px Microsoft YaHei";
  ctx.fillText(`${spec.title} · ${spec.mechanicName}`.slice(0, 22), cardX + 92, cardY + 28);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "12px Microsoft YaHei";
  ctx.fillText(spec.progressText.slice(0, 34), cardX + 92, cardY + 48);
  ctx.fillStyle = theme.accent;
  ctx.font = "800 11px Microsoft YaHei";
  ctx.fillText(spec.actionHint.slice(0, 32), cardX + 92, cardY + 64);

  const barX = cardX + 318;
  const barY = cardY + 22;
  ctx.fillStyle = "rgba(23, 35, 29, 0.1)";
  ctx.beginPath();
  ctx.roundRect(barX, barY, 124, 10, 999);
  ctx.fill();
  ctx.fillStyle = theme.accent;
  ctx.beginPath();
  ctx.roundRect(barX, barY, Math.max(12, 124 * (spec.progressPercent / 100)), 10, 999);
  ctx.fill();
  ctx.fillStyle = "#5d6f65";
  ctx.font = "700 10px Microsoft YaHei";
  ctx.fillText(`${spec.progressPercent}% 读懂`, barX + 36, barY + 27);

  ctx.restore();
  return true;
}

function drawDungeonFeedbackTrace(ctx, targetRule = "", cx = 432, cy = 352) {
  if (targetRule.includes("line") || targetRule.includes("charge") || targetRule.includes("projectile")) {
    ctx.beginPath();
    ctx.moveTo(cx - 160, cy + 84);
    ctx.lineTo(cx + 180, cy - 34);
    ctx.stroke();
    return;
  }
  if (targetRule.includes("arc") || targetRule.includes("cone")) {
    ctx.beginPath();
    ctx.moveTo(cx, cy + 16);
    ctx.arc(cx, cy + 16, 124, -0.88, 0.88);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    return;
  }
  if (targetRule.includes("random") || targetRule.includes("meteor") || targetRule.includes("rain") || targetRule.includes("tile")) {
    for (let i = 0; i < 5; i += 1) {
      const x = cx - 132 + i * 64;
      const y = cy - 92 + (i % 2) * 44;
      ctx.beginPath();
      ctx.arc(x, y, 20, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    }
    return;
  }
  if (targetRule.includes("ring") || targetRule.includes("pulse") || targetRule.includes("self")) {
    ctx.beginPath();
    ctx.arc(cx, cy, 112, 0, Math.PI * 2);
    ctx.stroke();
    ctx.globalAlpha *= 0.42;
    ctx.beginPath();
    ctx.arc(cx, cy, 72, 0, Math.PI * 2);
    ctx.fill();
    return;
  }
  ctx.beginPath();
  ctx.ellipse(cx, cy, 146, 58, -0.1, 0, Math.PI * 2);
  ctx.fill();
}

function drawDungeonFeedbackOverlay(ctx, width, height, feedback = activeDungeonFeedbackState()) {
  if (!feedback) return;
  const theme = dungeonMechanicTheme(feedback.tone);
  const elapsed = performance.now() - Number(feedback.start || 0);
  const duration = Math.max(1, Number(feedback.duration || 960));
  const progress = Math.max(0, Math.min(1, elapsed / duration));
  const fade = Math.max(0, 1 - progress);
  const bob = settings.reducedMotion ? 0 : Math.sin(elapsed / 150) * 4;
  const cardY = 204 + bob - progress * 8;

  ctx.save();
  ctx.globalAlpha = Math.max(0.22, 0.78 * fade);
  ctx.lineWidth = feedback.kind.includes("boss") ? 5 : 4;
  ctx.strokeStyle = feedback.kind.includes("boss") ? "rgba(190, 79, 55, 0.82)" : theme.accent;
  ctx.fillStyle = feedback.kind.includes("boss") ? "rgba(190, 79, 55, 0.14)" : theme.soft;

  if (feedback.kind === "attune") {
    ctx.beginPath();
    ctx.arc(674, 260, 84 + progress * 36, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(674, 260, 42 + progress * 18, 0, Math.PI * 2);
    ctx.fill();
  } else if (feedback.kind === "hazard") {
    ctx.beginPath();
    ctx.ellipse(214, 284, 96 + progress * 28, 34 + progress * 12, -0.18, 0, Math.PI * 2);
    ctx.stroke();
  } else if (feedback.kind === "explore") {
    ctx.beginPath();
    ctx.moveTo(248, 420);
    ctx.bezierCurveTo(324, 356 - progress * 10, 436, 332, 542, 288);
    ctx.bezierCurveTo(608, 260, 646, 232, 702, 206);
    ctx.stroke();
  } else {
    drawDungeonFeedbackTrace(ctx, feedback.targetRule, 432, 352);
  }

  ctx.globalAlpha = Math.max(0.34, fade);
  drawCanvasCard(ctx, 232, cardY, 456, 72, theme.card);
  ctx.fillStyle = feedback.kind.includes("boss") ? "#be4f37" : "#17231d";
  ctx.font = "700 17px Microsoft YaHei";
  ctx.fillText((feedback.label || "秘境异动").slice(0, 20), 256, cardY + 28);
  ctx.fillStyle = "#5d6f65";
  ctx.font = "13px Microsoft YaHei";
  ctx.fillText((feedback.detail || "灵气正在改写这一层的节奏。").slice(0, 40), 256, cardY + 50);
  if (feedback.solutionKey && feedback.solutionAbility) {
    ctx.fillStyle = theme.soft;
    ctx.beginPath();
    ctx.roundRect(576, cardY + 14, 88, 44, 14);
    ctx.fill();
    ctx.strokeStyle = theme.accent;
    ctx.lineWidth = 1.5;
    ctx.stroke();
    ctx.fillStyle = theme.accent;
    ctx.font = "700 11px Microsoft YaHei";
    ctx.fillText("精怪解法", 588, cardY + 31);
    ctx.fillStyle = "#17231d";
    ctx.font = "700 11px Microsoft YaHei";
    ctx.fillText((feedback.solutionAbility || feedback.solutionKey).slice(0, 6), 588, cardY + 49);
  }
  if (feedback.phase > 0 || feedback.castTime > 0) {
    ctx.fillStyle = feedback.kind.includes("boss") ? "#8f5f3f" : theme.accent;
    ctx.font = "700 12px Microsoft YaHei";
    ctx.fillText(`P${Math.max(1, feedback.phase || 1)} · 前摇 ${feedback.castTime > 0 ? feedback.castTime.toFixed(feedback.castTime >= 10 ? 0 : 1) : "?"} 秒`, 256, cardY + 66);
  }
  ctx.restore();
}

function drawDungeonWorld(ctx, width, height) {
  const dungeon = currentDungeonConfig() || availableDungeons()[0] || data.dungeons[0];
  const mechanic = currentDungeonMechanic(dungeon);
  const previewRun = {
    areaId: dungeon?.area_id,
    floor: Number(dungeon?.floor_start || 1),
    maxFloor: Number(dungeon?.floor_end || 3),
    hp: 100,
    bossHp: dungeonBossMaxHp(dungeon),
    bossMaxHp: dungeonBossMaxHp(dungeon),
    bossPhase: 1,
    bossReady: false,
    turn: state.day,
    loot: [],
    lastLoot: [],
    lastEnemyId: null,
    skillLog: ["秘境预览：进入后将显示敌人、掉落和 Boss 前摇。"],
    hazards: [],
  };
  const run = state.dungeon || previewRun;
  const mechanicHud = dungeonMechanicHudSpec(run, mechanic, dungeon);
  const spiritSolution = dungeonSpiritSolutionSpec(run, mechanic, dungeon);
  const structureRoute = dungeonStructureRouteSpec(run, mechanic, dungeon, mechanicHud, spiritSolution);
  const palette = dungeonPalette(dungeon, mechanic);
  const hazards = run.hazards?.length ? run.hazards : dungeonHazards(mechanic, run, dungeon);
  const caveGradient = ctx.createLinearGradient(0, 0, width, height);
  caveGradient.addColorStop(0, palette.top);
  caveGradient.addColorStop(0.58, palette.mid);
  caveGradient.addColorStop(1, palette.bottom);
  ctx.fillStyle = caveGradient;
  ctx.fillRect(0, 0, width, height);

  ctx.save();
  ctx.fillStyle = "rgba(255, 253, 245, 0.05)";
  for (let ridge = 0; ridge < 3; ridge += 1) {
    ctx.beginPath();
    ctx.moveTo(0, 210 + ridge * 86);
    for (let x = 0; x <= width + 80; x += 80) {
      const y = 190 + ridge * 86 + Math.sin((x + ridge * 70) / 90) * 24;
      ctx.lineTo(x, y);
    }
    ctx.lineTo(width, height);
    ctx.lineTo(0, height);
    ctx.fill();
  }
  ctx.restore();

  ctx.fillStyle = palette.glow;
  for (let i = 0; i < 24; i += 1) {
    const x = 70 + ((i * 97 + run.floor * 31 + run.turn * 13) % (width - 140));
    const y = 86 + ((i * 53 + state.day * 17) % (height - 172));
    ctx.beginPath();
    ctx.arc(x, y, 10 + (i % 4) * 7, 0, Math.PI * 2);
    ctx.fill();
  }

  drawDungeonMechanicAtmosphere(ctx, width, height, run, mechanic, dungeon, mechanicHud);

  hazards.forEach((hazard, index) => {
    ctx.fillStyle = index === 0 ? palette.hazard : "rgba(255, 253, 245, 0.12)";
    const x = 172 + index * 186;
    const y = 220 + ((run.turn + index) % 2) * 78;
    ctx.beginPath();
    ctx.ellipse(x, y, 74 + hazard.severity * 8, 30 + hazard.severity * 3, -0.18 + index * 0.14, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#fffdf5";
    ctx.font = "700 14px Microsoft YaHei";
    ctx.fillText(hazard.label, x - 42, y + 5);
  });

  drawCanvasCard(ctx, 58, 48, 440, 138, "rgba(255, 253, 245, 0.88)");
  ctx.fillStyle = "#17231d";
  ctx.font = "700 26px Microsoft YaHei";
  ctx.fillText(dungeonName(dungeon), 84, 88);
  ctx.font = "16px Microsoft YaHei";
  ctx.fillStyle = "#5d6f65";
  ctx.fillText(`第 ${run.floor}/${run.maxFloor} 层 · 随行战力 ${companionPower()} · ${mechanic?.solar_term || state.term}`, 84, 118);
  ctx.fillText((run.roomEvent || mechanic?.puzzle_core || "辨路、战斗、带回材料。").slice(0, 32), 84, 146);
  drawDungeonBar(ctx, 84, 158, 360, 14, run.hp, 100, "#4d91a6", `HP ${run.hp}/100`);
  drawDungeonStructureRouteRibbon(ctx, structureRoute);

  const doorwayGlow = ctx.createRadialGradient(674, 260, 12, 674, 260, 120);
  doorwayGlow.addColorStop(0, "rgba(255, 253, 245, 0.72)");
  doorwayGlow.addColorStop(1, "rgba(255, 253, 245, 0)");
  ctx.fillStyle = doorwayGlow;
  ctx.beginPath();
  ctx.arc(674, 260, 132, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = palette.accent;
  ctx.fillRect(610, 190, 130, 180);
  ctx.fillStyle = "#5b3328";
  ctx.fillRect(632, 220, 86, 132);
  ctx.fillStyle = "#fff4c4";
  ctx.beginPath();
  ctx.arc(674, 212, 26, 0, Math.PI * 2);
  ctx.fill();
  drawDungeonMechanicStageSet(ctx, width, height, run, mechanic, dungeon, mechanicHud);
  drawActiveDungeonMechanicOverlay(ctx, width, height, run, mechanic, dungeon, mechanicHud);
  drawDungeonSpiritSolutionTrace(ctx, run, mechanic, dungeon, spiritSolution);
  drawDungeonFeedbackOverlay(ctx, width, height);

  const lastEnemy = data.enemiesById.get(run.lastEnemyId) || dungeonEnemies(dungeon)[0];
  if (run.bossReady) {
    const activeBossId = dungeonBossId(dungeon, run);
    const currentSkill = bossSkillForTurn(activeBossId, run.turn, bossHpPercent(run, dungeon));
    const counterSpec = dungeonBossTelegraphSpec(currentSkill, activeBossId, run);
    drawDungeonTelegraph(ctx, currentSkill, 432, 352, palette);
    drawDungeonBossCounterCard(ctx, counterSpec);
    ctx.fillStyle = "rgba(23, 35, 29, 0.24)";
    ctx.beginPath();
    ctx.ellipse(444, 424, 162, 34, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = palette.boss;
    ctx.beginPath();
    ctx.roundRect(318, 238, 248, 178, 44);
    ctx.fill();
    ctx.fillStyle = "rgba(255, 253, 245, 0.92)";
    ctx.beginPath();
    ctx.arc(386, 304, 8, 0, Math.PI * 2);
    ctx.arc(486, 304, 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#fffdf5";
    ctx.font = "700 24px Microsoft YaHei";
    ctx.fillText(bossName(activeBossId), 354, 352);
    drawDungeonBar(ctx, 306, 434, 280, 18, run.bossHp, run.bossMaxHp, palette.boss, `Boss ${Math.ceil(bossHpPercent(run, dungeon) * 100)}% · P${run.bossPhase || 1}`);
  } else if (lastEnemy) {
    drawDungeonEnemyShape(ctx, lastEnemy, 410, 356, 1.4, palette);
  }

  if (state.spirits.length > 0) {
    drawSpiritAura(ctx, 86, 382, "随行协战");
    drawSpiritSprite(ctx, state.spirits[0], 104, 378, 118);
  }

  drawDungeonLootNodes(ctx, run, width, height, palette);
  drawDungeonSkillBadges(ctx, run, 560, 416);
  drawDungeonFirstMechanicTheater(ctx, dungeonFirstMechanicTheaterSpec(run, mechanic, dungeon, mechanicHud, spiritSolution));
  drawDungeonMechanicWorldCard(ctx, mechanicHud, 598, 48, 280, 188);
  drawDungeonSpiritSolutionWorldCard(ctx, spiritSolution, 598, 244, 280, 126);
  drawActiveCutsceneOverlay(ctx, width, height);
  drawActiveDialogueStage(ctx, width, height);
}

function startAnimationLoop() {
  if (state.animationStarted) return;
  state.animationStarted = true;
  const tick = () => {
    recordStabilityFrame();
    if (dungeonAnimationActive()) drawWorld();
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}

function bindKeyboardInput() {
  window.addEventListener("keydown", (event) => {
    if (event.repeat) return;
    if (event.target instanceof HTMLInputElement) return;

    const move = KEY_MOVES[event.code];
    if (move) {
      event.preventDefault();
      moveSelection(move[0], move[1]);
      return;
    }

    const action = KEY_ACTIONS.get(event.code);
    if (action) {
      event.preventDefault();
      performAction(action);
    }
  });
}

function pollGamepadInput() {
  const [pad] = navigator.getGamepads ? navigator.getGamepads() : [];
  if (pad) {
    const now = performance.now();
    const dx = Math.abs(pad.axes[0] || 0) > INPUT_DEADZONE ? Math.sign(pad.axes[0]) : 0;
    const dy = Math.abs(pad.axes[1] || 0) > INPUT_DEADZONE ? Math.sign(pad.axes[1]) : 0;
    const dpadX = (pad.buttons[15]?.pressed ? 1 : 0) - (pad.buttons[14]?.pressed ? 1 : 0);
    const dpadY = (pad.buttons[13]?.pressed ? 1 : 0) - (pad.buttons[12]?.pressed ? 1 : 0);
    const moveX = dpadX || dx;
    const moveY = dpadY || dy;

    if ((moveX || moveY) && now - state.lastGamepadMoveAt > GAMEPAD_MOVE_REPEAT_MS) {
      moveSelection(moveX, moveY);
      state.lastGamepadMoveAt = now;
    }

    for (const [buttonIndex, action] of GAMEPAD_ACTIONS) {
      const pressed = Boolean(pad.buttons[buttonIndex]?.pressed);
      if (pressed && !state.gamepadButtonsDown.has(buttonIndex)) performAction(action);
      if (pressed) state.gamepadButtonsDown.add(buttonIndex);
      else state.gamepadButtonsDown.delete(buttonIndex);
    }
  }

  requestAnimationFrame(pollGamepadInput);
}

function startInputLoop() {
  if (state.inputStarted) return;
  state.inputStarted = true;
  bindKeyboardInput();
  window.addEventListener("gamepadconnected", (event) => {
    addLog("手柄已连接", event.gamepad.id || "Gamepad");
    render();
  });
  requestAnimationFrame(pollGamepadInput);
}

