  refs.buySeedButton.addEventListener("click", () => buySelectedSeeds(3));
  refs.inventoryList.addEventListener("click", (event) => {
    const shopRestockButton = event.target.closest("[data-inventory-shop-restock]");
    const weatherRestockButton = event.target.closest("[data-inventory-weather-restock]");
    const routeOrderButton = event.target.closest("[data-inventory-route-order]");
    const routeRecipeButton = event.target.closest("[data-inventory-route-recipe]");
    const routeSeedButton = event.target.closest("[data-inventory-route-seed]");
    const routeShopButton = event.target.closest("[data-inventory-route-shop]");
    if (shopRestockButton) return focusDaySummaryShopRestock("shop", { itemId: shopRestockButton.dataset.inventoryShopRestock });
    if (weatherRestockButton) return applyShopWeatherShelfRestock({ itemId: weatherRestockButton.dataset.inventoryWeatherRestock });
    if (routeOrderButton) return focusPlotRouteOrder(routeOrderButton.dataset.inventoryRouteOrder);
    if (routeRecipeButton) return focusPlotRouteRecipe(routeRecipeButton.dataset.inventoryRouteRecipe);
    if (routeSeedButton) return focusPlotRouteSeed(routeSeedButton.dataset.inventoryRouteSeed);
    if (routeShopButton) return focusPlotRouteShop(routeShopButton.dataset.inventoryRouteShop, routeShopButton.dataset.inventoryRouteItem);
  });
  refs.selectedPlotCard.addEventListener("click", (event) => {
    const routeOrderButton = event.target.closest("[data-plot-route-order]");
    const routeRecipeButton = event.target.closest("[data-plot-route-recipe]");
    const routeSeedButton = event.target.closest("[data-plot-route-seed]");
    const routeShopButton = event.target.closest("[data-plot-route-shop]");
    if (routeOrderButton) return focusPlotRouteOrder(routeOrderButton.dataset.plotRouteOrder);
    if (routeRecipeButton) return focusPlotRouteRecipe(routeRecipeButton.dataset.plotRouteRecipe);
    if (routeSeedButton) return focusPlotRouteSeed(routeSeedButton.dataset.plotRouteSeed);
    if (routeShopButton) return focusPlotRouteShop(routeShopButton.dataset.plotRouteShop, routeShopButton.dataset.plotRouteItem);
    const button = event.target.closest("[data-selected-plot-action]");
    if (!button || button.disabled) return;
    performAction(button.dataset.selectedPlotAction);
  });
  refs.captureStartButton.addEventListener("click", () => applyCaptureScene("start"));
  refs.captureSpiritButton.addEventListener("click", () => applyCaptureScene("spirit"));
